// ── Data modal ──
function openDataModal() {
  document.getElementById('data-modal').classList.add('open');
  document.getElementById('data-modal-status').textContent = '';
  updateSrsSettingDisplay();
}
function closeDataModal() { document.getElementById('data-modal').classList.remove('open'); }

function exportData() {
  const data = { srs: srsData, activity: getActivity(), favs: getFavs(), exported: new Date().toISOString() };
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `lebanese-arabic-progress-${new Date().toISOString().slice(0,10)}.json`;
  a.click();
  URL.revokeObjectURL(a.href);
  document.getElementById('data-modal-status').textContent = 'Exported successfully.';
}

function importData(e) {
  const file = e.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = ev => {
    try {
      const data = JSON.parse(ev.target.result);
      if (data.srs) { srsData = data.srs; saveSRS(); }
      if (data.activity) _lsSet('la_activity', JSON.stringify(data.activity));
      if (data.favs) saveFavs(data.favs);
      updateNavStats();
      document.getElementById('data-modal-status').textContent = 'Imported successfully. Reload to see all changes.';
    } catch { document.getElementById('data-modal-status').textContent = 'Error: invalid file.'; }
  };
  reader.readAsText(file);
}

function resetProgress() {
  if (!confirm('Reset ALL progress? This cannot be undone.')) return;
  localStorage.removeItem('la_srs');
  localStorage.removeItem('la_activity');
  srsData = {};
  updateNavStats();
  startStudy();
  closeDataModal();
}

function exportVocabCSV() {
  const header = 'id,arabic,transliteration,english,category,notes';
  const rows = VOCAB.map(v => [
    v.id,
    `"${v.ar.replace(/"/g,'""')}"`,
    `"${v.tr.replace(/"/g,'""')}"`,
    `"${v.en.replace(/"/g,'""')}"`,
    v.cat,
    `"${(v.notes||'').replace(/"/g,'""')}"`
  ].join(','));
  const csv = [header, ...rows].join('\n');
  const blob = new Blob([csv], { type: 'text/csv' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = `lebanese-arabic-vocab-${new Date().toISOString().slice(0,10)}.csv`;
  a.click();
  URL.revokeObjectURL(a.href);
  document.getElementById('data-modal-status').textContent = `Exported ${VOCAB.length} words as CSV.`;
}

