// ── Quick Lookup ──
function openLookup() {
  document.getElementById('lookup-overlay').classList.add('open');
  document.getElementById('lookup-results').innerHTML = '';
  const inp = document.getElementById('lookup-input');
  inp.value = '';
  setTimeout(() => inp.focus(), 50);
}
function closeLookup() { document.getElementById('lookup-overlay').classList.remove('open'); }
let lookupTab = 'all';
function setLookupTab(tab) {
  lookupTab = tab;
  ['all','vocab','phrases','convo'].forEach(t => {
    const b = document.getElementById('ltab-' + t);
    if (b) b.classList.toggle('active', t === tab);
  });
  renderLookupResults();
}

function renderLookupResults() {
  const q = document.getElementById('lookup-input').value.trim().toLowerCase();
  const res = document.getElementById('lookup-results');
  const emptyEl = document.getElementById('lookup-empty');
  if (!q) { res.innerHTML = ''; if (emptyEl) emptyEl.style.display = 'none'; return; }

  let html = '';
  let total = 0;

  // ── Vocabulary ──
  if (lookupTab === 'all' || lookupTab === 'vocab') {
    const vocabHits = VOCAB.filter(v =>
      v.ar.includes(q) || v.tr.toLowerCase().includes(q) || v.en.toLowerCase().includes(q) ||
      (v.notes && v.notes.toLowerCase().includes(q))
    ).slice(0, lookupTab === 'vocab' ? 20 : 8);
    if (vocabHits.length > 0) {
      html += `<div style="font-size:0.65rem;text-transform:uppercase;letter-spacing:2px;color:var(--muted);padding:6px 0 4px">📚 Vocabulary (${vocabHits.length})</div>`;
      html += vocabHits.map(v => `
        <div onclick="closeLookup();openWordModal('${v.id}')" class="lookup-row">
          <div style="font-size:1.3rem;direction:rtl;min-width:48px;text-align:right;font-family:'Segoe UI','Noto Naskh Arabic',serif">${v.ar}</div>
          <div style="flex:1">
            <div style="font-size:0.9rem;font-weight:600">${v.en}</div>
            <div style="font-size:0.78rem;color:var(--accent2);font-style:italic">${v.tr}</div>
          </div>
          <div style="font-size:0.6rem;color:var(--muted);text-transform:uppercase;letter-spacing:1px;flex-shrink:0">${v.cat}</div>
        </div>`).join('');
      total += vocabHits.length;
    }
  }

  // ── Phrasebook ──
  if (lookupTab === 'all' || lookupTab === 'phrases') {
    const phraseHits = [];
    try {
      for (const cat of PHRASEBOOK) {
        for (const p of cat.phrases) {
          if (p.ar.includes(q) || p.tr.toLowerCase().includes(q) || p.en.toLowerCase().includes(q)) {
            phraseHits.push({ ...p, cat: cat.cat });
            if (phraseHits.length >= (lookupTab === 'phrases' ? 20 : 6)) break;
          }
        }
        if (phraseHits.length >= (lookupTab === 'phrases' ? 20 : 6)) break;
      }
    } catch(e) {}
    if (phraseHits.length > 0) {
      html += `<div style="font-size:0.65rem;text-transform:uppercase;letter-spacing:2px;color:var(--muted);padding:8px 0 4px">💬 Phrases (${phraseHits.length})</div>`;
      html += phraseHits.map(p => `
        <div onclick="speak(${attrArg(p.ar)})" class="lookup-row">
          <div style="font-size:1.15rem;direction:rtl;min-width:48px;font-family:'Segoe UI','Noto Naskh Arabic',serif">${p.ar}</div>
          <div style="flex:1">
            <div style="font-size:0.88rem;font-weight:600">${p.en}</div>
            <div style="font-size:0.75rem;color:var(--accent2);font-style:italic">${p.tr}</div>
          </div>
          <div style="font-size:0.6rem;color:var(--muted);flex-shrink:0">${p.cat}</div>
        </div>`).join('');
      total += phraseHits.length;
    }
  }

  // ── Conversations ──
  if (lookupTab === 'all' || lookupTab === 'convo') {
    const convoHits = [];
    try {
      for (const convo of CONVERSATIONS) {
        for (const line of convo.lines) {
          if (line.ar.includes(q) || line.tr.toLowerCase().includes(q) || line.en.toLowerCase().includes(q)) {
            convoHits.push({ ...line, convoTitle: convo.title, convoId: convo.id });
            if (convoHits.length >= (lookupTab === 'convo' ? 20 : 5)) break;
          }
        }
        if (convoHits.length >= (lookupTab === 'convo' ? 20 : 5)) break;
      }
    } catch(e) {}
    if (convoHits.length > 0) {
      html += `<div style="font-size:0.65rem;text-transform:uppercase;letter-spacing:2px;color:var(--muted);padding:8px 0 4px">🗣️ Conversations (${convoHits.length})</div>`;
      html += convoHits.map(c => `
        <div onclick="closeLookup();showView('convo')" class="lookup-row">
          <div style="flex:1">
            <div style="font-size:0.85rem;font-weight:600;direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif;text-align:right">${c.ar}</div>
            <div style="font-size:0.78rem;color:var(--muted);">${c.en}</div>
          </div>
          <div style="font-size:0.6rem;color:var(--muted);flex-shrink:0;text-align:right">${c.convoTitle}</div>
        </div>`).join('');
      total += convoHits.length;
    }
  }

  res.innerHTML = html;
  if (emptyEl) emptyEl.style.display = total === 0 ? '' : 'none';
}
function setModalStatus(msg, type) {
  const el = document.getElementById('modal-status');
  el.textContent = msg;
  el.className = 'modal-status' + (type ? ' ' + type : '');
}

