let buildIndex = 0;
let buildTokens = [];

function startBuild() {
  buildIndex = Math.floor(Math.random() * BUILD_SENTENCES.length);
  buildTokens = [];
  renderBuild();
}

function renderBuild() {
  const s = BUILD_SENTENCES[buildIndex];
  document.getElementById('build-target').innerHTML =
    `<strong>Translate:</strong> "${s.en}" <span style="color:var(--muted);font-size:0.78rem">— ${s.hint}</span>`;
  renderBuiltSentence();
  renderBuildTray(s);
  document.getElementById('build-feedback').style.display = 'none';
}

function renderBuiltSentence() {
  const el = document.getElementById('build-sentence');
  if (buildTokens.length === 0) {
    el.innerHTML = '<span style="color:var(--muted);font-size:0.8rem;direction:ltr">Click words below to build the sentence →</span>';
  } else {
    el.innerHTML = buildTokens.map(t => `<span class="built-token">${t}</span>`).join('');
  }
  const trEl = document.getElementById('build-transliteration');
  if (trEl) trEl.textContent = '';
}

function renderBuildTray(s) {
  const words = shuffle([...s.ar]);
  document.getElementById('build-tray').innerHTML = words.map(w => {
    const v = VOCAB.find(v2 => v2.ar === w || v2.ar.startsWith(w));
    const tr = v ? v.tr : '';
    return `<div class="build-word" onclick="buildAddWord('${w.replace(/'/g,"\\'")}')">
      <span class="bw-ar">${w}</span>
      ${tr ? `<span class="bw-tr">${tr.split('/')[0].trim()}</span>` : ''}
    </div>`;
  }).join('');
}

function buildAddWord(w) {
  buildTokens.push(w);
  renderBuiltSentence();
}

function buildRemoveLast() {
  if (buildTokens.length > 0) {
    buildTokens.pop();
    renderBuiltSentence();
  }
}

function buildClear() {
  buildTokens = [];
  renderBuiltSentence();
  document.getElementById('build-feedback').style.display = 'none';
}

function checkBuildSentence() {
  const s = BUILD_SENTENCES[buildIndex];
  const fb = document.getElementById('build-feedback');
  const trEl = document.getElementById('build-transliteration');
  if (buildTokens.length === 0) { fb.style.display = 'block'; fb.style.background = 'var(--card2)'; fb.style.color = 'var(--muted)'; fb.textContent = 'Add some words first!'; return; }
  const correct = JSON.stringify(buildTokens) === JSON.stringify(s.ar);
  // Also accept any order that contains all words
  const allPresent = s.ar.every(w => buildTokens.includes(w)) && buildTokens.length === s.ar.length;
  fb.style.display = 'block';
  if (correct) {
    fb.style.background = 'rgba(42,157,143,.15)'; fb.style.color = 'var(--easy)';
    fb.innerHTML = `✓ Perfect! <em>${s.tr}</em>`;
    if (trEl) trEl.textContent = s.tr;
    recordActivity(); incDailyCount();
    if (typeof addXp === 'function') addXp((typeof XP_PER_RATING !== 'undefined' ? XP_PER_RATING[2] : 0) || 10);
  } else if (allPresent) {
    fb.style.background = 'rgba(69,123,157,.15)'; fb.style.color = 'var(--blue)';
    fb.innerHTML = `Almost! Word order: <em>${s.ar.join(' ')}</em> — <em>${s.tr}</em>`;
    if (trEl) trEl.textContent = s.tr;
  } else {
    fb.style.background = 'rgba(230,57,70,.1)'; fb.style.color = 'var(--again)';
    fb.innerHTML = `Answer: <span style="direction:rtl">${s.ar.join(' ')}</span> — <em>${s.tr}</em>`;
  }
}

function nextBuildSentence() {
  buildIndex = (buildIndex + 1) % BUILD_SENTENCES.length;
  buildTokens = [];
  renderBuild();
}

let grammarRendered = false;
// ─── ARABIC ROOT BROWSER ─────────────────────────────────────────────────────
const ARABIC_ROOTS = [
  { root:'ك-ت-ب', latin:'k-t-b', meaning:'writing / books', words:['كتاب','كتابة','مكتوب','مكتبة','كاتب','يكتب'] },
  { root:'د-ر-س', latin:'d-r-s', meaning:'study / lessons', words:['درس','دراسة','مدرسة','مدرّس','يدرس','دروس'] },
  { root:'ع-م-ل', latin:'3-m-l', meaning:'work / action', words:['عمل','عامل','معمل','يعمل','عملية','عمّال'] },
  { root:'ق-و-ل', latin:'2-w-l', meaning:'saying / speech', words:['قال','قول','مقولة','يقول','قالولي','قولو'] },
  { root:'ر-ج-ع', latin:'r-j-3', meaning:'returning / going back', words:['رجع','رجوع','يرجع','مرجع','راجع'] },
  { root:'ح-ك-ي', latin:'7-k-y', meaning:'talking / speaking', words:['حكى','حكاية','يحكي','محكي','حكي'] },
  { root:'ش-ر-ب', latin:'sh-r-b', meaning:'drinking', words:['شرب','شراب','يشرب','مشروب','شارب'] },
  { root:'أ-ك-ل', latin:'a-k-l', meaning:'eating / food', words:['أكل','أكلة','ياكل','مأكولات','أكلي'] },
  { root:'ف-ه-م', latin:'f-h-m', meaning:'understanding', words:['فهم','يفهم','مفهوم','فهام','فاهم'] },
  { root:'ع-ر-ف', latin:'3-r-f', meaning:'knowing / knowledge', words:['عرف','معرفة','يعرف','عارف','معروف'] },
  { root:'ح-ب-ب', latin:'7-b-b', meaning:'love / liking', words:['حب','حبيب','يحب','محبوب','حبيبتي','أحبك'] },
  { root:'ج-ي-ء', latin:'j-y', meaning:'coming / arriving', words:['جاء','جاي','يجي','مجيء','تعا'] },
  { root:'ر-و-ح', latin:'r-w-7', meaning:'going / soul', words:['راح','روح','يروح','رايح','مروّح'] },
  { root:'ب-ي-ت', latin:'b-y-t', meaning:'house / home', words:['بيت','بيوت','بيّات','مبيّت'] },
  { root:'ك-ب-ر', latin:'k-b-r', meaning:'big / growing', words:['كبير','كبار','يكبر','أكبر','كبّر'] },
  { root:'ص-غ-ر', latin:'s-gh-r', meaning:'small / young', words:['صغير','صغار','يصغر','أصغر','صغيرة'] },
  { root:'ح-س-ن', latin:'7-s-n', meaning:'good / beautiful', words:['حسن','حسنة','محسّن','أحسن','حسناء'] },
  { root:'ق-د-ر', latin:'2-d-r', meaning:'ability / power', words:['قدر','قدرة','يقدر','مقدور','قادر'] },
  { root:'و-ق-ت', latin:'w-2-t', meaning:'time', words:['وقت','أوقات','موقّت','بالوقت'] },
  { root:'ف-ت-ح', latin:'f-t-7', meaning:'opening', words:['فتح','فتحة','يفتح','مفتوح','مفتاح'] },
  { root:'س-ك-ن', latin:'s-k-n', meaning:'living / residing', words:['سكن','ساكن','مسكن','يسكن','سكنة'] },
  { root:'ح-م-ل', latin:'7-m-l', meaning:'carrying / pregnancy', words:['حمل','حامل','يحمل','محمول','حمولة'] },
  { root:'ع-ل-م', latin:'3-l-m', meaning:'knowledge / world', words:['علم','عالم','يعلم','معلوم','تعليم','علّم'] },
  { root:'ن-ظ-ر', latin:'n-dh-r', meaning:'looking / seeing', words:['نظر','ناظر','ينظر','منظر','نظرة'] },
  { root:'خ-ر-ج', latin:'kh-r-j', meaning:'going out / exit', words:['خرج','خروج','يخرج','خارج','مخرج'] },
  { root:'د-خ-ل', latin:'d-kh-l', meaning:'entering', words:['دخل','دخول','يدخل','داخل','مدخل'] },
  { root:'س-أ-ل', latin:'s-2-l', meaning:'asking / questions', words:['سأل','سؤال','يسأل','مسألة','أسئلة'] },
  { root:'ج-و-ب', latin:'j-w-b', meaning:'answering', words:['جواب','يجاوب','أجاب','مجاوبة'] },
  { root:'ن-ز-ل', latin:'n-z-l', meaning:'going down / hotel', words:['نزل','نزلة','ينزل','نازل','فندق'] },
  { root:'ط-ل-ع', latin:'t-l-3', meaning:'going up / rising', words:['طلع','طلوع','يطلع','طالع'] },
];

let _rootFilter = '';
function filterRoots(q) {
  _rootFilter = q.toLowerCase().trim();
  renderRootBrowser();
}

function renderRootBrowser() {
  const el = document.getElementById('root-browser-panel');
  if (!el) return;
  const q = _rootFilter;
  const roots = q ? ARABIC_ROOTS.filter(r =>
    r.root.includes(q) || r.latin.includes(q) || r.meaning.toLowerCase().includes(q)
  ) : ARABIC_ROOTS;

  if (roots.length === 0) {
    el.innerHTML = `<div style="text-align:center;padding:16px;color:var(--muted)">No matching roots found</div>`;
    return;
  }

  el.innerHTML = roots.map(r => {
    // Find matching VOCAB words for each root word
    const matches = r.words.map(w => {
      const v = VOCAB.find(v => v.ar === w || v.ar.includes(w) || w.includes(v.ar.replace(/[ًٌٍَُِّ]/g,'')));
      return { ar: w, vocab: v };
    });
    const known = matches.filter(m => m.vocab && getCard(m.vocab.id).reps > 0).length;
    const total = matches.filter(m => m.vocab).length;
    return `
    <div style="background:var(--card);border-radius:12px;padding:14px;margin-bottom:10px;border:1px solid var(--border)">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px">
        <div>
          <span style="font-size:1.5rem;direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif;font-weight:700">${r.root}</span>
          <span style="margin-left:10px;font-size:0.8rem;color:var(--accent2);font-style:italic">${r.latin}</span>
        </div>
        <div style="text-align:right">
          <div style="font-size:0.72rem;color:var(--muted);">${r.meaning}</div>
          ${total > 0 ? `<div style="font-size:0.68rem;color:var(--easy)">${known}/${total} learned</div>` : ''}
        </div>
      </div>
      <div style="display:flex;flex-wrap:wrap;gap:6px">
        ${matches.map(m => {
          const learned = m.vocab && getCard(m.vocab.id).reps > 0;
          const bg = m.vocab ? (learned ? 'var(--easy)22' : 'var(--card2)') : 'var(--card2)';
          const border = m.vocab ? (learned ? 'var(--easy)' : 'var(--border)') : 'var(--border)44';
          const click = m.vocab ? `onclick="openWordModal('${m.vocab.id}')"` : `onclick="speak('${m.ar}')"`;
          return `<div ${click} style="cursor:pointer;padding:5px 10px;border-radius:20px;border:1.5px solid ${border};background:${bg};font-size:0.88rem;direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif" title="${m.vocab ? m.vocab.en : 'tap to hear'}">${m.ar}${m.vocab ? '' : ' <span style="font-size:0.6rem;color:var(--muted)">?</span>'}</div>`;
        }).join('')}
      </div>
    </div>`;
  }).join('');
}

function renderGrammar() {
  if (grammarRendered) return;
  grammarRendered = true;
  renderRootBrowser();
  renderProverbs();
  renderConjTabs();
  const acc = document.getElementById('grammar-accordion');
  acc.innerHTML = GRAMMAR_SECTIONS.map(s => `
    <div class="grammar-section">
      <div class="grammar-header" id="gh-${s.id}" onclick="toggleGrammarSection('${s.id}')">
        <div class="grammar-title"><span>${s.icon}</span><span>${s.title}</span></div>
        <span class="grammar-chevron">▼</span>
      </div>
      <div class="grammar-body" id="gb-${s.id}">
        ${s.render()}
        ${GRAMMAR_EXERCISES[s.id] ? `<div class="gex-area" id="gex-${s.id}"><button class="btn btn-outline" style="font-size:0.8rem;padding:6px 14px" onclick="startGrammarExercise('${s.id}')">🎯 Practice this grammar</button></div>` : ''}
      </div>
    </div>
  `).join('');

  const rg = document.getElementById('resources-grid');
  rg.innerHTML = RESOURCES.map(r => {
    const tags = r.tags.map(t => `<span class="rtag rtag-${t}">${t}</span>`).join('');
    return `<div class="resource-card">
      <h4>${r.name}</h4>
      <div style="margin-bottom:8px">${tags}</div>
      <p>${r.desc}</p>
      <a href="${r.url}" target="_blank" rel="noopener" class="resource-link">→ ${r.urlLabel}</a>
    </div>`;
  }).join('');
}

function toggleGrammarSection(id) {
  document.getElementById('gh-' + id).classList.toggle('open');
  document.getElementById('gb-' + id).classList.toggle('open');
}

function filterGrammar(query) {
  const q = (query || '').toLowerCase().trim();
  const sections = document.querySelectorAll('#grammar-accordion .grammar-section');
  let visible = 0;
  sections.forEach(sec => {
    const text = sec.textContent.toLowerCase();
    const match = !q || text.includes(q);
    sec.style.display = match ? '' : 'none';
    if (match) visible++;
    // Auto-expand matched sections
    if (q && match) {
      const id = sec.querySelector('.grammar-header')?.id?.replace('gh-','');
      if (id) {
        document.getElementById('gh-'+id)?.classList.add('open');
        document.getElementById('gb-'+id)?.classList.add('open');
      }
    }
  });
  const noRes = document.getElementById('grammar-no-results');
  if (noRes) noRes.style.display = (visible === 0 && q) ? '' : 'none';
}

// ─── GRAMMAR EXERCISES ────────────────────────────────────────────────────────

let _gexState = {};

function startGrammarExercise(sectionId) {
  const qs = GRAMMAR_EXERCISES[sectionId];
  if (!qs) return;
  _gexState[sectionId] = { idx: 0, score: 0, answered: false };
  renderGrammarExercise(sectionId);
}

function renderGrammarExercise(sectionId) {
  const el = document.getElementById('gex-' + sectionId);
  if (!el) return;
  const qs = GRAMMAR_EXERCISES[sectionId];
  const st = _gexState[sectionId];
  if (!st) return;

  if (st.idx >= qs.length) {
    const pct = Math.round(st.score / qs.length * 100);
    const emoji = pct === 100 ? '🏆' : pct >= 70 ? '🌟' : '📚';
    el.innerHTML = `<div class="gex-title">🎯 Practice Complete</div>
      <div class="gex-score">${emoji} ${st.score}/${qs.length} correct (${pct}%)</div>
      <div class="gex-feedback">${pct === 100 ? 'Perfect! You\'ve mastered this grammar point.' : pct >= 70 ? 'Good work! Review the explanations above to sharpen your understanding.' : 'Keep studying — re-read the section above and try again.'}</div>
      <div class="gex-btn-row">
        <button class="btn btn-outline" style="font-size:0.8rem;padding:6px 12px" onclick="startGrammarExercise('${sectionId}')">↺ Try again</button>
      </div>`;
    return;
  }

  const q = qs[st.idx];
  const optsHtml = q.opts.map((o, i) =>
    `<button class="gex-opt" onclick="answerGrammarEx(this,${i},'${sectionId}')">${o}</button>`
  ).join('');

  el.innerHTML = `
    <div class="gex-title">🎯 Practice — Question ${st.idx + 1}/${qs.length}</div>
    <div class="gex-q">${q.q}</div>
    <div class="gex-opts">${optsHtml}</div>
    <div class="gex-feedback" id="gex-fb-${sectionId}"></div>
    <div class="gex-progress">${st.score} correct so far</div>
  `;
}

function answerGrammarEx(btn, chosenIdx, sectionId) {
  const st = _gexState[sectionId];
  if (!st || st.answered) return;
  st.answered = true;

  const qs = GRAMMAR_EXERCISES[sectionId];
  const q = qs[st.idx];
  const isCorrect = chosenIdx === q.ans;

  const el = document.getElementById('gex-' + sectionId);
  el.querySelectorAll('.gex-opt').forEach((b, i) => {
    b.disabled = true;
    if (i === q.ans) b.classList.add('gex-correct');
  });
  if (!isCorrect) btn.classList.add('gex-wrong');

  if (isCorrect) { st.score++; sfx(sfxCorrect); recordActivity(); incDailyCount(); if (typeof addXp === 'function') addXp((typeof XP_PER_RATING !== 'undefined' ? XP_PER_RATING[2] : 0) || 10); }
  else sfx(sfxWrong);

  const fb = document.getElementById('gex-fb-' + sectionId);
  if (fb) fb.innerHTML = `<span style="color:var(--${isCorrect ? 'easy' : 'again'})">${isCorrect ? '✓ Correct!' : '✗ Not quite.'}</span> ${q.exp}`;

  setTimeout(() => {
    st.idx++;
    st.answered = false;
    renderGrammarExercise(sectionId);
  }, 1800);
}

// ─── NAV ─────────────────────────────────────────────────────────────────────
function showView(name) {
  document.querySelectorAll('.view').forEach(v => v.classList.remove('active'));
  document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
  document.getElementById('view-' + name).classList.add('active');
  const btn = document.querySelector(`.tab-btn[onclick="showView('${name}')"]`);
  if (btn) btn.classList.add('active');
  setHash(name);
  if (name === 'study') { renderTodayDashboard(); renderSmartRecs(); renderHourlyForecast(); setupSentenceOfDay(); renderProverbOfDay(); }
  if (name === 'browse') { renderCatFilters(); renderLevelFilters(); updateBrowseListFilter(); renderBrowse(); }
  if (name === 'stats') renderStats();
  if (name === 'quiz') startQuiz();
  if (name === 'sounds') renderSounds();
  if (name === 'grammar') renderGrammar();
  if (name === 'build') startBuild();
  if (name === 'convo') renderConvoList();
  if (name === 'read') renderReadPassages();
  if (name === 'path') renderLearningPath();
  if (name === 'phrases') { renderPhrasebook(); setTimeout(updatePhraseDueBadge, 50); }
  if (name === 'listen') renderListenView();
  if (name === 'proverbs') renderProverbsView();
  if (name === 'numbers') renderNumbersView();
}

// ─── HASH ROUTING ────────────────────────────────────────────────────────────
const VALID_VIEWS = new Set(['study','browse','quiz','sounds','grammar','stats','build','convo','read','path','phrases','listen','flashcard','proverbs','numbers']);

function initHashRouting() {
  const hash = window.location.hash.slice(1);
  if (hash) applyHash(hash);
  window.addEventListener('hashchange', () => applyHash(window.location.hash.slice(1)));
}

function applyHash(hash) {
  if (!hash) return;
  if (hash.startsWith('word/')) {
    const id = hash.slice(5);
    const v = VOCAB_BY_ID[id];
    if (v) { setTimeout(() => openWordModal(id), 200); return; }
  }
  if (VALID_VIEWS.has(hash)) {
    showView(hash);
  }
}

function setHash(view) {
  const newHash = '#' + view;
  if (window.location.hash !== newHash) {
    history.replaceState(null, '', newHash);
  }
}

// ─── UTILS ───────────────────────────────────────────────────────────────────
function debounce(fn, ms) {
  let t;
  return (...args) => { clearTimeout(t); t = setTimeout(() => fn(...args), ms); };
}
const debouncedBrowse = debounce(renderBrowse, 150);

function shuffle(arr) {
  const a = [...arr];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// ─── SWIPE GESTURES ─────────────────────────────────────────────────────────
(function initSwipe() {
  const fc = document.getElementById('flashcard');
  if (!fc) return; // Run #47 BUG FIX: avoid TypeError if flashcard div missing
  let sx = 0, sy = 0, st = 0;
  fc.addEventListener('touchstart', e => {
    sx = e.touches[0].clientX; sy = e.touches[0].clientY; st = Date.now();
  }, { passive: true });
  fc.addEventListener('touchend', e => {
    if (!currentCard || Date.now() - st > 700) return;
    const dx = e.changedTouches[0].clientX - sx;
    const dy = e.changedTouches[0].clientY - sy;
    const adx = Math.abs(dx), ady = Math.abs(dy);
    const revealed = fc.classList.contains('card-revealed');
    if (adx > 55 && adx > ady * 1.4) {
      if (!revealed) { revealCard(); return; }
      dx > 0 ? rate(2) : rate(0); // right=good, left=again
    } else if (ady > 55 && ady > adx * 1.4) {
      if (!revealed) { revealCard(); return; }
      dy < 0 ? rate(3) : rate(1); // up=easy, down=hard
    }
  }, { passive: true });
})();

// ─── INIT ────────────────────────────────────────────────────────────────────
ttsAutoSpeak = localStorage.getItem('la_autospeak') !== '0';
// Seed audio cache from pre-baked data — only runs once (won't overwrite entries already in cache)
(function seedAudioCache() {
  const cache = audioCache();
  let seeded = false;
  for (const [word, url] of Object.entries(PRECACHED_AUDIO)) {
    // Run #80: also override stale __none__ entries from pre-seed era, so users with old caches get the precached URLs
    if (!(word in cache) || cache[word] === '__none__') { cache[word] = url; seeded = true; }
  }
  if (seeded) saveAudioCache(cache);
})();
let hardWordsMode = false;
let hardMode = localStorage.getItem('la_hard_mode') === '1';

function applyHardMode() {
  document.body.classList.toggle('hard-mode', hardMode);
  const btn = document.getElementById('hard-mode-btn');
  if (btn) {
    btn.style.background = hardMode ? 'var(--hard)' : '';
    btn.style.color = hardMode ? '#fff' : '';
    btn.style.borderColor = hardMode ? 'var(--hard)' : '';
    btn.title = hardMode ? 'Hard Mode ON — transliteration hidden. Click to disable.' : 'Hard Mode: hides transliteration — read Arabic script only';
  }
  // Show/hide hard mode badge in nav
  let badge = document.getElementById('hard-mode-nav-badge');
  if (hardMode && !badge) {
    const streak = document.getElementById('nav-streak');
    if (streak && streak.parentNode) {
      badge = document.createElement('span');
      badge.id = 'hard-mode-nav-badge';
      badge.className = 'hard-mode-badge';
      badge.textContent = 'HARD';
      streak.parentNode.insertBefore(badge, streak.nextSibling);
    }
  } else if (!hardMode && badge) {
    badge.remove();
  }
}

function toggleHardMode() {
  hardMode = !hardMode;
  _lsSet('la_hard_mode', hardMode ? '1' : '0');
  applyHardMode();
}

