let _phraseFavsOnly = false;
let _phraseQuery = '';

function getPhraseFavs() {
  try { return JSON.parse(localStorage.getItem('la_phrase_favs') || '[]'); } catch(e) { return []; }
}
function togglePhraseFav(ar) {
  let favs = getPhraseFavs();
  if (favs.includes(ar)) favs = favs.filter(f => f !== ar);
  else favs.push(ar);
  _lsSet('la_phrase_favs', JSON.stringify(favs));
  renderPhrasebook();
}
function togglePhraseFavs() {
  _phraseFavsOnly = !_phraseFavsOnly;
  const btn = document.getElementById('phrase-favs-btn');
  if (btn) { btn.textContent = _phraseFavsOnly ? '★ Favs' : '☆ Favs'; btn.classList.toggle('active', _phraseFavsOnly); }
  renderPhrasebook();
}
function showRandomPhrase() {
  const allPhrases = [];
  for (const cat of PHRASEBOOK) {
    for (const p of cat.phrases) allPhrases.push({ ...p, cat: cat.cat });
  }
  const p = allPhrases[Math.floor(Math.random() * allPhrases.length)];
  if (!p) return;
  const toast = document.createElement('div');
  toast.style.cssText = 'position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:var(--card);border:1px solid var(--accent2);border-radius:14px;padding:14px 18px;z-index:9999;max-width:320px;width:90%;box-shadow:0 4px 24px rgba(0,0,0,0.3);cursor:pointer';
  toast.innerHTML = `<div style="font-size:0.68rem;text-transform:uppercase;letter-spacing:1px;color:var(--muted);margin-bottom:4px">${p.cat}</div>
    <div style="font-size:1.5rem;direction:rtl;font-family:'Noto Naskh Arabic',serif;margin-bottom:4px" onclick="speak('${p.ar.replace(/'/g,"\\'")}');event.stopPropagation()">${p.ar} 🔊</div>
    <div style="color:var(--accent2);font-style:italic;margin-bottom:2px">${p.tr}</div>
    <div style="font-size:0.88rem;font-weight:600">${p.en}</div>
    <div style="font-size:0.68rem;color:var(--muted);margin-top:8px">Tap to dismiss · 🎲 again</div>`;
  toast.onclick = () => { if (toast.parentNode) toast.parentNode.removeChild(toast); };
  document.body.appendChild(toast);
  speak(p.ar);
  setTimeout(() => { if (toast.parentNode) toast.parentNode.removeChild(toast); }, 8000);
}

function filterPhrasebook(q) {
  _phraseQuery = q.toLowerCase().trim();
  renderPhrasebook();
}

function renderPhrasebook() {
  const el = document.getElementById('phrasebook-content');
  if (!el) return;
  const favs = getPhraseFavs();
  const q = _phraseQuery;

  let totalShown = 0;
  const html = PHRASEBOOK.map(section => {
    const filtered = section.phrases.filter(p => {
      const matchQ = !q || p.ar.includes(q) || p.tr.toLowerCase().includes(q) || p.en.toLowerCase().includes(q);
      const matchFav = !_phraseFavsOnly || favs.includes(p.ar);
      return matchQ && matchFav;
    });
    if (filtered.length === 0) return '';
    totalShown += filtered.length;
    return `
    <div class="phrase-cat-title">${section.cat} <span style="font-size:0.7rem;color:var(--muted);font-weight:400">(${filtered.length})</span></div>
    ${filtered.map(p => {
      const isFav = favs.includes(p.ar);
      return `
      <div class="phrase-card">
        <div class="phrase-card-text" style="flex:1">
          <div class="phrase-card-ar ar">${p.ar}</div>
          <div class="phrase-card-tr">${p.tr}</div>
          <div class="phrase-card-en">${p.en}</div>
        </div>
        <div style="display:flex;flex-direction:column;gap:4px">
          <button class="speak-btn" onclick="speak(${attrArg(p.ar)})" title="Pronounce">🔊</button>
          <button onclick="togglePhraseFav(${attrArg(p.ar)})" style="background:none;border:none;cursor:pointer;font-size:1rem;color:${isFav?'var(--accent2)':'var(--muted)'};padding:2px" title="${isFav?'Remove from favorites':'Add to favorites'}">${isFav?'★':'☆'}</button>
        </div>
      </div>`;
    }).join('')}`;
  }).join('');

  el.innerHTML = html || `<div style="text-align:center;padding:32px;color:var(--muted)">${_phraseFavsOnly?'No favorite phrases yet — tap ☆ on any phrase':'No phrases match your search'}</div>`;
}

