let readShowTr = true;
let readShowEn = false;

function startPassageQuiz(passageId) {
  const p = READ_PASSAGES.find(r => r.id === passageId);
  if (!p || !p.quiz) return;
  const el = document.getElementById('pq-' + passageId);
  if (!el) return;
  el.style.display = '';
  let qIdx = 0, score = 0;
  function renderQ() {
    if (qIdx >= p.quiz.length) {
      el.innerHTML = `<div style="text-align:center;padding:12px 0">
        <div style="font-size:1.6rem;margin-bottom:6px">${score === p.quiz.length ? '🏆' : score >= p.quiz.length/2 ? '🌟' : '📚'}</div>
        <div style="font-weight:700;margin-bottom:4px">Score: ${score}/${p.quiz.length}</div>
        <div style="color:var(--muted);font-size:0.82rem;margin-bottom:12px">${score === p.quiz.length ? 'Perfect!' : 'Keep reading to improve!'}</div>
        <button class="btn btn-outline" style="font-size:0.8rem" onclick="startPassageQuiz('${passageId}')">Retry</button>
      </div>`;
      return;
    }
    const q = p.quiz[qIdx];
    el.innerHTML = `<div class="pq-question">Q${qIdx+1}: ${q.q}</div>
      <div class="pq-opts">${q.opts.map((o,i) => `<button class="pq-opt" onclick="answerPassageQ(this,${i},${q.ans},'${passageId}',${qIdx})">${o}</button>`).join('')}</div>`;
  }
  window._pqNext = window._pqNext || {};
  window._pqNext[passageId] = { advance: () => { qIdx++; renderQ(); }, addScore: () => { score++; } };
  renderQ();
}
function answerPassageQ(btn, chosen, correct, passageId, qIdx) {
  const el = document.getElementById('pq-' + passageId);
  el.querySelectorAll('.pq-opt').forEach((b,i) => {
    b.disabled = true;
    if (i === correct) b.classList.add('correct');
    else if (b === btn && chosen !== correct) b.classList.add('wrong');
  });
  if (chosen === correct) { sfx(sfxCorrect); window._pqNext[passageId].addScore(); recordActivity(); incDailyCount(); if (typeof addXp === 'function') addXp((typeof XP_PER_RATING !== 'undefined' ? XP_PER_RATING[2] : 0) || 10); }
  else sfx(sfxWrong);
  setTimeout(() => window._pqNext[passageId].advance(), 900);
}

function studyPassageVocab(passageId) {
  const p = READ_PASSAGES.find(x => x.id === passageId);
  if (!p) return;
  // Collect all Arabic tokens from the passage
  const passageWords = new Set();
  p.sentences.forEach(s => {
    s.ar.split(/[\s،.؟!]+/).forEach(w => { if (w) passageWords.add(w.replace(/[ًٌٍَُِّ]/g, '')); });
  });
  // Find VOCAB words whose Arabic appears in the passage and aren't well-learned (reps < 3)
  const toStudy = VOCAB.filter(v => {
    const clean = v.ar.replace(/[ًٌٍَُِّ]/g, '');
    const c = getCard(v.id);
    return passageWords.has(clean) && (c.reps < 3);
  });
  if (toStudy.length === 0) {
    // Fall back to all passage-matching words
    const allMatch = VOCAB.filter(v => passageWords.has(v.ar.replace(/[ًٌٍَُِّ]/g,'')));
    if (allMatch.length === 0) { alert('No matching vocabulary found for this passage.'); return; }
    startWordListStudy(allMatch, 'Passage: ' + p.title);
    return;
  }
  startWordListStudy(toStudy, 'Passage: ' + p.title);
}

function studyCategory(cat) {
  const words = VOCAB.filter(v => v.cat === cat);
  if (!words.length) return;
  startWordListStudy(words, cat);
}

function startLevelStudy(lv) {
  const words = VOCAB.filter(v => v.level === lv && getCard(v.id).reps === 0);
  if (!words.length) {
    showMilestoneToast(`All ${LEVEL_LABELS[lv]} words already started!`);
    return;
  }
  startWordListStudy(words.slice(0, 20), LEVEL_LABELS[lv] + ' — New Words');
}

function startWordListStudy(words, label) {
  studyQueue = words.map(w => w.id);
  studyIndex = 0;
  sessionTotal = studyQueue.length;
  sessionCorrect = 0; sessionAgain = 0; sessionHard = 0; sessionGood = 0; sessionEasy = 0; sessionXpGained = 0;
  sessionStartTime = Date.now();
  showView('study');
  document.getElementById('study-main').style.display = '';
  document.getElementById('study-done').style.display = 'none';
  updateStudyProgress();
  showCard();
  const tip = document.getElementById('smart-recs');
  if (tip) tip.innerHTML = `<div style="font-size:0.8rem;color:var(--accent2);padding:6px 10px;background:var(--card2);border-radius:8px;margin-bottom:8px">📖 Studying vocab from: <strong>${label}</strong> — ${words.length} words</div>`;
}

function toggleReadTr() {
  readShowTr = !readShowTr;
  const btn = document.getElementById('read-tr-btn');
  if (btn) { btn.classList.toggle('active', readShowTr); }
  renderReadPassages();
}
function toggleReadEn() {
  readShowEn = !readShowEn;
  const btn = document.getElementById('read-en-btn');
  if (btn) { btn.classList.toggle('active', readShowEn); }
  renderReadPassages();
}

function renderReadPassages() {
  const el = document.getElementById('read-passages');
  if (!el) return;
  el.innerHTML = READ_PASSAGES.map(p => {
    const sentences = p.sentences.map((s, si) => `
      <div class="passage-sentence">
        <div class="passage-ar">${tokenizePassage(s.ar, p.id, si)}</div>
        ${readShowTr ? `<div class="passage-tr">${s.tr}</div>` : ''}
        ${readShowEn ? `<div class="passage-en">${s.en}</div>` : ''}
      </div>
    `).join('');
    return `
      <div class="passage-card">
        <div class="passage-title">${p.emoji} ${p.title} <span class="passage-level">${p.level}</span></div>
        <div style="height:12px"></div>
        ${sentences}
        <div class="passage-actions">
          <button class="btn btn-outline" style="font-size:0.8rem;padding:6px 12px" onclick="playPassageAudio('${p.id}')">▶ Listen</button>
          ${p.quiz ? `<button class="btn btn-outline" style="font-size:0.8rem;padding:6px 12px" onclick="startPassageQuiz('${p.id}')">📝 Quiz</button>` : ''}
          <button class="btn btn-outline" style="font-size:0.8rem;padding:6px 12px" onclick="studyPassageVocab('${p.id}')" title="Study words from this passage you haven't learned yet">📖 Study Vocab</button>
        </div>
        <div id="pq-${p.id}" class="passage-quiz" style="display:none"></div>
      </div>
    `;
  }).join('');
  // Re-attach tooltip events
  document.querySelectorAll('.passage-word').forEach(w => {
    w.addEventListener('click', e => showReadTooltip(w, e));
  });
  document.addEventListener('click', hideReadTooltip, { once: false });
}

function tokenizePassage(text, passageId, sentIdx) {
  // Split Arabic text on spaces, wrap each word in a clickable span
  return text.split(/(\s+)/).map((tok, i) => {
    if (/^\s+$/.test(tok)) return tok;
    const clean = tok.replace(/[،.؟!]/g, '');
    if (!clean) return tok;
    return `<span class="passage-word" data-ar="${clean}" data-pid="${passageId}" data-si="${sentIdx}">${tok}</span>`;
  }).join('');
}

function showReadTooltip(wordEl, e) {
  e.stopPropagation();
  const ar = wordEl.dataset.ar;
  if (!ar) return;

  // Look up in VOCAB
  const match = VOCAB.find(v => v.ar === ar || v.ar.includes(ar) || ar.includes(v.ar.replace(/[ًٌٍَُِّ]/g,'')));

  const tt = document.getElementById('read-tooltip');
  document.getElementById('rtt-ar').textContent = ar;
  if (match) {
    document.getElementById('rtt-tr').textContent = match.tr;
    document.getElementById('rtt-en').textContent = match.en;
  } else {
    document.getElementById('rtt-tr').textContent = '';
    document.getElementById('rtt-en').textContent = '(tap to hear pronunciation)';
  }
  tt.style.display = 'block';
  const rect = wordEl.getBoundingClientRect();
  const ttW = 220;
  let left = rect.left + window.scrollX;
  if (left + ttW > window.innerWidth - 10) left = window.innerWidth - ttW - 10;
  tt.style.left = left + 'px';
  tt.style.top = (rect.bottom + window.scrollY + 6) + 'px';
  speak(ar);
}

function hideReadTooltip(e) {
  const tt = document.getElementById('read-tooltip');
  if (tt && !tt.contains(e.target) && !e.target.classList.contains('passage-word')) {
    tt.style.display = 'none';
  }
}

async function playPassageAudio(passageId) {
  const p = READ_PASSAGES.find(r => r.id === passageId);
  if (!p) return;
  for (const s of p.sentences) {
    await speak(s.ar);
    await new Promise(r => setTimeout(r, 1800));
  }
}

// ─── CONVERSATIONS ────────────────────────────────────────────────────────────

let activeConvo = null;
let convoPlayIndex = -1;
let convoPlayTimer = null;

function renderConvoList() {
  document.getElementById('convo-list').style.display = '';
  document.getElementById('convo-detail').style.display = 'none';
  const el = document.getElementById('convo-list');
  el.innerHTML = CONVERSATIONS.map(c => `
    <div class="convo-card" onclick="openConvo('${c.id}')">
      <div class="convo-card-header">
        <div class="convo-card-emoji">${c.emoji}</div>
        <div>
          <div class="convo-card-title">${c.title}</div>
          <div class="convo-card-meta">${c.desc} · ${c.lines.length} lines</div>
        </div>
      </div>
    </div>
  `).join('');
}

function openConvo(id) {
  activeConvo = CONVERSATIONS.find(c => c.id === id);
  if (!activeConvo) return;
  document.getElementById('convo-list').style.display = 'none';
  const detail = document.getElementById('convo-detail');
  detail.style.display = '';
  document.getElementById('convo-title').textContent = activeConvo.emoji + ' ' + activeConvo.title;
  document.getElementById('convo-desc').textContent = activeConvo.desc;
  renderConvoLines();
}

function renderConvoLines() {
  const el = document.getElementById('convo-lines');
  el.innerHTML = activeConvo.lines.map((line, i) => `
    <div class="convo-line" id="convo-line-${i}" onclick="playConvoLine(${i})">
      <div class="convo-speaker convo-speaker-${line.s.toLowerCase()}">${line.s}</div>
      <div class="convo-text-col">
        <div class="convo-ar">${line.ar}</div>
        <div class="convo-tr">${line.tr}</div>
        <div class="convo-en">${line.en}</div>
      </div>
      <div style="padding-right:4px;color:var(--muted);font-size:0.8rem;align-self:center">▶</div>
    </div>
  `).join('');
}

function playConvoLine(index) {
  if (!activeConvo) return;
  document.querySelectorAll('.convo-line').forEach(el => el.classList.remove('playing'));
  const lineEl = document.getElementById('convo-line-' + index);
  if (lineEl) lineEl.classList.add('playing');
  speak(activeConvo.lines[index].ar);
}

async function playAllConvoLines() {
  if (!activeConvo) return;
  for (let i = 0; i < activeConvo.lines.length; i++) {
    playConvoLine(i);
    await new Promise(r => setTimeout(r, 2200));
  }
  document.querySelectorAll('.convo-line').forEach(el => el.classList.remove('playing'));
}

function closeConvo() {
  activeConvo = null;
  renderConvoList();
}

// ─── CONVERSATION PRACTICE MODE ──────────────────────────────────────────────
let _cpRole = 'B', _cpRevealed = new Set();

function startConvoPractice() {
  if (!activeConvo) return;
  _cpRevealed = new Set();
  const panel = document.getElementById('convo-practice-panel');
  panel.style.display = '';
  renderConvoPractice();
  panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function renderConvoPractice() {
  const panel = document.getElementById('convo-practice-panel');
  if (!panel || !activeConvo) return;
  const lines = activeConvo.lines;
  panel.innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">
      <div>
        <strong style="font-size:0.9rem">📝 Practice Mode</strong>
        <span style="font-size:0.75rem;color:var(--muted);margin-left:8px">You are Speaker <strong>${_cpRole}</strong></span>
      </div>
      <div style="display:flex;gap:6px">
        <button class="cat-filter${_cpRole==='A'?' active':''}" onclick="_cpRole='A';_cpRevealed=new Set();renderConvoPractice()">Play A</button>
        <button class="cat-filter${_cpRole==='B'?' active':''}" onclick="_cpRole='B';_cpRevealed=new Set();renderConvoPractice()">Play B</button>
        <button class="btn btn-outline" style="padding:3px 10px;font-size:0.75rem" onclick="_cpRevealed=new Set(lines.map((_,i)=>i));renderConvoPractice()">Reveal All</button>
        <button class="btn btn-outline" style="padding:3px 10px;font-size:0.75rem" onclick="document.getElementById('convo-practice-panel').style.display='none'">✕</button>
      </div>
    </div>
    <div style="font-size:0.75rem;color:var(--muted);margin-bottom:10px">Tap hidden lines to reveal them. Speak the lines aloud!</div>
    ${lines.map((l, i) => {
      const isYou = l.s === _cpRole;
      const revealed = _cpRevealed.has(i) || isYou;
      const bg = isYou ? 'var(--blue)18' : 'var(--card)';
      const border = isYou ? 'var(--blue)' : 'var(--border)';
      return `<div style="display:flex;gap:10px;align-items:flex-start;margin-bottom:10px;${isYou?'flex-direction:row-reverse':''}">
        <div style="min-width:24px;height:24px;border-radius:50%;background:${isYou?'var(--blue)':'var(--border)'};color:${isYou?'#fff':'var(--muted)'};display:flex;align-items:center;justify-content:center;font-size:0.72rem;font-weight:700;flex-shrink:0">${l.s}</div>
        <div onclick="${revealed||isYou?`speak(${attrArg(l.ar)})`:`cpReveal(${i})`}"
          style="flex:1;background:${bg};border:1.5px solid ${border};border-radius:10px;padding:10px 12px;cursor:pointer;
          ${!revealed&&!isYou?'filter:blur(4px);user-select:none':''}">
          <div style="direction:rtl;font-family:\'Segoe UI\',\'Noto Naskh Arabic\',serif;font-size:1.05rem;margin-bottom:3px">${l.ar}</div>
          <div style="font-size:0.78rem;color:var(--accent2);font-style:italic">${l.tr}</div>
          <div style="font-size:0.78rem;color:var(--muted);margin-top:2px">${l.en}</div>
        </div>
      </div>`;
    }).join('')}`;
  // Expose lines for reveal function
  window._cpLines = lines;
}

function cpReveal(i) {
  _cpRevealed.add(i);
  renderConvoPractice();
  const lines = window._cpLines;
  if (lines && lines[i]) speak(lines[i].ar);
}

// ─── SHADOWING MODE ──────────────────────────────────────────────────────────
let _shadowStep = 0, _shadowPaused = false, _shadowTimer = null;

function startShadowing() {
  if (!activeConvo) return;
  _shadowStep = 0; _shadowPaused = false;
  clearTimeout(_shadowTimer);
  document.getElementById('shadow-overlay').style.display = 'flex';
  document.getElementById('shadow-title').textContent = activeConvo.emoji + ' ' + activeConvo.title;
  shadowShowLine();
}

function closeShadowing() {
  clearTimeout(_shadowTimer);
  if (typeof stopAllAudio === 'function') stopAllAudio();
  document.getElementById('shadow-overlay').style.display = 'none';
  _shadowPaused = false;
}

function shadowShowLine() {
  const convo = activeConvo;
  if (!convo || _shadowStep >= convo.lines.length) {
    shadowFinish(); return;
  }
  const line = convo.lines[_shadowStep];
  const hideText = document.getElementById('shadow-hide-text')?.checked;
  document.getElementById('shadow-progress').textContent = `${_shadowStep + 1} / ${convo.lines.length}`;
  document.getElementById('shadow-speaker').textContent = line.s === 'A' ? 'Speaker A' : 'Speaker B';
  document.getElementById('shadow-ar').textContent = hideText ? '— — —' : line.ar;
  document.getElementById('shadow-tr').textContent = hideText ? '' : line.tr;
  document.getElementById('shadow-en').textContent = hideText ? '' : line.en;
  document.getElementById('shadow-repeat-bar').style.display = 'none';
  speak(line.ar);
  // After audio estimate (~1.5s/word), start repeat countdown
  const wordCount = (line.ar.match(/\S+/g) || []).length;
  const audioMs = Math.max(1500, wordCount * 600);
  _shadowTimer = setTimeout(() => {
    if (!_shadowPaused) shadowStartRepeat();
  }, audioMs);
}

function shadowStartRepeat() {
  const repeatMs = parseInt(document.getElementById('shadow-repeat-time')?.value || '3000');
  const bar = document.getElementById('shadow-repeat-bar');
  const countdown = document.getElementById('shadow-countdown');
  bar.style.display = '';
  let remaining = Math.round(repeatMs / 1000);
  countdown.textContent = remaining;
  const tick = setInterval(() => {
    remaining--;
    countdown.textContent = remaining > 0 ? remaining : '↗';
    if (remaining <= 0) { clearInterval(tick); }
  }, 1000);
  if (document.getElementById('shadow-auto-adv')?.checked) {
    _shadowTimer = setTimeout(() => { if (!_shadowPaused) shadowNext(); }, repeatMs);
  }
}

function shadowNext() {
  clearTimeout(_shadowTimer);
  _shadowStep++;
  if (_shadowStep < (activeConvo?.lines.length || 0)) {
    shadowShowLine();
  } else {
    shadowFinish();
  }
}

function shadowUpdateDisplay() { shadowShowLine(); }

function toggleShadowPause() {
  _shadowPaused = !_shadowPaused;
  const btn = document.getElementById('shadow-pause-btn');
  if (btn) btn.textContent = _shadowPaused ? '▶ Resume' : '⏸ Pause';
  if (!_shadowPaused) shadowShowLine();
  else clearTimeout(_shadowTimer);
}

function shadowFinish() {
  clearTimeout(_shadowTimer);
  document.getElementById('shadow-ar').textContent = '🎉';
  document.getElementById('shadow-tr').textContent = 'Shadowing complete!';
  document.getElementById('shadow-en').textContent = 'Great work — you spoke all ' + (activeConvo?.lines.length || 0) + ' lines.';
  document.getElementById('shadow-speaker').textContent = '';
  document.getElementById('shadow-repeat-bar').style.display = 'none';
  document.getElementById('shadow-progress').textContent = 'Done';
}

// ─── ROLE-PLAY MODE ───────────────────────────────────────────────────────────
let _rpSide = null; // 'A' or 'B'
let _rpStep = 0;    // current line index

function startRolePlay() {
  if (!activeConvo) return;
  _rpStep = 0;
  _rpSide = null;
  document.getElementById('roleplay-overlay').style.display = '';
  document.getElementById('rp-title').textContent = activeConvo.emoji + ' ' + activeConvo.title;
  // Show side selection
  const speakers = [...new Set(activeConvo.lines.map(l => l.s))].sort();
  const body = document.getElementById('rp-body');
  body.innerHTML = `
    <div style="text-align:center;margin-bottom:10px">
      <div style="font-size:0.88rem;color:var(--muted);margin-bottom:16px">Choose which speaker you'll practice as:</div>
      <div class="rp-side-select">
        ${speakers.map(s => `
          <div class="rp-side-btn" onclick="selectRpSide('${s}')">
            <div class="rp-side-icon">${s === 'A' ? '🧑' : '👤'}</div>
            <div class="rp-side-label">Speaker ${s}</div>
            <div class="rp-side-sub">${activeConvo.lines.filter(l=>l.s===s).length} lines</div>
          </div>`).join('')}
      </div>
      <div style="font-size:0.78rem;color:var(--muted);margin-top:16px">The app will play the other speaker's lines. You practice yours.</div>
    </div>`;
  document.getElementById('rp-progress').textContent = '';
}

function selectRpSide(side) {
  _rpSide = side;
  _rpStep = 0;
  renderRpStep();
}

function renderRpStep() {
  const convo = activeConvo;
  if (!convo) return;
  const lines = convo.lines;
  const body = document.getElementById('rp-body');
  const prog = document.getElementById('rp-progress');

  if (_rpStep >= lines.length) {
    // Done!
    const myLines = lines.filter(l => l.s === _rpSide).length;
    body.innerHTML = `<div class="rp-done-screen">
      <div class="rp-score">🎭</div>
      <div style="font-size:1.4rem;font-weight:700;margin-bottom:8px">Great practice!</div>
      <div style="color:var(--muted);font-size:0.88rem;margin-bottom:24px">You practiced ${myLines} line${myLines!==1?'s':''} as Speaker ${_rpSide}.</div>
      <div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap">
        <button class="btn" onclick="selectRpSide(_rpSide)">Practice Again</button>
        <button class="btn btn-outline" onclick="selectRpSide(_rpSide==='A'?'B':'A')">Switch Sides</button>
        <button class="btn btn-outline" onclick="closeRolePlay()">Done</button>
      </div>
    </div>`;
    prog.textContent = 'Complete!';
    return;
  }

  prog.textContent = `Line ${_rpStep + 1} / ${lines.length}`;
  const line = lines[_rpStep];
  const isYourTurn = line.s === _rpSide;

  if (isYourTurn) {
    body.innerHTML = `
      <div class="rp-your-turn">
        <div class="rp-speaker-badge you">🎙️ Your turn — Speaker ${_rpSide}</div>
        <div class="rp-prompt">${line.en}</div>
        <div id="rp-reveal" class="rp-reveal-area" style="display:none">
          <div class="rp-ar">${line.ar}</div>
          <div class="rp-tr">${line.tr}</div>
          <button class="speak-btn" style="width:36px;height:36px;font-size:1rem;margin-top:8px" onclick="speak('${line.ar.replace(/'/g,"\\'")}')">🔊</button>
        </div>
        <div class="rp-controls">
          <button class="btn btn-outline" onclick="rpReveal()">👁 Reveal Arabic</button>
          <button class="btn" onclick="rpNext()">Next →</button>
        </div>
      </div>`;
  } else {
    // Their turn — show their line and auto-play
    body.innerHTML = `
      <div class="rp-turn-card">
        <div class="rp-speaker-badge them">🔊 Speaker ${line.s}</div>
        <div class="rp-ar">${line.ar}</div>
        <div class="rp-tr">${line.tr}</div>
        <div class="rp-en">${line.en}</div>
        <div class="rp-controls" style="margin-top:16px">
          <button class="btn btn-outline" onclick="speak('${line.ar.replace(/'/g,"\\'")}')">🔊 Play again</button>
          <button class="btn" onclick="rpNext()">Next →</button>
        </div>
      </div>`;
    // Auto-play the other speaker's line
    setTimeout(() => speak(line.ar), 400);
  }
}

function rpReveal() {
  const el = document.getElementById('rp-reveal');
  if (el) el.style.display = '';
  const btn = document.querySelector('.rp-controls button:first-child');
  if (btn) btn.style.display = 'none';
}

function rpNext() {
  _rpStep++;
  renderRpStep();
}

function closeRolePlay() {
  document.getElementById('roleplay-overlay').style.display = 'none';
}

// ─── SPEED ROUND ──────────────────────────────────────────────────────────────
let speedInterval = null;
let speedTimeLeft = 60;
let speedCorrect = 0;
let speedWrong = 0;
let speedCard = null;
let speedAnswered = false;

function startSpeedRound() {
  clearInterval(speedInterval);
  speedTimeLeft = 60;
  speedCorrect = 0;
  speedWrong = 0;
  speedAnswered = false;

  const overlay = document.getElementById('speed-overlay');
  overlay.style.display = 'block';
  document.getElementById('speed-end').style.display = 'none';
  document.getElementById('speed-question').style.display = '';
  document.getElementById('speed-options').style.display = 'grid';
  document.getElementById('speed-correct').textContent = '0';
  document.getElementById('speed-wrong').textContent = '0';
  document.getElementById('speed-timer-bar').style.width = '100%';

  ['mc','type','audio','cloze','dictation','numbers','conj','context'].forEach(m =>
    document.getElementById('quiz-mode-'+m)?.classList.remove('active'));
  document.getElementById('quiz-mode-speed').classList.add('active');

  speedNextQuestion();

  speedInterval = setInterval(() => {
    speedTimeLeft--;
    document.getElementById('speed-timer-display').textContent = speedTimeLeft;
    document.getElementById('speed-timer-bar').style.width = (speedTimeLeft / 60 * 100) + '%';
    if (speedTimeLeft <= 10) {
      document.getElementById('speed-timer-display').style.color = 'var(--again)';
      document.getElementById('speed-timer-bar').style.background = 'var(--again)';
    }
    if (speedTimeLeft <= 0) endSpeedRound(false);
  }, 1000);
}

function speedNextQuestion() {
  speedAnswered = false;
  speedCard = VOCAB[Math.floor(Math.random() * VOCAB.length)];
  const toEn = Math.random() > 0.4;

  document.getElementById('speed-label').textContent = toEn ? 'What does this mean?' : 'How do you say this?';
  if (toEn) {
    document.getElementById('speed-prompt').textContent = speedCard.ar;
    document.getElementById('speed-prompt').style.direction = 'rtl';
    document.getElementById('speed-sub').textContent = speedCard.tr;
  } else {
    document.getElementById('speed-prompt').textContent = speedCard.en;
    document.getElementById('speed-prompt').style.direction = 'ltr';
    document.getElementById('speed-sub').textContent = '';
  }

  const others = shuffle(VOCAB.filter(v => v.id !== speedCard.id)).slice(0, 3);
  const choices = shuffle([speedCard, ...others]);
  const opts = document.getElementById('speed-options');
  opts.innerHTML = choices.map(c => {
    const label = toEn ? c.en : c.ar;
    return `<button class="speed-opt" onclick="answerSpeed('${c.id}', ${toEn})">${label}</button>`;
  }).join('');
}

function answerSpeed(chosenId, toEn) {
  if (speedAnswered) return;
  speedAnswered = true;
  const correct = chosenId === speedCard.id;

  document.querySelectorAll('.speed-opt').forEach(btn => {
    const label = toEn ? VOCAB_BY_ID[btn.getAttribute('onclick').match(/'([^']+)'/)[1]]?.en
                       : VOCAB_BY_ID[btn.getAttribute('onclick').match(/'([^']+)'/)[1]]?.ar;
    const thisId = btn.getAttribute('onclick').match(/'([^']+)'/)[1];
    if (thisId === speedCard.id) btn.classList.add('correct');
    else if (thisId === chosenId) btn.classList.add('wrong');
    btn.disabled = true;
  });

  if (correct) {
    speedCorrect++;
    sfx(sfxCorrect);
    recordActivity(); incDailyCount();
    if (typeof addXp === 'function') addXp((typeof XP_PER_RATING !== 'undefined' ? XP_PER_RATING[2] : 0) || 10);
  } else {
    speedWrong++;
    sfx(sfxWrong);
  }
  document.getElementById('speed-correct').textContent = speedCorrect;
  document.getElementById('speed-wrong').textContent = speedWrong;

  setTimeout(speedNextQuestion, 600);
}

function endSpeedRound(manual) {
  clearInterval(speedInterval);
  if (manual) {
    document.getElementById('speed-overlay').style.display = 'none';
    document.getElementById('quiz-mode-speed').classList.remove('active');
    document.getElementById('quiz-mode-mc').classList.add('active');
    return;
  }
  document.getElementById('speed-question').style.display = 'none';
  document.getElementById('speed-options').style.display = 'none';
  const total = speedCorrect + speedWrong;
  const pct = total > 0 ? Math.round(speedCorrect / total * 100) : 0;
  const grade = pct >= 90 ? '🏆' : pct >= 75 ? '⭐' : pct >= 50 ? '👍' : '💪';
  document.getElementById('speed-final-score').textContent =
    `${speedCorrect} correct out of ${total} (${pct}%)`;
  document.getElementById('speed-grade').textContent = grade;
  document.getElementById('speed-end').style.display = 'block';
  sfx(sfxGoal);
}

// ─── MEMORY MATCH GAME ───────────────────────────────────────────────────────
let matchCards = [];
let matchFlipped = [];
let matchSolved = 0;
let matchMoves = 0;
let matchTimer = null;
let matchSeconds = 0;
let matchLocked = false;

function openMatchGame() {
  // Pick 8 random words from current category/filter
  const pool = activeCat === 'All' ? VOCAB : VOCAB.filter(v => v.cat === activeCat);
  const words = shuffle(pool).slice(0, 8);
  matchCards = shuffle([
    ...words.map((w,i) => ({ id: i, word: w, side: 'ar', matched: false, flipped: false })),
    ...words.map((w,i) => ({ id: i, word: w, side: 'en', matched: false, flipped: false })),
  ]);
  matchFlipped = []; matchSolved = 0; matchMoves = 0; matchSeconds = 0; matchLocked = false;
  clearInterval(matchTimer);
  matchTimer = setInterval(() => {
    matchSeconds++;
    const el = document.getElementById('match-timer');
    if (el) el.textContent = Math.floor(matchSeconds/60) + ':' + String(matchSeconds%60).padStart(2,'0');
  }, 1000);
  const overlay = document.getElementById('match-overlay');
  overlay.style.display = 'flex';
  renderMatchBoard();
}

function closeMatchGame() {
  clearInterval(matchTimer);
  document.getElementById('match-overlay').style.display = 'none';
}

function renderMatchBoard() {
  const grid = document.getElementById('match-grid');
  const moves = document.getElementById('match-moves');
  if (moves) moves.textContent = matchMoves;
  grid.innerHTML = matchCards.map((c, i) => {
    const cls = c.matched ? 'match-card matched' : c.flipped ? 'match-card flipped' : 'match-card';
    const front = c.side === 'ar'
      ? `<span style="direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif;font-size:1.3rem">${c.word.ar}</span>`
      : `<span style="font-size:0.9rem;font-weight:600">${c.word.en}</span>`;
    return `<div class="${cls}" onclick="flipMatchCard(${i})" data-idx="${i}">
      <div class="match-card-inner">
        <div class="match-card-back">🇱🇧</div>
        <div class="match-card-front">${front}</div>
      </div>
    </div>`;
  }).join('');
}

function flipMatchCard(i) {
  if (matchLocked) return;
  const c = matchCards[i];
  if (c.matched || c.flipped) return;
  if (matchFlipped.length >= 2) return;

  c.flipped = true;
  matchFlipped.push(i);
  renderMatchBoard();
  sfx(sfxFlip);

  if (matchFlipped.length === 2) {
    matchMoves++;
    matchLocked = true;
    const [a, b] = matchFlipped.map(idx => matchCards[idx]);
    if (a.id === b.id && a.side !== b.side) {
      // Match!
      setTimeout(() => {
        matchCards[matchFlipped[0]].matched = true;
        matchCards[matchFlipped[1]].matched = true;
        matchFlipped = [];
        matchSolved++;
        matchLocked = false;
        sfx(sfxCorrect);
        recordActivity(); incDailyCount();
        if (typeof addXp === 'function') addXp((typeof XP_PER_RATING !== 'undefined' ? XP_PER_RATING[2] : 0) || 10);
        renderMatchBoard();
        if (matchSolved === 8) {
          clearInterval(matchTimer);
          setTimeout(() => showMatchWin(), 400);
        }
      }, 400);
    } else {
      setTimeout(() => {
        matchCards[matchFlipped[0]].flipped = false;
        matchCards[matchFlipped[1]].flipped = false;
        matchFlipped = [];
        matchLocked = false;
        sfx(sfxWrong);
        renderMatchBoard();
      }, 900);
    }
  }
}

function showMatchWin() {
  const mins = Math.floor(matchSeconds/60), secs = matchSeconds%60;
  const timeStr = mins > 0 ? `${mins}m ${secs}s` : `${secs}s`;
  document.getElementById('match-win').style.display = 'block';
  document.getElementById('match-grid').style.display = 'none';
  document.getElementById('match-win-stats').innerHTML =
    `<strong>${matchMoves}</strong> moves · <strong>${timeStr}</strong>`;
  launchConfetti();
}

function replayMatch() {
  document.getElementById('match-win').style.display = 'none';
  document.getElementById('match-grid').style.display = 'grid';
  openMatchGame();
}

// ─── NUMBERS QUIZ MODE ───────────────────────────────────────────────────────
const LEB_NUMS = [
  [0,'صفر','sifer'],[1,'واحد','wahad'],[2,'تنين','tnein'],[3,'تلاتة','tlate'],
  [4,'أربعة','arba3a'],[5,'خمسة','khemse'],[6,'ستة','sette'],[7,'سبعة','sab3a'],
  [8,'تمانية','tmenie'],[9,'تسعة','tes3a'],[10,'عشرة','3ashara'],
  [11,'حداعش','hda3sh'],[12,'تناعش','tna3sh'],[13,'تلطاعش','tletta3sh'],
  [14,'أربعطاعش','arba3ta3sh'],[15,'خمسطاعش','khamsta3sh'],[16,'ستطاعش','sitta3sh'],
  [17,'سبعطاعش','sab3ta3sh'],[18,'تمنطاعش','tamanta3sh'],[19,'تسعطاعش','tes3ta3sh'],
  [20,'عشرين','3eshrin'],[21,'واحد وعشرين','wahad w-3eshrin'],
  [22,'تنين وعشرين','tnein w-3eshrin'],[25,'خمسة وعشرين','khemse w-3eshrin'],
  [30,'تلاتين','tlatin'],[40,'أربعين','arba3in'],[50,'خمسين','khamsin'],
  [60,'ستين','sittin'],[70,'سبعين','sab3in'],[80,'تمانين','tmanin'],
  [90,'تسعين','tes3in'],[100,'مية','miye'],[200,'ميتين','miytayn'],
  [300,'تلتمية','tlutmiye'],[500,'خمسمية','khamsmiye'],[1000,'ألف','alf'],
  [2000,'ألفين','alfayn'],[1000000,'مليون','malyun'],
];
let numbersCard = null;
let numbersDirection = true; // true=show number→Arabic, false=show Arabic→number

function renderNumbersQuiz() {
  document.getElementById('quiz-options').style.display = '';
  document.getElementById('quiz-type-area').style.display = 'none';
  numbersDirection = Math.random() > 0.5;

  numbersCard = LEB_NUMS[Math.floor(Math.random() * LEB_NUMS.length)];
  const [num, ar, tr] = numbersCard;

  if (numbersDirection) {
    document.getElementById('quiz-label').textContent = 'What is this number in Lebanese Arabic?';
    document.getElementById('quiz-prompt').textContent = num.toLocaleString();
    document.getElementById('quiz-prompt').className = 'quiz-prompt';
    document.getElementById('quiz-sub').textContent = '';
  } else {
    document.getElementById('quiz-label').textContent = 'What number is this?';
    document.getElementById('quiz-prompt').innerHTML = `<span style="direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif">${ar}</span>`;
    document.getElementById('quiz-prompt').className = 'quiz-prompt';
    document.getElementById('quiz-sub').textContent = tr;
  }

  // Generate 3 distractors
  const others = shuffle(LEB_NUMS.filter(n => n[0] !== num)).slice(0, 3);
  const choices = shuffle([numbersCard, ...others]);
  const opts = document.getElementById('quiz-options');
  opts.innerHTML = '';
  choices.forEach(([n, a, t]) => {
    const btn = document.createElement('button');
    btn.className = 'quiz-opt';
    btn.textContent = numbersDirection ? `${a}  (${t})` : n.toLocaleString();
    btn.onclick = () => {
      if (quizAnswered) return;
      quizAnswered = true;
      const correct = n === num;
      btn.classList.add(correct ? 'correct' : 'wrong');
      opts.querySelectorAll('.quiz-opt').forEach(b => {
        const bn = choices.find(c => (numbersDirection ? `${c[1]}  (${c[2]})` : c[0].toLocaleString()) === b.textContent);
        if (bn && bn[0] === num) b.classList.add('correct');
        b.disabled = true;
      });
      if (correct) { quizCorrect++; quizStreakCount++; sfx(sfxCorrect); recordActivity(); incDailyCount(); if (typeof addXp === 'function') addXp((typeof XP_PER_RATING !== 'undefined' ? XP_PER_RATING[2] : 0) || 10); }
      else { quizWrong++; quizStreakCount = 0; sfx(sfxWrong); }
      updateQuizScore();
      document.getElementById('quiz-next').style.display = 'block';
      speak(ar);
    };
    opts.appendChild(btn);
  });
}

// ─── LISTENING COMPREHENSION ──────────────────────────────────────────────────

let listenCurrentStory = null;
let listenAnswers = {};

function renderListenView() {
  const list = document.getElementById('listen-story-list');
  const detail = document.getElementById('listen-story-detail');
  if (!list) return;
  detail.style.display = 'none';
  list.style.display = '';

  let scores; try { scores = JSON.parse(localStorage.getItem('la_listen_scores') || '{}'); } catch(e) { scores = {}; }
  list.innerHTML = LISTEN_STORIES.map(s => {
    const sc = scores[s.id];
    const scoreBadge = sc !== undefined
      ? `<span style="font-size:0.78rem;background:${s.color};color:#fff;padding:2px 8px;border-radius:10px;margin-left:8px">${sc}/${s.questions.length}</span>`
      : '';
    return `<div onclick="openListenStory('${s.id}')" style="background:var(--card);border-radius:14px;padding:18px 20px;margin-bottom:14px;cursor:pointer;border-left:4px solid ${s.color};display:flex;align-items:center;gap:16px;transition:transform .15s" onmouseenter="this.style.transform='translateX(4px)'" onmouseleave="this.style.transform=''">
      <div style="font-size:2rem">${s.emoji}</div>
      <div style="flex:1">
        <div style="font-weight:700;font-size:1rem;margin-bottom:2px">${s.title} ${scoreBadge}</div>
        <div style="font-size:0.82rem;color:var(--muted);direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif;margin-bottom:4px">${s.titleAr}</div>
        <div style="display:flex;gap:8px;align-items:center">
          <span style="font-size:0.72rem;background:var(--card2);padding:2px 8px;border-radius:8px;color:var(--muted)">${s.level}</span>
          <span style="font-size:0.72rem;color:var(--muted)">${s.lines.length} lines · ${s.questions.length} questions</span>
        </div>
      </div>
      <div style="color:var(--muted);font-size:1.2rem">›</div>
    </div>`;
  }).join('');
}

function openListenStory(id) {
  listenCurrentStory = LISTEN_STORIES.find(s => s.id === id);
  if (!listenCurrentStory) return;
  listenAnswers = {};

  document.getElementById('listen-story-list').style.display = 'none';
  const detail = document.getElementById('listen-story-detail');
  detail.style.display = '';

  const s = listenCurrentStory;
  document.getElementById('listen-story-header').innerHTML = `
    <div style="display:flex;align-items:center;gap:12px;margin-bottom:12px">
      <span style="font-size:2.2rem">${s.emoji}</span>
      <div>
        <div style="font-weight:700;font-size:1.2rem">${s.title}</div>
        <div style="font-size:0.9rem;direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif;color:var(--accent2)">${s.titleAr}</div>
      </div>
      <button onclick="playListenStory()" class="btn btn-outline" style="margin-left:auto;padding:8px 14px">▶ Play All</button>
    </div>
    <p style="font-size:0.82rem;color:var(--muted);margin:0">Tap 🔊 on any line to hear it. When you're ready, scroll down to answer questions.</p>
  `;

  document.getElementById('listen-story-text').innerHTML = s.lines.map((ln, i) =>
    `<div style="background:var(--card);border-radius:10px;padding:14px 16px;margin-bottom:10px;display:flex;align-items:flex-start;gap:12px">
      <button onclick="speakListenLine(${i})" style="background:var(--card2);border:none;border-radius:8px;padding:6px 10px;cursor:pointer;font-size:1rem;flex-shrink:0" title="Play">🔊</button>
      <div style="flex:1">
        <div style="direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif;font-size:1.2rem;margin-bottom:4px">${ln.ar}</div>
        <div style="font-size:0.82rem;color:var(--accent2);font-style:italic;margin-bottom:2px">${ln.tr}</div>
        <div style="font-size:0.8rem;color:var(--muted)">${ln.en}</div>
      </div>
    </div>`
  ).join('') + `<div style="margin-top:20px;text-align:center">
    <button class="btn" onclick="showListenQuiz()" style="padding:12px 28px;font-size:1rem">📝 Take the Quiz</button>
  </div>`;

  document.getElementById('listen-quiz-section').style.display = 'none';
  document.getElementById('listen-quiz-result').style.display = 'none';
}

function speakListenLine(idx) {
  if (!listenCurrentStory) return;
  const ln = listenCurrentStory.lines[idx];
  if (ln) speak(ln.ar);
}

function playListenStory() {
  if (!listenCurrentStory) return;
  const lines = listenCurrentStory.lines;
  const audio = document.getElementById('tts-audio');
  let i = 0;
  let cancelled = false;
  function next() {
    if (cancelled || i >= lines.length || !listenCurrentStory) return;
    const line = lines[i];
    i++;
    speak(line.ar);
    // Sequence on audio.ended event with a fallback timeout (1 word ≈ 600ms cap 5s).
    const wordCount = String(line.ar).trim().split(/\s+/).filter(Boolean).length;
    const fallbackMs = Math.min(5000, Math.max(1400, wordCount * 700));
    let advanced = false;
    const advance = () => { if(advanced) return; advanced = true; setTimeout(next, 220); };
    if (audio) {
      const onEnd = () => { audio.removeEventListener('ended', onEnd); advance(); };
      audio.addEventListener('ended', onEnd);
    }
    setTimeout(advance, fallbackMs);
  }
  next();
}

function showListenQuiz() {
  const s = listenCurrentStory;
  if (!s) return;
  const section = document.getElementById('listen-quiz-section');
  section.style.display = '';
  section.scrollIntoView({ behavior: 'smooth' });

  document.getElementById('listen-quiz-body').innerHTML = s.questions.map((q, qi) =>
    `<div id="lq-${qi}" style="background:var(--card);border-radius:12px;padding:16px;margin-bottom:14px">
      <div style="font-weight:600;margin-bottom:12px">${qi + 1}. ${q.q}</div>
      <div style="display:flex;flex-direction:column;gap:8px">
        ${q.opts.map((opt, oi) =>
          `<button id="lq-${qi}-${oi}" onclick="answerListenQ(${qi},${oi})"
            style="text-align:left;background:var(--card2);border:1.5px solid var(--border);border-radius:8px;padding:10px 14px;cursor:pointer;color:var(--text);font-size:0.9rem;transition:border-color .15s"
            onmouseenter="if(!this.disabled)this.style.borderColor='var(--accent2)'"
            onmouseleave="if(!this.disabled)this.style.borderColor='var(--border)'">${opt}</button>`
        ).join('')}
      </div>
      <div id="lq-fb-${qi}" style="font-size:0.82rem;margin-top:8px;min-height:18px"></div>
    </div>`
  ).join('') + `<button class="btn" onclick="submitListenQuiz()" style="width:100%;padding:12px;font-size:1rem;margin-top:8px">Submit Answers</button>`;

  document.getElementById('listen-quiz-result').style.display = 'none';
}

function answerListenQ(qi, oi) {
  if (listenAnswers[qi] !== undefined) return;
  listenAnswers[qi] = oi;
  const q = listenCurrentStory.questions[qi];
  const btns = document.querySelectorAll(`#lq-${qi} button[id^="lq-${qi}-"]`);
  btns.forEach((b, i) => {
    b.disabled = true;
    b.style.borderColor = 'var(--border)';
    if (i === q.ans) b.style.borderColor = 'var(--easy)';
    if (i === oi && oi !== q.ans) b.style.borderColor = 'var(--again)';
  });
  if (oi === q.ans) { recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10); }
  const fb = document.getElementById(`lq-fb-${qi}`);
  if (fb) fb.innerHTML = oi === q.ans
    ? `<span style="color:var(--easy)">✓ Correct!</span>`
    : `<span style="color:var(--again)">✗ The answer is: <strong>${q.opts[q.ans]}</strong></span>`;
}

function submitListenQuiz() {
  const s = listenCurrentStory;
  if (!s) return;
  let correct = 0;
  s.questions.forEach((q, qi) => {
    if (listenAnswers[qi] === q.ans) correct++;
    answerListenQ(qi, listenAnswers[qi] !== undefined ? listenAnswers[qi] : -1);
  });

  let scores; try { scores = JSON.parse(localStorage.getItem('la_listen_scores') || '{}'); } catch(e) { scores = {}; }
  const prev = scores[s.id];
  if (prev === undefined || correct > prev) scores[s.id] = correct;
  _lsSet('la_listen_scores', JSON.stringify(scores));

  const pct = (s.questions && s.questions.length > 0) ? Math.round((correct / s.questions.length) * 100) : 0;
  const msg = pct === 100 ? 'Perfect! Excellent listening!' : pct >= 75 ? 'Great job!' : pct >= 50 ? 'Good effort — review and try again!' : 'Keep practicing — you\'ll get there!';
  const res = document.getElementById('listen-quiz-result');
  res.style.display = '';
  res.innerHTML = `
    <div style="font-size:2.5rem;margin-bottom:8px">${pct === 100 ? '🏆' : pct >= 75 ? '⭐' : '📚'}</div>
    <div style="font-size:1.4rem;font-weight:700;margin-bottom:4px">${correct}/${s.questions.length} correct (${pct}%)</div>
    <div style="color:var(--muted);margin-bottom:16px">${msg}</div>
    <div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap">
      <button class="btn" onclick="openListenStory('${s.id}')">Try Again</button>
      <button class="btn btn-outline" onclick="closeListenStory()">← All Stories</button>
    </div>
  `;
  res.scrollIntoView({ behavior: 'smooth' });
}

function closeListenStory() {
  if (typeof stopAllAudio === 'function') stopAllAudio();
  listenCurrentStory = null;
  listenAnswers = {};
  document.getElementById('listen-story-detail').style.display = 'none';
  document.getElementById('listen-story-list').style.display = '';
  renderListenView();
}


// ─── PROVERBS & EXPRESSIONS ──────────────────────────────────────────────────
let _proverbCatFilter = 'All';
let _proverbOrder = null; // shuffle state

function getProverbProgress() {
  try { return JSON.parse(localStorage.getItem('la_proverb_progress') || '{}'); } catch(e) { return {}; }
}
function saveProverbProgress(p) {
  _lsSet('la_proverb_progress', JSON.stringify(p));
}
function markProverbKnown(id, known) {
  const p = getProverbProgress();
  if (known) p[id] = { known: true, ts: Date.now() };
  else delete p[id];
  saveProverbProgress(p);
}

function renderProverbsView() {
  if (typeof PROVERBS === 'undefined') return;
  const filterEl = document.getElementById('proverb-cat-filters');
  const cats = ['All', ...PROVERB_CATEGORIES];
  filterEl.innerHTML = cats.map(c =>
    `<button class="filter-chip${c === _proverbCatFilter ? ' active' : ''}" onclick="setProverbCat('${c}')">${c}</button>`
  ).join('');

  const list = _proverbOrder
    ? _proverbOrder.map(i => PROVERBS[i])
    : PROVERBS;
  const filtered = _proverbCatFilter === 'All'
    ? list
    : list.filter(p => p.cat === _proverbCatFilter);
  const progress = getProverbProgress();
  const known = filtered.filter(p => progress[p.id]).length;

  const listEl = document.getElementById('proverbs-main-list');
  listEl.innerHTML = `
    <div style="color:var(--muted);font-size:0.85rem;margin-bottom:10px">
      ${filtered.length} ${_proverbCatFilter === 'All' ? 'proverbs' : _proverbCatFilter.toLowerCase()} ·
      <span style="color:var(--easy)">${known} known</span>
    </div>
  ` + filtered.map(p => {
    const isKnown = !!progress[p.id];
    return `
    <div style="background:var(--card);border-radius:12px;padding:14px 16px;margin-bottom:10px;border-left:4px solid ${isKnown ? 'var(--easy)' : 'var(--accent)'}">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px">
        <div style="flex:1">
          <div style="direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif;font-size:1.25rem;font-weight:700;color:var(--accent2);margin-bottom:4px">${p.ar}</div>
          <div style="font-size:0.9rem;color:var(--green);font-style:italic;margin-bottom:6px">${p.tr}</div>
          <div style="font-size:0.85rem;color:var(--muted);margin-bottom:4px"><strong>Literal:</strong> ${p.lit}</div>
          <div style="font-size:0.95rem;margin-bottom:4px"><strong>Means:</strong> ${p.en}</div>
          <div style="font-size:0.8rem;color:var(--muted)"><strong>When:</strong> ${p.use}</div>
        </div>
        <div style="display:flex;flex-direction:column;gap:6px;align-items:flex-end">
          <span style="background:var(--bg);border-radius:10px;padding:2px 8px;font-size:0.7rem;color:var(--muted)">${p.cat}</span>
          <button class="btn btn-outline" style="font-size:0.72rem;padding:4px 8px" onclick="speak('${p.ar.replace(/'/g, "\\'")}', false)">🔊</button>
          <button class="btn btn-outline" style="font-size:0.72rem;padding:4px 8px;${isKnown ? 'background:var(--easy);color:#fff;border-color:var(--easy)' : ''}" onclick="toggleProverbKnown('${p.id}')">${isKnown ? '✓ Known' : 'Mark known'}</button>
        </div>
      </div>
    </div>`;
  }).join('');
}

function setProverbCat(c) {
  _proverbCatFilter = c;
  renderProverbsView();
}

function shuffleProverbs() {
  _proverbOrder = shuffle([...Array(PROVERBS.length).keys()]);
  renderProverbsView();
}

function toggleProverbKnown(id) {
  const p = getProverbProgress();
  markProverbKnown(id, !p[id]);
  renderProverbsView();
}

// Drill: show literal + meaning, ask user to recall the Arabic, then reveal
let _pdQueue = [], _pdIdx = 0, _pdRevealed = false, _pdCorrect = 0;

function startProverbDrill() {
  const progress = getProverbProgress();
  const pool = _proverbCatFilter === 'All' ? PROVERBS : PROVERBS.filter(p => p.cat === _proverbCatFilter);
  // Drill: prioritize unknown
  const unknown = pool.filter(p => !progress[p.id]);
  const known = pool.filter(p => progress[p.id]);
  _pdQueue = shuffle([...unknown, ...known]).slice(0, Math.min(20, pool.length));
  _pdIdx = 0; _pdCorrect = 0; _pdRevealed = false;
  document.getElementById('proverb-drill-overlay').style.display = '';
  renderProverbDrillCard();
}

function closeProverbDrill() {
  document.getElementById('proverb-drill-overlay').style.display = 'none';
  renderProverbsView();
}

function renderProverbDrillCard() {
  if (_pdIdx >= _pdQueue.length) {
    document.getElementById('pd-card').innerHTML = `
      <div style="text-align:center;padding:30px 0">
        <div style="font-size:2.4rem;margin-bottom:10px">🎉</div>
        <div style="font-size:1.3rem;font-weight:700;margin-bottom:6px">Drill Complete!</div>
        <div style="color:var(--muted);margin-bottom:14px">${_pdCorrect}/${_pdQueue.length} marked as known</div>
      </div>`;
    document.getElementById('pd-controls').innerHTML =
      `<button class="btn" onclick="startProverbDrill()">🔄 Again</button>
       <button class="btn btn-outline" onclick="closeProverbDrill()">Done</button>`;
    document.getElementById('pd-progress').textContent = '';
    return;
  }
  const p = _pdQueue[_pdIdx];
  document.getElementById('pd-progress').textContent = `${_pdIdx + 1} / ${_pdQueue.length}`;
  if (!_pdRevealed) {
    document.getElementById('pd-card').innerHTML = `
      <div style="font-size:0.78rem;color:var(--muted);margin-bottom:8px;text-transform:uppercase;letter-spacing:0.5px">${p.cat} · ${p.use}</div>
      <div style="font-size:1.05rem;margin-bottom:6px"><strong>Means:</strong> ${p.en}</div>
      <div style="font-size:0.85rem;color:var(--muted);margin-bottom:14px"><strong>Literal:</strong> ${p.lit}</div>
      <div style="text-align:center;padding:20px;background:var(--bg);border-radius:10px;color:var(--muted);font-style:italic">
        Try to recall the Arabic proverb, then reveal
      </div>`;
    document.getElementById('pd-controls').innerHTML =
      `<button class="btn" onclick="revealProverbDrill()">Reveal answer</button>`;
  } else {
    document.getElementById('pd-card').innerHTML = `
      <div style="font-size:0.78rem;color:var(--muted);margin-bottom:8px;text-transform:uppercase;letter-spacing:0.5px">${p.cat}</div>
      <div style="direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif;font-size:1.6rem;font-weight:700;color:var(--accent2);margin-bottom:8px;text-align:center">${p.ar}</div>
      <div style="font-size:1rem;color:var(--green);font-style:italic;margin-bottom:10px;text-align:center">${p.tr}</div>
      <div style="font-size:0.9rem;margin-bottom:4px"><strong>Means:</strong> ${p.en}</div>
      <div style="font-size:0.85rem;color:var(--muted);margin-bottom:4px"><strong>Literal:</strong> ${p.lit}</div>
      <div style="font-size:0.82rem;color:var(--muted)"><strong>When:</strong> ${p.use}</div>
      <div style="text-align:center;margin-top:12px"><button class="btn btn-outline" style="font-size:0.8rem" onclick="speak('${p.ar.replace(/'/g, "\\'")}', false)">🔊 Listen</button></div>`;
    document.getElementById('pd-controls').innerHTML = `
      <button class="btn" style="background:var(--hard);color:#fff" onclick="rateProverbDrill(false)">Didn't know</button>
      <button class="btn" style="background:var(--easy);color:#fff" onclick="rateProverbDrill(true)">Knew it ✓</button>`;
  }
}

function revealProverbDrill() {
  _pdRevealed = true;
  renderProverbDrillCard();
}

function rateProverbDrill(known) {
  const p = _pdQueue[_pdIdx];
  if (known) {
    markProverbKnown(p.id, true);
    _pdCorrect++;
  }
  _pdIdx++;
  _pdRevealed = false;
  renderProverbDrillCard();
}

// ─── NUMBER TRAINER ──────────────────────────────────────────────────────────
// Lebanese number generator — supports 1-9999
const NUM_ONES = ['','wahad','tnayn','tlete','arba3a','khamse','sitte','sab3a','tmene','tis3a'];
const NUM_TENS = ['','3ashra','3ishrin','tletin','arb3in','khamsin','sittin','sab3in','tmanin','tis3in'];
const NUM_TEENS = ['3ashra','7da3sh','tna3sh','tlatta3sh','arba3ta3sh','khamsta3sh','sitta3sh','saba3ta3sh','tmenta3sh','tisa3ta3sh'];
const NUM_HUNDREDS = ['','miyye','miten','tlatmiyye','arba3miyye','khamsmiyye','sittmiyye','sab3amiyye','tmanmiyye','tis3amiyye'];

function lebNumberWord(n) {
  if (n === 0) return 'sefer';
  if (n < 0 || n > 9999) return String(n);
  const parts = [];
  const thousands = Math.floor(n / 1000);
  const hundreds = Math.floor((n % 1000) / 100);
  const remainder = n % 100;

  if (thousands > 0) {
    if (thousands === 1) parts.push('alf');
    else if (thousands === 2) parts.push('alfayn');
    else if (thousands <= 10) parts.push(NUM_ONES[thousands] + ' alaf');
    else parts.push(thousands + ' alf');
  }
  if (hundreds > 0) parts.push(NUM_HUNDREDS[hundreds]);
  if (remainder > 0) {
    if (remainder < 10) parts.push(NUM_ONES[remainder]);
    else if (remainder < 20) parts.push(NUM_TEENS[remainder - 10]);
    else {
      const t = Math.floor(remainder / 10);
      const o = remainder % 10;
      if (o === 0) parts.push(NUM_TENS[t]);
      else parts.push(NUM_ONES[o] + ' w-' + NUM_TENS[t]);
    }
  }
  return parts.join(' w-').replace(/^w-/, '').trim();
}

// Arabic word forms (rough — dialect-friendly)
const NUM_AR_ONES = ['','واحد','تنين','تلاتة','أربعة','خمسة','ستة','سبعة','تمنية','تسعة'];
const NUM_AR_TENS = ['','عشرة','عشرين','تلاتين','أربعين','خمسين','ستين','سبعين','تمانين','تسعين'];
const NUM_AR_TEENS = ['عشرة','حداعش','تنعش','تلتعش','أربعتعش','خمستعش','ستعش','سبعتعش','تمنتعش','تسعتعش'];
const NUM_AR_HUNDREDS = ['','مية','ميتين','تلاتمية','أربعمية','خمسمية','ستمية','سبعمية','تمنمية','تسعمية'];

function lebNumberArabic(n) {
  if (n === 0) return 'صفر';
  if (n < 0 || n > 9999) return String(n);
  const parts = [];
  const thousands = Math.floor(n / 1000);
  const hundreds = Math.floor((n % 1000) / 100);
  const remainder = n % 100;
  if (thousands > 0) {
    if (thousands === 1) parts.push('ألف');
    else if (thousands === 2) parts.push('ألفين');
    else if (thousands <= 10) parts.push(NUM_AR_ONES[thousands] + ' آلاف');
    else parts.push(thousands + ' ألف');
  }
  if (hundreds > 0) parts.push(NUM_AR_HUNDREDS[hundreds]);
  if (remainder > 0) {
    if (remainder < 10) parts.push(NUM_AR_ONES[remainder]);
    else if (remainder < 20) parts.push(NUM_AR_TEENS[remainder - 10]);
    else {
      const t = Math.floor(remainder / 10);
      const o = remainder % 10;
      if (o === 0) parts.push(NUM_AR_TENS[t]);
      else parts.push(NUM_AR_ONES[o] + ' و' + NUM_AR_TENS[t]);
    }
  }
  return parts.join(' و');
}

let _numMode = 'digit_to_word'; // digit_to_word | word_to_digit | audio_to_word
let _numRange = '1_99'; // 1_20, 1_99, 1_999, 1_9999, time, money
let _numCurrent = null;
let _numRevealed = false;
let _numCorrect = 0, _numTotal = 0;

const NUM_MODES = [
  { id:'digit_to_word', label:'Digit → Word' },
  { id:'word_to_digit', label:'Word → Digit' },
  { id:'audio_to_word', label:'🔊 Audio → Word' },
];
const NUM_RANGES = [
  { id:'1_20', label:'1–20', min:1, max:20 },
  { id:'1_99', label:'1–99', min:1, max:99 },
  { id:'1_999', label:'1–999', min:1, max:999 },
  { id:'1_9999', label:'1–9999', min:1, max:9999 },
  { id:'time', label:'⏰ Time', min:1, max:24, special:'time' },
  { id:'money', label:'💵 Money LBP', min:1000, max:500000, special:'money', step:1000 },
];

function renderNumbersView() {
  const modeEl = document.getElementById('num-mode-pick');
  modeEl.innerHTML = NUM_MODES.map(m =>
    `<button class="filter-chip${m.id === _numMode ? ' active' : ''}" onclick="setNumMode('${m.id}')">${m.label}</button>`
  ).join('');
  const rangeEl = document.getElementById('num-range-pick');
  rangeEl.innerHTML = NUM_RANGES.map(r =>
    `<button class="filter-chip${r.id === _numRange ? ' active' : ''}" onclick="setNumRange('${r.id}')">${r.label}</button>`
  ).join('');
  if (!_numCurrent) nextNumber();
  else renderNumberCard();
}

function setNumMode(m) { _numMode = m; nextNumber(); }
function setNumRange(r) { _numRange = r; nextNumber(); }

function nextNumber() {
  const range = NUM_RANGES.find(r => r.id === _numRange);
  let n;
  if (range.special === 'money') {
    const steps = Math.floor((range.max - range.min) / range.step) + 1;
    n = range.min + Math.floor(Math.random() * steps) * range.step;
  } else {
    n = range.min + Math.floor(Math.random() * (range.max - range.min + 1));
  }
  _numCurrent = { n, range };
  _numRevealed = false;
  renderNumberCard();
}

function renderNumberCard() {
  if (!_numCurrent) return;
  const { n, range } = _numCurrent;
  const ar = lebNumberArabic(n);
  const tr = lebNumberWord(n);
  const numStr = range.special === 'time'
    ? `${n}:00`
    : range.special === 'money'
    ? n.toLocaleString() + ' L.L.'
    : String(n);

  const card = document.getElementById('num-card');
  if (_numMode === 'digit_to_word') {
    card.innerHTML = `
      <div style="font-size:0.78rem;color:var(--muted);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:8px">Read this aloud in Lebanese</div>
      <div style="font-size:3.4rem;font-weight:700;color:var(--accent);margin:14px 0">${numStr}</div>
      ${_numRevealed ? `
        <div style="direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif;font-size:1.6rem;font-weight:700;color:var(--accent2);margin:14px 0">${ar}</div>
        <div style="font-size:1rem;color:var(--green);font-style:italic">${tr}</div>
      ` : `<div style="color:var(--muted);font-size:0.9rem;margin-top:14px">Tap reveal when ready</div>`}`;
  } else if (_numMode === 'word_to_digit') {
    card.innerHTML = `
      <div style="font-size:0.78rem;color:var(--muted);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:8px">Write this number in digits</div>
      <div style="direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif;font-size:1.8rem;font-weight:700;color:var(--accent2);margin:14px 0">${ar}</div>
      <div style="font-size:1rem;color:var(--green);font-style:italic;margin-bottom:14px">${tr}</div>
      ${_numRevealed ? `<div style="font-size:3rem;font-weight:700;color:var(--accent)">${numStr}</div>` : ''}`;
  } else if (_numMode === 'audio_to_word') {
    card.innerHTML = `
      <div style="font-size:0.78rem;color:var(--muted);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:8px">Listen and write in digits</div>
      <button class="btn" style="margin:14px 0;font-size:1.2rem;padding:14px 22px" onclick="speak('${ar.replace(/'/g, "\\'")}', false)">🔊 Play Number</button>
      <div style="font-size:0.85rem;color:var(--muted);margin-top:8px">Tap to replay any time</div>
      ${_numRevealed ? `
        <div style="font-size:3rem;font-weight:700;color:var(--accent);margin-top:14px">${numStr}</div>
        <div style="direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif;font-size:1.4rem;color:var(--accent2);margin-top:8px">${ar}</div>
        <div style="font-size:0.95rem;color:var(--green);font-style:italic">${tr}</div>
      ` : ''}`;
  }

  const ctrl = document.getElementById('num-controls');
  if (_numRevealed) {
    ctrl.innerHTML = `
      <button class="btn" style="background:var(--hard);color:#fff" onclick="gradeNumber(false)">Got it wrong</button>
      <button class="btn" style="background:var(--easy);color:#fff" onclick="gradeNumber(true)">Got it right</button>`;
  } else {
    ctrl.innerHTML = `
      <button class="btn" onclick="revealNumber()">Reveal</button>
      <button class="btn btn-outline" onclick="speak('${ar.replace(/'/g, "\\'")}', false)">🔊 Listen</button>
      <button class="btn btn-outline" onclick="nextNumber()">Skip ⏭</button>`;
  }

  document.getElementById('num-stats').textContent =
    _numTotal > 0 ? `${_numCorrect} / ${_numTotal} correct (${Math.round(100*_numCorrect/_numTotal)}%)` : 'Start practicing!';
}

function revealNumber() { _numRevealed = true; renderNumberCard(); }
function gradeNumber(correct) {
  _numTotal++;
  if (correct) _numCorrect++;
  nextNumber();
}

// ─── AUDIO CRAM MODE ─────────────────────────────────────────────────────────
// Eyes-free vocab: speak English, pause, speak Arabic. Uses due cards.
let _acRunning = false;
let _acTimer = null;
let _acQueue = [];
let _acIdx = 0;
let _acGap = 2500; // ms between English and Arabic
let _acInterval = 1500; // ms between words

function startAudioCram() {
  const due = getDueCards();
  const newCards = getNewCards(20);
  _acQueue = shuffle([...due, ...newCards]).slice(0, 50);
  if (_acQueue.length === 0) {
    alert('No cards available. Add some vocab first!');
    return;
  }
  _acIdx = 0;
  _acRunning = true;
  document.getElementById('audio-cram-overlay').style.display = '';
  renderAudioCram();
  scheduleAudioCram();
}

function stopAudioCram() {
  _acRunning = false;
  if (_acTimer) { clearTimeout(_acTimer); _acTimer = null; }
  document.getElementById('audio-cram-overlay').style.display = 'none';
  if ('speechSynthesis' in window) speechSynthesis.cancel();
}

function scheduleAudioCram() {
  if (!_acRunning) return;
  if (_acIdx >= _acQueue.length) {
    document.getElementById('ac-status').textContent = '✓ Done — restart or close';
    return;
  }
  const card = _acQueue[_acIdx];
  const word = VOCAB_BY_ID[card.id] || VOCAB.find(v => v.id === card.id);
  if (!word) { _acIdx++; scheduleAudioCram(); return; }

  renderAudioCram();
  // Speak English
  if ('speechSynthesis' in window) {
    const u1 = new SpeechSynthesisUtterance(word.en);
    u1.lang = 'en-US';
    u1.rate = 0.95;
    speechSynthesis.speak(u1);
  }
  _acTimer = setTimeout(() => {
    if (!_acRunning) return;
    speak(word.ar, false);
    _acTimer = setTimeout(() => {
      if (!_acRunning) return;
      _acIdx++;
      scheduleAudioCram();
    }, _acInterval + 800);
  }, _acGap);
}

function renderAudioCram() {
  const card = _acQueue[_acIdx];
  if (!card) return;
  const word = VOCAB_BY_ID[card.id] || VOCAB.find(v => v.id === card.id);
  if (!word) return;
  document.getElementById('ac-current').innerHTML = `
    <div style="font-size:0.9rem;color:var(--muted);margin-bottom:6px">${_acIdx + 1} / ${_acQueue.length}</div>
    <div style="font-size:1.05rem;color:var(--text);margin-bottom:8px"><strong>${word.en}</strong></div>
    <div style="direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif;font-size:2rem;color:var(--accent2);margin-bottom:6px">${word.ar}</div>
    <div style="color:var(--green);font-style:italic">${word.tr}</div>
    <div style="color:var(--muted);font-size:0.8rem;margin-top:6px">${word.cat}</div>`;
  document.getElementById('ac-status').textContent = _acRunning ? '🔊 Playing...' : 'Paused';
}

function adjustAudioCramGap(delta) {
  _acGap = Math.max(500, Math.min(8000, _acGap + delta));
  document.getElementById('ac-gap-display').textContent = (_acGap / 1000).toFixed(1) + 's';
}

// ─── PROVERB OF THE DAY ──────────────────────────────────────────────────────
function renderProverbOfDay() {
  const el = document.getElementById('proverb-of-day');
  if (!el || typeof PROVERBS === 'undefined' || PROVERBS.length === 0) return;
  // Deterministic: index by day-of-year
  const today = new Date();
  const start = new Date(today.getFullYear(), 0, 0);
  const dayOfYear = Math.floor((today - start) / 86400000);
  const p = PROVERBS[dayOfYear % PROVERBS.length];
  el.innerHTML = `
    <div style="background:linear-gradient(135deg,var(--card),var(--card2,var(--card)));border-left:4px solid var(--accent2);border-radius:10px;padding:12px 16px;cursor:pointer" onclick="showView('proverbs')">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">
        <div style="flex:1">
          <div style="font-size:0.7rem;color:var(--muted);text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px">📜 Proverb of the Day · ${p.cat}</div>
          <div style="direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif;font-size:1.15rem;font-weight:700;color:var(--accent2);margin-bottom:2px">${p.ar}</div>
          <div style="font-size:0.82rem;color:var(--green);font-style:italic;margin-bottom:4px">${p.tr}</div>
          <div style="font-size:0.85rem;color:var(--text)">${p.en}</div>
        </div>
        <button class="btn btn-outline" style="font-size:0.72rem;padding:4px 10px;flex-shrink:0" onclick="event.stopPropagation();speak('${p.ar.replace(/'/g, "\\'")}', false)">🔊</button>
      </div>
    </div>`;
}

// ─── SENTENCE CLOZE FROM CONVERSATIONS ───────────────────────────────────────
let _scQueue = [], _scIdx = 0, _scAnswer = '', _scCorrect = 0, _scTotal = 0;

function buildClozeQueue() {
  const out = [];
  CONVERSATIONS.forEach(c => {
    c.lines.forEach(line => {
      const words = line.ar.split(/\s+/).filter(w => w.length > 1);
      if (words.length < 3) return;
      // Pick a content word (not first/last)
      const idx = 1 + Math.floor(Math.random() * (words.length - 2));
      const blanked = words[idx];
      const trWords = line.tr.split(/\s+/);
      out.push({
        sentence: words.map((w, i) => i === idx ? '____' : w).join(' '),
        full: line.ar,
        tr: line.tr,
        en: line.en,
        answer: blanked,
        convoTitle: c.title,
        emoji: c.emoji,
      });
    });
  });
  return shuffle(out);
}

function startClozeDrill() {
  _scQueue = buildClozeQueue().slice(0, 30);
  _scIdx = 0; _scCorrect = 0; _scTotal = 0;
  document.getElementById('cloze-overlay').style.display = '';
  renderClozeCard();
}

function closeClozeDrill() {
  document.getElementById('cloze-overlay').style.display = 'none';
}

function renderClozeCard() {
  const card = document.getElementById('cloze-card');
  const ctrl = document.getElementById('cloze-controls');
  const prog = document.getElementById('cloze-progress');
  if (_scIdx >= _scQueue.length) {
    card.innerHTML = `
      <div style="text-align:center;padding:30px 0">
        <div style="font-size:2.4rem;margin-bottom:10px">🎉</div>
        <div style="font-size:1.3rem;font-weight:700;margin-bottom:6px">Cloze drill complete!</div>
        <div style="color:var(--muted);margin-bottom:14px">${_scCorrect} / ${_scTotal} correct</div>
      </div>`;
    ctrl.innerHTML = `<button class="btn" onclick="startClozeDrill()">🔄 Again</button>
                      <button class="btn btn-outline" onclick="closeClozeDrill()">Done</button>`;
    prog.textContent = '';
    return;
  }
  const q = _scQueue[_scIdx];
  prog.textContent = `${_scIdx + 1} / ${_scQueue.length}`;
  card.innerHTML = `
    <div style="font-size:0.8rem;color:var(--muted);margin-bottom:10px">${q.emoji} ${q.convoTitle}</div>
    <div style="direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif;font-size:1.5rem;line-height:1.6;margin-bottom:10px;color:var(--text)">${q.sentence}</div>
    <div style="font-size:0.9rem;color:var(--muted);font-style:italic;margin-bottom:14px">${q.en}</div>
    <input id="cloze-input" type="text" placeholder="Fill the blank (Arabic)" style="width:100%;padding:10px 14px;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--text);font-size:1.05rem;direction:rtl;font-family:'Segoe UI','Noto Naskh Arabic',serif;box-sizing:border-box" onkeydown="if(event.key==='Enter')submitCloze()">
    <div id="cloze-feedback" style="margin-top:10px;font-size:0.9rem"></div>`;
  ctrl.innerHTML = `
    <button class="btn" onclick="submitCloze()">Check</button>
    <button class="btn btn-outline" onclick="skipCloze()">Show answer</button>
    <button class="btn btn-outline" onclick="speak('${q.full.replace(/'/g, "\\'")}', false)">🔊 Hear sentence</button>`;
  setTimeout(() => document.getElementById('cloze-input')?.focus(), 50);
}

function submitCloze() {
  const q = _scQueue[_scIdx];
  const input = document.getElementById('cloze-input').value.trim();
  const fb = document.getElementById('cloze-feedback');
  _scTotal++;
  const norm = s => s.replace(/[ًٌٍَُِّْ]/g, '').replace(/[ـ]/g, '').trim();
  if (norm(input) === norm(q.answer)) {
    _scCorrect++;
    fb.innerHTML = `<div style="color:var(--easy)">✓ Correct! ${q.answer}</div>`;
  } else {
    fb.innerHTML = `<div style="color:var(--hard)">✗ ${input || '(blank)'} → answer: <strong>${q.answer}</strong></div><div style="font-size:0.82rem;color:var(--muted);margin-top:4px">${q.tr}</div>`;
  }
  document.getElementById('cloze-controls').innerHTML =
    `<button class="btn" onclick="nextCloze()">Next →</button>
     <button class="btn btn-outline" onclick="speak('${q.full.replace(/'/g, "\\'")}', false)">🔊</button>`;
}

function skipCloze() {
  const q = _scQueue[_scIdx];
  _scTotal++;
  document.getElementById('cloze-feedback').innerHTML =
    `<div style="color:var(--muted)">Answer: <strong style="color:var(--accent2)">${q.answer}</strong></div><div style="font-size:0.82rem;color:var(--muted);margin-top:4px">${q.tr}</div>`;
  document.getElementById('cloze-controls').innerHTML =
    `<button class="btn" onclick="nextCloze()">Next →</button>`;
}

function nextCloze() {
  _scIdx++;
  renderClozeCard();
}

// Pronunciation recorder already exists in word modal (toggleRecording / playRecording)

// ─── PRONOUN SUFFIX TRAINER ────────────────────────────────────────────────
let _sfxSetIdx = 0;
let _sfxMode = 'chart';
let _sfxDrill = { queue:[], idx:0, correct:0, wrong:0, picked:null };

function openSuffixTrainer() {
  const overlay = document.getElementById('suffix-overlay');
  if (!overlay) return;
  overlay.style.display = 'block';
  _sfxMode = 'chart';
  _sfxSetIdx = 0;
  renderSuffixSetPicker();
  renderSuffixContent();
}
function closeSuffixTrainer() {
  document.getElementById('suffix-overlay').style.display = 'none';
}
function setSuffixMode(m) {
  _sfxMode = m;
  document.getElementById('sfx-mode-chart').classList.toggle('active', m==='chart');
  document.getElementById('sfx-mode-drill').classList.toggle('active', m==='drill');
  if (m === 'drill') buildSuffixDrillQueue();
  renderSuffixContent();
}
function pickSuffixSet(i) {
  _sfxSetIdx = i;
  renderSuffixSetPicker();
  if (_sfxMode === 'drill') buildSuffixDrillQueue();
  renderSuffixContent();
}
function renderSuffixSetPicker() {
  const wrap = document.getElementById('sfx-set-pick');
  if (!wrap) return;
  wrap.innerHTML = PRONOUN_SUFFIX_SETS.map((s,i) =>
    `<button class="cat-filter ${i===_sfxSetIdx?'active':''}" onclick="pickSuffixSet(${i})">${s.base_tr} <span style="opacity:.7">(${s.base_en})</span></button>`
  ).join('');
}
function renderSuffixContent() {
  const c = document.getElementById('sfx-content');
  if (!c) return;
  if (_sfxMode === 'chart') c.innerHTML = renderSuffixChart();
  else c.innerHTML = renderSuffixDrillCard();
}
function renderSuffixChart() {
  const s = PRONOUN_SUFFIX_SETS[_sfxSetIdx];
  let html = `<div style="margin-bottom:10px;font-size:0.88rem;color:var(--muted)">${s.cat}</div>`;
  html += `<div style="font-size:1.4rem;text-align:center;margin-bottom:10px;font-weight:700">${s.base_ar} <span style="color:var(--muted);font-size:1rem">${s.base_tr}</span> · <span style="font-style:italic;color:var(--muted);font-size:0.95rem">${s.base_en}</span></div>`;
  html += `<table style="width:100%;border-collapse:collapse;font-size:0.95rem">
    <thead><tr style="border-bottom:1px solid var(--border)"><th style="text-align:left;padding:8px">Pronoun</th><th style="text-align:right;padding:8px;direction:rtl">Arabic</th><th style="text-align:left;padding:8px">Translit</th><th style="text-align:left;padding:8px">English</th></tr></thead><tbody>`;
  s.forms.forEach((f,i) => {
    const lab = PRONOUN_LABELS.find(p => p.code === f.code) || {};
    html += `<tr style="border-bottom:1px solid var(--border)"><td style="padding:8px"><span style="color:var(--muted);font-size:0.82rem">${lab.en||f.code}</span></td><td style="padding:8px;text-align:right;direction:rtl;font-size:1.15rem;font-weight:600">${f.ar}</td><td style="padding:8px;font-family:monospace">${f.tr}</td><td style="padding:8px;color:var(--muted)">${f.en}</td></tr>`;
  });
  html += '</tbody></table>';
  html += `<div style="margin-top:14px;font-size:0.8rem;color:var(--muted);text-align:center">Tip: Click "Drill" above to test yourself.</div>`;
  return html;
}
function buildSuffixDrillQueue() {
  const s = PRONOUN_SUFFIX_SETS[_sfxSetIdx];
  const items = s.forms.map(f => ({ set:s, form:f })).sort(() => Math.random() - 0.5);
  _sfxDrill = { queue: items, idx: 0, correct: 0, wrong: 0, picked: null };
}
function renderSuffixDrillCard() {
  if (!_sfxDrill.queue.length) buildSuffixDrillQueue();
  if (_sfxDrill.idx >= _sfxDrill.queue.length) {
    return `<div style="text-align:center;padding:30px">
      <div style="font-size:1.4rem;margin-bottom:10px">🎉 Done!</div>
      <div style="margin-bottom:14px">Score: <b>${_sfxDrill.correct}</b> / ${_sfxDrill.queue.length}</div>
      <button class="btn btn-primary" onclick="buildSuffixDrillQueue();renderSuffixContent()">Restart</button>
    </div>`;
  }
  const it = _sfxDrill.queue[_sfxDrill.idx];
  const correctAr = it.form.ar;
  // 4 choices: correct + 3 distractors from same set
  const others = it.set.forms.filter(f => f.ar !== correctAr).sort(() => Math.random() - 0.5).slice(0, 3);
  const choices = [...others, it.form].sort(() => Math.random() - 0.5);
  const lab = PRONOUN_LABELS.find(p => p.code === it.form.code) || {};
  const picked = _sfxDrill.picked;
  const correctLabel = it.form.en;
  let html = `<div style="text-align:center;color:var(--muted);font-size:0.8rem;margin-bottom:8px">${_sfxDrill.idx+1} / ${_sfxDrill.queue.length} · ✅ ${_sfxDrill.correct} ❌ ${_sfxDrill.wrong}</div>`;
  html += `<div style="text-align:center;font-size:1rem;color:var(--muted);margin-bottom:6px">Pick the form for:</div>`;
  html += `<div style="text-align:center;font-size:1.6rem;font-weight:700;margin-bottom:18px">${correctLabel}<br><span style="font-size:0.95rem;color:var(--muted);font-weight:400">(stem: ${it.set.base_tr} = ${it.set.base_en})</span></div>`;
  html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;max-width:500px;margin:0 auto">';
  choices.forEach(ch => {
    let bg = 'var(--card)';
    let bd = '1px solid var(--border)';
    if (picked) {
      if (ch.ar === correctAr) bg = 'rgba(34,197,94,.15)', bd = '1px solid #22c55e';
      else if (ch.ar === picked) bg = 'rgba(239,68,68,.15)', bd = '1px solid #ef4444';
    }
    html += `<button onclick="pickSuffixAnswer('${ch.ar.replace(/'/g,"\\'")}')" style="background:${bg};border:${bd};border-radius:10px;padding:14px;cursor:pointer;direction:rtl;font-size:1.3rem;font-weight:600">${ch.ar}<div style="font-size:0.78rem;font-family:monospace;color:var(--muted);margin-top:4px;direction:ltr">${ch.tr}</div></button>`;
  });
  html += '</div>';
  if (picked) {
    html += `<div style="text-align:center;margin-top:18px"><button class="btn btn-primary" onclick="nextSuffixDrill()">Next →</button></div>`;
  }
  return html;
}
function pickSuffixAnswer(ar) {
  if (_sfxDrill.picked) return;
  _sfxDrill.picked = ar;
  const it = _sfxDrill.queue[_sfxDrill.idx];
  var correct = ar === it.form.ar;
  if (correct) { _sfxDrill.correct++; recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10); }
  else _sfxDrill.wrong++;
  renderSuffixContent();
  showToast && showToast(correct ? '✓ Correct!' : '✗ Try again');
}
function nextSuffixDrill() {
  _sfxDrill.idx++;
  _sfxDrill.picked = null;
  renderSuffixContent();
}

// ─── QUESTION WORDS ────────────────────────────────────────────────────────
let _qwMode = 'list';
let _qwDrill = { queue:[], idx:0, correct:0, wrong:0, picked:null };

function openQuestionWords() {
  const o = document.getElementById('qw-overlay');
  if (!o) return;
  o.style.display = 'block';
  _qwMode = 'list';
  renderQwContent();
}
function closeQuestionWords() { document.getElementById('qw-overlay').style.display = 'none'; }
function setQwMode(m) {
  _qwMode = m;
  document.getElementById('qw-mode-list').classList.toggle('active', m==='list');
  document.getElementById('qw-mode-drill').classList.toggle('active', m==='drill');
  if (m === 'drill') buildQwDrillQueue();
  renderQwContent();
}
function renderQwContent() {
  const c = document.getElementById('qw-content');
  if (_qwMode === 'list') c.innerHTML = renderQwList();
  else c.innerHTML = renderQwDrillCard();
}
function renderQwList() {
  let html = `<div style="font-size:0.85rem;color:var(--muted);margin-bottom:10px">Lebanese question words with usage notes and example sentences. Tap "Drill" to test yourself.</div>`;
  QUESTION_WORDS.forEach(q => {
    html += `<div style="border-bottom:1px solid var(--border);padding:14px 0">
      <div style="display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:6px">
        <span style="font-size:1.5rem;font-weight:700;direction:rtl">${q.ar}</span>
        <span style="font-family:monospace;color:var(--muted)">${q.tr}</span>
        <span style="color:var(--accent);font-weight:600">= ${q.en}</span>
      </div>
      <div style="font-size:0.83rem;color:var(--muted);margin-bottom:8px;font-style:italic">${q.notes}</div>
      <div style="background:var(--bg);border-radius:8px;padding:8px">`;
    q.examples.forEach(ex => {
      html += `<div style="padding:6px 0;border-bottom:1px dashed var(--border)">
        <div style="text-align:right;direction:rtl;font-size:1.05rem">${ex.ar}</div>
        <div style="font-family:monospace;font-size:0.85rem;color:var(--muted)">${ex.tr}</div>
        <div style="font-size:0.85rem">${ex.en}</div>
      </div>`;
    });
    html += `</div></div>`;
  });
  return html;
}
function buildQwDrillQueue() {
  const items = [];
  QUESTION_WORDS.forEach(q => {
    q.examples.forEach(ex => items.push({ q, ex }));
  });
  _qwDrill = { queue: items.sort(() => Math.random() - 0.5).slice(0, 16), idx:0, correct:0, wrong:0, picked:null };
}
function renderQwDrillCard() {
  if (!_qwDrill.queue.length) buildQwDrillQueue();
  if (_qwDrill.idx >= _qwDrill.queue.length) {
    return `<div style="text-align:center;padding:30px">
      <div style="font-size:1.4rem;margin-bottom:10px">🎉 Done!</div>
      <div style="margin-bottom:14px">Score: <b>${_qwDrill.correct}</b> / ${_qwDrill.queue.length}</div>
      <button class="btn btn-primary" onclick="buildQwDrillQueue();renderQwContent()">Restart</button>
    </div>`;
  }
  const it = _qwDrill.queue[_qwDrill.idx];
  const others = QUESTION_WORDS.filter(q => q.id !== it.q.id).sort(() => Math.random() - 0.5).slice(0, 3);
  const choices = [...others, it.q].sort(() => Math.random() - 0.5);
  const picked = _qwDrill.picked;
  // Show the example with the question word blanked out
  const blanked = it.ex.tr.replace(new RegExp('\\b' + it.q.tr.replace(/[-\/\\^$*+?.()|[\]{}]/g,'\\$&') + '\\b','i'), '___');
  const blankedAr = it.ex.ar.replace(it.q.ar, '___');
  let html = `<div style="text-align:center;color:var(--muted);font-size:0.8rem;margin-bottom:8px">${_qwDrill.idx+1} / ${_qwDrill.queue.length} · ✅ ${_qwDrill.correct} ❌ ${_qwDrill.wrong}</div>`;
  html += `<div style="text-align:center;font-size:1.05rem;color:var(--muted);margin-bottom:8px">Which word fills the blank?</div>`;
  html += `<div style="background:var(--bg);border-radius:10px;padding:14px;margin-bottom:14px">
    <div style="text-align:right;direction:rtl;font-size:1.4rem">${blankedAr}</div>
    <div style="font-family:monospace;font-size:0.95rem;color:var(--muted);margin-top:4px">${blanked}</div>
    <div style="font-size:0.92rem;margin-top:6px">${it.ex.en}</div>
  </div>`;
  html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">';
  choices.forEach(ch => {
    let bg = 'var(--card)';
    let bd = '1px solid var(--border)';
    if (picked) {
      if (ch.id === it.q.id) bg = 'rgba(34,197,94,.15)', bd = '1px solid #22c55e';
      else if (ch.id === picked) bg = 'rgba(239,68,68,.15)', bd = '1px solid #ef4444';
    }
    html += `<button onclick="pickQwAnswer('${ch.id}')" style="background:${bg};border:${bd};border-radius:10px;padding:12px;cursor:pointer">
      <div style="font-size:1.25rem;font-weight:700;direction:rtl">${ch.ar}</div>
      <div style="font-family:monospace;font-size:0.85rem;color:var(--muted)">${ch.tr}</div>
      <div style="font-size:0.82rem;margin-top:4px">${ch.en}</div>
    </button>`;
  });
  html += '</div>';
  if (picked) {
    html += `<div style="text-align:center;margin-top:18px"><button class="btn btn-primary" onclick="nextQwDrill()">Next →</button></div>`;
  }
  return html;
}
function pickQwAnswer(id) {
  if (_qwDrill.picked) return;
  _qwDrill.picked = id;
  const it = _qwDrill.queue[_qwDrill.idx];
  var correct = id === it.q.id;
  if (correct) { _qwDrill.correct++; recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10); } else _qwDrill.wrong++;
  renderQwContent();
  showToast && showToast(correct ? '✓ Correct!' : '✗ Try again');
}
function nextQwDrill() { _qwDrill.idx++; _qwDrill.picked = null; renderQwContent(); }

// ─── DAILY MIX ─────────────────────────────────────────────────────────────
function startDailyMix() {
  const o = document.getElementById('dmix-overlay');
  if (!o) return;
  o.style.display = 'block';
  renderDailyMix();
}
function closeDailyMix() { document.getElementById('dmix-overlay').style.display = 'none'; }
function renderDailyMix() {
  const c = document.getElementById('dmix-content');
  if (!c) return;
  // Find due flashcards
  const now = Date.now();
  const dueIds = (typeof VOCAB !== 'undefined' ? VOCAB : []).filter(v => {
    const s = (typeof srsData !== 'undefined' && srsData[v.id]) ? srsData[v.id] : null;
    return s && s.due && s.due <= now;
  }).slice(0, 8);
  // Pick a grammar section deterministically by day
  const grammarPick = (typeof GRAMMAR_SECTIONS !== 'undefined' && GRAMMAR_SECTIONS.length)
    ? GRAMMAR_SECTIONS[dayOfYearIdx() % GRAMMAR_SECTIONS.length] : null;
  // Pick a conversation
  const convoPick = (typeof CONVERSATIONS !== 'undefined' && CONVERSATIONS.length)
    ? CONVERSATIONS[dayOfYearIdx() % CONVERSATIONS.length] : null;
  // Pick a listen story
  const listenPick = (typeof LISTEN_STORIES !== 'undefined' && LISTEN_STORIES.length)
    ? LISTEN_STORIES[dayOfYearIdx() % LISTEN_STORIES.length] : null;
  // Proverb of day
  const provPick = (typeof PROVERBS !== 'undefined' && PROVERBS.length)
    ? PROVERBS[dayOfYearIdx() % PROVERBS.length] : null;

  let html = `<div style="margin-bottom:14px;color:var(--muted);font-size:0.9rem">A balanced 15-minute session. Tap any section to dive in.</div>`;

  // Due cards
  html += `<div style="background:var(--card);border-radius:12px;padding:14px;margin-bottom:12px">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
      <div style="font-weight:700">📚 Due flashcards <span style="color:var(--muted);font-weight:400">(${dueIds.length})</span></div>
      ${dueIds.length ? `<button class="btn btn-primary" onclick="closeDailyMix();showView('study');setTimeout(()=>{if(typeof startDueOnlySession==='function')startDueOnlySession();},100)">Review →</button>` : ''}
    </div>
    <div style="font-size:0.85rem;color:var(--muted)">${dueIds.length ? 'Cards waiting for review based on SRS schedule.' : 'No cards due right now — keep going to build your queue.'}</div>
  </div>`;

  // Grammar
  if (grammarPick) {
    html += `<div style="background:var(--card);border-radius:12px;padding:14px;margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
        <div style="font-weight:700">📖 Grammar focus</div>
        <button class="btn btn-outline" onclick="closeDailyMix();showView('grammar');setTimeout(()=>{if(typeof openGrammarSection==='function')openGrammarSection('${grammarPick.id||''}');},120)">Open →</button>
      </div>
      <div style="font-weight:600">${grammarPick.title || grammarPick.id || 'Grammar'}</div>
      <div style="font-size:0.85rem;color:var(--muted);margin-top:4px">${(grammarPick.intro||'').slice(0,160)}${(grammarPick.intro||'').length>160?'…':''}</div>
    </div>`;
  }

  // Conversation
  if (convoPick) {
    html += `<div style="background:var(--card);border-radius:12px;padding:14px;margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
        <div style="font-weight:700">💬 Conversation</div>
        <button class="btn btn-outline" onclick="closeDailyMix();showView('convo');setTimeout(()=>{if(typeof openConversation==='function')openConversation('${convoPick.id||''}');},120)">Open →</button>
      </div>
      <div style="font-weight:600">${convoPick.title || convoPick.id}</div>
      <div style="font-size:0.85rem;color:var(--muted);margin-top:4px">${convoPick.scenario || convoPick.context || ''}</div>
    </div>`;
  }

  // Listen
  if (listenPick) {
    html += `<div style="background:var(--card);border-radius:12px;padding:14px;margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
        <div style="font-weight:700">🎧 Listening</div>
        <button class="btn btn-outline" onclick="closeDailyMix();showView('listen');setTimeout(()=>{if(typeof openListenStory==='function')openListenStory('${listenPick.id||''}');},120)">Open →</button>
      </div>
      <div style="font-weight:600">${listenPick.title || listenPick.id}</div>
      <div style="font-size:0.85rem;color:var(--muted);margin-top:4px">Level: ${listenPick.level || '—'}</div>
    </div>`;
  }

  // Proverb
  if (provPick) {
    html += `<div style="background:var(--card);border-radius:12px;padding:14px;margin-bottom:12px">
      <div style="font-weight:700;margin-bottom:6px">📜 Proverb of the day</div>
      <div style="text-align:right;direction:rtl;font-size:1.2rem;margin-bottom:4px">${provPick.ar}</div>
      <div style="font-family:monospace;font-size:0.86rem;color:var(--muted);margin-bottom:4px">${provPick.tr}</div>
      <div style="font-size:0.92rem">${provPick.en}</div>
    </div>`;
  }

  // Drills
  html += `<div style="background:var(--card);border-radius:12px;padding:14px">
    <div style="font-weight:700;margin-bottom:8px">🧠 Quick drill</div>
    <div style="display:flex;gap:8px;flex-wrap:wrap">
      <button class="btn btn-outline" onclick="closeDailyMix();openSuffixTrainer();setTimeout(()=>setSuffixMode('drill'),60)">🔗 Pronoun Suffixes</button>
      <button class="btn btn-outline" onclick="closeDailyMix();openQuestionWords();setTimeout(()=>setQwMode('drill'),60)">❓ Question Words</button>
      <button class="btn btn-outline" onclick="closeDailyMix();startClozeDrill()">📝 Cloze</button>
    </div>
  </div>`;

  c.innerHTML = html;
}
function dayOfYearIdx() {
  const d = new Date();
  const start = new Date(d.getFullYear(), 0, 0);
  const diff = (d - start) + ((start.getTimezoneOffset() - d.getTimezoneOffset()) * 60 * 1000);
  return Math.floor(diff / (1000 * 60 * 60 * 24));
}

// ─── NEGATION TRAINER ─────────────────────────────────────────────────────
let _negMode = 'list';
let _negDrill = { queue:[], idx:0, correct:0, wrong:0, picked:null };

function openNegationTrainer() {
  document.getElementById('neg-overlay').style.display = 'block';
  _negMode = 'list';
  renderNegContent();
}
function closeNegationTrainer() { document.getElementById('neg-overlay').style.display = 'none'; }
function setNegMode(m) {
  _negMode = m;
  document.getElementById('neg-mode-list').classList.toggle('active', m==='list');
  document.getElementById('neg-mode-drill').classList.toggle('active', m==='drill');
  if (m === 'drill') buildNegDrillQueue();
  renderNegContent();
}
function renderNegContent() {
  const c = document.getElementById('neg-content');
  if (_negMode === 'list') c.innerHTML = renderNegList();
  else c.innerHTML = renderNegDrillCard();
}
function renderNegList() {
  let html = `<div style="font-size:0.85rem;color:var(--muted);margin-bottom:10px">Lebanese negation: <b>ma</b> for verbs (past + present), <b>mish</b> for adjectives + nouns, <b>mish/ma rah</b> for future. "ma 7ada" = nobody, "ma shi" = nothing.</div>`;
  NEGATION_PATTERNS.forEach(p => {
    html += `<div style="border-bottom:1px solid var(--border);padding:14px 0">
      <div style="font-weight:700;margin-bottom:4px">${p.label}</div>
      <div style="font-size:0.83rem;color:var(--muted);margin-bottom:8px;font-style:italic">${p.rule}</div>
      <div style="background:var(--bg);border-radius:8px;padding:8px">`;
    p.examples.forEach(ex => {
      html += `<div style="padding:6px 0;border-bottom:1px dashed var(--border)">
        <div style="text-align:right;direction:rtl;font-size:1.05rem">${ex.ar}</div>
        <div style="font-family:monospace;font-size:0.85rem;color:var(--muted)">${ex.tr}</div>
        <div style="font-size:0.85rem">${ex.en}</div>
      </div>`;
    });
    html += `</div></div>`;
  });
  return html;
}
function buildNegDrillQueue() {
  const items = [];
  NEGATION_PATTERNS.forEach(p => p.examples.forEach(ex => items.push({ p, ex })));
  _negDrill = { queue: items.sort(() => Math.random() - 0.5).slice(0, 16), idx:0, correct:0, wrong:0, picked:null };
}
function renderNegDrillCard() {
  if (!_negDrill.queue.length) buildNegDrillQueue();
  if (_negDrill.idx >= _negDrill.queue.length) {
    return `<div style="text-align:center;padding:30px">
      <div style="font-size:1.4rem;margin-bottom:10px">🎉 Done!</div>
      <div style="margin-bottom:14px">Score: <b>${_negDrill.correct}</b> / ${_negDrill.queue.length}</div>
      <button class="btn btn-primary" onclick="buildNegDrillQueue();renderNegContent()">Restart</button>
    </div>`;
  }
  const it = _negDrill.queue[_negDrill.idx];
  const others = NEGATION_PATTERNS.filter(p => p.id !== it.p.id).sort(() => Math.random() - 0.5).slice(0, 3);
  const choices = [...others, it.p].sort(() => Math.random() - 0.5);
  const picked = _negDrill.picked;
  let html = `<div style="text-align:center;color:var(--muted);font-size:0.8rem;margin-bottom:8px">${_negDrill.idx+1} / ${_negDrill.queue.length} · ✅ ${_negDrill.correct} ❌ ${_negDrill.wrong}</div>`;
  html += `<div style="text-align:center;font-size:1rem;color:var(--muted);margin-bottom:8px">Which negation pattern is this?</div>`;
  html += `<div style="background:var(--bg);border-radius:10px;padding:14px;margin-bottom:14px">
    <div style="text-align:right;direction:rtl;font-size:1.4rem">${it.ex.ar}</div>
    <div style="font-family:monospace;font-size:0.95rem;color:var(--muted);margin-top:4px">${it.ex.tr}</div>
    <div style="font-size:0.92rem;margin-top:6px">${it.ex.en}</div>
  </div>`;
  html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">';
  choices.forEach(ch => {
    let bg = 'var(--card)', bd = '1px solid var(--border)';
    if (picked) {
      if (ch.id === it.p.id) bg='rgba(34,197,94,.15)', bd='1px solid #22c55e';
      else if (ch.id === picked) bg='rgba(239,68,68,.15)', bd='1px solid #ef4444';
    }
    html += `<button onclick="pickNegAnswer('${ch.id}')" style="background:${bg};border:${bd};border-radius:10px;padding:12px;cursor:pointer;text-align:left">
      <div style="font-weight:700">${ch.label}</div>
      <div style="font-size:0.78rem;color:var(--muted);margin-top:4px">${ch.rule}</div>
    </button>`;
  });
  html += '</div>';
  if (picked) html += `<div style="text-align:center;margin-top:18px"><button class="btn btn-primary" onclick="nextNegDrill()">Next →</button></div>`;
  return html;
}
function pickNegAnswer(id) {
  if (_negDrill.picked) return;
  _negDrill.picked = id;
  const it = _negDrill.queue[_negDrill.idx];
  var correct = id === it.p.id;
  if (correct) { _negDrill.correct++; recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10); } else _negDrill.wrong++;
  renderNegContent();
  showToast && showToast(correct ? '✓ Correct!' : '✗ Try again');
}
function nextNegDrill() { _negDrill.idx++; _negDrill.picked = null; renderNegContent(); }

// ─── IMPERATIVES ───────────────────────────────────────────────────────────
let _impMode = 'chart';
let _impDrill = { queue:[], idx:0, correct:0, wrong:0, picked:null };

function openImperatives() { document.getElementById('imp-overlay').style.display = 'block'; _impMode='chart'; renderImpContent(); }
function closeImperatives() { document.getElementById('imp-overlay').style.display = 'none'; }
function setImpMode(m) {
  _impMode = m;
  document.getElementById('imp-mode-chart').classList.toggle('active', m==='chart');
  document.getElementById('imp-mode-drill').classList.toggle('active', m==='drill');
  if (m === 'drill') buildImpDrillQueue();
  renderImpContent();
}
function renderImpContent() {
  const c = document.getElementById('imp-content');
  if (_impMode === 'chart') c.innerHTML = renderImpChart(); else c.innerHTML = renderImpDrillCard();
}
function renderImpChart() {
  let html = `<div style="font-size:0.85rem;color:var(--muted);margin-bottom:10px">Command form for 15 common verbs. Three forms: <b>m</b> (to a male), <b>f</b> (to a female), <b>pl</b> (to a group).</div>`;
  html += `<table style="width:100%;border-collapse:collapse;font-size:0.92rem">
    <thead><tr style="border-bottom:1px solid var(--border)">
      <th style="text-align:left;padding:8px">Meaning</th>
      <th style="text-align:left;padding:8px">→ m</th>
      <th style="text-align:left;padding:8px">→ f</th>
      <th style="text-align:left;padding:8px">→ pl</th>
    </tr></thead><tbody>`;
  IMPERATIVES.forEach(v => {
    html += `<tr style="border-bottom:1px solid var(--border)">
      <td style="padding:8px"><b>${v.en}</b><div style="font-size:0.78rem;color:var(--muted);margin-top:4px">${v.ex||''}</div></td>
      <td style="padding:8px;direction:rtl"><b>${v.m.ar}</b><div style="font-family:monospace;font-size:0.78rem;color:var(--muted);direction:ltr">${v.m.tr}</div></td>
      <td style="padding:8px;direction:rtl"><b>${v.f.ar}</b><div style="font-family:monospace;font-size:0.78rem;color:var(--muted);direction:ltr">${v.f.tr}</div></td>
      <td style="padding:8px;direction:rtl"><b>${v.pl.ar}</b><div style="font-family:monospace;font-size:0.78rem;color:var(--muted);direction:ltr">${v.pl.tr}</div></td>
    </tr>`;
  });
  html += '</tbody></table>';
  return html;
}
function buildImpDrillQueue() {
  const items = [];
  IMPERATIVES.forEach(v => {
    ['m','f','pl'].forEach(g => items.push({ v, g, target: v[g] }));
  });
  _impDrill = { queue: items.sort(() => Math.random() - 0.5).slice(0, 18), idx:0, correct:0, wrong:0, picked:null };
}
function renderImpDrillCard() {
  if (!_impDrill.queue.length) buildImpDrillQueue();
  if (_impDrill.idx >= _impDrill.queue.length) {
    return `<div style="text-align:center;padding:30px">
      <div style="font-size:1.4rem;margin-bottom:10px">🎉 Done!</div>
      <div style="margin-bottom:14px">Score: <b>${_impDrill.correct}</b> / ${_impDrill.queue.length}</div>
      <button class="btn btn-primary" onclick="buildImpDrillQueue();renderImpContent()">Restart</button>
    </div>`;
  }
  const it = _impDrill.queue[_impDrill.idx];
  // 4 choices: correct + 3 distractors (mix of other verbs same gender, or same verb other gender)
  const sameVerbOther = ['m','f','pl'].filter(g => g !== it.g).map(g => it.v[g]);
  const otherVerbs = IMPERATIVES.filter(v => v.id !== it.v.id).sort(() => Math.random() - 0.5).slice(0, 2).map(v => v[it.g]);
  const distractors = [...sameVerbOther, ...otherVerbs].sort(() => Math.random() - 0.5).slice(0,3);
  const choices = [it.target, ...distractors].sort(() => Math.random() - 0.5);
  const picked = _impDrill.picked;
  const genderLabel = { m:'a male', f:'a female', pl:'a group' }[it.g];
  let html = `<div style="text-align:center;color:var(--muted);font-size:0.8rem;margin-bottom:8px">${_impDrill.idx+1} / ${_impDrill.queue.length} · ✅ ${_impDrill.correct} ❌ ${_impDrill.wrong}</div>`;
  html += `<div style="text-align:center;font-size:1rem;color:var(--muted);margin-bottom:8px">Tell ${genderLabel} to:</div>`;
  html += `<div style="text-align:center;font-size:1.6rem;font-weight:700;margin-bottom:18px">${it.v.en}</div>`;
  html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;max-width:500px;margin:0 auto">';
  choices.forEach(ch => {
    let bg = 'var(--card)', bd = '1px solid var(--border)';
    if (picked) {
      if (ch.ar === it.target.ar) bg='rgba(34,197,94,.15)', bd='1px solid #22c55e';
      else if (ch.ar === picked) bg='rgba(239,68,68,.15)', bd='1px solid #ef4444';
    }
    html += `<button onclick="pickImpAnswer('${ch.ar.replace(/'/g,"\\'")}')" style="background:${bg};border:${bd};border-radius:10px;padding:14px;cursor:pointer;direction:rtl;font-size:1.3rem;font-weight:600">${ch.ar}<div style="font-size:0.78rem;font-family:monospace;color:var(--muted);margin-top:4px;direction:ltr">${ch.tr}</div></button>`;
  });
  html += '</div>';
  if (picked) html += `<div style="text-align:center;margin-top:18px"><button class="btn btn-primary" onclick="nextImpDrill()">Next →</button></div>`;
  return html;
}
function pickImpAnswer(ar) {
  if (_impDrill.picked) return;
  _impDrill.picked = ar;
  const it = _impDrill.queue[_impDrill.idx];
  var correct = ar === it.target.ar;
  if (correct) { _impDrill.correct++; recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10); } else _impDrill.wrong++;
  renderImpContent();
  showToast && showToast(correct ? '✓ Correct!' : '✗ Try again');
}
function nextImpDrill() { _impDrill.idx++; _impDrill.picked = null; renderImpContent(); }

// ─── TIME EXPRESSIONS ─────────────────────────────────────────────────────
let _timeCat = 'telling_time';

function openTimeExpr() { document.getElementById('time-overlay').style.display = 'block'; _timeCat='telling_time'; renderTimeContent(); }
function closeTimeExpr() { document.getElementById('time-overlay').style.display = 'none'; }
function setTimeCat(cat) {
  _timeCat = cat;
  ['tcat-tt','tcat-days','tcat-pod','tcat-adv','tcat-mon'].forEach(id => document.getElementById(id).classList.remove('active'));
  const map = { telling_time:'tcat-tt', days_of_week:'tcat-days', parts_of_day:'tcat-pod', time_adverbs:'tcat-adv', months:'tcat-mon' };
  document.getElementById(map[cat]).classList.add('active');
  renderTimeContent();
}
function renderTimeContent() {
  const c = document.getElementById('time-content');
  const items = TIME_EXPRESSIONS[_timeCat] || [];
  let html = '';
  items.forEach(it => {
    html += `<div style="padding:10px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap">
      <div style="text-align:right;direction:rtl;font-size:1.2rem;flex:1;min-width:140px">${it.ar}</div>
      <div style="font-family:monospace;color:var(--muted);min-width:140px">${it.tr}</div>
      <div style="font-size:0.9rem;min-width:140px">${it.en}</div>
    </div>`;
  });
  // Bonus: show current time in Lebanese for "telling_time" category
  if (_timeCat === 'telling_time') {
    const now = new Date();
    const speak = currentTimeInLebanese(now);
    html = `<div style="background:var(--bg);border-radius:10px;padding:12px;margin-bottom:14px;text-align:center">
      <div style="font-size:0.82rem;color:var(--muted);margin-bottom:4px">Right now (${now.getHours()}:${String(now.getMinutes()).padStart(2,'0')})</div>
      <div style="font-size:1.4rem;font-weight:700;direction:rtl">${speak.ar}</div>
      <div style="font-family:monospace;color:var(--muted)">${speak.tr}</div>
    </div>` + html;
  }
  c.innerHTML = html;
}
function currentTimeInLebanese(d) {
  let h = d.getHours();
  const m = d.getMinutes();
  const ones = ['','wa7de','tnen','tlate','arb3a','khamse','sitte','sab3a','tmene','tis3a','3ashra','7da3sh','tna3sh'];
  const onesAr = ['','وحدة','تنين','تلاتة','أربعة','خمسة','ستة','سبعة','تمنة','تسعة','عشرة','حدعش','تنعش'];
  const h12 = h % 12 === 0 ? 12 : h % 12;
  let ar = `الساعة ${onesAr[h12]}`;
  let tr = `es-saa3a ${ones[h12]}`;
  if (m === 30)      { ar += ' ونص'; tr += ' w-noss'; }
  else if (m === 15) { ar += ' وربع'; tr += ' w-rub3'; }
  else if (m === 45) { const next = (h12 % 12) + 1; ar = `الساعة ${onesAr[next]} إلا ربع`; tr = `es-saa3a ${ones[next]} illa rub3`; }
  else if (m === 20) { ar += ' وتلت'; tr += ' w-tilt'; }
  else if (m === 40) { const next = (h12 % 12) + 1; ar = `الساعة ${onesAr[next]} إلا تلت`; tr = `es-saa3a ${ones[next]} illa tilt`; }
  else if (m > 0)    { ar += ` و${m} دقيقة`; tr += ` w-${m} d2i2a`; }
  return { ar, tr };
}

// ─── COMPARATIVES & SUPERLATIVES ──────────────────────────────────────────
let _cmpMode = 'chart';
let _cmpDrill = { queue:[], idx:0, correct:0, wrong:0, picked:null, dir:'pos2cmp' };

function openComparatives() { document.getElementById('cmp-overlay').style.display = 'block'; _cmpMode='chart'; renderCmpContent(); }
function closeComparatives() { document.getElementById('cmp-overlay').style.display = 'none'; }
function setCmpMode(m) {
  _cmpMode = m;
  document.getElementById('cmp-mode-chart').classList.toggle('active', m==='chart');
  document.getElementById('cmp-mode-drill').classList.toggle('active', m==='drill');
  if (m === 'drill') buildCmpDrillQueue();
  renderCmpContent();
}
function renderCmpContent() {
  const c = document.getElementById('cmp-content');
  if (_cmpMode === 'chart') c.innerHTML = renderCmpChart(); else c.innerHTML = renderCmpDrillCard();
}
function renderCmpChart() {
  let html = `<div style="font-size:0.85rem;color:var(--muted);margin-bottom:10px">The comparative form (af3al pattern) covers <b>both</b> "more X" and "the most X". Context decides. Use "min" (from) for "than": <i>akbar min</i> = bigger than.</div>`;
  html += `<table style="width:100%;border-collapse:collapse;font-size:0.92rem">
    <thead><tr style="border-bottom:1px solid var(--border)">
      <th style="text-align:left;padding:8px">Positive</th>
      <th style="text-align:left;padding:8px">Comparative</th>
      <th style="text-align:left;padding:8px">Note</th>
    </tr></thead><tbody>`;
  COMPARATIVES.forEach(c => {
    html += `<tr style="border-bottom:1px solid var(--border)">
      <td style="padding:8px"><div style="direction:rtl;font-size:1.1rem">${c.pos.ar}</div><div style="font-family:monospace;font-size:0.78rem;color:var(--muted)">${c.pos.tr}</div><div style="font-size:0.82rem">${c.pos.en}</div></td>
      <td style="padding:8px"><div style="direction:rtl;font-size:1.15rem;font-weight:700">${c.cmp.ar}</div><div style="font-family:monospace;font-size:0.78rem;color:var(--muted)">${c.cmp.tr}</div><div style="font-size:0.82rem">${c.cmp.en}</div></td>
      <td style="padding:8px;font-size:0.78rem;color:var(--muted)">${c.note||''}</td>
    </tr>`;
  });
  html += '</tbody></table>';
  html += `<div style="margin-top:14px;background:var(--bg);border-radius:8px;padding:10px;font-size:0.88rem">
    <b>Pattern formula:</b> Most adjectives transform <i>fa3il / fa3eel / fa3l</i> → <b>af3al</b><br>
    e.g., <span style="font-family:monospace">kbir → akbar, sghir → asghar, jdid → ajadd</span><br>
    <b>Final w/y</b> drops, replaced by alif: <span style="font-family:monospace">7elw → a7la, ghali → aghla</span><br>
    <b>Doubled root</b> stays doubled: <span style="font-family:monospace">2alil → a2all, jdid → ajadd</span><br>
    <b>"Than"</b> uses <span style="font-family:monospace">min</span>: <span style="font-family:monospace">Beirut akbar min Tripoli</span> = Beirut is bigger than Tripoli.<br>
    <b>Superlative</b>: same form, with definite article OR el-...fi-l-..: <span style="font-family:monospace">el-akbar</span> = the biggest.</div>`;
  return html;
}
function buildCmpDrillQueue() {
  _cmpDrill = { queue: [...COMPARATIVES].sort(() => Math.random() - 0.5).slice(0, 12), idx:0, correct:0, wrong:0, picked:null, dir:'pos2cmp' };
}
function renderCmpDrillCard() {
  if (!_cmpDrill.queue.length) buildCmpDrillQueue();
  if (_cmpDrill.idx >= _cmpDrill.queue.length) {
    return `<div style="text-align:center;padding:30px">
      <div style="font-size:1.4rem;margin-bottom:10px">🎉 Done!</div>
      <div style="margin-bottom:14px">Score: <b>${_cmpDrill.correct}</b> / ${_cmpDrill.queue.length}</div>
      <button class="btn btn-primary" onclick="buildCmpDrillQueue();renderCmpContent()">Restart</button>
    </div>`;
  }
  const it = _cmpDrill.queue[_cmpDrill.idx];
  // Choose comparative for the positive
  const others = COMPARATIVES.filter(c => c.cmp.tr !== it.cmp.tr).sort(() => Math.random() - 0.5).slice(0, 3);
  const choices = [it, ...others].sort(() => Math.random() - 0.5);
  const picked = _cmpDrill.picked;
  let html = `<div style="text-align:center;color:var(--muted);font-size:0.8rem;margin-bottom:8px">${_cmpDrill.idx+1} / ${_cmpDrill.queue.length} · ✅ ${_cmpDrill.correct} ❌ ${_cmpDrill.wrong}</div>`;
  html += `<div style="text-align:center;font-size:1rem;color:var(--muted);margin-bottom:8px">What's the comparative ("more / -er") of:</div>`;
  html += `<div style="text-align:center;margin-bottom:18px">
    <div style="font-size:1.6rem;font-weight:700;direction:rtl">${it.pos.ar}</div>
    <div style="font-family:monospace;color:var(--muted)">${it.pos.tr}</div>
    <div style="font-size:0.92rem">${it.pos.en}</div>
  </div>`;
  html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;max-width:500px;margin:0 auto">';
  choices.forEach(ch => {
    let bg='var(--card)', bd='1px solid var(--border)';
    if (picked) {
      if (ch.cmp.tr === it.cmp.tr) bg='rgba(34,197,94,.15)', bd='1px solid #22c55e';
      else if (ch.cmp.tr === picked) bg='rgba(239,68,68,.15)', bd='1px solid #ef4444';
    }
    html += `<button onclick="pickCmpAnswer('${ch.cmp.tr.replace(/'/g,"\\'")}')" style="background:${bg};border:${bd};border-radius:10px;padding:14px;cursor:pointer;direction:rtl;font-size:1.3rem;font-weight:600">${ch.cmp.ar}<div style="font-size:0.78rem;font-family:monospace;color:var(--muted);margin-top:4px;direction:ltr">${ch.cmp.tr}</div></button>`;
  });
  html += '</div>';
  if (picked) html += `<div style="text-align:center;margin-top:18px"><button class="btn btn-primary" onclick="nextCmpDrill()">Next →</button></div>`;
  return html;
}
function pickCmpAnswer(tr) {
  if (_cmpDrill.picked) return;
  _cmpDrill.picked = tr;
  const it = _cmpDrill.queue[_cmpDrill.idx];
  var correct = tr === it.cmp.tr;
  if (correct) { _cmpDrill.correct++; recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10); } else _cmpDrill.wrong++;
  renderCmpContent();
  showToast && showToast(correct ? '✓ Correct!' : '✗ Try again');
}
function nextCmpDrill() { _cmpDrill.idx++; _cmpDrill.picked = null; renderCmpContent(); }

// ─── PLURALS ──────────────────────────────────────────────────────────────
let _plMode = 'chart';
let _plDrill = { queue:[], idx:0, correct:0, wrong:0, picked:null };

function openPlurals() { document.getElementById('pl-overlay').style.display = 'block'; _plMode='chart'; renderPlContent(); }
function closePlurals() { document.getElementById('pl-overlay').style.display = 'none'; }
function setPlMode(m) {
  _plMode = m;
  document.getElementById('pl-mode-chart').classList.toggle('active', m==='chart');
  document.getElementById('pl-mode-drill').classList.toggle('active', m==='drill');
  if (m === 'drill') buildPlDrillQueue();
  renderPlContent();
}
function renderPlContent() {
  const c = document.getElementById('pl-content');
  if (_plMode === 'chart') c.innerHTML = renderPlChart(); else c.innerHTML = renderPlDrillCard();
}
function renderPlChart() {
  let html = `<div style="font-size:0.85rem;color:var(--muted);margin-bottom:10px">Two plural systems: <b>broken</b> (the root reshapes itself — common for nouns) and <b>sound</b> (just adds -in for masc. people, -aat for fem./inanimate).</div>`;
  html += `<table style="width:100%;border-collapse:collapse;font-size:0.92rem">
    <thead><tr style="border-bottom:1px solid var(--border)">
      <th style="text-align:left;padding:8px">Singular</th>
      <th style="text-align:left;padding:8px">Plural</th>
      <th style="text-align:left;padding:8px">Type · Pattern</th>
    </tr></thead><tbody>`;
  PLURALS.forEach(p => {
    const tcolor = p.type === 'broken' ? '#f59e0b' : (p.type === 'sound-m' ? '#3b82f6' : '#22c55e');
    html += `<tr style="border-bottom:1px solid var(--border)">
      <td style="padding:8px"><div style="direction:rtl;font-size:1.1rem">${p.sg.ar}</div><div style="font-family:monospace;font-size:0.78rem;color:var(--muted)">${p.sg.tr}</div><div style="font-size:0.82rem">${p.sg.en}</div></td>
      <td style="padding:8px"><div style="direction:rtl;font-size:1.15rem;font-weight:700">${p.pl.ar}</div><div style="font-family:monospace;font-size:0.78rem;color:var(--muted)">${p.pl.tr}</div></td>
      <td style="padding:8px;font-size:0.78rem"><span style="background:${tcolor};color:white;padding:2px 6px;border-radius:4px">${p.type}</span><div style="margin-top:4px;font-family:monospace;color:var(--muted)">${p.pattern}</div></td>
    </tr>`;
  });
  html += '</tbody></table>';
  return html;
}
function buildPlDrillQueue() {
  _plDrill = { queue: [...PLURALS].sort(() => Math.random() - 0.5).slice(0, 14), idx:0, correct:0, wrong:0, picked:null };
}
function renderPlDrillCard() {
  if (!_plDrill.queue.length) buildPlDrillQueue();
  if (_plDrill.idx >= _plDrill.queue.length) {
    return `<div style="text-align:center;padding:30px">
      <div style="font-size:1.4rem;margin-bottom:10px">🎉 Done!</div>
      <div style="margin-bottom:14px">Score: <b>${_plDrill.correct}</b> / ${_plDrill.queue.length}</div>
      <button class="btn btn-primary" onclick="buildPlDrillQueue();renderPlContent()">Restart</button>
    </div>`;
  }
  const it = _plDrill.queue[_plDrill.idx];
  const others = PLURALS.filter(p => p.pl.tr !== it.pl.tr).sort(() => Math.random() - 0.5).slice(0, 3);
  const choices = [it, ...others].sort(() => Math.random() - 0.5);
  const picked = _plDrill.picked;
  let html = `<div style="text-align:center;color:var(--muted);font-size:0.8rem;margin-bottom:8px">${_plDrill.idx+1} / ${_plDrill.queue.length} · ✅ ${_plDrill.correct} ❌ ${_plDrill.wrong}</div>`;
  html += `<div style="text-align:center;font-size:1rem;color:var(--muted);margin-bottom:8px">What's the plural of:</div>`;
  html += `<div style="text-align:center;margin-bottom:18px">
    <div style="font-size:1.6rem;font-weight:700;direction:rtl">${it.sg.ar}</div>
    <div style="font-family:monospace;color:var(--muted)">${it.sg.tr}</div>
    <div style="font-size:0.92rem">${it.sg.en}</div>
  </div>`;
  html += '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;max-width:500px;margin:0 auto">';
  choices.forEach(ch => {
    let bg='var(--card)', bd='1px solid var(--border)';
    if (picked) {
      if (ch.pl.tr === it.pl.tr) bg='rgba(34,197,94,.15)', bd='1px solid #22c55e';
      else if (ch.pl.tr === picked) bg='rgba(239,68,68,.15)', bd='1px solid #ef4444';
    }
    html += `<button onclick="pickPlAnswer('${ch.pl.tr.replace(/'/g,"\\'")}')" style="background:${bg};border:${bd};border-radius:10px;padding:14px;cursor:pointer;direction:rtl;font-size:1.3rem;font-weight:600">${ch.pl.ar}<div style="font-size:0.78rem;font-family:monospace;color:var(--muted);margin-top:4px;direction:ltr">${ch.pl.tr}</div></button>`;
  });
  html += '</div>';
  if (picked) {
    html += `<div style="text-align:center;margin-top:14px;font-size:0.85rem;color:var(--muted)">Type: <b>${it.type}</b> · Pattern: ${it.pattern}</div>`;
    html += `<div style="text-align:center;margin-top:14px"><button class="btn btn-primary" onclick="nextPlDrill()">Next →</button></div>`;
  }
  return html;
}
function pickPlAnswer(tr) {
  if (_plDrill.picked) return;
  _plDrill.picked = tr;
  const it = _plDrill.queue[_plDrill.idx];
  var correct = tr === it.pl.tr;
  if (correct) { _plDrill.correct++; recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10); } else _plDrill.wrong++;
  renderPlContent();
  showToast && showToast(correct ? '✓ Correct!' : '✗ Try again');
}
function nextPlDrill() { _plDrill.idx++; _plDrill.picked = null; renderPlContent(); }

