// ─── DICTATION ────────────────────────────────────────────────────────────
let _dictQ = { queue:[], idx:0, correct:0, wrong:0, revealed:false };

function _dictNormalize(s) {
  return (s||'').toLowerCase().trim()
    .replace(/[\s\-_]+/g,' ')
    .replace(/[ـ.,;:!?'""]/g,'')
    .replace(/aa/g,'a').replace(/ee/g,'e').replace(/ii/g,'i').replace(/oo/g,'o').replace(/uu/g,'u')
    .replace(/q/g,'2').replace(/k/g,'k').replace(/c/g,'k')
    .replace(/sh/g,'sh');
}
function _dictBuildQueue() {
  // Mix: vocab single words + short phrases from conversations
  const items = [];
  if (typeof VOCAB !== 'undefined') {
    VOCAB.filter(v => v.tr && v.ar && v.tr.length <= 18).slice(0, 400).forEach(v => {
      items.push({ ar:v.ar, tr:v.tr, en:v.en||'', src:'vocab' });
    });
  }
  // Short proverbs
  if (typeof PROVERBS !== 'undefined') {
    PROVERBS.filter(p => p.tr && p.tr.length <= 30).slice(0, 30).forEach(p => {
      items.push({ ar:p.ar, tr:p.tr, en:p.en||'', src:'proverb' });
    });
  }
  return items.sort(() => Math.random() - 0.5).slice(0, 30);
}
function openDictation() {
  document.getElementById('dict-overlay').style.display = 'block';
  _dictQ = { queue: _dictBuildQueue(), idx: 0, correct: 0, wrong: 0, revealed: false };
  renderDictCard();
}
function closeDictation() { if (typeof stopAllAudio === 'function') stopAllAudio(); document.getElementById('dict-overlay').style.display = 'none'; }
function renderDictCard() {
  const c = document.getElementById('dict-card');
  const ctrl = document.getElementById('dict-controls');
  const stats = document.getElementById('dict-stats');
  if (_dictQ.idx >= _dictQ.queue.length) {
    c.innerHTML = `<div style="text-align:center;padding:30px"><div style="font-size:1.4rem;margin-bottom:10px">🎉 Done!</div><div>Score: <b>${_dictQ.correct}</b> / ${_dictQ.queue.length}</div></div>`;
    ctrl.innerHTML = `<button class="btn btn-primary" onclick="openDictation()">Restart</button>`;
    stats.textContent = '';
    return;
  }
  const it = _dictQ.queue[_dictQ.idx];
  stats.textContent = `${_dictQ.idx+1}/${_dictQ.queue.length} · ✅ ${_dictQ.correct} ❌ ${_dictQ.wrong}`;
  let html = `<div style="text-align:center;color:var(--muted);font-size:0.88rem;margin-bottom:14px">Listen and type the chat-alphabet:</div>`;
  html += `<div style="text-align:center;margin-bottom:14px"><button class="btn btn-primary" onclick="speak(_dictQ.queue[_dictQ.idx].ar,false)" style="font-size:1.1rem;padding:14px 22px">▶ Play</button>
    <button class="btn btn-outline" onclick="speak(_dictQ.queue[_dictQ.idx].ar,true)" style="margin-left:8px">▶ Slow</button></div>`;
  if (!_dictQ.revealed) {
    html += `<input type="text" id="dict-input" placeholder="Type chat-alphabet (e.g. mar7aba)…" autofocus style="width:100%;padding:12px;border:1px solid var(--border);background:var(--bg);border-radius:8px;color:inherit;font-size:1.05rem;font-family:monospace" onkeydown="if(event.key==='Enter')submitDict()">`;
    ctrl.innerHTML = `<button class="btn btn-primary" onclick="submitDict()">Check</button>
      <button class="btn btn-outline" onclick="revealDict()" style="margin-left:8px">Reveal</button>
      <button class="btn btn-outline" onclick="skipDict()" style="margin-left:8px">Skip</button>`;
  } else {
    html += `<div style="background:var(--bg);border-radius:8px;padding:14px;margin-top:10px">
      <div style="text-align:right;direction:rtl;font-size:1.4rem;margin-bottom:6px">${it.ar}</div>
      <div style="font-family:monospace;font-size:1rem;color:var(--accent)">${it.tr}</div>
      ${it.en?`<div style="font-size:0.92rem;margin-top:6px;color:var(--muted)">${it.en}</div>`:''}
    </div>`;
    ctrl.innerHTML = `<button class="btn btn-primary" onclick="nextDict()">Next →</button>`;
  }
  c.innerHTML = html;
  // Auto-play first time
  if (!_dictQ.revealed) {
    setTimeout(() => { try { speak(it.ar, false); } catch(e){} }, 200);
    setTimeout(() => { const i = document.getElementById('dict-input'); if (i) i.focus(); }, 250);
  }
}
function submitDict() {
  const i = document.getElementById('dict-input');
  if (!i) return;
  const got = _dictNormalize(i.value);
  const want = _dictNormalize(_dictQ.queue[_dictQ.idx].tr);
  if (!got) { revealDict(); return; }
  if (got === want || _editDistance(got, want) <= 2) {
    _dictQ.correct++;
    if (typeof bumpAchievementCounter === 'function') bumpAchievementCounter('dict_correct');
    recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10);
  } else _dictQ.wrong++;
  _dictQ.revealed = true;
  renderDictCard();
}
function revealDict() { _dictQ.wrong++; _dictQ.revealed = true; renderDictCard(); }
function skipDict() { _dictQ.idx++; _dictQ.revealed = false; renderDictCard(); }
function nextDict() { _dictQ.idx++; _dictQ.revealed = false; renderDictCard(); }
function _editDistance(a, b) {
  if (Math.abs(a.length - b.length) > 6) return 99;
  const dp = Array.from({length:a.length+1}, () => new Array(b.length+1).fill(0));
  for (let i=0;i<=a.length;i++) dp[i][0] = i;
  for (let j=0;j<=b.length;j++) dp[0][j] = j;
  for (let i=1;i<=a.length;i++) for (let j=1;j<=b.length;j++) {
    dp[i][j] = a[i-1] === b[j-1] ? dp[i-1][j-1] : 1 + Math.min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]);
  }
  return dp[a.length][b.length];
}

// ─── ROOT EXPLORER ────────────────────────────────────────────────────────
function openRootExplorer() {
  document.getElementById('root-overlay').style.display = 'block';
  renderRootList();
}
function closeRootExplorer() { document.getElementById('root-overlay').style.display = 'none'; }
function renderRootList() {
  const c = document.getElementById('root-list');
  // Run #113 BUG FIX: overlay's search input was renamed from 'root-search' to
  // 'root-search-overlay' to resolve collision with the main-view input at the
  // Roots section (both had id="root-search" → getElementById returned only the
  // main-view one, making the overlay's input silently feed the wrong handler).
  const q = (document.getElementById('root-search-overlay')?.value || '').toLowerCase().trim();
  let items = ROOTS;
  if (q) items = ROOTS.filter(r => r.tr.toLowerCase().includes(q) || r.meaning.toLowerCase().includes(q) || r.words.some(w => (w.tr||'').toLowerCase().includes(q) || (w.en||'').toLowerCase().includes(q)));
  let html = `<div style="font-size:0.85rem;color:var(--muted);margin-bottom:10px">Arabic words come from <b>3-letter roots</b>. Patterns slot consonants in: <span style="font-family:monospace">k-t-b</span> → kteb (book), katab (he wrote), maktab (office), maktabe (library). Recognising roots makes vocab grow exponentially.</div>`;
  items.forEach(r => {
    html += `<div style="background:var(--card);border-radius:12px;padding:14px;margin-bottom:12px">
      <div style="display:flex;align-items:baseline;gap:12px;margin-bottom:8px;flex-wrap:wrap">
        <div style="font-size:1.6rem;font-weight:700;direction:rtl;letter-spacing:6px">${r.root}</div>
        <div style="font-family:monospace;font-size:1.05rem;color:var(--accent)">${r.tr}</div>
        <div style="color:var(--muted);font-style:italic">→ ${r.meaning}</div>
      </div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:6px">`;
    r.words.forEach(w => {
      html += `<div style="background:var(--bg);border-radius:6px;padding:8px">
        <div style="direction:rtl;font-size:1.1rem;font-weight:600">${w.ar}</div>
        <div style="font-family:monospace;font-size:0.82rem;color:var(--muted)">${w.tr}</div>
        <div style="font-size:0.82rem">${w.en}</div>
      </div>`;
    });
    html += `</div></div>`;
  });
  if (!items.length) html += `<div style="text-align:center;color:var(--muted);padding:30px">No matches.</div>`;
  c.innerHTML = html;
}

