function loadAchState() {
  try { return JSON.parse(localStorage.getItem('la_achievements') || '{}'); } catch(e) { return {}; }
}
function saveAchState(s) { _lsSet('la_achievements', JSON.stringify(s)); }
function _achGetUnlocked() { return loadAchState().unlocked || []; }
function _achGetCounters() { return loadAchState().counters || {}; }
function bumpAchievementCounter(name, by = 1) {
  const s = loadAchState();
  s.counters = s.counters || {};
  s.counters[name] = (s.counters[name] || 0) + by;
  saveAchState(s);
  checkAchievements();
}
function getMasteredCount() {
  if (typeof srsData === 'undefined') return 0;
  let n = 0;
  Object.values(srsData).forEach(c => { if (c && c.interval && c.interval >= 21) n++; });
  return n;
}
function getTotalReviewCount() {
  if (typeof srsData === 'undefined') return 0;
  let n = 0;
  Object.values(srsData).forEach(c => { if (c && c.reps) n += c.reps; });
  return n;
}
function checkAchievements() {
  const s = loadAchState();
  s.unlocked = s.unlocked || [];
  s.counters = s.counters || {};
  const ctx = {
    streak: typeof getStreak === 'function' ? getStreak() : 0,
    mastered: getMasteredCount(),
    totalRev: getTotalReviewCount(),
    counters: s.counters,
  };
  let any = false;
  ACHIEVEMENTS.forEach(a => {
    if (s.unlocked.includes(a.id)) return;
    try { if (a.check(ctx)) { s.unlocked.push(a.id); any = true; toastAchievement(a); } } catch(e){}
  });
  if (any) saveAchState(s);
}
function toastAchievement(a) {
  const t = document.createElement('div');
  t.style.cssText = 'position:fixed;bottom:20px;left:50%;transform:translateX(-50%);background:var(--card);border:2px solid var(--accent);border-radius:12px;padding:14px 18px;z-index:1000;box-shadow:0 4px 18px rgba(0,0,0,.3);max-width:340px;text-align:center';
  t.innerHTML = `<div style="font-size:1.6rem">${a.emoji}</div><div style="font-weight:700;margin:4px 0">${a.name}</div><div style="font-size:0.85rem;color:var(--muted)">${a.desc}</div>`;
  document.body.appendChild(t);
  setTimeout(() => t.remove(), 4500);
}
function openAchievements() {
  document.getElementById('achievements-overlay').style.display = 'block';
  checkAchievements();
  renderAchList();
}
function closeAchievements() { document.getElementById('achievements-overlay').style.display = 'none'; }
function renderAchList() {
  const c = document.getElementById('ach-list');
  const sum = document.getElementById('ach-summary');
  const unlocked = _achGetUnlocked();
  sum.textContent = `${unlocked.length} / ${ACHIEVEMENTS.length} unlocked`;
  let html = `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px">`;
  ACHIEVEMENTS.forEach(a => {
    const got = unlocked.includes(a.id);
    html += `<div style="background:var(--card);border-radius:10px;padding:12px;opacity:${got?1:0.45};border:${got?'2px solid var(--accent)':'1px solid var(--border)'}">
      <div style="display:flex;align-items:center;gap:8px">
        <div style="font-size:1.6rem">${a.emoji}</div>
        <div>
          <div style="font-weight:700">${a.name}</div>
          <div style="font-size:0.78rem;color:var(--muted)">${a.desc}</div>
        </div>
      </div>
      ${got?'<div style="margin-top:6px;font-size:0.78rem;color:var(--accent)">✓ Unlocked</div>':''}
    </div>`;
  });
  html += '</div>';
  c.innerHTML = html;
}
// Periodic check on common actions
setTimeout(() => { try { checkAchievements(); } catch(e){} }, 1500);

