// ─── ACTIVITY HEATMAP ─────────────────────────────────────────────────────
function openHeatmap() {
  document.getElementById('hm-overlay').style.display='block';
  renderHeatmap();
}
function closeHeatmap() { document.getElementById('hm-overlay').style.display='none'; }
function renderHeatmap() {
  const c = document.getElementById('hm-content');
  const sum = document.getElementById('hm-summary');
  // Run #74 BUG FIX: app maintains two parallel per-day counters that drifted
  // historically — la_daily_ct (added Run #59, drives the goal bar + heatmap)
  // and la_activity (drives the streak counter, populated by recordActivity).
  // Until Run #71, several drill paths called recordActivity without
  // incDailyCount, so la_activity has days that la_daily_ct doesn't. The
  // heatmap was only reading la_daily_ct, which made those days look blank
  // (e.g. user practiced minimal pairs all weekend, heatmap stayed grey).
  // Union the two per day — la_activity is a same-shape {dateKey: count} blob,
  // so per-day max gives the most accurate cell value without losing modern
  // post-#71 data (where the two counters agree by design).
  let dailyData = {}, actData = {};
  try { dailyData = JSON.parse(localStorage.getItem('la_daily_ct') || '{}'); } catch(e){}
  try { actData = JSON.parse(localStorage.getItem('la_activity') || '{}'); } catch(e){}
  const data = {};
  const allKeys = new Set([...Object.keys(dailyData), ...Object.keys(actData)]);
  allKeys.forEach(k => { data[k] = Math.max(dailyData[k] || 0, actData[k] || 0); });
  const today = new Date(); today.setHours(0,0,0,0);
  const days = 182; // ~6 months
  const cells = [];
  let total = 0, active = 0, peak = 0;
  for (let i = days-1; i >= 0; i--) {
    const d = new Date(today); d.setDate(d.getDate() - i);
    const key = _localDateKey(d);
    const ct = data[key] || 0;
    cells.push({ date:d, key, ct });
    total += ct;
    if (ct > 0) active++;
    if (ct > peak) peak = ct;
  }
  sum.textContent = `${active} active days · ${total} reviews · peak ${peak}`;
  // Pad to start on Sunday
  const firstDow = cells[0].date.getDay();
  for (let i=0;i<firstDow;i++) cells.unshift({ date:null, key:null, ct:null });
  // Build week columns
  const weeks = [];
  for (let i=0;i<cells.length;i+=7) weeks.push(cells.slice(i, i+7));
  function level(ct) {
    if (ct === null || ct === 0) return 0;
    if (peak <= 1) return 4;
    const pct = ct / peak;
    if (pct < 0.25) return 1;
    if (pct < 0.5) return 2;
    if (pct < 0.75) return 3;
    return 4;
  }
  const colors = ['rgba(127,127,127,0.12)','#0e4429','#006d32','#26a641','#39d353'];
  let html = `<div style="background:var(--card);border-radius:12px;padding:14px;overflow-x:auto">
    <div style="display:flex;gap:3px">`;
  weeks.forEach(week => {
    html += `<div style="display:flex;flex-direction:column;gap:3px">`;
    for (let r=0;r<7;r++) {
      const cell = week[r];
      if (!cell || cell.date === null) { html += `<div style="width:14px;height:14px"></div>`; continue; }
      const lv = level(cell.ct);
      html += `<div title="${cell.key}: ${cell.ct} reviews" style="width:14px;height:14px;background:${colors[lv]};border-radius:3px;cursor:pointer"></div>`;
    }
    html += `</div>`;
  });
  html += `</div>
    <div style="display:flex;align-items:center;gap:6px;margin-top:10px;font-size:0.8rem;color:var(--muted);justify-content:flex-end">
      <span>Less</span>
      ${colors.map(col => `<div style="width:12px;height:12px;background:${col};border-radius:3px"></div>`).join('')}
      <span>More</span>
    </div>
  </div>`;
  // Stats grid
  let cur7 = 0, prev7 = 0;
  for (let i = days-7; i < days; i++) cur7 += (cells[firstDow+i]?.ct||0);
  for (let i = days-14; i < days-7; i++) prev7 += (cells[firstDow+i]?.ct||0);
  const trend = prev7 ? Math.round(((cur7 - prev7) / prev7) * 100) : (cur7 ? 100 : 0);
  const avg = active ? Math.round(total / active) : 0;
  html += `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:10px;margin-top:14px">
    <div style="background:var(--card);border-radius:10px;padding:12px;text-align:center">
      <div style="font-size:1.6rem;font-weight:700">${cur7}</div>
      <div style="color:var(--muted);font-size:0.82rem">Last 7 days</div>
      <div style="font-size:0.78rem;margin-top:4px;color:${trend>=0?'#22c55e':'#ef4444'}">${trend>=0?'▲':'▼'} ${Math.abs(trend)}% vs prev wk</div>
    </div>
    <div style="background:var(--card);border-radius:10px;padding:12px;text-align:center">
      <div style="font-size:1.6rem;font-weight:700">${active}</div>
      <div style="color:var(--muted);font-size:0.82rem">Active days (180)</div>
    </div>
    <div style="background:var(--card);border-radius:10px;padding:12px;text-align:center">
      <div style="font-size:1.6rem;font-weight:700">${avg}</div>
      <div style="color:var(--muted);font-size:0.82rem">Avg / active day</div>
    </div>
    <div style="background:var(--card);border-radius:10px;padding:12px;text-align:center">
      <div style="font-size:1.6rem;font-weight:700">${peak}</div>
      <div style="color:var(--muted);font-size:0.82rem">Best day</div>
    </div>
  </div>`;
  c.innerHTML = html;
}

// ============ RUN #6: SOUND MINIMAL PAIRS (extended overlay — separate from sounds-tab inline drill) ============
