/* ------------------ TRAVEL & DIRECTIONS ------------------ */
let _trvTab = 'transport';
let _trvDialogIdx = 0;
let _trvDialogStep = 0;
function openTravel(){
  bumpAchievementCounter && bumpAchievementCounter('trv_open');
  const ov = document.getElementById('trv-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setTrvTab('transport');
}
function closeTravel(){ const ov=document.getElementById('trv-overlay'); if(ov) ov.style.display='none'; }
function setTrvTab(t){
  _trvTab = t;
  const bar = document.getElementById('trv-tab-bar');
  if(bar){
    const tabs = [['transport','🚌 Transport'],['directions','🧭 Directions'],['dialog','🎭 Dialogs']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_trvTab===k?'active':''}" onclick="setTrvTab('${k}')">${l}</button>`).join('');
  }
  renderTravel();
}
function renderTravel(){
  const c = document.getElementById('trv-content'); if(!c) return;
  if(_trvTab==='transport'){
    const cats = {vehicle:'🚗 Vehicles', place:'📍 Places', item:'📋 Items'};
    document.getElementById('trv-stats').textContent = `${TRANSPORT_VOCAB.length} words`;
    c.innerHTML = Object.keys(cats).map(k => {
      const items = TRANSPORT_VOCAB.filter(t => t.cat===k);
      return `
        <div style="margin-bottom:18px">
          <div style="font-weight:700;color:#3b82f6;margin-bottom:8px">${cats[k]} (${items.length})</div>
          <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:8px">
            ${items.map(it => `
              <div style="background:var(--card);border-radius:10px;padding:10px;display:flex;justify-content:space-between;align-items:center">
                <div style="flex:1">
                  <div style="font-size:1.1rem;direction:rtl">${it.ar}</div>
                  <div style="font-weight:600">${it.tr}</div>
                  <div style="color:var(--muted);font-size:0.8rem">${it.en}</div>
                </div>
                <button class="btn btn-sm btn-outline" onclick="speak('${it.tr.replace(/'/g,"\\'")}',true)">🔊</button>
              </div>`).join('')}
          </div>
        </div>`;
    }).join('');
  } else if(_trvTab==='directions'){
    document.getElementById('trv-stats').textContent = `${DIRECTION_PHRASES.length} phrases`;
    c.innerHTML = `
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:8px">
        ${DIRECTION_PHRASES.map(p => `
          <div style="background:var(--card);border-radius:10px;padding:12px;display:flex;justify-content:space-between;align-items:flex-start;gap:8px">
            <div style="flex:1">
              <div style="font-size:1.1rem;direction:rtl">${p.ar}</div>
              <div style="font-weight:600">${p.tr}</div>
              <div style="color:var(--muted);font-size:0.85rem">${p.en}</div>
            </div>
            <button class="btn btn-sm btn-outline" onclick="speak('${p.tr.replace(/'/g,"\\'")}',true)">🔊</button>
          </div>`).join('')}
      </div>`;
  } else if(_trvTab==='dialog'){
    document.getElementById('trv-stats').textContent = `Dialog ${_trvDialogIdx+1}/${TRAVEL_DIALOGS.length}`;
    const d = TRAVEL_DIALOGS[_trvDialogIdx];
    const visible = d.turns.slice(0, _trvDialogStep+1);
    const labelOf = w => w==='you'?'You':w==='driver'?'Driver':w==='staff'?'Staff':'Local';
    c.innerHTML = `
      <div style="background:var(--card);border-radius:14px;padding:18px;margin-bottom:12px">
        <div style="font-weight:700;color:#3b82f6;margin-bottom:12px">${d.title}</div>
        ${visible.map(t => `
          <div style="display:flex;justify-content:${t.who==='you'?'flex-end':'flex-start'};margin-bottom:8px">
            <div style="background:${t.who==='you'?'#3b82f6':'var(--bg)'};color:${t.who==='you'?'white':'var(--fg)'};padding:10px 14px;border-radius:14px;max-width:80%">
              <div style="font-size:0.7rem;opacity:0.8;margin-bottom:4px">${labelOf(t.who)}</div>
              <div style="font-size:1.1rem;direction:rtl">${t.ar}</div>
              <div style="font-weight:600">${t.tr}</div>
              <div style="opacity:0.85;font-size:0.85rem">${t.en}</div>
              <button class="btn btn-sm btn-outline" style="margin-top:6px" onclick="speak('${t.tr.replace(/'/g,"\\'")}',true)">🔊</button>
            </div>
          </div>`).join('')}
      </div>
      <div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap">
        <button class="btn btn-outline" onclick="trvPrevDialog()">← Prev</button>
        ${_trvDialogStep < d.turns.length-1
          ? `<button class="btn btn-primary" onclick="trvAdvanceTurn()">Next turn →</button>`
          : `<button class="btn btn-outline" onclick="trvRestartDialog()">↺ Restart</button>`}
        <button class="btn btn-outline" onclick="trvNextDialog()">Next dialog →</button>
      </div>`;
  }
}
function trvAdvanceTurn(){ const d=TRAVEL_DIALOGS[_trvDialogIdx]; if(_trvDialogStep<d.turns.length-1){ _trvDialogStep++; renderTravel(); } }
function trvRestartDialog(){ _trvDialogStep=0; renderTravel(); }
function trvNextDialog(){ _trvDialogIdx=(_trvDialogIdx+1)%TRAVEL_DIALOGS.length; _trvDialogStep=0; renderTravel(); }
function trvPrevDialog(){ _trvDialogIdx=(_trvDialogIdx-1+TRAVEL_DIALOGS.length)%TRAVEL_DIALOGS.length; _trvDialogStep=0; renderTravel(); }

