/* ------------------ REVERSE CONJUGATION ------------------ */
let _rcqState = { score:0, total:0, current:null, answered:false };
function openRevConj(){
  bumpAchievementCounter && bumpAchievementCounter('rcq_open');
  const ov = document.getElementById('rcq-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _rcqState = { score:0, total:0, current:null, answered:false };
  rcqNew();
}
function closeRevConj(){ const ov=document.getElementById('rcq-overlay'); if(ov) ov.style.display='none'; }
function rcqNew(){
  const verb = CONJ_QUIZ_VERBS[Math.floor(Math.random()*CONJ_QUIZ_VERBS.length)];
  const pron = CONJ_QUIZ_PRONOUNS[Math.floor(Math.random()*CONJ_QUIZ_PRONOUNS.length)];
  const tense = CONJ_QUIZ_TENSES[Math.floor(Math.random()*CONJ_QUIZ_TENSES.length)];
  const form = verb[tense.key][pron.key];
  _rcqState.current = { verb, pron, tense, form, pickedPron:null, pickedTense:null };
  _rcqState.answered = false;
  rcqRender();
}
function rcqRender(){
  const c = document.getElementById('rcq-content'); if(!c) return;
  const s = _rcqState;
  document.getElementById('rcq-stats').textContent = `Score ${s.score}/${s.total}`;
  if(!s.current) return;
  const cur = s.current;
  c.innerHTML = `
    <div style="background:var(--card);border-radius:14px;padding:24px">
      <div style="text-align:center">
        <div style="color:var(--muted);font-size:0.85rem;margin-bottom:6px">Identify pronoun + tense for:</div>
        <div style="font-size:0.85rem;color:var(--muted)">verb ${cur.verb.tr} (${cur.verb.en})</div>
        <div style="font-size:2rem;font-weight:700;color:#3b82f6;margin:14px 0">${cur.form}</div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:14px">
        <div>
          <div style="font-weight:600;margin-bottom:8px;text-align:center">Pronoun</div>
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">
            ${CONJ_QUIZ_PRONOUNS.map(p => `
              <button class="btn btn-outline" data-rcq-pron="${p.key}" onclick="rcqPickPron('${p.key}')" style="${cur.pickedPron===p.key?'border:2px solid #3b82f6;background:#3b82f622':''}">
                <div style="font-weight:600">${p.key}</div>
                <div style="color:var(--muted);font-size:0.75rem">${p.label}</div>
              </button>`).join('')}
          </div>
        </div>
        <div>
          <div style="font-weight:600;margin-bottom:8px;text-align:center">Tense</div>
          <div style="display:grid;gap:6px">
            ${CONJ_QUIZ_TENSES.map(t => `
              <button class="btn btn-outline" data-rcq-tense="${t.key}" onclick="rcqPickTense('${t.key}')" style="${cur.pickedTense===t.key?'border:2px solid #9333ea;background:#9333ea22':''}">
                ${t.label}
              </button>`).join('')}
          </div>
        </div>
      </div>
      <div style="text-align:center;margin-top:14px">
        <button class="btn btn-primary" onclick="rcqCheck()">Check</button>
        <button class="btn btn-outline" onclick="rcqReveal()">Reveal</button>
        <button class="btn btn-outline" onclick="rcqNew()">Skip →</button>
      </div>
      <div id="rcq-fb" style="text-align:center;min-height:28px;margin-top:12px;font-weight:600"></div>
    </div>`;
}
function rcqPickPron(p){ if(!_rcqState.current||_rcqState.answered) return; _rcqState.current.pickedPron = p; rcqRender(); }
function rcqPickTense(t){ if(!_rcqState.current||_rcqState.answered) return; _rcqState.current.pickedTense = t; rcqRender(); }
function rcqCheck(){
  const cur = _rcqState.current; if(!cur || _rcqState.answered) return;
  if(!cur.pickedPron || !cur.pickedTense){
    document.getElementById('rcq-fb').innerHTML = `<span style="color:#eab308">Pick both pronoun and tense.</span>`;
    return;
  }
  _rcqState.answered = true;
  _rcqState.total++;
  const ok = cur.pickedPron === cur.pron.key && cur.pickedTense === cur.tense.key;
  const fb = document.getElementById('rcq-fb');
  if(ok){
    _rcqState.score++;
    fb.innerHTML = `<span style="color:#22c55e">✓ Correct! ${cur.pron.key} (${cur.pron.label}), ${cur.tense.label}</span>`;
    bumpAchievementCounter && bumpAchievementCounter('rcq_correct');
    recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10);
  } else {
    fb.innerHTML = `<span style="color:#ef4444">✗ Was: <b>${cur.pron.key}</b> (${cur.pron.label}), <b>${cur.tense.label}</b></span>`;
  }
  document.getElementById('rcq-stats').textContent = `Score ${_rcqState.score}/${_rcqState.total}`;
}
function rcqReveal(){
  const cur = _rcqState.current; if(!cur) return;
  if(!_rcqState.answered){ _rcqState.total++; _rcqState.answered = true; }
  document.getElementById('rcq-fb').innerHTML = `<span style="color:#eab308">→ ${cur.pron.key} (${cur.pron.label}), ${cur.tense.label}</span>`;
  document.getElementById('rcq-stats').textContent = `Score ${_rcqState.score}/${_rcqState.total}`;
}

