let _shTab = 'vocab';
let _shCat = 'all';
let _shDrillIdx = -1;
let _shDrillChoices = [];
let _shStreak = 0;
let _shDialogTurn = 0;

function openSportsHobbies(){
  if(typeof bumpAchievementCounter === 'function') bumpAchievementCounter('sh_open');
  const ov = document.getElementById('sh-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setShTab('vocab');
}
function closeSportsHobbies(){ const ov=document.getElementById('sh-overlay'); if(ov) ov.style.display='none'; }
function setShTab(t){
  _shTab = t;
  const bar = document.getElementById('sh-tab-bar');
  if(bar){
    const tabs = [['vocab','📋 Vocab'],['phrases','💬 Phrases'],['dialog','🎭 Dialog'],['drill','🎯 Match']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_shTab===k?'active':''}" onclick="setShTab('${k}')">${l}</button>`).join('');
  }
  const stats = document.getElementById('sh-stats');
  if(stats) stats.textContent = `${SPORTS_VOCAB.length} terms · ${SPORTS_PHRASES.length} phrases · streak: ${_shStreak}`;
  renderSportsHobbies();
}
function renderSportsHobbies(){
  const c = document.getElementById('sh-content'); if(!c) return;
  if(_shTab === 'vocab'){
    const cats = ['all','sport','hobby','place','gear','verb'];
    const filterBar = '<div style="display:flex;gap:6px;justify-content:center;flex-wrap:wrap;margin-bottom:12px">' +
      cats.map(k => `<button class="cat-filter ${_shCat===k?'active':''}" onclick="_shCat='${k}';renderSportsHobbies()">${k}</button>`).join('') + '</div>';
    const items = _shCat === 'all' ? SPORTS_VOCAB : SPORTS_VOCAB.filter(i => i.cat === _shCat);
    c.innerHTML = filterBar + '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:8px">' +
      items.map(i => `<div style="background:var(--card);padding:10px;border-radius:8px">
        <div style="font-size:1.15rem">${i.ar}</div>
        <div style="color:var(--accent);font-weight:600">${i.tr}</div>
        <div style="color:var(--muted);font-size:0.85rem">${i.en} <span style="font-size:0.75rem">[${i.cat}]</span></div>
      </div>`).join('') + '</div>';
  } else if(_shTab === 'phrases'){
    c.innerHTML = '<div style="display:grid;gap:8px">' + SPORTS_PHRASES.map(p => `
      <div style="background:var(--card);padding:12px;border-radius:10px">
        <div style="font-size:1.1rem">${p.ar}</div>
        <div style="color:var(--accent);font-weight:600">${p.tr}</div>
        <div style="color:var(--muted);font-size:0.9rem">${p.en}</div>
      </div>`).join('') + '</div>';
  } else if(_shTab === 'dialog'){
    const d = SPORTS_DIALOG;
    const turns = d.turns.slice(0, _shDialogTurn + 1);
    c.innerHTML = `<div style="background:var(--card);padding:14px;border-radius:12px">
      <div style="font-weight:700;margin-bottom:10px;text-align:center">${d.title}</div>
      <div style="display:flex;flex-direction:column;gap:8px;margin-bottom:14px">
        ${turns.map(t => `<div style="background:var(--bg);padding:10px;border-radius:8px;border-left:3px solid ${t.sp==='A'?'var(--accent)':'#f59e0b'}">
          <div style="font-size:0.8rem;color:var(--muted);margin-bottom:3px">${t.sp}</div>
          <div style="font-size:1.05rem">${t.ar}</div>
          <div style="color:var(--accent);font-size:0.95rem">${t.tr}</div>
          <div style="color:var(--muted);font-size:0.85rem">${t.en}</div>
        </div>`).join('')}
      </div>
      <div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap">
        ${_shDialogTurn < d.turns.length - 1 ? `<button class="btn btn-primary" onclick="_shDialogTurn++;renderSportsHobbies()">Next turn →</button>` : `<button class="btn btn-primary" onclick="_shDialogTurn=0;renderSportsHobbies()">↻ Restart</button>`}
      </div>
    </div>`;
  } else if(_shTab === 'drill'){
    if(_shDrillIdx < 0) shNewDrill();
    const item = SPORTS_VOCAB[_shDrillIdx];
    c.innerHTML = `<div style="background:var(--card);padding:18px;border-radius:12px;text-align:center">
      <div style="color:var(--muted);font-size:0.9rem;margin-bottom:6px">Translate to English:</div>
      <div style="font-size:1.6rem;margin-bottom:4px">${item.ar}</div>
      <div style="color:var(--accent);margin-bottom:14px">${item.tr}</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px;max-width:480px;margin:0 auto">
        ${_shDrillChoices.map(c2 => `<button class="btn btn-outline" style="padding:10px" onclick="shCheck('${c2.replace(/'/g,"\\'")}')">${c2}</button>`).join('')}
      </div>
      <div id="sh-result" style="margin-top:12px;font-size:1rem;min-height:1.4em"></div>
    </div>`;
  }
}
function shNewDrill(){
  _shDrillIdx = Math.floor(Math.random() * SPORTS_VOCAB.length);
  const correct = SPORTS_VOCAB[_shDrillIdx].en;
  const pool = SPORTS_VOCAB.filter((_,i) => i !== _shDrillIdx).sort(() => Math.random() - 0.5).slice(0,3).map(x => x.en);
  _shDrillChoices = [correct, ...pool].sort(() => Math.random() - 0.5);
  renderSportsHobbies();
}
function shCheck(picked){
  const correct = SPORTS_VOCAB[_shDrillIdx].en;
  const r = document.getElementById('sh-result');
  if(r && r.dataset.answered) return; if(r) r.dataset.answered='1';
  if(picked === correct){
    _shStreak++;
    recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10);
    if(r) r.innerHTML = `<span style="color:#4ade80">✓ Correct!</span> streak: ${_shStreak}`;
    setTimeout(shNewDrill, 800);
  } else {
    _shStreak = 0;
    if(r) r.innerHTML = `<span style="color:#f87171">✗ Was: ${correct}</span>`;
    setTimeout(shNewDrill, 1500);
  }
}

