// ===== COMMON MISTAKES =====
let _cmTab = 'browse';
let _cmCat = 'all';
let _cmDrillIdx = -1;
let _cmStreak = 0;

function openCommonMistakes(){
  if(typeof bumpAchievementCounter === 'function') bumpAchievementCounter('cm_open');
  const ov = document.getElementById('cm-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setCmTab('browse');
}
function closeCommonMistakes(){ const ov=document.getElementById('cm-overlay'); if(ov) ov.style.display='none'; }
function setCmTab(t){
  _cmTab = t;
  const bar = document.getElementById('cm-tab-bar');
  if(bar){
    const tabs = [['browse','📋 Browse'],['drill','🎯 Spot the Mistake']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_cmTab===k?'active':''}" onclick="setCmTab('${k}')">${l}</button>`).join('');
  }
  const stats = document.getElementById('cm-stats');
  if(stats) stats.textContent = `${COMMON_MISTAKES.length} mistakes · ${CM_DRILL.length} drill items · streak: ${_cmStreak}`;
  renderCm();
}
function renderCm(){
  const c = document.getElementById('cm-content'); if(!c) return;
  if(_cmTab === 'browse'){
    const cats = ['all', ...new Set(COMMON_MISTAKES.map(m => m.cat))];
    const filterBar = '<div style="display:flex;gap:6px;justify-content:center;flex-wrap:wrap;margin-bottom:12px">' +
      cats.map(k => `<button class="cat-filter ${_cmCat===k?'active':''}" onclick="_cmCat='${k}';renderCm()">${k}</button>`).join('') + '</div>';
    const items = _cmCat === 'all' ? COMMON_MISTAKES : COMMON_MISTAKES.filter(m => m.cat === _cmCat);
    c.innerHTML = filterBar + '<div style="display:grid;gap:10px">' + items.map(m => `
      <div style="background:var(--card);padding:12px;border-radius:10px;border-left:4px solid #f87171">
        <div style="display:flex;gap:8px;align-items:center;margin-bottom:8px;flex-wrap:wrap">
          <span style="background:#f87171;color:white;padding:2px 8px;border-radius:6px;font-size:0.75rem">${m.cat}</span>
          <span style="color:var(--muted);font-size:0.85rem">${m.en}</span>
        </div>
        <div style="margin-bottom:6px"><span style="color:#f87171">✗</span> <span style="text-decoration:line-through">${m.wrong}</span></div>
        <div style="margin-bottom:8px"><span style="color:#4ade80">✓</span> <strong>${m.right}</strong></div>
        <div style="font-size:0.85rem;color:var(--muted);background:var(--bg);padding:8px;border-radius:6px">💡 ${m.why}</div>
      </div>`).join('') + '</div>';
  } else if(_cmTab === 'drill'){
    if(_cmDrillIdx < 0) cmNewDrill();
    const d = CM_DRILL[_cmDrillIdx];
    c.innerHTML = `<div style="background:var(--card);padding:18px;border-radius:12px;text-align:center">
      <div style="color:var(--muted);font-size:0.9rem;margin-bottom:8px">Is this sentence correct?</div>
      <div style="font-size:1.4rem;margin-bottom:18px;background:var(--bg);padding:14px;border-radius:8px">${d.sent}</div>
      <div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap">
        <button class="btn btn-primary" onclick="cmCheck(true)">✓ Correct</button>
        <button class="btn btn-outline" onclick="cmCheck(false)">✗ Wrong</button>
      </div>
      <div id="cm-result" style="margin-top:14px;font-size:0.95rem;min-height:1.4em"></div>
    </div>`;
  }
}
function cmNewDrill(){ _cmDrillIdx = Math.floor(Math.random() * CM_DRILL.length); renderCm(); }
function cmCheck(picked){
  const d = CM_DRILL[_cmDrillIdx];
  const r = document.getElementById('cm-result');
  if(r && r.dataset.answered) return; if(r) r.dataset.answered='1';
  if(picked === d.correct){
    _cmStreak++;
    recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10);
    const fix = d.fix ? ` Fix: <strong>${d.fix}</strong>` : '';
    if(r) r.innerHTML = `<span style="color:#4ade80">✓ Right!</span> ${d.why}.${fix} <span style="color:var(--muted)">streak: ${_cmStreak}</span>`;
  } else {
    _cmStreak = 0;
    const fix = d.fix ? ` Fix: <strong>${d.fix}</strong>` : '';
    if(r) r.innerHTML = `<span style="color:#f87171">✗ Actually ${d.correct?'correct':'wrong'}.</span> ${d.why}.${fix}`;
  }
  setTimeout(cmNewDrill, 2000);
}

// ===== SENTENCE TRANSFORMATION =====
let _stTab = 'browse';
let _stOp = 'all';
let _stDrillIdx = -1;
let _stStreak = 0;

function openSentTransform(){
  if(typeof bumpAchievementCounter === 'function') bumpAchievementCounter('st_open');
  const ov = document.getElementById('st-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setStTab('browse');
}
function closeSentTransform(){ const ov=document.getElementById('st-overlay'); if(ov) ov.style.display='none'; }
function setStTab(t){
  _stTab = t;
  const bar = document.getElementById('st-tab-bar');
  if(bar){
    const tabs = [['browse','📋 Browse'],['rules','📖 Rules'],['drill','🎯 Drill']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_stTab===k?'active':''}" onclick="setStTab('${k}')">${l}</button>`).join('');
  }
  const stats = document.getElementById('st-stats');
  if(stats) stats.textContent = `${ST_TRANSFORMS.length} transformations · streak: ${_stStreak}`;
  renderSt();
}
function renderSt(){
  const c = document.getElementById('st-content'); if(!c) return;
  if(_stTab === 'browse'){
    const ops = ['all', ...Object.keys(ST_OPS)];
    const filterBar = '<div style="display:flex;gap:6px;justify-content:center;flex-wrap:wrap;margin-bottom:12px">' +
      ops.map(k => `<button class="cat-filter ${_stOp===k?'active':''}" onclick="_stOp='${k}';renderSt()">${k==='all'?'all':ST_OPS[k].label}</button>`).join('') + '</div>';
    const items = _stOp === 'all' ? ST_TRANSFORMS : ST_TRANSFORMS.filter(t => t.op === _stOp);
    c.innerHTML = filterBar + '<div style="display:grid;gap:10px">' + items.map(t => `
      <div style="background:var(--card);padding:12px;border-radius:10px">
        <div style="display:flex;gap:6px;align-items:center;margin-bottom:8px">
          <span style="background:var(--accent);color:white;padding:2px 8px;border-radius:6px;font-size:0.75rem">${ST_OPS[t.op].label}</span>
        </div>
        <div style="margin-bottom:4px"><strong>${t.src}</strong> <span style="color:var(--muted);font-size:0.85rem">— ${t.srcEn}</span></div>
        <div style="color:var(--accent);margin-bottom:0">↓</div>
        <div><strong>${t.target}</strong> <span style="color:var(--muted);font-size:0.85rem">— ${t.targetEn}</span></div>
      </div>`).join('') + '</div>';
  } else if(_stTab === 'rules'){
    c.innerHTML = '<div style="display:grid;gap:10px">' + Object.entries(ST_OPS).map(([k,v]) => `
      <div style="background:var(--card);padding:14px;border-radius:10px;border-left:4px solid var(--accent)">
        <div style="font-weight:700;margin-bottom:6px;font-size:1.1rem">${v.label}</div>
        <div style="font-size:0.9rem;line-height:1.5">${v.desc}</div>
      </div>`).join('') + '</div>';
  } else if(_stTab === 'drill'){
    if(_stDrillIdx < 0) stNewDrill();
    const d = ST_TRANSFORMS[_stDrillIdx];
    c.innerHTML = `<div style="background:var(--card);padding:18px;border-radius:12px;text-align:center">
      <div style="color:var(--muted);font-size:0.9rem;margin-bottom:6px">Apply: ${ST_OPS[d.op].label}</div>
      <div style="font-size:1.3rem;margin-bottom:6px"><strong>${d.src}</strong></div>
      <div style="color:var(--muted);font-size:0.85rem;margin-bottom:14px">${d.srcEn}</div>
      <input id="st-input" placeholder="type the transformed sentence" style="padding:10px 14px;font-size:1.05rem;width:100%;max-width:400px;border-radius:8px;border:1px solid var(--border);background:var(--bg);color:var(--text)" onkeydown="if(event.key==='Enter')stCheck()" />
      <div style="margin-top:14px;display:flex;gap:8px;justify-content:center;flex-wrap:wrap">
        <button class="btn btn-primary" onclick="stCheck()">Check</button>
        <button class="btn btn-outline" onclick="stReveal()">Show</button>
        <button class="btn btn-outline" onclick="stNewDrill()">Next →</button>
      </div>
      <div id="st-result" style="margin-top:12px;font-size:0.95rem;min-height:1.4em"></div>
    </div>`;
    setTimeout(() => { const i=document.getElementById('st-input'); if(i) i.focus(); }, 50);
  }
}
function stNewDrill(){ _stDrillIdx = Math.floor(Math.random() * ST_TRANSFORMS.length); renderSt(); }
function stCheck(){
  const inp = document.getElementById('st-input'); if(!inp) return;
  const ans = inp.value.trim().toLowerCase().replace(/[?؟!.]/g, '').replace(/\s+/g,' ');
  const d = ST_TRANSFORMS[_stDrillIdx];
  const correct = d.target.toLowerCase().replace(/[?؟!.]/g, '').replace(/\s+/g,' ');
  const r = document.getElementById('st-result');
  if(ans === correct){
    _stStreak++;
    recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10);
    if(r) r.innerHTML = `<span style="color:#4ade80">✓ ${d.target}</span> = ${d.targetEn} <span style="color:var(--muted)">streak: ${_stStreak}</span>`;
    setTimeout(stNewDrill, 1500);
  } else {
    _stStreak = 0;
    if(r) r.innerHTML = `<span style="color:#f87171">✗ Try again</span>`;
  }
}
function stReveal(){
  const r = document.getElementById('st-result');
  const d = ST_TRANSFORMS[_stDrillIdx];
  if(r) r.innerHTML = `<span style="color:var(--accent)">${d.target}</span> = ${d.targetEn}`;
  _stStreak = 0;
}

