// ===== SPELLING DRILL =====
let _spTab = 'alphabet';
let _spDrillIdx = -1;
let _spWordIdx = -1;
let _spStreak = 0;

function openSpelling(){
  if(typeof bumpAchievementCounter === 'function') bumpAchievementCounter('sp_open');
  const ov = document.getElementById('sp-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setSpTab('alphabet');
}
function closeSpelling(){ const ov=document.getElementById('sp-overlay'); if(ov) ov.style.display='none'; }
function setSpTab(t){
  _spTab = t;
  const bar = document.getElementById('sp-tab-bar');
  if(bar){
    const tabs = [['alphabet','🔠 Alphabet'],['letter','🎯 Letter Drill'],['word','📝 Word Drill']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_spTab===k?'active':''}" onclick="setSpTab('${k}')">${l}</button>`).join('');
  }
  const stats = document.getElementById('sp-stats');
  if(stats) stats.textContent = `${ARABIC_LETTERS.length} letters · ${SPELL_WORDS.length} words · streak: ${_spStreak}`;
  renderSpelling();
}
function renderSpelling(){
  const c = document.getElementById('sp-content'); if(!c) return;
  if(_spTab === 'alphabet'){
    c.innerHTML = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:8px">' +
      ARABIC_LETTERS.map(L => `<div style="background:var(--card);padding:10px;border-radius:8px;text-align:center">
        <div style="font-size:2.4rem;line-height:1;margin-bottom:4px">${L.ar}</div>
        <div style="color:var(--accent);font-weight:600">${L.name}</div>
        <div style="color:var(--muted);font-size:0.8rem">tr: <strong>${L.tr}</strong></div>
        <div style="color:var(--muted);font-size:0.75rem;margin-top:4px">${L.sound}</div>
      </div>`).join('') + '</div>';
  } else if(_spTab === 'letter'){
    if(_spDrillIdx < 0) spNewLetter();
    const L = ARABIC_LETTERS[_spDrillIdx];
    c.innerHTML = `<div style="background:var(--card);padding:18px;border-radius:12px;text-align:center">
      <div style="color:var(--muted);font-size:0.9rem;margin-bottom:6px">Type the transliteration:</div>
      <div style="font-size:5rem;line-height:1;margin-bottom:10px">${L.ar}</div>
      <input id="sp-input" placeholder="e.g. b, 7, kh" style="padding:10px 14px;font-size:1.2rem;width:100%;max-width:240px;border-radius:8px;border:1px solid var(--border);background:var(--bg);color:var(--text);text-align:center" onkeydown="if(event.key==='Enter')spLetterCheck()" />
      <div style="margin-top:14px;display:flex;gap:8px;justify-content:center;flex-wrap:wrap">
        <button class="btn btn-primary" onclick="spLetterCheck()">Check</button>
        <button class="btn btn-outline" onclick="spLetterReveal()">Show</button>
        <button class="btn btn-outline" onclick="spNewLetter()">Next →</button>
      </div>
      <div id="sp-result" style="margin-top:12px;font-size:0.95rem;min-height:1.4em"></div>
    </div>`;
    setTimeout(() => { const i=document.getElementById('sp-input'); if(i) i.focus(); }, 50);
  } else if(_spTab === 'word'){
    if(_spWordIdx < 0) spNewWord();
    const w = SPELL_WORDS[_spWordIdx];
    c.innerHTML = `<div style="background:var(--card);padding:18px;border-radius:12px;text-align:center">
      <div style="color:var(--muted);font-size:0.9rem;margin-bottom:6px">Read & transliterate:</div>
      <div style="font-size:3rem;line-height:1.2;margin-bottom:6px">${w.ar}</div>
      <div style="color:var(--muted);font-size:0.85rem;margin-bottom:14px">means: ${w.en}</div>
      <input id="sp-winput" placeholder="type the chat-alphabet form" style="padding:10px 14px;font-size:1.1rem;width:100%;max-width:280px;border-radius:8px;border:1px solid var(--border);background:var(--bg);color:var(--text);text-align:center" onkeydown="if(event.key==='Enter')spWordCheck()" />
      <div style="margin-top:14px;display:flex;gap:8px;justify-content:center;flex-wrap:wrap">
        <button class="btn btn-primary" onclick="spWordCheck()">Check</button>
        <button class="btn btn-outline" onclick="spWordReveal()">Show</button>
        <button class="btn btn-outline" onclick="spNewWord()">Next →</button>
      </div>
      <div id="sp-wresult" style="margin-top:12px;font-size:0.95rem;min-height:1.4em"></div>
    </div>`;
    setTimeout(() => { const i=document.getElementById('sp-winput'); if(i) i.focus(); }, 50);
  }
}
function spNewLetter(){ _spDrillIdx = Math.floor(Math.random() * ARABIC_LETTERS.length); renderSpelling(); }
function spLetterCheck(){
  const inp = document.getElementById('sp-input'); if(!inp) return;
  const ans = inp.value.trim();
  const L = ARABIC_LETTERS[_spDrillIdx];
  const r = document.getElementById('sp-result');
  if(L.accept.some(a => a.toLowerCase() === ans.toLowerCase())){
    _spStreak++;
    recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10);
    if(r) r.innerHTML = `<span style="color:#4ade80">✓ ${L.name} = ${L.tr}</span> <span style="color:var(--muted)">streak: ${_spStreak}</span>`;
    setTimeout(spNewLetter, 1000);
  } else {
    _spStreak = 0;
    if(r) r.innerHTML = `<span style="color:#f87171">✗ Try again</span> <span style="color:var(--muted)">accepts: ${L.accept.join(', ')}</span>`;
  }
}
function spLetterReveal(){
  const r = document.getElementById('sp-result');
  const L = ARABIC_LETTERS[_spDrillIdx];
  if(r) r.innerHTML = `<span style="color:var(--accent)">${L.name} = ${L.tr}</span> — ${L.sound}`;
  _spStreak = 0;
}
function spNewWord(){ _spWordIdx = Math.floor(Math.random() * SPELL_WORDS.length); renderSpelling(); }
function spWordCheck(){
  const inp = document.getElementById('sp-winput'); if(!inp) return;
  const ans = inp.value.trim().toLowerCase();
  const w = SPELL_WORDS[_spWordIdx];
  const r = document.getElementById('sp-wresult');
  if(ans === w.tr.toLowerCase()){
    _spStreak++;
    recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10);
    if(r) r.innerHTML = `<span style="color:#4ade80">✓ ${w.tr}</span> = ${w.en} <span style="color:var(--muted)">streak: ${_spStreak}</span>`;
    setTimeout(spNewWord, 1200);
  } else {
    _spStreak = 0;
    if(r) r.innerHTML = `<span style="color:#f87171">✗ Try again</span>`;
  }
}
function spWordReveal(){
  const r = document.getElementById('sp-wresult');
  const w = SPELL_WORDS[_spWordIdx];
  if(r) r.innerHTML = `<span style="color:var(--accent)">${w.tr}</span> = ${w.en}`;
  _spStreak = 0;
}

// ===== STORY COMPREHENSION =====
let _scStoryIdx = 0;
let _scTab = 'read';
let _scAnswers = {};
let _scShowTr = false;
let _scShowEn = false;

function openStories(){
  if(typeof bumpAchievementCounter === 'function') bumpAchievementCounter('sc_open');
  const ov = document.getElementById('sc-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _scStoryIdx = 0; _scAnswers = {};
  setScTab('read');
}
function closeStories(){ const ov=document.getElementById('sc-overlay'); if(ov) ov.style.display='none'; }
function setScTab(t){
  _scTab = t;
  const bar = document.getElementById('sc-tab-bar');
  if(bar){
    const tabs = [['read','📖 Read'],['quiz','❓ Quiz']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_scTab===k?'active':''}" onclick="setScTab('${k}')">${l}</button>`).join('');
  }
  const stats = document.getElementById('sc-stats');
  if(stats) stats.textContent = `Story ${_scStoryIdx + 1}/${READING_STORIES.length}`;
  renderStories();
}
function renderStories(){
  const c = document.getElementById('sc-content'); if(!c) return;
  const s = READING_STORIES[_scStoryIdx];
  const navBar = `<div style="display:flex;gap:6px;justify-content:center;margin-bottom:12px;flex-wrap:wrap">${READING_STORIES.map((st,i) => `<button class="cat-filter ${i===_scStoryIdx?'active':''}" onclick="_scStoryIdx=${i};_scAnswers={};renderStories()">${i+1}. ${st.title.split(' — ')[1]||st.title}</button>`).join('')}</div>`;
  if(_scTab === 'read'){
    c.innerHTML = navBar + `<div style="background:var(--card);padding:14px;border-radius:12px">
      <div style="font-weight:700;text-align:center;margin-bottom:14px;font-size:1.1rem">${s.title}</div>
      <div style="display:flex;gap:6px;justify-content:center;margin-bottom:14px;flex-wrap:wrap">
        <button class="cat-filter ${_scShowTr?'active':''}" onclick="_scShowTr=!_scShowTr;renderStories()">${_scShowTr?'Hide':'Show'} translit</button>
        <button class="cat-filter ${_scShowEn?'active':''}" onclick="_scShowEn=!_scShowEn;renderStories()">${_scShowEn?'Hide':'Show'} English</button>
      </div>
      <div style="display:flex;flex-direction:column;gap:10px">
        ${s.ar.map((line,i) => `<div style="background:var(--bg);padding:10px;border-radius:8px">
          <div style="font-size:1.15rem">${line}</div>
          ${_scShowTr?`<div style="color:var(--accent);font-size:0.95rem;margin-top:4px">${s.tr[i]}</div>`:''}
          ${_scShowEn?`<div style="color:var(--muted);font-size:0.9rem;margin-top:4px">${s.en[i]}</div>`:''}
        </div>`).join('')}
      </div>
      <div style="text-align:center;margin-top:14px"><button class="btn btn-primary" onclick="setScTab('quiz')">Take Quiz →</button></div>
    </div>`;
  } else if(_scTab === 'quiz'){
    c.innerHTML = navBar + `<div style="background:var(--card);padding:14px;border-radius:12px">
      <div style="font-weight:700;text-align:center;margin-bottom:14px">${s.title}</div>
      ${s.questions.map((q,qi) => {
        const picked = _scAnswers[qi];
        return `<div style="background:var(--bg);padding:12px;border-radius:8px;margin-bottom:10px">
          <div style="font-weight:600;margin-bottom:8px">${qi+1}. ${q.q}</div>
          <div style="display:flex;flex-direction:column;gap:6px">
            ${q.opts.map((o,oi) => {
              let bg = '';
              if(picked !== undefined){
                if(oi === q.ans) bg = 'background:#4ade8033;border:1px solid #4ade80';
                else if(oi === picked) bg = 'background:#f8717133;border:1px solid #f87171';
              }
              return `<button class="btn btn-outline" style="text-align:left;padding:8px 10px;${bg}" onclick="scAnswer(${qi},${oi})" ${picked!==undefined?'disabled':''}>${o}</button>`;
            }).join('')}
          </div>
        </div>`;
      }).join('')}
      <div style="text-align:center;margin-top:10px">
        <button class="btn btn-primary" onclick="_scStoryIdx=(_scStoryIdx+1)%READING_STORIES.length;_scAnswers={};setScTab('read')">Next story →</button>
      </div>
    </div>`;
  }
}
function scAnswer(qi, oi){ _scAnswers[qi] = oi; renderStories(); }

