function renderPe(){
  const c = document.getElementById('pe-content'); if(!c) return;
  if(_peTab === 'browse'){
    c.innerHTML = '<div style="display:grid;gap:10px">' + POLITENESS_FORMS.map(p => `
      <div style="background:var(--card);padding:12px;border-radius:10px">
        <div style="font-weight:600;margin-bottom:8px;font-size:0.95rem">📍 ${p.sit}</div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px">
          <div style="background:#f59e0b33;padding:8px;border-radius:6px">
            <div style="font-size:0.7rem;color:#f59e0b;margin-bottom:2px">INFORMAL</div>
            <strong>${p.informal}</strong>
          </div>
          <div style="background:#3b82f633;padding:8px;border-radius:6px">
            <div style="font-size:0.7rem;color:#3b82f6;margin-bottom:2px">POLITE</div>
            <strong>${p.polite}</strong>
          </div>
        </div>
        <div style="font-size:0.85rem;color:var(--muted);background:var(--bg);padding:8px;border-radius:6px">💡 ${p.note}</div>
      </div>`).join('') + '</div>';
  } else {
    if(_peDrillIdx < 0) peNewDrill();
    const d = PE_DRILL[_peDrillIdx];
    c.innerHTML = `<div style="background:var(--card);padding:18px;border-radius:12px;text-align:center">
      <div style="color:var(--muted);font-size:0.9rem;margin-bottom:6px">Pick the polite response:</div>
      <div style="font-size:1.15rem;margin-bottom:14px;background:var(--bg);padding:12px;border-radius:8px">📍 ${d.sit}</div>
      <div style="display:flex;flex-direction:column;gap:8px;max-width:420px;margin:0 auto">
        ${d.wrong.map((o,i) => `<button class="btn btn-outline" style="padding:10px;text-align:left" onclick="peCheck(${i})">${o}</button>`).join('')}
      </div>
      <div id="pe-result" style="margin-top:14px;font-size:0.95rem;min-height:1.4em"></div>
    </div>`;
  }
}
function peNewDrill(){
  _peDrillIdx = Math.floor(Math.random() * PE_DRILL.length);
  // shuffle wrong opts (keep correct index aligned)
  const d = PE_DRILL[_peDrillIdx];
  const correctVal = d.wrong[d.correct];
  d.wrong = d.wrong.sort(() => Math.random() - 0.5);
  d.correct = d.wrong.indexOf(correctVal);
  renderPe();
}
function peCheck(picked){
  const d = PE_DRILL[_peDrillIdx];
  const r = document.getElementById('pe-result');
  if(r && r.dataset.answered) return; if(r) r.dataset.answered='1';
  if(picked === d.correct){
    _peStreak++;
    recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10);
    if(r) r.innerHTML = `<span style="color:#4ade80">✓ Right!</span> <span style="color:var(--muted)">streak: ${_peStreak}</span>`;
    setTimeout(peNewDrill, 1100);
  } else {
    _peStreak = 0;
    if(r) r.innerHTML = `<span style="color:#f87171">✗ Polite: ${d.wrong[d.correct]}</span>`;
    setTimeout(peNewDrill, 1800);
  }
}

