// ===== FREQUENCY TIER =====
let _ftTab = 'browse';
let _ftTier = 'all';
let _ftDrillIdx = -1;
let _ftStreak = 0;

function openFreqTier(){
  if(typeof bumpAchievementCounter === 'function') bumpAchievementCounter('ft_open');
  const ov = document.getElementById('ft-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setFtTab('browse');
}
function closeFreqTier(){ const ov=document.getElementById('ft-overlay'); if(ov) ov.style.display='none'; }
function setFtTab(t){
  _ftTab = t;
  const bar = document.getElementById('ft-tab-bar');
  if(bar){
    const tabs = [['browse','📋 Ranked'],['drill','🎯 Tier Drill']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_ftTab===k?'active':''}" onclick="setFtTab('${k}')">${l}</button>`).join('');
  }
  const stats = document.getElementById('ft-stats');
  if(stats) stats.textContent = `${FREQ_WORDS.length} essentials · streak: ${_ftStreak}`;
  renderFt();
}
function renderFt(){
  const c = document.getElementById('ft-content'); if(!c) return;
  if(_ftTab === 'browse'){
    const tiers = ['all','1','2','3'];
    const filterBar = '<div style="display:flex;gap:6px;justify-content:center;flex-wrap:wrap;margin-bottom:12px">' +
      tiers.map(k => `<button class="cat-filter ${_ftTier===k?'active':''}" onclick="_ftTier='${k}';renderFt()">${k==='all'?'all':'Tier '+k}</button>`).join('') + '</div>';
    const items = _ftTier === 'all' ? FREQ_WORDS : FREQ_WORDS.filter(i => String(i.tier) === _ftTier);
    const tierColor = (t) => t === 1 ? '#4ade80' : t === 2 ? '#3b82f6' : '#f59e0b';
    c.innerHTML = filterBar + '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:6px">' +
      items.map((w,i) => `<div style="background:var(--card);padding:8px 10px;border-radius:8px;border-left:3px solid ${tierColor(w.tier)}">
        <div style="display:flex;justify-content:space-between;align-items:baseline">
          <strong>${w.tr}</strong>
          <span style="font-size:0.7rem;color:var(--muted)">T${w.tier} · ${w.pos}</span>
        </div>
        <div style="font-size:0.8rem;color:var(--muted)">${w.en}</div>
        <div style="font-size:1rem">${w.ar}</div>
      </div>`).join('') + '</div>';
  } else {
    if(_ftDrillIdx < 0) ftNewDrill();
    const w = FREQ_WORDS[_ftDrillIdx];
    c.innerHTML = `<div style="background:var(--card);padding:18px;border-radius:12px;text-align:center">
      <div style="color:var(--muted);font-size:0.9rem;margin-bottom:6px">What tier is this word?</div>
      <div style="font-size:1.6rem;margin-bottom:4px"><strong>${w.tr}</strong></div>
      <div style="color:var(--muted);font-size:0.85rem;margin-bottom:14px">${w.en} · ${w.pos}</div>
      <div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap">
        <button class="btn btn-outline" style="background:#4ade8033" onclick="ftCheck(1)">Tier 1<br><span style="font-size:0.7rem">critical</span></button>
        <button class="btn btn-outline" style="background:#3b82f633" onclick="ftCheck(2)">Tier 2<br><span style="font-size:0.7rem">daily</span></button>
        <button class="btn btn-outline" style="background:#f59e0b33" onclick="ftCheck(3)">Tier 3<br><span style="font-size:0.7rem">situational</span></button>
      </div>
      <div id="ft-result" style="margin-top:14px;font-size:0.95rem;min-height:1.4em"></div>
    </div>`;
  }
}
function ftNewDrill(){ _ftDrillIdx = Math.floor(Math.random() * FREQ_WORDS.length); renderFt(); }
function ftCheck(picked){
  const w = FREQ_WORDS[_ftDrillIdx];
  const r = document.getElementById('ft-result');
  if(r && r.dataset.answered) return; if(r) r.dataset.answered='1';
  if(picked === w.tier){
    _ftStreak++;
    recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10);
    if(r) r.innerHTML = `<span style="color:#4ade80">✓ Tier ${w.tier}!</span> <span style="color:var(--muted)">streak: ${_ftStreak}</span>`;
    setTimeout(ftNewDrill, 900);
  } else {
    _ftStreak = 0;
    if(r) r.innerHTML = `<span style="color:#f87171">✗ Was Tier ${w.tier}</span>`;
    setTimeout(ftNewDrill, 1500);
  }
}

// ===== ACTIVE RECALL =====
let _arIdx = -1;
let _arSeen = 0;
let _arRight = 0;
let _arMissed = []; // indices into FREQ_WORDS
let _arShowAns = false;
let _arDirection = 'en2tr'; // or 'tr2en', 'ar2en'

function openActiveRecall(){
  if(typeof bumpAchievementCounter === 'function') bumpAchievementCounter('ar_open');
  const ov = document.getElementById('ar-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _arSeen = 0; _arRight = 0; _arMissed = []; _arShowAns = false;
  arNew();
  renderAr();
}
function closeActiveRecall(){ const ov=document.getElementById('ar-overlay'); if(ov) ov.style.display='none'; }
function renderAr(){
  const bar = document.getElementById('ar-tab-bar');
  if(bar){
    const dirs = [['en2tr','EN → tr'],['tr2en','tr → EN'],['ar2en','AR → EN']];
    bar.innerHTML = dirs.map(([k,l]) => `<button class="cat-filter ${_arDirection===k?'active':''}" onclick="_arDirection='${k}';arNew();renderAr()">${l}</button>`).join('') + (_arMissed.length > 0 ? `<button class="cat-filter" onclick="arReviewMissed()">↻ Review missed (${_arMissed.length})</button>` : '');
  }
  const stats = document.getElementById('ar-stats');
  const acc = _arSeen ? Math.round(100 * _arRight / _arSeen) : 0;
  if(stats) stats.textContent = `${_arRight}/${_arSeen} (${acc}%) · missed: ${_arMissed.length}`;
  const c = document.getElementById('ar-content'); if(!c) return;
  if(_arIdx < 0){ arNew(); }
  const w = FREQ_WORDS[_arIdx];
  let prompt = '', answer = '';
  if(_arDirection === 'en2tr'){ prompt = w.en; answer = w.tr; }
  else if(_arDirection === 'tr2en'){ prompt = w.tr; answer = w.en; }
  else { prompt = w.ar; answer = `${w.tr} = ${w.en}`; }
  c.innerHTML = `<div style="background:var(--card);padding:24px;border-radius:14px;text-align:center">
    <div style="color:var(--muted);font-size:0.85rem;margin-bottom:8px">Recall:</div>
    <div style="font-size:2rem;margin-bottom:14px">${prompt}</div>
    ${_arShowAns ? `<div style="background:var(--bg);padding:12px;border-radius:8px;margin-bottom:14px"><strong style="font-size:1.3rem">${answer}</strong></div>` : '<div style="color:var(--muted);margin-bottom:14px">— think first, then reveal —</div>'}
    <div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap">
      ${!_arShowAns ? `<button class="btn btn-primary" onclick="_arShowAns=true;renderAr()">Reveal</button>` : `
        <button class="btn btn-outline" style="background:#4ade8033" onclick="arGrade(true)">✓ Got it</button>
        <button class="btn btn-outline" style="background:#f8717133" onclick="arGrade(false)">✗ Missed</button>
      `}
    </div>
  </div>`;
}
function arNew(){
  _arIdx = Math.floor(Math.random() * FREQ_WORDS.length);
  _arShowAns = false;
}
function arGrade(right){
  _arSeen++;
  if(right) _arRight++;
  else if(!_arMissed.includes(_arIdx)) _arMissed.push(_arIdx);
  arNew();
  renderAr();
}
function arReviewMissed(){
  if(_arMissed.length === 0) return;
  const next = _arMissed.shift();
  _arIdx = next;
  _arShowAns = false;
  renderAr();
}

// ===== PAST NARRATIVE BUILDER =====
let _pnIdx = 0;
let _pnPicked = []; // indices into events
let _pnRevealed = false;

function openPastNarrative(){
  if(typeof bumpAchievementCounter === 'function') bumpAchievementCounter('pn_open');
  const ov = document.getElementById('pn-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _pnIdx = 0; _pnPicked = []; _pnRevealed = false;
  renderPn();
}
function closePastNarrative(){ const ov=document.getElementById('pn-overlay'); if(ov) ov.style.display='none'; }
function renderPn(){
  const c = document.getElementById('pn-content'); if(!c) return;
  const stats = document.getElementById('pn-stats');
  if(stats) stats.textContent = `Narrative ${_pnIdx + 1} / ${PAST_NARRATIVES.length}`;
  const bar = document.getElementById('pn-tab-bar');
  if(bar) bar.innerHTML = PAST_NARRATIVES.map((n,i) => `<button class="cat-filter ${i===_pnIdx?'active':''}" onclick="_pnIdx=${i};_pnPicked=[];_pnRevealed=false;renderPn()">${i+1}. ${n.title}</button>`).join('');
  const n = PAST_NARRATIVES[_pnIdx];
  const remaining = n.events.map((_,i) => i).filter(i => !_pnPicked.includes(i));
  c.innerHTML = `<div style="background:var(--card);padding:14px;border-radius:12px">
    <div style="font-weight:700;text-align:center;margin-bottom:14px">${n.title}</div>
    <div style="background:var(--bg);padding:10px;border-radius:8px;margin-bottom:8px;border-left:3px solid #4ade80">
      <div style="font-size:0.7rem;color:#4ade80;margin-bottom:2px">START</div>
      <div>${n.start.ar}</div>
      <div style="color:var(--accent);font-size:0.9rem">${n.start.tr}</div>
      <div style="color:var(--muted);font-size:0.85rem">${n.start.en}</div>
    </div>
    <div style="margin-bottom:8px">
      <div style="color:var(--muted);font-size:0.8rem;margin-bottom:6px">↓ Build the middle (in order):</div>
      ${_pnPicked.map((i,pos) => {
        const e = n.events[i];
        return `<div style="background:#3b82f633;padding:8px 10px;border-radius:6px;margin-bottom:4px">
          <span style="color:#3b82f6;font-weight:700">${pos+1}.</span> ${e.ar} <span style="color:var(--accent);font-size:0.85rem">— ${e.tr}</span>
          <span style="color:var(--muted);font-size:0.8rem">${e.en}</span>
        </div>`;
      }).join('')}
    </div>
    ${remaining.length > 0 && !_pnRevealed ? `<div style="margin-bottom:8px">
      <div style="color:var(--muted);font-size:0.8rem;margin-bottom:6px">Click to add next:</div>
      ${remaining.map(i => {
        const e = n.events[i];
        return `<button class="btn btn-outline" style="display:block;width:100%;text-align:left;margin-bottom:4px;padding:8px 10px" onclick="_pnPicked.push(${i});renderPn()">
          ${e.ar} <span style="color:var(--accent);font-size:0.85rem">— ${e.tr}</span>
          <span style="color:var(--muted);font-size:0.8rem">— ${e.en}</span>
        </button>`;
      }).join('')}
    </div>` : ''}
    <div style="background:var(--bg);padding:10px;border-radius:8px;margin-bottom:14px;border-left:3px solid #f59e0b">
      <div style="font-size:0.7rem;color:#f59e0b;margin-bottom:2px">END</div>
      <div>${n.end.ar}</div>
      <div style="color:var(--accent);font-size:0.9rem">${n.end.tr}</div>
      <div style="color:var(--muted);font-size:0.85rem">${n.end.en}</div>
    </div>
    <div style="display:flex;gap:8px;justify-content:center;flex-wrap:wrap">
      <button class="btn btn-outline" onclick="_pnPicked=[];_pnRevealed=false;renderPn()">↻ Reset</button>
      <button class="btn btn-primary" onclick="_pnIdx=(_pnIdx+1)%PAST_NARRATIVES.length;_pnPicked=[];_pnRevealed=false;renderPn()">Next narrative →</button>
    </div>
  </div>`;
}

