function chNext(){
  const host = document.getElementById('ch-drill-host'); if(!host) return;
  let i; do { i = Math.floor(Math.random()*CH_DRILL.length); } while(i === _chIdx && CH_DRILL.length > 1);
  _chIdx = i;
  const q = CH_DRILL[i];
  host.innerHTML = `<div class="card" style="padding:14px"><div style="font-weight:700;margin-bottom:10px">Lebanese for: <span style="color:var(--accent)">${q.en}</span></div>` +
    q.opts.map((o,k) => `<button class="btn btn-outline" style="display:block;width:100%;text-align:left;margin-bottom:6px" onclick="chCheck(${k})">${o}</button>`).join('') +
    '<div id="ch-fb" style="margin-top:8px;font-weight:600"></div></div>';
}
function chCheck(k){
  const q = CH_DRILL[_chIdx]; const fb = document.getElementById('ch-fb'); if(!fb) return;
  if(k === q.correct){ fb.style.color='#4caf50'; fb.textContent='✓ Correct!'; bumpAchievementCounter && bumpAchievementCounter('ch_correct'); recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10); }
  else { fb.style.color='#e53935'; fb.textContent=`✗ Answer: ${q.opts[q.correct]}`; }
}

// ===== Run #27 — Multi-User Profile System =====
// localStorage namespace wrapper lives in data/run27-data.js (loads first).
// This block adds UI: user picker modal, header pill, user-aware refresh.

function _getUserMgr(){ return window._userMgr; }

function refreshUserPill(){
  const pill = document.getElementById('user-pill'); if(!pill) return;
  const mgr = _getUserMgr(); if(!mgr) return;
  const id = mgr.activeId();
  const u = mgr.list().find(x => x.id === id) || { name:'?', avatar:'👤' };
  pill.innerHTML = u.avatar;
  pill.title = `User: ${u.name} (click to switch)`;
}

function openUserPicker(){
  const ov = document.getElementById('usr-overlay'); if(!ov) return;
  ov.style.display = 'block';
  renderUserPicker();
}
function closeUserPicker(){ const ov = document.getElementById('usr-overlay'); if(ov) ov.style.display = 'none'; }

function renderUserPicker(){
  const c = document.getElementById('usr-content'); if(!c) return;
  const mgr = _getUserMgr(); if(!mgr){ c.innerHTML = '<div style="color:var(--muted)">User manager unavailable.</div>'; return; }
  const users = mgr.list();
  const activeId = mgr.activeId();
  const stats = document.getElementById('usr-stats');
  if(stats) stats.textContent = `${users.length} user${users.length===1?'':'s'}`;
  let html = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:10px;margin-bottom:18px">';
  for(const u of users){
    const isActive = u.id === activeId;
    const xp = parseInt(mgr.rawGet('u_' + u.id + '_la_xp') || '0');
    const sessions = (() => {
      try { return (JSON.parse(mgr.rawGet('u_' + u.id + '_la_session_history') || '[]')).length; } catch(e){ return 0; }
    })();
    html += `<div class="card" style="padding:14px;${isActive ? 'border:2px solid var(--accent);' : 'border:2px solid transparent;'}cursor:pointer" onclick="switchUser('${u.id}')">
      <div style="font-size:2.4rem;text-align:center">${u.avatar||'👤'}</div>
      <div style="font-weight:700;text-align:center;margin-top:4px">${escapeHtml(u.name)}</div>
      <div style="font-size:0.78rem;color:var(--muted);text-align:center;margin-top:2px">XP: ${xp} · ${sessions} sessions</div>
      ${isActive ? '<div style="text-align:center;color:var(--accent);font-size:0.78rem;margin-top:4px">● Active</div>' : ''}
      <div style="display:flex;gap:4px;margin-top:8px;justify-content:center;flex-wrap:wrap">
        <button class="btn btn-outline" style="padding:3px 8px;font-size:0.75rem" onclick="event.stopPropagation();renameUserPrompt('${u.id}')">Rename</button>
        <button class="btn btn-outline" style="padding:3px 8px;font-size:0.75rem" onclick="event.stopPropagation();exportUserDownload('${u.id}')">Export</button>
        ${u.id !== 'default' ? `<button class="btn btn-outline" style="padding:3px 8px;font-size:0.75rem;color:#e53935" onclick="event.stopPropagation();deleteUserConfirm('${u.id}')">Delete</button>` : ''}
      </div>
    </div>`;
  }
  html += '</div>';
  html += '<div class="card" style="padding:14px;margin-bottom:10px"><div style="font-weight:700;margin-bottom:8px">➕ Add new user</div>';
  html += '<input id="usr-new-name" placeholder="Name" style="padding:8px;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);width:60%;margin-right:6px" />';
  html += '<input id="usr-new-avatar" placeholder="🦊" maxlength="2" style="padding:8px;border:1px solid var(--border);border-radius:8px;background:var(--bg);color:var(--fg);width:50px;margin-right:6px;text-align:center;font-size:1.2rem" />';
  html += '<button class="btn" onclick="createUserUI()">Create</button>';
  if(typeof USER_AVATARS !== 'undefined'){
    html += '<div style="margin-top:10px;font-size:0.78rem;color:var(--muted)">Pick avatar:</div><div style="display:flex;flex-wrap:wrap;gap:4px;margin-top:4px">';
    html += USER_AVATARS.map(a => `<button class="btn btn-outline" style="padding:4px 8px;font-size:1.1rem" onclick="document.getElementById('usr-new-avatar').value='${a}'">${a}</button>`).join('');
    html += '</div>';
  }
  html += '</div>';
  html += '<div class="card" style="padding:14px"><div style="font-weight:700;margin-bottom:8px">📥 Import user data</div>';
  html += '<input type="file" id="usr-import-file" accept="application/json,.json" style="margin-bottom:6px" />';
  html += '<button class="btn btn-outline" onclick="importUserUI()">Import file</button>';
  html += '<div style="font-size:0.78rem;color:var(--muted);margin-top:6px">Imports as new user. Won\'t overwrite existing.</div>';
  html += '</div>';
  c.innerHTML = html;
}

function escapeHtml(s){ return String(s||'').replace(/[<>&"']/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&#39;'})[c]); }
function attrArg(v){ return JSON.stringify(v).replace(/"/g, '&quot;'); }

function switchUser(id){
  const mgr = _getUserMgr(); if(!mgr) return;
  if(mgr.activeId() === id){ closeUserPicker(); return; }
  if(!confirm('Switch to this user? The page will reload to apply per-user data.')) return;
  mgr.setActiveId(id);
  // Update lastActive
  const users = mgr.list();
  const u = users.find(x => x.id === id);
  if(u){ u.lastActive = Date.now(); mgr.save(users); }
  location.reload();
}

function createUserUI(){
  const mgr = _getUserMgr(); if(!mgr) return;
  const name = (document.getElementById('usr-new-name')||{}).value || '';
  const avatar = (document.getElementById('usr-new-avatar')||{}).value || '👤';
  if(!name.trim()){ alert('Enter a name'); return; }
  const id = mgr.createUser(name.trim(), avatar.trim() || '👤');
  if(confirm(`User "${name}" created. Switch now?`)){
    mgr.setActiveId(id);
    location.reload();
  } else {
    renderUserPicker();
  }
}

function renameUserPrompt(id){
  const mgr = _getUserMgr(); if(!mgr) return;
  const u = mgr.list().find(x => x.id === id); if(!u) return;
  const name = prompt('New name:', u.name); if(name === null) return;
  const avatar = prompt('Avatar (single emoji or letter):', u.avatar||'👤'); if(avatar === null) return;
  mgr.renameUser(id, name.trim() || u.name, avatar.trim() || u.avatar || '👤');
  renderUserPicker(); refreshUserPill();
}

function deleteUserConfirm(id){
  const mgr = _getUserMgr(); if(!mgr) return;
  if(!confirm('Permanently delete this user and all their progress data?')) return;
  if(!confirm('Are you sure? This cannot be undone.')) return;
  const wasActive = mgr.activeId() === id;
  mgr.deleteUser(id);
  if(wasActive){ location.reload(); return; }
  renderUserPicker(); refreshUserPill();
}

function exportUserDownload(id){
  const mgr = _getUserMgr(); if(!mgr) return;
  const payload = mgr.exportUser(id); if(!payload){ alert('Export failed'); return; }
  try {
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = `lebanese-arabic-user-${id}-${new Date().toISOString().slice(0,10)}.json`;
    document.body.appendChild(a); a.click();
    setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 200);
  } catch(e){
    alert('Could not download. Copy this JSON manually:\n\n' + JSON.stringify(payload).slice(0, 200) + '...');
  }
}

function importUserUI(){
  const mgr = _getUserMgr(); if(!mgr) return;
  const fi = document.getElementById('usr-import-file');
  const f = fi && fi.files && fi.files[0];
  if(!f){ alert('Pick a file first'); return; }
  const r = new FileReader();
  r.onload = function(e){
    try {
      const payload = JSON.parse(e.target.result);
      if(!payload || !payload.user){ alert('Invalid file'); return; }
      const newName = prompt('Import as user name:', payload.user.name + ' (imported)');
      if(newName === null) return;
      const newId = mgr.importUser(payload, { newId: undefined, newName });
      if(newId){
        if(confirm(`Imported as "${newName}". Switch to this user now?`)){
          mgr.setActiveId(newId);
          location.reload();
        } else { renderUserPicker(); }
      } else { alert('Import failed'); }
    } catch(err){ alert('Could not parse file: ' + err.message); }
  };
  r.readAsText(f);
}

// Auto-refresh pill on load
if(typeof window !== 'undefined'){
  if(document.readyState === 'complete' || document.readyState === 'interactive') setTimeout(refreshUserPill, 0);
  else document.addEventListener('DOMContentLoaded', refreshUserPill);
}

// ===== Run #28 — Modern UI/UX Foundation =====

// ---- Toast notifications (replaces ad-hoc alerts) ----
function toast(msg, opts){
  opts = opts || {};
  const host = document.getElementById('toast-host'); if(!host){ console.log('toast:', msg); return; }
  const t = document.createElement('div');
  t.className = 'toast toast-' + (opts.type || 'info');
  const icon = opts.icon || ({success:'✓', error:'✕', warn:'⚠', info:'ℹ'})[opts.type || 'info'] || 'ℹ';
  t.innerHTML = `<span class="toast-icon">${icon}</span><span class="toast-msg"></span>`;
  t.querySelector('.toast-msg').textContent = msg;
  t.onclick = () => dismissToast(t);
  host.appendChild(t);
  requestAnimationFrame(() => t.classList.add('show'));
  const dur = opts.duration || 3200;
  setTimeout(() => dismissToast(t), dur);
  return t;
}
function dismissToast(t){
  if(!t || !t.parentNode) return;
  t.classList.remove('show');
  setTimeout(() => { if(t.parentNode) t.parentNode.removeChild(t); }, 250);
}
function toastSuccess(m, o){ return toast(m, Object.assign({type:'success'}, o||{})); }
function toastError(m, o){ return toast(m, Object.assign({type:'error'}, o||{})); }
function toastWarn(m, o){ return toast(m, Object.assign({type:'warn'}, o||{})); }
function toastInfo(m, o){ return toast(m, Object.assign({type:'info'}, o||{})); }

// ---- Loading helpers ----
function showLoading(containerId, msg){
  const c = document.getElementById(containerId); if(!c) return;
  c.innerHTML = `<div style="display:flex;align-items:center;gap:12px;justify-content:center;padding:30px;color:var(--muted)"><div class="la-spinner"></div><div>${msg||'Loading...'}</div></div>`;
}
function showSkeleton(containerId, lines){
  const c = document.getElementById(containerId); if(!c) return;
  lines = lines || 4;
  let html = '<div style="padding:20px">';
  for(let i = 0; i < lines; i++){
    const w = 60 + Math.random() * 40;
    html += `<div class="la-skeleton" style="width:${w}%"></div>`;
  }
  html += '</div>';
  c.innerHTML = html;
}

