      c.innerHTML = `<div class="card" style="padding:20px;text-align:center"><div style="font-size:1.5rem;margin-bottom:10px">✓ Done</div><div>Score: ${_svDrillScore}/${SV_DRILL.length}</div><button class="btn btn-primary" style="margin-top:14px" onclick="_svDrillIdx=0;_svDrillScore=0;renderSurvival()">Restart</button></div>`;
