  const exes = QFC_EXERCISES.map(e => `<div style="background:var(--card);border:1px solid var(--border);border-radius:10px;padding:10px;margin-bottom:8px">
    <div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap">
      <span dir="rtl">${_qfcEscape(e.prompt_ar)}</span>
      <span style="color:var(--muted);font-size:0.8rem">${_qfcEscape(e.prompt_tr)}</span>
      <button class="btn btn-outline" style="padding:2px 6px;font-size:0.7rem" onclick="speak(${attrArg(e.prompt_ar)})">🔊</button>
      <span style="color:var(--muted)">→</span>
      <span dir="rtl" style="color:var(--accent2);font-weight:600">${_qfcEscape(e.question_ar)}</span>
      <span style="color:var(--muted);font-size:0.8rem">${_qfcEscape(e.question_tr)}</span>
      <button class="btn btn-outline" style="padding:2px 6px;font-size:0.7rem" onclick="speak(${attrArg(e.question_ar)})">🔊</button>
    </div>
    <div style="color:var(--muted);font-size:0.78rem;margin-top:4px"><b>${_qfcEscape(e.wh)}</b> · target: ${_qfcEscape(e.target)}</div>
  </div>`).join('');
  root.innerHTML = `<div style="font-weight:600;margin-bottom:10px">Wh-words (${QFC_WHWORDS.length})</div>${wh}<div style="font-weight:600;margin:18px 0 10px">All exercises (${QFC_EXERCISES.length})</div>${exes}`;
