// ============================================================
// Run #108 — Oath & Emphasis Coach (OTH)
// ============================================================
// Distinct from SA (conventional acknowledgments), IDM (proverbs),
// and STC (2-turn scripts): these are single speech-act intensifiers.
// Drill gate: given a situation, pick the Lebanese phrase that fits
// the register. Distractors drawn from the same OTH_CATS category so
// every wrong choice is semantically plausible — the learner must
// discriminate between oath/emphasis/softener/filler within the field.
let _othTab = 'drill';
let _othFilter = 'all';
let _othIdx = 0;
let _othOrder = [];
let _othOptions = [];
let _othLocked = false;
let _othScore = { correct: 0, wrong: 0, answered: new Set() };

function _othEscape(s){ return String(s||'').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function _othShuffle(arr){ const a = arr.slice(); for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); const t=a[i]; a[i]=a[j]; a[j]=t; } return a; }
function _othItemById(id){ return OTH_ITEMS.find(it => it.id === id); }
function _othCatById(id){ return OTH_CATS.find(c => c.id === id); }
function _othFilteredExercises(){
  if(_othFilter === 'all') return OTH_EXERCISES.slice();
  return OTH_EXERCISES.filter(ex => {
    const it = _othItemById(ex.itemId);
    return it && it.cat === _othFilter;
  });
}
function _othCurrentExercise(){
  const id = _othOrder[_othIdx];
  return OTH_EXERCISES.find(e => e.id === id);
}
function _othBuildOptions(ex){
  const target = _othItemById(ex.itemId);
  if(!target) return [];
  const sameCat = OTH_ITEMS.filter(it => it.cat === target.cat && it.id !== target.id);
  const distractors = _othShuffle(sameCat).slice(0, 3);
  const pool = [target].concat(distractors);
  return _othShuffle(pool).map(it => ({
    id: it.id, ar: it.ar, tr: it.tr, en: it.en, note: it.note,
    example: it.example, example_tr: it.example_tr, example_en: it.example_en,
    correct: it.id === target.id
  }));
}
function _othLoadCurrent(){
  const ex = _othCurrentExercise();
  if(!ex) return;
  _othOptions = _othBuildOptions(ex);
  _othLocked = false;
}

function openOth(){
  if(typeof bumpAchievementCounter === 'function') bumpAchievementCounter('oth_open');
  const ov = document.getElementById('oth-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _othFilter = 'all';
  _othOrder = _othShuffle(_othFilteredExercises().map(e => e.id));
  _othIdx = 0;
  _othScore = { correct: 0, wrong: 0, answered: new Set() };
  _othLoadCurrent();
  setOthTab('drill');
}
function closeOth(){ const ov = document.getElementById('oth-overlay'); if(ov) ov.style.display='none'; }

function setOthTab(t){
  _othTab = t;
  const bar = document.getElementById('oth-tab-bar');
  if(bar){
    const tabs = [['drill','🎯 Drill'],['browse','📋 Browse'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_othTab===k?'active':''}" onclick="setOthTab('${k}')">${l}</button>`).join('');
  }
  renderOth();
}

function othSetFilter(catId){
  _othFilter = catId;
  _othOrder = _othShuffle(_othFilteredExercises().map(e => e.id));
  _othIdx = 0;
  _othScore = { correct: 0, wrong: 0, answered: new Set() };
  _othLoadCurrent();
  renderOth();
}

function _othRenderFilters(){
  const cats = [['all','🌐 All']].concat(OTH_CATS.map(c => [c.id, c.label]));
  return '<div style="display:flex;gap:6px;justify-content:center;margin-bottom:12px;flex-wrap:wrap">' +
    cats.map(([k,l]) => `<button class="cat-filter ${_othFilter===k?'active':''}" onclick="othSetFilter('${k}')">${_othEscape(l)}</button>`).join('') +
    '</div>';
}

function _othRenderDrill(){
  const stats = document.getElementById('oth-stats');
  if(stats) stats.textContent = `${_othScore.correct}✓ · ${_othScore.wrong}✗ · ${_othIdx+1}/${_othOrder.length}`;
  const ex = _othCurrentExercise();
  if(!ex){
    return _othRenderFilters() +
      '<div style="text-align:center;padding:40px;color:var(--muted)">No exercises in this category. Pick another filter.</div>';
  }
  const target = _othItemById(ex.itemId);
  const cat = target ? _othCatById(target.cat) : null;
  let html = _othRenderFilters();
  html += `<div style="background:var(--card);border-radius:12px;padding:18px;margin-bottom:14px">
    <div style="color:var(--muted);font-size:0.82rem;margin-bottom:6px">${cat?_othEscape(cat.label):''}</div>
    <div style="font-size:1.05rem;line-height:1.5">${_othEscape(ex.prompt)}</div>
  </div>`;
  html += '<div style="display:grid;gap:10px;margin-bottom:14px">';
  _othOptions.forEach((opt, i) => {
    let bg = 'var(--card)', border = '1px solid var(--border)';
    if(_othLocked){
      if(opt.correct){ bg = 'rgba(34,197,94,0.15)'; border = '2px solid #22c55e'; }
      else if(opt._chosen){ bg = 'rgba(239,68,68,0.15)'; border = '2px solid #ef4444'; }
    }
    let reveal = '';
    if(_othLocked && opt.correct){
      reveal = `<div style="color:var(--muted);font-size:0.82rem;margin-top:8px;line-height:1.4"><em>Note:</em> ${_othEscape(opt.note)}</div>`;
      if(opt.example){
        reveal += `<div style="margin-top:6px;padding-top:6px;border-top:1px dashed var(--border);font-size:0.85rem">
          <div style="direction:rtl;text-align:right">${_othEscape(opt.example)}</div>
          <div style="color:#3b82f6">${_othEscape(opt.example_tr)}</div>
          <div style="color:var(--muted)">${_othEscape(opt.example_en)}</div>
        </div>`;
      }
    }
    html += `<button onclick="othAnswer(${i})" style="text-align:left;padding:14px;background:${bg};border:${border};border-radius:10px;cursor:${_othLocked?'default':'pointer'};font-family:inherit;color:var(--text)">
      <div style="font-size:1.15rem;direction:rtl;text-align:right;margin-bottom:4px">${_othEscape(opt.ar)}</div>
      <div style="color:var(--accent,#3b82f6);font-weight:600">${_othEscape(opt.tr)}</div>
      <div style="color:var(--muted);font-size:0.85rem">${_othEscape(opt.en)}</div>
      ${reveal}
    </button>`;
  });
  html += '</div>';
  if(_othLocked){
    html += `<button class="btn btn-primary" onclick="othNext()" style="width:100%">Next →</button>`;
  }
  return html;
}

function _othRenderBrowse(){
  let html = _othRenderFilters();
  const items = _othFilter === 'all' ? OTH_ITEMS : OTH_ITEMS.filter(it => it.cat === _othFilter);
  html += '<div style="display:grid;gap:10px">';
  items.forEach(it => {
    const cat = _othCatById(it.cat);
    html += `<div style="background:var(--card);border-radius:10px;padding:14px">
      <div style="display:flex;justify-content:space-between;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:4px">
        <div style="color:var(--muted);font-size:0.82rem">${cat?_othEscape(cat.label):''}</div>
        <div style="color:var(--muted);font-size:0.75rem">${_othEscape(it.id)}</div>
      </div>
      <div style="font-size:1.2rem;direction:rtl;text-align:right;display:flex;align-items:center;gap:6px"><button class="speak-btn" style="width:26px;height:26px;font-size:0.8rem;flex-shrink:0" onclick="speak('${it.ar.replace(/'/g,"\\'")}')">🔊</button>${_othEscape(it.ar)}</div>
      <div style="color:var(--accent,#3b82f6);font-weight:600">${_othEscape(it.tr)}</div>
      <div style="color:var(--muted)">${_othEscape(it.en)}</div>
      <div style="margin-top:8px;color:var(--muted);font-size:0.88rem;line-height:1.5">${_othEscape(it.note)}</div>
      <div style="margin-top:6px;padding-top:6px;border-top:1px dashed var(--border);font-size:0.9rem">
        <div style="direction:rtl;text-align:right">${_othEscape(it.example)}</div>
        <div style="color:#3b82f6">${_othEscape(it.example_tr)}</div>
        <div style="color:var(--muted);font-size:0.85rem">${_othEscape(it.example_en)}</div>
      </div>
    </div>`;
  });
  html += '</div>';
  return html;
}

function _othRenderTips(){
  let html = '<div style="display:grid;gap:10px">';
  OTH_TIPS.forEach(t => {
    html += `<div style="background:var(--card);border-radius:10px;padding:14px;font-size:0.95rem;line-height:1.5">${_othEscape(t)}</div>`;
  });
  html += '</div>';
  return html;
}

function renderOth(){
  const content = document.getElementById('oth-content');
  if(!content) return;
  if(_othTab === 'drill') content.innerHTML = _othRenderDrill();
  else if(_othTab === 'browse') content.innerHTML = _othRenderBrowse();
  else if(_othTab === 'tips') content.innerHTML = _othRenderTips();
}

function othAnswer(idx){
  if(_othLocked) return;
  const opt = _othOptions[idx];
  if(!opt) return;
  opt._chosen = true;
  _othLocked = true;
  const ex = _othCurrentExercise();
  if(ex) _othScore.answered.add(ex.id);
  if(opt.correct){
    _othScore.correct++;
    if(typeof bumpAchievementCounter === 'function') bumpAchievementCounter('oth_correct');
    recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10);
  } else {
    _othScore.wrong++;
  }
  renderOth();
}

function othNext(){
  _othIdx++;
  if(_othIdx >= _othOrder.length){
    _othOrder = _othShuffle(_othFilteredExercises().map(e => e.id));
    _othIdx = 0;
  }
  _othLoadCurrent();
  renderOth();
}

// Self-register into TOPICS_CATEGORIES > conv.
(function(){
  try {
    if(typeof TOPICS_CATEGORIES === 'undefined') return;
    const conv = TOPICS_CATEGORIES.find(c => c.id === 'conv');
    if(!conv) return;
    if(!conv.items.find(it => it.fn === 'openOth')){
      conv.items.push({ label:'🤝 Oaths & Emphasis', fn:'openOth', desc:'wallah / 3ala rasi / law sama7et / yalla — register drills' });
    }
  } catch(e){}
})();

// ─────────────────────────────────────────────────────────────────────────
// Run #111 — Sentence Order drill
// Drill: shuffled word tokens; user clicks in order to reconstruct sentence.
// State per-question: _sorCurrent (sentence), _sorTokens (shuffled words),
// _sorPicks (indices picked so far), _sorLocked (true after full pick).
// ─────────────────────────────────────────────────────────────────────────

let _sorIdx = 0;
let _sorOrder = [];
let _sorFilter = 'all';
let _sorTab = 'drill';
let _sorTokens = [];
let _sorPicks = [];
let _sorLocked = false;
let _sorScore = { correct: 0, wrong: 0, answered: new Set() };

function _sorEscape(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
function _sorShuffle(arr){ const a = arr.slice(); for(let i=a.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); const t=a[i]; a[i]=a[j]; a[j]=t; } return a; }
function _sorFilteredSentences(){
  if(_sorFilter === 'all') return SOR_SENTENCES.slice();
  return SOR_SENTENCES.filter(s => s.cat === _sorFilter);
}
function _sorCurrentSentence(){
  const id = _sorOrder[_sorIdx];
  return SOR_SENTENCES.find(s => s.id === id);
}
function _sorBuildTokens(sent){
  const words = String(sent.ar || '').split(/\s+/).filter(Boolean);
  // If only 1-2 tokens, pad with original order (edge case; shouldn't happen with curated data).
  let shuffled = _sorShuffle(words);
  // Guard: ensure shuffled != original when >=2 tokens (avoid trivial "already correct" state).
  if(words.length >= 2 && shuffled.every((w,i) => w === words[i])){
    shuffled = shuffled.reverse();
  }
  return shuffled;
}
function _sorLoadCurrent(){
  const sent = _sorCurrentSentence();
  if(!sent){ _sorTokens = []; _sorPicks = []; _sorLocked = false; return; }
  _sorTokens = _sorBuildTokens(sent);
  _sorPicks = [];
  _sorLocked = false;
}

function openSor(){
  if(typeof bumpAchievementCounter === 'function') bumpAchievementCounter('sor_open');
  const ov = document.getElementById('sor-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _sorFilter = 'all';
  _sorOrder = _sorShuffle(_sorFilteredSentences().map(s => s.id));
  _sorIdx = 0;
  _sorScore = { correct: 0, wrong: 0, answered: new Set() };
  _sorLoadCurrent();
  setSorTab('drill');
}
function closeSor(){ const ov = document.getElementById('sor-overlay'); if(ov) ov.style.display='none'; }

function setSorTab(t){
  _sorTab = t;
  const bar = document.getElementById('sor-tab-bar');
  if(bar){
    const tabs = [['drill','🎯 Drill'],['browse','📋 Browse'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_sorTab===k?'active':''}" onclick="setSorTab('${k}')">${l}</button>`).join('');
  }
  renderSor();
}

function sorSetFilter(catId){
  _sorFilter = catId;
  _sorOrder = _sorShuffle(_sorFilteredSentences().map(s => s.id));
  _sorIdx = 0;
  _sorScore = { correct: 0, wrong: 0, answered: new Set() };
  _sorLoadCurrent();
  renderSor();
}

function _sorRenderFilters(){
  const cats = [['all','🌐 All']].concat(SOR_CATS.map(c => [c.id, c.label]));
  return '<div style="display:flex;gap:6px;justify-content:center;margin-bottom:12px;flex-wrap:wrap">' +
    cats.map(([k,l]) => `<button class="cat-filter ${_sorFilter===k?'active':''}" onclick="sorSetFilter('${k}')">${_sorEscape(l)}</button>`).join('') +
    '</div>';
}

function _sorRenderDrill(){
  const stats = document.getElementById('sor-stats');
  if(stats) stats.textContent = `${_sorScore.correct}✓ · ${_sorScore.wrong}✗ · ${_sorIdx+1}/${Math.max(1,_sorOrder.length)}`;
  const sent = _sorCurrentSentence();
  if(!sent){
    return _sorRenderFilters() +
      '<div style="text-align:center;padding:40px;color:var(--muted)">No sentences in this category.</div>';
  }
  let html = _sorRenderFilters();
  html += '<div style="background:var(--card);border:1px solid var(--border);border-radius:12px;padding:16px;margin-bottom:14px">';
  html += '<div style="color:var(--muted);font-size:0.85rem;margin-bottom:6px">Rebuild in Lebanese word order:</div>';
  html += `<div style="font-size:1.1rem;margin-bottom:4px">${_sorEscape(sent.en)}</div>`;
  if(_sorLocked){
    html += `<div style="color:var(--muted);font-size:0.85rem;font-family:monospace">${_sorEscape(sent.tr)}</div>`;
  }
  html += '</div>';

  // Reconstruction area (user picks shown here)
  html += '<div style="background:var(--card2);border:1px dashed var(--border);border-radius:10px;padding:14px;min-height:52px;display:flex;flex-wrap:wrap;gap:8px;justify-content:center;direction:rtl;margin-bottom:12px">';
  if(_sorPicks.length === 0){
    html += '<span style="color:var(--muted);font-size:0.85rem;align-self:center;direction:ltr">(click tokens below in order)</span>';
  } else {
    _sorPicks.forEach((tokIdx, i) => {
      const w = _sorTokens[tokIdx];
      html += `<span style="background:var(--bg);border:1px solid var(--border);border-radius:8px;padding:6px 12px;font-family:'Segoe UI','Noto Naskh Arabic','Amiri',system-ui,sans-serif;font-size:1.1rem;unicode-bidi:plaintext">${_sorEscape(w)}</span>`;
    });
  }
  html += '</div>';

  // Token pool
  html += '<div style="display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin-bottom:12px;direction:rtl">';
  _sorTokens.forEach((w, i) => {
    const used = _sorPicks.indexOf(i) >= 0;
    const disabled = used || _sorLocked;
    const bg = used ? 'var(--card2)' : 'var(--card)';
    const opacity = used ? '0.35' : '1';
    const cursor = disabled ? 'default' : 'pointer';
    html += `<button onclick="sorPick(${i})" ${disabled ? 'disabled' : ''} style="background:${bg};border:1px solid var(--border);border-radius:10px;padding:10px 16px;font-family:'Segoe UI','Noto Naskh Arabic','Amiri',system-ui,sans-serif;font-size:1.15rem;cursor:${cursor};opacity:${opacity};color:var(--text);unicode-bidi:plaintext">${_sorEscape(w)}</button>`;
  });
  html += '</div>';

  // Action buttons
  html += '<div style="display:flex;gap:8px;justify-content:center;margin-bottom:8px">';
  if(!_sorLocked){
    html += `<button class="btn btn-outline" onclick="sorUndo()" ${_sorPicks.length === 0 ? 'disabled' : ''}>↶ Undo</button>`;
    html += `<button class="btn btn-outline" onclick="sorReset()" ${_sorPicks.length === 0 ? 'disabled' : ''}>↺ Reset</button>`;
  } else {
    html += '<button class="btn btn-primary" onclick="sorNext()">Next →</button>';
  }
  html += '</div>';

  // Feedback
  if(_sorLocked){
    const originalWords = String(sent.ar).split(/\s+/).filter(Boolean);
    const reconstructed = _sorPicks.map(i => _sorTokens[i]);
    const correct = reconstructed.length === originalWords.length && reconstructed.every((w,i) => w === originalWords[i]);
    if(correct){
      html += '<div style="background:rgba(40,180,80,0.12);border-left:4px solid #3fb950;border-radius:6px;padding:12px;margin-top:8px">';
      html += '<div style="color:#3fb950;font-weight:600;margin-bottom:4px">✓ Correct order</div>';
      if(sent.note) html += `<div style="color:var(--muted);font-size:0.9rem;line-height:1.5">${_sorEscape(sent.note)}</div>`;
      html += '</div>';
    } else {
      html += '<div style="background:rgba(224,96,96,0.12);border-left:4px solid #e06060;border-radius:6px;padding:12px;margin-top:8px">';
      html += '<div style="color:#e06060;font-weight:600;margin-bottom:4px">✗ Correct order:</div>';
      html += `<div style="font-family:'Segoe UI','Noto Naskh Arabic','Amiri',system-ui,sans-serif;font-size:1.15rem;direction:rtl;margin-bottom:6px">${_sorEscape(sent.ar)}</div>`;
      html += `<div style="color:var(--muted);font-family:monospace;font-size:0.9rem;margin-bottom:6px">${_sorEscape(sent.tr)}</div>`;
      if(sent.note) html += `<div style="color:var(--muted);font-size:0.9rem;line-height:1.5">${_sorEscape(sent.note)}</div>`;
      html += '</div>';
    }
  }
  return html;
}

function _sorRenderBrowse(){
  let html = _sorRenderFilters();
  const items = _sorFilteredSentences();
  html += '<div style="display:flex;flex-direction:column;gap:10px">';
  items.forEach(s => {
    const cat = SOR_CATS.find(c => c.id === s.cat);
    html += '<div style="background:var(--card);border:1px solid var(--border);border-radius:10px;padding:12px">';
    html += `<div style="font-size:1.2rem;font-family:'Segoe UI','Noto Naskh Arabic','Amiri',system-ui,sans-serif;direction:rtl;margin-bottom:4px;display:flex;align-items:center;gap:6px"><button class="speak-btn" style="width:26px;height:26px;font-size:0.8rem;flex-shrink:0" onclick="speak('${s.ar.replace(/'/g,"\\'")}')">🔊</button>${_sorEscape(s.ar)}</div>`;
    html += `<div style="color:var(--muted);font-family:monospace;font-size:0.85rem;margin-bottom:4px">${_sorEscape(s.tr)}</div>`;
    html += `<div style="font-size:0.95rem;margin-bottom:4px">${_sorEscape(s.en)}</div>`;
    if(s.note) html += `<div style="color:var(--muted);font-size:0.8rem;line-height:1.4">${_sorEscape(s.note)}</div>`;
    if(cat) html += `<div style="margin-top:6px;display:inline-block;background:var(--card2);border-radius:6px;padding:2px 8px;font-size:0.75rem">${_sorEscape(cat.label)}</div>`;
    html += '</div>';
  });
  html += '</div>';
  return html;
}

function _sorRenderTips(){
  let html = '<div style="display:flex;flex-direction:column;gap:10px">';
  SOR_TIPS.forEach(t => {
    html += `<div style="background:var(--card);border:1px solid var(--border);border-radius:10px;padding:12px;line-height:1.5">${_sorEscape(t)}</div>`;
  });
  html += '</div>';
  return html;
}

function renderSor(){
  const el = document.getElementById('sor-content'); if(!el) return;
  if(_sorTab === 'drill')      el.innerHTML = _sorRenderDrill();
  else if(_sorTab === 'browse') el.innerHTML = _sorRenderBrowse();
  else                          el.innerHTML = _sorRenderTips();
}

function sorPick(tokIdx){
  if(_sorLocked) return;
  if(_sorPicks.indexOf(tokIdx) >= 0) return;
  _sorPicks.push(tokIdx);
  const sent = _sorCurrentSentence();
  if(!sent) return;
  const originalWords = String(sent.ar).split(/\s+/).filter(Boolean);
  if(_sorPicks.length >= _sorTokens.length){
    // Auto-check on full pick
    _sorLocked = true;
    const reconstructed = _sorPicks.map(i => _sorTokens[i]);
    const correct = reconstructed.length === originalWords.length && reconstructed.every((w,i) => w === originalWords[i]);
    _sorScore.answered.add(sent.id);
    if(correct){
      _sorScore.correct++;
      if(typeof bumpAchievementCounter === 'function') bumpAchievementCounter('sor_correct');
      recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10);
    } else {
      _sorScore.wrong++;
    }
  }
  renderSor();
}

function sorUndo(){
  if(_sorLocked) return;
  if(_sorPicks.length === 0) return;
  _sorPicks.pop();
  renderSor();
}

function sorReset(){
  if(_sorLocked) return;
  _sorPicks = [];
  renderSor();
}

function sorNext(){
  _sorIdx++;
  if(_sorIdx >= _sorOrder.length){
    _sorOrder = _sorShuffle(_sorFilteredSentences().map(s => s.id));
    _sorIdx = 0;
  }
  _sorLoadCurrent();
  renderSor();
}

