// === Run #147 AUDIO: rate badge next to 🐢 slow buttons on pdx + rtb ===
// R145 added 🐢 slow-replay but users still have no visibility of the
// current preferred rate (0.6 / 0.8 / 1.0 / 1.25×). The cycleAudioSpeed()
// function + AUDIO_SPEED_CYCLE + getPreferredPlaybackRate() already exist
// (R43). This run surfaces them as a 🎚️ button inside the drill UI so the
// user can see and toggle speed without leaving the drill. Same string-
// replace injection idiom as R145 with data-r147 guard to prevent double-
// inject, and prior wrap flags preserved.

function _r147RateLabel(){
  try {
    var r = (typeof getPreferredPlaybackRate === 'function') ? getPreferredPlaybackRate() : 1.0;
    var s = r.toString();
    if(s.indexOf('.') === -1) s = s + '.0';
    return s + '×';
  } catch(e){ return '1.0×'; }
}

function _r147PdxBadgeHtml(extraStyle){
  var lbl = _r147RateLabel();
  var style = extraStyle || '';
  return '<button class="btn btn-outline" data-r147="pdx" style="'+style+'" onclick="cycleAudioSpeed(); renderPdx();" title="Cycle playback speed (0.6× → 0.8× → 1.0× → 1.25×)">🎚️ '+lbl+'</button>';
}

function _r147RtbBadgeHtml(extraStyle){
  var lbl = _r147RateLabel();
  var style = extraStyle || '';
  return '<button class="btn btn-outline" data-r147="rtb" style="'+style+'" onclick="cycleAudioSpeed(); renderRtb();" title="Cycle playback speed (0.6× → 0.8× → 1.0× → 1.25×)">🎚️ '+lbl+'</button>';
}

