// ── R183 French Loanwords Coach (frw) ────────────────────────────────────────
let _frwTab = 'browse';
let _frwCatFilter = 'all';
let _frwDrillIdx = 0;
let _frwDrillAnswered = false;
let _frwPickedId = null;
let _frwDrillScore = { correct: 0, total: 0 };

function openFrw() {
  bumpAchievementCounter && bumpAchievementCounter('frw_open');
  var ov = document.getElementById('frw-overlay');
  if (!ov) return;
  ov.style.display = 'block';
  _frwDrillIdx = 0; _frwDrillAnswered = false; _frwPickedId = null;
  _frwDrillScore = { correct: 0, total: 0 };
  setFrwTab('browse');
}

function closeFrw() {
  var ov = document.getElementById('frw-overlay');
  if (ov) ov.style.display = 'none';
}

function setFrwTab(t) {
  _frwTab = t;
  if (t === 'drill') {
    _frwDrillIdx = 0; _frwDrillAnswered = false; _frwPickedId = null;
    _frwDrillScore = { correct: 0, total: 0 };
  }
  var bar = document.getElementById('frw-tab-bar');
  if (bar) {
    var tabs = [['browse','📖 Browse'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(function(tb) {
      return '<button class="cat-filter' + (_frwTab === tb[0] ? ' active' : '') + '" onclick="setFrwTab(\'' + tb[0] + '\')">' + tb[1] + '</button>';
    }).join('');
  }
  renderFrw();
}

function renderFrw() {
  var stats = document.getElementById('frw-stats');
  if (stats) stats.textContent = FRW_WORDS.length + ' words';
  var c = document.getElementById('frw-content');
  if (!c) return;
  if (_frwTab === 'browse') c.innerHTML = _frwRenderBrowse();
  else if (_frwTab === 'drill') c.innerHTML = _frwRenderDrill();
  else c.innerHTML = _frwRenderTips();
}

function _frwRenderBrowse() {
  var cats = ['all','social','everyday','objects','home','transport','city','food'];
  var catLabels = {all:'All',social:'Social',everyday:'Everyday',objects:'Objects',home:'Home',transport:'Transport',city:'City',food:'Food'};
  var filtered = _frwCatFilter === 'all' ? FRW_WORDS : FRW_WORDS.filter(function(w) { return w.category === _frwCatFilter; });
  var html = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px;">';
  cats.forEach(function(cat) {
    html += '<button class="cat-filter' + (_frwCatFilter === cat ? ' active' : '') + '" onclick="_frwSetCat(\'' + cat + '\')">' + catLabels[cat] + '</button>';
  });
  html += '</div>';
  html += '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px;">';
  filtered.forEach(function(w) {
    html += '<div style="background:var(--card);border-radius:10px;padding:14px;">';
    html += '<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px;">';
    html += '<div>';
    html += '<div style="font-size:1.35rem;font-weight:700;">' + w.ar + '</div>';
    html += '<div style="color:var(--muted);font-size:0.85rem;">' + w.tr + '</div>';
    html += '</div>';
    html += '<div style="font-size:1.5rem;">' + w.emoji + '</div>';
    html += '<button class="speak-btn" style="width:28px;height:28px;font-size:0.82rem" onclick="event.stopPropagation();speak(\'' + w.ar.replace(/'/g,"\\'") + '\')" title="Pronounce">🔊</button>';
    html += '</div>';
    html += '<div style="font-weight:600;margin-bottom:4px;">' + w.en + '</div>';
    html += '<div style="font-size:0.8rem;color:#8b5cf6;margin-bottom:6px;">← French: <em>' + w.french + '</em></div>';
    html += '<div style="font-size:0.82rem;color:var(--muted);margin-bottom:8px;">' + w.desc + '</div>';
    html += '<div style="background:var(--bg);border-radius:6px;padding:8px;font-size:0.82rem;">';
    html += '<div style="font-weight:600;margin-bottom:2px;">' + w.example_ar + '</div>';
    html += '<div style="color:var(--muted);margin-bottom:1px;">' + w.example_tr + '</div>';
    html += '<div style="color:var(--muted);font-style:italic;">' + w.example_en + '</div>';
    html += '</div>';
    html += '</div>';
  });
  html += '</div>';
  return html;
}

function _frwSetCat(c) { _frwCatFilter = c; renderFrw(); }

function _frwRenderDrill() {
  if (_frwDrillIdx >= FRW_DRILLS.length) {
    var pct = FRW_DRILLS.length > 0 ? Math.round(_frwDrillScore.correct / FRW_DRILLS.length * 100) : 0;
    return '<div style="text-align:center;padding:40px 20px;">' +
      '<div style="font-size:3rem;margin-bottom:16px;">🎉</div>' +
      '<div style="font-size:1.4rem;font-weight:700;margin-bottom:8px;">Drill Complete!</div>' +
      '<div style="color:var(--muted);margin-bottom:20px;">Score: ' + _frwDrillScore.correct + ' / ' + FRW_DRILLS.length + ' (' + pct + '%)</div>' +
      '<button class="btn btn-primary" onclick="setFrwTab(\'drill\')">Try Again</button></div>';
  }
  var q = FRW_DRILLS[_frwDrillIdx];
  var progress = '<div style="color:var(--muted);font-size:0.82rem;margin-bottom:12px;text-align:center;">Question ' + (_frwDrillIdx + 1) + ' / ' + FRW_DRILLS.length + ' · Score: ' + _frwDrillScore.correct + '</div>';
  var prompt = '<div style="text-align:center;margin-bottom:20px;">' +
    '<div style="font-size:2rem;font-weight:700;margin-bottom:6px;">' + q.prompt_ar + '</div>' +
    '<div style="color:var(--muted);">' + q.prompt_tr + '</div>' +
    '<div style="color:var(--muted);font-size:0.9rem;margin-top:4px;">' + q.prompt_en + '</div></div>';
  var optsHtml = '<div style="display:flex;flex-direction:column;gap:10px;max-width:480px;margin:0 auto;">';
  q.options.forEach(function(opt) {
    var bg = 'var(--card)';
    var border = '2px solid transparent';
    if (_frwDrillAnswered) {
      if (opt.id === q.correct_id) { bg = 'rgba(34,197,94,0.15)'; border = '2px solid #22c55e'; }
      else if (opt.id === _frwPickedId) { bg = 'rgba(239,68,68,0.15)'; border = '2px solid #ef4444'; }
    } else if (opt.id === _frwPickedId) {
      border = '2px solid var(--primary)';
    }
    optsHtml += '<button onclick="frwPickOpt(\'' + opt.id + '\')" style="background:' + bg + ';border:' + border + ';border-radius:8px;padding:12px 16px;text-align:left;cursor:pointer;color:inherit;font-size:0.95rem;">' +
      '<span style="font-weight:600;">' + opt.ar + '</span> — ' + opt.en + '</button>';
  });
  optsHtml += '</div>';
  var nextBtn = _frwDrillAnswered ? '<div style="text-align:center;margin-top:16px;"><button class="btn btn-primary" onclick="_frwDrillNext()">' + (_frwDrillIdx + 1 < FRW_DRILLS.length ? 'Next →' : 'See Results') + '</button></div>' : '';
  return progress + prompt + optsHtml + nextBtn;
}

function frwPickOpt(id) {
  if (_frwDrillAnswered) return;
  _frwPickedId = id;
  _frwDrillAnswered = true;
  var q = FRW_DRILLS[_frwDrillIdx];
  var correct = id === q.correct_id;
  _frwDrillScore.total++;
  if (correct) {
    _frwDrillScore.correct++;
    recordActivity();
    incDailyCount();
    addXp(XP_PER_RATING[2] || 10);
  }
  renderFrw();
  showToast && showToast(correct ? '✓ Correct!' : '✗ Try again');
}

function _frwDrillNext() {
  _frwDrillIdx++;
  _frwDrillAnswered = false;
  _frwPickedId = null;
  renderFrw();
}

function _frwRenderTips() {
  var html = '<div style="max-width:600px;margin:0 auto;">';
  html += '<div style="margin-bottom:20px;padding:14px;background:var(--card);border-radius:10px;">';
  html += '<div style="font-size:0.9rem;color:var(--muted);">' + FRW_ABOUT + '</div></div>';
  FRW_TIPS.forEach(function(tip, i) {
    html += '<div style="background:var(--card);border-radius:10px;padding:14px;margin-bottom:10px;">';
    html += '<div style="font-weight:700;margin-bottom:6px;">💡 Tip ' + (i + 1) + '</div>';
    html += '<div style="font-size:0.9rem;">' + tip + '</div>';
    html += '</div>';
  });
  html += '</div>';
  return html;
}
