let _qwdDrillIdx = 0;
let _qwdDrillAnswered = false;
let _qwdPickedId = null;
let _qwdDrillScore = { correct: 0, total: 0 };

function openQwd() {
  bumpAchievementCounter && bumpAchievementCounter('qwd_open');
  var ov = document.getElementById('qwd-overlay');
  if (!ov) return;
  ov.style.display = 'block';
  _qwdDrillIdx = 0; _qwdDrillAnswered = false; _qwdPickedId = null;
  _qwdDrillScore = { correct: 0, total: 0 };
  setQwdTab('browse');
}

function closeQwd() {
  var ov = document.getElementById('qwd-overlay');
  if (ov) ov.style.display = 'none';
}

function setQwdTab(t) {
  _qwdTab = t;
  if (t === 'drill') {
    _qwdDrillIdx = 0; _qwdDrillAnswered = false; _qwdPickedId = null;
    _qwdDrillScore = { correct: 0, total: 0 };
  }
  var bar = document.getElementById('qwd-tab-bar');
  if (bar) {
    var tabs = [['browse','❓ Browse'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(function(tb) {
      return '<button class="cat-filter' + (_qwdTab === tb[0] ? ' active' : '') + '" onclick="setQwdTab(\'' + tb[0] + '\')">' + tb[1] + '</button>';
    }).join('');
  }
  renderQwd();
}

function renderQwd() {
  var stats = document.getElementById('qwd-stats');
  if (stats) stats.textContent = QWD_WORDS.length + ' question words';
  var c = document.getElementById('qwd-content');
  if (!c) return;
  if (_qwdTab === 'browse') c.innerHTML = _qwdRenderBrowse();
  else if (_qwdTab === 'drill') c.innerHTML = _qwdRenderDrill();
  else c.innerHTML = _qwdRenderTips();
}

function _qwdRenderBrowse() {
  var cats = ['all','basic','compound'];
  var catLabels = { all: 'All', basic: 'Basic', compound: 'Compound' };
  var filtered = _qwdCatFilter === 'all' ? QWD_WORDS : QWD_WORDS.filter(function(w) { return w.category === _qwdCatFilter; });
  var html = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px;">';
  cats.forEach(function(cat) {
    html += '<button class="cat-filter' + (_qwdCatFilter === cat ? ' active' : '') + '" onclick="_qwdSetCat(\'' + cat + '\')">' + catLabels[cat] + '</button>';
  });
  html += '</div>';
  html += '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px;">';
  filtered.forEach(function(w) {
    html += '<div style="background:var(--card);border-radius:10px;padding:14px;">';
    html += '<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px;">';
    html += '<div>';
    html += '<div style="font-size:2rem;font-weight:800;color:var(--primary);line-height:1.1;">' + w.ar + '</div>';
    html += '<div style="color:var(--muted);font-size:0.85rem;margin-top:2px;">' + w.tr + '</div>';
    html += '</div>';
    html += '<div style="font-size:1.6rem;">' + w.emoji + '</div>';
    html += '<button class="speak-btn" style="width:28px;height:28px;font-size:0.82rem;flex-shrink:0" onclick="event.stopPropagation();speak(\'' + w.ar.replace(/'/g,"\\'") + '\')" title="Pronounce">🔊</button>';
    html += '</div>';
    html += '<div style="font-weight:700;font-size:1.1rem;margin-bottom:6px;">' + w.en + '</div>';
    html += '<div style="font-size:0.82rem;color:var(--muted);margin-bottom:8px;">' + w.usage + '</div>';
    html += '<div style="background:var(--bg);border-radius:6px;padding:8px;font-size:0.82rem;">';
    html += '<div style="font-weight:600;margin-bottom:2px;">' + w.example_ar + '</div>';
    html += '<div style="color:var(--muted);margin-bottom:1px;">' + w.example_tr + '</div>';
    html += '<div style="color:var(--muted);font-style:italic;">' + w.example_en + '</div>';
    html += '</div>';
    html += '</div>';
  });
  html += '</div>';
  return html;
}

function _qwdSetCat(c) { _qwdCatFilter = c; renderQwd(); }

function _qwdRenderDrill() {
  if (_qwdDrillIdx >= QWD_DRILLS.length) {
    var pct = QWD_DRILLS.length > 0 ? Math.round(_qwdDrillScore.correct / QWD_DRILLS.length * 100) : 0;
    return '<div style="text-align:center;padding:40px 20px;">' +
      '<div style="font-size:3rem;margin-bottom:16px;">🎉</div>' +
      '<div style="font-size:1.4rem;font-weight:700;margin-bottom:8px;">Drill Complete!</div>' +
      '<div style="color:var(--muted);margin-bottom:20px;">Score: ' + _qwdDrillScore.correct + ' / ' + QWD_DRILLS.length + ' (' + pct + '%)</div>' +
      '<button class="btn btn-primary" onclick="setQwdTab(\'drill\')">Try Again</button></div>';
  }
  var q = QWD_DRILLS[_qwdDrillIdx];
  var progress = '<div style="color:var(--muted);font-size:0.82rem;margin-bottom:12px;text-align:center;">Question ' + (_qwdDrillIdx + 1) + ' / ' + QWD_DRILLS.length + ' · Score: ' + _qwdDrillScore.correct + '</div>';
  var prompt = '<div style="text-align:center;margin-bottom:20px;">' +
    '<div style="font-size:1.5rem;font-weight:700;margin-bottom:6px;">' + q.prompt_ar + '</div>' +
    '<div style="color:var(--muted);margin-bottom:4px;">' + q.prompt_tr + '</div>' +
    '<div style="color:var(--muted);font-size:0.9rem;">' + q.prompt_en + '</div></div>';
  var optsHtml = '<div style="display:flex;flex-direction:column;gap:10px;max-width:480px;margin:0 auto;">';
  q.options.forEach(function(opt) {
    var bg = 'var(--card)';
    var border = '2px solid transparent';
    if (_qwdDrillAnswered) {
      if (opt.id === q.correct_id) { bg = 'rgba(34,197,94,0.15)'; border = '2px solid #22c55e'; }
      else if (opt.id === _qwdPickedId) { bg = 'rgba(239,68,68,0.15)'; border = '2px solid #ef4444'; }
    } else if (opt.id === _qwdPickedId) {
      border = '2px solid var(--primary)';
    }
    optsHtml += '<button onclick="qwdPickOpt(\'' + opt.id + '\')" style="background:' + bg + ';border:' + border + ';border-radius:8px;padding:12px 16px;text-align:left;cursor:pointer;color:inherit;font-size:0.95rem;">' +
      '<span style="font-size:1.2rem;font-weight:700;">' + opt.ar + '</span> — ' + opt.en + '</button>';
  });
  optsHtml += '</div>';
  var nextBtn = _qwdDrillAnswered ? '<div style="text-align:center;margin-top:16px;"><button class="btn btn-primary" onclick="_qwdDrillNext()">' + (_qwdDrillIdx + 1 < QWD_DRILLS.length ? 'Next →' : 'See Results') + '</button></div>' : '';
  return progress + prompt + optsHtml + nextBtn;
}

function qwdPickOpt(id) {
  if (_qwdDrillAnswered) return;
  _qwdPickedId = id;
  _qwdDrillAnswered = true;
  var q = QWD_DRILLS[_qwdDrillIdx];
  var correct = id === q.correct_id;
  _qwdDrillScore.total++;
  if (correct) {
    _qwdDrillScore.correct++;
    recordActivity();
    incDailyCount();
    addXp(XP_PER_RATING[2] || 10);
  }
  renderQwd();
  showToast && showToast(correct ? '✓ Correct!' : '✗ Try again');
}

function _qwdDrillNext() {
  _qwdDrillIdx++;
  _qwdDrillAnswered = false;
  _qwdPickedId = null;
  renderQwd();
}

function _qwdRenderTips() {
  var html = '<div style="max-width:600px;margin:0 auto;">';
  html += '<div style="margin-bottom:20px;padding:14px;background:var(--card);border-radius:10px;">';
  html += '<div style="font-size:0.9rem;color:var(--muted);">' + QWD_ABOUT + '</div></div>';
  QWD_TIPS.forEach(function(tip, i) {
    html += '<div style="background:var(--card);border-radius:10px;padding:14px;margin-bottom:10px;">';
    html += '<div style="font-weight:700;margin-bottom:6px;">💡 Tip ' + (i + 1) + '</div>';
    html += '<div style="font-size:0.9rem;">' + tip + '</div>';
    html += '</div>';
  });
  html += '</div>';
  return html;
}
// ── end R189 ──────────────────────────────────────────────────────────────────

