// ── Run #221 · BUG FIX: define showToast so mini-coach drill feedback works ──
// 20+ coaches use `showToast && showToast(msg)` but the function was never defined.
// All guarded calls silently did nothing — no ✓/✗ feedback toast fired.
// Fix: define showToast routing to toastSuccess (✓) or toastError (✗) based on msg prefix.
var showToast = function(msg){
  if(typeof toast !== 'function') return;
  if(typeof msg === 'string' && msg.charAt(0) === '✓'){
    if(typeof toastSuccess === 'function') toastSuccess(msg);
    else toast(msg, {type:'success'});
  } else {
    if(typeof toastError === 'function') toastError(msg);
    else toast(msg, {type:'error'});
  }
};
// ── End Run #221 ─────────────────────────────────────────────────────────────

