  const d = HLT_DRILLS[_hltDrillIdx];
  const correct = (i===d.correct);
  const fb = document.getElementById('hlt-drill-fb');
  const btns = document.querySelectorAll('#hlt-content .btn-outline');
  btns.forEach((b,idx)=>{
    if(idx===d.correct) b.style.background='#1b5e20';
    else if(idx===i && !correct) b.style.background='#b71c1c';
  });
  if(fb) fb.innerHTML = (correct?'<b style="color:#81c784">✓ Correct!</b> ':'<b style="color:#e57373">✗ Wrong.</b> ') + d.note;
  showToast && showToast(correct ? '✓ Correct!' : '✗ Try again');
  if(correct){ recordActivity&&recordActivity(); incDailyCount&&incDailyCount(); addXp&&addXp(XP_PER_RATING&&XP_PER_RATING[2]||10); }
