// ── Run #260 — BUG FIX: Progress tracking improvements ───────────────────────
// Fix 1: updateNavStats() had no null-guard on nav-due/nav-total elements.
// If either element was missing (DOM manipulation, extension, edge case),
// the function threw TypeError and updateStreak/updateXpBadge/renderTodayDashboard
// never ran — silently breaking all progress display updates.
// Fix 2: sessionStartTime was never initialized for mini-coach sessions.
// Mini-coach users saw "time today: 0" permanently. Now recordActivity()
// initializes sessionStartTime on first call if not already set.
(function(){
  var _origUpdateNavStats = (typeof updateNavStats === 'function') ? updateNavStats : null;
  updateNavStats = function(){
    try {
      var due = getDueCards().length;
      var learned = typeof VOCAB !== 'undefined' ? VOCAB.filter(function(v){ return getCard(v.id).reps > 0; }).length : 0;
      var navDue = document.getElementById('nav-due');
      var navTotal = document.getElementById('nav-total');
      if(navDue) navDue.textContent = due;
      if(navTotal) navTotal.textContent = learned;
      if(typeof updateStreak === 'function') updateStreak();
      if(typeof updateXpBadge === 'function') updateXpBadge();
      if(typeof renderTodayDashboard === 'function') renderTodayDashboard();
    } catch(e) {
      // Fallback to original if wrapped version fails
      if(_origUpdateNavStats) { try { _origUpdateNavStats(); } catch(e2){} }
    }
  };
  updateNavStats.__r260Fixed = true;
})();

(function(){
  // Fix 2: incDailyCount() now initializes sessionStartTime if null.
  // Mini-coach users were getting "time today: 0" because sessionStartTime
  // was only set in startSessionTimer() (flashcard flow). Now any correct
  // mini-coach answer initializes it for the session.
  var _origIncDailyCount = (typeof incDailyCount === 'function') ? incDailyCount : null;
  incDailyCount = function(){
    if(typeof sessionStartTime !== 'undefined' && sessionStartTime === null){
      sessionStartTime = Date.now();
    }
    if(_origIncDailyCount) { try { _origIncDailyCount(); } catch(e){} }
  };
  incDailyCount.__r260Fixed = true;
})();

