// ── Run #263 — BUG FIX: Expire stale audio cache "none" entries ──────────────
// '__none__' entries in audioCache are permanent — if Wiktionary or Commons
// had no recording when first checked, the word stays silent forever even after
// recordings are later added. Fix: stamp '__none__' writes with a timestamp and
// treat entries older than 7 days as absent (trigger re-check on next speak()).
(function(){
  var NONE_TTL = 7 * 24 * 60 * 60 * 1000; // 7 days in ms

  var _origAudioCache = audioCache;
  audioCache = function(){
    var c = _origAudioCache();
    var changed = false;
    Object.keys(c).forEach(function(k){
      var v = c[k];
      if(typeof v === 'string' && v.indexOf('__none__:') === 0){
        var ts = parseInt(v.slice(9), 10);
        if(isNaN(ts) || (Date.now() - ts) > NONE_TTL){
          // stale — drop so speak() re-checks live sources
          delete c[k];
          changed = true;
        } else {
          // fresh — normalize to plain '__none__' for all existing comparisons
          c[k] = '__none__';
        }
      }
    });
    if(changed){
      try { localStorage.setItem(CACHE_KEY, JSON.stringify(c)); } catch(e){}
    }
    return c;
  };
  audioCache.__r263Fixed = true;

  var _origSaveAudioCache = saveAudioCache;
  saveAudioCache = function(c){
    // stamp any plain '__none__' with current timestamp before persisting
    var stamped = {};
    Object.keys(c).forEach(function(k){
      var v = c[k];
      if(v === '__none__'){
        stamped[k] = '__none__:' + Date.now();
      } else {
        stamped[k] = v;
      }
    });
    _origSaveAudioCache(stamped);
  };
  saveAudioCache.__r263Fixed = true;
})();

