// ── Run #266 — BUG FIX: Voice race condition in browser TTS ──────────────────
// _speakViaBrowser and _speakWebSpeech fall back to u.lang='ar' (generic Arabic)
// when _arVoices is empty. This happens on first call before the voiceschanged
// event fires — a race condition. The browser may already have Arabic voices
// available via speechSynthesis.getVoices() even if our event hasn't fired yet.
// Fix: add _getArVoicesNow() that tries a live query when _arVoices is empty,
// prioritizing ar-LB/ar-SY/ar-EG before plain 'ar'. Override both functions.
(function(){
  function _getArVoicesNow(){
    if(typeof _arVoices !== 'undefined' && _arVoices.length) return _arVoices;
    if(!window.speechSynthesis) return [];
    var live = speechSynthesis.getVoices().filter(function(v){ return v.lang && v.lang.startsWith('ar'); });
    if(live.length){
      if(typeof _arVoices !== 'undefined') _arVoices = live;
    }
    return live;
  }

  function _pickBestVoice(voices){
    if(!voices || !voices.length) return null;
    var pref = (typeof getPreferredVoiceIdx === 'function') ? getPreferredVoiceIdx() : -1;
    if(pref >= 0 && voices[pref]) return voices[pref];
    if(typeof getBestVoiceIdx === 'function'){
      var bi = getBestVoiceIdx();
      if(bi >= 0 && voices[bi]) return voices[bi];
    }
    // prefer Lebanese/Levantine lang tags
    var lbVoice = voices.find(function(v){ return v.lang==='ar-LB'||v.lang==='ar-SY'; });
    return lbVoice || voices[0];
  }

  var _origSpeakViaBrowser = _speakViaBrowser;
  _speakViaBrowser = function(text, slow, clearAnim){
    var badge = document.getElementById('audio-source');
    if(!text || !window.speechSynthesis){ clearAnim && clearAnim(); return false; }
    if(typeof _lebStrictBlocksBrowserTts === 'function' && _lebStrictBlocksBrowserTts()){
      if(badge) badge.textContent = '🇱🇧 Strict mode — no Lebanese/Levantine voice available';
      clearAnim && clearAnim();
      return false;
    }
    try {
      speechSynthesis.cancel();
      var u = new SpeechSynthesisUtterance(text);
      var voices = _getArVoicesNow();
      if(voices.length){
        u.voice = _pickBestVoice(voices);
        var lab = (typeof _voiceLabel === 'function' && u.voice) ? _voiceLabel(u.voice) : '🗣';
        if(badge) badge.textContent = lab + ' ' + ((u.voice && u.voice.name) || 'browser');
      } else {
        // no Arabic voice at all — use locale-hinted lang to guide the browser
        u.lang = 'ar-LB';
        if(badge) badge.textContent = '🗣 Browser speech (ar-LB hint)';
      }
      u.rate = (slow ? 0.7 : 1.0) * (typeof getPreferredPlaybackRate === 'function' ? getPreferredPlaybackRate() : 1.0);
      u.onend = clearAnim;
      u.onerror = clearAnim;
      speechSynthesis.speak(u);
      return true;
    } catch(e){ clearAnim && clearAnim(); return false; }
  };
  _speakViaBrowser.__r266Fixed = true;

  var _origSpeakWebSpeech = _speakWebSpeech;
  _speakWebSpeech = function(text, voiceIdx, slow){
    if(!window.speechSynthesis) return;
    speechSynthesis.cancel();
    var utt = new SpeechSynthesisUtterance(text);
    var voices = _getArVoicesNow();
    var voice = voices[voiceIdx] || null;
    if(voice){ utt.voice = voice; }
    else if(voices.length){ utt.voice = _pickBestVoice(voices); }
    else { utt.lang = 'ar-LB'; }
    utt.rate = (slow ? 0.7 : 1.0) * (typeof getPreferredPlaybackRate === 'function' ? getPreferredPlaybackRate() : 1.0);
    speechSynthesis.speak(utt);
  };
  _speakWebSpeech.__r266Fixed = true;
})();

