// ── Run #269 — BUG FIX: _audioBulkPrecache skips fresh __none__ entries ───────
// R263 made audioCache() normalize fresh miss entries back to plain '__none__'.
// Before R263, _audioBulkPrecache would re-query '__none__' entries hoping they
// might now have audio — that was intentional (permanent misses). After R263,
// audioCache() already handles expiry: stale entries are dropped (undefined),
// fresh ones stay as '__none__'. So when _audioBulkPrecache sees '__none__', it
// means "checked recently, nothing found" — re-querying is wasted network traffic.
// Fix: patch the pending filter to also skip '__none__' entries for both wikt
// and commons. Stale entries (where R263 deleted the key → undefined) still
// get re-queued correctly.
(function(){
  var _origBulkPrecache = _audioBulkPrecache;
  _audioBulkPrecache = function(texts, onProgress){
    if(!Array.isArray(texts) || texts.length === 0){
      return Promise.resolve({ done:0, total:0, hits:0 });
    }
    if(typeof audioCache !== 'function'){
      return _origBulkPrecache(texts, onProgress);
    }
    var cache = audioCache();
    // Mark stale: remove entries that R263 would have dropped (stale __none__)
    // so the original function sees them as undefined (needs re-check).
    // Skip fresh __none__ entries — R263 guarantees these were checked recently.
    var filtered = texts.filter(function(t){
      if(!t) return false;
      var raw = cache[t];
      // Positive wikt hit
      if(raw && raw !== '__none__') return false;
      // Fresh wikt miss — R263 confirmed recently checked
      if(raw === '__none__') return false;
      var commons = cache['__commons__:' + t];
      // Positive commons hit
      if(commons && commons !== '__none__') return false;
      // Fresh commons miss
      if(commons === '__none__') return false;
      return true;
    });
    if(filtered.length === texts.length){
      // Nothing filtered — use original to avoid double audioCache() call
      return _origBulkPrecache(texts, onProgress);
    }
    // Report pre-skipped entries as "done" immediately
    var preSkipped = texts.length - filtered.length;
    if(filtered.length === 0){
      if(onProgress) try { onProgress({ done:texts.length, total:texts.length, hits:preSkipped }); } catch(e){}
      return Promise.resolve({ done:texts.length, total:texts.length, hits:preSkipped });
    }
    return _origBulkPrecache(filtered, function(p){
      if(onProgress) try {
        onProgress({ done:p.done+preSkipped, total:texts.length, hits:p.hits+preSkipped });
      } catch(e){}
    }).then(function(r){
      return { done:r.done+preSkipped, total:texts.length, hits:r.hits+preSkipped };
    });
  };
  _audioBulkPrecache.__r269Fixed = true;
})();

