// ── R287 — BUG FIX: R284 hlt/tdr wrappers double-called activity on correct ──
// R284 wrapped hltPickOpt/tdrPickOpt to call recordActivity+incDailyCount+addXp
// unconditionally. But original functions also call them on correct answers —
// so correct answers trigger TWO increments. Fix: wrap again, neutralizing the
// original's activity calls (since R284 already handles them for all answers).
(function(){
  var _noop = function(){};

  var _r284Hlt = hltPickOpt;
  hltPickOpt = function(i){
    var _origRec = recordActivity, _origInc = incDailyCount, _origXp = addXp;
    recordActivity = _noop; incDailyCount = _noop; addXp = _noop;
    try { _r284Hlt.apply(this, arguments); } finally {
      recordActivity = _origRec; incDailyCount = _origInc; addXp = _origXp;
    }
  };
  hltPickOpt.__r284Fixed = true;
  hltPickOpt.__r287Fixed = true;

  var _r284Tdr = tdrPickOpt;
  tdrPickOpt = function(i){
    var _origRec = recordActivity, _origInc = incDailyCount, _origXp = addXp;
    recordActivity = _noop; incDailyCount = _noop; addXp = _noop;
    try { _r284Tdr.apply(this, arguments); } finally {
      recordActivity = _origRec; incDailyCount = _origInc; addXp = _origXp;
    }
  };
  tdrPickOpt.__r284Fixed = true;
  tdrPickOpt.__r287Fixed = true;
})();

