// ── R290 — BUG FIX: R287 zeroed all activity for hlt/tdr (fix the fix) ────────
// R287 nulled recordActivity/incDailyCount/addXp before calling R284 wrapper —
// but R284 wrapper also calls them, so R284 got nulled too → zero activity.
// Fix: call activity functions once at top of new wrapper, THEN null for chain.
(function(){
  var _noop = function(){};
  var _xpVal = function(){ return (typeof XP_PER_RATING!=='undefined'&&XP_PER_RATING[2])||10; };

  var _r287Hlt = hltPickOpt;
  hltPickOpt = function(i){
    if(typeof recordActivity==='function') try{ recordActivity(); }catch(e){}
    if(typeof incDailyCount==='function') try{ incDailyCount(); }catch(e){}
    if(typeof addXp==='function') try{ addXp(_xpVal()); }catch(e){}
    var _r=recordActivity,_c=incDailyCount,_x=addXp;
    recordActivity=_noop; incDailyCount=_noop; addXp=_noop;
    try{ _r287Hlt.apply(this,arguments); }finally{ recordActivity=_r; incDailyCount=_c; addXp=_x; }
  };
  hltPickOpt.__r284Fixed = true;
  hltPickOpt.__r287Fixed = true;
  hltPickOpt.__r290Fixed = true;

  var _r287Tdr = tdrPickOpt;
  tdrPickOpt = function(i){
    if(typeof recordActivity==='function') try{ recordActivity(); }catch(e){}
    if(typeof incDailyCount==='function') try{ incDailyCount(); }catch(e){}
    if(typeof addXp==='function') try{ addXp(_xpVal()); }catch(e){}
    var _r=recordActivity,_c=incDailyCount,_x=addXp;
    recordActivity=_noop; incDailyCount=_noop; addXp=_noop;
    try{ _r287Tdr.apply(this,arguments); }finally{ recordActivity=_r; incDailyCount=_c; addXp=_x; }
  };
  tdrPickOpt.__r284Fixed = true;
  tdrPickOpt.__r287Fixed = true;
  tdrPickOpt.__r290Fixed = true;
})();

