// ── R293 — BUG FIX: _xxxDrillAnswered stale state after overlay close ─────────
// When user answers a drill then closes overlay, _xxxDrillAnswered stays true.
// Reopening + clicking Drill tab renders fresh buttons that silently ignore clicks.
// Fix: reset answered flag + clear pending timer when switching TO drill tab.
(function(){
  // Wrap each coach's tab-switch function to reset drill state on drill tab open
  var coaches = [
    { setFn: 'setWrk', answered: '_wrkDrillAnswered', timer: '_wrkTimer' },
    { setFn: 'setNtrTab', answered: '_ntrDrillAnswered', timer: '_ntrTimer' },
    { setFn: 'setScl', answered: '_sclDrillAnswered', timer: '_sclTimer' },
    { setFn: 'setHom', answered: '_homDrillAnswered', timer: '_homTimer' },
    { setFn: 'setPrt', answered: '_prtDrillAnswered', timer: '_prtTimer' },
    { setFn: 'setBod', answered: '_bodDrillAnswered', timer: '_bodTimer' },
  ];
  coaches.forEach(function(c){
    if(typeof window[c.setFn] !== 'function') return;
    var _orig = window[c.setFn];
    window[c.setFn] = function(t){
      if(t === 'drill'){
        // Reset stale answered state before rendering drill tab
        try{
          if(window[c.timer]){ clearTimeout(window[c.timer]); window[c.timer]=null; }
          window[c.answered] = false;
        }catch(e){}
      }
      _orig.apply(this, arguments);
    };
    window[c.setFn].__r293Fixed = true;
  });
})();

// ── R293b — Fix: setWrk→setWrkTab name correction ────────────────────────────
(function(){
  if(typeof setWrkTab !== 'function') return;
  if(setWrkTab.__r293Fixed) return;
  var _orig = setWrkTab;
  setWrkTab = function(t){
    if(t === 'drill'){
      try{
        if(window._wrkTimer){ clearTimeout(window._wrkTimer); window._wrkTimer=null; }
        window._wrkDrillAnswered = false;
      }catch(e){}
    }
    _orig.apply(this, arguments);
  };
  setWrkTab.__r293Fixed = true;
})();

// ── R293c — Direct stale-drill-state fix for remaining coaches ────────────────
(function(){
  function _fixDrillReset(fn, answeredVar, timerVar){
    if(typeof fn !== 'function' || fn.__r293Fixed) return fn;
    var _orig = fn;
    var _new = function(t){
      if(t === 'drill'){
        try{
          if(window[timerVar]){ clearTimeout(window[timerVar]); window[timerVar]=null; }
          window[answeredVar] = false;
        }catch(e){}
      }
      _orig.apply(this, arguments);
    };
    _new.__r293Fixed = true;
    return _new;
  }
  setNtrTab = _fixDrillReset(setNtrTab, '_ntrDrillAnswered', '_ntrTimer');
  setScl    = _fixDrillReset(setScl,    '_sclDrillAnswered', '_sclTimer');
  setHom    = _fixDrillReset(setHom,    '_homDrillAnswered', '_homTimer');
  setPrt    = _fixDrillReset(setPrt,    '_prtDrillAnswered', '_prtTimer');
  setBod    = _fixDrillReset(setBod,    '_bodDrillAnswered', '_bodTimer');
})();

