// ── R296 — BUG FIX: coach close functions don't clear timers; setTrp missing stale-state fix ───
// Close functions for WRK/NTR/SCL/HOM/PRT/BOD never cleared the 1800ms auto-advance
// timer — if user closed the overlay right after answering, the timer fired and called
// renderX() on a hidden overlay, wasting CPU and potentially causing stale state on reopen.
// Also: TRP coach (added R294) was not covered by R293's stale-drill-state fix.
(function(){
  // Wrap close functions to clear pending drill timer + reset answered state
  var closeMap = [
    { close: 'closeWrk', timer: '_wrkTimer', answered: '_wrkDrillAnswered' },
    { close: 'closeNtr', timer: '_ntrTimer', answered: '_ntrDrillAnswered' },
    { close: 'closeScl', timer: '_sclTimer', answered: '_sclDrillAnswered' },
    { close: 'closeHom', timer: '_homTimer', answered: '_homDrillAnswered' },
    { close: 'closePrt', timer: '_prtTimer', answered: '_prtDrillAnswered' },
    { close: 'closeBod', timer: '_bodTimer', answered: '_bodDrillAnswered' },
    { close: 'closeTrp', timer: '_trpTimer', answered: '_trpDrillAnswered' },
  ];
  closeMap.forEach(function(c){
    if(typeof window[c.close] !== 'function') return;
    if(window[c.close].__r296Fixed) return;
    var _orig = window[c.close];
    window[c.close] = function(){
      try{
        if(window[c.timer]){ clearTimeout(window[c.timer]); window[c.timer]=null; }
        window[c.answered] = false;
      }catch(e){}
      _orig.apply(this, arguments);
    };
    window[c.close].__r296Fixed = true;
  });

  // TRP stale-drill-state fix (setTrp not in R293 — TRP was created after)
  if(typeof setTrp === 'function' && !setTrp.__r293Fixed){
    var _origSetTrp = setTrp;
    setTrp = function(t){
      if(t === 'drill'){
        try{
          if(window._trpTimer){ clearTimeout(window._trpTimer); window._trpTimer=null; }
          window._trpDrillAnswered = false;
        }catch(e){}
      }
      _origSetTrp.apply(this, arguments);
    };
    setTrp.__r293Fixed = true;
    setTrp.__r296Fixed = true;
  }
})();

// ── R296b — Direct close-function timer-clear fix ────────────────────────────
(function(){
  function _fixClose(fn, timerVar, answeredVar){
    if(typeof fn !== 'function' || fn.__r296Fixed) return fn;
    var _orig = fn;
    var _new = function(){
      try{
        if(window[timerVar]){ clearTimeout(window[timerVar]); window[timerVar]=null; }
        window[answeredVar] = false;
      }catch(e){}
      _orig.apply(this, arguments);
    };
    _new.__r296Fixed = true;
    return _new;
  }
  closeWrk = _fixClose(closeWrk, '_wrkTimer', '_wrkDrillAnswered');
  closeNtr = _fixClose(closeNtr, '_ntrTimer', '_ntrDrillAnswered');
  closeScl = _fixClose(closeScl, '_sclTimer', '_sclDrillAnswered');
  closeHom = _fixClose(closeHom, '_homTimer', '_homDrillAnswered');
  closePrt = _fixClose(closePrt, '_prtTimer', '_prtDrillAnswered');
  closeBod = _fixClose(closeBod, '_bodTimer', '_bodDrillAnswered');
  closeTrp = _fixClose(closeTrp, '_trpTimer', '_trpDrillAnswered');
})();

