// ── R299 — BUG FIX: R296b timer-clear broken for let-scoped timer vars ────────
// R296b used window[timerVar] to clear timers, but WRK/NTR/SCL/HOM/PRT/BOD
// declare their timers and answered flags with `let`, not `var`. Top-level `let`
// vars are NOT properties of window — so window['_wrkTimer'] === undefined and
// clearTimeout(undefined) is a no-op. Timer still fires after overlay closes.
// Fix: wrap each close function to directly reference the closed-over let vars.
(function(){
  // closeWrk: directly access _wrkTimer / _wrkDrillAnswered
  var _cWrk = closeWrk;
  closeWrk = function(){
    if(_wrkTimer){ clearTimeout(_wrkTimer); _wrkTimer=null; }
    _wrkDrillAnswered = false;
    _cWrk.apply(this, arguments);
  };
  closeWrk.__r296Fixed = true;
  closeWrk.__r299Fixed = true;

  // closeNtr: directly access _ntrTimer / _ntrDrillAnswered
  var _cNtr = closeNtr;
  closeNtr = function(){
    if(_ntrTimer){ clearTimeout(_ntrTimer); _ntrTimer=null; }
    _ntrDrillAnswered = false;
    _cNtr.apply(this, arguments);
  };
  closeNtr.__r296Fixed = true;
  closeNtr.__r299Fixed = true;

  // closeScl: directly access _sclTimer / _sclDrillAnswered
  var _cScl = closeScl;
  closeScl = function(){
    if(_sclTimer){ clearTimeout(_sclTimer); _sclTimer=null; }
    _sclDrillAnswered = false;
    _cScl.apply(this, arguments);
  };
  closeScl.__r296Fixed = true;
  closeScl.__r299Fixed = true;

  // closeHom: directly access _homTimer / _homDrillAnswered
  var _cHom = closeHom;
  closeHom = function(){
    if(_homTimer){ clearTimeout(_homTimer); _homTimer=null; }
    _homDrillAnswered = false;
    _cHom.apply(this, arguments);
  };
  closeHom.__r296Fixed = true;
  closeHom.__r299Fixed = true;

  // closePrt: directly access _prtTimer / _prtDrillAnswered
  var _cPrt = closePrt;
  closePrt = function(){
    if(_prtTimer){ clearTimeout(_prtTimer); _prtTimer=null; }
    _prtDrillAnswered = false;
    _cPrt.apply(this, arguments);
  };
  closePrt.__r296Fixed = true;
  closePrt.__r299Fixed = true;

  // closeBod: directly access _bodTimer / _bodDrillAnswered
  var _cBod = closeBod;
  closeBod = function(){
    if(_bodTimer){ clearTimeout(_bodTimer); _bodTimer=null; }
    _bodDrillAnswered = false;
    _cBod.apply(this, arguments);
  };
  closeBod.__r296Fixed = true;
  closeBod.__r299Fixed = true;
  // closeTrp/closeMny use `var` — window[key] works there, no re-wrap needed.
})();

