// ── R301 — Audio: sequential "Listen All" for FSH browse tab ─────────────────
// Adds a 🔊 Listen All button to FSH browse tab so users can hear all words
// in the current category played sequentially (passive listening mode).
var _fshListenAllActive = false;
var _fshListenAllIdx = 0;

function _fshListenAll(){
  if(typeof FSH_WORDS==='undefined') return;
  var words = _fshCat==='all' ? FSH_WORDS : FSH_WORDS.filter(function(w){ return w.cat===_fshCat; });
  if(!words.length) return;
  _fshListenAllActive = true;
  _fshListenAllIdx = 0;
  _fshListenNext(words);
}

function _fshStopListenAll(){
  _fshListenAllActive = false;
  if(typeof stopAllAudio === 'function') try{ stopAllAudio(); }catch(e){}
  renderFsh();
}

function _fshListenNext(words){
  if(!_fshListenAllActive) return;
  if(_fshListenAllIdx >= words.length){
    _fshListenAllActive = false;
    renderFsh();
    return;
  }
  var w = words[_fshListenAllIdx];
  _fshListenAllIdx++;
  // Update progress button text
  var btn = document.getElementById('fsh-listen-all-btn');
  if(btn) btn.textContent = '⏹ Stop ('+_fshListenAllIdx+'/'+words.length+')';
  if(typeof speak === 'function'){
    // After speak completes, wait 600ms then play next
    var afterSpeak = function(){
      if(!_fshListenAllActive) return;
      setTimeout(function(){ _fshListenNext(words); }, 600);
    };
    try{
      var p = speak(w.ar);
      if(p && typeof p.then === 'function'){
        p.then(afterSpeak).catch(afterSpeak);
      } else {
        setTimeout(function(){ _fshListenNext(words); }, 1200);
      }
    }catch(e){
      setTimeout(function(){ _fshListenNext(words); }, 1200);
    }
  } else {
    setTimeout(function(){ _fshListenNext(words); }, 800);
  }
}

// Patch _fshRenderBrowse to include the Listen All button
(function(){
  var _origBrowse = _fshRenderBrowse;
  _fshRenderBrowse = function(){
    var html = _origBrowse.apply(this, arguments);
    var listenBtn = _fshListenAllActive
      ? '<button id="fsh-listen-all-btn" class="btn btn-outline" style="margin-bottom:10px" onclick="_fshStopListenAll()">⏹ Stop ('+_fshListenAllIdx+'/...)</button>'
      : '<button id="fsh-listen-all-btn" class="btn btn-outline" style="margin-bottom:10px" onclick="_fshListenAll()">🔊 Listen All</button>';
    return listenBtn + html;
  };
  _fshRenderBrowse.__r301Enhanced = true;
})();

// ── R302 — BUG FIX: _fshListenAll has 3 bugs ─────────────────────────────────
// 1. closeFsh didn't stop Listen All — audio kept playing after overlay closed
// 2. speak() promise resolves immediately (before audio ends), not when audio done
//    → _fshListenNext fires afterSpeak too early → words overlap
// 3. _fshSetCat didn't stop Listen All on category change → stale words array
(function(){
  // Fix 1: patch closeFsh to stop Listen All
  var _cFsh = closeFsh;
  closeFsh = function(){
    _fshListenAllActive = false;
    _cFsh.apply(this, arguments);
  };
  closeFsh.__r296Fixed = true;
  closeFsh.__r302Fixed = true;

  // Fix 2 & 3: patch _fshSetCat to stop Listen All on category change
  var _origSetCat = _fshSetCat;
  _fshSetCat = function(c){
    if(_fshListenAllActive){
      _fshListenAllActive = false;
      if(typeof stopAllAudio === 'function') try{ stopAllAudio(); }catch(e){}
    }
    _origSetCat.apply(this, arguments);
  };
  _fshSetCat.__r302Fixed = true;

  // Fix 2: replace _fshListenNext with timing-safe version
  // speak() resolves before audio ends — use audio.onended hook instead
  _fshListenNext = function(words){
    if(!_fshListenAllActive) return;
    if(_fshListenAllIdx >= words.length){
      _fshListenAllActive = false;
      renderFsh();
      return;
    }
    var w = words[_fshListenAllIdx];
    _fshListenAllIdx++;
    var btn = document.getElementById('fsh-listen-all-btn');
    if(btn) btn.textContent = '\u23F9 Stop ('+_fshListenAllIdx+'/'+words.length+')';

    // Hook audio element's onended to advance
    var audio = document.getElementById('tts-audio');
    var _next = function(){
      if(!_fshListenAllActive) return;
      setTimeout(function(){ _fshListenNext(words); }, 500);
    };
    if(audio && typeof audio.addEventListener === 'function'){
      var _handler = function(){
        audio.removeEventListener('ended', _handler);
        audio.removeEventListener('error', _handler);
        _next();
      };
      audio.addEventListener('ended', _handler);
      audio.addEventListener('error', _handler);
    } else {
      // No audio element in this env — just use fixed delay
      setTimeout(function(){ _fshListenNext(words); }, 1500);
    }

    if(typeof speak === 'function'){
      try{ speak(w.ar); }catch(e){ _next(); }
    } else {
      setTimeout(function(){ _fshListenNext(words); }, 1500);
    }
  };
  _fshListenNext.__r302Fixed = true;
})();

