// ── R304 — Audio: sequential "Listen All" for DVB browse tab ─────────────────
// Same pattern as FSH R301/R302 but with fixes baked in from the start:
// - closeDvb stops playback
// - _dvbSetCat stops playback on category change
// - Uses audio.onended hook (not speak() promise) for timing
var _dvbListenAllActive = false;
var _dvbListenAllIdx = 0;

function _dvbListenAll(){
  if(typeof DVB_WORDS==='undefined') return;
  var words = _dvbCat==='all' ? DVB_WORDS : DVB_WORDS.filter(function(w){ return w.cat===_dvbCat; });
  if(!words.length) return;
  _dvbListenAllActive = true;
  _dvbListenAllIdx = 0;
  _dvbListenNext(words);
}

function _dvbStopListenAll(){
  _dvbListenAllActive = false;
  if(typeof stopAllAudio === 'function') try{ stopAllAudio(); }catch(e){}
  renderDvb();
}

function _dvbListenNext(words){
  if(!_dvbListenAllActive) return;
  if(_dvbListenAllIdx >= words.length){
    _dvbListenAllActive = false;
    renderDvb();
    return;
  }
  var w = words[_dvbListenAllIdx];
  _dvbListenAllIdx++;
  var btn = document.getElementById('dvb-listen-all-btn');
  if(btn) btn.textContent = '\u23F9 Stop ('+_dvbListenAllIdx+'/'+words.length+')';
  var audio = document.getElementById('tts-audio');
  var _next = function(){
    if(!_dvbListenAllActive) return;
    setTimeout(function(){ _dvbListenNext(words); }, 500);
  };
  if(audio && typeof audio.addEventListener === 'function'){
    var _handler = function(){
      audio.removeEventListener('ended', _handler);
      audio.removeEventListener('error', _handler);
      _next();
    };
    audio.addEventListener('ended', _handler);
    audio.addEventListener('error', _handler);
  } else {
    setTimeout(function(){ _dvbListenNext(words); }, 1500);
  }
  if(typeof speak === 'function'){
    try{ speak(w.ar); }catch(e){ _next(); }
  } else {
    setTimeout(function(){ _dvbListenNext(words); }, 1500);
  }
}

// Patch _dvbRenderBrowse to include Listen All button
(function(){
  var _origBrowse = _dvbRenderBrowse;
  _dvbRenderBrowse = function(){
    var html = _origBrowse.apply(this, arguments);
    var btn = _dvbListenAllActive
      ? '<button id="dvb-listen-all-btn" class="btn btn-outline" style="margin-bottom:10px" onclick="_dvbStopListenAll()">\u23F9 Stop ('+_dvbListenAllIdx+'/...)</button>'
      : '<button id="dvb-listen-all-btn" class="btn btn-outline" style="margin-bottom:10px" onclick="_dvbListenAll()">\uD83D\uDD0A Listen All</button>';
    return btn + html;
  };
  _dvbRenderBrowse.__r304Enhanced = true;
})();

// Patch closeDvb to stop Listen All
(function(){
  var _cDvb = closeDvb;
  closeDvb = function(){
    _dvbListenAllActive = false;
    _cDvb.apply(this, arguments);
  };
  closeDvb.__r304Fixed = true;
})();

// Patch _dvbSetCat to stop Listen All on category change
