function _tchListenNext(words){
  if(!_tchListenAllActive) return;
  if(_tchListenAllIdx >= words.length){
    _tchListenAllActive = false;
    renderTch();
    return;
  }
  var w = words[_tchListenAllIdx];
  _tchListenAllIdx++;
  var btn = document.getElementById('tch-listen-all-btn');
  if(btn) btn.textContent = '\u23F9 Stop ('+_tchListenAllIdx+'/'+words.length+')';
  var audio = document.getElementById('tts-audio');
  var _next = function(){
    if(!_tchListenAllActive) return;
    setTimeout(function(){ _tchListenNext(words); }, 500);
  };
  if(audio && typeof audio.addEventListener === 'function'){
    var _handler = function(){
      audio.removeEventListener('ended', _handler);
      audio.removeEventListener('error', _handler);
      _next();
    };
    audio.addEventListener('ended', _handler);
    audio.addEventListener('error', _handler);
  } else {
    setTimeout(function(){ _tchListenNext(words); }, 1500);
  }
  if(typeof speak === 'function'){
    try{ speak(w.ar); }catch(e){ _next(); }
  } else {
    setTimeout(function(){ _tchListenNext(words); }, 1500);
  }
}
