// ── R311 — BUG FIX: mini-coach pickOpt functions award XP on wrong answers ────
// fshPickOpt/dvbPickOpt/homPickOpt/prtPickOpt/bodPickOpt: call addXp()
// unconditionally — users earn XP even on incorrect answers, inflating levels.
// wrkPickOpt: misses recordActivity + addXp entirely.
// sclPickOpt: misses addXp entirely.
// Fix: wrap each pickOpt to guard addXp behind correctness check, and add
// missing calls. Standard pattern (matching main SRS rate()): recordActivity +
// incDailyCount always, addXp only when correct.

(function(){
  function _fixPick(fn, drillsVar, drillIdxVar, answeredVar){
    return function(i){
      fn.apply(this, arguments);
      // Undo unconditional addXp: subtract the XP that was just wrongly added
      // if the answer was incorrect.
      try {
        var drills = (typeof drillsVar !== 'undefined') ? drillsVar : [];
        if(!drills.length) return;
        var idx = (typeof drillIdxVar !== 'undefined' ? drillIdxVar : 0);
        var d = drills[idx % drills.length];
        if(i !== d.correct){
          // Wrong answer — take back the XP (addXp doesn't have undo, so subtract)
          var xp = (typeof XP_PER_RATING !== 'undefined' && XP_PER_RATING[2]) || 10;
          var cur; try{ cur = parseInt(localStorage.getItem('la_xp')||'0',10); } catch(e){ cur = 0; }
          if(typeof _lsSet === 'function') _lsSet('la_xp', String(Math.max(0, cur - xp)));
          if(typeof updateXpBadge === 'function') updateXpBadge();
        }
      } catch(e){}
    };
  }

  // FSH: addXp on wrong — patch
  var _origFsh = fshPickOpt;
  fshPickOpt = _fixPick(_origFsh, FSH_DRILLS, _fshDrillIdx, _fshDrillAnswered);
  Object.defineProperty(fshPickOpt, '_fshDrillIdx_ref', { get: function(){ return _fshDrillIdx; } });
  fshPickOpt.__r311Fixed = true;

  // DVB: addXp on wrong — patch
  var _origDvb = dvbPickOpt;
  dvbPickOpt = _fixPick(_origDvb, DVB_DRILLS, _dvbDrillIdx, _dvbDrillAnswered);
  dvbPickOpt.__r311Fixed = true;

  // HOM: addXp on wrong — patch
  var _origHom = homPickOpt;
  homPickOpt = _fixPick(_origHom, HOM_DRILLS, _homDrillIdx, _homDrillAnswered);
  homPickOpt.__r311Fixed = true;

  // PRT: addXp on wrong — patch
  var _origPrt = prtPickOpt;
  prtPickOpt = _fixPick(_origPrt, PRT_DRILLS, _prtDrillIdx, _prtDrillAnswered);
  prtPickOpt.__r311Fixed = true;

  // BOD: addXp on wrong — patch
  var _origBod = bodPickOpt;
  bodPickOpt = _fixPick(_origBod, BOD_DRILLS, _bodDrillIdx, _bodDrillAnswered);
  bodPickOpt.__r311Fixed = true;

  // WRK: misses recordActivity + addXp — wrap to add them (correct-only)
  var _origWrk = wrkPickOpt;
  wrkPickOpt = function(i){
    _origWrk.apply(this, arguments);
    try {
      var d = WRK_DRILLS[_wrkDrillIdx % WRK_DRILLS.length];
      if(i === d.correct){
        if(typeof recordActivity === 'function') recordActivity();
        var xp = (typeof XP_PER_RATING !== 'undefined' && XP_PER_RATING[2]) || 10;
        if(typeof addXp === 'function') addXp(xp);
      }
    } catch(e){}
  };
  wrkPickOpt.__r311Fixed = true;

  // SCL: misses addXp — wrap to add it (correct-only)
  var _origScl = sclPickOpt;
  sclPickOpt = function(i){
    _origScl.apply(this, arguments);
    try {
      var d = SCL_DRILLS[_sclDrillIdx % SCL_DRILLS.length];
      if(i === d.correct){
        var xp = (typeof XP_PER_RATING !== 'undefined' && XP_PER_RATING[2]) || 10;
        if(typeof addXp === 'function') addXp(xp);
      }
    } catch(e){}
  };
  sclPickOpt.__r311Fixed = true;
})();

// ── R311b — BUG FIX correction: _fixPick in R311 captured drillIdx by value ───
// (always 0) so rollback only worked for drill #0. Replace with XP-delta approach:
// snapshot XP before, call original, if wrong answer undo any XP gained.

(function(){
  function _xpDeltaFix(fn, getDrillsCurr, getDrillIdx){
    return function(i){
      var xpBefore = (typeof getXp === 'function') ? getXp() : 0;
      fn.apply(this, arguments);
      try {
        var drills = getDrillsCurr();
        var idx = getDrillIdx();
        if(!drills.length) return;
        var d = drills[idx % drills.length];
        if(i !== d.correct){
          var xpAfter = (typeof getXp === 'function') ? getXp() : 0;
          var gained = xpAfter - xpBefore;
          if(gained > 0 && typeof _lsSet === 'function'){
            _lsSet('la_xp', String(Math.max(0, xpAfter - gained)));
            if(typeof updateXpBadge === 'function') updateXpBadge();
          }
        }
      } catch(e){}
    };
  }

  fshPickOpt = _xpDeltaFix(fshPickOpt,
    function(){ return (typeof FSH_DRILLS!=='undefined')?FSH_DRILLS:[]; },
    function(){ return _fshDrillIdx; });
  fshPickOpt.__r311Fixed = true; fshPickOpt.__r311bCorrected = true;

  dvbPickOpt = _xpDeltaFix(dvbPickOpt,
    function(){ return (typeof DVB_DRILLS!=='undefined')?DVB_DRILLS:[]; },
    function(){ return _dvbDrillIdx; });
  dvbPickOpt.__r311Fixed = true; dvbPickOpt.__r311bCorrected = true;

  homPickOpt = _xpDeltaFix(homPickOpt,
    function(){ return (typeof HOM_DRILLS!=='undefined')?HOM_DRILLS:[]; },
    function(){ return _homDrillIdx; });
  homPickOpt.__r311Fixed = true; homPickOpt.__r311bCorrected = true;

  prtPickOpt = _xpDeltaFix(prtPickOpt,
    function(){ return (typeof PRT_DRILLS!=='undefined')?PRT_DRILLS:[]; },
    function(){ return _prtDrillIdx; });
  prtPickOpt.__r311Fixed = true; prtPickOpt.__r311bCorrected = true;

  bodPickOpt = _xpDeltaFix(bodPickOpt,
    function(){ return (typeof BOD_DRILLS!=='undefined')?BOD_DRILLS:[]; },
    function(){ return _bodDrillIdx; });
  bodPickOpt.__r311Fixed = true; bodPickOpt.__r311bCorrected = true;
})();

