function _cknSetCat(c){
  _cknCat = c;
  var el = document.getElementById('ckn-content'); if(!el) return;
  el.innerHTML = _cknRenderBrowse();
}

function _cknRenderDrill(){
  if(typeof CKN_DRILLS==='undefined') return '<p>No drills.</p>';
  var drills = CKN_DRILLS;
  var idx = _cknDrillIdx % drills.length;
  var d = drills[idx];
  var statsEl = document.getElementById('ckn-stats');
  if(statsEl) statsEl.textContent = (idx+1)+' / '+drills.length;
  return '<div style="max-width:640px;margin:0 auto">'+
    '<div style="font-weight:600;font-size:1.05rem;margin-bottom:16px;line-height:1.5">'+d.q+'</div>'+
    '<div id="ckn-opts" style="display:flex;flex-direction:column;gap:8px">'+
    d.opts.map(function(o,i){ return '<button id="ckn-opt-'+i+'" class="btn btn-outline" style="text-align:left;padding:10px 14px" onclick="cknPickOpt('+i+')">'+o+'</button>'; }).join('')+
    '</div>'+
    '<div id="ckn-note" style="display:none;margin-top:14px;padding:12px;background:var(--surface2);border-radius:8px;font-size:0.9rem;line-height:1.55;color:var(--muted)"></div>'+
    '<button id="ckn-next" class="btn btn-primary" style="display:none;margin-top:12px" onclick="_cknDrillNext()">Next →</button>'+
    '</div>';
}

function cknPickOpt(i){
  if(_cknDrillAnswered) return;
  _cknDrillAnswered = true;
  var drills = (typeof CKN_DRILLS !== 'undefined') ? CKN_DRILLS : [];
  var d = drills[_cknDrillIdx % drills.length];
  var correct = (i === d.correct);
  if(correct){
    if(typeof recordActivity === 'function') try{ recordActivity(); }catch(e){}
    if(typeof incDailyCount === 'function') try{ incDailyCount(); }catch(e){}
    if(typeof addXp === 'function') try{ addXp(10); }catch(e){}
  }
  var opts = document.getElementById('ckn-opts');
  if(opts){
    var btns = opts.querySelectorAll('button');
    for(var b=0;b<btns.length;b++){
      if(b===d.correct) btns[b].style.background='var(--success,#22c55e)';
      else if(b===i&&!correct) btns[b].style.background='var(--danger,#ef4444)';
      btns[b].disabled=true;
    }
  }
  var note = document.getElementById('ckn-note');
  if(note){ note.style.display='block'; note.textContent=d.note; }
  var nxt = document.getElementById('ckn-next');
  if(nxt) nxt.style.display='block';
  _cknTimer = setTimeout(_cknDrillNext, 1800);
}

function _cknDrillNext(){
  if(_cknTimer){ clearTimeout(_cknTimer); _cknTimer=null; }
  _cknDrillIdx++;
  _cknDrillAnswered=false;
  renderCkn();
}

function _cknRenderTips(){
  if(typeof CKN_TIPS==='undefined') return '<p>No tips.</p>';
  return CKN_TIPS.map(function(t){
    return '<div style="margin-bottom:16px;padding:14px;background:var(--surface2);border-radius:10px">'+
      '<strong>'+t.title+'</strong>'+
      '<p style="margin:8px 0 0;font-size:0.9rem;color:var(--muted);line-height:1.6">'+t.body+'</p>'+
      '</div>';
  }).join('');
}


