// ── R326 — BUG FIX: Post-close timer guard for HLT and TDR coaches ──────────
// hltPickOpt / tdrPickOpt call setTimeout(()=>_hltDrillNext(), 1800) without
// storing the timer handle — clearTimeout is impossible. If user closes the
// overlay before 1800ms, the timer fires anyway, advancing the drill index and
// re-rendering into the hidden DOM element. Next open shows wrong question.
// R317 fixed FDR/NMC/CDS/DPL with the same pattern; HLT and TDR were missed
// because they predate R272's IIFE-timer approach and use inline arrow fns.
// Fix: wrap _hltDrillNext and _tdrDrillNext to bail when overlay is hidden.
(function(){
  function _guardDrillNext326(fn, overlayId){
    if(!fn || fn.__r326Fixed) return fn;
    var _orig = fn;
    var wrapped = function(){
      var ov = document.getElementById(overlayId);
      if(ov && ov.style.display === 'none') return;
      _orig.apply(this, arguments);
    };
    wrapped.__r326Fixed = true;
    return wrapped;
  }
  _hltDrillNext = _guardDrillNext326(_hltDrillNext, 'hlt-overlay');
  _tdrDrillNext = _guardDrillNext326(_tdrDrillNext, 'tdr-overlay');
})();

