// ── R329 — BUG FIX: Register missing coaches in TOPICS_CATEGORIES ────────────
// HSP/TCH/SLE/SPT tried TOPICS.push() but TOPICS is never declared — always
// silently skipped. WTH/CKN/OCC/SLN registered nowhere at all.
// Result: 8 coaches invisible in the Topics/Vocabulary browser.
// Fix: register all 8 in TOPICS_CATEGORIES vocab, same pattern as DVB/FSH/MNY.
(function(){
  if(typeof TOPICS_CATEGORIES === 'undefined') return;
  var vocab = TOPICS_CATEGORIES.find(function(c){ return c.id === 'vocab'; });
  if(!vocab) return;
  var toAdd = [
    { fn:'openHsp', label:'🫖 Hospitality & Guests',      desc:'greetings, hosting, guest culture, visiting phrases' },
    { fn:'openTch', label:'📱 Tech & Social Media',        desc:'phones, apps, internet, Lebanese digital culture' },
    { fn:'openSle', label:'🗣️ Slang & Expressions',        desc:'street slang, colloquial phrases, youth language' },
    { fn:'openSpt', label:'⚽ Sports & Recreation',         desc:'sports vocab, team phrases, Lebanese sports culture' },
    { fn:'openWth', label:'🌤️ Weather & Seasons',           desc:'conditions, temperature, seasons, nature expressions' },
    { fn:'openCkn', label:'🍽️ Cuisine & Cooking',           desc:'dishes, ingredients, cooking verbs, mezze culture' },
    { fn:'openOcc', label:'🎉 Celebrations & Occasions',   desc:'weddings, greetings, religious holidays, condolences' },
    { fn:'openSln', label:'😎 Slang & Street Talk',         desc:'everyday slang, reactions, compliments, social phrases' },
  ];
  toAdd.forEach(function(item){
    if(!vocab.items.some(function(i){ return i.fn === item.fn; })){
      vocab.items.push(item);
    }
  });
})();

