// ── R335 — BUG FIX: openWth audio precache used w.tr instead of w.ar ─────────
// openWth called _audioBulkPrecache(WTH_WORDS.map(w=>w.tr)) — romanized text
// cannot be looked up in the Arabic audio cache and produces wrong TTS.
// Also: openCkn/openOcc/openSln/openCty/openRlv had no precache calls at all,
// so first-open audio was always cold (extra delay on first speak()).
// Fix: patch openWth to use w.ar; add precache wrapping to the other 5 coaches.
(function(){
  // Fix openWth: replace w.tr with w.ar in precache call
  var _origWth = openWth;
  openWth = function(){
    if(typeof _audioBulkPrecache === 'function' && typeof WTH_WORDS !== 'undefined'){
      try{ _audioBulkPrecache(WTH_WORDS.map(function(w){ return w.ar; })).catch(function(){}); }catch(e){}
    }
    _origWth.apply(this, arguments);
  };
  openWth.__r318Added = true;
  openWth.__r335Fixed = true;

  // Add precache to coaches that had none
  function _addPrecache(openFn, wordsConst, marker){
    var _orig = openFn;
    var _wrapped = function(){
      if(typeof _audioBulkPrecache === 'function' && typeof window[wordsConst] !== 'undefined'){
        try{ _audioBulkPrecache(window[wordsConst].map(function(w){ return w.ar; })).catch(function(){}); }catch(e){}
      }
      _orig.apply(this, arguments);
    };
    _wrapped.__r335Added = true;
    _wrapped[marker] = true;
    return _wrapped;
  }

  openCkn = _addPrecache(openCkn, 'CKN_WORDS', '__r321Added');
  openOcc = _addPrecache(openOcc, 'OCC_WORDS', '__r324Added');
  openSln = _addPrecache(openSln, 'SLN_WORDS', '__r327Added');
  openCty = _addPrecache(openCty, 'CTY_WORDS', '__r330Added');
  openRlv = _addPrecache(openRlv, 'RLV_WORDS', '__r333Added');
})();

