// Run #341 — BUG FIX: XP/count awarded on wrong answers in BOD/MNY/FSH/DVB
// Root cause: bodPickOpt, mnyPickOpt, fshPickOpt, dvbPickOpt call
// recordActivity + incDailyCount + addXp outside any if(correct) guard.
// All other coaches (HSP, TCH, SLE, SPT, WTH, CKN, OCC, SLN, CTY, RLV,
// ZWY, TRB) correctly wrap these calls inside if(correct).
// Fix: wrap each function to temporarily neutralize the XP/count calls
// when the user picks a wrong answer, then restore them.
// ============================================================
(function(){
  function _makeCorrectOnlyPickOpt(fn, getDrillFn, answeredFlag) {
    var _orig = fn;
    return function(i) {
      if (window[answeredFlag]) return;
      var d = getDrillFn();
      if (!d) { _orig.apply(this, arguments); return; }
      var correct = (i === d.correct);
      if (correct) {
        _orig.apply(this, arguments);
      } else {
        var _ra = recordActivity, _ic = incDailyCount, _ax = addXp;
        recordActivity = function(){};
        incDailyCount = function(){};
        addXp = function(){};
        _orig.apply(this, arguments);
        recordActivity = _ra;
        incDailyCount = _ic;
        addXp = _ax;
      }
    };
  }

  bodPickOpt = _makeCorrectOnlyPickOpt(
    bodPickOpt,
    function(){ return typeof BOD_DRILLS !== 'undefined' ? BOD_DRILLS[_bodDrillIdx % BOD_DRILLS.length] : null; },
    '_bodDrillAnswered'
  );
  bodPickOpt.__r341Fixed = true;

  mnyPickOpt = _makeCorrectOnlyPickOpt(
    mnyPickOpt,
    function(){ return typeof MNY_DRILLS !== 'undefined' ? MNY_DRILLS[_mnyDrillIdx % MNY_DRILLS.length] : null; },
    '_mnyDrillAnswered'
  );
  mnyPickOpt.__r341Fixed = true;

  fshPickOpt = _makeCorrectOnlyPickOpt(
    fshPickOpt,
    function(){ return typeof FSH_DRILLS !== 'undefined' ? FSH_DRILLS[_fshDrillIdx % FSH_DRILLS.length] : null; },
    '_fshDrillAnswered'
  );
  fshPickOpt.__r341Fixed = true;

  dvbPickOpt = _makeCorrectOnlyPickOpt(
    dvbPickOpt,
    function(){ return typeof DVB_DRILLS !== 'undefined' ? DVB_DRILLS[_dvbDrillIdx % DVB_DRILLS.length] : null; },
    '_dvbDrillAnswered'
  );
  dvbPickOpt.__r341Fixed = true;
})();

