function _tndSetCat(c) { _tndCatFilter = c; renderTnd(); }

function renderTnd() {
  const el = document.getElementById('tnd-content');
  const stats = document.getElementById('tnd-stats');
  if (!el || typeof TND_WORDS === 'undefined') return;
  if (stats) stats.textContent = TND_WORDS.length + ' expressions';
  if (_tndTab === 'browse') {
    const cats = ['all','beloved','family-address','admiration','blessings','warmth'];
    const catLabels = {'all':'All','beloved':'💖 Beloved','family-address':'👨‍👩‍👧 Family','admiration':'⭐ Admiration','blessings':'🙏 Blessings','warmth':'🌻 Warmth'};
    let html = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px;justify-content:center">';
    cats.forEach(function(c){
      html += '<button class="cat-filter ' + (_tndCatFilter === c ? 'active' : '') + '" onclick="_tndSetCat(\'' + c + '\')">' + (catLabels[c] || c) + '</button>';
    });
    html += '</div><div style="display:grid;gap:10px;grid-template-columns:repeat(auto-fill,minmax(280px,1fr))">';
    const filtered = _tndCatFilter === 'all' ? TND_WORDS : TND_WORDS.filter(function(w){ return w.cat === _tndCatFilter; });
    filtered.forEach(function(w){
      const arDisplay = w.ar;
      const speakAr = w.ar.split('/')[0].trim();
      html += '<div style="background:var(--card);border-radius:10px;padding:14px;cursor:pointer" onclick="speak && speak(\'' + speakAr.replace(/'/g,"\\'") + '\')">';
      html += '<div style="font-size:1.5rem;font-weight:700;direction:rtl;margin-bottom:4px">' + arDisplay + '</div>';
      html += '<div style="color:var(--muted);font-size:0.85rem;margin-bottom:4px">' + w.tr + '</div>';
      const enShort = w.en.split('(')[0].trim();
      const enNote = w.en.indexOf('(') > -1 ? w.en.substring(w.en.indexOf('(')) : '';
      html += '<div style="font-size:0.9rem;font-weight:600;margin-bottom:2px">' + enShort + '</div>';
      if (enNote) html += '<div style="font-size:0.8rem;color:var(--muted)">' + enNote + '</div>';
      html += '</div>';
    });
    html += '</div>';
    el.innerHTML = html;
  } else if (_tndTab === 'drill') {
    _tndDrillNext(el);
  } else if (_tndTab === 'tips') {
    if (typeof TND_TIPS === 'undefined') { el.innerHTML = ''; return; }
    let html = '<div style="max-width:700px;margin:0 auto">';
    TND_TIPS.forEach(function(tip, i){
      html += '<div style="background:var(--card);border-radius:10px;padding:16px;margin-bottom:12px">';
      html += '<div style="font-weight:700;margin-bottom:6px">💡 Tip ' + (i+1) + '</div>';
      html += '<div style="font-size:0.9rem;line-height:1.6">' + tip + '</div></div>';
    });
    html += '</div>';
    el.innerHTML = html;
  } else if (_tndTab === 'about') {
    const txt = typeof TND_ABOUT !== 'undefined' ? TND_ABOUT : '';
    el.innerHTML = '<div style="max-width:700px;margin:0 auto;background:var(--surface);border-radius:10px;padding:20px;line-height:1.7;font-size:0.95rem">' + txt + '</div>';
  }
}

function _tndDrillNext(el) {
  const ov = document.getElementById('tnd-overlay');
  if (ov && ov.style.display === 'none') return;
  if (!el) el = document.getElementById('tnd-content');
  if (!el || typeof TND_DRILLS === 'undefined') return;
  const d = TND_DRILLS[_tndDrillIdx % TND_DRILLS.length];
  const progress = '<div style="color:var(--muted);font-size:0.82rem;margin-bottom:12px;text-align:center">Question ' + (_tndDrillIdx % TND_DRILLS.length + 1) + ' / ' + TND_DRILLS.length + '</div>';
  const qhtml = '<div style="text-align:center;margin-bottom:20px;font-size:1rem;line-height:1.5;padding:0 8px">' + d.q + '</div>';
  let optsHtml = '<div style="display:flex;flex-direction:column;gap:10px;max-width:560px;margin:0 auto">';
  d.opts.forEach(function(opt, i){
    optsHtml += '<button onclick="tndPickOpt(' + i + ')" style="background:var(--card);border:2px solid transparent;border-radius:8px;padding:12px 16px;text-align:left;cursor:pointer;color:inherit;font-size:0.92rem">' + opt + '</button>';
  });
  optsHtml += '</div>';
  el.innerHTML = progress + qhtml + optsHtml + '<div id="tnd-drill-note" style="display:none;max-width:560px;margin:16px auto 0;background:var(--surface);border-radius:8px;padding:14px;font-size:0.88rem;line-height:1.6"></div>';
}

function tndPickOpt(i) {
  if (typeof TND_DRILLS === 'undefined') return;
  if (_tndDrillPicked !== null) return;
  _tndDrillPicked = i;
  const d = TND_DRILLS[_tndDrillIdx % TND_DRILLS.length];
  const correct = (i === d.correct);
  const el = document.getElementById('tnd-content');
  if (el) {
    const btns = el.querySelectorAll('button');
    for (var b = 0; b < btns.length; b++) {
      btns[b].disabled = true;
      if (b === d.correct) btns[b].style.background = 'rgba(34,197,94,0.2)';
      else if (b === i && !correct) btns[b].style.background = 'rgba(239,68,68,0.2)';
    }
  }
  if (correct) {
    try { if (typeof recordActivity === 'function') recordActivity(); } catch(e){}
    try { if (typeof incDailyCount === 'function') incDailyCount(); } catch(e){}
    try { if (typeof addXp === 'function') addXp((typeof XP_PER_RATING !== 'undefined' && XP_PER_RATING[2]) || 10); } catch(e){}
    try {
      var correctTr = d.opts[d.correct];
      var words = typeof TND_WORDS !== 'undefined' ? TND_WORDS : [];
      for (var j = 0; j < words.length; j++) {
        if (words[j].tr === correctTr && words[j].ar) {
          var _ar = words[j].ar.split('/')[0].trim();
          setTimeout(function(){ try { if (typeof speak === 'function') speak(_ar); } catch(e){} }, 600);
          break;
        }
      }
    } catch(e){}
  }
  const note = document.getElementById('tnd-drill-note');
  if (note) { note.style.display = 'block'; note.innerHTML = (correct ? '✅ Correct! ' : '❌ Not quite. ') + d.note; }
  setTimeout(function(){ _tndDrillIdx++; _tndDrillPicked = null; _tndDrillNext(); }, correct ? 2200 : 3200);
}
