function _polDrillNext(elArg) {
  var ov = document.getElementById('pol-overlay');
  if (ov && ov.style.display === 'none') return;
  var el = elArg || document.getElementById('pol-content');
  if (!el) return;
  var drills = typeof POL_DRILLS !== 'undefined' ? POL_DRILLS : [];
  if (!drills.length) { el.innerHTML = '<p>No drills available.</p>'; return; }
  var d = drills[_polDrillIdx % drills.length];
  _polDrillPicked = null;
  el.innerHTML = '<div style="max-width:600px;margin:0 auto">' +
    '<div style="background:var(--surface2);border-radius:12px;padding:20px;margin-bottom:16px">' +
    '<div style="font-size:0.8rem;color:var(--muted);margin-bottom:8px">Question ' + ((_polDrillIdx % drills.length) + 1) + ' / ' + drills.length + '</div>' +
    '<div style="font-size:1.1rem;font-weight:600;line-height:1.5">' + d.q + '</div></div>' +
    '<div style="display:grid;gap:10px">' +
    d.opts.map(function(opt, i){
      return '<button class="btn btn-outline" style="text-align:left;padding:14px 18px;font-size:1rem" onclick="polPickOpt(' + i + ')">' + opt + '</button>';
    }).join('') + '</div>' +
    '<div id="pol-drill-note" style="display:none;margin-top:16px;padding:14px;background:var(--surface2);border-radius:10px;font-size:0.9rem;line-height:1.6"></div>' +
    '</div>';
}

function polPickOpt(i) {
  if (_polDrillPicked !== null) return;
  _polDrillPicked = i;
  var drills = typeof POL_DRILLS !== 'undefined' ? POL_DRILLS : [];
  var d = drills[_polDrillIdx % drills.length];
  var correct = (i === d.correct);
  var el = document.getElementById('pol-content');
  if (el) {
    var btns = el.querySelectorAll('button');
    for (var b = 0; b < btns.length; b++) {
      btns[b].disabled = true;
      if (b === d.correct) btns[b].style.background = 'rgba(34,197,94,0.2)';
      else if (b === i && !correct) btns[b].style.background = 'rgba(239,68,68,0.2)';
    }
  }
  if (correct) {
    try { if (typeof recordActivity === 'function') recordActivity(); } catch(e) {}
    try { if (typeof incDailyCount === 'function') incDailyCount(); } catch(e) {}
    try { if (typeof addXp === 'function') addXp((typeof XP_PER_RATING !== 'undefined' && XP_PER_RATING[2]) || 10); } catch(e) {}
    try {
      var correctTr = d.opts[d.correct];
      var words = typeof POL_WORDS !== 'undefined' ? POL_WORDS : [];
      for (var j = 0; j < words.length; j++) {
        if (words[j].tr === correctTr && words[j].ar) {
          var _ar = words[j].ar;
          setTimeout(function(){ try { if (typeof speak === 'function') speak(_ar); } catch(e) {} }, 600);
          break;
        }
      }
    } catch(e) {}
  }
  var note = document.getElementById('pol-drill-note');
  if (note) { note.style.display = 'block'; note.innerHTML = (correct ? '✅ Correct! ' : '❌ Not quite. ') + d.note; }
  setTimeout(function(){ _polDrillIdx++; _polDrillPicked = null; _polDrillNext(); }, correct ? 2200 : 3200);
}
