var _rdmTab = 'browse';
var _rdmCatFilter = 'all';
var _rdmDrillIdx = 0;
var _rdmDrillPicked = null;
var _rdmDrillScore = { correct: 0, total: 0 };

function openRdm() {
  bumpAchievementCounter && bumpAchievementCounter('rdm_open');
  var ov = document.getElementById('rdm-overlay');
  if (!ov) return;
  _rdmDrillPicked = null;
  _rdmDrillIdx = 0;
  _rdmDrillScore = { correct: 0, total: 0 };
  ov.style.display = 'block';
  try {
    if (typeof RDM_WORDS !== 'undefined' && RDM_WORDS.length && typeof _audioBulkPrecache === 'function') {
      _audioBulkPrecache(RDM_WORDS.map(function(w){ return w.ar; })).catch(function(){});
    }
  } catch(e) {}
  setRdmTab('browse');
}
function closeRdm() {
  var ov = document.getElementById('rdm-overlay');
  if (ov) ov.style.display = 'none';
}
function setRdmTab(t) {
  _rdmTab = t;
  var bar = document.getElementById('rdm-tab-bar');
  if (bar) {
    var tabs = [['browse','📋 Browse'],['drill','🎯 Drill'],['tips','💡 Tips'],['about','ℹ️ About']];
    bar.innerHTML = tabs.map(function(kl){ return '<button class="cat-filter ' + (_rdmTab===kl[0]?'active':'') + '" onclick="setRdmTab(\'' + kl[0] + '\')">' + kl[1] + '</button>'; }).join('');
  }
  renderRdm();
}
function _rdmSetCat(c) {
  _rdmCatFilter = c;
  renderRdm();
}
function renderRdm() {
  var el = document.getElementById('rdm-content');
  if (!el || typeof RDM_WORDS === 'undefined') return;
  var stats = document.getElementById('rdm-stats');
  if (stats) stats.textContent = RDM_WORDS.length + ' words';
  if (_rdmTab === 'browse') {
    var cats = ['all','greetings','fasting','food','culture','eid'];
    var catLabels = {all:'All',greetings:'🌙 Greetings',fasting:'🕌 Fasting',food:'🍽️ Food',culture:'🪔 Culture',eid:'🎉 Eid'};
    var filtered = _rdmCatFilter === 'all' ? RDM_WORDS : RDM_WORDS.filter(function(w){ return w.cat === _rdmCatFilter; });
    el.innerHTML = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">' +
      cats.map(function(c){ return '<button class="cat-filter ' + (_rdmCatFilter===c?'active':'') + '" onclick="_rdmSetCat(\'' + c + '\')">' + catLabels[c] + '</button>'; }).join('') +
      '</div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">' +
      filtered.map(function(w){
        return '<div class="word-card" style="cursor:pointer" onclick="speak(\'' + w.ar.replace(/'/g,"\\'") + '\')">' +
          '<div style="font-size:1.4rem;font-weight:700;direction:rtl">' + w.ar + '</div>' +
          '<div style="color:var(--accent);font-size:0.85rem">' + w.tr + '</div>' +
          '<div style="color:var(--muted);font-size:0.82rem">' + w.en + '</div></div>';
      }).join('') + '</div>';
  } else if (_rdmTab === 'drill') {
    _rdmDrillNext(el);
  } else if (_rdmTab === 'tips') {
    if (typeof RDM_TIPS === 'undefined') { el.innerHTML = '<p>Tips unavailable.</p>'; return; }
    el.innerHTML = RDM_TIPS.map(function(t){
      return '<div class="word-card" style="margin-bottom:12px"><div style="font-weight:700;margin-bottom:6px">' + t.title + '</div><div style="color:var(--muted);font-size:0.9rem;line-height:1.5">' + t.body + '</div></div>';
    }).join('');
  } else if (_rdmTab === 'about') {
    el.innerHTML = '<div class="word-card"><p style="line-height:1.6">' + (typeof RDM_ABOUT !== 'undefined' ? RDM_ABOUT : '') + '</p></div>';
  }
}
function _rdmDrillNext(elArg) {
  var ov = document.getElementById('rdm-overlay');
  if (ov && ov.style.display === 'none') return;
  var el = elArg || document.getElementById('rdm-content');
  if (!el || typeof RDM_DRILLS === 'undefined') return;
  if (_rdmDrillIdx >= RDM_DRILLS.length) {
    el.innerHTML = '<div class="word-card" style="text-align:center"><div style="font-size:2rem">🌙</div><div style="font-weight:700;margin:10px 0">All drills done!</div><div style="color:var(--muted)">' + _rdmDrillScore.correct + ' / ' + _rdmDrillScore.total + ' correct</div><button class="btn" style="margin-top:14px" onclick="_rdmDrillIdx=0;_rdmDrillScore={correct:0,total:0};_rdmDrillNext()">Restart</button></div>';
    return;
  }
  var d = RDM_DRILLS[_rdmDrillIdx];
  _rdmDrillPicked = null;
  el.innerHTML = '<div class="word-card"><div style="font-size:0.75rem;color:var(--muted);margin-bottom:8px">Question ' + (_rdmDrillIdx+1) + ' / ' + RDM_DRILLS.length + '</div>' +
    '<div style="font-weight:700;font-size:1rem;margin-bottom:16px;line-height:1.5">' + d.q + '</div>' +
    '<div style="display:flex;flex-direction:column;gap:8px">' +
    d.opts.map(function(o, i){ return '<button class="btn btn-outline" id="rdm-opt-' + i + '" onclick="rdmPickOpt(' + i + ')">' + o + '</button>'; }).join('') +
    '</div><div id="rdm-note" style="margin-top:14px;display:none"></div>' +
    '<div style="text-align:right;margin-top:12px"><button class="btn" id="rdm-next-btn" style="display:none" onclick="_rdmDrillIdx++;_rdmDrillNext()">Next →</button></div></div>';
}
function rdmPickOpt(i) {
  if (_rdmDrillPicked !== null) return;
  _rdmDrillPicked = i;
  var d = RDM_DRILLS[_rdmDrillIdx];
  var correct = (i === d.correct);
  if (correct) {
    _rdmDrillScore.correct++;
    try { if (typeof recordActivity === 'function') recordActivity(); } catch(e) {}
    try { if (typeof incDailyCount === 'function') incDailyCount(); } catch(e) {}
    try { if (typeof addXp === 'function') addXp((typeof XP_PER_RATING !== 'undefined' && XP_PER_RATING[2]) || 10); } catch(e) {}
    try {
      var correctOpt = d.opts[d.correct];
      var words = typeof RDM_WORDS !== 'undefined' ? RDM_WORDS : [];
      for (var j = 0; j < words.length; j++) {
        if (words[j].tr === correctOpt && words[j].ar) {
          var _ar = words[j].ar;
          setTimeout(function(){ try { if (typeof speak === 'function') speak(_ar); } catch(e2) {} }, 600);
          break;
        }
      }
    } catch(e) {}
  }
  _rdmDrillScore.total++;
  for (var k = 0; k < d.opts.length; k++) {
    var btn = document.getElementById('rdm-opt-' + k);
    if (!btn) continue;
    btn.disabled = true;
    if (k === d.correct) btn.style.background = '#22c55e';
    else if (k === i && !correct) btn.style.background = '#ef4444';
  }
  var note = document.getElementById('rdm-note');
  if (note) { note.style.display = 'block'; note.innerHTML = '<div style="background:var(--card-bg);border-radius:8px;padding:12px;font-size:0.85rem;line-height:1.5;color:var(--muted)">' + (correct ? '✅ ' : '❌ ') + d.note + '</div>'; }
  var nb = document.getElementById('rdm-next-btn');
  if (nb) nb.style.display = 'inline-block';
}
