// ── R436: Fix drill audio for vlg/pol/cfc/air/rdm (en+tr lookup) ─────────────
// These coaches' pickOpt functions searched w.tr === d.opts[d.correct], but
// drill options are English text (e.g. "village center square" ≠ tr "saa7a").
// Wraps each pickOpt to also check w.en after the original fires silently.
(function(){
  function _r436TrySpeak(drillIdx, drillsArr, wordsArr) {
    if (!drillsArr || !wordsArr || typeof speak !== 'function') return;
    var d = drillsArr[drillIdx % drillsArr.length];
    if (!d) return;
    var correctOpt = d.opts && d.opts[d.correct];
    if (!correctOpt) return;
    setTimeout(function(){
      for (var j = 0; j < wordsArr.length; j++) {
        var w = wordsArr[j];
        if (!w || !w.ar) continue;
        if (w.en === correctOpt || w.tr === correctOpt) {
          try { speak(w.ar); } catch(e2) {}
          return;
        }
      }
    }, 700);
  }

  function _r436Wrap(fn, getDrillIdx, getDrills, getWords) {
    if (!fn || fn.__r436AudioFixed) return fn;
    var _orig = fn;
    var wrapped = function(i) {
      var drills = getDrills();
      var idx = getDrillIdx();
      var d = drills && drills[idx % (drills.length || 1)];
      var isCorrect = d && (i === d.correct);
      _orig.apply(this, arguments);
      if (isCorrect) _r436TrySpeak(idx, drills, getWords());
    };
    for (var _k in _orig) { try { wrapped[_k] = _orig[_k]; } catch(e) {} }
    wrapped.__r436AudioFixed = true;
    return wrapped;
  }

  if (typeof vlgPickOpt === 'function')
    vlgPickOpt = _r436Wrap(vlgPickOpt,
      function(){ return _vlgDrillIdx; },
      function(){ return typeof VLG_DRILLS !== 'undefined' ? VLG_DRILLS : []; },
      function(){ return typeof VLG_WORDS  !== 'undefined' ? VLG_WORDS  : []; });

  if (typeof polPickOpt === 'function')
    polPickOpt = _r436Wrap(polPickOpt,
      function(){ return _polDrillIdx; },
      function(){ return typeof POL_DRILLS !== 'undefined' ? POL_DRILLS : []; },
      function(){ return typeof POL_WORDS  !== 'undefined' ? POL_WORDS  : []; });

  if (typeof cfcPickOpt === 'function')
    cfcPickOpt = _r436Wrap(cfcPickOpt,
      function(){ return _cfcDrillIdx; },
      function(){ return typeof CFC_DRILLS !== 'undefined' ? CFC_DRILLS : []; },
      function(){ return typeof CFC_WORDS  !== 'undefined' ? CFC_WORDS  : []; });

  if (typeof airPickOpt === 'function')
    airPickOpt = _r436Wrap(airPickOpt,
      function(){ return _airDrillIdx; },
      function(){ return typeof AIR_DRILLS !== 'undefined' ? AIR_DRILLS : []; },
      function(){ return typeof AIR_WORDS  !== 'undefined' ? AIR_WORDS  : []; });

  if (typeof rdmPickOpt === 'function')
    rdmPickOpt = _r436Wrap(rdmPickOpt,
      function(){ return _rdmDrillIdx; },
      function(){ return typeof RDM_DRILLS !== 'undefined' ? RDM_DRILLS : []; },
      function(){ return typeof RDM_WORDS  !== 'undefined' ? RDM_WORDS  : []; });
})();
// ── end R436 ─────────────────────────────────────────────────────────────────

