      `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">${filtered.map(w=>`<div class="card" style="padding:12px"><div style="font-size:1.3rem;font-weight:700">${w.ar}</div><div style="color:var(--muted);font-size:0.85rem">${w.tr}</div><div style="margin-top:4px">${w.en}</div><button class="btn btn-sm" style="margin-top:6px" onclick="speak('${w.ar.replace(/'/g,"\\'")}')">🔊</button></div>`).join('')}</div>`;
