// ============================================================
var _slcTab = 'vocab';
var _slcCat = 'all';
var _slcDrillIdx = 0;
var _slcDrillPicked = null;
var _slcDrillScore = {correct: 0, total: 0};

function openSlc() {
  bumpAchievementCounter && bumpAchievementCounter('slc_open');
  const ov = document.getElementById('slc-overlay'); if (!ov) return;
  _slcDrillIdx = 0; _slcDrillPicked = null; _slcDrillScore = {correct: 0, total: 0};
  ov.style.display = 'block';
  setSlcTab('vocab');
}
function closeSlc() { const ov = document.getElementById('slc-overlay'); if (ov) ov.style.display = 'none'; }
function setSlcTab(t) {
  _slcTab = t;
  const bar = document.getElementById('slc-tab-bar');
  if (bar) {
    const tabs = [['vocab','📋 Vocab'],['drill','🎯 Drill'],['tips','💡 Tips'],['about','ℹ️ About']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_slcTab===k?'active':''}" onclick="setSlcTab('${k}')">${l}</button>`).join('');
  }
  renderSlc();
}
function renderSlc() {
  const el = document.getElementById('slc-content'); if (!el) return;
  const stats = document.getElementById('slc-stats');
  if (_slcTab === 'vocab') {
    const cats = ['all','classic','digital','youth','frustration','social'];
    const catLabels = {all:'All',classic:'Classic',digital:'Digital/WhatsApp',youth:'Youth Slang',frustration:'Frustration',social:'Social'};
    const words = (typeof SLC_WORDS !== 'undefined') ? SLC_WORDS : [];
    const filtered = _slcCat === 'all' ? words : words.filter(w => w.cat === _slcCat);
    if (stats) stats.textContent = filtered.length + ' expressions';
    el.innerHTML = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px">${cats.map(c=>`<button class="cat-filter ${_slcCat===c?'active':''}" onclick="_slcCat='${c}';renderSlc()">${catLabels[c]||c}</button>`).join('')}</div>` +
      `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">${filtered.map(w=>`<div class="card" style="padding:12px"><div style="font-size:1.3rem;font-weight:700">${w.ar}</div><div style="color:var(--muted);font-size:0.85rem">${w.tr}</div><div style="margin-top:4px;font-size:0.9rem">${w.en}</div><button class="btn btn-sm" style="margin-top:6px" onclick="speak('${w.ar.replace(/'/g,"\\'")}')">🔊</button></div>`).join('')}</div>`;
  } else if (_slcTab === 'drill') {
    const drills = (typeof SLC_DRILLS !== 'undefined') ? SLC_DRILLS : [];
    if (!drills.length) { el.innerHTML = '<p>No drills.</p>'; return; }
    if (_slcDrillIdx >= drills.length) {
      const sc = _slcDrillScore;
      if (stats) stats.textContent = sc.correct + '/' + sc.total;
      el.innerHTML = `<div style="text-align:center;padding:40px"><div style="font-size:2.5rem">🎉</div><div style="font-size:1.3rem;font-weight:700;margin:12px 0">${sc.correct}/${sc.total} correct</div><button class="btn" onclick="slcRestartDrill()">🔄 Restart</button></div>`;
      return;
    }
    const d = drills[_slcDrillIdx];
    if (stats) stats.textContent = (_slcDrillIdx+1) + '/' + drills.length + ' · ' + _slcDrillScore.correct + ' correct';
    const picked = _slcDrillPicked;
    el.innerHTML = `<div class="card" style="padding:20px;max-width:600px;margin:0 auto"><div style="font-weight:600;margin-bottom:16px">${d.q}</div><div style="display:flex;flex-direction:column;gap:8px">${d.opts.map((o,i)=>{let bg='';if(picked!==null){bg=i===d.correct?'background:var(--correct,#2a5)':i===picked&&picked!==d.correct?'background:var(--wrong,#a22)':'';}return `<button class="btn btn-outline" style="text-align:left;${bg}" onclick="slcPickOpt(${i})" ${picked!==null?'disabled':''}>${o}</button>`;}).join('')}</div>${picked!==null?`<div style="margin-top:14px;padding:12px;background:var(--surface2,#1a2030);border-radius:8px;font-size:0.9rem">${d.note}</div><button class="btn" style="margin-top:12px" onclick="_slcDrillNext()">Next →</button>`:''}`;
  } else if (_slcTab === 'tips') {
    const tips = (typeof SLC_TIPS !== 'undefined') ? SLC_TIPS : [];
    if (stats) stats.textContent = tips.length + ' tips';
    el.innerHTML = tips.map(t=>`<div class="card" style="padding:16px;margin-bottom:12px"><div style="font-weight:700;margin-bottom:8px">${t.title}</div><div style="line-height:1.6">${t.body}</div></div>`).join('');
  } else if (_slcTab === 'about') {
    const about = (typeof SLC_ABOUT !== 'undefined') ? SLC_ABOUT : '';
    if (stats) stats.textContent = '';
    el.innerHTML = `<div class="card" style="padding:20px;line-height:1.7">${about}</div>`;
  }
}
function slcPickOpt(i) {
  if (_slcDrillPicked !== null) return;
  const drills = (typeof SLC_DRILLS !== 'undefined') ? SLC_DRILLS : [];
  const d = drills[_slcDrillIdx]; if (!d) return;
  _slcDrillPicked = i;
  _slcDrillScore.total++;
  if (i === d.correct) {
    _slcDrillScore.correct++;
    recordActivity && recordActivity();
    const w = (typeof SLC_WORDS !== 'undefined') ? SLC_WORDS.find(x => x.en === d.opts[d.correct] || x.tr === d.opts[d.correct] || x.ar === d.opts[d.correct]) : null;
    if (w && w.ar) setTimeout(function(){ speak && speak(w.ar); }, 700);
  }
  renderSlc();
}
function _slcDrillNext() {
  _slcDrillIdx++;
  _slcDrillPicked = null;
  renderSlc();
}
function slcRestartDrill() {
  _slcDrillIdx = 0; _slcDrillPicked = null; _slcDrillScore = {correct: 0, total: 0};
  renderSlc();
}

