// R450 — NEW FEATURE: Lebanese Expressions & Sayings (exp)
// ============================================================
let _expTab = 'browse';
let _expDrillIdx = 0;
let _expDrillPicked = null;
let _expDrillScore = 0;
let _expDrillAnswered = false;
let _expBrowseCat = 'all';

function openExp(){
  bumpAchievementCounter && bumpAchievementCounter('exp_open');
  const ov = document.getElementById('exp-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setExpTab('browse');
}
function closeExp(){ const ov=document.getElementById('exp-overlay'); if(ov) ov.style.display='none'; }

function setExpTab(t){
  _expTab = t;
  const bar = document.getElementById('exp-tab-bar');
  if(bar){
    const tabs = [['browse','📖 Browse'],['drill','🎯 Drill'],['tips','💡 Tips'],['about','ℹ️ About']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_expTab===k?'active':''}" onclick="setExpTab('${k}')">${l}</button>`).join('');
  }
  renderExp();
}

function renderExp(){
  const el = document.getElementById('exp-content');
  if(!el) return;
  const st = document.getElementById('exp-stats');
  if(_expTab === 'browse') _renderExpBrowse(el, st);
  else if(_expTab === 'drill') _renderExpDrill(el, st);
  else if(_expTab === 'tips') _renderExpTips(el, st);
  else if(_expTab === 'about') _renderExpAbout(el, st);
}

function _renderExpBrowse(el, st){
  if(typeof EXP_WORDS === 'undefined'){ el.innerHTML='<p>Data not loaded.</p>'; return; }
  const cats = ['all',...[...new Set(EXP_WORDS.map(w=>w.cat))]];
  const filtered = _expBrowseCat==='all' ? EXP_WORDS : EXP_WORDS.filter(w=>w.cat===_expBrowseCat);
  if(st) st.textContent = filtered.length + ' expressions';
  let html = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">';
  html += cats.map(c => `<button class="cat-filter ${_expBrowseCat===c?'active':''}" onclick="_expBrowseCat='${c}';renderExp()">${c==='all'?'🗂️ All':c}</button>`).join('');
  html += '</div><div style="display:grid;gap:10px">';
  for(const w of filtered){
    html += `<div style="background:var(--surface);border-radius:10px;padding:14px 16px">
      <div style="font-size:1.35rem;margin-bottom:4px">${w.ar}</div>
      <div style="font-size:1.05rem;color:var(--accent);margin-bottom:2px"><em>${w.tr}</em></div>
      <div style="color:var(--muted);font-size:0.9rem">${w.en}</div>
    </div>`;
  }
  html += '</div>';
  el.innerHTML = html;
}

function _renderExpDrill(el, st){
  if(typeof EXP_DRILLS === 'undefined'){ el.innerHTML='<p>Data not loaded.</p>'; return; }
  const drills = EXP_DRILLS;
  if(st) st.textContent = (_expDrillIdx+1) + '/' + drills.length + ' · ' + _expDrillScore + ' correct';
  if(_expDrillIdx >= drills.length){
    el.innerHTML = `<div style="text-align:center;padding:40px;max-width:560px;margin:0 auto">
      <div style="font-size:2.5rem">🎉</div>
      <div style="font-size:1.3rem;font-weight:700;margin:12px 0">Drill complete!</div>
      <div style="color:var(--muted);margin-bottom:18px">Score: ${_expDrillScore}/${drills.length}</div>
      <button class="btn" onclick="expRestartDrill()">🔄 Restart</button>
    </div>`;
    return;
  }
  const d = drills[_expDrillIdx];
  let html = `<div style="max-width:600px;margin:0 auto">
    <div style="background:var(--surface);border-radius:12px;padding:18px;margin-bottom:14px">
      <div style="font-size:1.05rem;line-height:1.5">${d.q}</div>
    </div>
    <div style="display:grid;gap:8px">`;
  for(let i=0;i<d.opts.length;i++){
    let style = 'background:var(--surface);border:2px solid var(--border)';
    if(_expDrillAnswered){
      if(i===d.correct) style='background:#1a3a1a;border:2px solid #4caf50';
      else if(i===_expDrillPicked && i!==d.correct) style='background:#3a1a1a;border:2px solid #f44336';
      else style='background:var(--surface);border:2px solid var(--border);opacity:0.5';
    }
    const clickable = _expDrillAnswered ? '' : `onclick="expPickOpt(${i})"`;
    html += `<button ${clickable} style="${style};border-radius:9px;padding:12px 14px;text-align:left;cursor:${_expDrillAnswered?'default':'pointer'};width:100%;font-size:0.95rem">${d.opts[i]}</button>`;
  }
  html += '</div>';
  if(_expDrillAnswered){
    const correct = _expDrillPicked === d.correct;
    html += `<div style="margin-top:14px;background:var(--surface);border-radius:10px;padding:14px;border-left:4px solid ${correct?'#4caf50':'#f44336'}">
      <div style="font-weight:700;margin-bottom:6px">${correct?'✅ Correct!':'❌ Not quite'}</div>
      <div style="font-size:0.9rem;line-height:1.55;color:var(--muted)">${d.note}</div>
    </div>
    <div style="text-align:center;margin-top:14px">
      <button class="btn" onclick="_expDrillNext()">Next →</button>
    </div>`;
  }
  html += '</div>';
  el.innerHTML = html;
}

function expPickOpt(i){
  if(_expDrillAnswered) return;
  _expDrillPicked = i;
  _expDrillAnswered = true;
  if(i === EXP_DRILLS[_expDrillIdx].correct) _expDrillScore++;
  renderExp();
}

function _expDrillNext(){
  _expDrillIdx++;
  _expDrillPicked = null;
  _expDrillAnswered = false;
  renderExp();
}

function expRestartDrill(){
  _expDrillIdx = 0;
  _expDrillPicked = null;
  _expDrillAnswered = false;
  _expDrillScore = 0;
  renderExp();
}

function _renderExpTips(el, st){
  if(typeof EXP_TIPS === 'undefined'){ el.innerHTML='<p>Data not loaded.</p>'; return; }
  if(st) st.textContent = EXP_TIPS.length + ' tips';
  el.innerHTML = EXP_TIPS.map(t =>
    `<div style="background:var(--surface);border-radius:12px;padding:16px 18px;margin-bottom:12px">
      <div style="font-weight:700;margin-bottom:8px">${t.title}</div>
      <div style="font-size:0.9rem;line-height:1.6;color:var(--muted)">${t.body}</div>
    </div>`
  ).join('');
}

function _renderExpAbout(el, st){
  if(typeof EXP_ABOUT === 'undefined'){ el.innerHTML='<p>Data not loaded.</p>'; return; }
  if(st) st.textContent = '';
  el.innerHTML = `<div style="background:var(--surface);border-radius:12px;padding:18px;font-size:0.95rem;line-height:1.65;color:var(--muted)">${EXP_ABOUT}</div>`;
}

