// R454 — AUDIO: Index MUS_WORDS (R453) in speak() chain
// ============================================================
(function(){
  var _origSpeak = speak;
  var _r454ext = null;

  function _buildR454(){
    if (_r454ext) return;
    _r454ext = {};
    if (typeof MUS_WORDS !== 'undefined') {
      for (var i = 0; i < MUS_WORDS.length; i++) {
        var w = MUS_WORDS[i];
        if (w.tr && w.ar && !_r454ext[w.tr]) _r454ext[w.tr] = w.ar;
        if (w.en && w.en.length < 60 && w.ar && !_r454ext[w.en]) _r454ext[w.en] = w.ar;
      }
    }
  }

  var _r454wrapped = function(text, lang) {
    _buildR454();
    var arabic = _r454ext && _r454ext[text];
    if (arabic) { _origSpeak(arabic, 'ar'); return; }
    _origSpeak.apply(this, arguments);
  };
  for (var _k in _origSpeak) { try { _r454wrapped[_k] = _origSpeak[_k]; } catch(e) {} }
  _r454wrapped.__r454Audio = true;
  speak = _r454wrapped;
})();

