// R455 — BUG FIX: Add addXp to med/slc/geo/exp/mus coaches
// (R452 added incDailyCount but forgot addXp; mus/exp also missing)
// ============================================================
(function(){
  function _wrapAddXp(pickOptFn, getScore, isObjScore) {
    var _orig = pickOptFn;
    var wrapped = function(i) {
      var before = isObjScore ? (_orig && getScore() ? getScore().correct : 0) : (getScore() || 0);
      _orig.apply(this, arguments);
      var after = isObjScore ? (getScore() ? getScore().correct : 0) : (getScore() || 0);
      if (after > before) {
        addXp && addXp(10);
      }
    };
    for (var _k in _orig) { try { wrapped[_k] = _orig[_k]; } catch(e) {} }
    wrapped.__r455XpFix = true;
    return wrapped;
  }

  if (typeof medPickOpt === 'function' && !medPickOpt.__r455XpFix)
    medPickOpt = _wrapAddXp(medPickOpt, function(){ return _medDrillScore; }, true);

  if (typeof slcPickOpt === 'function' && !slcPickOpt.__r455XpFix)
    slcPickOpt = _wrapAddXp(slcPickOpt, function(){ return _slcDrillScore; }, true);

  if (typeof geoPickOpt === 'function' && !geoPickOpt.__r455XpFix)
    geoPickOpt = _wrapAddXp(geoPickOpt, function(){ return _geoDrillScore; }, true);

  if (typeof expPickOpt === 'function' && !expPickOpt.__r455XpFix)
    expPickOpt = _wrapAddXp(expPickOpt, function(){ return _expDrillScore; }, false);

  if (typeof musPickOpt === 'function' && !musPickOpt.__r455XpFix)
    musPickOpt = _wrapAddXp(musPickOpt, function(){ return _musDrillScore; }, false);
})();

