// R458 — BUG FIX: Add 🔊 speak buttons to exp/mus/tim browse tabs
// ============================================================
(function(){
  function _safeAr(s){ return (s||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'"); }

  function _makeBrowseWithSpeak(words, getCat, setCatFn, renderFn, statEl) {
    var filtered = getCat() === 'all' ? words : words.filter(function(w){ return w.cat === getCat(); });
    var cats = ['all'];
    var seen = {};
    for (var i = 0; i < words.length; i++) { if (!seen[words[i].cat]) { seen[words[i].cat] = 1; cats.push(words[i].cat); } }
    var html = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">';
    html += cats.map(function(c){ return '<button class="cat-filter ' + (getCat()===c?'active':'') + '" onclick="' + setCatFn + '(\'' + c + '\');' + renderFn + '()">' + (c==='all'?'🗂️ All':c) + '</button>'; }).join('');
    html += '</div><div style="display:grid;gap:10px">';
    for (var j = 0; j < filtered.length; j++) {
      var w = filtered[j];
      html += '<div style="background:var(--surface);border-radius:10px;padding:14px 16px;display:flex;justify-content:space-between;align-items:flex-start;gap:8px">' +
        '<div style="flex:1">' +
        '<div style="font-size:1.35rem;margin-bottom:4px">' + w.ar + '</div>' +
        '<div style="font-size:1.05rem;color:var(--accent);margin-bottom:2px"><em>' + w.tr + '</em></div>' +
        '<div style="color:var(--muted);font-size:0.9rem">' + w.en + '</div>' +
        '</div>' +
        '<button class="btn btn-outline" style="padding:4px 8px;font-size:0.85rem;flex-shrink:0" onclick="speak(\'' + _safeAr(w.ar) + '\')">🔊</button>' +
        '</div>';
    }
    html += '</div>';
    return html;
  }

  // Override _renderExpBrowse
  _renderExpBrowse = function(el, st) {
    if (typeof EXP_WORDS === 'undefined') { el.innerHTML = '<p>Data not loaded.</p>'; return; }
    if (st) st.textContent = ((_expBrowseCat === 'all' ? EXP_WORDS : EXP_WORDS.filter(function(w){ return w.cat === _expBrowseCat; })).length) + ' expressions';
    el.innerHTML = _makeBrowseWithSpeak(EXP_WORDS, function(){ return _expBrowseCat; },
      '_expBrowseCat=', 'renderExp', st);
  };

  // Override _renderMusBrowse
  _renderMusBrowse = function(el, st) {
    if (typeof MUS_WORDS === 'undefined') { el.innerHTML = '<p>Data not loaded.</p>'; return; }
    if (st) st.textContent = ((_musBrowseCat === 'all' ? MUS_WORDS : MUS_WORDS.filter(function(w){ return w.cat === _musBrowseCat; })).length) + ' entries';
    el.innerHTML = _makeBrowseWithSpeak(MUS_WORDS, function(){ return _musBrowseCat; },
      '_musBrowseCat=', 'renderMus', st);
  };

  // Override _renderTimBrowse
  _renderTimBrowse = function(el, st) {
    if (typeof TIM_WORDS === 'undefined') { el.innerHTML = '<p>Data not loaded.</p>'; return; }
    if (st) st.textContent = ((_timBrowseCat === 'all' ? TIM_WORDS : TIM_WORDS.filter(function(w){ return w.cat === _timBrowseCat; })).length) + ' expressions';
    el.innerHTML = _makeBrowseWithSpeak(TIM_WORDS, function(){ return _timBrowseCat; },
      '_timBrowseCat=', 'renderTim', st);
  };
})();

