// ── R494 · BUG FIX — Reset drill state on re-open for nat/spr/cui/emg/par/fbl ──
// R431/R434 added drill-state-reset wrappers to many coaches but nat/spr/cui/emg/
// par/fbl were added after those runs and never got the treatment. Reopening any
// of these mid-drill shows "already answered" question or wrong question number.
(function(){
  function _wrapOpenReset494(fn, resetFn) {
    if(!fn || fn.__r494Reset) return fn;
    var _orig = fn;
    var wrapped = function(){
      try{ resetFn(); }catch(e){}
      _orig.apply(this, arguments);
    };
    for(var _k in _orig){ try{ wrapped[_k]=_orig[_k]; }catch(e){} }
    wrapped.__r494Reset = true;
    return wrapped;
  }
  if(typeof openNat==='function') openNat = _wrapOpenReset494(openNat, function(){
    _natDrillIdx=0; _natDrillScore=0; _natDrillDone=false;
  });
  if(typeof openSpr==='function') openSpr = _wrapOpenReset494(openSpr, function(){
    _sprDrillIdx=0; _sprDrillScore=0; _sprDrillDone=false;
  });
  if(typeof openCui==='function') openCui = _wrapOpenReset494(openCui, function(){
    _cuiDrillIdx=0; _cuiDrillScore=0; _cuiDrillDone=false;
  });
  if(typeof openEmg==='function') openEmg = _wrapOpenReset494(openEmg, function(){
    _emgDrillIdx=0; _emgDrillScore=0; _emgDrillDone=false;
  });
  if(typeof openPar==='function') openPar = _wrapOpenReset494(openPar, function(){
    _parDrillIdx=0; _parDrillScore=0; _parDrillDone=false;
  });
  if(typeof openFbl==='function') openFbl = _wrapOpenReset494(openFbl, function(){
    _fblDrillIdx=0; _fblDrillPicked=false; _fblDrillShuf=[];
  });
})();
