// ── R496 · AUDIO — index COF_WORDS into speak() lookup ───────────────────────
// COF_WORDS added in R495 but not yet in speak() tr→ar chain.
(function(){
  if(typeof speak!=='function') return;
  if(speak.__r496Audio) return;
  const _prev496 = speak;
  const _map496 = {};
  if(typeof COF_WORDS!=='undefined'){
    COF_WORDS.forEach(function(w){
      if(w.tr && w.ar){ _map496[w.tr.toLowerCase()] = w.ar; }
      if(w.en && w.ar){ _map496[w.en.toLowerCase()] = w.ar; }
    });
  }
  speak = function(text, slow, externalBtn){
    if(!text) return _prev496(text, slow, externalBtn);
    const key = text.trim().toLowerCase();
    if(_map496[key]) return _prev496(_map496[key], slow, externalBtn);
    return _prev496(text, slow, externalBtn);
  };
  for(var _k in _prev496){ try{ speak[_k]=_prev496[_k]; }catch(e){} }
  speak.__r496Audio = true;
})();
// ── end R496 ──────────────────────────────────────────────────────────────────

// ── R497 · BUG FIX — Drill state reset on re-open for cof + reset openFbl cat ──
// openCof (R495) was added after R494's reset-wrapper pass, so it was missed.
// Re-opening mid-drill shows ghost "already answered" state or wrong question number.
(function(){
  if(typeof openCof==='function' && !openCof.__r497Reset){
    var _origCof = openCof;
    openCof = function(){
      try{ _cofDrillIdx=0; _cofDrillPicked=false; _cofDrillShuf=[]; }catch(e){}
      _origCof.apply(this, arguments);
    };
    for(var _k in _origCof){ try{ openCof[_k]=_origCof[_k]; }catch(e){} }
    openCof.__r497Reset = true;
  }
})();
// ── end R497 ──────────────────────────────────────────────────────────────────

