// ── R499 · BUG FIX — Reset drill state on re-open for ahw/wed/vlg/pol/cfc/exp/mus/tim/dia/pet/ord/grts/clth ──
// Coaches added in R486–R492 range were not covered by R494's reset-wrapper pass.
// Re-opening mid-drill showed stale question state. Same fix pattern as R494/R497.
(function(){
  function _wrapOpenReset499(fn, resetFn) {
    if(!fn || fn.__r499Reset) return fn;
    var _orig = fn;
    var wrapped = function(){
      try{ resetFn(); }catch(e){}
      _orig.apply(this, arguments);
    };
    for(var _k in _orig){ try{ wrapped[_k]=_orig[_k]; }catch(e){} }
    wrapped.__r499Reset = true;
    return wrapped;
  }
  if(typeof openAhw==='function') openAhw = _wrapOpenReset499(openAhw, function(){
    _ahwDrillIdx=0; _ahwDrillPicked=null;
  });
  if(typeof openWed==='function') openWed = _wrapOpenReset499(openWed, function(){
    _wedDrillIdx=0; _wedDrillPicked=null;
  });
  if(typeof openVlg==='function') openVlg = _wrapOpenReset499(openVlg, function(){
    _vlgDrillIdx=0; _vlgDrillPicked=null;
  });
  if(typeof openPol==='function') openPol = _wrapOpenReset499(openPol, function(){
    _polDrillIdx=0; _polDrillPicked=null;
  });
  if(typeof openCfc==='function') openCfc = _wrapOpenReset499(openCfc, function(){
    _cfcDrillIdx=0; _cfcDrillPicked=null;
  });
  if(typeof openExp==='function') openExp = _wrapOpenReset499(openExp, function(){
    _expDrillIdx=0; _expDrillPicked=null; _expDrillScore=0;
  });
  if(typeof openMus==='function') openMus = _wrapOpenReset499(openMus, function(){
    _musDrillIdx=0; _musDrillPicked=null; _musDrillScore=0;
  });
  if(typeof openTim==='function') openTim = _wrapOpenReset499(openTim, function(){
    _timDrillIdx=0; _timDrillPicked=null; _timDrillScore=0;
  });
  if(typeof openDia==='function') openDia = _wrapOpenReset499(openDia, function(){
    _diaDrillIdx=0; _diaDrillPicked=null; _diaDrillScore=0; _diaDrillAnswered=false;
  });
  if(typeof openPet==='function') openPet = _wrapOpenReset499(openPet, function(){
    _petDrillIdx=0; _petDrillPicked=null; _petDrillScore=0; _petDrillAnswered=false;
  });
  if(typeof openOrd==='function') openOrd = _wrapOpenReset499(openOrd, function(){
    _ordDrillIdx=0; _ordDrillPicked=null; _ordDrillScore=0; _ordDrillAnswered=false;
  });
  if(typeof openGrts==='function') openGrts = _wrapOpenReset499(openGrts, function(){
    _grtsDrillIdx=0; _grtsDrillPicked=null; _grtsDrillScore=0; _grtsDrillAnswered=false;
  });
  if(typeof openClth==='function') openClth = _wrapOpenReset499(openClth, function(){
    _clthDrillIdx=0; _clthDrillPicked=null; _clthDrillScore=0; _clthDrillAnswered=false;
  });
})();
// ── end R499 ──────────────────────────────────────────────────────────────────

