// ── R502 · AUDIO — Index TRF_WORDS into speak() audio lookup ──────────────────
(function(){
  if(typeof speak!=='function') return;
  if(speak.__r502Audio) return;
  const _prev502 = speak;
  const _map502 = {};
  if(typeof TRF_WORDS!=='undefined'){
    TRF_WORDS.forEach(function(w){
      if(w.tr && w.ar){ _map502[w.tr.toLowerCase()] = w.ar; }
      if(w.en && w.ar){ _map502[w.en.toLowerCase()] = w.ar; }
    });
  }
  speak = function(text, slow, externalBtn){
    if(!text) return _prev502(text, slow, externalBtn);
    const key = text.trim().toLowerCase();
    if(_map502[key]) return _prev502(_map502[key], slow, externalBtn);
    return _prev502(text, slow, externalBtn);
  };
  for(var _k in _prev502){ try{ speak[_k]=_prev502[_k]; }catch(e){} }
  speak.__r502Audio = true;
})();
// ── end R502 ──────────────────────────────────────────────────────────────────

