// ── R504 — NLF Lebanese Nightlife & Going Out Coach ───────────────────────────
let _nlfTab = 'words';
let _nlfCat = 'all';
let _nlfDrillIdx = 0;
let _nlfDrillPicked = false;
let _nlfDrillShuf = [];

function openNlf(){
  bumpAchievementCounter && bumpAchievementCounter('nlf_open');
  _nlfDrillIdx = 0; _nlfDrillPicked = false; _nlfDrillShuf = [];
  _nlfCat = 'all'; _nlfTab = 'words';
  const ov = document.getElementById('nlf-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setNlfTab('words');
}
function closeNlf(){
  const ov = document.getElementById('nlf-overlay'); if(ov) ov.style.display = 'none';
}
function setNlfTab(t){
  _nlfTab = t;
  const bar = document.getElementById('nlf-tab-bar');
  if(bar){
    const tabs = [['words','📖 Words'],['drill','🎯 Drill'],['tips','💡 Tips'],['about','ℹ️ About']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_nlfTab===k?'active':''}" onclick="setNlfTab('${k}')">${l}</button>`).join('');
  }
  renderNlf();
}
function renderNlf(){
  const stats = document.getElementById('nlf-stats');
  if(stats) stats.textContent = (typeof NLF_WORDS!=='undefined') ? NLF_WORDS.length+' words' : '';
  if(_nlfTab==='words') _renderNlfWords();
  else if(_nlfTab==='drill') _renderNlfDrill();
  else if(_nlfTab==='tips') _renderNlfTips();
  else _renderNlfAbout();
}
function _renderNlfWords(){
  const el = document.getElementById('nlf-content'); if(!el) return;
  if(typeof NLF_WORDS==='undefined'){ el.innerHTML='<p>No data.</p>'; return; }
  const cats = ['all',...[...new Set(NLF_WORDS.map(w=>w.cat))]];
  let html = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">';
  html += cats.map(c=>`<button class="cat-filter ${_nlfCat===c?'active':''}" onclick="_nlfCat='${c}';_renderNlfWords()">${c}</button>`).join('');
  html += '</div><div style="display:grid;gap:8px">';
  const words = _nlfCat==='all' ? NLF_WORDS : NLF_WORDS.filter(w=>w.cat===_nlfCat);
  words.forEach(w=>{
    html += `<div class="card" style="padding:12px 16px;cursor:pointer" onclick="speak('${w.ar.replace(/'/g,"\\'")}')">
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px">
        <span style="font-size:1.4rem;font-family:serif">${w.ar}</span>
        <span style="color:var(--muted);font-size:0.85rem">${w.tr}</span>
      </div>
      <div style="margin-top:4px;font-size:0.9rem">${w.en}</div>
    </div>`;
  });
  html += '</div>';
  el.innerHTML = html;
}
function _renderNlfDrill(){
  const el = document.getElementById('nlf-content'); if(!el) return;
  if(typeof NLF_DRILLS==='undefined'||!NLF_DRILLS.length){ el.innerHTML='<p>No drills.</p>'; return; }
  if(_nlfDrillIdx >= NLF_DRILLS.length){
    el.innerHTML = `<div style="text-align:center;padding:40px">
      <div style="font-size:2rem">🎉</div>
      <div style="font-size:1.2rem;font-weight:700;margin:12px 0">All drills done!</div>
      <button class="btn" onclick="_nlfDrillIdx=0;_nlfDrillPicked=false;_nlfDrillShuf=[];_renderNlfDrill()">Restart</button>
    </div>`;
    return;
  }
  const d = NLF_DRILLS[_nlfDrillIdx];
  if(!_nlfDrillShuf.length) _nlfDrillShuf = d.opts.map((_,i)=>i).sort(()=>Math.random()-0.5);
  let html = `<div style="margin-bottom:8px;color:var(--muted);font-size:0.85rem">Question ${_nlfDrillIdx+1} / ${NLF_DRILLS.length}</div>`;
  html += `<div class="card" style="padding:16px;margin-bottom:16px;font-weight:600">${d.q}</div>`;
  html += '<div style="display:grid;gap:8px">';
  _nlfDrillShuf.forEach(oi=>{
    let style = 'padding:12px 16px;cursor:pointer;border:2px solid transparent';
    if(_nlfDrillPicked!==false){
      if(oi===d.ans) style += ';border-color:#22c55e;background:rgba(34,197,94,0.1)';
      else if(oi===_nlfDrillPicked) style += ';border-color:#ef4444;background:rgba(239,68,68,0.1)';
    }
    html += `<div class="card" style="${style}" onclick="nlfPickOpt(${oi})">${d.opts[oi]}</div>`;
  });
  html += '</div>';
  if(_nlfDrillPicked!==false){
    html += `<div class="card" style="margin-top:16px;padding:14px;background:rgba(var(--accent-rgb),0.08);font-size:0.9rem">${d.note}</div>`;
    html += `<div style="text-align:center;margin-top:14px"><button class="btn" onclick="nlfNext()">Next →</button></div>`;
  }
  el.innerHTML = html;
}
function nlfPickOpt(i){
  if(_nlfDrillPicked!==false) return;
  _nlfDrillPicked = i;
  const d = NLF_DRILLS[_nlfDrillIdx];
  if(i===d.ans){ incDailyCount && incDailyCount(); }
  _renderNlfDrill();
}
function nlfNext(){
  _nlfDrillIdx++;
  _nlfDrillPicked = false;
  _nlfDrillShuf = [];
  _renderNlfDrill();
}
function _renderNlfTips(){
  const el = document.getElementById('nlf-content'); if(!el) return;
  if(typeof NLF_TIPS==='undefined'){ el.innerHTML='<p>No tips.</p>'; return; }
  el.innerHTML = NLF_TIPS.map(t=>`<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="font-weight:700;margin-bottom:8px">💡 ${t.title}</div>
    <div style="font-size:0.9rem;line-height:1.6">${t.body}</div>
  </div>`).join('');
}
function _renderNlfAbout(){
  const el = document.getElementById('nlf-content'); if(!el) return;
  if(typeof NLF_ABOUT==='undefined'){ el.innerHTML='<p>No about.</p>'; return; }
  el.innerHTML = `<div class="card" style="padding:20px;line-height:1.7">${NLF_ABOUT}</div>`;
}
