// ── R506 · BUG FIX — Reset category filter on re-open for wed/pol/med/slc/geo ──
// Coaches with _xxxCat state that wasn't reset on re-open showed filtered word
// list without indication. Same fix pattern as R503 (wst/cof/trf/fbl).
(function(){
  function _wrapCatReset506(fn, resetFn) {
    if(!fn || fn.__r506Reset) return fn;
    var _orig = fn;
    var wrapped = function(){
      try{ resetFn(); }catch(e){}
      _orig.apply(this, arguments);
    };
    for(var _k in _orig){ try{ wrapped[_k]=_orig[_k]; }catch(e){} }
    wrapped.__r506Reset = true;
    return wrapped;
  }
  if(typeof openWed==='function') openWed = _wrapCatReset506(openWed, function(){ _wedCat='all'; });
  if(typeof openPol==='function') openPol = _wrapCatReset506(openPol, function(){ _polCat='all'; });
  if(typeof openMed==='function') openMed = _wrapCatReset506(openMed, function(){ _medCat='all'; });
  if(typeof openSlc==='function') openSlc = _wrapCatReset506(openSlc, function(){ _slcCat='all'; });
  if(typeof openGeo==='function') openGeo = _wrapCatReset506(openGeo, function(){ _geoCat='all'; });
})();
// ── end R506 ──────────────────────────────────────────────────────────────────

