  const d = MNO_DRILLS[_mnoDrillIdx];
  if(!_mnoDrillShuf.length) _mnoDrillShuf = d.opts.map((_,i)=>i).sort(()=>Math.random()-0.5);
  let html = `<div style="margin-bottom:8px;color:var(--muted);font-size:0.85rem">Question ${_mnoDrillIdx+1} / ${MNO_DRILLS.length}</div>`;
  html += `<div class="card" style="padding:16px;margin-bottom:16px;font-weight:600">${d.q}</div>`;
  html += '<div style="display:grid;gap:8px">';
