// ── R511 · AUDIO — Index MNO_WORDS into speak() audio lookup ──────────────────
(function(){
  if(typeof speak!=='function') return;
  if(speak.__r511Audio) return;
  const _prev511 = speak;
  const _map511 = {};
  if(typeof MNO_WORDS!=='undefined'){
    MNO_WORDS.forEach(function(w){
      if(w.tr && w.ar){ _map511[w.tr.toLowerCase()] = w.ar; }
      if(w.en && w.ar){ _map511[w.en.toLowerCase()] = w.ar; }
    });
  }
  speak = function(text, slow, externalBtn){
    if(!text) return _prev511(text, slow, externalBtn);
    const key = text.trim().toLowerCase();
    if(_map511[key]) return _prev511(_map511[key], slow, externalBtn);
    return _prev511(text, slow, externalBtn);
  };
  for(var _k in _prev511){ try{ speak[_k]=_prev511[_k]; }catch(e){} }
  speak.__r511Audio = true;
})();
// ── end R511 ──────────────────────────────────────────────────────────────────

// ── R512 · BUG FIX — Reset _expDrillAnswered + wrap openRel (missed by R499) ──
// R499 missed _expDrillAnswered=false in openExp reset, and openRel was entirely
// absent from R499. Both show stale "answered" state on re-open mid-drill.
(function(){
  if(typeof openExp==='function' && !openExp.__r512Reset){
    var _origExp512 = openExp;
    openExp = function(){
      try{ _expDrillAnswered=false; }catch(e){}
      _origExp512.apply(this, arguments);
    };
    for(var _k in _origExp512){ try{ openExp[_k]=_origExp512[_k]; }catch(e){} }
    openExp.__r512Reset = true;
  }
  if(typeof openRel==='function' && !openRel.__r512Reset){
    var _origRel512 = openRel;
    openRel = function(){
      try{ _relDrillIdx=0; _relDrillPicked=null; _relDrillScore=0; _relDrillAnswered=false; }catch(e){}
      _origRel512.apply(this, arguments);
    };
    for(var _k in _origRel512){ try{ openRel[_k]=_origRel512[_k]; }catch(e){} }
    openRel.__r512Reset = true;
  }
})();
// ── end R512 ──────────────────────────────────────────────────────────────────

