  if(st) st.textContent = words.length + ' phrases';
  let h = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">`;
  h += cats.map(c=>`<button class="cat-filter ${_celCat===c?'active':''}" onclick="_celCat='${c}';renderCel()">${c==='all'?'🎉 All':c}</button>`).join('');
