// R573 — NEW FEATURE: Lebanese Pharmacy & Medicine culture coach (prefix: phr)
let _phrTab = 'words';
let _phrCat = 'all';
let _phrDrillIdx = 0;
let _phrDrillPicked = false;
let _phrDrillShuf = [];

function openPhr(){
  try{ bumpAchievementCounter && bumpAchievementCounter('phr_open'); }catch(e){}
  const ov = document.getElementById('phr-overlay');
  if(!ov) return;
  ov.style.display = 'block';
  setPhrTab('words');
}
function closePhr(){
  const ov = document.getElementById('phr-overlay');
  if(ov) ov.style.display = 'none';
}
function setPhrTab(t){
  _phrTab = t;
  const bar = document.getElementById('phr-tab-bar');
  if(bar){
    const tabs = [['words','💊 Words'],['drill','🎯 Drill'],['tips','💡 Tips'],['about','📖 About']];
    bar.innerHTML = tabs.map(function(tb){ return '<button class="cat-filter ' + (_phrTab===tb[0]?'active':'') + '" onclick="setPhrTab(\'' + tb[0] + '\')">' + tb[1] + '</button>'; }).join('');
  }
  renderPhr();
}
function renderPhr(){
  const c = document.getElementById('phr-content');
  if(!c) return;
  const st = document.getElementById('phr-stats');
  if(_phrTab==='words') _renderPhrWords(c, st);
  else if(_phrTab==='drill') _renderPhrDrill(c, st);
  else if(_phrTab==='tips') _renderPhrTips(c);
  else if(_phrTab==='about') _renderPhrAbout(c);
}
function _renderPhrWords(c, st){
  if(typeof PHR_WORDS === 'undefined'){ c.innerHTML = '<p style="color:var(--muted);padding:20px">Data not loaded.</p>'; return; }
  const cats = ['all','basics','symptoms','interact','cultural'];
  const catLabels = {all:'💊 All', basics:'🏥 Basics', symptoms:'🤒 Symptoms', interact:'💬 Interact', cultural:'🌿 Cultural'};
  const words = _phrCat === 'all' ? PHR_WORDS : PHR_WORDS.filter(function(w){ return w.cat === _phrCat; });
  if(st) st.textContent = words.length + ' terms';
  let h = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">';
  cats.forEach(function(cat){
    h += '<button class="cat-filter ' + (_phrCat===cat?'active':'') + '" onclick="_phrSetCat(\'' + cat + '\')">' + catLabels[cat] + '</button>';
  });
  h += '</div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">';
  words.forEach(function(w){
    h += '<div style="background:var(--card);border-radius:10px;padding:12px;border:1px solid var(--border)">' +
      '<div style="font-size:1.4rem;font-weight:700;direction:rtl">' + w.ar + '</div>' +
      '<div style="color:var(--accent);font-size:0.9rem;margin:2px 0">' + w.tr + '</div>' +
      '<div style="color:var(--muted);font-size:0.85rem">' + w.en + '</div>' +
      '<div style="margin-top:6px"><button class="btn btn-sm btn-outline" onclick="speak(\'' + w.ar.replace(/'/g,"\\'") + '\')">🔊</button></div>' +
      '</div>';
  });
  h += '</div>';
  c.innerHTML = h;
}
function _phrSetCat(cat){ _phrCat = cat; renderPhr(); }
function _renderPhrDrill(c, st){
  var drills = typeof PHR_DRILLS !== 'undefined' ? PHR_DRILLS : [];
  if(!drills.length){ c.innerHTML = '<p>No drills available.</p>'; return; }
  if(!_phrDrillShuf.length){
    _phrDrillShuf = drills.map(function(_,i){ return i; }).sort(function(){ return Math.random()-0.5; });
    _phrDrillIdx = 0; _phrDrillPicked = false;
  }
  if(_phrDrillIdx >= _phrDrillShuf.length){
    if(st) st.textContent = 'done!';
    c.innerHTML = '<div style="background:var(--card);border-radius:12px;padding:20px;text-align:center;max-width:600px;margin:0 auto">' +
      '<div style="font-size:2rem;margin-bottom:10px">🎉</div>' +
      '<div style="font-weight:700;margin-bottom:10px">All ' + _phrDrillShuf.length + ' drills done!</div>' +
      '<button class="btn" onclick="_phrDrillShuf=[];_phrDrillIdx=0;_phrDrillPicked=false;renderPhr()">🔄 Restart</button></div>';
    return;
  }
  var d = drills[_phrDrillShuf[_phrDrillIdx]];
  if(st) st.textContent = (_phrDrillIdx+1) + '/' + _phrDrillShuf.length;
  var html = '<div style="background:var(--card);border-radius:12px;padding:20px;max-width:600px;margin:0 auto">' +
    '<div style="font-weight:600;margin-bottom:18px;font-size:1rem">' + d.q + '</div>' +
    '<div style="display:grid;gap:8px">';
  d.opts.forEach(function(opt, i){
    var bg='var(--card)', clr='var(--text)', br='1px solid var(--border)';
    if(_phrDrillPicked !== false){
      if(i===d.ans){ bg='var(--success,#22c55e)'; clr='#fff'; br='none'; }
      else if(i===_phrDrillPicked && i!==d.ans){ bg='var(--danger,#ef4444)'; clr='#fff'; br='none'; }
    }
    html += '<button onclick="phrPickOpt(' + i + ')" style="text-align:left;padding:12px 14px;border-radius:8px;border:' + br + ';background:' + bg + ';color:' + clr + ';cursor:' + (_phrDrillPicked!==false?'default':'pointer') + ';font-size:0.95rem">' + opt + '</button>';
  });
  html += '</div>';
  if(_phrDrillPicked !== false){
    html += '<div style="margin-top:14px;padding:12px;background:var(--bg);border-radius:8px;font-size:0.9rem;color:var(--muted)">' + d.exp + '</div>' +
      '<button onclick="phrNext()" style="margin-top:12px;width:100%;padding:11px;background:var(--accent);color:#fff;border:none;border-radius:8px;cursor:pointer;font-weight:600">Next →</button>';
  }
  html += '</div>';
  c.innerHTML = html;
}
function phrPickOpt(i){
  if(_phrDrillPicked !== false) return;
  var drills = typeof PHR_DRILLS !== 'undefined' ? PHR_DRILLS : [];
  var d = drills[_phrDrillShuf[_phrDrillIdx]];
  _phrDrillPicked = i;
  if(d && i === d.ans){
    try{ incDailyCount && incDailyCount(); recordActivity && recordActivity(); addXp && addXp(10); }catch(e){}
  }
  renderPhr();
}
function phrNext(){ _phrDrillIdx++; _phrDrillPicked = false; renderPhr(); }
function _renderPhrTips(c){
  var tips = typeof PHR_TIPS !== 'undefined' ? PHR_TIPS : [];
  c.innerHTML = '<div style="display:grid;gap:12px">' + tips.map(function(t, i){
    return '<div class="card" style="padding:16px"><div style="font-size:0.75rem;color:var(--muted);margin-bottom:6px;text-transform:uppercase;letter-spacing:0.05em">Tip ' + (i+1) + '</div><div style="font-size:0.92rem;line-height:1.65">' + t + '</div></div>';
  }).join('') + '</div>';
}
function _renderPhrAbout(c){
  var about = typeof PHR_ABOUT !== 'undefined' ? PHR_ABOUT : '';
  c.innerHTML = '<div style="background:var(--card);border-radius:10px;padding:20px;line-height:1.7;color:var(--muted);font-size:0.93rem">' + about + '</div>';
}

