// R576 — NEW FEATURE: Lebanese Nightlife & Going Out coach (prefix: nyt)
let _nytTab = 'words';
let _nytCat = 'all';
let _nytDrillIdx = 0;
let _nytDrillPicked = false;
let _nytDrillShuf = [];

function openNyt(){
  try{ bumpAchievementCounter && bumpAchievementCounter('nyt_open'); }catch(e){}
  const ov = document.getElementById('nyt-overlay');
  if(!ov) return;
  ov.style.display = 'block';
  setNytTab('words');
}
function closeNyt(){
  const ov = document.getElementById('nyt-overlay');
  if(ov) ov.style.display = 'none';
}
function setNytTab(t){
  _nytTab = t;
  const bar = document.getElementById('nyt-tab-bar');
  if(bar){
    const tabs = [['words','🌙 Words'],['drill','🎯 Drill'],['tips','💡 Tips'],['about','📖 About']];
    bar.innerHTML = tabs.map(function(tb){ return '<button class="cat-filter ' + (_nytTab===tb[0]?'active':'') + '" onclick="setNytTab(\'' + tb[0] + '\')">' + tb[1] + '</button>'; }).join('');
  }
  renderNyt();
}
function renderNyt(){
  const c = document.getElementById('nyt-content');
  if(!c) return;
  const st = document.getElementById('nyt-stats');
  if(_nytTab==='words') _renderNytWords(c, st);
  else if(_nytTab==='drill') _renderNytDrill(c, st);
  else if(_nytTab==='tips') _renderNytTips(c);
  else if(_nytTab==='about') _renderNytAbout(c);
}
function _renderNytWords(c, st){
  if(typeof NYT_WORDS === 'undefined'){ c.innerHTML = '<p style="color:var(--muted);padding:20px">Data not loaded.</p>'; return; }
  const cats = ['all','places','drinks','ordering','expr','culture'];
  const catLabels = {all:'🌙 All', places:'📍 Places', drinks:'🥃 Drinks', ordering:'🧾 Ordering', expr:'💬 Expressions', culture:'🎭 Culture'};
  const words = _nytCat === 'all' ? NYT_WORDS : NYT_WORDS.filter(function(w){ return w.cat === _nytCat; });
  if(st) st.textContent = words.length + ' terms';
  let h = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">';
  cats.forEach(function(cat){
    h += '<button class="cat-filter ' + (_nytCat===cat?'active':'') + '" onclick="_nytSetCat(\'' + cat + '\')">' + catLabels[cat] + '</button>';
  });
  h += '</div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">';
  words.forEach(function(w){
    h += '<div style="background:var(--card);border-radius:10px;padding:12px;border:1px solid var(--border)">' +
      '<div style="font-size:1.4rem;font-weight:700;direction:rtl">' + w.ar + '</div>' +
      '<div style="color:var(--accent);font-size:0.9rem;margin:2px 0">' + w.tr + '</div>' +
      '<div style="color:var(--muted);font-size:0.85rem">' + w.en + '</div>' +
      '<div style="margin-top:6px"><button class="btn btn-sm btn-outline" onclick="speak(\'' + w.ar.replace(/'/g,"\\'") + '\')">🔊</button></div>' +
      '</div>';
  });
  h += '</div>';
  c.innerHTML = h;
}
function _nytSetCat(cat){ _nytCat = cat; renderNyt(); }
function _renderNytDrill(c, st){
  var drills = typeof NYT_DRILLS !== 'undefined' ? NYT_DRILLS : [];
  if(!drills.length){ c.innerHTML = '<p>No drills available.</p>'; return; }
  if(!_nytDrillShuf.length){
    _nytDrillShuf = drills.map(function(_,i){ return i; }).sort(function(){ return Math.random()-0.5; });
    _nytDrillIdx = 0; _nytDrillPicked = false;
  }
  if(_nytDrillIdx >= _nytDrillShuf.length){
    if(st) st.textContent = 'done!';
    c.innerHTML = '<div style="background:var(--card);border-radius:12px;padding:20px;text-align:center;max-width:600px;margin:0 auto"><div style="font-size:2rem;margin-bottom:10px">🎉</div><div style="font-weight:700;margin-bottom:10px">All ' + _nytDrillShuf.length + ' drills done!</div><button class="btn" onclick="_nytDrillShuf=[];_nytDrillIdx=0;_nytDrillPicked=false;renderNyt()">🔄 Restart</button></div>';
    return;
  }
  var d = drills[_nytDrillShuf[_nytDrillIdx]];
  if(st) st.textContent = (_nytDrillIdx+1) + '/' + _nytDrillShuf.length;
  var html = '<div style="background:var(--card);border-radius:12px;padding:20px;max-width:600px;margin:0 auto"><div style="font-weight:600;margin-bottom:18px;font-size:1rem">' + d.q + '</div><div style="display:grid;gap:8px">';
  d.opts.forEach(function(opt, i){
    var bg='var(--card)', clr='var(--text)', br='1px solid var(--border)';
    if(_nytDrillPicked !== false){
      if(i===d.ans){ bg='var(--success,#22c55e)'; clr='#fff'; br='none'; }
      else if(i===_nytDrillPicked && i!==d.ans){ bg='var(--danger,#ef4444)'; clr='#fff'; br='none'; }
    }
    html += '<button onclick="nytPickOpt(' + i + ')" style="text-align:left;padding:12px 14px;border-radius:8px;border:' + br + ';background:' + bg + ';color:' + clr + ';cursor:' + (_nytDrillPicked!==false?'default':'pointer') + ';font-size:0.95rem">' + opt + '</button>';
  });
  html += '</div>';
  if(_nytDrillPicked !== false){
    html += '<div style="margin-top:14px;padding:12px;background:var(--bg);border-radius:8px;font-size:0.9rem;color:var(--muted)">' + d.exp + '</div><button onclick="nytNext()" style="margin-top:12px;width:100%;padding:11px;background:var(--accent);color:#fff;border:none;border-radius:8px;cursor:pointer;font-weight:600">Next →</button>';
  }
  html += '</div>';
  c.innerHTML = html;
}
function nytPickOpt(i){
  if(_nytDrillPicked !== false) return;
  var drills = typeof NYT_DRILLS !== 'undefined' ? NYT_DRILLS : [];
  var d = drills[_nytDrillShuf[_nytDrillIdx]];
  _nytDrillPicked = i;
  if(d && i === d.ans){
    try{ incDailyCount && incDailyCount(); recordActivity && recordActivity(); addXp && addXp(10); }catch(e){}
  }
  renderNyt();
}
function nytNext(){ _nytDrillIdx++; _nytDrillPicked = false; renderNyt(); }
function _renderNytTips(c){
  var tips = typeof NYT_TIPS !== 'undefined' ? NYT_TIPS : [];
  c.innerHTML = '<div style="display:grid;gap:12px">' + tips.map(function(t, i){
    return '<div class="card" style="padding:16px"><div style="font-size:0.75rem;color:var(--muted);margin-bottom:6px;text-transform:uppercase;letter-spacing:0.05em">Tip ' + (i+1) + '</div><div style="font-size:0.92rem;line-height:1.65">' + t + '</div></div>';
  }).join('') + '</div>';
}
function _renderNytAbout(c){
  var about = typeof NYT_ABOUT !== 'undefined' ? NYT_ABOUT : '';
  c.innerHTML = '<div style="background:var(--card);border-radius:10px;padding:20px;line-height:1.7;color:var(--muted);font-size:0.93rem">' + about + '</div>';
}

// R577 — AUDIO: Index NYT_WORDS into speak() (prefix: nyt)
(function(){
  if(typeof speak !== 'function') return;
  if(speak.__r577Audio) return;
  var _prev577 = speak;
  var _map577 = {};
  if(typeof NYT_WORDS !== 'undefined'){
    NYT_WORDS.forEach(function(w){
      if(w.tr && w.ar){ _map577[w.tr.toLowerCase()] = w.ar; }
      if(w.en && w.ar){ _map577[w.en.toLowerCase()] = w.ar; }
    });
  }
  speak = function(text, slow, externalBtn){
    var key = typeof text === 'string' ? text.toLowerCase() : '';
    var mapped = _map577[key];
    return _prev577(mapped !== undefined ? mapped : text, slow, externalBtn);
  };
  speak.__r577Audio = true;
  if(window.__audioFlagsKnown) window.__audioFlagsKnown.forEach(function(f){ if(!speak[f]) speak[f] = true; });
  if(!window.__audioFlagsKnown) window.__audioFlagsKnown = [];
  window.__audioFlagsKnown.push('__r577Audio');
})();

