      return '<button onclick="desPickOpt(' + i + ')" style="width:100%;text-align:left;padding:10px 14px;margin-bottom:6px;border-radius:8px;border:none;cursor:pointer;background:' + bg + ';' + col + 'font-size:0.95rem">' + o + '</button>';
