    el.innerHTML = '<div style="background:var(--card);border-radius:12px;padding:18px;max-width:560px;margin:0 auto"><div style="margin-bottom:12px;font-size:0.8rem;color:var(--muted)">Question ' + (idx+1) + ' of ' + drills.length + '</div><div style="font-size:1.05rem;margin-bottom:16px">' + q.q + '</div>' + opts + note + (_desDrillAnswered ? '<button class="btn" style="width:100%;margin-top:8px" onclick="_desDrillNext()">Next →</button>' : '') + '</div>';
