// R586 — AUDIO: Index MHL_WORDS into speak() (prefix: mhl)
(function(){
  if(typeof speak !== 'function') return;
  if(speak.__r586Audio) return;
  var _prev586 = speak;
  var _map586 = {};
  if(typeof MHL_WORDS !== 'undefined'){
    MHL_WORDS.forEach(function(w){
      if(w.tr && w.ar){ _map586[w.tr.toLowerCase()] = w.ar; }
      if(w.en && w.ar){ _map586[w.en.toLowerCase()] = w.ar; }
    });
  }
  speak = function(text, slow, externalBtn){
    var key = typeof text === 'string' ? text.toLowerCase() : '';
    var mapped = _map586[key];
    return _prev586(mapped !== undefined ? mapped : text, slow, externalBtn);
  };
  speak.__r586Audio = true;
  if(window.__audioFlagsKnown) window.__audioFlagsKnown.forEach(function(f){ if(!speak[f]) speak[f] = true; });
  if(!window.__audioFlagsKnown) window.__audioFlagsKnown = [];
  window.__audioFlagsKnown.push('__r586Audio');
})();

