    html += '<button onclick="mktPickOpt(' + i + ')" style="text-align:left;padding:10px 14px;border-radius:8px;border:1px solid var(--border);background:' + bg + ';' + col + 'cursor:pointer;font-size:0.95rem">' + opt + '</button>';
