// ── R603 — NEW FEATURE: Lebanese Arak, Wine & Drinking Culture (ark) ──────────

let _arkTab = 'browse';
let _arkCat = 'all';
let _arkDrillIdx = 0;
let _arkDrillAnswered = false;

function openArk(){
  bumpAchievementCounter && bumpAchievementCounter('ark_open');
  const ov = document.getElementById('ark-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setArkTab('browse');
}
function closeArk(){ const ov=document.getElementById('ark-overlay'); if(ov) ov.style.display='none'; }
function setArkTab(t){
  _arkTab = t;
  const bar = document.getElementById('ark-tab-bar');
  if(bar){
    const tabs = [['browse','🍶 Browse'],['drill','🎯 Drill'],['tips','💡 Tips'],['about','📖 About']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_arkTab===k?'active':''}" onclick="setArkTab('${k}')">${l}</button>`).join('');
  }
  renderArk();
}
function renderArk(){
  const el = document.getElementById('ark-content'); if(!el) return;
  if(_arkTab==='browse') el.innerHTML = _arkRenderBrowse();
  else if(_arkTab==='drill') _arkRenderDrill(el);
  else if(_arkTab==='tips') el.innerHTML = _arkRenderTips();
  else el.innerHTML = _arkRenderAbout();
}
