// ── R606 — NEW FEATURE: Lebanese Jobs & Work Culture (jbs) ────────────────────

let _jbsTab = 'browse';
let _jbsCat = 'all';
let _jbsDrillIdx = 0;
let _jbsDrillAnswered = false;

function openJbs(){
  bumpAchievementCounter && bumpAchievementCounter('jbs_open');
  const ov = document.getElementById('jbs-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setJbsTab('browse');
}
function closeJbs(){ const ov=document.getElementById('jbs-overlay'); if(ov) ov.style.display='none'; }
function setJbsTab(t){
  _jbsTab = t;
  const bar = document.getElementById('jbs-tab-bar');
  if(bar){
    const tabs = [['browse','💼 Browse'],['drill','🎯 Drill'],['tips','💡 Tips'],['about','📖 About']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_jbsTab===k?'active':''}" onclick="setJbsTab('${k}')">${l}</button>`).join('');
  }
  renderJbs();
}
function renderJbs(){
  const el = document.getElementById('jbs-content'); if(!el) return;
  if(_jbsTab==='browse') el.innerHTML = _jbsRenderBrowse();
  else if(_jbsTab==='drill') _jbsRenderDrill(el);
  else if(_jbsTab==='tips') el.innerHTML = _jbsRenderTips();
  else el.innerHTML = _jbsRenderAbout();
}
function _jbsRenderBrowse(){
  if(typeof JBS_WORDS==='undefined') return '<p>No data.</p>';
  const cats = ['all','roles','seeking','workplace','culture'];
  const labels = {all:'💼 All',roles:'👤 Roles',seeking:'🔍 Job Hunt',workplace:'🏢 Workplace',culture:'🇱🇧 Culture'};
  const bar = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">'+cats.map(c=>'<button class="cat-filter '+(_jbsCat===c?'active':'')+'" onclick="_jbsSetCat(\''+c+'\')">'+labels[c]+'</button>').join('')+'</div>';
  const words = _jbsCat==='all' ? JBS_WORDS : JBS_WORDS.filter(w=>w.cat===_jbsCat);
  const cards = words.map(w=>'<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 14px;background:var(--surface2);border-radius:8px;margin-bottom:6px">'
    +'<div><span style="font-weight:600">'+w.tr+'</span> <span style="color:var(--muted);font-size:0.85rem">'+w.en+'</span></div>'
    +'<div style="display:flex;align-items:center;gap:8px"><span style="font-size:1.1rem;direction:rtl">'+w.ar+'</span>'
    +'<button class="btn btn-outline" style="padding:2px 8px;font-size:0.8rem" onclick="speak(\''+w.ar.replace(/'/g,"\\'")+'\')">🔊</button></div>'
    +'</div>').join('');
  const stats = document.getElementById('jbs-stats');
  if(stats) stats.textContent = words.length+' words';
  return bar+cards;
}
function _jbsSetCat(c){ _jbsCat=c; renderJbs(); }

window._jbsDrillReset = function(){ _jbsDrillIdx=0; _jbsDrillAnswered=false; renderJbs(); };

function _jbsRenderDrill(el){
  const drills = typeof JBS_DRILLS!=='undefined' ? JBS_DRILLS : [];
  if(!drills.length){ el.innerHTML='<p>No drills.</p>'; return; }
  if(_jbsDrillIdx >= drills.length){
    const st = document.getElementById('jbs-stats');
    if(st) st.textContent='done!';
    el.innerHTML='<div style="text-align:center;padding:40px 20px"><div style="font-size:2rem;margin-bottom:12px">🎉</div>'
      +'<div style="font-size:1.1rem;font-weight:600;margin-bottom:16px">All '+drills.length+' drills done!</div>'
      +'<button class="btn btn-primary" onclick="_jbsDrillReset()">🔄 Restart</button></div>';
    return;
  }
  const d = drills[_jbsDrillIdx];
  const st = document.getElementById('jbs-stats');
  if(st) st.textContent='Q '+(_jbsDrillIdx+1)+' / '+drills.length;
  const optsHtml = d.opts.map((o,i)=>'<button class="btn btn-outline" style="display:block;width:100%;text-align:left;margin-bottom:8px" onclick="jbsPickOpt('+i+')">'+o+'</button>').join('');
  el.innerHTML='<div style="background:var(--surface2);border-radius:12px;padding:20px;margin-bottom:16px">'
    +'<div style="font-size:0.8rem;color:var(--muted);margin-bottom:8px">Question '+(_jbsDrillIdx+1)+' / '+drills.length+'</div>'
    +'<div style="font-size:1.1rem;font-weight:600;margin-bottom:16px">'+d.q+'</div>'
    +'<div id="jbs-opts">'+optsHtml+'</div></div>'
    +'<div id="jbs-feedback" style="margin-top:12px"></div>';
}
function jbsPickOpt(i){
  if(_jbsDrillAnswered) return;
  _jbsDrillAnswered = true;
  const drills = typeof JBS_DRILLS!=='undefined' ? JBS_DRILLS : [];
  const d = drills[_jbsDrillIdx];
  const correct = (i===d.ans);
  if(correct){
    if(typeof recordActivity==='function') try{ recordActivity(); }catch(e){}
    if(typeof incDailyCount==='function') try{ incDailyCount(); }catch(e){}
    if(typeof addXp==='function') try{ addXp((typeof XP_PER_RATING!=='undefined'&&XP_PER_RATING[2])||10); }catch(e){}
  }
  const fb = document.getElementById('jbs-feedback');
  if(fb){
    fb.innerHTML='<div style="padding:12px;border-radius:8px;background:'+(correct?'var(--correct-bg,#d4edda)':'var(--wrong-bg,#f8d7da)')+';color:'+(correct?'var(--correct,#155724)':'var(--wrong,#721c24)')+';margin-bottom:12px">'
      +(correct?'✓ Correct!':'✗ Incorrect — correct: '+d.opts[d.ans])
      +'<div style="margin-top:8px;font-size:0.9rem;color:var(--text)">'+d.exp+'</div></div>'
      +'<button class="btn btn-primary" onclick="jbsNext()">Next →</button>';
  }
  const opts = document.getElementById('jbs-opts');
  if(opts){ opts.querySelectorAll('button').forEach(b=>b.disabled=true); }
}
function jbsNext(){
  _jbsDrillIdx++;
  _jbsDrillAnswered=false;
  renderJbs();
}
function _jbsRenderTips(){
  if(typeof JBS_TIPS==='undefined') return '<p>No tips.</p>';
  const st = document.getElementById('jbs-stats');
  if(st) st.textContent=JBS_TIPS.length+' tips';
  return JBS_TIPS.map((t,i)=>'<div style="margin-bottom:18px;padding:14px;background:var(--surface2);border-radius:10px">'
    +'<div style="font-weight:700;margin-bottom:6px">Tip '+(i+1)+'</div>'
    +'<div style="color:var(--text);font-size:0.9rem;line-height:1.6">'+t+'</div></div>').join('');
}
function _jbsRenderAbout(){
  const txt = typeof JBS_ABOUT!=='undefined' ? JBS_ABOUT : '';
  const st = document.getElementById('jbs-stats');
  if(st) st.textContent='';
  return '<div style="padding:16px;background:var(--surface2);border-radius:10px;font-size:0.95rem;line-height:1.6">'+txt+'</div>';
}

