// ===== R609: Lebanese History & Heritage Coach (hst) =====
let _hstTab = 'browse';
let _hstFilter = 'all';
let _hstScore = { correct: 0, wrong: 0 };
let _hstLocked = false;
let _hstIdx = 0;
let _hstOrder = [];
let _hstOptions = [];

function openHst() {
  bumpAchievementCounter && bumpAchievementCounter('hst_open');
  const ov = document.getElementById('hst-overlay');
  if (!ov) return;
  ov.style.display = 'block';
  setHstTab('browse');
}
function closeHst() {
  const ov = document.getElementById('hst-overlay');
  if (ov) ov.style.display = 'none';
}
function setHstTab(t) {
  _hstTab = t;
  const bar = document.getElementById('hst-tab-bar');
  if (bar) {
    const tabs = [['browse','📖 Browse'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_hstTab===k?'active':''}" onclick="setHstTab('${k}')">${l}</button>`).join('');
  }
  renderHst();
}
function renderHst() {
  const el = document.getElementById('hst-content');
  const st = document.getElementById('hst-stats');
  if (!el) return;
  if (_hstTab === 'browse') _hstRenderBrowse(el, st);
  else if (_hstTab === 'drill') _hstRenderDrill(el, st);
  else _hstRenderTips(el, st);
}
function _hstSetCat(c) {
  _hstFilter = c;
  renderHst();
}
function _hstRenderBrowse(el, st) {
  const cats = typeof HST_CATS !== 'undefined' ? HST_CATS : [];
  const items = typeof HST_ITEMS !== 'undefined' ? HST_ITEMS : [];
  const filtered = _hstFilter === 'all' ? items : items.filter(it => it.cat === _hstFilter);
  if (st) st.textContent = filtered.length + ' entries';
  const catBar = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">
    <button class="cat-filter ${_hstFilter==='all'?'active':''}" onclick="_hstSetCat('all')">All</button>
    ${cats.map(c => `<button class="cat-filter ${_hstFilter===c.id?'active':''}" onclick="_hstSetCat('${c.id}')">${c.label}</button>`).join('')}
  </div>`;
  const cards = filtered.map(it => `
    <div style="background:var(--card-bg);border:1px solid var(--border);border-radius:10px;padding:14px 16px;margin-bottom:10px">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px">
        <div>
          <div style="font-size:1.3rem;font-family:'Noto Naskh Arabic',serif;direction:rtl">${it.ar}</div>
          <div style="font-size:0.85rem;color:var(--muted)">${it.tr}</div>
        </div>
        <button class="btn btn-outline" style="font-size:0.75rem;padding:3px 8px" onclick="speak(${attrArg(it.ar)})">🔊</button>
      </div>
      <div style="font-weight:600;margin-top:6px">${it.en}</div>
      <div style="font-size:0.85rem;color:var(--muted);margin-top:4px;font-style:italic">${it.note}</div>
    </div>`).join('');
  el.innerHTML = catBar + (filtered.length ? cards : '<p style="color:var(--muted)">No items.</p>');
}
function _hstFilteredExercises() {
  const exercises = typeof HST_EXERCISES !== 'undefined' ? HST_EXERCISES : [];
  const items = typeof HST_ITEMS !== 'undefined' ? HST_ITEMS : [];
  if (_hstFilter === 'all') return exercises;
  return exercises.filter(ex => {
    const it = items.find(i => i.id === ex.itemId);
    return it && it.cat === _hstFilter;
  });
}
function _hstBuildOptions(ex) {
  const items = typeof HST_ITEMS !== 'undefined' ? HST_ITEMS : [];
  const correct = items.find(i => i.id === ex.itemId);
  if (!correct) return [];
  const distractors = ex.distractors.map(id => items.find(i => i.id === id)).filter(Boolean);
  const opts = [{ ...correct, correct: true }, ...distractors.map(d => ({ ...d, correct: false }))];
  for (let i = opts.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [opts[i], opts[j]] = [opts[j], opts[i]];
  }
  return opts;
}
function _hstCurrentExercise() {
  const exercises = typeof HST_EXERCISES !== 'undefined' ? HST_EXERCISES : [];
  if (!_hstOrder.length) return null;
  return exercises.find(e => e.id === _hstOrder[_hstIdx]) || null;
}
function _hstBuildOrder() {
  const filtered = _hstFilteredExercises();
  _hstOrder = filtered.map(e => e.id);
  for (let i = _hstOrder.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [_hstOrder[i], _hstOrder[j]] = [_hstOrder[j], _hstOrder[i]];
  }
  _hstIdx = 0;
  _hstLocked = false;
  _hstOptions = [];
}
function _hstRenderDrill(el, st) {
  const cats = typeof HST_CATS !== 'undefined' ? HST_CATS : [];
  const catBar = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">
    <button class="cat-filter ${_hstFilter==='all'?'active':''}" onclick="_hstSetCat('all')">All</button>
    ${cats.map(c => `<button class="cat-filter ${_hstFilter===c.id?'active':''}" onclick="_hstSetCat('${c.id}')">${c.label}</button>`).join('')}
  </div>`;
  if (!_hstOrder.length) _hstBuildOrder();
  if (_hstIdx >= _hstOrder.length) {
    if (st) st.textContent = 'done!';
    el.innerHTML = catBar + `<div style="text-align:center;padding:40px 20px">
      <div style="font-size:2rem">🏛️</div>
      <div style="font-size:1.1rem;font-weight:600;margin:12px 0">All ${_hstOrder.length} drills done!</div>
      <div style="color:var(--muted);margin-bottom:16px">Score: ${_hstScore.correct}/${_hstScore.correct+_hstScore.wrong}</div>
      <button class="btn" onclick="window._hstDrillReset()">🔄 Restart</button>
    </div>`;
    return;
  }
  const ex = _hstCurrentExercise();
  if (!ex) { el.innerHTML = catBar + '<p>No exercises.</p>'; return; }
  if (!_hstOptions.length || _hstLocked) {
    if (!_hstLocked) _hstOptions = _hstBuildOptions(ex);
  } else {
    _hstOptions = _hstBuildOptions(ex);
  }
  if (st) st.textContent = `${_hstIdx+1}/${_hstOrder.length} · ✓${_hstScore.correct} ✗${_hstScore.wrong}`;
  const optsHtml = _hstOptions.map((o, i) => {
    let bg = 'var(--card-bg)';
    if (_hstLocked) bg = o.correct ? '#1b5e2030' : '#ff000015';
    return `<div onclick="hstAnswer(${i})" style="cursor:${_hstLocked?'default':'pointer'};background:${bg};border:1px solid var(--border);border-radius:8px;padding:12px 14px;margin-bottom:8px;transition:background 0.2s">
      <div style="font-size:1.15rem;font-family:'Noto Naskh Arabic',serif;direction:rtl">${o.ar}</div>
      <div style="font-size:0.8rem;color:var(--muted)">${o.tr}</div>
      ${_hstLocked ? `<div style="font-size:0.8rem;margin-top:4px;color:${o.correct?'#4caf50':'#f44336'}">${o.correct?'✓ ':''}<em>${o.en}</em></div>` : ''}
    </div>`;
  }).join('');
  const feedbackHtml = _hstLocked ? (() => {
    const chosen = _hstOptions.find((_, i) => i === (_hstLastChosen||0));
    const correct = _hstOptions.find(o => o.correct);
    return `<div style="margin-top:12px;padding:10px 14px;background:var(--card-bg);border-radius:8px;font-size:0.85rem">
      <em>${correct.note}</em><br>
      <button class="btn" style="margin-top:8px" onclick="hstNext()">Next →</button>
    </div>`;
  })() : '';
  el.innerHTML = catBar + `<div style="background:var(--card-bg);border:1px solid var(--border);border-radius:10px;padding:16px;margin-bottom:12px">
    <div style="font-size:0.85rem;color:var(--muted);margin-bottom:8px">What is this?</div>
    <div style="font-size:1rem;font-weight:600">${ex.prompt}</div>
  </div>
  ${optsHtml}${feedbackHtml}`;
}
let _hstLastChosen = 0;
function hstAnswer(idx) {
  if (_hstLocked) return;
  _hstLocked = true;
  _hstLastChosen = idx;
  const opt = _hstOptions[idx];
  if (opt) {
    if (opt.correct) _hstScore.correct++; else _hstScore.wrong++;
  }
  renderHst();
}
function hstNext() {
  _hstIdx++;
  _hstLocked = false;
  _hstOptions = [];
  renderHst();
}
window._hstDrillReset = function() {
  _hstScore = { correct: 0, wrong: 0 };
  _hstBuildOrder();
  renderHst();
};
function _hstRenderTips(el, st) {
  const tips = typeof HST_TIPS !== 'undefined' ? HST_TIPS : [];
  if (st) st.textContent = tips.length + ' tips';
  el.innerHTML = tips.map(t => `<div style="background:var(--card-bg);border:1px solid var(--border);border-radius:8px;padding:12px 14px;margin-bottom:8px;font-size:0.95rem">💡 ${t.tip}</div>`).join('');
}

