// ── R612 — NEW FEATURE: Lebanese Street Food & Snacks Coach (str) ──────────────
let _strTab = 'words';
let _strCat = 'all';
let _strDrillIdx = 0;
let _strDrillPicked = false;
let _strDrillShuf = [];

function openStr(){
  try{ bumpAchievementCounter && bumpAchievementCounter('str_open'); }catch(e){}
  var ov = document.getElementById('str-overlay'); if(!ov) return;
  _strTab = 'words'; _strCat = 'all'; _strDrillIdx = 0; _strDrillPicked = false; _strDrillShuf = [];
  ov.style.display = 'block';
  setStrTab('words');
}
function closeStr(){ var ov=document.getElementById('str-overlay'); if(ov) ov.style.display='none'; }

function setStrTab(t){
  _strTab = t;
  var bar = document.getElementById('str-tab-bar');
  if(bar){
    var tabs = [['words','🥙 Words'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(function(tb){ return '<button class="cat-filter '+(_strTab===tb[0]?'active':'')+'" onclick="setStrTab(\''+tb[0]+'\')">'+tb[1]+'</button>'; }).join('');
  }
  renderStr();
}

function renderStr(){
  var el = document.getElementById('str-content');
  var st = document.getElementById('str-stats');
  if(!el) return;
  if(_strTab==='words') _renderStrWords(el, st);
  else if(_strTab==='drill') _renderStrDrill(el, st);
  else _renderStrTips(el, st);
}

function _renderStrWords(el, st){
  var cats = ['all','bread','snack','sweet','drink'];
  var catLabels = {all:'🍽️ All',bread:'🫓 Breads',snack:'🥙 Snacks',sweet:'🍯 Sweets',drink:'☕ Drinks'};
  var words = typeof STR_WORDS!=='undefined' ? (_strCat==='all' ? STR_WORDS : STR_WORDS.filter(function(w){ return w.cat===_strCat; })) : [];
  if(st) st.textContent = words.length + ' items';
  var h = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">';
  h += cats.map(function(c){ return '<button class="cat-filter '+(_strCat===c?'active':'')+'" onclick="_strCat=\''+c+'\';renderStr()">'+catLabels[c]+'</button>'; }).join('');
  h += '</div><div style="display:grid;gap:10px">';
  words.forEach(function(w){
    h += '<div class="card" style="padding:14px">'
      + '<div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:8px">'
      + '<div><div style="font-size:1.3rem;font-weight:700">' + w.ar + '</div>'
      + '<div style="color:var(--accent);font-size:1rem">' + w.tr + '</div></div>'
      + '<span style="font-size:0.75rem;background:var(--card-border,rgba(0,0,0,0.08));padding:2px 8px;border-radius:12px;color:var(--muted)">' + w.cat + '</span></div>'
      + '<div style="margin-top:6px;color:var(--muted);font-size:0.88rem">' + w.en + '</div>'
      + '<div style="margin-top:4px;font-size:0.82rem;color:var(--muted);font-style:italic">' + w.note + '</div>'
      + '</div>';
  });
  h += '</div>';
  el.innerHTML = h;
}

function _renderStrDrill(el, st){
  var drills = typeof STR_DRILLS!=='undefined' ? STR_DRILLS : [];
  if(!drills.length){ el.innerHTML='<p>No drills.</p>'; return; }
  if(!_strDrillShuf.length){
    _strDrillShuf = drills.map(function(_,i){ return i; }).sort(function(){ return Math.random()-0.5; });
    _strDrillIdx = 0; _strDrillPicked = false;
  }
  if(_strDrillIdx >= _strDrillShuf.length){
    if(st) st.textContent = 'done!';
    el.innerHTML = '<div class="card" style="padding:24px;text-align:center;max-width:480px;margin:0 auto">'
      + '<div style="font-size:2.5rem;margin-bottom:10px">🎉</div>'
      + '<div style="font-weight:700;font-size:1.1rem;margin-bottom:16px">All ' + _strDrillShuf.length + ' drills done!</div>'
      + '<button class="btn" onclick="_strDrillShuf=[];_strDrillIdx=0;_strDrillPicked=false;renderStr()">🔄 Restart</button></div>';
    return;
  }
  var d = drills[_strDrillShuf[_strDrillIdx]];
  if(st) st.textContent = (_strDrillIdx+1) + '/' + _strDrillShuf.length;
  var picked = _strDrillPicked;
  var h = '<div class="card" style="padding:20px">'
    + '<div style="font-size:0.8rem;color:var(--muted);margin-bottom:8px">Street Food Drill ' + (_strDrillIdx+1) + '/' + _strDrillShuf.length + '</div>'
    + '<div style="font-size:1.1rem;font-weight:700;margin-bottom:16px">' + d.q + '</div>'
    + '<div style="display:grid;gap:8px">';
  d.opts.forEach(function(opt, i){
    var bg='', clr='', br='';
    if(picked!==false){
      if(i===d.ans){ bg='var(--success,#22c55e)'; clr='#fff'; br='none'; }
      else if(i===picked && i!==d.ans){ bg='var(--danger,#ef4444)'; clr='#fff'; br='none'; }
    }
    h += '<button class="btn btn-outline" style="text-align:left;' + (bg?'background:'+bg+';color:'+clr+';border-color:'+br+';':'') + '" onclick="strPickOpt('+i+')" '+(picked!==false?'disabled':'')+'>'+opt+'</button>';
  });
  h += '</div>';
  if(picked!==false){
    h += '<div style="margin-top:14px;padding:12px;background:var(--bg);border-radius:8px;font-size:0.9rem;color:var(--muted)">' + d.exp + '</div>';
    h += '<button class="btn" style="margin-top:12px" onclick="strNext()">Next →</button>';
  }
  h += '</div>';
  el.innerHTML = h;
}

function strPickOpt(i){
  if(_strDrillPicked!==false) return;
  _strDrillPicked = i;
  var drills = typeof STR_DRILLS!=='undefined' ? STR_DRILLS : [];
  var d = drills[_strDrillShuf[_strDrillIdx]];
  if(d && i===d.ans){
    try{ incDailyCount&&incDailyCount(); recordActivity&&recordActivity(); addXp&&addXp(10); }catch(e){}
  }
  renderStr();
}
function strNext(){ _strDrillIdx++; _strDrillPicked = false; renderStr(); }

function _renderStrTips(el, st){
  var tips = typeof STR_TIPS!=='undefined' ? STR_TIPS : [];
  if(st) st.textContent = tips.length + ' tips';
  el.innerHTML = '<div style="display:grid;gap:12px">' + tips.map(function(t){
    return '<div class="card" style="padding:16px"><div style="font-weight:700;margin-bottom:6px">💡 ' + t.title + '</div><div style="color:var(--muted);font-size:0.92rem;line-height:1.55">' + t.body + '</div></div>';
  }).join('') + '</div>';
}

// Self-register into TOPICS_CATEGORIES > culture
(function(){
  if(typeof TOPICS_CATEGORIES==='undefined') return;
  var cult = TOPICS_CATEGORIES.find(function(c){ return c.id==='culture'; });
  if(!cult){ cult = {id:'culture',label:'🌍 Culture',items:[]}; TOPICS_CATEGORIES.push(cult); }
  if(!cult.items.find(function(it){ return it.fn==='openStr'; })){
    cult.items.push({label:'🥙 Street Food',fn:'openStr'});
  }
})();

