// ── R615 — NEW FEATURE: Lebanese Neighborhood & City Life Coach (nbh) ──────────
let _nbhTab = 'words';
let _nbhCat = 'all';
let _nbhDrillIdx = 0;
let _nbhDrillPicked = false;
let _nbhDrillShuf = [];

function openNbh(){
  try{ bumpAchievementCounter && bumpAchievementCounter('nbh_open'); }catch(e){}
  var ov = document.getElementById('nbh-overlay'); if(!ov) return;
  _nbhTab = 'words'; _nbhCat = 'all'; _nbhDrillIdx = 0; _nbhDrillPicked = false; _nbhDrillShuf = [];
  ov.style.display = 'block';
  setNbhTab('words');
}
function closeNbh(){ var ov=document.getElementById('nbh-overlay'); if(ov) ov.style.display='none'; }

function setNbhTab(t){
  _nbhTab = t;
  var bar = document.getElementById('nbh-tab-bar');
  if(bar){
    var tabs = [['words','🏘️ Words'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(function(tb){ return '<button class="cat-filter '+(_nbhTab===tb[0]?'active':'')+'" onclick="setNbhTab(\''+tb[0]+'\')">'+tb[1]+'</button>'; }).join('');
  }
  renderNbh();
}

function renderNbh(){
  var el = document.getElementById('nbh-content');
  var st = document.getElementById('nbh-stats');
  if(!el) return;
  if(_nbhTab==='words') _renderNbhWords(el, st);
  else if(_nbhTab==='drill') _renderNbhDrill(el, st);
  else _renderNbhTips(el, st);
}

function _renderNbhWords(el, st){
  var cats = ['all','places','directions','transport','services'];
  var catLabels = {all:'🌆 All',places:'🏘️ Places',directions:'🧭 Directions',transport:'🚌 Transport',services:'🏥 Services'};
  var words = typeof NBH_WORDS!=='undefined' ? (_nbhCat==='all' ? NBH_WORDS : NBH_WORDS.filter(function(w){ return w.cat===_nbhCat; })) : [];
  if(st) st.textContent = words.length + ' items';
  var h = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">';
  h += cats.map(function(c){ return '<button class="cat-filter '+(_nbhCat===c?'active':'')+'" onclick="_nbhCat=\''+c+'\';renderNbh()">'+catLabels[c]+'</button>'; }).join('');
  h += '</div><div style="display:grid;gap:10px">';
  words.forEach(function(w){
    h += '<div class="card" style="padding:14px">'
      + '<div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:8px">'
      + '<div><div style="font-size:1.3rem;font-weight:700">' + w.ar + '</div>'
      + '<div style="color:var(--accent);font-size:1rem">' + w.tr + '</div></div>'
      + '<span style="font-size:0.75rem;background:var(--card-border,rgba(0,0,0,0.08));padding:2px 8px;border-radius:12px;color:var(--muted)">' + w.cat + '</span></div>'
      + '<div style="margin-top:6px;color:var(--muted);font-size:0.88rem">' + w.en + '</div>'
      + '<div style="margin-top:4px;font-size:0.82rem;color:var(--muted);font-style:italic">' + w.note + '</div>'
      + '</div>';
  });
  h += '</div>';
  el.innerHTML = h;
}

function _renderNbhDrill(el, st){
  var drills = typeof NBH_DRILLS!=='undefined' ? NBH_DRILLS : [];
  if(!drills.length){ el.innerHTML='<p>No drills.</p>'; return; }
  if(!_nbhDrillShuf.length){
    _nbhDrillShuf = drills.map(function(_,i){ return i; }).sort(function(){ return Math.random()-0.5; });
    _nbhDrillIdx = 0; _nbhDrillPicked = false;
  }
  if(_nbhDrillIdx >= _nbhDrillShuf.length){
    if(st) st.textContent = 'done!';
    el.innerHTML = '<div class="card" style="padding:24px;text-align:center;max-width:480px;margin:0 auto">'
      + '<div style="font-size:2.5rem;margin-bottom:10px">🎉</div>'
      + '<div style="font-weight:700;font-size:1.1rem;margin-bottom:16px">All ' + _nbhDrillShuf.length + ' drills done!</div>'
      + '<button class="btn" onclick="_nbhDrillShuf=[];_nbhDrillIdx=0;_nbhDrillPicked=false;renderNbh()">🔄 Restart</button></div>';
    return;
  }
  var d = drills[_nbhDrillShuf[_nbhDrillIdx]];
  if(st) st.textContent = (_nbhDrillIdx+1) + '/' + _nbhDrillShuf.length;
  var picked = _nbhDrillPicked;
  var h = '<div class="card" style="padding:20px">'
    + '<div style="font-size:0.8rem;color:var(--muted);margin-bottom:8px">City Life Drill ' + (_nbhDrillIdx+1) + '/' + _nbhDrillShuf.length + '</div>'
    + '<div style="font-size:1.1rem;font-weight:700;margin-bottom:16px">' + d.q + '</div>'
    + '<div style="display:grid;gap:8px">';
  d.opts.forEach(function(opt, i){
    var bg='', clr='', br='';
    if(picked!==false){
      if(i===d.ans){ bg='var(--success,#22c55e)'; clr='#fff'; br='none'; }
      else if(i===picked && i!==d.ans){ bg='var(--danger,#ef4444)'; clr='#fff'; br='none'; }
    }
    h += '<button class="btn btn-outline" style="text-align:left;' + (bg?'background:'+bg+';color:'+clr+';border-color:'+br+';':'') + '" onclick="nbhPickOpt('+i+')" '+(picked!==false?'disabled':'')+'>'+opt+'</button>';
  });
  h += '</div>';
  if(picked!==false){
    h += '<div style="margin-top:14px;padding:12px;background:var(--bg);border-radius:8px;font-size:0.9rem;color:var(--muted)">' + d.exp + '</div>';
    h += '<button class="btn" style="margin-top:12px" onclick="nbhNext()">Next →</button>';
  }
  h += '</div>';
  el.innerHTML = h;
}

function nbhPickOpt(i){
  if(_nbhDrillPicked!==false) return;
  _nbhDrillPicked = i;
  var drills = typeof NBH_DRILLS!=='undefined' ? NBH_DRILLS : [];
  var d = drills[_nbhDrillShuf[_nbhDrillIdx]];
  if(d && i===d.ans){
    try{ incDailyCount&&incDailyCount(); recordActivity&&recordActivity(); addXp&&addXp(10); }catch(e){}
  }
  renderNbh();
}
function nbhNext(){ _nbhDrillIdx++; _nbhDrillPicked = false; renderNbh(); }

function _renderNbhTips(el, st){
  var tips = typeof NBH_TIPS!=='undefined' ? NBH_TIPS : [];
  if(st) st.textContent = tips.length + ' tips';
  el.innerHTML = '<div style="display:grid;gap:12px">' + tips.map(function(t){
    return '<div class="card" style="padding:16px"><div style="font-weight:700;margin-bottom:6px">💡 ' + t.title + '</div><div style="color:var(--muted);font-size:0.92rem;line-height:1.55">' + t.body + '</div></div>';
  }).join('') + '</div>';
}

// Self-register into TOPICS_CATEGORIES > culture
(function(){
  if(typeof TOPICS_CATEGORIES==='undefined') return;
  var cult = TOPICS_CATEGORIES.find(function(c){ return c.id==='culture'; });
  if(!cult){ cult = {id:'culture',label:'🌍 Culture',items:[]}; TOPICS_CATEGORIES.push(cult); }
  if(!cult.items.find(function(it){ return it.fn==='openNbh'; })){
    cult.items.push({label:'🏘️ City Life',fn:'openNbh'});
  }
})();

