// ── Run #627 · NEW FEATURE: Lebanese Technology & Social Media (dij) ──────────
let _dijTab = 'words';
let _dijCat = 'devices';
let _dijDrillIdx = 0;
let _dijDrillAnswered = false;
let _dijPickedIdx = null;
let _dijDrillScore = 0;

function openDij(){
  bumpAchievementCounter && bumpAchievementCounter('dij_open');
  const ov = document.getElementById('dij-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _dijDrillIdx = 0; _dijDrillAnswered = false; _dijPickedIdx = null; _dijDrillScore = 0;
  setDijTab('words');
}
function closeDij(){ const ov=document.getElementById('dij-overlay'); if(ov) ov.style.display='none'; }

function setDijTab(t){
  _dijTab = t;
  const bar = document.getElementById('dij-tab-bar');
  if(bar){
    const tabs = [['words','📱 Words'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_dijTab===k?'active':''}" onclick="setDijTab('${k}')">${l}</button>`).join('');
  }
  renderDij();
}

function renderDij(){
  const el = document.getElementById('dij-content'); if(!el) return;
  const st = document.getElementById('dij-stats');
  if(_dijTab === 'words') _renderDijWords(el, st);
  else if(_dijTab === 'drill') _renderDijDrill(el, st);
  else _renderDijTips(el, st);
}

function _renderDijWords(el, st){
  const words = typeof DIJ_WORDS !== 'undefined' ? DIJ_WORDS : [];
  const cats = typeof DIJ_CATS !== 'undefined' ? DIJ_CATS : [];
  if(st) st.textContent = words.length + ' words';
  const catBar = cats.map(c => `<button class="cat-filter ${_dijCat===c.id?'active':''}" onclick="_dijCat='${c.id}';renderDij()">${c.label}</button>`).join('');
  const filtered = words.filter(w => w.cat === _dijCat);
  const cards = filtered.map(w => `<div style="background:var(--card);border-radius:12px;padding:16px;margin-bottom:10px">
    <div style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:8px">
      <div>
        <div style="font-family:serif;font-size:1.5rem;direction:rtl;margin-bottom:4px">${w.ar}</div>
        <div style="color:var(--acc);font-size:1rem;margin-bottom:2px">${w.tr}</div>
        <div style="font-weight:600;font-size:0.95rem">${w.en}</div>
      </div>
      <button onclick="speak('${w.ar.replace(/'/g,"\\'")}',false)" style="background:var(--acc);color:#fff;border:none;border-radius:8px;padding:6px 12px;cursor:pointer;font-size:1rem">🔊</button>
    </div>
    ${w.note ? `<div style="margin-top:8px;font-size:0.82rem;color:var(--muted);border-top:1px solid var(--border);padding-top:6px">${w.note}</div>` : ''}
  </div>`).join('');
  el.innerHTML = `<div style="display:flex;gap:6px;justify-content:center;flex-wrap:wrap;margin-bottom:14px">${catBar}</div>${cards}`;
}

function _renderDijDrill(el, st){
  const drills = typeof DIJ_DRILLS !== 'undefined' ? DIJ_DRILLS : [];
  if(!drills.length){ el.innerHTML='<p>No drills.</p>'; return; }
  if(_dijDrillIdx >= drills.length){
    if(st) st.textContent = 'Done!';
    el.innerHTML = '<div style="max-width:560px;margin:0 auto;padding-top:20px;text-align:center"><div style="font-size:2.5rem">🎉</div><div style="font-weight:700;font-size:1.1rem;margin:10px 0">All ' + drills.length + ' drills done!</div><div style="color:var(--muted);margin-bottom:14px">Score: ' + _dijDrillScore + ' / ' + drills.length + '</div><button class="btn" style="margin-top:14px" onclick="_dijDrillIdx=0;_dijDrillScore=0;_dijDrillAnswered=false;_dijPickedIdx=null;renderDij()">↺ Restart</button></div>';
    return;
  }
  const d = drills[_dijDrillIdx];
  if(st) st.textContent = `${_dijDrillIdx+1}/${drills.length} · Score: ${_dijDrillScore}`;
  const opts = d.opts.map((o,i) => {
    let bg = 'background:var(--card)'; let col = '';
    if(_dijDrillAnswered){ if(i===d.ans){ bg='background:#1b5e20'; col='color:#fff;'; } else if(i===_dijPickedIdx){ bg='background:#b71c1c'; col='color:#fff;'; } }
    return `<button onclick="dijPickOpt(${i})" style="width:100%;text-align:left;padding:10px 14px;margin-bottom:6px;border-radius:8px;border:none;cursor:pointer;${bg};${col}font-size:0.95rem">${o}</button>`;
  }).join('');
  el.innerHTML = `<div style="background:var(--card);border-radius:12px;padding:18px;max-width:560px;margin:0 auto">
    <div style="margin-bottom:12px;font-size:0.8rem;color:var(--muted)">Question ${_dijDrillIdx+1} of ${drills.length}</div>
    <div style="font-weight:600;font-size:1rem;margin-bottom:14px">${d.q}</div>
    ${opts}
    ${_dijDrillAnswered ? `<div style="margin-top:10px;font-size:0.85rem;color:var(--muted);padding:8px;background:var(--bg);border-radius:6px">${d.exp}</div><button class="btn" style="width:100%;margin-top:8px" onclick="_dijDrillNext()">Next →</button>` : ''}
  </div>`;
}

function dijPickOpt(i){
  if(_dijDrillAnswered) return;
  const drills = typeof DIJ_DRILLS !== 'undefined' ? DIJ_DRILLS : [];
  const d = drills[_dijDrillIdx];
  _dijPickedIdx = i;
  _dijDrillAnswered = true;
  if(i === d.ans){ _dijDrillScore++; recordActivity && recordActivity(); incDailyCount && incDailyCount(); addXp && addXp(XP_PER_RATING ? XP_PER_RATING[2]||10 : 10); }
  showToast && showToast(i === d.ans ? '✓ Correct!' : '✗ Try again');
  renderDij();
}

function _dijDrillNext(){
  _dijDrillIdx++;
  _dijDrillAnswered = false;
  _dijPickedIdx = null;
  renderDij();
}

function _renderDijTips(el, st){
  const tips = typeof DIJ_TIPS !== 'undefined' ? DIJ_TIPS : [];
  if(st) st.textContent = tips.length + ' tips';
  el.innerHTML = `<div style="display:flex;flex-direction:column;gap:12px">${tips.map(t => `<div style="background:var(--card);border-radius:10px;padding:14px;display:flex;gap:12px;align-items:flex-start"><div style="font-size:1.4rem;min-width:32px">📱</div><div><strong style="color:var(--acc)">${t.title}</strong><br>${t.body}</div></div>`).join('')}</div>`;
}

