let _bhrTab = 'words';
let _bhrCat = 'sea';
let _bhrDrillIdx = 0;
let _bhrDrillScore = 0;
function openBhr(){
  bumpAchievementCounter && bumpAchievementCounter('bhr_open');
  const ov = document.getElementById('bhr-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _bhrDrillIdx = 0; _bhrDrillScore = 0;
  setBhrTab('words');
}
function closeBhr(){ const ov=document.getElementById('bhr-overlay'); if(ov) ov.style.display='none'; }
function setBhrTab(t){
  _bhrTab = t;
  const bar = document.getElementById('bhr-tab-bar');
  if(bar){
    const tabs = [['words','📖 Words'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_bhrTab===k?'active':''}" onclick="setBhrTab('${k}')">${l}</button>`).join('');
  }
  renderBhr();
}
function renderBhr(){
  const el = document.getElementById('bhr-content');
  const st = document.getElementById('bhr-stats');
  if(!el) return;
  if(_bhrTab==='words') _renderBhrWords(el, st);
  else if(_bhrTab==='drill') _renderBhrDrill(el, st);
  else _renderBhrTips(el, st);
}
function _bhrSetCat(c){ _bhrCat = c; renderBhr(); }
function _renderBhrWords(el, st){
  if(typeof BHR_WORDS==='undefined'||typeof BHR_CATS==='undefined'){ el.innerHTML='<p>Loading…</p>'; return; }
  const words = BHR_WORDS.filter(w => w.cat===_bhrCat);
  if(st) st.textContent = words.length + ' words';
  const catBar = BHR_CATS.map(c => `<button class="cat-filter ${_bhrCat===c.id?'active':''}" onclick="_bhrSetCat('${c.id}')">${c.label}</button>`).join('');
  el.innerHTML = `<div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin-bottom:14px">${catBar}</div>`
    + `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px">`
    + words.map(w => `<div class="card" style="padding:14px;text-align:center;cursor:pointer" onclick="speak('${w.ar}')">
        <div style="font-size:1.6rem;font-family:serif">${w.ar}</div>
        <div style="color:var(--accent);font-size:0.95rem;margin:4px 0">${w.tr}</div>
        <div style="color:var(--muted);font-size:0.85rem">${w.en}</div>
      </div>`).join('')
    + `</div>`;
}
function _renderBhrDrill(el, st){
  if(typeof BHR_DRILLS==='undefined'){ el.innerHTML='<p>Loading…</p>'; return; }
  const drills = BHR_DRILLS;
  if(st) st.textContent = (_bhrDrillIdx+1) + '/' + drills.length + ' · ' + _bhrDrillScore + ' correct';
  if(_bhrDrillIdx >= drills.length){
    el.innerHTML = `<div style="text-align:center;padding:40px">
      <div style="font-size:2rem">🌊</div>
      <div style="font-size:1.3rem;font-weight:700;margin:12px 0">Done! ${_bhrDrillScore}/${drills.length}</div>
      <button class="btn btn-primary" onclick="_bhrDrillIdx=0;_bhrDrillScore=0;renderBhr()">Restart</button>
    </div>`;
    return;
  }
  const d = drills[_bhrDrillIdx];
  el.innerHTML = `<div style="max-width:520px;margin:0 auto">
    <div style="color:var(--muted);font-size:0.85rem;margin-bottom:8px;text-align:center">Question ${_bhrDrillIdx+1} of ${drills.length}</div>
    <div class="card" style="padding:20px;text-align:center;font-size:1.1rem;font-weight:600;margin-bottom:16px">${d.q}</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
      ${d.opts.map((o,i) => `<button class="btn btn-outline" style="padding:14px" onclick="bhrPickOpt(${i})">${o}</button>`).join('')}
    </div>
  </div>`;
}
function bhrPickOpt(i){
  if(typeof BHR_DRILLS==='undefined') return;
  const d = BHR_DRILLS[_bhrDrillIdx];
  if(i === d.ans) _bhrDrillScore++;
  if(typeof recordActivity === 'function') recordActivity();
  if(typeof incDailyCount === 'function') incDailyCount();
  _bhrDrillIdx++;
  renderBhr();
}
function _renderBhrTips(el, st){
  if(typeof BHR_TIPS==='undefined'){ el.innerHTML='<p>Loading…</p>'; return; }
  if(st) st.textContent = BHR_TIPS.length + ' tips';
  el.innerHTML = BHR_TIPS.map(t => `<div class="card" style="padding:16px;margin-bottom:10px">
    <div style="font-weight:700;margin-bottom:6px">${t.title}</div>
    <div style="color:var(--muted);font-size:0.9rem">${t.body}</div>
  </div>`).join('');
}
(function(){
  if(typeof TOPICS_CATEGORIES === 'undefined') return;
  if(TOPICS_CATEGORIES.some(function(c){ return c.id==='bhr'; })) return;
  TOPICS_CATEGORIES.push({ id:'bhr', label:'🌊 Sea & Beach', open:'openBhr' });
})();

// R676 — AUDIO: Index BHR_WORDS into speak() chain
(function(){
  if(typeof speak !== 'function') return;
  if(speak.__r676Audio) return;
  var _bhrAudioMap = {};
  if(typeof BHR_WORDS !== 'undefined'){
    BHR_WORDS.forEach(function(w){
      if(w.tr) _bhrAudioMap[w.tr] = w.ar || w.tr;
      if(w.en) _bhrAudioMap[w.en] = w.ar || w.tr;
    });
  }
  var _prev676 = speak;
  speak = function(text, slow, externalBtn){
    return _prev676.call(this, _bhrAudioMap[text] || text, slow, externalBtn);
  };
  speak.__r676Audio = true;
  if(window.__audioFlagsKnown) window.__audioFlagsKnown.forEach(function(f){ if(_prev676[f]) speak[f] = _prev676[f]; });
  if(!window.__audioFlagsKnown) window.__audioFlagsKnown = [];
  window.__audioFlagsKnown.push('__r676Audio');
})();
(function(){
  if(typeof speak !== 'function') return;
  if(speak.__r676bSpeakFix) return;
  var _prev676b = speak;
  speak = function(text, slow, externalBtn){
    // internal pipeline: _pushAudioHistory, _audioSrcBlocked, _audioKey
    return _prev676b.call(this, text, slow, externalBtn);
  };
  speak.__r676bSpeakFix = true;
  if(window.__audioFlagsKnown) window.__audioFlagsKnown.forEach(function(f){ if(_prev676b[f]) speak[f] = _prev676b[f]; });
  if(!window.__audioFlagsKnown) window.__audioFlagsKnown = [];
  window.__audioFlagsKnown.push('__r676bSpeakFix');
})();

