let _jwlTab = 'words';
let _jwlCat = 'metals';
let _jwlDrillIdx = 0;
let _jwlDrillPicked = false;
function openJwl(){
  bumpAchievementCounter && bumpAchievementCounter('jwl_open');
  const ov = document.getElementById('jwl-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _jwlDrillIdx = 0; _jwlDrillPicked = false;
  setJwlTab('words');
}
function closeJwl(){ const ov=document.getElementById('jwl-overlay'); if(ov) ov.style.display='none'; }
function setJwlTab(t){
  _jwlTab = t;
  const bar = document.getElementById('jwl-tab-bar');
  if(bar){
    const tabs = [['words','📖 Words'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_jwlTab===k?'active':''}" onclick="setJwlTab('${k}')">${l}</button>`).join('');
  }
  renderJwl();
}
function renderJwl(){
  const el = document.getElementById('jwl-content'); if(!el) return;
  if(_jwlTab==='words') _renderJwlWords(el);
  else if(_jwlTab==='drill') _renderJwlDrill(el);
  else _renderJwlTips(el);
}
function _jwlSetCat(c){
  _jwlCat = c;
  renderJwl();
}
function _renderJwlWords(el){
  const cats = typeof JWL_CATS!=='undefined'?JWL_CATS:[];
  const words = typeof JWL_WORDS!=='undefined'?JWL_WORDS:[];
  const filtered = words.filter(w=>w.cat===_jwlCat);
  const catBar = cats.map(c=>`<button class="cat-filter ${_jwlCat===c.id?'active':''}" onclick="_jwlSetCat('${c.id}')">${c.label}</button>`).join('');
  el.innerHTML = `<div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin-bottom:14px">${catBar}</div>`+
    `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px">`+
    filtered.map(w=>`<div class="card" style="padding:14px;cursor:pointer" onclick="speak('${w.ar}','ar')">
      <div style="font-size:1.4rem;font-weight:700;color:var(--primary)">${w.ar}</div>
      <div style="color:var(--muted);font-size:0.9rem">${w.tr}</div>
      <div style="font-size:0.85rem">${w.en}</div>
    </div>`).join('')+`</div>`;
}
function _renderJwlDrill(el){
  const drills = typeof JWL_DRILLS!=='undefined'?JWL_DRILLS:[];
  if(!drills.length){ el.innerHTML='<p>No drills.</p>'; return; }
  if(_jwlDrillIdx>=drills.length){ el.innerHTML=`<div style="text-align:center;padding:40px"><div style="font-size:2rem">🎉</div><div>All ${drills.length} drills done!</div><button class="btn btn-primary" onclick="_jwlDrillIdx=0;_jwlDrillPicked=false;renderJwl()">Restart</button></div>`; return; }
  const d = drills[_jwlDrillIdx];
  const stat = document.getElementById('jwl-stats'); if(stat) stat.textContent = `${_jwlDrillIdx+1}/${drills.length}`;
  el.innerHTML = `<div style="max-width:540px;margin:0 auto;padding:20px">
    <div class="card" style="padding:24px;text-align:center;margin-bottom:16px">
      <div style="font-size:1.1rem;font-weight:600;margin-bottom:20px">${d.q}</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
        ${d.opts.map((o,i)=>`<button class="btn btn-outline jwl-opt" data-i="${i}" onclick="jwlPickOpt(${i})" style="padding:12px">${o}</button>`).join('')}
      </div>
    </div>
  </div>`;
}
function jwlPickOpt(i){
  if(_jwlDrillPicked) return;
  _jwlDrillPicked = true;
  recordActivity && recordActivity();
  incDailyCount && incDailyCount();
  const drills = typeof JWL_DRILLS!=='undefined'?JWL_DRILLS:[];
  const d = drills[_jwlDrillIdx];
  document.querySelectorAll('.jwl-opt').forEach(function(b){
    const bi = parseInt(b.getAttribute('data-i'));
    b.style.background = bi===d.ans ? 'var(--success,#4caf50)' : (bi===i ? 'var(--error,#e53935)' : '');
    b.style.color = (bi===d.ans||bi===i) ? '#fff' : '';
  });
  setTimeout(function(){ _jwlDrillIdx++; _jwlDrillPicked=false; renderJwl(); }, 900);
}
function _renderJwlTips(el){
  const tips = typeof JWL_TIPS!=='undefined'?JWL_TIPS:[];
  el.innerHTML = tips.map(t=>`<div class="card" style="padding:18px;margin-bottom:12px">
    <div style="font-weight:700;margin-bottom:8px">${t.title}</div>
    <div style="color:var(--muted);font-size:0.9rem;line-height:1.6">${t.body}</div>
  </div>`).join('');
}

