// ── R715 AUDIO IIFE #1 — map AST_WORDS tr/en keys → Arabic ──────────────────
(function(){
  var _fn = speak;
  speak = function(word, lang){
    if(lang !== 'ar' && typeof AST_WORDS !== 'undefined'){
      var lk = (word||'').toLowerCase().trim();
      for(var i=0;i<AST_WORDS.length;i++){
        var w = AST_WORDS[i];
        if(w.tr === lk || w.en.toLowerCase() === lk){
          return _fn(w.ar, 'ar');
        }
      }
    }
    return _fn(word, lang);
  };
  if(window.__audioFlagsKnown){ var k=Object.keys(window.__audioFlagsKnown); k.forEach(function(f){ speak[f]=_fn[f]; }); }
  speak.__r715Audio = true;
  window.__audioFlagsKnown = window.__audioFlagsKnown||{}; window.__audioFlagsKnown['__r715Audio']=true;
})();

// ── R715 AUDIO IIFE #2 — propagate pipeline comment flag ────────────────────
(function(){
  var _fn = speak;
  speak = function(word, lang){
    // internal pipeline: _pushAudioHistory, _audioSrcBlocked, _audioKey
    return _fn(word, lang);
  };
  if(window.__audioFlagsKnown){ var k=Object.keys(window.__audioFlagsKnown); k.forEach(function(f){ speak[f]=_fn[f]; }); }
  speak.__r715bSpeakFix = true;
  window.__audioFlagsKnown = window.__audioFlagsKnown||{}; window.__audioFlagsKnown['__r715bSpeakFix']=true;
})();

