  function _wrap716(fn, resetFn){
    if(!fn || fn.__r716Reset) return fn;
    var _orig = fn;
    var wrapped = function(){ try{ resetFn(); }catch(e){} _orig.apply(this,arguments); };
    for(var k in _orig){ try{ wrapped[k]=_orig[k]; }catch(e){} }
    Object.keys(_orig).forEach(function(k){ try{ wrapped[k]=_orig[k]; }catch(e){} });
    wrapped.__r716Reset = true;
    return wrapped;
  }
  if(typeof openBhr  ==='function') openBhr  =_wrap716(openBhr,  function(){ _bhrDrillIdx=0; });
