  if(typeof openHst  ==='function') openHst  =_wrap716(openHst,  function(){ _hstIdx=0; _hstLocked=false; });
  if(typeof openLic  ==='function') openLic  =_wrap716(openLic,  function(){ _licIdx=0; _licLocked=false; });
