// ── R717 NEW FEATURE — Lebanese News & Media (nwsp) ─────────────────────────
let _nwspTab = 'words';
let _nwspCat = 'all';
let _nwspDrillIdx = 0;
let _nwspDrillPicked = false;

function openNwsp(){
  bumpAchievementCounter && bumpAchievementCounter('nwsp_open');
  const ov = document.getElementById('nwsp-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _nwspDrillIdx = 0; _nwspDrillPicked = false;
  setNwspTab('words');
}
function closeNwsp(){ const ov=document.getElementById('nwsp-overlay'); if(ov) ov.style.display='none'; }
function setNwspTab(t){
  _nwspTab = t;
  const bar = document.getElementById('nwsp-tab-bar');
  if(bar){
    const tabs = [['words','📰 Words'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_nwspTab===k?'active':''}" onclick="setNwspTab('${k}')">${l}</button>`).join('');
  }
  renderNwsp();
}
function renderNwsp(){
  const el = document.getElementById('nwsp-content'); if(!el) return;
  if(_nwspTab==='words') _renderNwspWords(el);
  else if(_nwspTab==='drill') _renderNwspDrill(el);
  else _renderNwspTips(el);
}
function _nwspSetCat(c){
  _nwspCat = c;
  renderNwsp();
}
function _renderNwspWords(el){
  const cats = [['all','All']].concat(NWSP_CATS.map(c=>[c.id,c.label]));
  const words = _nwspCat==='all' ? NWSP_WORDS : NWSP_WORDS.filter(w=>w.cat===_nwspCat);
  const st = document.getElementById('nwsp-stats');
  if(st) st.textContent = words.length + ' words';
  el.innerHTML = `<div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin-bottom:12px">${cats.map(([id,lb])=>`<button class="cat-filter ${_nwspCat===id?'active':''}" onclick="_nwspSetCat('${id}')">${lb}</button>`).join('')}</div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px">${words.map(w=>`<div class="card" style="padding:12px;cursor:pointer" onclick="speak('${w.ar}','ar')"><div style="font-size:1.3rem;font-weight:700">${w.ar}</div><div style="color:var(--accent);font-size:0.9rem">${w.tr}</div><div style="color:var(--muted);font-size:0.85rem">${w.en}</div></div>`).join('')}</div>`;
}
function _renderNwspDrill(el){
  if(!NWSP_DRILLS || !NWSP_DRILLS.length){ el.innerHTML='<p>No drills.</p>'; return; }
  if(_nwspDrillIdx >= NWSP_DRILLS.length) _nwspDrillIdx = 0;
  const d = NWSP_DRILLS[_nwspDrillIdx];
  const st = document.getElementById('nwsp-stats');
  if(st) st.textContent = (_nwspDrillIdx+1)+'/'+NWSP_DRILLS.length;
  el.innerHTML = `<div class="card" style="padding:20px;max-width:560px;margin:0 auto"><p style="font-size:1.1rem;font-weight:600;margin-bottom:16px">${d.q}</p><div style="display:flex;flex-direction:column;gap:8px">${d.opts.map((o,i)=>`<button id="nwsp-opt-${i}" class="btn btn-outline" style="text-align:left" onclick="nwspPickOpt(${i})">${o}</button>`).join('')}</div><div id="nwsp-drill-fb" style="margin-top:14px;font-weight:600"></div></div>`;
  _nwspDrillPicked = false;
}
function nwspPickOpt(i){
  if(_nwspDrillPicked) return;
  _nwspDrillPicked = true;
  const d = NWSP_DRILLS[_nwspDrillIdx];
  const correct = i === d.ans;
  const fb = document.getElementById('nwsp-drill-fb');
  if(fb) fb.innerHTML = correct ? '<span style="color:#4caf50">✓ Correct!</span> <button class="btn btn-outline" style="margin-left:8px" onclick="nwspNext()">Next →</button>' : `<span style="color:#e57373">✗ Answer: ${d.opts[d.ans]}</span> <button class="btn btn-outline" style="margin-left:8px" onclick="nwspNext()">Next →</button>`;
  const btn = document.getElementById('nwsp-opt-'+i);
  if(btn) btn.style.background = correct ? 'rgba(76,175,80,0.2)' : 'rgba(229,115,115,0.2)';
  const correct_btn = document.getElementById('nwsp-opt-'+d.ans);
  if(correct_btn && !correct) correct_btn.style.background = 'rgba(76,175,80,0.2)';
  recordActivity && recordActivity();
  incDailyCount && incDailyCount();
}
function nwspNext(){
  _nwspDrillIdx = (_nwspDrillIdx + 1) % NWSP_DRILLS.length;
  _nwspDrillPicked = false;
  _renderNwspDrill(document.getElementById('nwsp-content'));
}
function _renderNwspTips(el){
  el.innerHTML = NWSP_TIPS.map(t=>`<div class="card" style="padding:16px;margin-bottom:12px"><strong>${t.title}</strong><p style="margin-top:8px;color:var(--muted);line-height:1.6">${t.body}</p></div>`).join('');
}

