let _unvTab = 'words';
let _unvCat = 'all';
let _unvDrillIdx = 0;
let _unvDrillPicked = false;

function openUnv(){
  bumpAchievementCounter && bumpAchievementCounter('unv_open');
  const ov = document.getElementById('unv-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _unvDrillIdx = 0; _unvDrillPicked = false;
  setUnvTab('words');
}
function closeUnv(){ const ov=document.getElementById('unv-overlay'); if(ov) ov.style.display='none'; }
function setUnvTab(t){
  _unvTab = t;
  const bar = document.getElementById('unv-tab-bar');
  if(bar){
    const tabs = [['words','📚 Words'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_unvTab===k?'active':''}" onclick="setUnvTab('${k}')">${l}</button>`).join('');
  }
  renderUnv();
}
function renderUnv(){
  const el = document.getElementById('unv-content'); if(!el) return;
  if(_unvTab==='words') _renderUnvWords(el);
  else if(_unvTab==='drill') _renderUnvDrill(el);
  else _renderUnvTips(el);
}
function _unvSetCat(c){ _unvCat = c; renderUnv(); }
function _renderUnvWords(el){
  const cats = [['all','All']].concat(UNV_CATS.map(c=>[c.id,c.label]));
  const words = _unvCat==='all' ? UNV_WORDS : UNV_WORDS.filter(w=>w.cat===_unvCat);
  const st = document.getElementById('unv-stats');
  if(st) st.textContent = words.length + ' words';
  el.innerHTML = `<div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin-bottom:12px">${cats.map(([id,lb])=>`<button class="cat-filter ${_unvCat===id?'active':''}" onclick="_unvSetCat('${id}')">${lb}</button>`).join('')}</div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px">${words.map(w=>`<div class="card" style="padding:12px;cursor:pointer" onclick="speak('${w.ar}','ar')"><div style="font-size:1.3rem;font-weight:700">${w.ar}</div><div style="color:var(--accent);font-size:0.9rem">${w.tr}</div><div style="color:var(--muted);font-size:0.85rem">${w.en}</div></div>`).join('')}</div>`;
}
function _renderUnvDrill(el){
  if(!UNV_DRILLS || !UNV_DRILLS.length){ el.innerHTML='<p>No drills.</p>'; return; }
  if(_unvDrillIdx >= UNV_DRILLS.length) _unvDrillIdx = 0;
  const d = UNV_DRILLS[_unvDrillIdx];
  const st = document.getElementById('unv-stats');
  if(st) st.textContent = (_unvDrillIdx+1)+'/'+UNV_DRILLS.length;
  el.innerHTML = `<div class="card" style="padding:20px;max-width:560px;margin:0 auto"><p style="font-size:1.1rem;font-weight:600;margin-bottom:16px">${d.q}</p><div style="display:flex;flex-direction:column;gap:8px">${d.opts.map((o,i)=>`<button id="unv-opt-${i}" class="btn btn-outline" style="text-align:left" onclick="unvPickOpt(${i})">${o}</button>`).join('')}</div><div id="unv-drill-fb" style="margin-top:14px;font-weight:600"></div></div>`;
  _unvDrillPicked = false;
}
function unvPickOpt(i){
  if(_unvDrillPicked) return;
  _unvDrillPicked = true;
  const d = UNV_DRILLS[_unvDrillIdx];
  const correct = i === d.ans;
  const fb = document.getElementById('unv-drill-fb');
  if(fb) fb.innerHTML = correct ? '<span style="color:#4caf50">✓ Correct!</span> <button class="btn btn-outline" style="margin-left:8px" onclick="unvNext()">Next →</button>' : `<span style="color:#e57373">✗ Answer: ${d.opts[d.ans]}</span> <button class="btn btn-outline" style="margin-left:8px" onclick="unvNext()">Next →</button>`;
  const btn = document.getElementById('unv-opt-'+i);
  if(btn) btn.style.background = correct ? 'rgba(76,175,80,0.2)' : 'rgba(229,115,115,0.2)';
  const cbtn = document.getElementById('unv-opt-'+d.ans);
  if(cbtn && !correct) cbtn.style.background = 'rgba(76,175,80,0.2)';
  recordActivity && recordActivity();
  incDailyCount && incDailyCount();
}
function unvNext(){
  _unvDrillIdx = (_unvDrillIdx + 1) % UNV_DRILLS.length;
  _unvDrillPicked = false;
  _renderUnvDrill(document.getElementById('unv-content'));
}
function _renderUnvTips(el){
  el.innerHTML = UNV_TIPS.map(t=>`<div class="card" style="padding:16px;margin-bottom:12px"><strong>${t.title}</strong><p style="margin-top:8px;color:var(--muted);line-height:1.6">${t.body}</p></div>`).join('');
}

