// ── R737 BUG FIX: index SPATIAL_WORDS/FREQ_WORDS/NUMBER_WORDS/QUESTION_WORDS into speak() ──
// These core vocab arrays predated the audio indexing system and were never wired.
(function(){
  if(window.__r737AudioFix) return;
  window.__r737AudioFix = true;

  function _wrapForWords(wordArray) {
    var _fn = speak;
    speak = function(word, lang){
      if(lang !== 'ar' && Array.isArray(wordArray)){
        var lk = (word||'').toLowerCase().trim();
        for(var i=0;i<wordArray.length;i++){
          var w = wordArray[i];
          if(!w || !w.ar) continue;
          if((w.tr && w.tr.toLowerCase() === lk) || (w.en && w.en.toLowerCase() === lk)){
            return _fn(w.ar, 'ar');
          }
        }
      }
      return _fn(word, lang);
    };
    if(window.__audioFlagsKnown){ var k=Object.keys(window.__audioFlagsKnown); k.forEach(function(f){ speak[f]=_fn[f]; }); }
    speak.__r737AudioFix = true;
    window.__audioFlagsKnown = window.__audioFlagsKnown||{}; window.__audioFlagsKnown['__r737AudioFix']=true;
  }

  var arrays = [];
  if(typeof SPATIAL_WORDS   !== 'undefined') arrays.push(SPATIAL_WORDS);
  if(typeof FREQ_WORDS      !== 'undefined') arrays.push(FREQ_WORDS);
  if(typeof NUMBER_WORDS    !== 'undefined') arrays.push(NUMBER_WORDS);
  if(typeof QUESTION_WORDS  !== 'undefined') arrays.push(QUESTION_WORDS);
  arrays.forEach(_wrapForWords);
})();

