function _renderGrgDrill(el){
  const drills = typeof GRG_DRILLS!=='undefined'?GRG_DRILLS:[];
  if(!drills.length){ el.innerHTML='<p>No drills.</p>'; return; }
  const d = drills[_grgDrillIdx % drills.length];
  const statsEl = document.getElementById('grg-stats');
  if(statsEl) statsEl.textContent = `${_grgDrillIdx % drills.length + 1}/${drills.length}`;
  if(_grgDrillPicked){
    el.innerHTML=`<div class="drill-card"><p class="drill-q">${d.q}</p>${d.opts.map((o,i)=>`<button class="drill-opt ${i===d.a?'correct':''}" disabled>${o}</button>`).join('')}<button class="btn btn-primary" style="margin-top:14px" onclick="grgNext()">Next →</button></div>`;
  } else {
    el.innerHTML=`<div class="drill-card"><p class="drill-q">${d.q}</p>${d.opts.map((o,i)=>`<button class="drill-opt" onclick="grgPickOpt(${i})">${o}</button>`).join('')}</div>`;
  }
}
function grgPickOpt(i){
  const drills = typeof GRG_DRILLS!=='undefined'?GRG_DRILLS:[];
  const d = drills[_grgDrillIdx % drills.length];
  _grgDrillPicked = true;
  const correct = i===d.a;
  if(correct){ sfx(sfxCorrect); recordActivity && recordActivity(); incDailyCount && incDailyCount(); if(typeof addXp==='function') addXp((typeof XP_PER_RATING!=='undefined'?XP_PER_RATING[2]:0)||10); }
  else sfx(sfxWrong);
  const el=document.getElementById('grg-content'); if(!el) return;
  const d2=drills[_grgDrillIdx%drills.length];
  el.innerHTML=`<div class="drill-card"><p class="drill-q">${d2.q}</p>${d2.opts.map((o,j)=>`<button class="drill-opt ${j===d2.a?'correct':j===i?'wrong':''}" disabled>${o}</button>`).join('')}<button class="btn btn-primary" style="margin-top:14px" onclick="grgNext()">Next →</button></div>`;
}
function grgNext(){ _grgDrillIdx++; _grgDrillPicked=false; renderGrg(); }
function _renderGrgTips(el){
  const tips = typeof GRG_TIPS!=='undefined'?GRG_TIPS:[];
  el.innerHTML=tips.map(t=>`<div class="tip-card"><strong>${t.title}</strong><p>${t.body}</p></div>`).join('');
}

