// ── R743 BUG FIX: add missing progress tracking to 10 pickOpts ───────────────
// sws/pvg/bky: had addXp+incDailyCount but missing recordActivity
// hrb/cft/sch/mnt/dgt: had addXp but missing recordActivity+incDailyCount
// vlg/pol: had recordActivity but missing incDailyCount+addXp
(function(){
  if(window.__r743TrackFix) return;
  window.__r743TrackFix = true;

  // Wrap to inject missing tracking calls (only on correct answer via passthrough)
  function _wrapAddTracking743(fn, flags){
    if(!fn || fn.__r743Fixed) return fn;
    var _orig = fn;
    var wrapped = function(){
      var result = _orig.apply(this, arguments);
      try{
        if(flags.rec && typeof recordActivity==='function') recordActivity();
        if(flags.inc && typeof incDailyCount==='function') incDailyCount();
        if(flags.xp && typeof addXp==='function') addXp((typeof XP_PER_RATING!=='undefined'?XP_PER_RATING[2]:0)||10);
      }catch(e){}
      return result;
    };
    Object.keys(_orig).forEach(function(k){ try{ wrapped[k]=_orig[k]; }catch(e){} });
    wrapped.__r743Fixed = true;
    return wrapped;
  }

  // sws/pvg/bky: add recordActivity only (already have inc+xp)
  if(typeof swsPickOpt==='function') swsPickOpt=_wrapAddTracking743(swsPickOpt,{rec:true,inc:false,xp:false});
  if(typeof pvgPickOpt==='function') pvgPickOpt=_wrapAddTracking743(pvgPickOpt,{rec:true,inc:false,xp:false});
  if(typeof bkyPickOpt==='function') bkyPickOpt=_wrapAddTracking743(bkyPickOpt,{rec:true,inc:false,xp:false});

  // hrb/cft/sch/mnt/dgt: add recordActivity+incDailyCount (already have xp)
  if(typeof hrbPickOpt==='function') hrbPickOpt=_wrapAddTracking743(hrbPickOpt,{rec:true,inc:true,xp:false});
  if(typeof cftPickOpt==='function') cftPickOpt=_wrapAddTracking743(cftPickOpt,{rec:true,inc:true,xp:false});
  if(typeof schPickOpt==='function') schPickOpt=_wrapAddTracking743(schPickOpt,{rec:true,inc:true,xp:false});
  if(typeof mntPickOpt==='function') mntPickOpt=_wrapAddTracking743(mntPickOpt,{rec:true,inc:true,xp:false});
  if(typeof dgtPickOpt==='function') dgtPickOpt=_wrapAddTracking743(dgtPickOpt,{rec:true,inc:true,xp:false});

  // vlg/pol: add incDailyCount+addXp (already have recordActivity)
  if(typeof vlgPickOpt==='function') vlgPickOpt=_wrapAddTracking743(vlgPickOpt,{rec:false,inc:true,xp:true});
  if(typeof polPickOpt==='function') polPickOpt=_wrapAddTracking743(polPickOpt,{rec:false,inc:true,xp:true});
})();

