  if(typeof hmePickOpt==='function'&&typeof HME_DRILLS!=='undefined')
    hmePickOpt=_wrapSfx746(hmePickOpt,function(idx){return HME_DRILLS[idx];},function(){return _hmeDrillIdx;});
