// ── R750 NEW FEATURE: Lebanese Pharmacy & Health coach (sdl) ──
let _sdlTab = 'words';
let _sdlCat = 'pharmacy';
let _sdlDrillIdx = 0;
let _sdlDrillPicked = false;
let _sdlDrillScore = 0;

function openSdl(){
  bumpAchievementCounter && bumpAchievementCounter('sdl_open');
  const ov = document.getElementById('sdl-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _sdlDrillIdx = 0; _sdlDrillPicked = false; _sdlDrillScore = 0;
  setSdlTab('words');
}
function closeSdl(){ const ov=document.getElementById('sdl-overlay'); if(ov) ov.style.display='none'; }
function setSdlTab(t){
  _sdlTab = t;
  const bar = document.getElementById('sdl-tab-bar');
  if(bar){
    const tabs = [['words','💊 Words'],['drill','🎯 Drill'],['tips','📖 Culture']];
    bar.innerHTML = tabs.map(([k,l])=>`<button class="cat-filter ${_sdlTab===k?'active':''}" onclick="setSdlTab('${k}')">${l}</button>`).join('');
  }
  renderSdl();
}
function renderSdl(){
  const el = document.getElementById('sdl-content');
  const st = document.getElementById('sdl-stats');
  if(!el) return;
  if(_sdlTab==='words') _renderSdlWords(el, st);
  else if(_sdlTab==='drill') _renderSdlDrill(el, st);
  else _renderSdlTips(el);
}
function _sdlSetCat(c){ _sdlCat=c; renderSdl(); }
function _renderSdlWords(el, st){
  const cats = SDL_CATS;
  const words = SDL_WORDS.filter(w=>w.cat===_sdlCat);
  if(st) st.textContent = `${words.length} words`;
  el.innerHTML = `<div style="display:flex;gap:6px;justify-content:center;flex-wrap:wrap;margin-bottom:14px">${cats.map(c=>`<button class="cat-filter ${_sdlCat===c?'active':''}" onclick="_sdlSetCat('${c}')">${c}</button>`).join('')}</div>`
    + `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:10px">${words.map(w=>`<div class="card" style="padding:14px;cursor:pointer" onclick="speak('${w.tr}')"><div style="font-size:1.3rem;font-weight:700">${w.ar}</div><div style="color:var(--muted);font-size:0.9rem">${w.tr}</div><div style="font-size:0.85rem;margin-top:4px">${w.en}</div></div>`).join('')}</div>`;
}
function _renderSdlDrill(el, st){
  if(_sdlDrillIdx >= SDL_DRILLS.length){
    if(st) st.textContent = `${_sdlDrillScore}/${SDL_DRILLS.length} correct`;
    el.innerHTML = `<div style="text-align:center;padding:40px"><div style="font-size:2rem">✅</div><div style="font-size:1.2rem;font-weight:700;margin:12px 0">${_sdlDrillScore}/${SDL_DRILLS.length} correct</div><button class="btn btn-primary" onclick="_sdlDrillIdx=0;_sdlDrillPicked=false;_sdlDrillScore=0;renderSdl()">Try Again</button></div>`;
    return;
  }
  const d = SDL_DRILLS[_sdlDrillIdx];
  if(st) st.textContent = `${_sdlDrillScore}/${_sdlDrillIdx} correct`;
  el.innerHTML = `<div style="max-width:540px;margin:0 auto"><div style="font-size:0.8rem;color:var(--muted);margin-bottom:8px">Q ${_sdlDrillIdx+1} of ${SDL_DRILLS.length}</div><div style="font-size:1.15rem;font-weight:700;margin-bottom:18px">${d.q}</div><div style="display:grid;gap:8px">${d.opts.map((o,i)=>`<button class="btn sdl-opt ${_sdlDrillPicked?(i===d.ans?'btn-success':(i===(_sdlDrillPicked===i?i:-1)?'btn-danger':'btn-outline')):'btn-outline'}" data-i="${i}" onclick="sdlPickOpt(${i})">${o}</button>`).join('')}</div></div>`;
}
function sdlPickOpt(i){
  if(_sdlDrillPicked) return;
  _sdlDrillPicked = true;
  recordActivity && recordActivity();
  incDailyCount && incDailyCount();
  const d = SDL_DRILLS[_sdlDrillIdx];
  const correct = i === d.ans;
  if(correct){ _sdlDrillScore++; addXp && addXp(2); }
  try{ correct ? sfx(sfxCorrect) : sfx(sfxWrong); }catch(e){}
  document.querySelectorAll('.sdl-opt').forEach(function(b){
    const bi = parseInt(b.getAttribute('data-i'));
    b.style.background = bi===d.ans ? 'var(--success,#4caf50)' : (bi===i&&!correct ? 'var(--error,#e53935)' : '');
    b.style.color = (bi===d.ans||(bi===i&&!correct)) ? '#fff' : '';
  });
  setTimeout(sdlNext, 900);
}
function sdlNext(){
  _sdlDrillIdx++;
  _sdlDrillPicked = false;
  renderSdl();
}
function _renderSdlTips(el){
  el.innerHTML = SDL_TIPS.map(t=>`<div class="card" style="padding:18px;margin-bottom:12px"><div style="font-weight:700;margin-bottom:8px">💊 ${t.title}</div><div style="line-height:1.6;color:var(--muted)">${t.body}</div></div>`).join('');
}

