// ── R756 NEW FEATURE: Lebanese Mouneh & Preserved Foods coach (mnh) ──
let _mnhTab = 'words';
let _mnhCat = 'pantry';
let _mnhDrillIdx = 0;
let _mnhDrillPicked = false;
let _mnhDrillScore = 0;

function openMnh(){
  bumpAchievementCounter && bumpAchievementCounter('mnh_open');
  const ov = document.getElementById('mnh-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _mnhDrillIdx = 0; _mnhDrillPicked = false; _mnhDrillScore = 0;
  setMnhTab('words');
}
function closeMnh(){ const ov=document.getElementById('mnh-overlay'); if(ov) ov.style.display='none'; }
function setMnhTab(t){
  _mnhTab = t;
  const bar = document.getElementById('mnh-tab-bar');
  if(bar){
    const tabs = [['words','🫙 Words'],['drill','🎯 Drill'],['tips','📖 Culture']];
    bar.innerHTML = tabs.map(([k,l])=>`<button class="cat-filter ${_mnhTab===k?'active':''}" onclick="setMnhTab('${k}')">${l}</button>`).join('');
  }
  renderMnh();
}
function renderMnh(){
  const el = document.getElementById('mnh-content');
  const st = document.getElementById('mnh-stats');
  if(!el) return;
  if(_mnhTab==='words') _renderMnhWords(el, st);
  else if(_mnhTab==='drill') _renderMnhDrill(el, st);
  else _renderMnhTips(el);
}
function _mnhSetCat(c){ _mnhCat=c; renderMnh(); }
function _renderMnhWords(el, st){
  const words = MNH_WORDS.filter(w=>w.cat===_mnhCat);
  if(st) st.textContent = `${words.length} words`;
  el.innerHTML = `<div style="display:flex;gap:6px;justify-content:center;flex-wrap:wrap;margin-bottom:14px">${MNH_CATS.map(c=>`<button class="cat-filter ${_mnhCat===c?'active':''}" onclick="_mnhSetCat('${c}')">${c}</button>`).join('')}</div>`
    + `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:10px">${words.map(w=>`<div class="card" style="padding:14px;cursor:pointer" onclick="speak('${w.tr}')"><div style="font-size:1.3rem;font-weight:700">${w.ar}</div><div style="color:var(--muted);font-size:0.9rem">${w.tr}</div><div style="font-size:0.85rem;margin-top:4px">${w.en}</div></div>`).join('')}</div>`;
}
function _renderMnhDrill(el, st){
  if(_mnhDrillIdx >= MNH_DRILLS.length){
    if(st) st.textContent = `${_mnhDrillScore}/${MNH_DRILLS.length} correct`;
    el.innerHTML = `<div style="text-align:center;padding:40px"><div style="font-size:2rem">✅</div><div style="font-size:1.2rem;font-weight:700;margin:12px 0">${_mnhDrillScore}/${MNH_DRILLS.length} correct</div><button class="btn btn-primary" onclick="_mnhDrillIdx=0;_mnhDrillPicked=false;_mnhDrillScore=0;renderMnh()">Try Again</button></div>`;
    return;
  }
  const d = MNH_DRILLS[_mnhDrillIdx];
  if(st) st.textContent = `${_mnhDrillScore}/${_mnhDrillIdx} correct`;
  el.innerHTML = `<div style="max-width:540px;margin:0 auto"><div style="font-size:0.8rem;color:var(--muted);margin-bottom:8px">Q ${_mnhDrillIdx+1} of ${MNH_DRILLS.length}</div><div style="font-size:1.15rem;font-weight:700;margin-bottom:18px">${d.q}</div><div style="display:grid;gap:8px">${d.opts.map((o,i)=>`<button class="btn mnh-opt btn-outline" data-i="${i}" onclick="mnhPickOpt(${i})">${o}</button>`).join('')}</div></div>`;
}
function mnhPickOpt(i){
  if(_mnhDrillPicked) return;
  _mnhDrillPicked = true;
  recordActivity && recordActivity();
  incDailyCount && incDailyCount();
  const d = MNH_DRILLS[_mnhDrillIdx];
  const correct = i === d.ans;
  if(correct){ _mnhDrillScore++; addXp && addXp(2); }
  try{ correct ? sfx(sfxCorrect) : sfx(sfxWrong); }catch(e){}
  document.querySelectorAll('.mnh-opt').forEach(function(b){
    const bi = parseInt(b.getAttribute('data-i'));
    b.style.background = bi===d.ans ? 'var(--success,#4caf50)' : (bi===i&&!correct ? 'var(--error,#e53935)' : '');
    b.style.color = (bi===d.ans||(bi===i&&!correct)) ? '#fff' : '';
  });
  setTimeout(mnhNext, 900);
}
function mnhNext(){
  _mnhDrillIdx++;
  _mnhDrillPicked = false;
  renderMnh();
}
function _renderMnhTips(el){
  el.innerHTML = MNH_TIPS.map(t=>`<div class="card" style="padding:18px;margin-bottom:12px"><div style="font-weight:700;margin-bottom:8px">🫙 ${t.title}</div><div style="line-height:1.6;color:var(--muted)">${t.body}</div></div>`).join('');
}

