// ============================================================
let _txiTab = 'words';
let _txiCat = 'vehicles';
let _txiDrillIdx = 0;
let _txiDrillShuf = [];
let _txiTipIdx = 0;

function openTxi(){
  bumpAchievementCounter && bumpAchievementCounter('txi_open');
  const ov = document.getElementById('txi-overlay'); if(!ov) return;
  ov.style.display = 'block';
  if(_txiDrillShuf.length === 0){
    _txiDrillShuf = TXI_DRILLS.map((_,i)=>i).sort(()=>Math.random()-0.5);
  }
  setTxiTab('words');
}
function closeTxi(){ const ov=document.getElementById('txi-overlay'); if(ov) ov.style.display='none'; }
function setTxiTab(t){
  _txiTab = t;
  const bar = document.getElementById('txi-tab-bar');
  if(bar){
    const tabs = [['words','📋 Words'],['drill','🎯 Drill'],['tips','📖 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_txiTab===k?'active':''}" onclick="setTxiTab('${k}')">${l}</button>`).join('');
  }
  renderTxi();
}
function renderTxi(){
  const el = document.getElementById('txi-content');
  const st = document.getElementById('txi-stats');
  if(!el) return;
  if(_txiTab === 'words') _renderTxiWords(el, st);
  else if(_txiTab === 'drill') _renderTxiDrill(el, st);
  else _renderTxiTips(el, st);
}
function _txiSetCat(c){
  _txiCat = c;
  renderTxi();
}
function _renderTxiWords(el, st){
  const cats = TXI_CATS;
  const words = TXI_WORDS.filter(w => w.cat === _txiCat);
  let html = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">';
  cats.forEach(c => {
    html += `<button class="cat-filter ${_txiCat===c?'active':''}" onclick="_txiSetCat('${c}')">${c}</button>`;
  });
  html += '</div><div style="display:grid;gap:8px">';
  words.forEach(w => {
    html += `<div class="card" style="padding:12px 16px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px">
      <div>
        <span style="font-size:1.1rem;font-weight:600">${w.tr}</span>
        <span style="color:var(--muted);margin-left:10px">${w.en}</span>
      </div>
      <div style="display:flex;align-items:center;gap:10px">
        <span style="font-family:serif;font-size:1.2rem;direction:rtl">${w.ar}</span>
        <button class="btn btn-sm btn-outline" onclick="speak('${w.ar.replace(/'/g,"\\'")}','ar')">🔊</button>
      </div>
    </div>`;
  });
  html += '</div>';
  el.innerHTML = html;
  if(st) st.textContent = words.length + ' words';
}
function _renderTxiDrill(el, st){
  const total = TXI_DRILLS.length;
  const idx = _txiDrillShuf[_txiDrillIdx % _txiDrillShuf.length];
  const d = TXI_DRILLS[idx];
  if(!d){ el.innerHTML='<p>No drills.</p>'; return; }
  let html = `<div class="card" style="padding:20px;margin-bottom:16px">
    <div style="font-size:1.1rem;font-weight:600;margin-bottom:16px">${d.q}</div>
    <div style="display:grid;gap:8px">`;
  d.opts.forEach((o,i) => {
    html += `<button class="btn btn-outline" id="txi-opt-${i}" onclick="txiPickOpt(${i})">${o}</button>`;
  });
  html += `</div></div>
  <div id="txi-feedback" style="min-height:36px;margin-bottom:12px"></div>
  <div style="display:flex;justify-content:flex-end">
    <button class="btn btn-primary" onclick="txiNext()">Next →</button>
  </div>`;
  el.innerHTML = html;
  if(st) st.textContent = (_txiDrillIdx % total + 1) + ' / ' + total;
}
function txiPickOpt(i){
  const idx = _txiDrillShuf[_txiDrillIdx % _txiDrillShuf.length];
  const d = TXI_DRILLS[idx];
  if(!d) return;
  const correct = (i === d.ans);
  const fb = document.getElementById('txi-feedback');
  for(let j=0;j<d.opts.length;j++){
    const b = document.getElementById('txi-opt-'+j);
    if(!b) continue;
    if(j === d.ans) b.style.background = 'var(--success,#22c55e)';
    else if(j === i && !correct) b.style.background = 'var(--danger,#ef4444)';
    b.disabled = true;
  }
  if(fb) fb.innerHTML = correct
    ? '<span style="color:var(--success,#22c55e);font-weight:600">✓ Correct!</span>'
    : `<span style="color:var(--danger,#ef4444);font-weight:600">✗ Answer: ${d.opts[d.ans]}</span>`;
  sfx && sfx(correct ? sfxCorrect : sfxWrong);
}
function txiNext(){
  _txiDrillIdx++;
  _renderTxiDrill(document.getElementById('txi-content'), document.getElementById('txi-stats'));
}
function _renderTxiTips(el, st){
  const tips = TXI_TIPS;
  let html = '<div style="display:grid;gap:14px">';
  tips.forEach((tip,i) => {
    html += `<div class="card" style="padding:18px">
      <div style="font-weight:700;margin-bottom:8px">${tip.title}</div>
      <div style="color:var(--muted);line-height:1.6">${tip.body}</div>
    </div>`;
  });
  html += '</div>';
  el.innerHTML = html;
  if(st) st.textContent = tips.length + ' notes';
}

