// ============================================================
let _gnrTab = 'words';
let _gnrCat = 'cuts';
let _gnrDrillIdx = 0;
let _gnrDrillShuf = [];

function openGnr(){
  bumpAchievementCounter && bumpAchievementCounter('gnr_open');
  const ov = document.getElementById('gnr-overlay'); if(!ov) return;
  ov.style.display = 'block';
  if(_gnrDrillShuf.length === 0){
    _gnrDrillShuf = GNR_DRILLS.map((_,i)=>i).sort(()=>Math.random()-0.5);
  }
  setGnrTab('words');
}
function closeGnr(){ const ov=document.getElementById('gnr-overlay'); if(ov) ov.style.display='none'; }
function setGnrTab(t){
  _gnrTab = t;
  const bar = document.getElementById('gnr-tab-bar');
  if(bar){
    const tabs = [['words','📋 Words'],['drill','🎯 Drill'],['tips','📖 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_gnrTab===k?'active':''}" onclick="setGnrTab('${k}')">${l}</button>`).join('');
  }
  renderGnr();
}
function renderGnr(){
  const el = document.getElementById('gnr-content');
  const st = document.getElementById('gnr-stats');
  if(!el) return;
  if(_gnrTab === 'words') _renderGnrWords(el, st);
  else if(_gnrTab === 'drill') _renderGnrDrill(el, st);
  else _renderGnrTips(el, st);
}
function _gnrSetCat(c){
  _gnrCat = c;
  renderGnr();
}
function _renderGnrWords(el, st){
  const cats = GNR_CATS;
  const words = GNR_WORDS.filter(w => w.cat === _gnrCat);
  let html = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">';
  cats.forEach(c => {
    html += `<button class="cat-filter ${_gnrCat===c?'active':''}" onclick="_gnrSetCat('${c}')">${c}</button>`;
  });
  html += '</div><div style="display:grid;gap:8px">';
  words.forEach(w => {
    html += `<div class="card" style="padding:12px 16px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px">
      <div>
        <span style="font-size:1.1rem;font-weight:600">${w.tr}</span>
        <span style="color:var(--muted);margin-left:10px">${w.en}</span>
      </div>
      <div style="display:flex;align-items:center;gap:10px">
        <span style="font-family:serif;font-size:1.2rem;direction:rtl">${w.ar}</span>
        <button class="btn btn-sm btn-outline" onclick="speak('${w.ar.replace(/'/g,"\\'")}','ar')">🔊</button>
      </div>
    </div>`;
  });
  html += '</div>';
  el.innerHTML = html;
  if(st) st.textContent = words.length + ' words';
}
function _renderGnrDrill(el, st){
  const total = GNR_DRILLS.length;
  const idx = _gnrDrillShuf[_gnrDrillIdx % _gnrDrillShuf.length];
  const d = GNR_DRILLS[idx];
  if(!d){ el.innerHTML='<p>No drills.</p>'; return; }
  let html = `<div class="card" style="padding:20px;margin-bottom:16px">
    <div style="font-size:1.1rem;font-weight:600;margin-bottom:16px">${d.q}</div>
    <div style="display:grid;gap:8px">`;
  d.opts.forEach((o,i) => {
    html += `<button class="btn btn-outline" id="gnr-opt-${i}" onclick="gnrPickOpt(${i})">${o}</button>`;
  });
  html += `</div></div>
  <div id="gnr-feedback" style="min-height:36px;margin-bottom:12px"></div>
  <div style="display:flex;justify-content:flex-end">
    <button class="btn btn-primary" onclick="gnrNext()">Next →</button>
  </div>`;
  el.innerHTML = html;
  if(st) st.textContent = (_gnrDrillIdx % total + 1) + ' / ' + total;
}
function gnrPickOpt(i){
  const idx = _gnrDrillShuf[_gnrDrillIdx % _gnrDrillShuf.length];
  const d = GNR_DRILLS[idx];
  if(!d) return;
  const correct = (i === d.ans);
  const fb = document.getElementById('gnr-feedback');
  for(let j=0;j<d.opts.length;j++){
    const b = document.getElementById('gnr-opt-'+j);
    if(!b) continue;
    if(j === d.ans) b.style.background = 'var(--success,#22c55e)';
    else if(j === i && !correct) b.style.background = 'var(--danger,#ef4444)';
    b.disabled = true;
  }
  if(fb) fb.innerHTML = correct
    ? '<span style="color:var(--success,#22c55e);font-weight:600">✓ Correct!</span>'
    : `<span style="color:var(--danger,#ef4444);font-weight:600">✗ Answer: ${d.opts[d.ans]}</span>`;
  sfx && sfx(correct ? sfxCorrect : sfxWrong);
}
function gnrNext(){
  _gnrDrillIdx++;
  _renderGnrDrill(document.getElementById('gnr-content'), document.getElementById('gnr-stats'));
}
function _renderGnrTips(el, st){
  const tips = GNR_TIPS;
  let html = '<div style="display:grid;gap:14px">';
  tips.forEach(tip => {
    html += `<div class="card" style="padding:18px">
      <div style="font-weight:700;margin-bottom:8px">${tip.title}</div>
      <div style="color:var(--muted);line-height:1.6">${tip.body}</div>
    </div>`;
  });
  html += '</div>';
  el.innerHTML = html;
  if(st) st.textContent = tips.length + ' notes';
}

