// ============================================================
// R768 — NEW FEATURE: Lebanese Thawra & Revolution Vocabulary (thw)
// ============================================================
let _thwTab = 'words';
let _thwCat = 'crowd';
let _thwDrillIdx = 0;
let _thwDrillShuf = [];

function openThw(){
  bumpAchievementCounter && bumpAchievementCounter('thw_open');
  const ov = document.getElementById('thw-overlay'); if(!ov) return;
  ov.style.display = 'block';
  if(_thwDrillShuf.length === 0){
    _thwDrillShuf = THW_DRILLS.map((_,i)=>i).sort(()=>Math.random()-0.5);
  }
  setThwTab('words');
}
function closeThw(){ const ov=document.getElementById('thw-overlay'); if(ov) ov.style.display='none'; }
function setThwTab(t){
  _thwTab = t;
  const bar = document.getElementById('thw-tab-bar');
  if(bar){
    const tabs = [['words','📋 Words'],['drill','🎯 Drill'],['tips','📖 History']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_thwTab===k?'active':''}" onclick="setThwTab('${k}')">${l}</button>`).join('');
  }
  renderThw();
}
function renderThw(){
  const el = document.getElementById('thw-content');
  const st = document.getElementById('thw-stats');
  if(!el) return;
  if(_thwTab === 'words') _renderThwWords(el, st);
  else if(_thwTab === 'drill') _renderThwDrill(el, st);
  else _renderThwTips(el, st);
}
function _thwSetCat(c){
  _thwCat = c;
  renderThw();
}
function _renderThwWords(el, st){
  const cats = THW_CATS;
  const words = THW_WORDS.filter(w => w.cat === _thwCat);
  let html = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">';
  cats.forEach(c => {
    html += `<button class="cat-filter ${_thwCat===c?'active':''}" onclick="_thwSetCat('${c}')">${c}</button>`;
  });
  html += '</div><div style="display:grid;gap:8px">';
  words.forEach(w => {
    html += `<div class="card" style="padding:12px 16px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px">
      <div>
        <span style="font-size:1.1rem;font-weight:600">${w.tr}</span>
        <span style="color:var(--muted);margin-left:10px">${w.en}</span>
      </div>
      <div style="display:flex;align-items:center;gap:10px">
        <span style="font-family:serif;font-size:1.2rem;direction:rtl">${w.ar}</span>
        <button class="btn btn-sm btn-outline" onclick="speak('${w.ar.replace(/'/g,"\\'")}','ar')">🔊</button>
      </div>
    </div>`;
  });
  html += '</div>';
  el.innerHTML = html;
  if(st) st.textContent = words.length + ' words';
}
function _renderThwDrill(el, st){
  const total = THW_DRILLS.length;
  const idx = _thwDrillShuf[_thwDrillIdx % _thwDrillShuf.length];
  const d = THW_DRILLS[idx];
  if(!d){ el.innerHTML='<p>No drills.</p>'; return; }
  let html = `<div class="card" style="padding:20px;margin-bottom:16px">
    <div style="font-size:1.1rem;font-weight:600;margin-bottom:16px">${d.q}</div>
    <div style="display:grid;gap:8px">`;
  d.opts.forEach((o,i) => {
    html += `<button class="btn btn-outline" id="thw-opt-${i}" onclick="thwPickOpt(${i})">${o}</button>`;
  });
  html += `</div></div>
  <div id="thw-feedback" style="min-height:36px;margin-bottom:12px"></div>
  <div style="display:flex;justify-content:flex-end">
    <button class="btn btn-primary" onclick="thwNext()">Next →</button>
  </div>`;
  el.innerHTML = html;
  if(st) st.textContent = (_thwDrillIdx % total + 1) + ' / ' + total;
}
function thwPickOpt(i){
  const idx = _thwDrillShuf[_thwDrillIdx % _thwDrillShuf.length];
  const d = THW_DRILLS[idx];
  if(!d) return;
  const correct = (i === d.ans);
  const fb = document.getElementById('thw-feedback');
  for(let j=0;j<d.opts.length;j++){
    const b = document.getElementById('thw-opt-'+j);
    if(!b) continue;
    if(j === d.ans) b.style.background = 'var(--success,#22c55e)';
    else if(j === i && !correct) b.style.background = 'var(--danger,#ef4444)';
    b.disabled = true;
  }
  if(fb) fb.innerHTML = correct
    ? '<span style="color:var(--success,#22c55e);font-weight:600">✓ Correct!</span>'
    : `<span style="color:var(--danger,#ef4444);font-weight:600">✗ Answer: ${d.opts[d.ans]}</span>`;
  sfx && sfx(correct ? sfxCorrect : sfxWrong);
}
function thwNext(){
  _thwDrillIdx++;
  _renderThwDrill(document.getElementById('thw-content'), document.getElementById('thw-stats'));
}
function _renderThwTips(el, st){
  const tips = THW_TIPS;
  let html = '<div style="display:grid;gap:14px">';
  tips.forEach(tip => {
    html += `<div class="card" style="padding:18px">
      <div style="font-weight:700;margin-bottom:8px">${tip.title}</div>
      <div style="color:var(--muted);line-height:1.6">${tip.body}</div>
    </div>`;
  });
  html += '</div>';
  el.innerHTML = html;
  if(st) st.textContent = tips.length + ' notes';
}

// self-register
(function(){
  if(typeof TOPICS_CATEGORIES==='undefined') return;
  if(TOPICS_CATEGORIES.some(function(x){return x.id==='thw';})) return;
  TOPICS_CATEGORIES.push({id:'thw',label:'✊ Thawra & Revolution',fn:'openThw',items:THW_WORDS});
})();

