// ── R771 NEW FEATURE — Lebanese Barbershop & Hair Salon (brb)
let _brbTab = 'words';
let _brbCat = 'barber';
let _brbDrillIdx = 0;
let _brbDrillAnswered = false;
let _brbDrillScore = {correct:0, total:0};

function openBrb(){
  bumpAchievementCounter && bumpAchievementCounter('brb_open');
  const ov = document.getElementById('brb-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setBrbTab('words');
}
function closeBrb(){ const ov=document.getElementById('brb-overlay'); if(ov) ov.style.display='none'; }
function setBrbTab(t){
  _brbTab = t;
  const bar = document.getElementById('brb-tab-bar');
  if(bar){
    const tabs = [['words','💈 Words'],['drill','🎯 Drill'],['tips','📖 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_brbTab===k?'active':''}" onclick="setBrbTab('${k}')">${l}</button>`).join('');
  }
  renderBrb();
}
function renderBrb(){
  const el = document.getElementById('brb-content');
  const st = document.getElementById('brb-stats');
  if(!el) return;
  if(_brbTab === 'words') _renderBrbWords(el, st);
  else if(_brbTab === 'drill') _renderBrbDrill(el, st);
  else _renderBrbTips(el, st);
}
function _brbSetCat(c){ _brbCat = c; renderBrb(); }
function _renderBrbWords(el, st){
  const cats = BRB_CATS;
  const words = (typeof BRB_WORDS !== 'undefined' ? BRB_WORDS : []).filter(w => _brbCat === 'all' || w.cat === _brbCat);
  if(st) st.textContent = words.length + ' words';
  const catBar = cats.map(c => `<button class="cat-filter ${_brbCat===c?'active':''}" onclick="_brbSetCat('${c}')">${c}</button>`).join('');
  el.innerHTML = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">${catBar}<button class="cat-filter ${_brbCat==='all'?'active':''}" onclick="_brbSetCat('all')">all</button></div>
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">
  ${words.map(w=>`<div class="card" style="padding:12px">
    <div style="font-size:1.1rem;font-weight:700">${w.tr}</div>
    <div style="color:var(--muted);font-size:0.9rem">${w.en}</div>
    <div style="font-size:1.2rem;text-align:right;margin-top:4px">${w.ar}</div>
    <button class="btn btn-outline" style="margin-top:6px;font-size:0.8rem" onclick="speak('${w.tr}')">🔊</button>
  </div>`).join('')}
  </div>`;
}
function _renderBrbDrill(el, st){
  const drills = typeof BRB_DRILLS !== 'undefined' ? BRB_DRILLS : [];
  if(!drills.length){ el.innerHTML='<p>No drills.</p>'; return; }
  const d = drills[_brbDrillIdx % drills.length];
  if(st) st.textContent = `${_brbDrillScore.correct}/${_brbDrillScore.total} · Q${(_brbDrillIdx%drills.length)+1}/${drills.length}`;
  const opts = d.opts.map((o,i)=>{
    let bg = '';
    if(_brbDrillAnswered){ bg = (i===d.ans) ? 'background:var(--success,#22c55e);color:#fff;' : (i===_brbPickedIdx ? 'background:var(--danger,#ef4444);color:#fff;' : ''); }
    return `<button class="btn btn-outline" style="width:100%;margin-bottom:8px;text-align:left;${bg}" onclick="brbPickOpt(${i})">${o}</button>`;
  }).join('');
  el.innerHTML = `<div class="card" style="padding:18px;margin-bottom:14px"><div style="font-size:1.05rem;font-weight:600;margin-bottom:14px">${d.q}</div>${opts}</div>
  <div style="text-align:center"><button class="btn btn-outline" onclick="brbNext()">Next ▶</button></div>`;
}
let _brbPickedIdx = null;
function brbPickOpt(i){
  if(_brbDrillAnswered) return;
  _brbPickedIdx = i;
  _brbDrillAnswered = true;
  const drills = typeof BRB_DRILLS !== 'undefined' ? BRB_DRILLS : [];
  const d = drills[_brbDrillIdx % drills.length];
  if(i === d.ans){
    _brbDrillScore.correct++;
    recordActivity && recordActivity();
    incDailyCount && incDailyCount();
    addXp && addXp((typeof XP_PER_RATING !== 'undefined' && XP_PER_RATING[2]) || 10);
  }
  _brbDrillScore.total++;
  renderBrb();
}
function brbNext(){
  _brbDrillIdx++;
  _brbDrillAnswered = false;
  _brbPickedIdx = null;
  renderBrb();
}
function _renderBrbTips(el, st){
  const tips = typeof BRB_TIPS !== 'undefined' ? BRB_TIPS : [];
  if(st) st.textContent = tips.length + ' stories';
  el.innerHTML = tips.map(t=>`<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="font-weight:700;margin-bottom:8px">💈 ${t.title}</div>
    <div style="color:var(--muted);line-height:1.6;font-size:0.92rem">${t.body}</div>
  </div>`).join('');
}
