// ── R774 NEW FEATURE — Lebanese Bureaucracy & Red Tape (bur)
let _burTab = 'words';
let _burCat = 'offices';
let _burDrillIdx = 0;
let _burDrillAnswered = false;
let _burPickedIdx = null;
let _burDrillScore = {correct:0, total:0};

function openBur(){
  bumpAchievementCounter && bumpAchievementCounter('bur_open');
  const ov = document.getElementById('bur-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setBurTab('words');
}
function closeBur(){ const ov=document.getElementById('bur-overlay'); if(ov) ov.style.display='none'; }
function setBurTab(t){
  _burTab = t;
  const bar = document.getElementById('bur-tab-bar');
  if(bar){
    const tabs = [['words','📄 Words'],['drill','🎯 Drill'],['tips','📖 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_burTab===k?'active':''}" onclick="setBurTab('${k}')">${l}</button>`).join('');
  }
  renderBur();
}
function renderBur(){
  const el = document.getElementById('bur-content');
  const st = document.getElementById('bur-stats');
  if(!el) return;
  if(_burTab === 'words') _renderBurWords(el, st);
  else if(_burTab === 'drill') _renderBurDrill(el, st);
  else _renderBurTips(el, st);
}
function _burSetCat(c){ _burCat = c; renderBur(); }
function _renderBurWords(el, st){
  const cats = BUR_CATS;
  const words = (typeof BUR_WORDS !== 'undefined' ? BUR_WORDS : []).filter(w => _burCat === 'all' || w.cat === _burCat);
  if(st) st.textContent = words.length + ' words';
  const catBar = cats.map(c => `<button class="cat-filter ${_burCat===c?'active':''}" onclick="_burSetCat('${c}')">${c}</button>`).join('');
  el.innerHTML = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">${catBar}<button class="cat-filter ${_burCat==='all'?'active':''}" onclick="_burSetCat('all')">all</button></div>
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">
  ${words.map(w=>`<div class="card" style="padding:12px">
    <div style="font-size:1.1rem;font-weight:700">${w.tr}</div>
    <div style="color:var(--muted);font-size:0.9rem">${w.en}</div>
    <div style="font-size:1.2rem;text-align:right;margin-top:4px">${w.ar}</div>
    <button class="btn btn-outline" style="margin-top:6px;font-size:0.8rem" onclick="speak('${w.tr}')">🔊</button>
  </div>`).join('')}
  </div>`;
}
function _renderBurDrill(el, st){
  const drills = typeof BUR_DRILLS !== 'undefined' ? BUR_DRILLS : [];
  if(!drills.length){ el.innerHTML='<p>No drills.</p>'; return; }
  const d = drills[_burDrillIdx % drills.length];
  if(st) st.textContent = `${_burDrillScore.correct}/${_burDrillScore.total} · Q${(_burDrillIdx%drills.length)+1}/${drills.length}`;
  const opts = d.opts.map((o,i)=>{
    let bg = '';
    if(_burDrillAnswered){ bg = (i===d.ans) ? 'background:var(--success,#22c55e);color:#fff;' : (i===_burPickedIdx ? 'background:var(--danger,#ef4444);color:#fff;' : ''); }
    return `<button class="btn btn-outline" style="width:100%;margin-bottom:8px;text-align:left;${bg}" onclick="burPickOpt(${i})">${o}</button>`;
  }).join('');
  el.innerHTML = `<div class="card" style="padding:18px;margin-bottom:14px"><div style="font-size:1.05rem;font-weight:600;margin-bottom:14px">${d.q}</div>${opts}</div>
  <div style="text-align:center"><button class="btn btn-outline" onclick="burNext()">Next ▶</button></div>`;
}
function burPickOpt(i){
  if(_burDrillAnswered) return;
  _burPickedIdx = i;
  _burDrillAnswered = true;
  const drills = typeof BUR_DRILLS !== 'undefined' ? BUR_DRILLS : [];
  const d = drills[_burDrillIdx % drills.length];
  if(i === d.ans){
    _burDrillScore.correct++;
    recordActivity && recordActivity();
    incDailyCount && incDailyCount();
    addXp && addXp((typeof XP_PER_RATING !== 'undefined' && XP_PER_RATING[2]) || 10);
  }
  _burDrillScore.total++;
  renderBur();
}
function burNext(){
  _burDrillIdx++;
  _burDrillAnswered = false;
  _burPickedIdx = null;
  renderBur();
}
function _renderBurTips(el, st){
  const tips = typeof BUR_TIPS !== 'undefined' ? BUR_TIPS : [];
  if(st) st.textContent = tips.length + ' stories';
  el.innerHTML = tips.map(t=>`<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="font-weight:700;margin-bottom:8px">📋 ${t.title}</div>
    <div style="color:var(--muted);line-height:1.6;font-size:0.92rem">${t.body}</div>
  </div>`).join('');
}
