function drySetCat(c){ _dryCat=c; renderDry(); }
function _renderDryDrill(el, st){
  const drills = typeof DRY_DRILLS!=='undefined' ? DRY_DRILLS : [];
  if(!drills.length){ el.innerHTML='<p>No drills.</p>'; return; }
  if(_dryDrillIdx >= drills.length){
    if(st) st.textContent='done!';
    el.innerHTML=`<div class="card" style="padding:20px;text-align:center">
      <div style="font-size:2rem;margin-bottom:10px">🧀</div>
      <div style="font-weight:700;margin-bottom:8px">All ${drills.length} drills done!</div>
      <div style="color:var(--muted);margin-bottom:14px">Score: ${_dryDrillScore.correct}/${_dryDrillScore.total}</div>
      <button class="btn" onclick="_dryDrillIdx=0;_dryDrillAnswered=false;_dryPickedIdx=null;_dryDrillScore={correct:0,total:0};renderDry()">🔄 Restart</button>
    </div>`;
    return;
  }
  const d = drills[_dryDrillIdx % drills.length];
  if(st) st.textContent = `${_dryDrillIdx+1}/${drills.length} · ${_dryDrillScore.correct}✓`;
  let h = `<div class="card" style="padding:20px">
    <div style="font-size:0.8rem;color:var(--muted);margin-bottom:8px">Dairy Drill ${_dryDrillIdx+1}/${drills.length}</div>
    <div style="font-size:1.15rem;font-weight:700;margin-bottom:16px">${d.q}</div>
    <div style="display:grid;gap:8px">`;
  d.opts.forEach((opt,i)=>{
    let style='';
    if(_dryDrillAnswered){
      if(i===d.ans) style='background:var(--success,#2d6a4f);color:#fff;border-color:transparent';
      else if(i===_dryPickedIdx&&i!==d.ans) style='background:var(--danger,#c1121f);color:#fff;border-color:transparent';
    }
    h += `<button class="btn btn-outline" style="text-align:left;${style}" onclick="dryPickOpt(${i})" ${_dryDrillAnswered?'disabled':''}>${opt}</button>`;
  });
  h += `</div>`;
  if(_dryDrillAnswered){
    h += `<div style="margin-top:12px;padding:10px;background:var(--card-border);border-radius:8px;font-size:0.9rem;color:var(--muted)">${d.exp}</div>`;
    h += `<button class="btn btn-primary" style="margin-top:12px" onclick="dryNext()">Next →</button>`;
  }
  h += `</div>`;
  el.innerHTML = h;
}
function dryPickOpt(i){
  if(_dryDrillAnswered) return;
  _dryPickedIdx = i;
  _dryDrillAnswered = true;
  _dryDrillScore.total++;
  const d = DRY_DRILLS[_dryDrillIdx % DRY_DRILLS.length];
  if(i === d.ans){
    _dryDrillScore.correct++;
    try{ sfx('correct'); }catch(e){}
    recordActivity && recordActivity();
    incDailyCount && incDailyCount();
    addXp && addXp(XP_PER_RATING ? XP_PER_RATING[2]||10 : 10);
  } else {
    try{ sfx('wrong'); }catch(e){}
  }
  renderDry();
}
function dryNext(){
  _dryDrillIdx++;
  _dryDrillAnswered = false;
  _dryPickedIdx = null;
  renderDry();
}
function _renderDryTips(el, st){
  const tips = typeof DRY_TIPS!=='undefined' ? DRY_TIPS : [];
  if(st) st.textContent = tips.length + ' tips';
  el.innerHTML = `<div style="display:grid;gap:12px">${tips.map((t,i)=>`<div class="card" style="padding:16px"><div style="font-size:0.8rem;color:var(--muted);margin-bottom:6px">Tip ${i+1}</div><div style="font-size:0.93rem;line-height:1.6">${t}</div></div>`).join('')}</div>`;
}

