  try{ thwPickOpt = _wrap821(thwPickOpt, function(i){ var idx=_thwDrillShuf[_thwDrillIdx%_thwDrillShuf.length]; var d=THW_DRILLS[idx]; return !!(d && i===d.ans); }, true); }catch(e){}
  // wrk/ntr — use .correct field, already have incDailyCount
  try{ wrkPickOpt = _wrap821(wrkPickOpt, function(i){ var d=WRK_DRILLS[_wrkDrillIdx%WRK_DRILLS.length]; return !!(d && i===d.correct); }, false); }catch(e){}
  try{ ntrPickOpt = _wrap821(ntrPickOpt, function(i){ var d=NTR_DRILLS[_ntrDrillIdx%NTR_DRILLS.length]; return !!(d && i===d.correct); }, false); }catch(e){}
  // wst/trf/nlf/pwr/mno — already have incDailyCount
  try{ wstPickOpt = _wrap821(wstPickOpt, function(i){ var d=WST_DRILLS[_wstDrillIdx]; return !!(d && i===d.ans); }, false); }catch(e){}
  try{ trfPickOpt = _wrap821(trfPickOpt, function(i){ var d=TRF_DRILLS[_trfDrillIdx]; return !!(d && i===d.ans); }, false); }catch(e){}
  try{ nlfPickOpt = _wrap821(nlfPickOpt, function(i){ var d=NLF_DRILLS[_nlfDrillIdx]; return !!(d && i===d.ans); }, false); }catch(e){}
  try{ pwrPickOpt = _wrap821(pwrPickOpt, function(i){ var d=PWR_DRILLS[_pwrDrillIdx]; return !!(d && i===d.ans); }, false); }catch(e){}
  try{ mnoPickOpt = _wrap821(mnoPickOpt, function(i){ var d=MNO_DRILLS[_mnoDrillIdx]; return !!(d && i===d.ans); }, false); }catch(e){}
  // blg — completely bare (R812 added sfx, this adds tracking)
