// ── R824 BUG FIX — add missing incDailyCount/addXp to 8 answer functions ─────
// hstAnswer: fully missing. dnt/eid/imm/ins: missing incDailyCount+addXp.
// nzr/hum/chk (first arg = correct): missing incDailyCount.
(function(){
  var _xp = function(){ addXp && addXp(XP_PER_RATING ? XP_PER_RATING[2]||10 : 10); };

  // hstAnswer: full tracking — peek at _hstOptions[idx].correct before call
  try{
    if(typeof hstAnswer==='function' && !hstAnswer.__r824Fixed){
      var _hstOrig = hstAnswer;
      hstAnswer = function(idx){
        var correct = false;
        try{ correct = !!(typeof _hstOptions!=='undefined' && _hstOptions[idx] && _hstOptions[idx].correct); }catch(e){}
        var result = _hstOrig.apply(this, arguments);
        try{ if(correct){ recordActivity && recordActivity(); incDailyCount && incDailyCount(); _xp(); } }catch(e){}
        return result;
      };
      hstAnswer.__r824Fixed = true;
    }
  }catch(e){}

  // dnt/eid/imm/ins: already have recordActivity — add incDailyCount + addXp
  function _wrapDailyXp824(fn, getDrill, ansField){
    if(!fn || fn.__r824Fixed) return fn;
    var w = function(i){
      var result = fn.apply(this, arguments);
      try{
        var d = getDrill();
        if(d && i===d[ansField]){ incDailyCount && incDailyCount(); _xp(); }
      }catch(e){}
      return result;
    };
    w.__r824Fixed = true;
    return w;
  }
  try{ dntPickOpt = _wrapDailyXp824(dntPickOpt, function(){ return DNT_DRILLS[_dntDrillIdx%DNT_DRILLS.length]; }, 'a'); }catch(e){}
  try{ eidPickOpt = _wrapDailyXp824(eidPickOpt, function(){ return EID_DRILLS[_eidDrillIdx%EID_DRILLS.length]; }, 'a'); }catch(e){}
  try{ immPickOpt = _wrapDailyXp824(immPickOpt, function(){ return IMM_DRILLS[_immDrillIdx%IMM_DRILLS.length]; }, 'a'); }catch(e){}
  try{ insPickOpt = _wrapDailyXp824(insPickOpt, function(){ return INS_DRILLS[_insDrillIdx%INS_DRILLS.length]; }, 'a'); }catch(e){}

  // nzr/hum/chk: first arg IS the correct boolean — add incDailyCount only
  function _wrapIncDaily824(fn){
    if(!fn || fn.__r824Fixed) return fn;
    var w = function(correct){
      var result = fn.apply(this, arguments);
      try{ if(correct) incDailyCount && incDailyCount(); }catch(e){}
      return result;
    };
    w.__r824Fixed = true;
    return w;
  }
  try{ nzrPickOpt = _wrapIncDaily824(nzrPickOpt); }catch(e){}
  try{ humPickOpt = _wrapIncDaily824(humPickOpt); }catch(e){}
  try{ chkPickOpt = _wrapIncDaily824(chkPickOpt); }catch(e){}
})();

