let _qhwTab = 'browse';
let _qhwCat = 'all';
let _qhwDrillIdx = 0;
let _qhwDrillAnswered = false;
let _qhwPickedIdx = null;
let _qhwDrillScore = { correct: 0, total: 0 };

function openQhw(){
  bumpAchievementCounter && bumpAchievementCounter('qhw_open');
  const ov = document.getElementById('qhw-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setQhwTab('browse');
}
function closeQhw(){ const ov=document.getElementById('qhw-overlay'); if(ov) ov.style.display='none'; }
function setQhwTab(t){
  _qhwTab = t;
  const bar = document.getElementById('qhw-tab-bar');
  if(bar){
    const tabs = [['browse','☕ Browse'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_qhwTab===k?'active':''}" onclick="setQhwTab('${k}')">${l}</button>`).join('');
  }
  renderQhw();
}
function renderQhw(){
  const el = document.getElementById('qhw-content');
  const st = document.getElementById('qhw-stats');
  if(!el) return;
  if(_qhwTab === 'browse') _renderQhwBrowse(el, st);
  else if(_qhwTab === 'drill') _renderQhwDrill(el, st);
  else _renderQhwTips(el, st);
}
function _renderQhwBrowse(el, st){
  const cats = ['all'].concat(QHW_CATS);
  const catBar = cats.map(c => `<button class="cat-filter ${_qhwCat===c?'active':''}" onclick="qhwSetCat('${c}')">${c==='all'?'All':c}</button>`).join('');
  const words = (typeof QHW_WORDS !== 'undefined') ? (_qhwCat === 'all' ? QHW_WORDS : QHW_WORDS.filter(w=>w.cat===_qhwCat)) : [];
  if(st) st.textContent = words.length + ' expressions';
  el.innerHTML = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">${catBar}</div>` +
    `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:10px">` +
    words.map(w=>`<div class="card" style="padding:14px;cursor:pointer" onclick="speak&&speak('${w.a.replace(/'/g,"\\'")}','ar')">
      <div style="font-size:1.3rem;font-weight:700;color:var(--accent)">${w.a}</div>
      <div style="color:var(--muted);font-size:0.9rem">${w.tr}</div>
      <div style="margin-top:4px;font-size:0.85rem">${w.en}</div>
    </div>`).join('') + '</div>';
}
function qhwSetCat(c){ _qhwCat = c; renderQhw(); }
function _renderQhwDrill(el, st){
  if(st) st.textContent = `${_qhwDrillScore.correct}/${_qhwDrillScore.total} correct`;
  if(typeof QHW_DRILLS === 'undefined' || !QHW_DRILLS.length){ el.innerHTML='<p>No drills.</p>'; return; }
  const d = QHW_DRILLS[_qhwDrillIdx % QHW_DRILLS.length];
  if(_qhwDrillAnswered){
    el.innerHTML = `<div class="card" style="padding:24px;max-width:540px;margin:0 auto;text-align:center">
      <div style="font-size:1rem;margin-bottom:12px">${d.q}</div>
      <div style="color:var(--success,#22c55e);font-weight:700;margin-bottom:8px">✓ ${d.opts[d.ans]}</div>
      <div style="color:var(--muted);font-size:0.85rem;margin-bottom:16px">${d.exp}</div>
      <button class="btn" onclick="qhwNext()">Next ➜</button>
    </div>`;
    return;
  }
  el.innerHTML = `<div class="card" style="padding:24px;max-width:540px;margin:0 auto">
    <div style="font-size:1rem;font-weight:600;margin-bottom:16px;text-align:center">${d.q}</div>
    ${d.opts.map((o,i)=>`<button class="btn btn-outline" style="display:block;width:100%;margin-bottom:8px;text-align:left" onclick="qhwPickOpt(${i})">${o}</button>`).join('')}
  </div>`;
}
function qhwPickOpt(i){
  if(_qhwDrillAnswered) return;
  const d = (typeof QHW_DRILLS !== 'undefined') ? QHW_DRILLS[_qhwDrillIdx % QHW_DRILLS.length] : null;
  if(!d) return;
  _qhwPickedIdx = i;
  _qhwDrillAnswered = true;
  _qhwDrillScore.total++;
  if(i === d.ans){
    _qhwDrillScore.correct++;
    try{ sfx('correct'); }catch(e){}
    recordActivity && recordActivity();
    incDailyCount && incDailyCount();
    addXp && addXp(XP_PER_RATING ? XP_PER_RATING[2]||10 : 10);
  } else {
    try{ sfx('wrong'); }catch(e){}
  }
  renderQhw();
}
function qhwNext(){
  _qhwDrillIdx++;
  _qhwDrillAnswered = false;
  _qhwPickedIdx = null;
  renderQhw();
}
function _renderQhwTips(el, st){
  if(st) st.textContent = QHW_TIPS.length + ' tips';
  el.innerHTML = (typeof QHW_TIPS !== 'undefined') ? QHW_TIPS.map((t,i)=>`<div class="card" style="padding:16px;margin-bottom:10px"><span style="font-weight:700;color:var(--accent)">${i+1}.</span> ${t}</div>`).join('') : '';
}
(function(){
  if(typeof TOPICS_CATEGORIES !== 'undefined'){
    var found = false;
    for(var ci=0;ci<TOPICS_CATEGORIES.length;ci++){
      if(TOPICS_CATEGORIES[ci].id === 'qhw'){ found = true; break; }
    }
    if(!found) TOPICS_CATEGORIES.push({ id:'qhw', label:'☕ Coffee Culture', open:'openQhw' });
  }
})();

