// ── R857 BUG FIX: Normalize TOPICS_CATEGORIES entries lacking items[] ────────
// renderTopics() calls cat.items.filter() — crashes for ~40 coaches that pushed
// flat objects {id,label,open/fn} without an items array (srk/dlr/psh/wtr/nlt/
// sfs/trk/vil + ~35 earlier: hrb/cft/sch/mnt/dgt/hme/veg/bhr/zwr/htl/fml/wld/
// stf/spg/msc/cntv/clmt/art/jwl/law/ast + qhw/ntf + nwsp/sprt/unv + others).
// Fix: collect broken entries, normalize into coaches-ext category, remove them.
(function(){
  if(window.__r857Fix) return;
  window.__r857Fix = true;
  if(typeof TOPICS_CATEGORIES === 'undefined') return;
  var broken = [];
  var toRemove = [];
  for(var i=0;i<TOPICS_CATEGORIES.length;i++){
    var cat = TOPICS_CATEGORIES[i];
    if(!Array.isArray(cat.items)) toRemove.push(i);
  }
  // Collect broken entries (iterate in reverse to splice safely)
  for(var j=toRemove.length-1;j>=0;j--){
    broken.unshift(TOPICS_CATEGORIES.splice(toRemove[j],1)[0]);
  }
  if(!broken.length) return;
  // Find or create coaches-ext category
  var ext = null;
  for(var k=0;k<TOPICS_CATEGORIES.length;k++){
    if(TOPICS_CATEGORIES[k].id==='coaches-ext'){ext=TOPICS_CATEGORIES[k];break;}
  }
  if(!ext){
    ext = {id:'coaches-ext',title:'🗂️ Topic Coaches',items:[]};
    TOPICS_CATEGORIES.push(ext);
  }
  // Normalize each broken entry into {label,fn,desc}
  for(var m=0;m<broken.length;m++){
    var b = broken[m];
    var fnStr = null;
    if(typeof b.fn==='string') fnStr = b.fn;
    else if(typeof b.open==='string') fnStr = b.open;
    else if(typeof b.open==='function') fnStr = b.open.name||null;
    if(!fnStr) continue;
    var label = b.label||b.title||fnStr;
    var dup = false;
    for(var n=0;n<ext.items.length;n++){
      if(ext.items[n].fn===fnStr){dup=true;break;}
    }
    if(!dup) ext.items.push({label:label,fn:fnStr,desc:''});
  }
  // Also patch openTopics to re-run normalization in case future coaches push late
  if(typeof openTopics==='function'){
    var _origOpenTopics = openTopics;
    openTopics = function(){
      if(typeof TOPICS_CATEGORIES!=='undefined'){
        var extCat=null;
        for(var ii=TOPICS_CATEGORIES.length-1;ii>=0;ii--){
          var cc=TOPICS_CATEGORIES[ii];
          if(cc.id==='coaches-ext'){extCat=cc;continue;}
          if(!Array.isArray(cc.items)){
            var fn2=null;
            if(typeof cc.fn==='string') fn2=cc.fn;
            else if(typeof cc.open==='string') fn2=cc.open;
            else if(typeof cc.open==='function') fn2=cc.open.name||null;
            if(fn2){
              if(!extCat){extCat={id:'coaches-ext',title:'🗂️ Topic Coaches',items:[]};TOPICS_CATEGORIES.push(extCat);}
              var dup2=false;
              for(var jj=0;jj<extCat.items.length;jj++){if(extCat.items[jj].fn===fn2){dup2=true;break;}}
              if(!dup2) extCat.items.push({label:cc.label||cc.title||fn2,fn:fn2,desc:''});
            }
            TOPICS_CATEGORIES.splice(ii,1);
          }
        }
      }
      return _origOpenTopics.apply(this,arguments);
    };
    window.__r857OpenTopicsPatched = true;
  }
})();

