// ── R863 BUG FIX: Fix TOPICS_CATEGORIES entries with WORDS arrays as items ───
// ~20 coaches (nwsp/sprt/unv/elc/mig/bty/cns/bkf/grg/wyn/bsp/sdl/sat/mnh/txi/
// gnr/mec/thw/brb/bur/cin + more) push {fn:'openX', items: WORDS_ARRAY} where
// each item has {a,tr,en,cat} but renderTopics expects {label,fn,desc}.
// Result: every word entry renders as a button with label="undefined" and
// onclick="window.undefined()". Fix: replace WORDS-array items with one proper
// item {label,fn,desc} derived from the category's own fn/label fields.
(function(){
  if(window.__r863ItemsFix) return;
  window.__r863ItemsFix = true;
  if(typeof TOPICS_CATEGORIES === 'undefined') return;
  for(var i=0;i<TOPICS_CATEGORIES.length;i++){
    var cat = TOPICS_CATEGORIES[i];
    if(!Array.isArray(cat.items) || cat.items.length === 0) continue;
    // Detect WORDS array: first item has 'a' (Arabic) + 'tr' (transliteration) but no 'fn'
    var first = cat.items[0];
    if(first && typeof first.a !== 'undefined' && typeof first.tr !== 'undefined' && typeof first.fn === 'undefined'){
      // This is a WORDS array masquerading as items
      var fnStr = (typeof cat.fn === 'string') ? cat.fn : null;
      var label = cat.label || cat.title || fnStr || '?';
      if(fnStr){
        cat.items = [{ label: label, fn: fnStr, desc: '' }];
      } else {
        // No fn either — strip to avoid undefined onclick
        cat.items = [];
      }
    }
  }
})();

// ── R863b FIX: R863 missed WORDS arrays using 'ar' field instead of 'a' ──────
(function(){
  if(window.__r863bItemsFix) return;
  window.__r863bItemsFix = true;
  if(typeof TOPICS_CATEGORIES === 'undefined') return;
  for(var i=0;i<TOPICS_CATEGORIES.length;i++){
    var cat = TOPICS_CATEGORIES[i];
    if(!Array.isArray(cat.items) || cat.items.length === 0) continue;
    var first = cat.items[0];
    // Detect 'ar'-keyed WORDS array (e.g. NWSP_WORDS, SPRT_WORDS format)
    if(first && typeof first.ar !== 'undefined' && typeof first.tr !== 'undefined' && typeof first.fn === 'undefined'){
      var fnStr = (typeof cat.fn === 'string') ? cat.fn : null;
      var label = cat.label || cat.title || fnStr || '?';
      if(fnStr) cat.items = [{ label: label, fn: fnStr, desc: '' }];
      else cat.items = [];
    }
  }
})();

