// R879 — WhatsApp & Digital Communication Culture coach (wha)
let _whaTab = 'browse'; let _whaCat = 'all'; let _whaDrillIdx = 0;
let _whaDrillAnswered = false; let _whaPickedIdx = null;
let _whaDrillScore = { correct: 0, total: 0 };

function openWha() {
  bumpAchievementCounter && bumpAchievementCounter('wha_open');
  const ov = document.getElementById('wha-overlay'); if (!ov) return;
  ov.style.display = 'block';
  setWhaTab('browse');
}
function closeWha() { const ov = document.getElementById('wha-overlay'); if (ov) ov.style.display = 'none'; }
function setWhaTab(t) {
  _whaTab = t;
  const bar = document.getElementById('wha-tab-bar');
  if (bar) {
    const tabs = [['browse','📖 Browse'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_whaTab===k?'active':''}" onclick="setWhaTab('${k}')">${l}</button>`).join('');
  }
  renderWha();
}
function renderWha() {
  const el = document.getElementById('wha-content'); if (!el) return;
  const st = document.getElementById('wha-stats');
  if (st) st.textContent = `${_whaDrillScore.correct}/${_whaDrillScore.total} correct`;
  if (_whaTab === 'browse') _renderWhaBrowse(el);
  else if (_whaTab === 'drill') _renderWhaDrill(el);
  else _renderWhaTips(el);
}
function _renderWhaBrowse(el) {
  const cats = ['all', ...WHA_CATS];
  const words = _whaCat === 'all' ? WHA_WORDS : WHA_WORDS.filter(w => w.cat === _whaCat);
  el.innerHTML = `<div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin-bottom:14px">${cats.map(c=>`<button class="cat-filter ${_whaCat===c?'active':''}" onclick="whaSetCat('${c}')">${c}</button>`).join('')}</div>`
    + words.map(w => `<div class="word-card"><div class="arabic">${w.a}</div><div class="transliteration">${w.tr}</div><div class="english">${w.en}</div><button class="btn btn-sm" onclick="speak('${w.tr}','ar')" style="margin-top:6px">🔊</button></div>`).join('');
}
function whaSetCat(c) { _whaCat = c; renderWha(); }
function _renderWhaDrill(el) {
  const d = WHA_DRILLS[_whaDrillIdx % WHA_DRILLS.length];
  const answered = _whaDrillAnswered;
  el.innerHTML = `<div style="text-align:center;margin-bottom:18px"><div style="font-size:1.1rem;font-weight:600;margin-bottom:14px">${d.q}</div>`
    + d.opts.map((o,i) => {
      let bg = '';
      if (answered) { if (i === d.ans) bg = 'background:#1b5e20;color:#fff;'; else if (i === _whaPickedIdx) bg = 'background:#b71c1c;color:#fff;'; }
      return `<button class="btn" style="display:block;width:100%;margin:6px 0;${bg}" onclick="whaPickOpt(${i})">${o}</button>`;
    }).join('')
    + (answered ? `<button class="btn btn-outline" onclick="whaNext()" style="margin-top:12px">Next ➜</button>` : '')
    + `</div>`;
}
function whaPickOpt(i) {
  if (_whaDrillAnswered) return;
  _whaPickedIdx = i; _whaDrillAnswered = true; _whaDrillScore.total++;
  const correct = i === WHA_DRILLS[_whaDrillIdx % WHA_DRILLS.length].ans;
  if (correct) { _whaDrillScore.correct++; recordActivity && recordActivity(); incDailyCount && incDailyCount(); addXp && addXp(10); }
  sfx && sfx(correct ? sfxCorrect : sfxWrong);
  renderWha();
}
function whaNext() { _whaDrillIdx++; _whaDrillAnswered = false; _whaPickedIdx = null; renderWha(); }
function _renderWhaTips(el) {
  el.innerHTML = WHA_TIPS.map(t => `<div class="word-card"><div style="font-weight:700;margin-bottom:6px">${t.title}</div><div style="color:var(--muted)">${t.body}</div></div>`).join('');
}

