// R885 — NEW FEATURE: Lebanese Engagement & Proposal Culture (eng)
let _engTab = 'browse'; let _engCat = 'all'; let _engDrillIdx = 0;
let _engDrillAnswered = false; let _engPickedIdx = null;
let _engDrillScore = { correct: 0, total: 0 };
function openEng(){
  bumpAchievementCounter && bumpAchievementCounter('eng_open');
  const ov = document.getElementById('eng-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _engDrillIdx = 0; _engDrillAnswered = false; _engPickedIdx = null;
  _engDrillScore = { correct: 0, total: 0 };
  setEngTab('browse');
}
function closeEng(){ const ov=document.getElementById('eng-overlay'); if(ov) ov.style.display='none'; }
function setEngTab(t){
  _engTab = t;
  const bar = document.getElementById('eng-tab-bar');
  if(bar){
    const tabs=[['browse','📖 Browse'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l])=>`<button class="cat-filter ${_engTab===k?'active':''}" onclick="setEngTab('${k}')">${l}</button>`).join('');
  }
  renderEng();
}
function renderEng(){
  const el = document.getElementById('eng-content'); if(!el) return;
  const stats = document.getElementById('eng-stats');
  if(stats) stats.textContent = `${ENG_WORDS.length} words · ${ENG_DRILLS.length} drills`;
  if(_engTab==='browse') _renderEngBrowse(el);
  else if(_engTab==='drill') _renderEngDrill(el);
  else _renderEngTips(el);
}
function _renderEngBrowse(el){
  const cats = ['all',...ENG_CATS];
  let html = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">${cats.map(c=>`<button class="cat-filter ${_engCat===c?'active':''}" onclick="engSetCat('${c}')">${c}</button>`).join('')}</div>`;
  const words = _engCat==='all' ? ENG_WORDS : ENG_WORDS.filter(w=>w.cat===_engCat);
  html += `<div style="display:grid;gap:8px">${words.map(w=>`<div class="word-card" onclick="speak('${w.a}','ar')" style="cursor:pointer;padding:12px;border-radius:8px;background:var(--card)"><div style="font-size:1.3rem;font-weight:700">${w.a}</div><div style="color:var(--accent)">${w.tr}</div><div style="color:var(--muted);font-size:0.85rem">${w.en}</div></div>`).join('')}</div>`;
  el.innerHTML = html;
}
function engSetCat(c){ _engCat=c; renderEng(); }
function _renderEngDrill(el){
  const q = ENG_DRILLS[_engDrillIdx % ENG_DRILLS.length];
  const score = `${_engDrillScore.correct}/${_engDrillScore.total}`;
  let html = `<div style="text-align:center;margin-bottom:8px;color:var(--muted)">Score: ${score} · Q${(_engDrillIdx%ENG_DRILLS.length)+1}/${ENG_DRILLS.length}</div>`;
  html += `<div style="font-size:1.1rem;font-weight:600;margin-bottom:16px;text-align:center">${q.q}</div>`;
  html += `<div style="display:grid;gap:8px">${q.opts.map((o,i)=>{
    let bg='var(--card)'; let col='';
    if(_engDrillAnswered){ if(i===q.ans){bg='var(--success,#22c55e)';col='#fff';} else if(i===_engPickedIdx){bg='var(--error,#ef4444)';col='#fff';} }
    return `<button onclick="engPickOpt(${i})" style="padding:12px;border-radius:8px;background:${bg};color:${col};border:none;cursor:pointer;font-size:1rem;text-align:left">${o}</button>`;
  }).join('')}</div>`;
  if(_engDrillAnswered) html += `<div style="text-align:center;margin-top:12px"><button class="btn btn-outline" onclick="engNext()">Next →</button></div>`;
  el.innerHTML = html;
}
function engPickOpt(i){
  if(_engDrillAnswered) return;
  _engPickedIdx=i; _engDrillAnswered=true; _engDrillScore.total++;
  const correct = i===ENG_DRILLS[_engDrillIdx%ENG_DRILLS.length].ans;
  if(correct){ _engDrillScore.correct++; recordActivity&&recordActivity(); incDailyCount&&incDailyCount(); addXp&&addXp(10); }
  sfx&&sfx(correct?sfxCorrect:sfxWrong);
  renderEng();
}
function engNext(){ _engDrillIdx++; _engDrillAnswered=false; _engPickedIdx=null; renderEng(); }
function _renderEngTips(el){
  el.innerHTML = `<div style="display:grid;gap:12px">${ENG_TIPS.map(t=>`<div style="padding:14px;border-radius:8px;background:var(--card)"><div style="font-weight:700;margin-bottom:6px">💍 ${t.title}</div><div style="color:var(--muted);font-size:0.9rem">${t.body}</div></div>`).join('')}</div>`;
}
