// ── R888 NEW FEATURE: Lebanese Fitness & Health Culture (fit) ────────────────
let _fitTab = 'browse'; let _fitCat = 'all'; let _fitDrillIdx = 0;
let _fitDrillAnswered = false; let _fitPickedIdx = null;
let _fitDrillScore = { correct: 0, total: 0 };

function openFit(){
  bumpAchievementCounter && bumpAchievementCounter('fit_open');
  const ov = document.getElementById('fit-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _fitDrillIdx = 0; _fitDrillAnswered = false; _fitPickedIdx = null;
  _fitDrillScore = { correct: 0, total: 0 };
  setFitTab('browse');
}
function closeFit(){ const ov=document.getElementById('fit-overlay'); if(ov) ov.style.display='none'; }
function setFitTab(t){
  _fitTab = t;
  const bar = document.getElementById('fit-tab-bar');
  if(bar){
    const tabs = [['browse','📋 Browse'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_fitTab===k?'active':''}" onclick="setFitTab('${k}')">${l}</button>`).join('');
  }
  renderFit();
}
function renderFit(){
  const el = document.getElementById('fit-content'); if(!el) return;
  const st = document.getElementById('fit-stats');
  if(_fitTab==='browse') _renderFitBrowse(el, st);
  else if(_fitTab==='drill') _renderFitDrill(el, st);
  else _renderFitTips(el, st);
}
function _renderFitBrowse(el, st){
  const cats = ['all'].concat(FIT_CATS);
  let html = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">`;
  cats.forEach(c => {
    html += `<button class="cat-filter ${_fitCat===c?'active':''}" onclick="fitSetCat('${c}')">${c==='all'?'🏋️ All':c}</button>`;
  });
  html += `</div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px">`;
  const items = _fitCat==='all' ? FIT_WORDS : FIT_WORDS.filter(w=>w.cat===_fitCat);
  items.forEach(w => {
    html += `<div class="card" style="padding:12px;cursor:pointer" onclick="speak('${w.tr}','ar')">
      <div style="font-size:1.3rem;font-weight:700">${w.a}</div>
      <div style="color:var(--muted);font-size:0.85rem">${w.tr}</div>
      <div style="font-size:0.9rem">${w.en}</div>
    </div>`;
  });
  html += `</div>`;
  el.innerHTML = html;
  if(st) st.textContent = items.length + ' words';
}
function fitSetCat(c){ _fitCat=c; renderFit(); }
function _renderFitDrill(el, st){
  const d = FIT_DRILLS[_fitDrillIdx % FIT_DRILLS.length];
  const pct = FIT_DRILLS.length ? Math.round(_fitDrillIdx/FIT_DRILLS.length*100) : 0;
  let html = `<div style="margin-bottom:12px;background:var(--border);border-radius:4px;height:6px">
    <div style="width:${pct}%;background:var(--accent);height:6px;border-radius:4px"></div></div>
  <div class="card" style="padding:20px;margin-bottom:14px;text-align:center;font-size:1.1rem;font-weight:600">${d.q}</div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px">`;
  d.opts.forEach((o,i) => {
    let bg=''; let icon='';
    if(_fitDrillAnswered){
      if(i===d.ans){ bg='background:var(--success-bg,#e6f9ee);border-color:var(--success,#2ecc71)'; icon='✅ '; }
      else if(i===_fitPickedIdx){ bg='background:var(--error-bg,#fdecea);border-color:var(--error,#e74c3c)'; icon='❌ '; }
    }
    html += `<button class="card" style="padding:12px;text-align:left;cursor:pointer;${bg}" onclick="fitPickOpt(${i})">${icon}${o}</button>`;
  });
  html += `</div>`;
  if(_fitDrillAnswered){
    html += `<div style="text-align:center"><button class="btn btn-primary" onclick="fitNext()">Next →</button></div>`;
  }
  el.innerHTML = html;
  if(st) st.textContent = `${_fitDrillScore.correct}/${_fitDrillScore.total} correct · Q${(_fitDrillIdx%FIT_DRILLS.length)+1}/${FIT_DRILLS.length}`;
}
function fitPickOpt(i){
  if(_fitDrillAnswered) return;
  _fitPickedIdx=i; _fitDrillAnswered=true; _fitDrillScore.total++;
  const correct = i===FIT_DRILLS[_fitDrillIdx%FIT_DRILLS.length].ans;
  if(correct){ _fitDrillScore.correct++; recordActivity&&recordActivity(); incDailyCount&&incDailyCount(); addXp&&addXp(10); }
  sfx&&sfx(correct?sfxCorrect:sfxWrong);
  renderFit();
}
function fitNext(){
  _fitDrillIdx++; _fitDrillAnswered=false; _fitPickedIdx=null;
  renderFit();
}
function _renderFitTips(el, st){
  let html = `<div style="display:grid;gap:14px">`;
  FIT_TIPS.forEach(t => {
    html += `<div class="card" style="padding:16px">
      <div style="font-weight:700;margin-bottom:6px">💪 ${t.title}</div>
      <div style="line-height:1.6">${t.body}</div>
    </div>`;
  });
  html += `</div>`;
  el.innerHTML = html;
  if(st) st.textContent = FIT_TIPS.length + ' tips';
}
// R888 self-registration
(function(){
  if(typeof TOPICS_CATEGORIES==='undefined') return;
  var ext=TOPICS_CATEGORIES.find(function(c){return c.id==='coaches-ext';});
  if(!ext||!Array.isArray(ext.items)) return;
  if(!ext.items.find(function(it){return it.fn==='openFit';}))
    ext.items.push({label:'💪 Fitness Culture',fn:'openFit',desc:'Lebanese gym & fitness culture vocabulary'});
})();

