// ── R891 NEW FEATURE: Lebanese Compliments & Social Flattery (flt) ────────────
let _fltTab = 'browse'; let _fltCat = 'all'; let _fltDrillIdx = 0;
let _fltDrillAnswered = false; let _fltPickedIdx = null;
let _fltDrillScore = { correct: 0, total: 0 };

function openFlt(){
  bumpAchievementCounter && bumpAchievementCounter('flt_open');
  const ov = document.getElementById('flt-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _fltDrillIdx = 0; _fltDrillAnswered = false; _fltPickedIdx = null;
  _fltDrillScore = { correct: 0, total: 0 };
  setFltTab('browse');
}
function closeFlt(){ const ov=document.getElementById('flt-overlay'); if(ov) ov.style.display='none'; }
function setFltTab(t){
  _fltTab = t;
  const bar = document.getElementById('flt-tab-bar');
  if(bar){
    const tabs = [['browse','📋 Browse'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_fltTab===k?'active':''}" onclick="setFltTab('${k}')">${l}</button>`).join('');
  }
  renderFlt();
}
function renderFlt(){
  const el = document.getElementById('flt-content'); if(!el) return;
  const st = document.getElementById('flt-stats');
  if(_fltTab==='browse') _renderFltBrowse(el, st);
  else if(_fltTab==='drill') _renderFltDrill(el, st);
  else _renderFltTips(el, st);
}
function _renderFltBrowse(el, st){
  const cats = ['all'].concat(FLT_CATS);
  let html = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">`;
  cats.forEach(c => {
    html += `<button class="cat-filter ${_fltCat===c?'active':''}" onclick="fltSetCat('${c}')">${c==='all'?'🌹 All':c}</button>`;
  });
  html += `</div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px">`;
  const items = _fltCat==='all' ? FLT_WORDS : FLT_WORDS.filter(w=>w.cat===_fltCat);
  items.forEach(w => {
    html += `<div class="card" style="padding:12px;cursor:pointer" onclick="speak('${w.tr}','ar')">
      <div style="font-size:1.2rem;font-weight:700">${w.a}</div>
      <div style="color:var(--muted);font-size:0.85rem">${w.tr}</div>
      <div style="font-size:0.9rem">${w.en}</div>
    </div>`;
  });
  html += `</div>`;
  el.innerHTML = html;
  if(st) st.textContent = items.length + ' phrases';
}
function fltSetCat(c){ _fltCat=c; renderFlt(); }
function _renderFltDrill(el, st){
  const d = FLT_DRILLS[_fltDrillIdx % FLT_DRILLS.length];
  const pct = FLT_DRILLS.length ? Math.round(_fltDrillIdx/FLT_DRILLS.length*100) : 0;
  let html = `<div style="margin-bottom:12px;background:var(--border);border-radius:4px;height:6px">
    <div style="width:${pct}%;background:var(--accent);height:6px;border-radius:4px"></div></div>
  <div class="card" style="padding:20px;margin-bottom:14px;text-align:center;font-size:1.1rem;font-weight:600">${d.q}</div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px">`;
  d.opts.forEach((o,i) => {
    let bg=''; let icon='';
    if(_fltDrillAnswered){
      if(i===d.ans){ bg='background:var(--success-bg,#e6f9ee);border-color:var(--success,#2ecc71)'; icon='✅ '; }
      else if(i===_fltPickedIdx){ bg='background:var(--error-bg,#fdecea);border-color:var(--error,#e74c3c)'; icon='❌ '; }
    }
    html += `<button class="card" style="padding:12px;text-align:left;cursor:pointer;${bg}" onclick="fltPickOpt(${i})">${icon}${o}</button>`;
  });
  html += `</div>`;
  if(_fltDrillAnswered){
    html += `<div style="text-align:center"><button class="btn btn-primary" onclick="fltNext()">Next →</button></div>`;
  }
  el.innerHTML = html;
  if(st) st.textContent = `${_fltDrillScore.correct}/${_fltDrillScore.total} correct · Q${(_fltDrillIdx%FLT_DRILLS.length)+1}/${FLT_DRILLS.length}`;
}
function fltPickOpt(i){
  if(_fltDrillAnswered) return;
  _fltPickedIdx=i; _fltDrillAnswered=true; _fltDrillScore.total++;
  const correct = i===FLT_DRILLS[_fltDrillIdx%FLT_DRILLS.length].ans;
  if(correct){ _fltDrillScore.correct++; recordActivity&&recordActivity(); incDailyCount&&incDailyCount(); addXp&&addXp(10); }
  sfx&&sfx(correct?sfxCorrect:sfxWrong);
  renderFlt();
}
function fltNext(){
  _fltDrillIdx++; _fltDrillAnswered=false; _fltPickedIdx=null;
  renderFlt();
}
function _renderFltTips(el, st){
  let html = `<div style="display:grid;gap:14px">`;
  FLT_TIPS.forEach(t => {
    html += `<div class="card" style="padding:16px">
      <div style="font-weight:700;margin-bottom:6px">🌹 ${t.title}</div>
      <div style="line-height:1.6">${t.body}</div>
    </div>`;
  });
  html += `</div>`;
  el.innerHTML = html;
  if(st) st.textContent = FLT_TIPS.length + ' tips';
}
