// ── R894 NEW FEATURE: Lebanese Card Games (crd) ──────────────────────────────
let _crdTab = 'vocab';
let _crdDrillIdx = 0;
let _crdDrillPicked = null;
let _crdDrillAnswered = 0;
let _crdDrillCorrect = 0;

function openCrd(){
  bumpAchievementCounter && bumpAchievementCounter('crd_open');
  const ov = document.getElementById('crd-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _crdDrillIdx = 0; _crdDrillPicked = null; _crdDrillAnswered = 0; _crdDrillCorrect = 0;
  setCrdTab('vocab');
}
function closeCrd(){ const ov=document.getElementById('crd-overlay'); if(ov) ov.style.display='none'; }
function setCrdTab(t){
  _crdTab = t;
  const bar = document.getElementById('crd-tab-bar');
  if(bar){
    const tabs = [['vocab','🃏 Vocab'],['drill','🎯 Drill'],['tips','📖 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_crdTab===k?'active':''}" onclick="setCrdTab('${k}')">${l}</button>`).join('');
  }
  renderCrd();
}
function renderCrd(){
  const el = document.getElementById('crd-content'); if(!el) return;
  if(_crdTab==='vocab') renderCrdVocab(el);
  else if(_crdTab==='drill') renderCrdDrill(el);
  else renderCrdTips(el);
}
function renderCrdVocab(el){
  const stats = document.getElementById('crd-stats');
  if(stats) stats.textContent = CRD_WORDS.length + ' words';
  el.innerHTML = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">' +
    CRD_WORDS.map(w => `<div class="card" style="padding:12px">
      <div style="font-size:1.4rem;font-weight:700;direction:rtl">${w.ar}</div>
      <div style="color:var(--accent);font-size:0.95rem">${w.tr}</div>
      <div style="color:var(--muted);font-size:0.85rem">${w.en}</div>
      <button class="btn btn-sm" style="margin-top:6px" onclick="speak('${w.ar.replace(/'/g,"\\'")}')">🔊</button>
    </div>`).join('') + '</div>';
}
function renderCrdDrill(el){
  const stats = document.getElementById('crd-stats');
  if(stats) stats.textContent = _crdDrillCorrect + '/' + _crdDrillAnswered + ' correct';
  if(_crdDrillIdx >= CRD_DRILLS.length){
    el.innerHTML = `<div class="card" style="text-align:center;padding:24px">
      <div style="font-size:2rem">🃏</div>
      <div style="font-size:1.2rem;font-weight:700;margin:12px 0">Drill complete!</div>
      <div style="color:var(--muted)">${_crdDrillCorrect}/${_crdDrillAnswered} correct</div>
      <button class="btn btn-primary" style="margin-top:14px" onclick="_crdDrillIdx=0;_crdDrillAnswered=0;_crdDrillCorrect=0;renderCrd()">↩ Restart</button>
    </div>`;
    return;
  }
  const item = CRD_DRILLS[_crdDrillIdx];
  const opts = _buildCrdOpts(item.a);
  el.innerHTML = `<div class="card" style="padding:20px;max-width:520px;margin:0 auto">
    <div style="color:var(--muted);font-size:0.8rem;margin-bottom:6px">Question ${_crdDrillIdx+1}/${CRD_DRILLS.length}</div>
    <div style="font-size:1.1rem;font-weight:600;margin-bottom:4px">${item.q}</div>
    <div style="color:var(--muted);font-size:0.85rem;margin-bottom:14px">Hint: ${item.hint}</div>
    <div id="crd-opts" style="display:flex;flex-direction:column;gap:8px">
      ${opts.map(o=>`<button class="btn btn-outline" onclick="crdPickOpt('${o.replace(/'/g,"\\'")}')">${o}</button>`).join('')}
    </div>
    <div id="crd-feedback" style="margin-top:12px;min-height:24px"></div>
  </div>`;
}
function _buildCrdOpts(correct){
  const pool = CRD_DRILLS.map(d=>d.a).filter(a=>a!==correct);
  const shuffled = pool.sort(()=>Math.random()-0.5).slice(0,3);
  const all = [correct,...shuffled].sort(()=>Math.random()-0.5);
  return all;
}
function crdPickOpt(chosen){
  if(_crdDrillPicked) return;
  _crdDrillPicked = chosen;
  const item = CRD_DRILLS[_crdDrillIdx];
  const correct = chosen === item.a;
  _crdDrillAnswered++;
  if(correct) _crdDrillCorrect++;
  recordActivity && recordActivity();
  incDailyCount && incDailyCount();
  addXp && addXp(correct?10:2);
  const fb = document.getElementById('crd-feedback');
  if(fb) fb.innerHTML = correct
    ? '<span style="color:var(--success)">✓ Correct!</span>'
    : `<span style="color:var(--danger)">✗ Answer: <strong>${item.a}</strong></span>`;
  const opts = document.getElementById('crd-opts');
  if(opts) opts.querySelectorAll('button').forEach(b=>{
    b.disabled = true;
    if(b.textContent.trim()===item.a) b.style.background='var(--success)';
    else if(b.textContent.trim()===chosen && !correct) b.style.background='var(--danger)';
  });
  setTimeout(()=>{ _crdDrillPicked=null; _crdDrillIdx++; renderCrd(); }, 1100);
}
function renderCrdTips(el){
  const stats = document.getElementById('crd-stats');
  if(stats) stats.textContent = CRD_TIPS.length + ' tips';
  el.innerHTML = CRD_TIPS.map(t=>`<div class="card" style="padding:16px;margin-bottom:10px">
    <div style="font-weight:700;margin-bottom:6px">${t.title}</div>
    <div style="color:var(--muted);font-size:0.9rem">${t.body}</div>
  </div>`).join('');
}

