// ── R900 NEW FEATURE — Lebanese Neighborhood Shop & Dukkan Culture (dkn) ─────
let _dknTab = 'words';
let _dknDrillIdx = 0;
let _dknDrillPicked = false;

function openDkn(){
  bumpAchievementCounter && bumpAchievementCounter('dkn_open');
  const ov = document.getElementById('dkn-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setDknTab('words');
}
function closeDkn(){ const ov=document.getElementById('dkn-overlay'); if(ov) ov.style.display='none'; }
function setDknTab(t){
  _dknTab = t;
  const bar = document.getElementById('dkn-tab-bar');
  if(bar){
    const tabs = [['words','🛒 Vocab'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_dknTab===k?'active':''}" onclick="setDknTab('${k}')">${l}</button>`).join('');
  }
  renderDkn();
}
function renderDkn(){
  const el = document.getElementById('dkn-content'); if(!el) return;
  if(_dknTab==='words') renderDknVocab(el);
  else if(_dknTab==='drill') renderDknDrill(el);
  else renderDknTips(el);
}
function renderDknVocab(el){
  const stats = document.getElementById('dkn-stats');
  if(stats) stats.textContent = (typeof DKN_WORDS!=='undefined'?DKN_WORDS.length:0)+' words';
  if(typeof DKN_WORDS==='undefined'){ el.innerHTML='<p>No data.</p>'; return; }
  el.innerHTML = '<div style="display:grid;gap:8px;grid-template-columns:repeat(auto-fill,minmax(260px,1fr))">' +
    DKN_WORDS.map(w=>`<div class="card" style="padding:14px">
      <div style="font-size:1.3rem;font-weight:700">${w.ar}</div>
      <div style="color:var(--accent);font-size:0.95rem">${w.tr}</div>
      <div style="color:var(--muted);font-size:0.85rem">${w.en}</div>
      <button class="btn btn-outline" style="margin-top:6px;font-size:0.8rem" onclick="speak('${w.tr}')">🔊</button>
    </div>`).join('') + '</div>';
}
function renderDknDrill(el){
  if(typeof DKN_DRILLS==='undefined'||!DKN_DRILLS.length){ el.innerHTML='<p>No drills.</p>'; return; }
  _dknDrillPicked = false;
  const d = DKN_DRILLS[_dknDrillIdx % DKN_DRILLS.length];
  const stats = document.getElementById('dkn-stats');
  if(stats) stats.textContent = (_dknDrillIdx % DKN_DRILLS.length + 1)+'/'+DKN_DRILLS.length;
  el.innerHTML = `<div class="card" style="padding:20px;max-width:560px;margin:0 auto">
    <div style="font-size:1.1rem;font-weight:600;margin-bottom:16px">${d.q}</div>
    <div style="display:grid;gap:8px" id="dkn-opts">${_buildDknOpts(d)}</div>
    <div id="dkn-feedback" style="margin-top:14px;font-size:1rem"></div>
    <button class="btn btn-outline" style="margin-top:12px" onclick="dknNext()">Next ▶</button>
  </div>`;
}
function _buildDknOpts(d){
  if(typeof DKN_DRILLS==='undefined') return '';
  const correct = d.a;
  const pool = DKN_DRILLS.map(x=>x.a).filter(x=>x!==correct);
  const wrongs = pool.sort(()=>Math.random()-0.5).slice(0,3);
  const opts = [correct,...wrongs].sort(()=>Math.random()-0.5);
  return opts.map(o=>`<button class="btn btn-outline" onclick="dknPickOpt('${o.replace(/'/g,"\\'")}','${correct.replace(/'/g,"\\'")}','${d.hint||''}')">${o}</button>`).join('');
}
function dknPickOpt(chosen, correct, hint){
  if(_dknDrillPicked) return;
  _dknDrillPicked = true;
  const fb = document.getElementById('dkn-feedback'); if(!fb) return;
  const ok = chosen === correct;
  fb.innerHTML = ok
    ? `<span style="color:var(--accent)">✓ Correct! ${hint}</span>`
    : `<span style="color:#e74c3c">✗ ${correct} — ${hint}</span>`;
  if(ok){ try{ recordActivity && recordActivity(); incDailyCount && incDailyCount(); addXp && addXp(10); }catch(e){} }
  try{ speak(correct); }catch(e){}
}
function dknNext(){
  _dknDrillIdx++;
  renderDknDrill(document.getElementById('dkn-content'));
}
function renderDknTips(el){
  if(typeof DKN_TIPS==='undefined'){ el.innerHTML='<p>No tips.</p>'; return; }
  const stats = document.getElementById('dkn-stats');
  if(stats) stats.textContent = DKN_TIPS.length+' tips';
  el.innerHTML = DKN_TIPS.map(t=>`<div class="card" style="padding:18px;margin-bottom:10px">
    <div style="font-weight:700;margin-bottom:6px">🏪 ${t.title}</div>
    <div style="color:var(--muted);line-height:1.6">${t.body}</div>
  </div>`).join('');
}

// self-register in coaches-ext
(function(){
  if(typeof TOPICS_CATEGORIES==='undefined') return;
  var ext = TOPICS_CATEGORIES.find(function(c){ return c.id==='coaches-ext'; });
  if(!ext){ ext={id:'coaches-ext',label:'More',items:[]}; TOPICS_CATEGORIES.push(ext); }
  if(!ext.items) ext.items=[];
  if(!ext.items.some(function(i){ return i.fn==='openDkn'; }))
    ext.items.push({label:'🏪 Dukkan',fn:'openDkn'});
})();

