// ── R903 NEW FEATURE — Lebanese Fortune Telling & Coffee Cup Reading (ftn) ───
let _ftnTab = 'words';
let _ftnDrillIdx = 0;
let _ftnDrillPicked = false;

function openFtn(){
  bumpAchievementCounter && bumpAchievementCounter('ftn_open');
  const ov = document.getElementById('ftn-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setFtnTab('words');
}
function closeFtn(){ const ov=document.getElementById('ftn-overlay'); if(ov) ov.style.display='none'; }
function setFtnTab(t){
  _ftnTab = t;
  const bar = document.getElementById('ftn-tab-bar');
  if(bar){
    const tabs = [['words','☕ Vocab'],['drill','🎯 Drill'],['tips','🔮 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_ftnTab===k?'active':''}" onclick="setFtnTab('${k}')">${l}</button>`).join('');
  }
  renderFtn();
}
function renderFtn(){
  const el = document.getElementById('ftn-content'); if(!el) return;
  if(_ftnTab==='words') renderFtnVocab(el);
  else if(_ftnTab==='drill') renderFtnDrill(el);
  else renderFtnTips(el);
}
function renderFtnVocab(el){
  const stats = document.getElementById('ftn-stats');
  if(stats) stats.textContent = (typeof FTN_WORDS!=='undefined'?FTN_WORDS.length:0)+' words';
  if(typeof FTN_WORDS==='undefined'){ el.innerHTML='<p>No data.</p>'; return; }
  el.innerHTML = '<div style="display:grid;gap:8px;grid-template-columns:repeat(auto-fill,minmax(260px,1fr))">' +
    FTN_WORDS.map(w=>`<div class="card" style="padding:14px">
      <div style="font-size:1.3rem;font-weight:700">${w.ar}</div>
      <div style="color:var(--accent);font-size:0.95rem">${w.tr}</div>
      <div style="color:var(--muted);font-size:0.85rem">${w.en}</div>
      <button class="btn btn-outline" style="margin-top:6px;font-size:0.8rem" onclick="speak('${w.tr}')">🔊</button>
    </div>`).join('') + '</div>';
}
function renderFtnDrill(el){
  if(typeof FTN_DRILLS==='undefined'||!FTN_DRILLS.length){ el.innerHTML='<p>No drills.</p>'; return; }
  _ftnDrillPicked = false;
  const d = FTN_DRILLS[_ftnDrillIdx % FTN_DRILLS.length];
  const stats = document.getElementById('ftn-stats');
  if(stats) stats.textContent = (_ftnDrillIdx % FTN_DRILLS.length + 1)+'/'+FTN_DRILLS.length;
  el.innerHTML = `<div class="card" style="padding:20px;max-width:560px;margin:0 auto">
    <div style="font-size:1.1rem;font-weight:600;margin-bottom:16px">${d.q}</div>
    <div style="display:grid;gap:8px" id="ftn-opts">${_buildFtnOpts(d)}</div>
    <div id="ftn-feedback" style="margin-top:14px;font-size:1rem"></div>
    <button class="btn btn-outline" style="margin-top:12px" onclick="ftnNext()">Next ▶</button>
  </div>`;
}
function _buildFtnOpts(d){
  if(typeof FTN_DRILLS==='undefined') return '';
  const correct = d.a;
  const pool = FTN_DRILLS.map(x=>x.a).filter(x=>x!==correct);
  const wrongs = pool.sort(()=>Math.random()-0.5).slice(0,3);
  const opts = [correct,...wrongs].sort(()=>Math.random()-0.5);
  return opts.map(o=>`<button class="btn btn-outline" onclick="ftnPickOpt('${o.replace(/'/g,"\\'")}','${correct.replace(/'/g,"\\'")}','${(d.hint||'').replace(/'/g,"\\'")}')"> ${o}</button>`).join('');
}
function ftnPickOpt(chosen, correct, hint){
  if(_ftnDrillPicked) return;
  _ftnDrillPicked = true;
  const ok = chosen === correct;
  const fb = document.getElementById('ftn-feedback'); if(!fb) return;
  fb.innerHTML = ok
    ? `<span style="color:var(--accent)">✓ Correct! ${hint}</span>`
    : `<span style="color:#e74c3c">✗ ${correct} — ${hint}</span>`;
  try{ sfx && sfx(ok ? sfxCorrect : sfxWrong); }catch(e){}
  if(ok){ try{ recordActivity && recordActivity(); incDailyCount && incDailyCount(); addXp && addXp(10); }catch(e){} }
  try{ speak(correct); }catch(e){}
}
function ftnNext(){
  _ftnDrillIdx++;
  renderFtnDrill(document.getElementById('ftn-content'));
}
function renderFtnTips(el){
  if(typeof FTN_TIPS==='undefined'){ el.innerHTML='<p>No tips.</p>'; return; }
  const stats = document.getElementById('ftn-stats');
  if(stats) stats.textContent = FTN_TIPS.length+' tips';
  el.innerHTML = FTN_TIPS.map(t=>`<div class="card" style="padding:18px;margin-bottom:10px">
    <div style="font-weight:700;margin-bottom:6px">🔮 ${t.title}</div>
    <div style="color:var(--muted);line-height:1.6">${t.body}</div>
  </div>`).join('');
}

// self-register in coaches-ext
(function(){
  if(typeof TOPICS_CATEGORIES==='undefined') return;
  var ext = TOPICS_CATEGORIES.find(function(c){ return c.id==='coaches-ext'; });
  if(!ext){ ext={id:'coaches-ext',label:'More',items:[]}; TOPICS_CATEGORIES.push(ext); }
  if(!ext.items) ext.items=[];
  if(!ext.items.some(function(i){ return i.fn==='openFtn'; }))
    ext.items.push({label:'🔮 Fortune',fn:'openFtn'});
})();

