let _skiTab = 'vocab';
let _skiDrillIdx = 0;
let _skiDrillAnswered = false;
let _skiPickedIdx = null;
let _skiDrillScore = { correct: 0, total: 0 };

function openSki(){
  bumpAchievementCounter && bumpAchievementCounter('ski_open');
  const ov = document.getElementById('ski-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setSkiTab('vocab');
}
function closeSki(){ const ov=document.getElementById('ski-overlay'); if(ov) ov.style.display='none'; }
function setSkiTab(t){
  _skiTab = t;
  const bar = document.getElementById('ski-tab-bar');
  if(bar){
    const tabs = [['vocab','⛷️ Vocab'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l])=>`<button class="cat-filter ${_skiTab===k?'active':''}" onclick="setSkiTab('${k}')">${l}</button>`).join('');
  }
  renderSki();
}
function renderSki(){
  const c = document.getElementById('ski-content');
  const st = document.getElementById('ski-stats');
  if(!c) return;
  if(_skiTab==='vocab') _renderSkiVocab(c, st);
  else if(_skiTab==='drill') _renderSkiDrill(c, st);
  else _renderSkiTips(c, st);
}
function _renderSkiVocab(c, st){
  if(typeof SKI_WORDS==='undefined'){ c.innerHTML='<p style="color:var(--muted);padding:20px">Data not loaded.</p>'; return; }
  if(st) st.textContent = SKI_WORDS.length + ' words';
  c.innerHTML = '<div style="display:grid;gap:10px">' + SKI_WORDS.map(w =>
    `<div class="word-card" style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px">
      <span style="font-size:1.2rem;font-weight:700">${w.ar}</span>
      <span style="color:var(--accent)">${w.tr}</span>
      <span style="color:var(--muted);font-size:0.9rem">${w.en}</span>
      <button class="btn btn-sm" onclick="speak('${w.tr}')">🔊</button>
    </div>`
  ).join('') + '</div>';
}
function _renderSkiDrill(c, st){
  if(typeof SKI_DRILLS==='undefined'){ c.innerHTML='<p style="color:var(--muted);padding:20px">Data not loaded.</p>'; return; }
  if(st) st.textContent = _skiDrillScore.correct + '/' + _skiDrillScore.total + ' correct';
  const d = SKI_DRILLS[_skiDrillIdx % SKI_DRILLS.length];
  const opts = _skiDrillAnswered
    ? d.opts.map((o,i)=>`<button class="btn ${i===d.ans?'btn-success':(_skiPickedIdx===i?'btn-danger':'btn-outline')}" disabled>${o}</button>`).join('')
    : d.opts.map((o,i)=>`<button class="btn btn-outline" onclick="skiPickOpt(${i})">${o}</button>`).join('');
  c.innerHTML = `<div class="card" style="padding:24px;text-align:center;max-width:600px;margin:0 auto">
    <div style="font-size:1.1rem;margin-bottom:20px">${d.q}</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:16px">${opts}</div>
    ${_skiDrillAnswered?`<button class="btn" onclick="skiNext()">Next ➜</button>`:''}
  </div>`;
}
function skiPickOpt(i){
  if(_skiDrillAnswered) return;
  _skiPickedIdx = i;
  _skiDrillAnswered = true;
  _skiDrillScore.total++;
  const d = SKI_DRILLS[_skiDrillIdx % SKI_DRILLS.length];
  const correct = i === d.ans;
  if(correct){
    _skiDrillScore.correct++;
    recordActivity && recordActivity();
    incDailyCount && incDailyCount();
    addXp && addXp(10);
  }
  sfx && sfx(correct ? sfxCorrect : sfxWrong);
  renderSki();
}
function skiNext(){
  _skiDrillIdx++;
  _skiDrillAnswered = false;
  _skiPickedIdx = null;
  renderSki();
}
function _renderSkiTips(c, st){
  if(typeof SKI_TIPS==='undefined'){ c.innerHTML='<p style="color:var(--muted);padding:20px">Data not loaded.</p>'; return; }
  if(st) st.textContent = SKI_TIPS.length + ' tips';
  c.innerHTML = '<div style="display:grid;gap:14px">' + SKI_TIPS.map((t,i)=>
    `<div class="card" style="padding:18px">
      <div style="font-weight:700;color:var(--accent);margin-bottom:8px">${i+1}. ${t.title}</div>
      <div style="color:var(--muted);line-height:1.6;font-size:0.95rem">${t.body}</div>
    </div>`
  ).join('') + '</div>';
}

