// R912 — NEW FEATURE: Lebanese Solar & Generator Culture (slr)
let _slrTab = 'vocab';
let _slrDrillIdx = 0;
let _slrDrillAnswered = false;
let _slrPickedIdx = null;
let _slrDrillScore = { correct: 0, total: 0 };
function openSlr(){
  bumpAchievementCounter && bumpAchievementCounter('slr_open');
  const ov = document.getElementById('slr-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setSlrTab('vocab');
}
function closeSlr(){ const ov=document.getElementById('slr-overlay'); if(ov) ov.style.display='none'; }
function setSlrTab(t){
  _slrTab = t;
  const bar = document.getElementById('slr-tab-bar');
  if(bar){
    const tabs = [['vocab','📖 Vocab'],['drill','🎯 Drill'],['tips','💡 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_slrTab===k?'active':''}" onclick="setSlrTab('${k}')">${l}</button>`).join('');
  }
  renderSlr();
}
function renderSlr(){
  const c = document.getElementById('slr-content'); if(!c) return;
  const st = document.getElementById('slr-stats');
  if(_slrTab==='vocab') _renderSlrVocab(c, st);
  else if(_slrTab==='drill') _renderSlrDrill(c, st);
  else _renderSlrTips(c, st);
}
function _renderSlrVocab(c, st){
  if(st) st.textContent = SLR_WORDS.length + ' words';
  c.innerHTML = '<div style="display:grid;gap:8px">' +
    SLR_WORDS.map(w => '<div style="background:var(--card);border-radius:10px;padding:12px 16px;display:flex;justify-content:space-between;align-items:center;gap:12px">' +
      '<div><div style="font-size:1.3rem;font-weight:600">' + w.ar + '</div>' +
      '<div style="color:var(--muted);font-size:0.82rem;margin-top:2px">' + w.tr + '</div></div>' +
      '<div style="display:flex;align-items:center;gap:8px">' +
      '<div style="color:var(--accent);font-size:0.88rem;text-align:right">' + w.en + '</div>' +
      '<button class="btn btn-outline" style="padding:4px 8px;font-size:0.8rem" onclick="speak(\'' + w.tr + '\')">🔊</button>' +
      '</div></div>').join('') + '</div>';
}
function _renderSlrDrill(c, st){
  if(st) st.textContent = _slrDrillScore.correct + '/' + _slrDrillScore.total + ' correct';
  const d = SLR_DRILLS[_slrDrillIdx % SLR_DRILLS.length];
  c.innerHTML = '<div style="max-width:560px;margin:0 auto;padding:20px 0">' +
    '<div style="text-align:center;color:var(--muted);font-size:0.82rem;margin-bottom:8px">Q' + (_slrDrillIdx+1) + '</div>' +
    '<div style="font-size:1.1rem;font-weight:600;text-align:center;margin-bottom:24px">' + d.q + '</div>' +
    '<div style="display:grid;gap:10px">' +
    d.opts.map((o,i) => {
      let bg='var(--card)'; let col='';
      if(_slrDrillAnswered){
        if(i===d.ans){ bg='var(--success,#22c55e)'; col='color:#fff'; }
        else if(i===_slrPickedIdx){ bg='var(--danger,#ef4444)'; col='color:#fff'; }
      }
      return '<button onclick="slrPickOpt(' + i + ')" style="background:' + bg + ';' + col + ';border:none;border-radius:10px;padding:14px 18px;text-align:left;cursor:pointer;font-size:1rem">' + o + '</button>';
    }).join('') +
    '</div>' +
    (_slrDrillAnswered ? '<div style="text-align:center;margin-top:20px"><button class="btn" onclick="slrNext()">Next →</button></div>' : '') +
    '</div>';
}
function slrPickOpt(i){
  if(_slrDrillAnswered) return;
  _slrPickedIdx = i; _slrDrillAnswered = true; _slrDrillScore.total++;
  const d = SLR_DRILLS[_slrDrillIdx % SLR_DRILLS.length];
  const correct = i === d.ans;
  if(correct){ _slrDrillScore.correct++; recordActivity && recordActivity(); incDailyCount && incDailyCount(); addXp && addXp(10); }
  sfx && sfx(correct ? sfxCorrect : sfxWrong);
  renderSlr();
}
function slrNext(){ _slrDrillIdx++; _slrDrillAnswered=false; _slrPickedIdx=null; renderSlr(); }
function _renderSlrTips(c, st){
  if(st) st.textContent = SLR_TIPS.length + ' culture notes';
  c.innerHTML = '<div style="display:grid;gap:14px">' +
    SLR_TIPS.map(t => '<div style="background:var(--card);border-radius:12px;padding:16px 18px">' +
      '<div style="font-weight:700;margin-bottom:6px">' + t.title + '</div>' +
      '<div style="color:var(--muted);font-size:0.9rem;line-height:1.55">' + t.body + '</div>' +
      '</div>').join('') + '</div>';
}
(function(){
  var ext = TOPICS_CATEGORIES.find(function(c){ return c.id==='coaches-ext'; });
  if(!ext){ ext={id:'coaches-ext',title:'🗂️ Topic Coaches',items:[]}; TOPICS_CATEGORIES.push(ext); }
  if(!ext.items.find(function(it){ return it.fn==='openSlr'; }))
    ext.items.push({ label: '⚡ Solar & Generator Culture', fn: 'openSlr', desc: 'Kahraba, moteur, alwaa7 shamsiyye — surviving Lebanese power cuts' });
})();

