// R921 — NEW FEATURE: Lebanese Coffee Shop & Café Culture (cfs)
let _cfsTab = 'vocab';
let _cfsDrillIdx = 0;
let _cfsDrillAnswered = false;
let _cfsPickedIdx = null;
let _cfsDrillScore = { correct: 0, total: 0 };
function openCfs(){
  bumpAchievementCounter && bumpAchievementCounter('cfs_open');
  const ov = document.getElementById('cfs-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setCfsTab('vocab');
}
function closeCfs(){ const ov=document.getElementById('cfs-overlay'); if(ov) ov.style.display='none'; }
function setCfsTab(t){
  _cfsTab = t;
  const bar = document.getElementById('cfs-tab-bar');
  if(bar){
    const tabs = [['vocab','📖 Vocab'],['drill','🎯 Drill'],['tips','💡 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_cfsTab===k?'active':''}" onclick="setCfsTab('${k}')">${l}</button>`).join('');
  }
  renderCfs();
}
function renderCfs(){
  const c = document.getElementById('cfs-content');
  const st = document.getElementById('cfs-stats');
  if(!c) return;
  if(_cfsTab === 'vocab') _renderCfsVocab(c, st);
  else if(_cfsTab === 'drill') _renderCfsDrill(c, st);
  else _renderCfsTips(c, st);
}
function _renderCfsVocab(c, st){
  if(st) st.textContent = CFS_WORDS.length + ' words';
  c.innerHTML = `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">` +
    CFS_WORDS.map(w => `<div class="card" style="padding:12px;cursor:pointer" onclick="speak('${w.tr}')">
      <div style="font-size:1.3rem;font-weight:700">${w.ar}</div>
      <div style="color:var(--accent);font-size:0.9rem">${w.tr}</div>
      <div style="color:var(--muted);font-size:0.85rem">${w.en}</div>
    </div>`).join('') + `</div>`;
}
function _renderCfsDrill(c, st){
  if(st) st.textContent = _cfsDrillScore.correct + '/' + _cfsDrillScore.total;
  const d = CFS_DRILLS[_cfsDrillIdx % CFS_DRILLS.length];
  c.innerHTML = `<div class="card" style="padding:20px;max-width:560px;margin:0 auto">
    <div style="font-weight:700;margin-bottom:16px;font-size:1.05rem">${d.q}</div>
    <div style="display:grid;gap:8px">${d.opts.map((o,i) => {
      let bg = 'var(--card-bg)';
      if(_cfsDrillAnswered){ if(i===d.ans) bg='var(--easy)'; else if(i===_cfsPickedIdx) bg='var(--hard)'; }
      return `<button class="btn btn-outline" style="text-align:left;background:${bg}" onclick="cfsPickOpt(${i})">${o}</button>`;
    }).join('')}
    </div>
    ${_cfsDrillAnswered ? `<button class="btn" style="margin-top:16px" onclick="cfsNext()">Next →</button>` : ''}
  </div>`;
}
function cfsPickOpt(i){
  if(_cfsDrillAnswered) return;
  _cfsPickedIdx = i; _cfsDrillAnswered = true; _cfsDrillScore.total++;
  const d = CFS_DRILLS[_cfsDrillIdx % CFS_DRILLS.length];
  const correct = i === d.ans;
  if(correct){ _cfsDrillScore.correct++; recordActivity && recordActivity(); incDailyCount && incDailyCount(); addXp && addXp(10); }
  sfx && sfx(correct ? sfxCorrect : sfxWrong);
  renderCfs();
}
function cfsNext(){ _cfsDrillIdx++; _cfsDrillAnswered=false; _cfsPickedIdx=null; renderCfs(); }
function _renderCfsTips(c, st){
  if(st) st.textContent = CFS_TIPS.length + ' tips';
  c.innerHTML = CFS_TIPS.map(t => `<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="font-weight:700;margin-bottom:8px">☕ ${t.title}</div>
    <div style="color:var(--muted);line-height:1.6">${t.body}</div>
  </div>`).join('');
}
// coaches-ext self-register
(function(){
  if(typeof TOPICS_CATEGORIES === 'undefined') return;
  var ext = TOPICS_CATEGORIES.find(function(c){ return c.id === 'coaches-ext'; });
  if(!ext) return;
  if(ext.items.some(function(c){ return c.fn === 'openCfs'; })) return;
  ext.items.push({ label: '☕ Coffee Shop & Café Culture', fn: 'openCfs', desc: 'Lebanese café life, Arabic coffee, hookah, jalse, backgammon + MCQ drill' });
})();

