// R924 — NEW FEATURE: Lebanese Proverbs & Wisdom (prw)
let _prwTab = 'vocab';
let _prwDrillIdx = 0;
let _prwDrillAnswered = false;
let _prwPickedIdx = null;
let _prwDrillScore = { correct: 0, total: 0 };
function openPrw(){
  bumpAchievementCounter && bumpAchievementCounter('prw_open');
  const ov = document.getElementById('prw-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setPrwTab('vocab');
}
function closePrw(){ const ov=document.getElementById('prw-overlay'); if(ov) ov.style.display='none'; }
function setPrwTab(t){
  _prwTab = t;
  const bar = document.getElementById('prw-tab-bar');
  if(bar){
    const tabs = [['vocab','📜 Proverbs'],['drill','🎯 Drill'],['tips','💡 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_prwTab===k?'active':''}" onclick="setPrwTab('${k}')">${l}</button>`).join('');
  }
  renderPrw();
}
function renderPrw(){
  const c = document.getElementById('prw-content');
  const st = document.getElementById('prw-stats');
  if(!c) return;
  if(_prwTab === 'vocab') _renderPrwVocab(c, st);
  else if(_prwTab === 'drill') _renderPrwDrill(c, st);
  else _renderPrwTips(c, st);
}
function _renderPrwVocab(c, st){
  if(st) st.textContent = PRW_WORDS.length + ' proverbs';
  c.innerHTML = PRW_WORDS.map(w => `<div class="card" style="padding:14px;margin-bottom:10px;cursor:pointer" onclick="speak('${w.tr}')">
    <div style="font-size:1.1rem;font-weight:700;margin-bottom:4px">${w.ar}</div>
    <div style="color:var(--accent);font-size:0.9rem;margin-bottom:4px">${w.tr}</div>
    <div style="color:var(--muted);font-size:0.85rem;font-style:italic">${w.en}</div>
  </div>`).join('');
}
function _renderPrwDrill(c, st){
  if(st) st.textContent = _prwDrillScore.correct + '/' + _prwDrillScore.total;
  const d = PRW_DRILLS[_prwDrillIdx % PRW_DRILLS.length];
  c.innerHTML = `<div class="card" style="padding:20px;max-width:560px;margin:0 auto">
    <div style="font-weight:700;margin-bottom:16px;font-size:1.05rem">${d.q}</div>
    <div style="display:grid;gap:8px">${d.opts.map((o,i) => {
      let bg = 'var(--card-bg)';
      if(_prwDrillAnswered){ if(i===d.ans) bg='var(--easy)'; else if(i===_prwPickedIdx) bg='var(--hard)'; }
      return `<button class="btn btn-outline" style="text-align:left;background:${bg}" onclick="prwPickOpt(${i})">${o}</button>`;
    }).join('')}
    </div>
    ${_prwDrillAnswered ? `<button class="btn" style="margin-top:16px" onclick="prwNext()">Next →</button>` : ''}
  </div>`;
}
function prwPickOpt(i){
  if(_prwDrillAnswered) return;
  _prwPickedIdx = i; _prwDrillAnswered = true; _prwDrillScore.total++;
  const d = PRW_DRILLS[_prwDrillIdx % PRW_DRILLS.length];
  const correct = i === d.ans;
  if(correct){ _prwDrillScore.correct++; recordActivity && recordActivity(); incDailyCount && incDailyCount(); addXp && addXp(10); }
  sfx && sfx(correct ? sfxCorrect : sfxWrong);
  renderPrw();
}
function prwNext(){ _prwDrillIdx++; _prwDrillAnswered=false; _prwPickedIdx=null; renderPrw(); }
function _renderPrwTips(c, st){
  if(st) st.textContent = PRW_TIPS.length + ' tips';
  c.innerHTML = PRW_TIPS.map(t => `<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="font-weight:700;margin-bottom:8px">📜 ${t.title}</div>
    <div style="color:var(--muted);line-height:1.6">${t.body}</div>
  </div>`).join('');
}
// coaches-ext self-register
(function(){
  if(typeof TOPICS_CATEGORIES === 'undefined') return;
  var ext = TOPICS_CATEGORIES.find(function(c){ return c.id === 'coaches-ext'; });
  if(!ext) return;
  if(ext.items.some(function(c){ return c.fn === 'openPrw'; })) return;
  ext.items.push({ label: '📜 Proverbs & Wisdom', fn: 'openPrw', desc: 'Lebanese proverbs, amthaal, family/patience/wisdom sayings + MCQ drill' });
})();

