// ── R926 BUG FIX: Normalize slow='ar' from b-IIFEs ──────────────────────────
// b-IIFEs (R919b/R922b/R925b etc.) call _fn(word, 'ar') to signal Arabic bypass.
// 'ar' is truthy → all audio plays at 0.70x instead of 1.0x.
// Fix: patch playAudio + _speakViaBrowser to convert slow='ar' → slow=false.
(function(){
  if(window.__r926SlowFix) return;
  window.__r926SlowFix = true;
  if(typeof playAudio === 'function'){
    var _origPA = playAudio;
    playAudio = function(primaryUrl, fallbackUrl, slow, clearAnim, originalText){
      if(slow === 'ar') slow = false;
      return _origPA.call(this, primaryUrl, fallbackUrl, slow, clearAnim, originalText);
    };
  }
  if(typeof _speakViaBrowser === 'function'){
    var _origSVB = _speakViaBrowser;
    _speakViaBrowser = function(text, slow, clearAnim){
      if(slow === 'ar') slow = false;
      return _origSVB.call(this, text, slow, clearAnim);
    };
  }
})();
