// ── R933: Lebanese Electricity Cuts & Generator Culture (blk) ──────────────
let _blkTab = 'vocab';
let _blkDrillIdx = 0;
let _blkDrillAnswered = false;
let _blkPickedIdx = null;
let _blkDrillScore = { correct: 0, total: 0 };
function openBlk(){
  bumpAchievementCounter && bumpAchievementCounter('blk_open');
  const ov = document.getElementById('blk-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setBlkTab('vocab');
}
function closeBlk(){ const ov=document.getElementById('blk-overlay'); if(ov) ov.style.display='none'; }
function setBlkTab(t){
  _blkTab = t;
  const bar = document.getElementById('blk-tab-bar');
  if(bar){
    const tabs = [['vocab','⚡ Phrases'],['drill','🎯 Drill'],['tips','💡 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_blkTab===k?'active':''}" onclick="setBlkTab('${k}')">${l}</button>`).join('');
  }
  renderBlk();
}
function renderBlk(){
  const el = document.getElementById('blk-content'); if(!el) return;
  const st = document.getElementById('blk-stats');
  if(_blkTab === 'vocab'){
    if(st) st.textContent = BLK_WORDS.length + ' phrases';
    el.innerHTML = '<div style="display:grid;gap:10px">' +
      BLK_WORDS.map(w => `<div class="card" style="display:flex;justify-content:space-between;align-items:center;padding:12px 16px;gap:12px">
        <div style="text-align:right;font-size:1.3rem;font-family:serif">${w.ar}</div>
        <div style="color:var(--muted);font-size:0.85rem;flex:1;text-align:center">${w.tr}</div>
        <div style="flex:1">${w.en}</div>
        <button class="btn btn-sm btn-outline" onclick="speak('${w.ar.replace(/'/g,"\\'")}')">🔊</button>
      </div>`).join('') + '</div>';
  } else if(_blkTab === 'drill'){
    const items = BLK_DRILLS;
    if(st) st.textContent = _blkDrillScore.correct + '/' + _blkDrillScore.total + ' correct';
    if(_blkDrillIdx >= items.length){
      el.innerHTML = `<div class="card" style="text-align:center;padding:32px">
        <div style="font-size:2rem">⚡</div>
        <div style="font-size:1.2rem;font-weight:700;margin:12px 0">Drill complete!</div>
        <div style="color:var(--muted)">${_blkDrillScore.correct}/${items.length} correct</div>
        <button class="btn btn-primary" style="margin-top:16px" onclick="_blkDrillIdx=0;_blkDrillAnswered=false;_blkPickedIdx=null;_blkDrillScore={correct:0,total:0};renderBlk()">Restart</button>
      </div>`; return;
    }
    const q = items[_blkDrillIdx];
    el.innerHTML = `<div class="card" style="padding:24px">
      <div style="font-size:0.8rem;color:var(--muted);margin-bottom:8px">Question ${_blkDrillIdx+1} of ${items.length}</div>
      <div style="font-size:1.1rem;font-weight:600;margin-bottom:18px">${q.q}</div>
      <div style="display:grid;gap:8px">
        ${q.opts.map((o,i) => {
          let cls = 'btn btn-outline'; let suf = '';
          if(_blkDrillAnswered){
            if(i===q.ans){ cls='btn btn-success'; suf=' ✓'; }
            else if(i===_blkPickedIdx){ cls='btn btn-danger'; suf=' ✗'; }
          }
          return `<button class="${cls}" style="text-align:left;padding:10px 14px" ${_blkDrillAnswered?'disabled':''} onclick="blkPickOpt(${i})">${o}${suf}</button>`;
        }).join('')}
      </div>
      ${_blkDrillAnswered ? `<button class="btn btn-primary" style="margin-top:16px;width:100%" onclick="blkNext()">Next →</button>` : ''}
    </div>`;
  } else if(_blkTab === 'tips'){
    if(st) st.textContent = BLK_TIPS.length + ' tips';
    el.innerHTML = '<div style="display:grid;gap:12px">' +
      BLK_TIPS.map((t,i) => `<div class="card" style="padding:16px"><span style="font-weight:700;color:var(--accent)">💡 ${i+1}.</span> ${t}</div>`).join('') + '</div>';
  }
}
function blkPickOpt(i){
  if(_blkDrillAnswered) return;
  _blkDrillAnswered = true; _blkPickedIdx = i;
  const q = BLK_DRILLS[_blkDrillIdx];
  const correct = (i === q.ans);
  _blkDrillScore.total++;
  if(correct){ _blkDrillScore.correct++; addXp && addXp(5); sfx && sfx('correct'); }
  else { sfx && sfx('wrong'); }
  recordActivity && recordActivity('blk_drill');
  incDailyCount && incDailyCount();
  renderBlk();
}
function blkNext(){ _blkDrillIdx++; _blkDrillAnswered=false; _blkPickedIdx=null; renderBlk(); }
// self-register
(function(){
  if(typeof TOPICS_CATEGORIES === 'undefined') return;
  const ext = TOPICS_CATEGORIES.find(c => c.id === 'coaches-ext');
  if(!ext) return;
  if(ext.items.some(x => x.id === 'blk')) return;
  ext.items.push({ id:'blk', label:'⚡ Electricity & Generators', open:'openBlk()' });
})();

