// ── R939: Lebanese Airport Arrival & Beirut Experience (arv) ──────────────────
let _arvTab = 'vocab';
let _arvDrillIdx = 0;
let _arvDrillAnswered = false;
let _arvPickedIdx = null;
let _arvDrillScore = { correct: 0, total: 0 };
function openArv(){
  bumpAchievementCounter && bumpAchievementCounter('arv_open');
  const ov = document.getElementById('arv-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setArvTab('vocab');
}
function closeArv(){ const ov=document.getElementById('arv-overlay'); if(ov) ov.style.display='none'; }
function setArvTab(t){
  _arvTab = t;
  const bar = document.getElementById('arv-tab-bar');
  if(bar){
    const tabs = [['vocab','✈️ Phrases'],['drill','🎯 Drill'],['tips','💡 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_arvTab===k?'active':''}" onclick="setArvTab('${k}')">${l}</button>`).join('');
  }
  renderArv();
}
function renderArv(){
  const el = document.getElementById('arv-content'); if(!el) return;
  const st = document.getElementById('arv-stats');
  if(_arvTab === 'vocab'){
    if(st) st.textContent = ARV_WORDS.length + ' phrases';
    el.innerHTML = '<div style="display:grid;gap:10px">' +
      ARV_WORDS.map(w => `<div class="card" style="display:flex;justify-content:space-between;align-items:center;padding:12px 16px;gap:12px">
        <div style="text-align:right;font-size:1.3rem;font-family:serif">${w.ar}</div>
        <div style="color:var(--muted);font-size:0.85rem;flex:1;text-align:center">${w.tr}</div>
        <div style="flex:1">${w.en}</div>
        <button class="btn btn-sm btn-outline" onclick="speak('${w.ar.replace(/'/g,"\\'")}')">🔊</button>
      </div>`).join('') + '</div>';
  } else if(_arvTab === 'drill'){
    const items = ARV_DRILLS;
    if(st) st.textContent = _arvDrillScore.correct + '/' + _arvDrillScore.total + ' correct';
    if(_arvDrillIdx >= items.length){
      el.innerHTML = `<div class="card" style="text-align:center;padding:32px">
        <div style="font-size:2rem">✈️</div>
        <div style="font-size:1.2rem;font-weight:700;margin:12px 0">Drill complete!</div>
        <div style="color:var(--muted)">${_arvDrillScore.correct}/${items.length} correct</div>
        <button class="btn btn-primary" style="margin-top:16px" onclick="_arvDrillIdx=0;_arvDrillAnswered=false;_arvPickedIdx=null;_arvDrillScore={correct:0,total:0};renderArv()">Restart</button>
      </div>`; return;
    }
    const q = items[_arvDrillIdx];
    el.innerHTML = `<div class="card" style="padding:24px">
      <div style="font-size:0.8rem;color:var(--muted);margin-bottom:8px">Question ${_arvDrillIdx+1} of ${items.length}</div>
      <div style="font-size:1.1rem;font-weight:600;margin-bottom:18px">${q.q}</div>
      <div style="display:grid;gap:8px">
        ${q.opts.map((o,i) => {
          let cls = 'btn btn-outline'; let suf = '';
          if(_arvDrillAnswered){
            if(i===q.ans){ cls='btn btn-success'; suf=' ✓'; }
            else if(i===_arvPickedIdx){ cls='btn btn-danger'; suf=' ✗'; }
          }
          return `<button class="${cls}" style="text-align:left;padding:10px 14px" ${_arvDrillAnswered?'disabled':''} onclick="arvPickOpt(${i})">${o}${suf}</button>`;
        }).join('')}
      </div>
      ${_arvDrillAnswered ? `<button class="btn btn-primary" style="margin-top:16px;width:100%" onclick="arvNext()">Next →</button>` : ''}
    </div>`;
  } else if(_arvTab === 'tips'){
    if(st) st.textContent = ARV_TIPS.length + ' tips';
    el.innerHTML = '<div style="display:grid;gap:12px">' +
      ARV_TIPS.map((t,i) => `<div class="card" style="padding:16px"><span style="font-weight:700;color:var(--accent)">💡 ${i+1}.</span> ${t}</div>`).join('') + '</div>';
  }
}
function arvPickOpt(i){
  if(_arvDrillAnswered) return;
  _arvDrillAnswered = true; _arvPickedIdx = i;
  const q = ARV_DRILLS[_arvDrillIdx];
  const correct = (i === q.ans);
  _arvDrillScore.total++;
  if(correct){ _arvDrillScore.correct++; addXp && addXp(5); sfx && sfx('correct'); }
  else { sfx && sfx('wrong'); }
  recordActivity && recordActivity('arv_drill');
  incDailyCount && incDailyCount();
  renderArv();
}
function arvNext(){ _arvDrillIdx++; _arvDrillAnswered=false; _arvPickedIdx=null; renderArv(); }
