// ── R951 NEW FEATURE: Lebanese Argileh & Café Culture (arg) ────────────────
let _argTab = 'vocab';
let _argDrillIdx = 0;
let _argDrillAnswered = false;
let _argPickedIdx = null;
let _argDrillScore = { correct: 0, total: 0 };
function openArg(){
  bumpAchievementCounter && bumpAchievementCounter('arg_open');
  const ov = document.getElementById('arg-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _argDrillAnswered = false; _argPickedIdx = null; _argDrillIdx = 0; _argDrillScore = { correct: 0, total: 0 };
  setArgTab('vocab');
}
function closeArg(){ const ov=document.getElementById('arg-overlay'); if(ov) ov.style.display='none'; }
function setArgTab(t){
  _argTab = t;
  const bar = document.getElementById('arg-tab-bar');
  if(bar){
    const tabs = [['vocab','🪝 Vocab'],['drill','🎯 Drill'],['tips','💡 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_argTab===k?'active':''}" onclick="setArgTab('${k}')">${l}</button>`).join('');
  }
  renderArg();
}
function renderArg(){
  const el = document.getElementById('arg-content'); if(!el) return;
  const st = document.getElementById('arg-stats');
  if(_argTab === 'vocab'){
    if(st) st.textContent = ARG_WORDS.length + ' terms';
    el.innerHTML = '<div style="display:grid;gap:8px">' +
      ARG_WORDS.map(w => `<div class="card" style="display:flex;justify-content:space-between;align-items:center;padding:12px 16px;gap:12px">
        <div style="text-align:right;font-size:1.3rem;font-family:serif">${w.ar}</div>
        <div style="color:var(--muted);font-size:0.85rem;flex:1;text-align:center">${w.tr}</div>
        <div style="flex:1">${w.en}</div>
        <button class="btn btn-sm btn-outline" onclick="speak('${w.ar.replace(/'/g,"\\'")}')">🔊</button></div>`).join('') + '</div>';
  } else if(_argTab === 'drill'){
    if(typeof ARG_DRILLS === 'undefined' || !ARG_DRILLS.length){ el.innerHTML='<p>No drills.</p>'; return; }
    const idx = _argDrillIdx % ARG_DRILLS.length;
    const d = ARG_DRILLS[idx];
    if(st) st.textContent = `${_argDrillScore.correct}/${_argDrillScore.total} · Q${idx+1}/${ARG_DRILLS.length}`;
    const optsHtml = d.opts.map((o,i) => {
      let style = '';
      if(_argDrillAnswered){
        if(i===d.ans) style='background:#d4edda;color:#155724;border-color:#c3e6cb';
        else if(i===_argPickedIdx) style='background:#f8d7da;color:#721c24;border-color:#f5c6cb';
      }
      return `<button class="btn btn-outline" style="width:100%;text-align:left;margin-bottom:6px;${style}" onclick="argPickOpt(${i})" ${_argDrillAnswered?'disabled':''}>${o}</button>`;
    }).join('');
    el.innerHTML = `<div class="card" style="padding:20px;max-width:560px;margin:0 auto">
      <div style="font-size:0.8rem;color:var(--muted);margin-bottom:8px">Question ${idx+1} / ${ARG_DRILLS.length}</div>
      <div style="font-size:1.1rem;font-weight:600;margin-bottom:16px">${d.q}</div>
      <div>${optsHtml}</div>
      ${_argDrillAnswered ? `<button class="btn btn-primary" style="margin-top:14px" onclick="argNext()">Next →</button>` : ''}
    </div>`;
  } else {
    if(st) st.textContent = ARG_TIPS.length + ' tips';
    el.innerHTML = '<div style="display:grid;gap:14px">' +
      ARG_TIPS.map((t,i) => `<div class="card" style="padding:16px;line-height:1.6"><span style="font-weight:700;color:var(--accent)">💡 Tip ${i+1}:</span> ${t}</div>`).join('') + '</div>';
  }
}
function argPickOpt(i){
  if(_argDrillAnswered) return;
  _argDrillAnswered = true; _argPickedIdx = i;
  const d = ARG_DRILLS[_argDrillIdx % ARG_DRILLS.length];
  const correct = (i === d.ans);
  _argDrillScore.total++;
  if(correct){ _argDrillScore.correct++; addXp && addXp(5); sfx && sfx('correct'); }
  else { sfx && sfx('wrong'); }
  recordActivity && recordActivity('arg_drill');
  incDailyCount && incDailyCount();
  renderArg();
}
function argNext(){ _argDrillIdx++; _argDrillAnswered=false; _argPickedIdx=null; renderArg(); }
