let _smcTab = 'vocab';
let _smcDrillIdx = 0;
let _smcDrillAnswered = false;
let _smcPickedIdx = null;
let _smcDrillScore = { correct: 0, total: 0 };

function openSmc(){
  bumpAchievementCounter && bumpAchievementCounter('smc_open');
  const ov = document.getElementById('smc-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _smcDrillIdx = 0; _smcDrillAnswered = false; _smcPickedIdx = null; _smcDrillScore = { correct: 0, total: 0 };
  setSmcTab('vocab');
}
function closeSmc(){ const ov = document.getElementById('smc-overlay'); if(ov) ov.style.display = 'none'; }

function setSmcTab(t){
  _smcTab = t;
  const bar = document.getElementById('smc-tab-bar');
  if(bar){
    const tabs = [['vocab','📱 Vocab'],['drill','🎯 Drill'],['tips','💡 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_smcTab===k?'active':''}" onclick="setSmcTab('${k}')">${l}</button>`).join('');
  }
  renderSmc();
}

function renderSmc(){
  const el = document.getElementById('smc-content'); if(!el) return;
  const st = document.getElementById('smc-stats');
  if(_smcTab === 'vocab'){
    if(st) st.textContent = SMC_WORDS.length + ' terms';
    el.innerHTML = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:10px">' +
      SMC_WORDS.map(w => `<div class="card" style="padding:14px">
        <div style="font-size:1.4rem;font-weight:700">${w.ar}</div>
        <div style="color:var(--muted);font-size:0.85rem;margin:2px 0">${w.tr}</div>
        <div style="font-size:0.92rem">${w.en}</div>
      </div>`).join('') + '</div>';
  } else if(_smcTab === 'drill'){
    if(st) st.textContent = _smcDrillScore.correct + '/' + _smcDrillScore.total + ' correct';
    const items = SMC_DRILLS;
    if(_smcDrillIdx >= items.length){
      el.innerHTML = `<div class="card" style="text-align:center;padding:32px">
        <div style="font-size:2rem">🎉</div>
        <div style="font-weight:700;margin:8px 0">Drill complete!</div>
        <div style="color:var(--muted)">${_smcDrillScore.correct}/${items.length} correct</div>
        <button class="btn btn-primary" style="margin-top:16px" onclick="_smcDrillIdx=0;_smcDrillAnswered=false;_smcPickedIdx=null;_smcDrillScore={correct:0,total:0};renderSmc()">Restart</button>
      </div>`; return;
    }
    const q = items[_smcDrillIdx];
    el.innerHTML = `<div class="card" style="padding:20px;max-width:560px;margin:0 auto">
      <div style="font-size:0.8rem;color:var(--muted);margin-bottom:8px">Question ${_smcDrillIdx+1} of ${items.length}</div>
      <div style="font-size:1.1rem;font-weight:600;margin-bottom:16px">${q.q}</div>
      <div style="display:grid;gap:8px">
        ${q.opts.map((o,i) => {
          let cls = 'btn btn-outline';
          let suf = '';
          if(_smcDrillAnswered){
            if(i === q.ans){ cls='btn btn-success'; suf=' ✓'; }
            else if(i === _smcPickedIdx){ cls='btn btn-danger'; suf=' ✗'; }
          }
          return `<button class="${cls}" style="text-align:left;padding:10px 14px" ${_smcDrillAnswered?'disabled':''} onclick="smcPickOpt(${i})">${o}${suf}</button>`;
        }).join('')}
      </div>
      ${_smcDrillAnswered ? `<button class="btn btn-primary" style="margin-top:16px;width:100%" onclick="smcNext()">Next →</button>` : ''}
    </div>`;
  } else {
    if(st) st.textContent = SMC_TIPS.length + ' tips';
    el.innerHTML = SMC_TIPS.map((tip,i) => `<div class="card" style="padding:16px;margin-bottom:10px">
      <div style="font-weight:700;margin-bottom:6px">💡 Tip ${i+1}</div>
      <div style="line-height:1.6">${tip}</div>
    </div>`).join('');
  }
}

function smcPickOpt(i){
  if(_smcDrillAnswered) return;
  _smcPickedIdx = i;
  _smcDrillAnswered = true;
  const q = SMC_DRILLS[_smcDrillIdx];
  if(i === q.ans){
    _smcDrillScore.correct++;
    addXp && addXp(5);
    if(typeof sfx !== 'undefined') sfx('correct');
  } else {
    if(typeof sfx !== 'undefined') sfx('wrong');
  }
  _smcDrillScore.total++;
  recordActivity && recordActivity('smc_drill');
  incDailyCount && incDailyCount();
  renderSmc();
}

function smcNext(){
  _smcDrillIdx++;
  _smcDrillAnswered = false;
  _smcPickedIdx = null;
  renderSmc();
}

