// ── R963 NEW FEATURE: Lebanese Thawra & Protest Culture (rev) ─────────────────
let _revTab = 'vocab';
let _revDrillIdx = 0;
let _revDrillAnswered = false;
let _revPickedIdx = null;
let _revDrillScore = { correct: 0, total: 0 };

function openRev(){
  bumpAchievementCounter && bumpAchievementCounter('rev_open');
  const ov = document.getElementById('rev-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _revDrillIdx = 0; _revDrillAnswered = false; _revPickedIdx = null; _revDrillScore = { correct: 0, total: 0 };
  setRevTab('vocab');
}
function closeRev(){ const ov = document.getElementById('rev-overlay'); if(ov) ov.style.display = 'none'; }

function setRevTab(t){
  _revTab = t;
  const bar = document.getElementById('rev-tab-bar');
  if(bar){
    const tabs = [['vocab','✊ Vocab'],['drill','🎯 Drill'],['tips','💡 History']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_revTab===k?'active':''}" onclick="setRevTab('${k}')">${l}</button>`).join('');
  }
  renderRev();
}

function renderRev(){
  const el = document.getElementById('rev-content'); if(!el) return;
  const st = document.getElementById('rev-stats');
  if(_revTab === 'vocab'){
    if(st) st.textContent = REV_WORDS.length + ' terms';
    el.innerHTML = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:10px">' +
      REV_WORDS.map(w => `<div class="card" style="padding:14px">
        <div style="font-size:1.4rem;font-weight:700">${w.ar}</div>
        <div style="color:var(--muted);font-size:0.85rem;margin:2px 0">${w.tr}</div>
        <div style="font-size:0.92rem">${w.en}</div>
      </div>`).join('') + '</div>';
  } else if(_revTab === 'drill'){
    if(st) st.textContent = _revDrillScore.correct + '/' + _revDrillScore.total + ' correct';
    const items = REV_DRILLS;
    if(_revDrillIdx >= items.length){
      el.innerHTML = `<div class="card" style="text-align:center;padding:32px">
        <div style="font-size:2rem">🎉</div>
        <div style="font-weight:700;margin:8px 0">Drill complete!</div>
        <div style="color:var(--muted)">${_revDrillScore.correct}/${items.length} correct</div>
        <button class="btn btn-primary" style="margin-top:16px" onclick="_revDrillIdx=0;_revDrillAnswered=false;_revPickedIdx=null;_revDrillScore={correct:0,total:0};renderRev()">Restart</button>
      </div>`; return;
    }
    const q = items[_revDrillIdx];
    el.innerHTML = `<div class="card" style="padding:20px;max-width:560px;margin:0 auto">
      <div style="font-size:0.8rem;color:var(--muted);margin-bottom:8px">Question ${_revDrillIdx+1} of ${items.length}</div>
      <div style="font-size:1.1rem;font-weight:600;margin-bottom:16px">${q.q}</div>
      <div style="display:grid;gap:8px">
        ${q.opts.map((o,i) => {
          let cls = 'btn btn-outline';
          let suf = '';
          if(_revDrillAnswered){
            if(i === q.ans){ cls='btn btn-success'; suf=' ✓'; }
            else if(i === _revPickedIdx){ cls='btn btn-danger'; suf=' ✗'; }
          }
          return `<button class="${cls}" style="text-align:left;padding:10px 14px" ${_revDrillAnswered?'disabled':''} onclick="revPickOpt(${i})">${o}${suf}</button>`;
        }).join('')}
      </div>
      ${_revDrillAnswered ? `<button class="btn btn-primary" style="margin-top:16px;width:100%" onclick="revNext()">Next →</button>` : ''}
    </div>`;
  } else {
    if(st) st.textContent = REV_TIPS.length + ' entries';
    el.innerHTML = REV_TIPS.map((tip,i) => `<div class="card" style="padding:16px;margin-bottom:10px">
      <div style="font-weight:700;margin-bottom:6px">✊ Tip ${i+1}</div>
      <div style="line-height:1.6">${tip}</div>
    </div>`).join('');
  }
}

function revPickOpt(i){
  if(_revDrillAnswered) return;
  _revPickedIdx = i;
  _revDrillAnswered = true;
  const q = REV_DRILLS[_revDrillIdx];
  if(i === q.ans){
    _revDrillScore.correct++;
    addXp && addXp(5);
    if(typeof sfx !== 'undefined') sfx('correct');
  } else {
    if(typeof sfx !== 'undefined') sfx('wrong');
  }
  _revDrillScore.total++;
  recordActivity && recordActivity('rev_drill');
  incDailyCount && incDailyCount();
  renderRev();
}

function revNext(){
  _revDrillIdx++;
  _revDrillAnswered = false;
  _revPickedIdx = null;
  renderRev();
}

// self-register in coaches-ext
(function(){
  if(typeof TOPICS_CATEGORIES === 'undefined') return;
  var ext = TOPICS_CATEGORIES.find(function(c){ return c.id === 'coaches-ext'; });
  if(!ext) return;
  if(ext.items.some(function(x){ return x.id === 'rev'; })) return;
  ext.items.push({ id:'rev', label:'✊ Thawra & Protest', fn:'openRev', desc:'Lebanese revolution vocab, protest chants, political demands, 2019 Thawra expressions + drill' });
})();
