// ── R969 NEW FEATURE: Lebanese Frustration & Venting Expressions (frs) ────────
let _frsTab = 'vocab';
let _frsDrillIdx = 0;
let _frsDrillAnswered = false;
let _frsPickedIdx = null;
let _frsDrillScore = { correct: 0, total: 0 };

function openFrs(){
  bumpAchievementCounter && bumpAchievementCounter('frs_open');
  const ov = document.getElementById('frs-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _frsDrillIdx = 0; _frsDrillAnswered = false; _frsPickedIdx = null; _frsDrillScore = {correct:0,total:0};
  setFrsTab('vocab');
}
function closeFrs(){ const ov=document.getElementById('frs-overlay'); if(ov) ov.style.display='none'; }
function setFrsTab(t){
  _frsTab = t;
  const bar = document.getElementById('frs-tab-bar');
  if(bar){
    const tabs = [['vocab','😤 Vocab'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_frsTab===k?'active':''}" onclick="setFrsTab('${k}')">${l}</button>`).join('');
  }
  renderFrs();
}
function renderFrs(){
  const el = document.getElementById('frs-content');
  const st = document.getElementById('frs-stats');
  if(!el) return;
  if(_frsTab === 'vocab'){
    if(st) st.textContent = FRS_WORDS.length + ' expressions';
    el.innerHTML = FRS_WORDS.map((w,i) => `<div class="card" style="padding:14px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center">
      <div>
        <div style="font-size:1.3rem;font-weight:700">${w.ar}</div>
        <div style="color:var(--muted);font-size:0.85rem">${w.tr}</div>
      </div>
      <div style="text-align:right;max-width:55%">${w.en}</div>
    </div>`).join('');
  } else if(_frsTab === 'drill'){
    if(st) st.textContent = `${_frsDrillScore.correct}/${_frsDrillScore.total} correct`;
    const q = FRS_DRILLS[_frsDrillIdx % FRS_DRILLS.length];
    el.innerHTML = `<div class="card" style="padding:20px">
      <div style="font-weight:700;font-size:1.05rem;margin-bottom:16px">Q${(_frsDrillIdx%FRS_DRILLS.length)+1}/${FRS_DRILLS.length}: ${q.q}</div>
      <div style="display:grid;gap:8px">
        ${q.opts.map((o,i) => {
          let cls='btn btn-outline'; let suf='';
          if(_frsDrillAnswered){
            if(i===q.ans){ cls='btn btn-success'; suf=' ✓'; }
            else if(i===_frsPickedIdx){ cls='btn btn-danger'; suf=' ✗'; }
          }
          return `<button class="${cls}" style="text-align:left;padding:10px 14px" ${_frsDrillAnswered?'disabled':''} onclick="frsPickOpt(${i})">${o}${suf}</button>`;
        }).join('')}
      </div>
      ${_frsDrillAnswered ? `<button class="btn btn-primary" style="margin-top:16px;width:100%" onclick="frsNext()">Next →</button>` : ''}
    </div>`;
  } else {
    if(st) st.textContent = FRS_TIPS.length + ' entries';
    el.innerHTML = FRS_TIPS.map((tip,i) => `<div class="card" style="padding:16px;margin-bottom:10px">
      <div style="font-weight:700;margin-bottom:6px">😤 Tip ${i+1}</div>
      <div style="line-height:1.6">${tip}</div>
    </div>`).join('');
  }
}

function frsPickOpt(i){
  if(_frsDrillAnswered) return;
  _frsPickedIdx = i;
  _frsDrillAnswered = true;
  const q = FRS_DRILLS[_frsDrillIdx % FRS_DRILLS.length];
  if(i === q.ans){
    _frsDrillScore.correct++;
    addXp && addXp(5);
    if(typeof sfx !== 'undefined') sfx('correct');
  } else {
    if(typeof sfx !== 'undefined') sfx('wrong');
  }
  _frsDrillScore.total++;
  recordActivity && recordActivity('frs_drill');
  incDailyCount && incDailyCount();
  renderFrs();
}

function frsNext(){
  _frsDrillIdx++;
  _frsDrillAnswered = false;
  _frsPickedIdx = null;
  renderFrs();
}

// self-register in coaches-ext
(function(){
  if(typeof TOPICS_CATEGORIES === 'undefined') return;
  var ext = TOPICS_CATEGORIES.find(function(c){ return c.id === 'coaches-ext'; });
  if(!ext) return;
  if(ext.items.some(function(x){ return x.id === 'frs'; })) return;
  ext.items.push({ id:'frs', label:'😤 Frustration & Venting', fn:'openFrs', desc:'Lebanese expressions of frustration, resignation, venting & dark humor in daily life + drill' });
})();
