function closeBkq(){ const ov=document.getElementById('bkq-overlay'); if(ov) ov.style.display='none'; }
function setBkqTab(t){
  _bkqTab = t;
  const bar = document.getElementById('bkq-tab-bar');
  if(bar){
    const tabs = [['vocab','📋 Vocab'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_bkqTab===k?'active':''}" onclick="setBkqTab('${k}')">${l}</button>`).join('');
  }
  renderBkq();
}
function renderBkq(){
  const el = document.getElementById('bkq-content'); if(!el) return;
  const st = document.getElementById('bkq-stats');
  if(_bkqTab === 'vocab'){
    if(st) st.textContent = (typeof BKQ_WORDS !== 'undefined') ? BKQ_WORDS.length + ' words' : '';
    const words = (typeof BKQ_WORDS !== 'undefined') ? BKQ_WORDS : [];
    el.innerHTML = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:10px">' +
      words.map(w => `<div class="card" style="padding:12px"><div style="font-size:1.4rem;font-weight:700" onclick="speak('${w.ar}')">${w.ar}</div><div style="color:var(--muted);font-size:0.85rem">${w.tr}</div><div style="margin-top:4px">${w.en}</div></div>`).join('') +
      '</div>';
  } else if(_bkqTab === 'drill'){
    const drills = (typeof BKQ_DRILLS !== 'undefined') ? BKQ_DRILLS : [];
    if(st) st.textContent = `${_bkqDrillScore.correct}/${_bkqDrillScore.total} · Q${_bkqDrillIdx+1}/${drills.length}`;
    if(!drills.length){ el.innerHTML = '<p>No drills.</p>'; return; }
    if(_bkqDrillIdx >= drills.length){ el.innerHTML = `<div class="card" style="text-align:center;padding:24px"><div style="font-size:1.5rem">✅ Done!</div><div>${_bkqDrillScore.correct}/${_bkqDrillScore.total} correct</div><button class="btn" onclick="_bkqDrillIdx=0;_bkqDrillScore={correct:0,total:0};renderBkq()">Restart</button></div>`; return; }
    const d = drills[_bkqDrillIdx];
    el.innerHTML = `<div class="card" style="padding:20px"><div style="font-size:1.1rem;font-weight:600;margin-bottom:16px">${d.q}</div><div style="display:grid;gap:8px">${d.opts.map((o,i) => `<button class="btn ${_bkqDrillAnswered?(i===d.ans?'btn-success':(i===_bkqPickedIdx?'btn-danger':'btn-outline')):'btn-outline'}" onclick="bkqPickOpt(${i})" ${_bkqDrillAnswered?'disabled':''}>${o}</button>`).join('')}</div>${_bkqDrillAnswered?`<button class="btn" style="margin-top:14px" onclick="bkqNext()">Next →</button>`:''}</div>`;
  } else if(_bkqTab === 'tips'){
    const tips = (typeof BKQ_TIPS !== 'undefined') ? BKQ_TIPS : [];
    if(st) st.textContent = tips.length + ' tips';
    el.innerHTML = tips.map((t,i) => `<div class="card" style="padding:16px;margin-bottom:10px"><div style="font-weight:700;margin-bottom:6px">Tip ${i+1}</div><div>${t}</div></div>`).join('');
  }
}
function bkqPickOpt(i){
  if(_bkqDrillAnswered) return;
  _bkqPickedIdx = i;
  _bkqDrillAnswered = true;
  const drills = (typeof BKQ_DRILLS !== 'undefined') ? BKQ_DRILLS : [];
  if(i === drills[_bkqDrillIdx].ans) _bkqDrillScore.correct++;
  _bkqDrillScore.total++;
  renderBkq();
}
function bkqNext(){
  _bkqDrillIdx++;
  _bkqDrillAnswered = false;
  _bkqPickedIdx = null;
  renderBkq();
}

