// ── R975 NEW FEATURE: Lebanese Teta & Traditional Wisdom (tet) ────────────────
let _tetTab = 'vocab';
let _tetDrillIdx = 0;
let _tetDrillAnswered = false;
let _tetPickedIdx = null;
let _tetDrillScore = { correct: 0, total: 0 };

function openTet(){
  bumpAchievementCounter && bumpAchievementCounter('tet_open');
  const ov = document.getElementById('tet-overlay'); if(!ov) return;
  _tetDrillIdx = 0; _tetDrillAnswered = false; _tetPickedIdx = null; _tetDrillScore = { correct: 0, total: 0 };
  ov.style.display = 'block';
  setTetTab('vocab');
}
function closeTet(){ const ov=document.getElementById('tet-overlay'); if(ov) ov.style.display='none'; }
function setTetTab(t){
  _tetTab = t;
  const bar = document.getElementById('tet-tab-bar');
  if(bar){
    const tabs = [['vocab','📋 Vocab'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_tetTab===k?'active':''}" onclick="setTetTab('${k}')">${l}</button>`).join('');
  }
  renderTet();
}
function renderTet(){
  const el = document.getElementById('tet-content'); if(!el) return;
  const st = document.getElementById('tet-stats');
  if(_tetTab === 'vocab'){
    if(st) st.textContent = (typeof TET_WORDS !== 'undefined') ? TET_WORDS.length + ' words' : '';
    const words = (typeof TET_WORDS !== 'undefined') ? TET_WORDS : [];
    el.innerHTML = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:10px">' +
      words.map(w => `<div class="card" style="padding:12px"><div style="font-size:1.4rem;font-weight:700" onclick="speak('${w.ar}')">${w.ar}</div><div style="color:var(--muted);font-size:0.85rem">${w.tr}</div><div style="margin-top:4px">${w.en}</div></div>`).join('') +
      '</div>';
  } else if(_tetTab === 'drill'){
    const drills = (typeof TET_DRILLS !== 'undefined') ? TET_DRILLS : [];
    if(st) st.textContent = `${_tetDrillScore.correct}/${_tetDrillScore.total} · Q${_tetDrillIdx+1}/${drills.length}`;
    if(!drills.length){ el.innerHTML = '<p>No drills.</p>'; return; }
    if(_tetDrillIdx >= drills.length){ el.innerHTML = `<div class="card" style="text-align:center;padding:24px"><div style="font-size:1.5rem">✅ Done!</div><div>${_tetDrillScore.correct}/${_tetDrillScore.total} correct</div><button class="btn" onclick="_tetDrillIdx=0;_tetDrillScore={correct:0,total:0};renderTet()">Restart</button></div>`; return; }
    const d = drills[_tetDrillIdx];
    el.innerHTML = `<div class="card" style="padding:20px"><div style="font-size:1.1rem;font-weight:600;margin-bottom:16px">${d.q}</div><div style="display:grid;gap:8px">${d.opts.map((o,i) => `<button class="btn ${_tetDrillAnswered?(i===d.ans?'btn-success':(i===_tetPickedIdx?'btn-danger':'btn-outline')):'btn-outline'}" onclick="tetPickOpt(${i})" ${_tetDrillAnswered?'disabled':''}>${o}</button>`).join('')}</div>${_tetDrillAnswered?`<button class="btn" style="margin-top:14px" onclick="tetNext()">Next →</button>`:''}</div>`;
  } else if(_tetTab === 'tips'){
    const tips = (typeof TET_TIPS !== 'undefined') ? TET_TIPS : [];
    if(st) st.textContent = tips.length + ' tips';
    el.innerHTML = tips.map((t,i) => `<div class="card" style="padding:16px;margin-bottom:10px"><div style="font-weight:700;margin-bottom:6px">Tip ${i+1}</div><div>${t}</div></div>`).join('');
  }
}
function tetPickOpt(i){
  if(_tetDrillAnswered) return;
  _tetPickedIdx = i;
  _tetDrillAnswered = true;
  const drills = (typeof TET_DRILLS !== 'undefined') ? TET_DRILLS : [];
  if(i === drills[_tetDrillIdx].ans) _tetDrillScore.correct++;
  _tetDrillScore.total++;
  renderTet();
}
function tetNext(){
  _tetDrillIdx++;
  _tetDrillAnswered = false;
  _tetPickedIdx = null;
  renderTet();
}

