    const ok = _sajPickedIdx === d.correct;
    html += `<div style="margin-top:10px;color:${ok?'#3fb950':'#e06060'};font-weight:600">${ok?'✓ Correct!':'✗ Wrong — '+_sajEsc(d.opts[d.correct])}</div>`;
