// ── R1001 BUG FIX: 18 coach word-card render fns call speak(w.tr) not speak(w.ar)
// Wrap speak() to intercept transliteration keys and redirect to Arabic.
// Affected: ELC/MIG/BTY/CNS/BKF/GRG/WYN/BSP/SDL/SAT/MNH/BRB/BUR/CIN/GSP/TBL/OLH/BLD
(function(){
  if(window.__r1001SpeakTrFix) return;
  window.__r1001SpeakTrFix = true;
  var _names = ['ELC_WORDS','MIG_WORDS','BTY_WORDS','CNS_WORDS','BKF_WORDS',
    'GRG_WORDS','WYN_WORDS','BSP_WORDS','SDL_WORDS','SAT_WORDS','MNH_WORDS',
    'BRB_WORDS','BUR_WORDS','CIN_WORDS','GSP_WORDS','TBL_WORDS','OLH_WORDS','BLD_WORDS'];
  var _trToAr = Object.create(null);
  _names.forEach(function(n){
    var arr = typeof window[n] !== 'undefined' ? window[n] : [];
    if(!Array.isArray(arr)) return;
    arr.forEach(function(w){
      var arabic = w.ar || w.a;
      if(w.tr && arabic) _trToAr[w.tr] = arabic;
    });
  });
  var _prev1001 = speak;
  speak = function(word, slow, externalBtn){
    if(word && slow !== 'ar' && _trToAr[word]) return _prev1001(_trToAr[word], slow, externalBtn);
    return _prev1001(word, slow, externalBtn);
  };
  if(window.__audioFlagsKnown){ Object.keys(window.__audioFlagsKnown).forEach(function(f){ try{speak[f]=_prev1001[f];}catch(e){}; }); }
  speak.__r1001TrFix = true;
  if(window.__audioFlagsKnown) window.__audioFlagsKnown['__r1001TrFix'] = true;
})();
