// ── R1005 NEW FEATURE ── Lebanese Pharmacy & Self-Medication Culture (phx) ──
let _phxTab = 'vocab';
let _phxCat = 'all';
let _phxDrillIdx = 0;
let _phxDrillScore = { correct: 0, total: 0 };
let _phxDrillPicked = false;
function openPhx(){
  bumpAchievementCounter && bumpAchievementCounter('phx_open');
  const ov = document.getElementById('phx-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setPhxTab('vocab');
}
function closePhx(){ const ov=document.getElementById('phx-overlay'); if(ov) ov.style.display='none'; }
function setPhxTab(t){
  _phxTab = t;
  const bar = document.getElementById('phx-tab-bar');
  if(bar){
    const tabs = [['vocab','💊 Vocab'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_phxTab===k?'active':''}" onclick="setPhxTab('${k}')">${l}</button>`).join('');
  }
  renderPhx();
}
function renderPhx(){
  const el = document.getElementById('phx-content');
  const st = document.getElementById('phx-stats');
  if(!el) return;
  if(_phxTab==='vocab') _renderPhxVocab(el, st);
  else if(_phxTab==='drill') _renderPhxDrill(el, st);
  else _renderPhxTips(el, st);
}
function _phxSetCat(c){ _phxCat=c; renderPhx(); }
function _renderPhxVocab(el, st){
  const cats = typeof PHX_CATS!=='undefined'?PHX_CATS:[];
  const words = typeof PHX_WORDS!=='undefined'?PHX_WORDS:[];
  const filtered = _phxCat==='all'?words:words.filter(w=>w.cat===_phxCat);
  if(st) st.textContent = filtered.length+' / '+words.length+' words';
  const catBar = [['all','🏥 All'],...cats.map(c=>[c,c.charAt(0).toUpperCase()+c.slice(1)])].map(([c,l])=>`<button class="cat-filter ${_phxCat===c?'active':''}" onclick="_phxSetCat('${c}')">${l}</button>`).join('');
  el.innerHTML = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">${catBar}</div>`
    + `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">`
    + filtered.map(w=>`<div class="card" style="padding:14px;cursor:pointer" onclick="speak('${w.ar.replace(/'/g,"\\'")}')">
        <div style="font-size:1.3rem;font-weight:700">${w.ar}</div>
        <div style="color:var(--accent);font-size:0.95rem">${w.tr}</div>
        <div style="color:var(--muted);font-size:0.85rem">${w.en}</div>
      </div>`).join('')
    + '</div>';
}
function _renderPhxDrill(el, st){
  if(typeof PHX_DRILLS==='undefined'||!PHX_DRILLS.length){el.innerHTML='<p>No drills.</p>';return;}
  _phxDrillPicked = false;
  const d = PHX_DRILLS[_phxDrillIdx % PHX_DRILLS.length];
  if(st) st.textContent = (_phxDrillIdx % PHX_DRILLS.length + 1)+'/'+PHX_DRILLS.length+' · '+_phxDrillScore.correct+'/'+_phxDrillScore.total+' correct';
  el.innerHTML = `<div class="card" style="padding:20px;max-width:560px;margin:0 auto">
    <div style="font-size:1.05rem;font-weight:600;margin-bottom:16px">${d.q}</div>
    <div style="display:flex;flex-direction:column;gap:8px">`
    + d.opts.map((opt,i)=>`<button class="btn btn-outline" id="phx-opt-${i}" onclick="phxPickOpt(${i})" style="text-align:left;padding:10px 14px">${opt}</button>`).join('')
    + `</div><div id="phx-feedback" style="margin-top:14px;font-size:1rem"></div>
    <button class="btn btn-outline" style="margin-top:12px" onclick="phxNext()">Next ▶</button>
  </div>`;
}
function phxPickOpt(i){
  if(_phxDrillPicked) return;
  _phxDrillPicked = true;
  const d = PHX_DRILLS[_phxDrillIdx % PHX_DRILLS.length];
  const correct = i === d.ans;
  _phxDrillScore.total++;
  if(correct) _phxDrillScore.correct++;
  incDailyCount && incDailyCount();
  addXp && addXp(correct?10:2);
  recordActivity && recordActivity();
  const fb = document.getElementById('phx-feedback');
  if(fb) fb.innerHTML = correct ? '<span style="color:var(--success)">✓ Correct!</span>' : `<span style="color:var(--danger)">✗ Answer: ${d.opts[d.ans]}</span>`;
  for(let j=0;j<d.opts.length;j++){
    const b=document.getElementById('phx-opt-'+j);
    if(b){ b.disabled=true; if(j===d.ans) b.style.background='var(--success-bg,#d1fae5)'; else if(j===i) b.style.background='var(--danger-bg,#fee2e2)'; }
  }
}
function phxNext(){
  _phxDrillIdx++;
  _phxDrillPicked = false;
  renderPhx();
}
function _renderPhxTips(el, st){
  if(st) st.textContent = '';
  if(typeof PHX_TIPS==='undefined'||!PHX_TIPS.length){el.innerHTML='<p>No tips.</p>';return;}
  el.innerHTML = `<div style="display:flex;flex-direction:column;gap:14px">`
    + PHX_TIPS.map(t=>`<div class="card" style="padding:16px">
        <div style="font-weight:700;margin-bottom:8px">${t.title}</div>
        <div style="color:var(--muted);font-size:0.95rem;line-height:1.5">${t.body}</div>
      </div>`).join('')
    + '</div>';
}
(function(){
  if(typeof TOPICS_CATEGORIES==='undefined') return;
  const ext = TOPICS_CATEGORIES.find(c=>c.id==='coaches-ext');
  if(ext&&!ext.items.some(x=>x.id==='phx')) ext.items.push({id:'phx',label:'💊 Pharmacy',fn:'openPhx'});
})();

