// ── R1017 NEW FEATURE: Lebanese Supermarket & Grocery Shopping (groc) ────────
let _grocTab = 'vocab';
let _grocCat = 'all';
let _grocDrillIdx = 0;
let _grocDrillScore = { correct: 0, total: 0 };
let _grocDrillPicked = false;
let _grocPickedIdx = null;
function openGroc(){
  bumpAchievementCounter && bumpAchievementCounter('groc_open');
  const ov = document.getElementById('groc-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _grocDrillIdx = 0; _grocDrillPicked = false; _grocPickedIdx = null; _grocDrillScore = { correct: 0, total: 0 };
  setGrocTab('vocab');
}
function closeGroc(){ const ov=document.getElementById('groc-overlay'); if(ov) ov.style.display='none'; }
function setGrocTab(t){
  _grocTab = t;
  const bar = document.getElementById('groc-tab-bar');
  if(bar){
    const tabs = [['vocab','🛒 Vocab'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_grocTab===k?'active':''}" onclick="setGrocTab('${k}')">${l}</button>`).join('');
  }
  renderGroc();
}
function renderGroc(){
  const el = document.getElementById('groc-content');
  const st = document.getElementById('groc-stats');
  if(!el) return;
  if(_grocTab === 'vocab') _renderGrocVocab(el, st);
  else if(_grocTab === 'drill') _renderGrocDrill(el, st);
  else if(_grocTab === 'tips') _renderGrocTips(el, st);
}
function _grocSetCat(c){
  _grocCat = c;
  renderGroc();
}
function _renderGrocVocab(el, st){
  const words = typeof GROC_WORDS !== 'undefined' ? GROC_WORDS : [];
  const cats = typeof GROC_CATS !== 'undefined' ? GROC_CATS : [];
  const filtered = _grocCat === 'all' ? words : words.filter(w => w.cat === _grocCat);
  if(st) st.textContent = `${filtered.length} words`;
  let h = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px">
    <button class="cat-filter ${_grocCat==='all'?'active':''}" onclick="_grocSetCat('all')">All</button>
    ${cats.map(c=>`<button class="cat-filter ${_grocCat===c?'active':''}" onclick="_grocSetCat('${c}')">${c}</button>`).join('')}
  </div><div style="display:grid;gap:8px">`;
  filtered.forEach(w => {
    h += `<div class="word-card" style="cursor:pointer" onclick="speak('${w.tr}')">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <div>
          <span style="font-size:1.2rem;font-weight:600">${w.ar}</span>
          <span style="margin-left:12px;color:var(--muted)">${w.tr}</span>
        </div>
        <span style="color:var(--text-secondary)">${w.en}</span>
      </div>
    </div>`;
  });
  el.innerHTML = h + '</div>';
}
function _renderGrocDrill(el, st){
  const drills = typeof GROC_DRILLS !== 'undefined' ? GROC_DRILLS : [];
  if(!drills.length){ el.innerHTML='<p>No drills.</p>'; return; }
  const d = drills[_grocDrillIdx % drills.length];
  const pct = drills.length > 0 ? Math.round((_grocDrillScore.correct/_grocDrillScore.total||0)*100) : 0;
  if(st) st.textContent = `${_grocDrillScore.correct}/${_grocDrillScore.total} correct`;
  let h = `<div style="margin-bottom:16px;font-size:0.85rem;color:var(--muted)">Question ${(_grocDrillIdx%drills.length)+1}/${drills.length}</div>
  <div style="font-size:1.1rem;font-weight:600;margin-bottom:20px">${d.q}</div>
  <div style="display:grid;gap:10px" id="groc-opts">`;
  d.opts.forEach((o,i) => {
    const picked = _grocDrillPicked;
    const correct = i === d.ans;
    const chosen = i === _grocPickedIdx;
    let bg = '';
    if(picked && correct) bg = 'background:var(--success-bg,#d1fae5)';
    else if(picked && chosen) bg = 'background:var(--danger-bg,#fee2e2)';
    h += `<button id="groc-opt-${i}" class="btn btn-outline" style="text-align:left;${bg}" ${picked?'disabled':''} onclick="grocPickOpt(${i})">${o}</button>`;
  });
  h += `</div><div id="groc-feedback" style="margin-top:14px;font-weight:600"></div>`;
  if(_grocDrillPicked) h += `<button class="btn btn-primary" style="margin-top:16px" onclick="grocNext()">Next →</button>`;
  el.innerHTML = h;
  if(_grocDrillPicked){
    const fb = document.getElementById('groc-feedback');
    if(fb) fb.innerHTML = _grocPickedIdx===d.ans
      ? '<span style="color:var(--success)">✓ Correct!</span>'
      : `<span style="color:var(--danger)">✗ Answer: ${d.opts[d.ans]}</span>`;
  }
}
function _renderGrocTips(el, st){
  const tips = typeof GROC_TIPS !== 'undefined' ? GROC_TIPS : [];
  if(st) st.textContent = `${tips.length} tips`;
  el.innerHTML = tips.map(t => `<div class="word-card" style="margin-bottom:12px">
    <div style="font-weight:700;margin-bottom:6px">${t.title}</div>
    <div style="color:var(--text-secondary);line-height:1.6">${t.body}</div>
  </div>`).join('');
}
function grocPickOpt(i){
  if(_grocDrillPicked) return;
  _grocDrillPicked = true;
  _grocPickedIdx = i;
  const drills = typeof GROC_DRILLS !== 'undefined' ? GROC_DRILLS : [];
  const d = drills[_grocDrillIdx % drills.length];
  const correct = i === d.ans;
  _grocDrillScore.total++;
  if(correct) _grocDrillScore.correct++;
  incDailyCount && incDailyCount();
  addXp && addXp(correct ? 10 : 2);
  recordActivity && recordActivity();
  if(typeof sfx === 'function') sfx(correct ? 'correct' : 'wrong');
  const fb = document.getElementById('groc-feedback');
  if(fb) fb.innerHTML = correct
    ? '<span style="color:var(--success)">✓ Correct!</span>'
    : `<span style="color:var(--danger)">✗ Answer: ${d.opts[d.ans]}</span>`;
  for(let j = 0; j < d.opts.length; j++){
    const b = document.getElementById('groc-opt-' + j);
    if(b){
      b.disabled = true;
      if(j === d.ans) b.style.background = 'var(--success-bg,#d1fae5)';
      else if(j === i) b.style.background = 'var(--danger-bg,#fee2e2)';
    }
  }
}
function grocNext(){
  _grocDrillIdx++;
  _grocDrillPicked = false;
  _grocPickedIdx = null;
  renderGroc();
}
// Self-register in coaches-ext
(function(){
  if(typeof TOPICS_CATEGORIES === 'undefined') return;
  const ext = TOPICS_CATEGORIES.find(function(c){ return c.id === 'coaches-ext'; });
  if(ext && !ext.items.some(function(x){ return x.id === 'groc'; }))
    ext.items.push({ id: 'groc', label: '🛒 Supermarket & Grocery', fn: 'openGroc' });
})();
