let _dlvTab = 'vocab';
let _dlvCat = 'all';
let _dlvDrillIdx = 0;
let _dlvDrillScore = { correct: 0, total: 0 };
let _dlvDrillPicked = false;
let _dlvPickedIdx = null;

function openDlv(){
  try{ bumpAchievementCounter && bumpAchievementCounter('dlv_open'); }catch(e){}
  const ov = document.getElementById('dlv-overlay'); if(!ov) return;
  _dlvDrillIdx = 0; _dlvDrillPicked = false; _dlvPickedIdx = null; _dlvDrillScore = { correct: 0, total: 0 };
  ov.style.display = 'block';
  setDlvTab('vocab');
}
function closeDlv(){ const ov=document.getElementById('dlv-overlay'); if(ov) ov.style.display='none'; }
function setDlvTab(t){
  _dlvTab = t;
  const bar = document.getElementById('dlv-tab-bar');
  if(bar){
    const tabs = [['vocab','📋 Vocab'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_dlvTab===k?'active':''}" onclick="setDlvTab('${k}')">${l}</button>`).join('');
  }
  renderDlv();
}
function renderDlv(){
  const el = document.getElementById('dlv-content'); if(!el) return;
  const st = document.getElementById('dlv-stats');
  if(_dlvTab === 'vocab') _renderDlvVocab(el, st);
  else if(_dlvTab === 'drill') _renderDlvDrill(el, st);
  else _renderDlvTips(el, st);
}
function _dlvSetCat(c){ _dlvCat = c; renderDlv(); }
function _renderDlvVocab(el, st){
  const words = typeof DLV_WORDS !== 'undefined' ? DLV_WORDS : [];
  const cats = typeof DLV_CATS !== 'undefined' ? DLV_CATS : [];
  const filtered = _dlvCat === 'all' ? words : words.filter(w => w.cat === _dlvCat);
  if(st) st.textContent = filtered.length + ' / ' + words.length + ' words';
  let catBar = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">
    <button class="cat-filter${_dlvCat==='all'?' active':''}" onclick="_dlvSetCat('all')">All</button>`;
  cats.forEach(c => { catBar += `<button class="cat-filter${_dlvCat===c?' active':''}" onclick="_dlvSetCat('${c}')">${c}</button>`; });
  catBar += '</div>';
  el.innerHTML = catBar + '<div style="display:grid;gap:10px">' +
    filtered.map(w => `<div class="card" style="padding:14px;display:flex;justify-content:space-between;align-items:center;gap:12px">
      <div>
        <div style="font-size:1.3rem;font-weight:700">${w.ar}</div>
        <div style="color:var(--accent);font-size:0.9rem">${w.tr}</div>
        <div style="color:var(--muted);font-size:0.85rem">${w.en}</div>
      </div>
      <button class="btn btn-outline" style="flex-shrink:0" onclick="speak('${w.ar.replace(/'/g,"\\'")}','ar')">🔊</button>
    </div>`).join('') + '</div>';
}
function _renderDlvDrill(el, st){
  const drills = typeof DLV_DRILLS !== 'undefined' ? DLV_DRILLS : [];
  if(!drills.length){ el.innerHTML = '<p>No drills.</p>'; return; }
  if(st) st.textContent = _dlvDrillScore.correct + '/' + _dlvDrillScore.total + ' correct';
  const d = drills[_dlvDrillIdx % drills.length];
  el.innerHTML = `<div class="card" style="padding:20px">
    <div style="font-size:0.85rem;color:var(--muted);margin-bottom:8px">Q${(_dlvDrillIdx % drills.length)+1}/${drills.length}</div>
    <div style="font-size:1.05rem;font-weight:600;margin-bottom:16px">${d.q}</div>
    <div style="display:grid;gap:8px">
      ${d.opts.map((o,i) => {
        let bg='var(--card)'; let brd='1px solid var(--border)';
        if(_dlvDrillPicked){
          if(i===d.ans){bg='rgba(34,197,94,0.15)';brd='1px solid #22c55e';}
          else if(i===_dlvPickedIdx){bg='rgba(239,68,68,0.15)';brd='1px solid #ef4444';}
        }
        return `<button id="dlv-opt-${i}" onclick="dlvPickOpt(${i})" style="background:${bg};border:${brd};border-radius:8px;padding:10px 14px;text-align:left;cursor:pointer;color:var(--text);font-size:0.95rem">${o}</button>`;
      }).join('')}
    </div>
    <div id="dlv-feedback" style="margin-top:12px;font-weight:600;min-height:24px"></div>
    ${_dlvDrillPicked ? `<div style="text-align:center;margin-top:12px"><button class="btn btn-primary" onclick="dlvNext()">Next →</button></div>` : ''}
  </div>`;
}
function _renderDlvTips(el, st){
  const tips = typeof DLV_TIPS !== 'undefined' ? DLV_TIPS : [];
  if(st) st.textContent = tips.length + ' tips';
  el.innerHTML = '<div style="display:grid;gap:14px">' +
    tips.map((t,i) => `<div class="card" style="padding:16px">
      <div style="font-weight:600;color:var(--accent);margin-bottom:6px">🛵 Tip ${i+1}</div>
      <div style="line-height:1.6;color:var(--text)">${t}</div>
    </div>`).join('') + '</div>';
}
function dlvPickOpt(i){
  if(_dlvDrillPicked) return;
  _dlvDrillPicked = true;
  _dlvPickedIdx = i;
  const drills = typeof DLV_DRILLS !== 'undefined' ? DLV_DRILLS : [];
  const d = drills[_dlvDrillIdx % drills.length];
  const correct = i === d.ans;
  _dlvDrillScore.total++;
  if(correct) _dlvDrillScore.correct++;
  try{ incDailyCount && incDailyCount(); }catch(e){}
  try{ addXp && addXp(correct ? 10 : 2); }catch(e){}
  try{ recordActivity && recordActivity(); }catch(e){}
  if(typeof sfx === 'function') sfx(correct ? 'correct' : 'wrong');
  const fb = document.getElementById('dlv-feedback');
  if(fb) fb.innerHTML = correct
    ? '<span style="color:var(--success)">✓ Correct!</span>'
    : `<span style="color:var(--danger)">✗ Answer: ${d.opts[d.ans]}</span>`;
  for(let j=0;j<d.opts.length;j++){
    const b = document.getElementById('dlv-opt-'+j);
    if(b){
      b.disabled = true;
      if(j===d.ans) b.style.background='var(--success-bg,#d1fae5)';
      else if(j===i) b.style.background='var(--danger-bg,#fee2e2)';
    }
  }
}
function dlvNext(){
  _dlvDrillIdx++;
  _dlvDrillPicked = false;
  _dlvPickedIdx = null;
  renderDlv();
}
