// ── R1035 NEW FEATURE: Lebanese Cooking & Kitchen Culture coach (cok) ────────
let _cokTab = 'vocab';
let _cokCat = 'all';
let _cokDrillIdx = 0;
let _cokDrillScore = { correct: 0, total: 0 };
let _cokDrillPicked = false;
let _cokPickedIdx = null;

function openCok() {
  try { bumpAchievementCounter && bumpAchievementCounter('cok_open'); } catch(e) {}
  const ov = document.getElementById('cok-overlay'); if (!ov) return;
  _cokDrillIdx = 0; _cokDrillPicked = false; _cokPickedIdx = null;
  _cokDrillScore = { correct: 0, total: 0 };
  ov.style.display = 'block';
  setCokTab('vocab');
}

function closeCok() {
  const ov = document.getElementById('cok-overlay');
  if (ov) ov.style.display = 'none';
}

function setCokTab(t) {
  _cokTab = t;
  const bar = document.getElementById('cok-tab-bar');
  if (bar) {
    const tabs = [['vocab','📋 Vocab'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) =>
      `<button class="cat-filter ${_cokTab===k?'active':''}" onclick="setCokTab('${k}')">${l}</button>`
    ).join('');
  }
  renderCok();
}

function renderCok() {
  const st = document.getElementById('cok-stats');
  if (st) st.textContent = `${_cokDrillScore.correct}/${_cokDrillScore.total} correct`;
  if (_cokTab === 'vocab') _renderCokVocab();
  else if (_cokTab === 'drill') _renderCokDrill();
  else _renderCokTips();
}

function _cokSetCat(c) {
  _cokCat = c;
  renderCok();
}

function _renderCokVocab() {
  const el = document.getElementById('cok-content'); if (!el) return;
  const cats = typeof COK_CATS !== 'undefined' ? COK_CATS : ['all'];
  const words = typeof COK_WORDS !== 'undefined' ? COK_WORDS : [];
  const filtered = _cokCat === 'all' ? words : words.filter(w => w.cat === _cokCat);
  const catBar = cats.map(c =>
    `<button class="cat-filter ${_cokCat===c?'active':''}" onclick="_cokSetCat('${c}')">${c}</button>`
  ).join('');
  const cards = filtered.map(w =>
    `<div class="word-card" onclick="speak('${w.ar}','ar')" style="cursor:pointer">
      <div style="font-size:1.5rem;font-family:var(--arabic-font)">${w.ar}</div>
      <div style="color:var(--muted);font-size:0.85rem">${w.tr}</div>
      <div style="font-weight:600">${w.eng}</div>
      <div style="font-size:0.75rem;color:var(--muted);margin-top:4px">${w.cat}</div>
    </div>`
  ).join('');
  el.innerHTML = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">${catBar}</div>
    <div class="word-grid">${cards}</div>`;
}

function _renderCokDrill() {
  const el = document.getElementById('cok-content'); if (!el) return;
  const drills = typeof COK_DRILLS !== 'undefined' ? COK_DRILLS : [];
  if (!drills.length) { el.innerHTML = '<p>No drills available.</p>'; return; }
  const d = drills[_cokDrillIdx % drills.length];
  const opts = d.opts.map((o, i) => {
    let cls = 'btn btn-outline';
    if (_cokDrillPicked) {
      if (i === d.ans) cls = 'btn btn-success';
      else if (i === _cokPickedIdx) cls = 'btn btn-danger';
    }
    return `<button class="${cls}" onclick="cokPickOpt(${i})" style="margin:4px;min-width:160px">${o}</button>`;
  }).join('');
  el.innerHTML = `<div style="text-align:center;margin-bottom:20px">
    <div style="font-size:0.85rem;color:var(--muted);margin-bottom:8px">Q ${(_cokDrillIdx % drills.length)+1} / ${drills.length}</div>
    <div style="font-size:1.1rem;font-weight:600;margin-bottom:16px">${d.q}</div>
    <div style="display:flex;flex-wrap:wrap;justify-content:center;gap:8px">${opts}</div>
    ${_cokDrillPicked ? `<button class="btn btn-primary" onclick="cokNext()" style="margin-top:16px">Next →</button>` : ''}
  </div>`;
}

function _renderCokTips() {
  const el = document.getElementById('cok-content'); if (!el) return;
  const tips = typeof COK_TIPS !== 'undefined' ? COK_TIPS : [];
  el.innerHTML = tips.map(t =>
    `<div class="card" style="margin-bottom:12px">
      <div style="font-weight:700;margin-bottom:6px">💡 ${t.title}</div>
      <div style="color:var(--muted);line-height:1.5">${t.body}</div>
    </div>`
  ).join('');
}

function cokPickOpt(i) {
  if (_cokDrillPicked) return;
  _cokDrillPicked = true; _cokPickedIdx = i;
  const drills = typeof COK_DRILLS !== 'undefined' ? COK_DRILLS : [];
  const d = drills[_cokDrillIdx % drills.length];
  const correct = i === d.ans;
  _cokDrillScore.total++;
  if (correct) _cokDrillScore.correct++;
  try { incDailyCount && incDailyCount(); } catch(e) {}
  try { addXp && addXp(correct ? 10 : 2); } catch(e) {}
  try { recordActivity && recordActivity(); } catch(e) {}
  if (typeof sfx === 'function') sfx(correct ? 'correct' : 'wrong');
  renderCok();
}

function cokNext() {
  _cokDrillIdx++;
  _cokDrillPicked = false; _cokPickedIdx = null;
  renderCok();
}

