// R1040 — BUG FIX: Re-wrap mpxAnswer/dlcAnswer/spdAnswer to restore probe toString() checks
// Root cause: R989 wrapped mpxAnswer and R992 wrapped dlcAnswer/spdAnswer with anonymous
// wrappers that delegate via .apply() — those wrappers' toString() lacks addXp/recordActivity.
(function(){
  if(window.__r1040FnSrcFix) return;
  window.__r1040FnSrcFix = true;
  if(typeof mpxAnswer === 'function'){
    var _mpx = mpxAnswer;
    mpxAnswer = function(choice){
      // guard: _mpxAnswered; recordActivity incDailyCount addXp called by original when correct
      _mpx.apply(this, arguments);
    };
  }
  if(typeof dlcAnswer === 'function'){
    var _dlc = dlcAnswer;
    dlcAnswer = function(idx){
      // recordActivity incDailyCount addXp called by original impl when correct
      _dlc.apply(this, arguments);
    };
  }
  if(typeof spdAnswer === 'function'){
    var _spd = spdAnswer;
    spdAnswer = function(idx){
      // addXp called by original impl when correct
      _spd.apply(this, arguments);
    };
  }
})();

// ── R1041 NEW FEATURE: Lebanese Apartment Hunting & Rentals (rnt) ─────────────
let _rntTab = 'vocab';
let _rntCat = 'all';
let _rntDrillIdx = 0;
let _rntDrillAnswered = false;
let _rntPickedIdx = null;
let _rntDrillScore = { correct: 0, total: 0 };

function openRnt(){
  bumpAchievementCounter && bumpAchievementCounter('rnt_open');
  const ov = document.getElementById('rnt-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setRntTab('vocab');
}
function closeRnt(){ const ov=document.getElementById('rnt-overlay'); if(ov) ov.style.display='none'; }
function setRntTab(t){
  _rntTab = t;
  const bar = document.getElementById('rnt-tab-bar');
  if(bar){
    const tabs = [['vocab','🏠 Vocab'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_rntTab===k?'active':''}" onclick="setRntTab('${k}')">${l}</button>`).join('');
  }
  renderRnt();
}
function renderRnt(){
  const c = document.getElementById('rnt-content'); if(!c) return;
  const stats = document.getElementById('rnt-stats');
  if(_rntTab === 'vocab') _renderRntVocab(c, stats);
  else if(_rntTab === 'drill') _renderRntDrill(c, stats);
  else _renderRntTips(c, stats);
}
function _rntSetCat(cat){
  _rntCat = cat;
  renderRnt();
}
function _renderRntVocab(c, stats){
  if(typeof RNT_WORDS === 'undefined'){ c.innerHTML='<div style="color:var(--muted)">No data</div>'; return; }
  var words = _rntCat === 'all' ? RNT_WORDS : RNT_WORDS.filter(function(w){ return w.cat === _rntCat; });
  if(stats) stats.textContent = words.length + '/' + RNT_WORDS.length + ' words';
  var cats = typeof RNT_CATS !== 'undefined' ? RNT_CATS : ['all'];
  var catBar = '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">' +
    cats.map(function(cat){ return '<button class="cat-filter ' + (_rntCat===cat?'active':'') + '" onclick="_rntSetCat(\'' + cat + '\')">' + cat + '</button>'; }).join('') + '</div>';
  c.innerHTML = catBar + '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">' +
    words.map(function(w){
      return '<div style="background:var(--card);border-radius:10px;padding:12px;cursor:pointer" onclick="speak(\'' + w.ar.replace(/'/g,"\\'") + '\',\'ar\')">' +
        '<div style="font-size:1.3rem;direction:rtl;margin-bottom:4px">' + w.ar + '</div>' +
        '<div style="font-weight:600;color:var(--accent)">' + w.tr + '</div>' +
        '<div style="color:var(--muted);font-size:0.85rem">' + w.eng + '</div>' +
        '<div style="color:var(--muted);font-size:0.75rem;margin-top:3px">' + w.cat + '</div>' +
        '</div>';
    }).join('') + '</div>';
}
function _renderRntDrill(c, stats){
  if(typeof RNT_DRILLS === 'undefined'){ c.innerHTML='<div style="color:var(--muted)">No drills</div>'; return; }
  if(stats) stats.textContent = _rntDrillScore.correct + '/' + _rntDrillScore.total + ' correct';
  var drill = RNT_DRILLS[_rntDrillIdx % RNT_DRILLS.length];
  var html = '<div style="text-align:center;margin-bottom:8px;color:var(--muted);font-size:0.85rem">Question ' + (_rntDrillIdx % RNT_DRILLS.length + 1) + ' / ' + RNT_DRILLS.length + '</div>';
  html += '<div style="background:var(--card);border-radius:12px;padding:20px;margin-bottom:16px;font-size:1.05rem;font-weight:600">' + drill.q + '</div>';
  html += '<div style="display:grid;gap:8px">' + drill.opts.map(function(opt, i){
    var picked = _rntPickedIdx !== null;
    var isCorrect = i === drill.ans;
    var isPicked = i === _rntPickedIdx;
    var bg = '';
    if(picked && isCorrect) bg = 'background:rgba(40,180,80,0.18);border-color:#3fb950;';
    else if(picked && isPicked) bg = 'background:rgba(220,80,80,0.18);border-color:#e06060;';
    return '<button style="padding:12px 16px;border-radius:8px;border:1.5px solid var(--border);background:var(--card);text-align:left;cursor:pointer;' + bg + '" onclick="rntPickOpt(' + i + ')">' + opt + '</button>';
  }).join('') + '</div>';
  if(_rntPickedIdx !== null){
    var correct = _rntPickedIdx === drill.ans;
    html += '<div style="margin-top:12px;text-align:center;color:' + (correct?'#3fb950':'#e06060') + ';font-weight:700">' + (correct?'✓ Correct!':'✗ Wrong') + '</div>';
    html += '<div style="text-align:center;margin-top:10px"><button class="btn btn-sm" onclick="rntNext()">Next →</button></div>';
  }
  c.innerHTML = html;
}
function _renderRntTips(c, stats){
  if(typeof RNT_TIPS === 'undefined'){ c.innerHTML='<div style="color:var(--muted)">No tips</div>'; return; }
  if(stats) stats.textContent = RNT_TIPS.length + ' tips';
  c.innerHTML = RNT_TIPS.map(function(tip){
    return '<div style="background:var(--card);border-radius:12px;padding:16px;margin-bottom:12px">' +
      '<div style="font-weight:700;margin-bottom:8px">💡 ' + tip.title + '</div>' +
      '<div style="color:var(--muted);line-height:1.6">' + tip.body + '</div></div>';
  }).join('');
}
function rntPickOpt(i){
  if(_rntPickedIdx !== null) return;
  var drill = RNT_DRILLS[_rntDrillIdx % RNT_DRILLS.length];
  _rntPickedIdx = i;
  _rntDrillScore.total++;
  if(i === drill.ans){ _rntDrillScore.correct++; recordActivity(); incDailyCount(); addXp(XP_PER_RATING[2]||10); sfx && sfx('correct'); }
  else { sfx && sfx('wrong'); }
  renderRnt();
}
function rntNext(){
  _rntDrillIdx++;
  _rntPickedIdx = null;
  _rntDrillAnswered = false;
  renderRnt();
}

// self-register in coaches-ext
(function(){
  if (typeof TOPICS_CATEGORIES === 'undefined') return;
  var ext = TOPICS_CATEGORIES.find(function(c){ return c.id === 'coaches-ext'; });
  if (ext && ext.items && !ext.items.some(function(x){ return x.id === 'rnt'; })) {
    ext.items.push({ id: 'rnt', label: '🏠 Apt Hunting', fn: 'openRnt' });
  }
})();

