// ── R1046 BUG FIX: Fix minimal pairs listen drill — audio sequencing ────────
// Bug: listen tab used setTimeout(900ms) between speak(a) and speak(b).
// If a's audio lookup took >900ms, speak(b) fired stopAllAudio() cancelling a.
// Fix: playMinPairListen waits for tts-audio 'ended' event before playing b;
// setMpxMode patched to re-render listen tab using playMinPairListen.
(function(){
  if(window.__r1046MpxListenFix) return;
  window.__r1046MpxListenFix = true;

  window.playMinPairListen = function(aAr, bAr) {
    var audio = document.getElementById('tts-audio');
    var done = false;
    function playB() {
      if(done) return;
      done = true;
      speak(bAr, true);
    }
    if(audio && typeof audio.addEventListener === 'function') {
      var onEnd = function() {
        audio.removeEventListener('ended', onEnd);
        audio.removeEventListener('error', onEnd);
        setTimeout(playB, 200);
      };
      audio.addEventListener('ended', onEnd);
      audio.addEventListener('error', onEnd);
      setTimeout(playB, 5000);
    } else {
      setTimeout(playB, 1400);
    }
    speak(aAr, true);
  };

  if(typeof setMpxMode === 'function') {
    var _origSetMpxMode = setMpxMode;
    setMpxMode = function(m) {
      _origSetMpxMode.apply(this, arguments);
      if(m !== 'listen') return;
      if(typeof MIN_PAIRS_X === 'undefined') return;
      var c = document.getElementById('mpx-content');
      if(!c) return;
      c.innerHTML = '<div style="background:var(--card);border-radius:12px;padding:18px">' +
        '<div style="margin-bottom:12px;color:var(--muted)">Press a pair to hear both words back-to-back. Compare carefully — the only difference is the contrast letter.</div>' +
        '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:8px">' +
        MIN_PAIRS_X.map(function(p) {
          var aEsc = JSON.stringify(p.a.ar);
          var bEsc = JSON.stringify(p.b.ar);
          return '<button class="btn btn-outline" style="text-align:left;padding:10px" onclick="playMinPairListen(' + aEsc + ',' + bEsc + ')">' +
            '<div style="font-weight:700">' + (p.a.tr||'') + ' vs ' + (p.b.tr||'') + '</div>' +
            '<div style="color:var(--muted);font-size:0.8rem">' + (p.contrast||'') + '</div>' +
            '</button>';
        }).join('') +
        '</div></div>';
    };
    try{ Object.keys(_origSetMpxMode).forEach(function(k){ try{ setMpxMode[k]=_origSetMpxMode[k]; }catch(e){} }); }catch(e){}
  }
})();
