// ── R1047 NEW FEATURE: Lebanese Content Creator & Social Media Culture (crt) ─
let _crtTab = 'vocab';
let _crtCat = 'all';
let _crtDrillIdx = 0;
let _crtDrillAnswered = false;
let _crtPickedIdx = null;
let _crtDrillScore = { correct: 0, total: 0 };
function openCrt(){
  try{ bumpAchievementCounter && bumpAchievementCounter('crt_open'); }catch(e){}
  const ov = document.getElementById('crt-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _crtDrillIdx = 0; _crtDrillAnswered = false; _crtPickedIdx = null;
  _crtDrillScore = { correct: 0, total: 0 };
  setCrtTab('vocab');
}
function closeCrt(){ const ov = document.getElementById('crt-overlay'); if(ov) ov.style.display = 'none'; }
function setCrtTab(t){
  _crtTab = t;
  const bar = document.getElementById('crt-tab-bar');
  if(bar){
    const tabs = [['vocab','📱 Vocab'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_crtTab===k?'active':''}" onclick="setCrtTab('${k}')">${l}</button>`).join('');
  }
  renderCrt();
}
function renderCrt(){
  const c = document.getElementById('crt-content');
  if(!c) return;
  const stats = document.getElementById('crt-stats');
  if(stats) stats.textContent = `${(typeof CRT_WORDS!=='undefined'?CRT_WORDS.length:0)} words`;
  if(_crtTab === 'vocab') _renderCrtVocab(c, stats);
  else if(_crtTab === 'drill') _renderCrtDrill(c, stats);
  else _renderCrtTips(c, stats);
}
function _crtSetCat(cat){
  _crtCat = cat;
  renderCrt();
}
function _renderCrtVocab(c, stats){
  if(typeof CRT_WORDS === 'undefined'){ c.innerHTML='<div style="color:var(--muted)">No data</div>'; return; }
  const cats = typeof CRT_CATS !== 'undefined' ? CRT_CATS : ['all'];
  const catBar = cats.map(cat =>
    `<button class="cat-filter ${_crtCat===cat?'active':''}" onclick="_crtSetCat('${cat}')">${cat}</button>`
  ).join('');
  const words = _crtCat === 'all' ? CRT_WORDS : CRT_WORDS.filter(w => w.cat === _crtCat);
  c.innerHTML = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px">${catBar}</div>` +
    `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px">` +
    words.map(w => `<div class="card" style="padding:12px;cursor:pointer" onclick="speak(${attrArg(w.ar)})">
      <div style="font-size:1.2rem;font-weight:700;direction:rtl">${w.ar}</div>
      <div style="color:var(--accent);margin:2px 0;font-size:0.9rem">${w.tr}</div>
      <div style="color:var(--muted);font-size:0.82rem">${w.eng}</div>
      <div style="font-size:0.7rem;color:var(--accent2);margin-top:4px;text-transform:uppercase">${w.cat}</div>
    </div>`).join('') + '</div>';
}
function _renderCrtDrill(c, stats){
  if(typeof CRT_DRILLS === 'undefined'){ c.innerHTML='<div style="color:var(--muted)">No drills</div>'; return; }
  if(stats) stats.textContent = `${_crtDrillScore.correct}/${_crtDrillScore.total} correct`;
  const q = CRT_DRILLS[_crtDrillIdx % CRT_DRILLS.length];
  const opts = q.opts.map((o,i) => {
    let bg = 'var(--card2)'; let col = '';
    if(_crtDrillAnswered){
      if(i === q.ans) bg = '#22c55e22', col = 'color:#22c55e;font-weight:700';
      else if(i === _crtPickedIdx) bg = '#ef444422', col = 'color:#ef4444';
    }
    return `<button class="btn btn-outline" style="text-align:left;background:${bg};${col}" onclick="crtPickOpt(${i})" ${_crtDrillAnswered?'disabled':''}>${o}</button>`;
  }).join('');
  const prog = `Drill ${(_crtDrillIdx % CRT_DRILLS.length) + 1}/${CRT_DRILLS.length}`;
  c.innerHTML = `<div style="background:var(--card);border-radius:12px;padding:18px">
    <div style="color:var(--muted);font-size:0.82rem;margin-bottom:8px">${prog}</div>
    <div style="font-weight:600;margin-bottom:14px;font-size:1rem">${q.q}</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">${opts}</div>
    ${_crtDrillAnswered ? `<button class="btn" style="margin-top:14px;width:100%" onclick="crtNext()">Next →</button>` : ''}
  </div>`;
}
function _renderCrtTips(c){
  if(typeof CRT_TIPS === 'undefined'){ c.innerHTML='<div style="color:var(--muted)">No tips</div>'; return; }
  c.innerHTML = CRT_TIPS.map(t => `<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="font-weight:700;margin-bottom:8px">📱 ${t.title}</div>
    <div style="color:var(--muted);font-size:0.88rem;line-height:1.6">${t.body}</div>
  </div>`).join('');
}
function crtPickOpt(i){
  if(_crtDrillAnswered) return;
  _crtPickedIdx = i;
  _crtDrillAnswered = true;
  const q = CRT_DRILLS[_crtDrillIdx % CRT_DRILLS.length];
  _crtDrillScore.total++;
  if(i === q.ans){
    _crtDrillScore.correct++;
    try{ recordActivity(); }catch(e){}
    try{ incDailyCount(); }catch(e){}
    try{ addXp(XP_PER_RATING&&XP_PER_RATING[2]||10); }catch(e){}
  }
  renderCrt();
}
function crtNext(){
  _crtDrillIdx++;
  _crtDrillAnswered = false;
  _crtPickedIdx = null;
  renderCrt();
}
