// ── R1050 NEW FEATURE: Lebanese Morning & Breakfast Culture (sbh) ─────────────
let _sbhTab = 'vocab';
let _sbhCat = 'all';
let _sbhDrillIdx = 0;
let _sbhDrillAnswered = false;
let _sbhPickedIdx = null;
let _sbhDrillScore = { correct: 0, total: 0 };

function openSbh(){
  try{ bumpAchievementCounter && bumpAchievementCounter('sbh_open'); }catch(e){}
  const ov = document.getElementById('sbh-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _sbhDrillIdx = 0; _sbhDrillAnswered = false; _sbhPickedIdx = null;
  _sbhDrillScore = { correct: 0, total: 0 };
  _sbhCat = 'all';
  setSbhTab('vocab');
}
function closeSbh(){ const ov=document.getElementById('sbh-overlay'); if(ov) ov.style.display='none'; }
function setSbhTab(t){
  _sbhTab = t;
  const bar = document.getElementById('sbh-tab-bar');
  if(bar){
    const tabs = [['vocab','☀️ Vocab'],['drill','🎯 Drill'],['tips','📖 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_sbhTab===k?'active':''}" onclick="setSbhTab('${k}')">${l}</button>`).join('');
  }
  renderSbh();
}
function renderSbh(){
  const c = document.getElementById('sbh-content');
  const stats = document.getElementById('sbh-stats');
  if(!c) return;
  if(_sbhTab === 'vocab') _renderSbhVocab(c, stats);
  else if(_sbhTab === 'drill') _renderSbhDrill(c, stats);
  else _renderSbhTips(c, stats);
}
function _sbhSetCat(cat){
  _sbhCat = cat;
  renderSbh();
}
function _renderSbhVocab(c, stats){
  if(typeof SBH_WORDS === 'undefined'){ c.innerHTML='<div style="color:var(--muted)">No data</div>'; return; }
  if(stats) stats.textContent = `${SBH_WORDS.length} words`;
  const cats = typeof SBH_CATS !== 'undefined' ? SBH_CATS : ['all'];
  let html = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px">` +
    cats.map(cat => `<button class="cat-filter ${_sbhCat===cat?'active':''}" onclick="_sbhSetCat('${cat}')">${cat}</button>`).join('') +
    `</div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:8px">`;
  const words = _sbhCat === 'all' ? SBH_WORDS : SBH_WORDS.filter(w => w.cat === _sbhCat);
  words.forEach(w => {
    html += `<div class="card" style="padding:12px;cursor:pointer" onclick="speak('${w.ar.replace(/'/g,"\\'")}')">
      <div style="font-size:1.2rem;font-weight:700">${w.ar}</div>
      <div style="color:var(--accent)">${w.tr}</div>
      <div style="color:var(--muted);font-size:0.85rem">${w.eng}</div>
    </div>`;
  });
  html += `</div>`;
  c.innerHTML = html;
}
function _renderSbhDrill(c, stats){
  if(typeof SBH_DRILLS === 'undefined' || !SBH_DRILLS.length){ c.innerHTML='<div style="color:var(--muted)">No drills</div>'; return; }
  if(stats) stats.textContent = `${_sbhDrillScore.correct}/${_sbhDrillScore.total} correct`;
  if(_sbhDrillIdx >= SBH_DRILLS.length){
    c.innerHTML = `<div style="text-align:center;padding:40px">
      <div style="font-size:2rem">☀️</div>
      <div style="font-size:1.3rem;font-weight:700;margin:12px 0">Finished! ${_sbhDrillScore.correct}/${SBH_DRILLS.length} correct</div>
      <button class="btn" onclick="_sbhDrillIdx=0;_sbhDrillScore={correct:0,total:0};_sbhDrillAnswered=false;_sbhPickedIdx=null;renderSbh()">Try Again</button>
    </div>`;
    return;
  }
  const q = SBH_DRILLS[_sbhDrillIdx];
  c.innerHTML = `<div style="background:var(--card);border-radius:12px;padding:20px">
    <div style="color:var(--muted);font-size:0.85rem;margin-bottom:8px">Question ${_sbhDrillIdx+1} of ${SBH_DRILLS.length}</div>
    <div style="font-size:1.1rem;font-weight:600;margin-bottom:16px">${q.q}</div>
    <div style="display:grid;gap:8px">
      ${q.opts.map((o,i) => {
        let bg = 'var(--card)'; let border = '1px solid var(--border)';
        if(_sbhDrillAnswered){
          if(i === q.ans){ bg='var(--success,#22c55e)'; border='none'; }
          else if(i === _sbhPickedIdx){ bg='var(--error,#ef4444)'; border='none'; }
        }
        return `<button class="btn btn-outline" style="text-align:left;background:${bg};border:${border}" ${_sbhDrillAnswered?'disabled':''} onclick="sbhPickOpt(${i})">${o}</button>`;
      }).join('')}
    </div>
    ${_sbhDrillAnswered ? `<button class="btn" style="margin-top:14px;width:100%" onclick="sbhNext()">Next →</button>` : ''}
  </div>`;
}
function _renderSbhTips(c, stats){
  if(typeof SBH_TIPS === 'undefined'){ c.innerHTML='<div style="color:var(--muted)">No tips</div>'; return; }
  if(stats) stats.textContent = `${SBH_TIPS.length} notes`;
  c.innerHTML = SBH_TIPS.map(t => `<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="font-weight:700;margin-bottom:6px">${t.title}</div>
    <div style="color:var(--muted);line-height:1.5">${t.body}</div>
  </div>`).join('');
}
function sbhPickOpt(i){
  if(_sbhDrillAnswered) return;
  _sbhDrillAnswered = true;
  _sbhPickedIdx = i;
  const q = SBH_DRILLS[_sbhDrillIdx];
  if(i === q.ans) _sbhDrillScore.correct++;
  _sbhDrillScore.total++;
  try{ recordActivity && recordActivity(); }catch(e){}
  try{ incDailyCount && incDailyCount(); }catch(e){}
  try{ addXp && addXp(10); }catch(e){}
  renderSbh();
}
function sbhNext(){
  _sbhDrillIdx++;
  _sbhDrillAnswered = false;
  _sbhPickedIdx = null;
  renderSbh();
}
// self-register in coaches-ext
(function(){
  if(typeof TOPICS_CATEGORIES === 'undefined') return;
  var ext = TOPICS_CATEGORIES.find(function(c){ return c.id === 'coaches-ext'; });
  if(ext && ext.items && !ext.items.some(function(x){ return x.id === 'sbh'; })){
    ext.items.push({ id: 'sbh', label: '☀️ Morning & Breakfast', fn: 'openSbh' });
  }
})();
