function openDsr(){
  try{ bumpAchievementCounter && bumpAchievementCounter('dsr_open'); }catch(e){}
  const ov = document.getElementById('dsr-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setDsrTab('vocab');
}
function closeDsr(){ const ov=document.getElementById('dsr-overlay'); if(ov) ov.style.display='none'; }
function setDsrTab(t){
  _dsrTab = t;
  const bar = document.getElementById('dsr-tab-bar');
  if(bar){
    const tabs = [['vocab','📚 Vocab'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_dsrTab===k?'active':''}" onclick="setDsrTab('${k}')">${l}</button>`).join('');
  }
  renderDsr();
}
function renderDsr(){
  const el = document.getElementById('dsr-content'); if(!el) return;
  const stats = document.getElementById('dsr-stats');
  if(_dsrTab === 'vocab') _renderDsrVocab(el, stats);
  else if(_dsrTab === 'drill') _renderDsrDrill(el, stats);
  else _renderDsrTips(el, stats);
}
function _dsrSetCat(c){
  _dsrCat = c;
  renderDsr();
}
function _renderDsrVocab(el, stats){
  if(stats) stats.textContent = '';
  const words = (typeof DSR_WORDS !== 'undefined') ? (_dsrCat === 'all' ? DSR_WORDS : DSR_WORDS.filter(w => w.cat === _dsrCat)) : [];
  const cats = (typeof DSR_CATS !== 'undefined') ? DSR_CATS : ['all'];
  let h = `<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px">`;
  cats.forEach(c => { h += `<button class="cat-filter ${_dsrCat===c?'active':''}" onclick="_dsrSetCat('${c}')">${c}</button>`; });
  h += `</div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px">`;
  words.forEach(w => {
    h += `<div class="card" style="padding:12px;cursor:pointer" onclick="speak('${w.ar}','ar')">
      <div style="font-size:1.4rem;font-weight:700">${w.ar}</div>
      <div style="color:var(--muted);font-size:0.85rem">${w.tr}</div>
      <div style="font-size:0.9rem;margin-top:4px">${w.eng}</div>
    </div>`;
  });
  h += `</div>`;
  el.innerHTML = h;
  if(stats) stats.textContent = `${words.length} words`;
}
function _renderDsrDrill(el, stats){
  const drills = (typeof DSR_DRILLS !== 'undefined') ? DSR_DRILLS : [];
  if(!drills.length){ el.innerHTML = '<p>No drills.</p>'; return; }
  if(_dsrDrillIdx >= drills.length) _dsrDrillIdx = 0;
  const d = drills[_dsrDrillIdx];
  if(stats) stats.textContent = `${_dsrDrillScore.correct}/${_dsrDrillScore.total} · ${_dsrDrillIdx+1}/${drills.length}`;
  let h = `<div class="card" style="padding:20px;max-width:520px;margin:0 auto">
    <div style="font-size:1.1rem;font-weight:600;margin-bottom:16px">${d.q}</div>
    <div style="display:grid;gap:8px">`;
  d.opts.forEach((o,i) => {
    let style = 'padding:10px 14px;border-radius:8px;cursor:pointer;border:2px solid var(--border);background:var(--card)';
    if(_dsrDrillAnswered){
      if(i === d.ans) style += ';border-color:#4caf50;background:#4caf5022';
      else if(i === _dsrPickedIdx) style += ';border-color:#f44336;background:#f4433622';
    }
    h += `<div style="${style}" onclick="dsrPickOpt(${i})">${o}</div>`;
  });
  h += `</div>`;
  if(_dsrDrillAnswered){
    h += `<button class="btn btn-primary" style="margin-top:16px;width:100%" onclick="dsrNext()">Next →</button>`;
  }
  h += `</div>`;
  el.innerHTML = h;
}
function _renderDsrTips(el, stats){
  if(stats) stats.textContent = '';
  const tips = (typeof DSR_TIPS !== 'undefined') ? DSR_TIPS : [];
  el.innerHTML = tips.map(t => `<div class="card" style="padding:16px;margin-bottom:12px">
    <div style="font-weight:700;margin-bottom:6px">🌍 ${t.title}</div>
    <div style="line-height:1.6;color:var(--text)">${t.body}</div>
  </div>`).join('');
}
function dsrPickOpt(i){
  if(_dsrDrillAnswered) return;
  _dsrDrillAnswered = true;
  _dsrPickedIdx = i;
  const drills = (typeof DSR_DRILLS !== 'undefined') ? DSR_DRILLS : [];
  const d = drills[_dsrDrillIdx];
  const correct = (i === d.ans);
  _dsrDrillScore.total++;
  if(correct){ _dsrDrillScore.correct++; try{ sfx('correct'); }catch(e){} }
  else { try{ sfx('wrong'); }catch(e){} }
  try{ incDailyCount && incDailyCount(); addXp && addXp(correct?10:2); recordActivity && recordActivity(); }catch(e){}
  renderDsr();
}
function dsrNext(){
  _dsrDrillAnswered = false;
  _dsrPickedIdx = null;
  const drills = (typeof DSR_DRILLS !== 'undefined') ? DSR_DRILLS : [];
  _dsrDrillIdx = (_dsrDrillIdx + 1) % drills.length;
  renderDsr();
}
