// ── R1068 NEW FEATURE: Lebanese Wisdom & Life Proverbs (hkm) ─────────────────
let _hkmTab = 'vocab';
let _hkmCat = 'all';
let _hkmDrillIdx = 0;
let _hkmDrillAnswered = false;
let _hkmPickedIdx = null;
let _hkmDrillScore = { correct: 0, total: 0 };

function openHkm(){
  try{ bumpAchievementCounter && bumpAchievementCounter('hkm_open'); }catch(e){}
  const ov = document.getElementById('hkm-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _hkmDrillIdx = 0; _hkmDrillAnswered = false; _hkmPickedIdx = null;
  _hkmDrillScore = { correct: 0, total: 0 };
  setHkmTab('vocab');
}
function closeHkm(){ const ov=document.getElementById('hkm-overlay'); if(ov) ov.style.display='none'; }
function setHkmTab(t){
  _hkmTab = t;
  const bar = document.getElementById('hkm-tab-bar');
  if(bar){
    const tabs = [['vocab','📜 Proverbs'],['drill','🎯 Drill'],['tips','💡 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_hkmTab===k?'active':''}" onclick="setHkmTab('${k}')">${l}</button>`).join('');
  }
  renderHkm();
}
function renderHkm(){
  const el = document.getElementById('hkm-content'); if(!el) return;
  const stats = document.getElementById('hkm-stats');
  if(_hkmTab === 'vocab') _renderHkmVocab(el, stats);
  else if(_hkmTab === 'drill') _renderHkmDrill(el, stats);
  else _renderHkmTips(el, stats);
}
function _hkmSetCat(c){
  _hkmCat = c;
  renderHkm();
}
function _renderHkmVocab(el, stats){
  const words = (typeof HKM_WORDS !== 'undefined') ? (_hkmCat === 'all' ? HKM_WORDS : HKM_WORDS.filter(w => w.cat === _hkmCat)) : [];
  const cats = (typeof HKM_CATS !== 'undefined') ? HKM_CATS : ['all'];
  if(stats) stats.textContent = words.length + ' proverbs';
  let h = `<div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin-bottom:14px">`;
  cats.forEach(c => { h += `<button class="cat-filter ${_hkmCat===c?'active':''}" onclick="_hkmSetCat('${c}')">${c}</button>`; });
  h += `</div><div style="display:grid;gap:10px">`;
  words.forEach((w,i) => {
    h += `<div class="card" style="padding:14px;cursor:pointer" onclick="try{speak(w.ar,'ar');}catch(e){try{speak('${w.ar.replace(/'/g,"\\'")}','ar');}catch(e){}}">
      <div style="font-size:1.3rem;font-weight:700;direction:rtl;margin-bottom:6px">${w.ar}</div>
      <div style="color:var(--accent);font-size:0.9rem;margin-bottom:4px">${w.tr}</div>
      <div style="color:var(--muted);font-size:0.85rem">${w.eng}</div>
      <div style="font-size:0.75rem;color:var(--muted);margin-top:4px;text-transform:uppercase">${w.cat}</div>
    </div>`;
  });
  h += `</div>`;
  el.innerHTML = h;
}
function _renderHkmDrill(el, stats){
  const drills = (typeof HKM_DRILLS !== 'undefined') ? HKM_DRILLS : [];
  if(!drills.length){ el.innerHTML = '<p>No drills available.</p>'; return; }
  const d = drills[_hkmDrillIdx % drills.length];
  if(stats) stats.textContent = `${_hkmDrillScore.correct}/${_hkmDrillScore.total} correct · Q${(_hkmDrillIdx%drills.length)+1}/${drills.length}`;
  let h = `<div class="card" style="padding:18px;max-width:560px;margin:0 auto">
    <div style="font-size:1.1rem;font-weight:700;margin-bottom:16px;direction:rtl;text-align:right">${d.q}</div>
    <div style="display:grid;gap:8px">`;
  d.opts.forEach((o,i) => {
    let style = 'padding:10px 14px;border-radius:8px;cursor:pointer;border:2px solid var(--border);background:var(--card)';
    if(_hkmDrillAnswered){
      if(i === d.ans) style += ';border-color:#22c55e;background:#14532d20';
      else if(i === _hkmPickedIdx) style += ';border-color:#ef4444;background:#7f1d1d20';
    }
    h += `<div style="${style}" onclick="hkmPickOpt(${i})">${o}</div>`;
  });
  h += `</div>`;
  if(_hkmDrillAnswered){
    h += `<button class="btn btn-primary" style="margin-top:14px;width:100%" onclick="hkmNext()">Next ▶</button>`;
  }
  h += `</div>`;
  el.innerHTML = h;
}
function _renderHkmTips(el, stats){
  const tips = (typeof HKM_TIPS !== 'undefined') ? HKM_TIPS : [];
  if(stats) stats.textContent = tips.length + ' insights';
  el.innerHTML = tips.map(t => `<div class="card" style="padding:16px;margin-bottom:10px">
    <div style="font-weight:700;margin-bottom:8px">📜 ${t.title}</div>
    <div style="color:var(--muted);font-size:0.9rem;line-height:1.6">${t.body}</div>
  </div>`).join('');
}
function hkmPickOpt(i){
  if(_hkmDrillAnswered) return;
  _hkmDrillAnswered = true;
  _hkmPickedIdx = i;
  const drills = (typeof HKM_DRILLS !== 'undefined') ? HKM_DRILLS : [];
  const d = drills[_hkmDrillIdx % drills.length];
  const correct = (i === d.ans);
  _hkmDrillScore.total++;
  if(correct){ _hkmDrillScore.correct++; try{ sfx('correct'); }catch(e){} }
  else { try{ sfx('wrong'); }catch(e){} }
  try{ incDailyCount && incDailyCount(); addXp && addXp(correct?10:2); recordActivity && recordActivity(); }catch(e){}
  renderHkm();
}
function hkmNext(){
  _hkmDrillAnswered = false;
  _hkmPickedIdx = null;
  const drills = (typeof HKM_DRILLS !== 'undefined') ? HKM_DRILLS : [];
  _hkmDrillIdx = (_hkmDrillIdx + 1) % drills.length;
  renderHkm();
}
