function openJbn(){
  try{ bumpAchievementCounter && bumpAchievementCounter('jbn_open'); }catch(e){}
  const ov = document.getElementById('jbn-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _jbnDrillIdx = 0; _jbnDrillAnswered = false; _jbnPickedIdx = null;
  _jbnDrillScore = { correct: 0, total: 0 };
  setJbnTab('vocab');
}
function closeJbn(){ const ov=document.getElementById('jbn-overlay'); if(ov) ov.style.display='none'; }
function setJbnTab(t){
  _jbnTab = t;
  const bar = document.getElementById('jbn-tab-bar');
  if(bar){
    const tabs=[['vocab','📖 Vocab'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l])=>`<button class="cat-filter ${_jbnTab===k?'active':''}" onclick="setJbnTab('${k}')">${l}</button>`).join('');
  }
  renderJbn();
}
function renderJbn(){
  const el = document.getElementById('jbn-content');
  const st = document.getElementById('jbn-stats');
  if(!el) return;
  if(_jbnTab==='vocab') _renderJbnVocab(el, st);
  else if(_jbnTab==='drill') _renderJbnDrill(el, st);
  else _renderJbnTips(el, st);
}
function _jbnSetCat(c){ _jbnCat=c; renderJbn(); }
function _renderJbnVocab(el, st){
  const words = typeof JBN_WORDS!=='undefined'?JBN_WORDS:[];
  const cats = typeof JBN_CATS!=='undefined'?JBN_CATS:['all'];
  const filtered = _jbnCat==='all'?words:words.filter(w=>w.cat===_jbnCat);
  if(st) st.textContent = filtered.length+' words';
  const catBar = cats.map(c=>`<button class="cat-filter ${_jbnCat===c?'active':''}" onclick="_jbnSetCat('${c}')" style="font-size:0.78rem">${c}</button>`).join('');
  el.innerHTML = `<div style="display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin-bottom:12px">${catBar}</div>`+
    filtered.map(w=>`<div class="word-card" style="cursor:pointer" onclick="speak('${w.ar.replace(/'/g,"\\'")}')">
      <div style="font-size:1.3rem;font-weight:700;direction:rtl">${w.ar}</div>
      <div style="color:var(--accent)">${w.tr}</div>
      <div style="color:var(--muted);font-size:0.85rem">${w.eng}</div>
      <div style="font-size:0.7rem;color:var(--muted);text-transform:uppercase;margin-top:4px">${w.cat}</div>
    </div>`).join('');
}
function _renderJbnDrill(el, st){
  const drills = typeof JBN_DRILLS!=='undefined'?JBN_DRILLS:[];
  if(!drills.length){ el.innerHTML='<p>No drills.</p>'; return; }
  const idx = _jbnDrillIdx % drills.length;
  const d = drills[idx];
  if(st) st.textContent = `${_jbnDrillScore.correct}/${_jbnDrillScore.total} · Q${idx+1}/${drills.length}`;
  const optsHtml = d.opts.map((o,i)=>{
    let bg='';
    if(_jbnDrillAnswered){
      if(i===d.ans) bg='background:var(--success-bg,#d1fae5)';
      else if(i===_jbnPickedIdx) bg='background:var(--danger-bg,#fee2e2)';
    }
    return `<button id="jbn-opt-${i}" class="btn btn-outline" style="margin:4px;${bg}" onclick="jbnPickOpt(${i})" ${_jbnDrillAnswered?'disabled':''}>${o}</button>`;
  }).join('');
  el.innerHTML = `<div style="text-align:center;padding:12px">
    <div style="font-size:1.1rem;font-weight:600;margin-bottom:14px">${d.q}</div>
    <div>${optsHtml}</div>
    <div id="jbn-feedback" style="margin-top:10px;min-height:24px"></div>
    ${_jbnDrillAnswered?`<button class="btn btn-primary" style="margin-top:8px" onclick="jbnNext()">Next →</button>`:''}
  </div>`;
}
function _renderJbnTips(el, st){
  const tips = typeof JBN_TIPS!=='undefined'?JBN_TIPS:[];
  if(st) st.textContent = tips.length+' tips';
  el.innerHTML = tips.map(t=>`<div class="word-card" style="margin-bottom:10px">
    <div style="font-weight:700;margin-bottom:6px">🧀 ${t.title}</div>
    <div style="color:var(--muted);font-size:0.9rem;line-height:1.5">${t.body}</div>
  </div>`).join('');
}
function jbnPickOpt(i){
  if(_jbnDrillAnswered) return;
  _jbnDrillAnswered = true;
  _jbnPickedIdx = i;
  const drills = typeof JBN_DRILLS!=='undefined'?JBN_DRILLS:[];
  const d = drills[_jbnDrillIdx % drills.length];
  const correct = i === d.ans;
  _jbnDrillScore.total++;
  if(correct) _jbnDrillScore.correct++;
  try{ sfx && sfx(correct?'correct':'wrong'); }catch(e){}
  incDailyCount && incDailyCount();
  addXp && addXp(correct?10:2);
  recordActivity && recordActivity();
  const fb = document.getElementById('jbn-feedback');
  if(fb) fb.innerHTML = correct?'<span style="color:var(--success)">✓ Correct!</span>':`<span style="color:var(--danger)">✗ Answer: ${d.opts[d.ans]}</span>`;
  for(let j=0;j<d.opts.length;j++){
    const b=document.getElementById('jbn-opt-'+j);
    if(b){ b.disabled=true; if(j===d.ans) b.style.background='var(--success-bg,#d1fae5)'; else if(j===i) b.style.background='var(--danger-bg,#fee2e2)'; }
  }
  const nb=document.getElementById('jbn-content');
  if(nb){ const xb=nb.querySelector('button.btn-primary'); if(!xb){ const btn=document.createElement('button'); btn.className='btn btn-primary'; btn.style.marginTop='8px'; btn.textContent='Next →'; btn.onclick=jbnNext; nb.querySelector('[id^="jbn-feedback"]')?.after(btn); }}
  renderJbn();
}
function jbnNext(){
  _jbnDrillIdx++;
  _jbnDrillAnswered = false;
  _jbnPickedIdx = null;
  renderJbn();
}

// Self-register
(function(){
  if(typeof window._topicsExt==='undefined') window._topicsExt={items:[]};
  var ext=window._topicsExt;
  if(!ext.items) ext.items=[];
  if(!ext.items.find(function(x){return x.id==='jbn';}))
    ext.items.push({id:'jbn', label:'🧀 Cheese & Dairy', fn:'openJbn'});
})();
