// ── R1086 NEW FEATURE: Lebanese Sunday Family Lunch (sfl) ─────────────────────
let _sflTab = 'words';
let _sflDrillIdx = 0;
let _sflDrillAnswered = false;
let _sflPickedIdx = null;
let _sflDrillScore = {correct:0, total:0};

function openSfl(){
  bumpAchievementCounter && bumpAchievementCounter('sfl_open');
  const ov = document.getElementById('sfl-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _sflDrillIdx = 0; _sflDrillAnswered = false; _sflPickedIdx = null; _sflDrillScore = {correct:0,total:0};
  setSflTab('words');
}
function closeSfl(){ const ov=document.getElementById('sfl-overlay'); if(ov) ov.style.display='none'; }
function setSflTab(t){
  _sflTab = t;
  const bar = document.getElementById('sfl-tab-bar');
  if(bar){
    const tabs = [['words','📋 Words'],['drill','🎯 Drill'],['tips','💡 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_sflTab===k?'active':''}" onclick="setSflTab('${k}')">${l}</button>`).join('');
  }
  renderSfl();
}
function renderSfl(){
  const el = document.getElementById('sfl-content');
  const st = document.getElementById('sfl-stats');
  if(!el) return;
  if(_sflTab === 'words'){
    if(st) st.textContent = SFL_WORDS.length + ' words';
    el.innerHTML = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">'
      + SFL_WORDS.map(w => `<div class="card" style="padding:12px 14px">
          <div style="font-size:1.3rem;font-weight:700">${w.ar}</div>
          <div style="color:var(--accent);font-size:0.9rem">${w.tr}</div>
          <div style="color:var(--muted);font-size:0.85rem">${w.en}</div>
        </div>`).join('')
      + '</div>';
  } else if(_sflTab === 'drill'){
    const idx = _sflDrillIdx % SFL_DRILLS.length;
    const d = SFL_DRILLS[idx];
    const pct = _sflDrillScore.total ? Math.round(_sflDrillScore.correct/_sflDrillScore.total*100) : 0;
    if(st) st.textContent = `${_sflDrillScore.correct}/${_sflDrillScore.total} (${pct}%)`;
    el.innerHTML = `<div class="card" style="padding:20px;max-width:600px;margin:0 auto">
      <div style="font-size:0.8rem;color:var(--muted);margin-bottom:10px">Q ${idx+1} / ${SFL_DRILLS.length}</div>
      <div style="font-weight:700;font-size:1.05rem;margin-bottom:16px">${d.q}</div>
      <div style="display:flex;flex-direction:column;gap:8px">
        ${d.opts.map((o,i) => {
          let bg='', border='1px solid var(--border)';
          if(_sflDrillAnswered){
            if(i===d.ans){ bg='background:var(--success-bg,#d1fae5);'; border='1px solid var(--success,#10b981)'; }
            else if(i===_sflPickedIdx){ bg='background:var(--danger-bg,#fee2e2);'; border='1px solid var(--danger,#ef4444)'; }
          }
          return `<button onclick="sflPickOpt(${i})" style="${bg}border:${border};border-radius:10px;padding:12px 16px;text-align:left;cursor:pointer;font-size:0.95rem;transition:all .15s" ${_sflDrillAnswered?'disabled':''}>${o}</button>`;
        }).join('')}
      </div>
      ${_sflDrillAnswered ? `<button class="btn btn-outline" onclick="sflNext()" style="margin-top:16px;width:100%">Next →</button>` : ''}
    </div>`;
  } else {
    if(st) st.textContent = '';
    if(typeof SFL_TIPS==='undefined'||!SFL_TIPS.length){el.innerHTML='<p>No tips.</p>';return;}
    el.innerHTML = '<div style="display:flex;flex-direction:column;gap:14px">'
      + SFL_TIPS.map(t => `<div class="card" style="padding:16px">
          <div style="font-weight:700;margin-bottom:8px">${t.title}</div>
          <div style="color:var(--muted);font-size:0.95rem;line-height:1.5">${t.body}</div>
        </div>`).join('')
      + '</div>';
  }
}
function sflPickOpt(i){
  if(_sflDrillAnswered) return;
  _sflDrillAnswered = true;
  _sflPickedIdx = i;
  const d = SFL_DRILLS[_sflDrillIdx % SFL_DRILLS.length];
  const correct = (i === d.ans);
  _sflDrillScore.total++;
  if(correct){
    _sflDrillScore.correct++;
    try{ addXp && addXp(10); }catch(e){}
    try{ recordActivity && recordActivity('sfl','drill','correct'); }catch(e){}
    try{ incDailyCount && incDailyCount(); }catch(e){}
  } else {
    try{ addXp && addXp(2); }catch(e){}
  }
  try{ sfx && sfx(correct ? 'correct' : 'wrong'); }catch(e){}
  renderSfl();
}
function sflNext(){
  _sflDrillIdx++;
  _sflDrillAnswered = false;
  _sflPickedIdx = null;
  renderSfl();
}
// Self-register in Topics coach extension
