let _kttTab = 'words';
let _kttDrillIdx = 0;
let _kttDrillAnswered = false;
let _kttPickedIdx = null;
let _kttDrillScore = {correct:0, total:0};

function openKtt(){
  bumpAchievementCounter && bumpAchievementCounter('ktt_open');
  const ov = document.getElementById('ktt-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _kttDrillIdx = 0; _kttDrillAnswered = false; _kttPickedIdx = null; _kttDrillScore = {correct:0,total:0};
  setKttTab('words');
}
function closeKtt(){ const ov=document.getElementById('ktt-overlay'); if(ov) ov.style.display='none'; }
function setKttTab(t){
  _kttTab = t;
  const bar = document.getElementById('ktt-tab-bar');
  if(bar){
    const tabs = [['words','📋 Words'],['drill','🎯 Drill'],['tips','💡 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_kttTab===k?'active':''}" onclick="setKttTab('${k}')">${l}</button>`).join('');
  }
  renderKtt();
}
function renderKtt(){
  const el = document.getElementById('ktt-content');
  const st = document.getElementById('ktt-stats');
  if(!el) return;
  if(_kttTab === 'words'){
    if(st) st.textContent = KTT_WORDS.length + ' words';
    el.innerHTML = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">'
      + KTT_WORDS.map(w => `<div class="card" style="padding:12px 14px">
          <div style="font-size:1.3rem;font-weight:700">${w.ar}</div>
          <div style="color:var(--accent);font-size:0.9rem">${w.tr}</div>
          <div style="color:var(--muted);font-size:0.85rem">${w.en}</div>
        </div>`).join('')
      + '</div>';
  } else if(_kttTab === 'drill'){
    const idx = _kttDrillIdx % KTT_DRILLS.length;
    const d = KTT_DRILLS[idx];
    const pct = _kttDrillScore.total ? Math.round(_kttDrillScore.correct/_kttDrillScore.total*100) : 0;
    if(st) st.textContent = `${_kttDrillScore.correct}/${_kttDrillScore.total} (${pct}%)`;
    el.innerHTML = `<div class="card" style="padding:20px;max-width:600px;margin:0 auto">
      <div style="font-size:0.8rem;color:var(--muted);margin-bottom:10px">Q ${idx+1} / ${KTT_DRILLS.length}</div>
      <div style="font-weight:700;font-size:1.05rem;margin-bottom:16px">${d.q}</div>
      <div style="display:flex;flex-direction:column;gap:8px">
        ${d.opts.map((o,i) => {
          let bg='', border='1px solid var(--border)';
          if(_kttDrillAnswered){
            if(i===d.ans){ bg='background:var(--success-bg,#d1fae5);'; border='1px solid var(--success,#10b981)'; }
            else if(i===_kttPickedIdx){ bg='background:var(--danger-bg,#fee2e2);'; border='1px solid var(--danger,#ef4444)'; }
          }
          return `<button onclick="kttPickOpt(${i})" style="${bg}border:${border};border-radius:10px;padding:12px 16px;text-align:left;cursor:pointer;font-size:0.95rem;transition:all .15s" ${_kttDrillAnswered?'disabled':''}>${o}</button>`;
        }).join('')}
      </div>
      ${_kttDrillAnswered ? `<button class="btn btn-outline" onclick="kttNext()" style="margin-top:16px;width:100%">Next →</button>` : ''}
    </div>`;
  } else {
    if(st) st.textContent = '';
    if(typeof KTT_TIPS==='undefined'||!KTT_TIPS.length){el.innerHTML='<p>No tips.</p>';return;}
    el.innerHTML = '<div style="display:flex;flex-direction:column;gap:14px">'
      + KTT_TIPS.map(t => `<div class="card" style="padding:16px">
          <div style="font-weight:700;margin-bottom:8px">${t.title}</div>
          <div style="color:var(--muted);font-size:0.95rem;line-height:1.5">${t.body}</div>
        </div>`).join('')
      + '</div>';
  }
}
function kttPickOpt(i){
  if(_kttDrillAnswered) return;
  _kttDrillAnswered = true;
  _kttPickedIdx = i;
  const d = KTT_DRILLS[_kttDrillIdx % KTT_DRILLS.length];
  const correct = (i === d.ans);
  _kttDrillScore.total++;
  if(correct){
    _kttDrillScore.correct++;
    try{ addXp && addXp(10); }catch(e){}
    try{ recordActivity && recordActivity('ktt','drill','correct'); }catch(e){}
    try{ incDailyCount && incDailyCount(); }catch(e){}
  } else {
    try{ addXp && addXp(2); }catch(e){}
  }
  try{ sfx && sfx(correct ? 'correct' : 'wrong'); }catch(e){}
  renderKtt();
}
function kttNext(){
  _kttDrillIdx++;
  _kttDrillAnswered = false;
  _kttPickedIdx = null;
  renderKtt();
}
// Self-register in Topics coach extension
