// ── R1104 NEW FEATURE: Lebanese Baby & Newborn Traditions (bby) ───────────────
let _bbyTab = 'words';
let _bbyDrillIdx = 0;
let _bbyDrillAnswered = false;
let _bbyPickedIdx = null;
let _bbyDrillScore = {correct:0, total:0};

function openBby(){
  bumpAchievementCounter && bumpAchievementCounter('bby_open');
  var ov = document.getElementById('bby-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setBbyTab('words');
}
function closeBby(){ var ov=document.getElementById('bby-overlay'); if(ov) ov.style.display='none'; }
function setBbyTab(t){
  _bbyTab = t;
  var bar = document.getElementById('bby-tab-bar');
  if(bar){
    var tabs=[['words','📖 Words'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(function(p){ return '<button class="cat-filter '+(_bbyTab===p[0]?'active':'')+'" onclick="setBbyTab(\''+p[0]+'\')">'+p[1]+'</button>'; }).join('');
  }
  renderBby();
}
function renderBby(){
  var el = document.getElementById('bby-content'); if(!el) return;
  var st = document.getElementById('bby-stats');
  var words = typeof BBY_WORDS !== 'undefined' ? BBY_WORDS : [];
  var drills = typeof BBY_DRILLS !== 'undefined' ? BBY_DRILLS : [];
  var tips = typeof BBY_TIPS !== 'undefined' ? BBY_TIPS : [];
  if(_bbyTab === 'words'){
    if(st) st.textContent = words.length + ' terms';
    el.innerHTML = '<div style="display:grid;gap:10px">' + words.map(function(w){
      return '<div style="background:var(--card);padding:14px;border-radius:10px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px">'
        +'<div><div style="font-size:1.35rem;font-weight:700;color:var(--accent)">' + w.ar + '</div>'
        +'<div style="color:var(--muted);font-size:0.85rem">' + w.tr + '</div></div>'
        +'<div style="font-size:0.9rem;max-width:220px;text-align:right">' + w.en + '</div></div>';
    }).join('') + '</div>';
  } else if(_bbyTab === 'drill'){
    if(st) st.textContent = 'Score: ' + _bbyDrillScore.correct + '/' + _bbyDrillScore.total;
    if(!drills.length){ el.innerHTML='<p style="color:var(--muted);text-align:center">No drills yet.</p>'; return; }
    var q = drills[_bbyDrillIdx % drills.length];
    var html = '<div style="background:var(--card);padding:20px;border-radius:12px;max-width:600px;margin:0 auto">'
      +'<div style="font-size:1.05rem;font-weight:600;margin-bottom:18px;text-align:center">'+q.q+'</div>'
      +'<div style="display:grid;gap:10px">';
    q.opts.forEach(function(o,i){
      var bg='var(--card)'; var col='';
      if(_bbyDrillAnswered){
        if(i===q.ans){ bg='#1a3a2a'; col='color:#4ade80;'; }
        else if(i===_bbyPickedIdx){ bg='#3a1a1a'; col='color:#f87171;'; }
      }
      html += '<button onclick="bbyPickOpt('+i+')" style="background:'+bg+';border:1px solid var(--border);border-radius:8px;padding:12px 16px;text-align:left;cursor:pointer;'+col+'">'+(i+1)+'. '+o+'</button>';
    });
    html += '</div>';
    if(_bbyDrillAnswered) html += '<div style="text-align:center;margin-top:16px"><button class="btn btn-primary" onclick="bbyNext()">Next →</button></div>';
    html += '</div>';
    el.innerHTML = html;
  } else {
    if(st) st.textContent = tips.length + ' tips';
    el.innerHTML = '<div style="display:grid;gap:12px">' + tips.map(function(tip,i){
      return '<div style="background:var(--card);padding:16px;border-radius:10px;border-left:3px solid var(--accent)">'
        +'<span style="font-weight:700;color:var(--accent)">'+(i+1)+'.</span> '+tip+'</div>';
    }).join('') + '</div>';
  }
}
function bbyPickOpt(i){
  if(_bbyDrillAnswered) return;
  _bbyPickedIdx = i; _bbyDrillAnswered = true;
  var drills = typeof BBY_DRILLS !== 'undefined' ? BBY_DRILLS : [];
  var q = drills[_bbyDrillIdx % drills.length];
  var correct = (i === q.ans);
  if(correct){ _bbyDrillScore.correct++; try{addXp&&addXp(10);}catch(e){} try{sfx('correct');}catch(e){} }
  else { try{addXp&&addXp(2);}catch(e){} try{sfx('wrong');}catch(e){} }
  _bbyDrillScore.total++;
  try{recordActivity&&recordActivity('bby_drill');}catch(e){}
  try{incDailyCount&&incDailyCount();}catch(e){}
  renderBby();
}
function bbyNext(){
  _bbyDrillIdx++; _bbyDrillAnswered = false; _bbyPickedIdx = null;
  renderBby();
}

