// ── R1107 NEW FEATURE: Lebanese Zodiac & Astrology Culture (brj) ──────────────
let _brjTab = 'vocab';
let _brjDrillIdx = 0;
let _brjDrillScore = {correct:0, total:0};
let _brjPicked = false;

function openBrj(){
  bumpAchievementCounter && bumpAchievementCounter('brj_open');
  const ov = document.getElementById('brj-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setBrjTab('vocab');
}
function closeBrj(){ const ov=document.getElementById('brj-overlay'); if(ov) ov.style.display='none'; }
function setBrjTab(t){
  _brjTab = t;
  const bar = document.getElementById('brj-tab-bar');
  if(bar){
    const tabs=[['vocab','⭐ Vocab'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l])=>`<button class="cat-filter ${_brjTab===k?'active':''}" onclick="setBrjTab('${k}')">${l}</button>`).join('');
  }
  renderBrj();
}
function renderBrj(){
  const el = document.getElementById('brj-content'); if(!el) return;
  const stats = document.getElementById('brj-stats');
  if(_brjTab==='vocab'){
    if(stats) stats.textContent = BRJ_WORDS.length+' terms';
    el.innerHTML = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">'
      + BRJ_WORDS.map(w=>`<div class="card" style="padding:12px;cursor:pointer" onclick="speak('${w.tr}')">
          <div style="font-size:1.4rem;font-weight:700">${w.ar}</div>
          <div style="color:var(--muted);font-size:0.85rem">${w.tr}</div>
          <div style="font-size:0.9rem;margin-top:4px">${w.en}</div>
        </div>`).join('')
      + '</div>';
  } else if(_brjTab==='drill'){
    if(stats) stats.textContent = 'Score: '+_brjDrillScore.correct+'/'+_brjDrillScore.total;
    if(!BRJ_DRILLS.length){el.innerHTML='<p>No drills yet.</p>';return;}
    const idx = _brjDrillIdx % BRJ_DRILLS.length;
    const q = BRJ_DRILLS[idx];
    el.innerHTML = `<div class="card" style="padding:20px;max-width:560px;margin:0 auto">
      <div style="font-size:0.8rem;color:var(--muted);margin-bottom:8px">Q ${idx+1}/${BRJ_DRILLS.length}</div>
      <div style="font-weight:700;margin-bottom:16px">${q.q}</div>
      <div style="display:grid;gap:8px">
        ${q.opts.map((o,i)=>`<button id="brj-opt-${i}" class="btn btn-outline" style="text-align:left" onclick="brjPickOpt(${i})">${o}</button>`).join('')}
      </div>
      <div id="brj-feedback" style="margin-top:12px;min-height:24px"></div>
      <button class="btn" style="margin-top:12px;display:none" id="brj-next-btn" onclick="brjNext()">Next ▶</button>
    </div>`;
    _brjPicked = false;
  } else {
    if(stats) stats.textContent = BRJ_TIPS.length+' tips';
    el.innerHTML = BRJ_TIPS.map(t=>`<div class="card" style="padding:16px;margin-bottom:10px">
      <div style="font-weight:700;margin-bottom:6px">${t.title}</div>
      <div style="font-size:0.9rem;color:var(--muted)">${t.body}</div>
    </div>`).join('');
  }
}
function brjPickOpt(i){
  if(_brjPicked) return;
  _brjPicked = true;
  const idx = _brjDrillIdx % BRJ_DRILLS.length;
  const q = BRJ_DRILLS[idx];
  const correct = i === q.ans;
  _brjDrillScore.total++;
  if(correct){ _brjDrillScore.correct++; addXp(10); sfx('correct'); }
  else { addXp(2); sfx('wrong'); }
  incDailyCount && incDailyCount();
  recordActivity && recordActivity();
  const fb = document.getElementById('brj-feedback');
  if(fb) fb.innerHTML = correct
    ? '<span style="color:var(--correct)">✓ Correct!</span>'
    : `<span style="color:var(--wrong)">✗ Answer: ${q.opts[q.ans]}</span>`;
  for(let j=0;j<q.opts.length;j++){
    const btn=document.getElementById('brj-opt-'+j);
    if(btn){ btn.disabled=true; if(j===q.ans) btn.style.borderColor='var(--correct)'; else if(j===i) btn.style.borderColor='var(--wrong)'; }
  }
  const nb=document.getElementById('brj-next-btn'); if(nb) nb.style.display='inline-block';
  const statsEl=document.getElementById('brj-stats'); if(statsEl) statsEl.textContent='Score: '+_brjDrillScore.correct+'/'+_brjDrillScore.total;
}
function brjNext(){
  _brjDrillIdx++;
  _brjPicked = false;
  renderBrj();
}

