// R1110 — NEW FEATURE: Lebanese Booza & Ice Cream Culture (bza)
let _bzaTab = 'vocab';
let _bzaCat = 'all';
let _bzaDrillIdx = 0;
let _bzaDrillPicked = false;
let _bzaPickedIdx = null;
let _bzaDrillScore = {correct:0, total:0};

function openBza(){
  bumpAchievementCounter && bumpAchievementCounter('bza_open');
  const ov = document.getElementById('bza-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _bzaDrillIdx = 0; _bzaDrillPicked = false; _bzaPickedIdx = null;
  _bzaDrillScore = {correct:0, total:0};
  setBzaTab('vocab');
}
function closeBza(){ const ov=document.getElementById('bza-overlay'); if(ov) ov.style.display='none'; }
function setBzaTab(t){
  _bzaTab = t;
  const bar = document.getElementById('bza-tab-bar');
  if(bar){
    const tabs = [['vocab','🍦 Vocab'],['drill','🎯 Drill'],['tips','💡 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_bzaTab===k?'active':''}" onclick="setBzaTab('${k}')">${l}</button>`).join('');
  }
  renderBza();
}
function renderBza(){
  const el = document.getElementById('bza-content'); if(!el) return;
  const st = document.getElementById('bza-stats');
  if(_bzaTab === 'vocab') _renderBzaVocab(el, st);
  else if(_bzaTab === 'drill') _renderBzaDrill(el, st);
  else _renderBzaTips(el, st);
}
function _renderBzaVocab(el, st){
  const words = typeof BZA_WORDS !== 'undefined' ? BZA_WORDS : [];
  if(st) st.textContent = words.length + ' terms';
  el.innerHTML = '<div style="display:grid;gap:8px">' +
    words.map(function(w){
      return '<div style="background:var(--card);border-radius:10px;padding:12px 16px;display:flex;justify-content:space-between;align-items:center;gap:12px">' +
        '<div style="font-size:1.2rem;font-weight:700;direction:rtl">' + w.ar + '</div>' +
        '<div style="text-align:center;flex:1">' +
          '<div style="font-style:italic;color:var(--accent)">' + w.tr + '</div>' +
          '<div style="color:var(--muted);font-size:0.9rem">' + w.en + '</div>' +
        '</div>' +
        '<button class="btn btn-sm" onclick="speak(\'' + w.tr.replace(/'/g,"\\'") + '\',\'ar\')" style="padding:4px 10px;font-size:0.8rem">▶</button>' +
      '</div>';
    }).join('') + '</div>';
}
function _renderBzaDrill(el, st){
  const drills = typeof BZA_DRILLS !== 'undefined' ? BZA_DRILLS : [];
  if(!drills.length){ el.innerHTML='<div style="color:var(--muted)">No drills</div>'; return; }
  if(st) st.textContent = _bzaDrillScore.correct + '/' + _bzaDrillScore.total + ' correct';
  const drill = drills[_bzaDrillIdx % drills.length];
  let html = '<div style="text-align:center;margin-bottom:8px;color:var(--muted);font-size:0.85rem">Question ' + (_bzaDrillIdx % drills.length + 1) + ' / ' + drills.length + '</div>';
  html += '<div style="background:var(--card);border-radius:12px;padding:20px;margin-bottom:16px;font-size:1.05rem;font-weight:600">' + drill.q + '</div>';
  html += '<div style="display:grid;gap:8px">' + drill.opts.map(function(opt, i){
    var picked = _bzaPickedIdx !== null;
    var isCorrect = i === drill.ans;
    var isPicked = i === _bzaPickedIdx;
    var bg = '';
    if(picked && isCorrect) bg = 'background:#1a3a1a;border:1px solid #3fb950;';
    else if(picked && isPicked) bg = 'background:#3a1a1a;border:1px solid #e06060;';
    else bg = 'background:var(--card);border:1px solid var(--border);';
    return '<button onclick="bzaPickOpt(' + i + ')" style="' + bg + 'border-radius:8px;padding:12px 16px;text-align:left;cursor:pointer;color:var(--text);font-size:0.95rem">' + opt + '</button>';
  }).join('') + '</div>';
  if(_bzaPickedIdx !== null){
    var correct = _bzaPickedIdx === drill.ans;
    html += '<div style="margin-top:12px;text-align:center;color:' + (correct?'#3fb950':'#e06060') + ';font-weight:700">' + (correct?'✓ Correct!':'✗ Wrong — ' + drill.opts[drill.ans]) + '</div>';
    html += '<div style="margin-top:10px;text-align:center"><button class="btn" onclick="bzaNext()">Next ▶</button></div>';
  }
  el.innerHTML = html;
}
function _renderBzaTips(el, st){
  const tips = typeof BZA_TIPS !== 'undefined' ? BZA_TIPS : [];
  if(st) st.textContent = tips.length + ' culture notes';
  el.innerHTML = '<div style="display:grid;gap:12px">' +
    tips.map(function(t){
      return '<div style="background:var(--card);border-radius:10px;padding:16px">' +
        '<div style="font-weight:700;margin-bottom:6px">🍦 ' + t.title + '</div>' +
        '<div style="color:var(--muted);line-height:1.6">' + t.body + '</div>' +
      '</div>';
    }).join('') + '</div>';
}
function bzaPickOpt(i){
  if(_bzaPickedIdx !== null) return;
  const drills = typeof BZA_DRILLS !== 'undefined' ? BZA_DRILLS : [];
  const drill = drills[_bzaDrillIdx % drills.length];
  _bzaPickedIdx = i;
  _bzaDrillScore.total++;
  const correct = i === drill.ans;
  if(correct){ _bzaDrillScore.correct++; recordActivity(); incDailyCount(); addXp(10); sfx && sfx('correct'); }
  else { addXp(2); sfx && sfx('wrong'); }
  _bzaDrillPicked = true;
  renderBza();
}
function bzaNext(){
  _bzaDrillIdx++;
  _bzaPickedIdx = null;
  _bzaDrillPicked = false;
  renderBza();
}

