// R1113 — NEW FEATURE: Lebanese Promenade & Walking Culture (msh)
let _mshTab = 'words';
let _mshDrillIdx = 0;
let _mshDrillAnswered = false;

function openMsh(){
  bumpAchievementCounter && bumpAchievementCounter('msh_open');
  const ov = document.getElementById('msh-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _mshDrillIdx = 0;
  _mshDrillAnswered = false;
  setMshTab('words');
}
function closeMsh(){ const ov=document.getElementById('msh-overlay'); if(ov) ov.style.display='none'; }
function setMshTab(t){
  _mshTab = t;
  const bar = document.getElementById('msh-tab-bar');
  if(bar){
    const tabs = [['words','🚶 Words'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_mshTab===k?'active':''}" onclick="setMshTab('${k}')">${l}</button>`).join('');
  }
  renderMsh();
}
function renderMsh(){
  const el = document.getElementById('msh-content'); if(!el) return;
  const stats = document.getElementById('msh-stats');
  if(_mshTab === 'words'){
    if(stats) stats.textContent = (typeof MSH_WORDS !== 'undefined' ? MSH_WORDS.length : 0) + ' phrases';
    const words = typeof MSH_WORDS !== 'undefined' ? MSH_WORDS : [];
    el.innerHTML = '<div style="display:grid;gap:10px;grid-template-columns:repeat(auto-fill,minmax(260px,1fr))">' +
      words.map(w => `<div class="card" style="padding:14px;cursor:pointer" onclick="speak('${w.ar.replace(/'/g,"\\'")}')">
        <div style="font-size:1.3rem;font-weight:700;direction:rtl">${w.ar}</div>
        <div style="color:var(--accent);font-size:0.9rem;margin:4px 0">${w.tr}</div>
        <div style="color:var(--muted);font-size:0.85rem">${w.en}</div>
      </div>`).join('') + '</div>';
  } else if(_mshTab === 'drill'){
    const drills = typeof MSH_DRILLS !== 'undefined' ? MSH_DRILLS : [];
    if(!drills.length){ el.innerHTML = '<p style="color:var(--muted)">No drills.</p>'; return; }
    if(stats) stats.textContent = 'Drill ' + (_mshDrillIdx % drills.length + 1) + '/' + drills.length;
    const d = drills[_mshDrillIdx % drills.length];
    el.innerHTML = `<div style="text-align:center;max-width:500px;margin:0 auto">
      <div style="font-size:2rem;font-weight:700;direction:rtl;margin-bottom:24px;cursor:pointer" onclick="speak('${d.q.replace(/'/g,"\\'")}')">
        ${d.q} <span style="font-size:1rem;opacity:0.5">🔊</span>
      </div>
      <div style="display:grid;gap:10px;grid-template-columns:1fr 1fr" id="msh-opts">
        ${d.opts.map((o,i) => `<button class="btn btn-outline" id="msh-opt-${i}" onclick="mshPickOpt(${i})">${o}</button>`).join('')}
      </div>
      <div id="msh-feedback" style="margin-top:16px;min-height:24px"></div>
      ${_mshDrillAnswered ? `<button class="btn" style="margin-top:16px" onclick="mshNext()">Next ➜</button>` : ''}
    </div>`;
  } else {
    const tips = typeof MSH_TIPS !== 'undefined' ? MSH_TIPS : [];
    if(stats) stats.textContent = tips.length + ' tips';
    el.innerHTML = '<div style="display:grid;gap:14px">' +
      tips.map(t => `<div class="card" style="padding:16px">
        <div style="font-weight:700;margin-bottom:6px">💡 ${t.title}</div>
        <div style="color:var(--muted);font-size:0.9rem;line-height:1.5">${t.body}</div>
      </div>`).join('') + '</div>';
  }
}
function mshPickOpt(i){
  if(_mshDrillAnswered) return;
  _mshDrillAnswered = true;
  const drills = typeof MSH_DRILLS !== 'undefined' ? MSH_DRILLS : [];
  const d = drills[_mshDrillIdx % drills.length];
  const correct = i === d.ans;
  recordActivity && recordActivity('msh');
  incDailyCount && incDailyCount();
  if(correct){
    addXp && addXp(XP_PER_RATING ? (XP_PER_RATING[2]||10) : 10);
    sfx && sfx('correct');
  } else {
    addXp && addXp(2);
    sfx && sfx('wrong');
  }
  for(let j=0;j<d.opts.length;j++){
    const b = document.getElementById('msh-opt-'+j);
    if(!b) continue;
    if(j===d.ans) b.style.background = 'var(--easy)';
    else if(j===i) b.style.background = 'var(--hard)';
    b.disabled = true;
  }
  const fb = document.getElementById('msh-feedback');
  if(fb) fb.innerHTML = correct ? '<span style="color:var(--easy)">✓ Correct!</span>' : `<span style="color:var(--hard)">✗ "${d.opts[d.ans]}"</span>`;
  const c = document.getElementById('msh-content');
  if(c){
    const nb = document.createElement('button');
    nb.className = 'btn'; nb.style.marginTop='16px'; nb.textContent = 'Next ➜';
    nb.onclick = mshNext;
    c.querySelector('div').appendChild(nb);
  }
}
function mshNext(){
  _mshDrillIdx++;
  _mshDrillAnswered = false;
  renderMsh();
}

