// R1116 — NEW FEATURE: Lebanese School Field Trip & Excursion Culture (rhl)
let _rhlTab = 'words';
let _rhlDrillIdx = 0;
let _rhlDrillAnswered = false;
let _rhlPickedIdx = null;
let _rhlDrillScore = {correct:0, total:0};

function openRhl(){
  bumpAchievementCounter && bumpAchievementCounter('rhl_open');
  const ov = document.getElementById('rhl-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _rhlDrillIdx = 0; _rhlDrillAnswered = false; _rhlPickedIdx = null;
  _rhlDrillScore = {correct:0, total:0};
  setRhlTab('words');
}
function closeRhl(){ const ov=document.getElementById('rhl-overlay'); if(ov) ov.style.display='none'; }
function setRhlTab(t){
  _rhlTab = t;
  const bar = document.getElementById('rhl-tab-bar');
  if(bar){
    const tabs = [['words','📚 Vocab'],['drill','🎯 Drill'],['tips','💡 Culture']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_rhlTab===k?'active':''}" onclick="setRhlTab('${k}')">${l}</button>`).join('');
  }
  renderRhl();
}
function renderRhl(){
  const el = document.getElementById('rhl-content'); if(!el) return;
  const st = document.getElementById('rhl-stats');
  if(_rhlTab === 'words') _renderRhlWords(el, st);
  else if(_rhlTab === 'drill') _renderRhlDrill(el, st);
  else _renderRhlTips(el, st);
}
function _renderRhlWords(el, st){
  const words = typeof RHL_WORDS !== 'undefined' ? RHL_WORDS : [];
  if(st) st.textContent = words.length + ' terms';
  el.innerHTML = '<div style="display:grid;gap:8px">' +
    words.map(function(w){
      return '<div style="background:var(--card);border-radius:10px;padding:12px 16px;display:flex;justify-content:space-between;align-items:center;gap:12px">' +
        '<div style="font-size:1.2rem;font-weight:700;direction:rtl">' + w.ar + '</div>' +
        '<div style="text-align:center;flex:1"><div style="font-style:italic;color:var(--accent)">' + w.tr + '</div>' +
        '<div style="color:var(--muted);font-size:0.9rem">' + w.en + '</div></div>' +
        '<button class="btn btn-sm" onclick="speak(\'' + w.tr.replace(/'/g,"\\'") + '\',\'ar\')" style="padding:4px 10px;font-size:0.8rem">▶</button>' +
      '</div>';
    }).join('') + '</div>';
}
function _renderRhlDrill(el, st){
  const drills = typeof RHL_DRILLS !== 'undefined' ? RHL_DRILLS : [];
  if(!drills.length){ el.innerHTML='<p>No drills.</p>'; return; }
  if(_rhlDrillIdx >= drills.length){
    const pct = Math.round((_rhlDrillScore.correct/drills.length)*100);
    if(st) st.textContent = 'Done! ' + pct + '%';
    el.innerHTML = '<div style="text-align:center;padding:32px">' +
      '<div style="font-size:3rem">🚌</div>' +
      '<h3>' + _rhlDrillScore.correct + '/' + drills.length + ' correct (' + pct + '%)</h3>' +
      '<button class="btn btn-primary" onclick="_rhlDrillIdx=0;_rhlDrillAnswered=false;_rhlPickedIdx=null;_rhlDrillScore={correct:0,total:0};renderRhl()">Retry</button>' +
    '</div>';
    return;
  }
  const d = drills[_rhlDrillIdx];
  if(st) st.textContent = (_rhlDrillIdx+1) + '/' + drills.length + ' · ' + _rhlDrillScore.correct + ' correct';
  el.innerHTML = '<div style="padding:16px">' +
    '<div style="font-size:1.2rem;font-weight:700;margin-bottom:18px;text-align:right">' + d.q + '</div>' +
    d.opts.map(function(o,i){
      let bg = 'var(--card-bg)';
      if(_rhlDrillAnswered){ if(i===d.ans) bg='var(--success,#2d6a4f)'; else if(i===_rhlPickedIdx) bg='var(--error,#c1121f)'; }
      return '<button onclick="rhlPickOpt(' + i + ')" style="width:100%;text-align:left;padding:12px 16px;margin-bottom:8px;border-radius:8px;background:' + bg + ';border:1px solid var(--border);color:var(--text);cursor:pointer">' + o + '</button>';
    }).join('') +
    (_rhlDrillAnswered ? '<button class="btn btn-primary" style="margin-top:12px" onclick="rhlNext()">Next →</button>' : '') +
  '</div>';
}
function _renderRhlTips(el, st){
  const tips = typeof RHL_TIPS !== 'undefined' ? RHL_TIPS : [];
  if(st) st.textContent = tips.length + ' cultural notes';
  el.innerHTML = tips.map(function(t){
    return '<div style="margin-bottom:18px;padding:16px;border-radius:8px;background:var(--card-bg)">' +
      '<div style="font-weight:700;margin-bottom:8px">🚌 ' + t.title + '</div>' +
      '<div style="line-height:1.6;color:var(--muted)">' + t.body + '</div>' +
    '</div>';
  }).join('');
}
function rhlPickOpt(i){
  if(_rhlDrillAnswered) return;
  _rhlPickedIdx = i; _rhlDrillAnswered = true;
  const drills = typeof RHL_DRILLS !== 'undefined' ? RHL_DRILLS : [];
  const d = drills[_rhlDrillIdx % drills.length];
  const correct = (i === d.ans);
  _rhlDrillScore.total++;
  if(correct) _rhlDrillScore.correct++;
  try{ recordActivity && recordActivity(); }catch(e){}
  try{ incDailyCount && incDailyCount(); }catch(e){}
  try{ addXp && addXp(correct ? 10 : 2); }catch(e){}
  try{ sfx && sfx(correct ? 'correct' : 'wrong'); }catch(e){}
  renderRhl();
}
function rhlNext(){
  _rhlDrillIdx++; _rhlDrillAnswered = false; _rhlPickedIdx = null;
  renderRhl();
}
