let _jrnTab = 'words';
let _jrnDrillIdx = 0;
let _jrnDrillAnswered = false;
let _jrnPickedIdx = null;
let _jrnDrillScore = {correct:0, total:0};

function openJrn(){
  _jrnTab = 'words';
  _jrnDrillIdx = 0;
  _jrnDrillAnswered = false;
  _jrnPickedIdx = null;
  _jrnDrillScore = {correct:0, total:0};
  const ov = document.getElementById('jrn-overlay');
  if(!ov) return;
  ov.style.display = 'block';
  setJrnTab('words');
}
function closeJrn(){
  const ov = document.getElementById('jrn-overlay');
  if(ov) ov.style.display = 'none';
}
function setJrnTab(t){
  _jrnTab = t;
  const bar = document.getElementById('jrn-tab-bar');
  if(bar){
    const tabs = [['words','📋 Words'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(function(tb){ return '<button class="cat-filter ' + (_jrnTab===tb[0]?'active':'') + '" onclick="setJrnTab(\'' + tb[0] + '\')">' + tb[1] + '</button>'; }).join('');
  }
  renderJrn();
}
function renderJrn(){
  const el = document.getElementById('jrn-content');
  if(!el) return;
  const stats = document.getElementById('jrn-stats');
  if(stats) stats.textContent = _jrnDrillScore.total > 0 ? (_jrnDrillScore.correct + '/' + _jrnDrillScore.total + ' correct') : '';
  if(_jrnTab === 'words'){
    var rows = JRN_WORDS.map(function(w,i){
      return '<div style="display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid var(--border)">' +
        '<button class="btn btn-outline" style="min-width:36px" onclick="speak(\'' + w.tr + '\',\'ar\')" aria-label="play">▶</button>' +
        '<span style="font-size:1.2rem;min-width:90px">' + w.ar + '</span>' +
        '<span style="color:var(--muted);min-width:90px">' + w.tr + '</span>' +
        '<span>' + w.en + '</span>' +
        '</div>';
    }).join('');
    el.innerHTML = '<div style="margin-bottom:8px;color:var(--muted);font-size:0.85rem">' + JRN_WORDS.length + ' words</div>' + rows;
  } else if(_jrnTab === 'drill'){
    if(!JRN_DRILLS || JRN_DRILLS.length === 0){ el.innerHTML = '<p>No drills yet.</p>'; return; }
    if(_jrnDrillIdx >= JRN_DRILLS.length){
      el.innerHTML = '<div style="text-align:center;padding:40px"><h3>Done! ' + _jrnDrillScore.correct + '/' + _jrnDrillScore.total + ' correct</h3>' +
        '<button class="btn" onclick="_jrnDrillIdx=0;_jrnDrillAnswered=false;_jrnPickedIdx=null;_jrnDrillScore={correct:0,total:0};renderJrn()">Restart</button></div>';
      return;
    }
    var d = JRN_DRILLS[_jrnDrillIdx];
    var optsHtml = d.opts.map(function(opt,i){
      var cls = 'btn btn-outline';
      if(_jrnDrillAnswered){
        if(i === d.a) cls = 'btn' + ' correct-btn';
        else if(i === _jrnPickedIdx) cls = 'btn' + ' wrong-btn';
      }
      return '<button class="' + cls + '" style="width:100%;margin:4px 0;text-align:left" ' + (_jrnDrillAnswered?'disabled':'') + ' onclick="jrnPickOpt(' + i + ')">' + opt + '</button>';
    }).join('');
    el.innerHTML = '<div style="padding:8px 0">' +
      '<div style="color:var(--muted);font-size:0.85rem;margin-bottom:8px">Question ' + (_jrnDrillIdx+1) + ' / ' + JRN_DRILLS.length + '</div>' +
      '<div style="font-size:1.05rem;font-weight:600;margin-bottom:14px">' + d.q + '</div>' +
      optsHtml +
      (_jrnDrillAnswered ? '<div style="margin-top:12px;padding:10px;background:var(--surface);border-radius:8px;font-size:0.9rem">' + d.ex + '</div>' +
        '<button class="btn" style="margin-top:12px" onclick="jrnNext()">Next →</button>' : '') +
      '</div>';
  } else if(_jrnTab === 'tips'){
    el.innerHTML = (JRN_TIPS||[]).map(function(t){
      return '<div style="margin-bottom:18px;padding:14px;background:var(--surface);border-radius:10px">' +
        '<div style="font-weight:700;margin-bottom:6px">' + t.title + '</div>' +
        '<div style="font-size:0.95rem;line-height:1.6">' + t.body + '</div>' +
        '</div>';
    }).join('');
  }
}
function jrnPickOpt(i){
  if(_jrnDrillAnswered) return;
  _jrnPickedIdx = i;
  _jrnDrillAnswered = true;
  var d = JRN_DRILLS[_jrnDrillIdx];
  var correct = (i === d.a);
  _jrnDrillScore.total++;
  if(correct){ _jrnDrillScore.correct++; try{ sfx && sfx('correct'); }catch(e){} }
  else{ try{ sfx && sfx('wrong'); }catch(e){} }
  try{ recordActivity && recordActivity('jrn_drill'); }catch(e){}
  try{ incDailyCount && incDailyCount(); }catch(e){}
  try{ addXp && addXp(correct?3:1); }catch(e){}
  renderJrn();
}
function jrnNext(){
  _jrnDrillIdx++;
  _jrnDrillAnswered = false;
  _jrnPickedIdx = null;
  renderJrn();
}

