// ── R1155 NEW FEATURE: Lebanese Butcher & Meat Culture (lhm) ─────────────────
let _lhmTab = 'vocab';
let _lhmDrillIdx = 0;
let _lhmDrillAnswered = false;
let _lhmPickedIdx = null;
let _lhmDrillScore = { correct: 0, total: 0 };

function openLhm(){
  bumpAchievementCounter && bumpAchievementCounter('lhm_open');
  var ov = document.getElementById('lhm-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setLhmTab('vocab');
}
function closeLhm(){ var ov=document.getElementById('lhm-overlay'); if(ov) ov.style.display='none'; }
function setLhmTab(t){
  _lhmTab = t;
  var bar = document.getElementById('lhm-tab-bar');
  if(bar){
    var tabs = [['vocab','🥩 Vocab'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(function(tb){
      return '<button class="cat-filter' + (_lhmTab===tb[0]?' active':'') + '" onclick="setLhmTab(\''+tb[0]+'\')">' + tb[1] + '</button>';
    }).join('');
  }
  if(t==='drill'){ _lhmDrillIdx=0; _lhmDrillAnswered=false; _lhmPickedIdx=null; _lhmDrillScore={correct:0,total:0}; }
  renderLhm();
}
function renderLhm(){
  var el = document.getElementById('lhm-content'); if(!el) return;
  var st = document.getElementById('lhm-stats');
  if(_lhmTab==='vocab'){
    if(st) st.textContent = (typeof LHM_WORDS!=='undefined') ? LHM_WORDS.length+' words' : '';
    el.innerHTML = _lhmRenderVocab();
  } else if(_lhmTab==='drill'){
    if(st){
      var s=_lhmDrillScore;
      st.textContent = s.total ? s.correct+'/'+s.total+' correct' : '';
    }
    el.innerHTML = _lhmRenderDrill();
  } else {
    if(st) st.textContent = '';
    el.innerHTML = _lhmRenderTips();
  }
}
function _lhmRenderVocab(){
  if(typeof LHM_WORDS==='undefined') return '<p>Data not loaded.</p>';
  var html = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px">';
  LHM_WORDS.forEach(function(w){
    html += '<div style="background:var(--card);border-radius:10px;padding:14px">';
    html += '<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px">';
    html += '<div><div style="font-size:1.6rem;font-family:serif;direction:rtl">'+w.ar+'</div>';
    html += '<div style="color:var(--muted);font-size:0.85rem;margin-top:2px">'+w.tr+'</div></div>';
    html += '<button class="speak-btn" style="width:28px;height:28px;font-size:0.82rem;flex-shrink:0" onclick="event.stopPropagation();speak(\''+w.ar.replace(/'/g,"\\'")+'\')" title="Pronounce">🔊</button>';
    html += '</div>';
    html += '<div style="font-weight:700">'+w.en+'</div>';
    html += '</div>';
  });
  html += '</div>';
  if(typeof LHM_ABOUT!=='undefined'){
    html += '<div style="margin-top:16px;padding:12px;background:var(--card);border-radius:10px;font-size:0.85rem;color:var(--muted)">'+LHM_ABOUT+'</div>';
  }
  return html;
}
function _lhmRenderDrill(){
  if(typeof LHM_DRILLS==='undefined'||!LHM_DRILLS.length) return '<p>Data not loaded.</p>';
  if(_lhmDrillIdx>=LHM_DRILLS.length){
    var s=_lhmDrillScore;
    return '<div style="text-align:center;padding:40px 20px"><div style="font-size:2.5rem;margin-bottom:12px">🎉</div>' +
      '<div style="font-size:1.3rem;font-weight:700;margin-bottom:8px">Drill complete!</div>' +
      '<div style="color:var(--muted);margin-bottom:20px">'+s.correct+' / '+LHM_DRILLS.length+' correct</div>' +
      '<button class="btn btn-primary" onclick="setLhmTab(\'drill\')">Restart</button></div>';
  }
  var d = LHM_DRILLS[_lhmDrillIdx];
  var html = '<div style="max-width:600px;margin:0 auto">';
  html += '<div style="color:var(--muted);font-size:0.85rem;margin-bottom:8px">Question '+(_lhmDrillIdx+1)+' of '+LHM_DRILLS.length+'</div>';
  html += '<div style="background:var(--card);border-radius:12px;padding:18px;margin-bottom:14px;font-size:1.05rem">'+d.q+'</div>';
  html += '<div style="display:flex;flex-direction:column;gap:8px">';
  d.opts.forEach(function(opt, i){
    var style = 'text-align:left;padding:12px 16px;border-radius:8px';
    var disabled = '';
    if(_lhmDrillAnswered){
      disabled = 'disabled';
      if(i===d.ans) style+=';border-color:var(--easy);color:var(--easy)';
      else if(i===_lhmPickedIdx&&_lhmPickedIdx!==d.ans) style+=';border-color:var(--again);color:var(--again)';
    }
    html += '<button class="btn btn-outline" style="'+style+'" '+disabled+' onclick="lhmPickOpt('+i+')">'+opt+'</button>';
  });
  html += '</div>';
  if(_lhmDrillAnswered){
    html += '<div style="margin-top:14px;text-align:center">';
    html += '<button class="btn btn-primary" onclick="_lhmDrillNext()">';
    html += (_lhmDrillIdx+1<LHM_DRILLS.length?'Next →':'See Results')+'</button></div>';
  }
  html += '</div>';
  return html;
}
function lhmPickOpt(i){
  if(_lhmDrillAnswered) return;
  _lhmPickedIdx = i;
  _lhmDrillAnswered = true;
  var d = (typeof LHM_DRILLS!=='undefined') ? LHM_DRILLS[_lhmDrillIdx] : null;
  if(!d) return;
  var correct = i===d.ans;
  if(correct) _lhmDrillScore.correct++;
  _lhmDrillScore.total++;
  try{ sfx && sfx(correct ? sfxCorrect : sfxWrong); }catch(e){}
  try{ if(typeof recordActivity==='function') recordActivity(); }catch(e){}
  try{ if(typeof incDailyCount==='function') incDailyCount(); }catch(e){}
  try{ if(typeof addXp==='function') addXp(correct ? ((typeof XP_PER_RATING!=='undefined'?XP_PER_RATING[2]:0)||10) : 2); }catch(e){}
  renderLhm();
  showToast && showToast(correct ? '✓ Correct!' : '✗ Try again');
}
function _lhmDrillNext(){ _lhmDrillIdx++; _lhmDrillAnswered=false; _lhmPickedIdx=null; renderLhm(); }
function _lhmRenderTips(){
  if(typeof LHM_TIPS==='undefined') return '<p>Data not loaded.</p>';
  return '<div style="max-width:680px;margin:0 auto">' +
    LHM_TIPS.map(function(t,i){
      return '<div style="background:var(--card);border-radius:10px;padding:16px;margin-bottom:12px;display:flex;gap:14px;align-items:flex-start">' +
        '<div style="font-size:1.4rem;min-width:32px;text-align:center;color:var(--accent)">'+(i+1)+'</div>' +
        '<div style="line-height:1.6">'+t+'</div></div>';
    }).join('') + '</div>';
}

// self-register in coaches-ext
(function(){
  try{
    var ext = (typeof topicsCoachExt!=='undefined') ? topicsCoachExt : null;
    if(ext && Array.isArray(ext.items)){
      if(!ext.items.some(function(x){ return x.id==='lhm'; })){
        ext.items.push({ id:'lhm', label:'🥩 Butcher & Meat', fn:'openLhm' });
      }
    }
  }catch(e){}
})();
