// ── R1156 AUDIO: Index LHM_WORDS into speak() chain ───────────────────────────
(function(){
  if(window.__r1156AudioGuard) return;
  window.__r1156AudioGuard = true;
  if(typeof speak === 'function' && !speak.__r1156Audio){
    var _prevSpeak1156 = speak;
    speak = function(text, lang){
      if(typeof LHM_WORDS !== 'undefined' && Array.isArray(LHM_WORDS)){
        for(var i=0;i<LHM_WORDS.length;i++){
          var w = LHM_WORDS[i];
          if(text === w.tr || text === w.ar || text === w.en){
            var target = (lang==='ar' || !lang) ? w.ar : w.tr;
            return _prevSpeak1156.call(this, target, lang||'ar');
          }
        }
      }
      return _prevSpeak1156.apply(this, arguments);
    };
    speak.__r1156Audio = true;
    if(_prevSpeak1156){ Object.keys(_prevSpeak1156).forEach(function(k){ try{ if(!(k in speak)) speak[k]=_prevSpeak1156[k]; }catch(e){} }); }
  }
})();
