// ── R1188 NEW FEATURE: Lebanese Beach Club & Lido Culture (ldo) ──────────────
let _ldoTab = 'vocab';
let _ldoDrillIdx = 0;
let _ldoDrillPicked = false;
let _ldoPickedIdx = null;
let _ldoDrillScore = { correct: 0, total: 0 };

function openLdo(){
  try{ bumpAchievementCounter && bumpAchievementCounter('ldo_open'); }catch(e){}
  const ov = document.getElementById('ldo-overlay');
  if(!ov) return;
  ov.style.display = 'block';
  setLdoTab('vocab');
}
function closeLdo(){ const ov=document.getElementById('ldo-overlay'); if(ov) ov.style.display='none'; }
function setLdoTab(t){
  _ldoTab = t;
  const bar = document.getElementById('ldo-tab-bar');
  if(bar){
    const tabs = [['vocab','🏊 Vocab'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_ldoTab===k?'active':''}" onclick="setLdoTab('${k}')">${l}</button>`).join('');
  }
  renderLdo();
}
function renderLdo(){
  const el = document.getElementById('ldo-content');
  const st = document.getElementById('ldo-stats');
  if(!el) return;
  if(_ldoTab === 'vocab'){
    if(st) st.textContent = LDO_WORDS.length + ' words';
    el.innerHTML = '<div style="display:grid;gap:8px">' +
      LDO_WORDS.map(w => `<div style="background:var(--card);padding:12px 14px;border-radius:10px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px">
        <div>
          <span style="font-size:1.3rem;font-weight:700">${w.ar}</span>
          <span style="color:var(--muted);margin-left:10px">${w.tr}</span>
        </div>
        <div style="display:flex;align-items:center;gap:8px">
          <span style="color:var(--accent)">${w.en}</span>
          <button class="btn btn-sm btn-outline" onclick="speak('${w.ar.replace(/'/g,"\\'")}')">🔊</button>
        </div>
      </div>`).join('') +
    '</div>';
  } else if(_ldoTab === 'drill'){
    if(st) st.textContent = _ldoDrillScore.correct + '/' + _ldoDrillScore.total + ' correct';
    const d = LDO_DRILLS[_ldoDrillIdx % LDO_DRILLS.length];
    el.innerHTML = `<div style="background:var(--card);padding:20px;border-radius:12px;max-width:520px;margin:0 auto">
      <div style="font-weight:600;font-size:1.05rem;margin-bottom:18px;text-align:center">${d.q}</div>
      <div style="display:grid;gap:10px">
        ${d.opts.map((o,i) => {
          let cls = 'btn btn-outline';
          if(_ldoDrillPicked){
            if(i === d.ans) cls = 'btn btn-success';
            else if(i === _ldoPickedIdx) cls = 'btn btn-danger';
          }
          return `<button class="${cls}" style="width:100%;text-align:left" onclick="ldoPickOpt(${i})">${o}</button>`;
        }).join('')}
      </div>
      ${_ldoDrillPicked ? `<div style="margin-top:14px;text-align:center"><button class="btn btn-primary" onclick="ldoNext()">Next →</button></div>` : ''}
    </div>`;
  } else if(_ldoTab === 'tips'){
    if(st) st.textContent = LDO_TIPS.length + ' tips';
    el.innerHTML = '<div style="display:grid;gap:14px">' +
      LDO_TIPS.map(t => `<div style="background:var(--card);padding:16px;border-radius:12px">
        <div style="font-weight:700;margin-bottom:8px">🏖️ ${t.title}</div>
        <div style="color:var(--muted);line-height:1.6">${t.body}</div>
      </div>`).join('') +
    '</div>';
  }
}
function ldoPickOpt(i){
  if(_ldoDrillPicked) return;
  try{ incDailyCount && incDailyCount(); }catch(e){}
  try{ addXp && addXp(1); }catch(e){}
  _ldoPickedIdx = i;
  _ldoDrillPicked = true;
  const d = LDO_DRILLS[_ldoDrillIdx % LDO_DRILLS.length];
  _ldoDrillScore.total++;
  const correct = (i === d.ans);
  if(correct){
    _ldoDrillScore.correct++;
    try{ addXp && addXp(2); }catch(e){}
    try{ sfx && sfx('correct'); }catch(e){}
  } else {
    try{ sfx && sfx('wrong'); }catch(e){}
  }
  try{ recordActivity && recordActivity('ldo_drill'); }catch(e){}
  renderLdo();
}
function ldoNext(){
  _ldoDrillIdx++;
  _ldoDrillPicked = false;
  _ldoPickedIdx = null;
  renderLdo();
}

// ── R1189 AUDIO: Index LDO_WORDS into speak() chain ─────────────────────────
(function(){
  if(window.__r1189AudioGuard) return;
  window.__r1189AudioGuard = true;
  if(typeof speak !== 'function') return;
  var _prevLdo = speak;
  speak = function(text, slow, externalBtn){
    if(text && typeof LDO_WORDS !== 'undefined' && Array.isArray(LDO_WORDS)){
      for(var i=0;i<LDO_WORDS.length;i++){
        var w = LDO_WORDS[i];
        if(text===w.ar || text===w.tr || text===w.en){
          return _prevLdo(w.ar, slow, externalBtn);
        }
      }
    }
    return _prevLdo(text, slow, externalBtn);
  };
  if(_prevLdo){ Object.keys(_prevLdo).forEach(function(k){ try{ if(!(k in speak)) speak[k]=_prevLdo[k]; }catch(e){} }); }
  speak.__r1189Audio = true;
})();

