// ─── R1198 — AUDIO: Index NYR_WORDS into speak() chain ───
(function(){
  if(window.__r1198AudioGuard) return;
  window.__r1198AudioGuard = true;
  if(typeof speak !== 'function') return;
  var _prev = speak;
  speak = function(text, slow, externalBtn){
    if(text && typeof NYR_WORDS !== 'undefined' && Array.isArray(NYR_WORDS)){
      for(var i=0;i<NYR_WORDS.length;i++){
        var w = NYR_WORDS[i];
        if(text===w.ar || text===w.tr || text===w.en){
          return _prev(w.ar, slow, externalBtn);
        }
      }
    }
    return _prev(text, slow, externalBtn);
  };
  speak.__r1198Audio = true;
})();

