let _mflDrillScore = {correct:0, total:0};

function openMfl(){
  bumpAchievementCounter && bumpAchievementCounter('mfl_open');
  const ov = document.getElementById('mfl-overlay'); if(!ov) return;
  _mflDrillIdx = 0; _mflDrillPicked = false; _mflPickedIdx = null;
  _mflDrillScore = {correct:0, total:0};
  ov.style.display = 'block';
  setMflTab('browse');
}
function closeMfl(){
  const ov = document.getElementById('mfl-overlay'); if(ov) ov.style.display = 'none';
}
function setMflTab(t){
  _mflTab = t;
  const bar = document.getElementById('mfl-tab-bar');
  if(bar){
    const tabs = [['browse','🔧 Words'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_mflTab===k?'active':''}" onclick="setMflTab('${k}')">${l}</button>`).join('');
  }
  renderMfl();
}
function renderMfl(){
  const el = document.getElementById('mfl-content'); if(!el) return;
  const stats = document.getElementById('mfl-stats');
  if(_mflTab === 'browse'){
    if(stats) stats.textContent = (typeof MFL_WORDS !== 'undefined' ? MFL_WORDS.length : 0) + ' words';
    if(typeof MFL_WORDS === 'undefined'){ el.innerHTML='<p>Loading…</p>'; return; }
    el.innerHTML = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px">' +
      MFL_WORDS.map(w => `<div class="card" style="padding:14px;cursor:pointer" onclick="speak('${w.ar}')">
        <div style="font-size:1.5rem;text-align:right;margin-bottom:4px">${w.ar}</div>
        <div style="color:var(--muted);font-size:0.9rem">${w.tr}</div>
        <div style="font-size:0.85rem;margin-top:4px">${w.en}</div>
      </div>`).join('') + '</div>';
  } else if(_mflTab === 'drill'){
    if(typeof MFL_DRILLS === 'undefined'){ el.innerHTML='<p>Loading…</p>'; return; }
    if(stats) stats.textContent = `${_mflDrillScore.correct}/${_mflDrillScore.total}`;
    if(_mflDrillIdx >= MFL_DRILLS.length){
      el.innerHTML = `<div style="text-align:center;padding:40px">
        <div style="font-size:2rem">✅</div>
        <div style="font-size:1.2rem;margin:12px 0">Done! ${_mflDrillScore.correct}/${MFL_DRILLS.length} correct</div>
        <button class="btn btn-primary" onclick="_mflDrillIdx=0;_mflDrillScore={correct:0,total:0};_mflDrillPicked=false;_mflPickedIdx=null;renderMfl()">Try Again</button>
      </div>`; return;
    }
    const d = MFL_DRILLS[_mflDrillIdx];
    el.innerHTML = `<div style="max-width:560px;margin:0 auto">
      <div style="text-align:center;color:var(--muted);font-size:0.85rem;margin-bottom:12px">Question ${_mflDrillIdx+1} / ${MFL_DRILLS.length}</div>
      <div class="card" style="padding:20px;margin-bottom:16px;font-size:1.05rem;text-align:center">${d.q}</div>
      <div style="display:grid;gap:8px">
        ${d.opts.map((o,i) => {
          let cls = 'card'; let extra = '';
          if(_mflDrillPicked){ cls += i===d.a?' correct-answer':i===_mflPickedIdx?' wrong-answer':''; }
          return `<button class="${cls}" style="padding:12px;text-align:left;width:100%;border:none;cursor:pointer" onclick="mflPickOpt(${i})" ${_mflDrillPicked?'disabled':''}>${o}</button>`;
        }).join('')}
      </div>
      ${_mflDrillPicked?`<div style="text-align:center;margin-top:16px"><button class="btn btn-primary" onclick="mflNext()">Next →</button></div>`:''}
    </div>`;
  } else {
    if(typeof MFL_TIPS === 'undefined'){ el.innerHTML='<p>Loading…</p>'; return; }
    if(stats) stats.textContent = '';
    el.innerHTML = '<div style="display:grid;gap:12px">' +
      MFL_TIPS.map(t => `<div class="card" style="padding:16px">
        <div style="font-weight:700;margin-bottom:6px">🔧 ${t.title}</div>
        <div style="color:var(--muted);font-size:0.9rem;line-height:1.5">${t.body}</div>
      </div>`).join('') + '</div>';
  }
}
function mflPickOpt(i){
  if(_mflDrillPicked) return;
  _mflDrillPicked = true; _mflPickedIdx = i;
  const d = MFL_DRILLS[_mflDrillIdx];
  const correct = i === d.a;
  if(correct){ _mflDrillScore.correct++; addXp && addXp(2); } else { addXp && addXp(1); }
  _mflDrillScore.total++;
  recordActivity && recordActivity();
  incDailyCount && incDailyCount();
  sfx && sfx(correct ? 'correct' : 'wrong');
  renderMfl();
}
function mflNext(){
  _mflDrillIdx++; _mflDrillPicked = false; _mflPickedIdx = null;
  renderMfl();
}

// R1207 — AUDIO: Index MFL_WORDS into speak() chain
(function(){
  if(window.__r1207AudioGuard) return;
  window.__r1207AudioGuard = true;
  if(typeof speak !== 'function') return;
  var _prev = speak;
  speak = function(text, slow, externalBtn){
    if(text && typeof MFL_WORDS !== 'undefined' && Array.isArray(MFL_WORDS)){
      for(var i=0;i<MFL_WORDS.length;i++){
        var w = MFL_WORDS[i];
        if(text===w.ar || text===w.tr || text===w.en){
          return _prev(w.ar, slow, externalBtn);
        }
      }
    }
    return _prev(text, slow, externalBtn);
  };
  if(window.__audioFlagsKnown){
    var fk = window.__audioFlagsKnown;
    for(var k in fk){ try{ speak[k]=true; }catch(e){} }
  }
  speak.__r1207Audio = true;
  if(!window.__audioFlagsKnown) window.__audioFlagsKnown = {};
  window.__audioFlagsKnown['__r1207Audio'] = true;
})();

// R1208 — BUG FIX: Restore r1082/r1084b/r1087b speak flags + register in audioFlagsKnown
(function(){
  if(window.__r1208Guard) return;
  window.__r1208Guard = true;
  if(typeof speak !== 'function') return;
  var flags = ['__r1082BrowserStaleFix','__r1084bAudioFix','__r1087bAudioFix'];
  if(!window.__audioFlagsKnown) window.__audioFlagsKnown = {};
  for(var i=0;i<flags.length;i++){
    try{ speak[flags[i]]=true; }catch(e){}
    window.__audioFlagsKnown[flags[i]]=true;
  }
})();

