// R1212 — NEW FEATURE: Lebanese Wild Herb Picking (Za3tar & Mountain Herbs) coach (prefix: ztr)
let _ztrTab = 'browse';
let _ztrDrillIdx = 0;
let _ztrDrillPicked = false;
function openZtr(){
  bumpAchievementCounter && bumpAchievementCounter('ztr_open');
  const ov = document.getElementById('ztr-overlay'); if(!ov) return;
  ov.style.display = 'block';
  _ztrDrillIdx = 0; _ztrDrillPicked = false;
  setZtrTab('browse');
}
function closeZtr(){ const ov=document.getElementById('ztr-overlay'); if(ov) ov.style.display='none'; }
function setZtrTab(t){
  _ztrTab = t;
  const bar = document.getElementById('ztr-tab-bar');
  if(bar){
    const tabs=[['browse','🌿 Browse'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l])=>`<button class="cat-filter ${_ztrTab===k?'active':''}" onclick="setZtrTab('${k}')">${l}</button>`).join('');
  }
  renderZtr();
}
function renderZtr(){
  const el = document.getElementById('ztr-content'); if(!el) return;
  const stats = document.getElementById('ztr-stats');
  if(stats) stats.textContent = ZTR_WORDS.length+' words · '+ZTR_DRILLS.length+' drills';
  if(_ztrTab==='browse') _ztrRenderBrowse(el);
  else if(_ztrTab==='drill') _ztrRenderDrill(el);
  else if(_ztrTab==='tips') _ztrRenderTips(el);
}
function _ztrRenderBrowse(el){
  el.innerHTML = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px">'+
    ZTR_WORDS.map(w=>'<div class="card" style="padding:12px;cursor:pointer" onclick="speak(\''+w.tr+'\',\'ar\')">'+
      '<div style="font-size:1.3rem;font-weight:700">'+w.ar+'</div>'+
      '<div style="color:var(--muted);font-size:0.85rem">'+w.tr+'</div>'+
      '<div style="font-size:0.85rem;margin-top:4px">'+w.en+'</div>'+
      '<div style="font-size:0.75rem;color:var(--muted);margin-top:2px">'+w.cat+'</div>'+
    '</div>').join('')+
  '</div>';
}
function _ztrRenderDrill(el){
  if(!ZTR_DRILLS.length){el.innerHTML='<p>No drills.</p>';return;}
  if(_ztrDrillIdx>=ZTR_DRILLS.length){
    el.innerHTML='<div style="text-align:center;padding:40px"><div style="font-size:2rem">🌿</div><div style="font-size:1.2rem;font-weight:700;margin:12px 0">All done!</div><button class="btn btn-primary" onclick="_ztrDrillIdx=0;_ztrDrillPicked=false;renderZtr()">Again</button></div>';
    return;
  }
  const q=ZTR_DRILLS[_ztrDrillIdx];
  el.innerHTML='<div style="max-width:600px;margin:0 auto"><div style="margin-bottom:8px;color:var(--muted);font-size:0.85rem">'+(_ztrDrillIdx+1)+' / '+ZTR_DRILLS.length+'</div>'+
    '<div style="font-size:1.1rem;font-weight:700;margin-bottom:18px">'+q.q+'</div>'+
    '<div style="display:flex;flex-direction:column;gap:8px" id="ztr-opts">'+
      q.opts.map((o,i)=>'<button class="btn btn-outline" id="ztr-opt-'+i+'" onclick="ztrPickOpt('+i+')">'+o+'</button>').join('')+
    '</div><div id="ztr-exp" style="margin-top:14px"></div></div>';
}
function ztrPickOpt(i){
  if(_ztrDrillPicked) return;
  _ztrDrillPicked = true;
  const q=ZTR_DRILLS[_ztrDrillIdx];
  const correct=(i===q.ans);
  recordActivity && recordActivity('ztr_drill');
  incDailyCount && incDailyCount();
  addXp && addXp(correct?3:1);
  const sfx=document.getElementById('sfx-correct');
  const sfxW=document.getElementById('sfx-wrong');
  if(correct && sfx){try{sfx.currentTime=0;sfx.play();}catch(e){}}
  if(!correct && sfxW){try{sfxW.currentTime=0;sfxW.play();}catch(e){}}
  for(let j=0;j<q.opts.length;j++){
    const b=document.getElementById('ztr-opt-'+j);
    if(!b) continue;
    if(j===q.ans) b.style.background='var(--success,#2a9d5c)';
    else if(j===i) b.style.background='var(--danger,#e63946)';
    b.disabled=true;
  }
  const exp=document.getElementById('ztr-exp');
  if(exp) exp.innerHTML='<div style="padding:10px;border-radius:8px;background:var(--card-bg)">'+(correct?'✅ ':'❌ ')+q.exp+'</div>';
  setTimeout(()=>{ _ztrDrillPicked=false; _ztrDrillIdx++; renderZtr(); },1600);
}
function _ztrRenderTips(el){
  el.innerHTML='<div style="display:flex;flex-direction:column;gap:14px">'+
    ZTR_TIPS.map(t=>'<div class="card" style="padding:16px"><div style="font-weight:700;margin-bottom:6px">'+t.title+'</div><div style="line-height:1.6">'+t.body+'</div></div>').join('')+
  '</div>';
}

