// R1214 — BUG FIX: Restore R1111–R1189 audio flags clobbered by post-R1207 speak() re-wraps
// IIFEs R1111–R1189 set flags on speak but weren't registered in audioFlagsKnown (introduced R1207).
// Later wraps (R1207+) copy only audioFlagsKnown flags → older flags lost. Fix: register + re-stamp.
(function(){
  if(window.__r1214FlagRestoreGuard) return;
  window.__r1214FlagRestoreGuard = true;
  if(typeof speak !== 'function') return;
  var missing = [
    '__r1105bAudioFix',
    '__r1111bBzaAudio','__r1111eBrjAudio',
    '__r1126Audio','__r1129Audio','__r1132Audio',
    '__r1138Audio','__r1141Audio','__r1144Audio',
    '__r1147Audio','__r1150Audio','__r1153Audio',
    '__r1156Audio','__r1159Audio','__r1162Audio',
    '__r1168Audio','__r1171Audio','__r1174Audio',
    '__r1177Audio','__r1180Audio','__r1183Audio',
    '__r1186Audio','__r1189Audio'
  ];
  if(!window.__audioFlagsKnown) window.__audioFlagsKnown = {};
  for(var i=0;i<missing.length;i++){
    window.__audioFlagsKnown[missing[i]] = true;
    try{ speak[missing[i]] = true; }catch(e){}
  }
})();

