    el.innerHTML='<div style="text-align:center;padding:40px"><div style="font-size:2rem">📖</div><div style="font-size:1.2rem;font-weight:700;margin:12px 0">All done!</div><button class="btn btn-primary" onclick="_hkwDrillIdx=0;_hkwDrillPicked=false;renderHkw()">Again</button></div>';
