(function(){
  if(window.__r1232TrackGuard) return;
  window.__r1232TrackGuard = true;

  // att: wrap to add recordActivity + incDailyCount
  var _attOrig = window.attPickOpt;
  window.attPickOpt = function(i){
    if(typeof _attDrillIdx !== 'undefined'){
      var d = (typeof ATT_DRILLS !== 'undefined') ? ATT_DRILLS[_attDrillIdx % ATT_DRILLS.length] : null;
      var correct = d && (i === d.ans);
      _attOrig && _attOrig(i);
      try{ recordActivity && recordActivity('att'); }catch(e){}
      try{ incDailyCount && incDailyCount(); }catch(e){}
    } else {
      _attOrig && _attOrig(i);
    }
  };

  // ztn: wrap to add addXp + recordActivity + incDailyCount
  var _ztnOrig = window.ztnPickOpt;
  window.ztnPickOpt = function(i){
    if(typeof _ztnDrillPicked !== 'undefined' && _ztnDrillPicked) return;
    var d = (typeof ZTN_DRILLS !== 'undefined' && typeof _ztnDrillIdx !== 'undefined') ? ZTN_DRILLS[_ztnDrillIdx] : null;
    var correct = d && (i === d.ans);
    _ztnOrig && _ztnOrig(i);
    try{ addXp && addXp(correct ? 10 : 2); }catch(e){}
    try{ recordActivity && recordActivity('ztn'); }catch(e){}
    try{ incDailyCount && incDailyCount(); }catch(e){}
  };

  // zjl: wrap to add addXp + recordActivity + incDailyCount
  var _zjlOrig = window.zjlPickOpt;
  window.zjlPickOpt = function(i){
    if(typeof _zjlDrillPicked !== 'undefined' && _zjlDrillPicked) return;
    var d = (typeof ZJL_DRILLS !== 'undefined' && typeof _zjlDrillIdx !== 'undefined') ? ZJL_DRILLS[_zjlDrillIdx] : null;
    var correct = d && (i === d.ans);
    _zjlOrig && _zjlOrig(i);
    try{ addXp && addXp(correct ? 10 : 2); }catch(e){}
    try{ recordActivity && recordActivity('zjl'); }catch(e){}
    try{ incDailyCount && incDailyCount(); }catch(e){}
  };
})();

