// ── R1274 BUG FIX: prevent stale async speak() from playing previous card's audio ──
// speak() is async but called without await in renderCard(). When user advances
// before Wiktionary/Commons fetches complete, the old async chain has no gen check
// after the awaits and calls playAudio()/_speakViaBrowser() with the previous word.
// Fix: track the latest speak() call's text; playAudio/_speakViaBrowser abort if text stale.
(function(){
  if(window.__r1274Guard) return;
  window.__r1274Guard = true;

  var _r1274CurrentText = null;

  // Wrap speak() to record which text is the latest call
  if(typeof speak === 'function'){
    var _r1274OrigSpeak = speak;
    speak = function(text, slow, externalBtn){
      _r1274CurrentText = text || null;
      return _r1274OrigSpeak(text, slow, externalBtn);
    };
    // Copy audio flags chain across wrapper
    if(window.__audioFlagsKnown){ var fk=window.__audioFlagsKnown; for(var k in fk){ try{speak[k]=true;}catch(e){} } }
    speak.__r1274Fix = true;
    if(!window.__audioFlagsKnown) window.__audioFlagsKnown = {};
    window.__audioFlagsKnown['__r1274Fix'] = true;
  }

  // Wrap playAudio() — called with text as 5th arg; abort if stale
  if(typeof playAudio === 'function'){
    var _r1274OrigPlayAudio = playAudio;
    playAudio = function(primaryUrl, fallbackUrl, slow, onEnd, text){
      if(text && _r1274CurrentText !== null && text !== _r1274CurrentText){
        if(typeof onEnd === 'function') onEnd();
        return;
      }
      return _r1274OrigPlayAudio(primaryUrl, fallbackUrl, slow, onEnd, text);
    };
    playAudio.__r1274Fix = true;
  }

  // Wrap _speakViaBrowser() — called with text as 1st arg; abort if stale
  if(typeof _speakViaBrowser === 'function'){
    var _r1274OrigSVB = _speakViaBrowser;
    _speakViaBrowser = function(text, slow, clearAnim){
      if(text && _r1274CurrentText !== null && text !== _r1274CurrentText){
        if(typeof clearAnim === 'function') clearAnim();
        return;
      }
      return _r1274OrigSVB(text, slow, clearAnim);
    };
    _speakViaBrowser.__r1274Fix = true;
  }

  window.__r1274Fixed = true;
})();

// ── R1274b: restore __r1082BrowserStaleFix on the re-wrapped _speakViaBrowser ──
(function(){
  if(typeof _speakViaBrowser === 'function') {
    try { _speakViaBrowser.__r1082BrowserStaleFix = true; } catch(e){}
  }
})();

