// R1284 — NEW FEATURE: Lebanese Phone Call & Telephone Etiquette coach (tlf)
let _tlfTab = 'browse';
let _tlfDrillIdx = 0;
let _tlfDrillScore = 0;
let _tlfDrillPicked = null;
let _tlfTipIdx = 0;
function openTlf(){
  bumpAchievementCounter && bumpAchievementCounter('tlf_open');
  const ov = document.getElementById('tlf-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setTlfTab('browse');
}
function closeTlf(){ const ov=document.getElementById('tlf-overlay'); if(ov) ov.style.display='none'; }
function setTlfTab(t){
  _tlfTab = t;
  const bar = document.getElementById('tlf-tab-bar');
  if(bar){
    const tabs = [['browse','📖 Browse'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_tlfTab===k?'active':''}" onclick="setTlfTab('${k}')">${l}</button>`).join('');
  }
  renderTlf();
}
function renderTlf(){
  const el = document.getElementById('tlf-content'); if(!el) return;
  if(_tlfTab==='browse') _tlfRenderBrowse(el);
  else if(_tlfTab==='drill') _tlfRenderDrill(el);
  else _tlfRenderTips(el);
}
function _tlfRenderBrowse(el){
  const st = document.getElementById('tlf-stats');
  if(st) st.textContent = TLF_WORDS.length+' phrases';
  el.innerHTML = TLF_WORDS.map(w => `<div class="card" style="padding:16px;margin-bottom:10px">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
      <span style="font-size:1.4rem;font-weight:700">${w.ar}</span>
      <button class="btn btn-outline" style="padding:4px 10px;font-size:0.8rem" onclick="speak('${w.ar.replace(/'/g,"\\'")}')">🔊</button>
    </div>
    <div style="color:var(--primary);font-weight:600;margin-bottom:4px">${w.tr}</div>
    <div style="color:var(--muted);font-size:0.85rem;margin-bottom:6px">${w.en}</div>
    <div style="font-size:0.82rem;line-height:1.5;color:var(--text)">${w.hint}</div>
  </div>`).join('');
}
function _tlfRenderDrill(el){
  if(_tlfDrillIdx >= TLF_DRILLS.length){
    el.innerHTML = `<div style="text-align:center;padding:40px">
      <div style="font-size:2rem;margin-bottom:16px">📱</div>
      <div style="font-weight:700;font-size:1.2rem;margin-bottom:8px">Drill complete!</div>
      <div style="color:var(--muted);margin-bottom:20px">Score: ${_tlfDrillScore}/${TLF_DRILLS.length}</div>
      <button class="btn btn-primary" onclick="_tlfDrillIdx=0;_tlfDrillScore=0;_tlfDrillPicked=null;renderTlf()">Try Again</button>
    </div>`; return;
  }
  const q = TLF_DRILLS[_tlfDrillIdx];
  const st = document.getElementById('tlf-stats');
  if(st) st.textContent = (_tlfDrillIdx+1)+'/'+TLF_DRILLS.length+' · '+_tlfDrillScore+' pts';
  el.innerHTML = `<div style="padding:10px">
    <div style="font-weight:700;font-size:1.05rem;margin-bottom:20px">${q.q}</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
      ${q.opts.map((o,i) => {
        let bg=''; let op='1';
        if(_tlfDrillPicked!==null){ op='0.6';
          if(i===q.ans) bg='background:rgba(40,200,80,0.15);border-color:var(--primary)';
          else if(i===_tlfDrillPicked) bg='background:rgba(220,50,50,0.12);border-color:#e55'; }
        return `<button class="card" style="padding:14px;text-align:left;cursor:pointer;opacity:${op};${bg}" onclick="tlfPickOpt(${i})">${o}</button>`;
      }).join('')}
    </div>
    ${_tlfDrillPicked!==null ? `<div style="text-align:center;margin-top:16px"><button class="btn btn-primary" onclick="tlfNext()">Next →</button></div>` : ''}
  </div>`;
}
function tlfPickOpt(i){
  if(_tlfDrillPicked!==null) return;
  _tlfDrillPicked = i;
  const q = TLF_DRILLS[_tlfDrillIdx];
  const correct = i===q.ans;
  if(correct){ _tlfDrillScore++; addXp && addXp(10); } else { addXp && addXp(2); }
  incDailyCount && incDailyCount();
  recordActivity && recordActivity('tlf_drill');
  playSfx && playSfx(correct);
  renderTlf();
}
function tlfNext(){
  _tlfDrillIdx++;
  _tlfDrillPicked = null;
  renderTlf();
}
function _tlfRenderTips(el){
  const st = document.getElementById('tlf-stats');
  if(st) st.textContent = (_tlfTipIdx+1)+'/'+TLF_TIPS.length;
  const t = TLF_TIPS[_tlfTipIdx];
  el.innerHTML = `<div style="padding:10px">
    <div style="font-weight:700;font-size:1.05rem;margin-bottom:10px">${t.title}</div>
    <div style="color:var(--muted);line-height:1.6">${t.body}</div>
    <div style="display:flex;gap:10px;margin-top:20px;justify-content:center">
      <button class="btn btn-outline" onclick="_tlfTipIdx=(_tlfTipIdx-1+TLF_TIPS.length)%TLF_TIPS.length;renderTlf()">← Prev</button>
      <button class="btn btn-outline" onclick="_tlfTipIdx=(_tlfTipIdx+1)%TLF_TIPS.length;renderTlf()">Next →</button>
    </div>
  </div>`;
}

// R1285 — AUDIO: Index TLF_WORDS into speak() chain
(function(){
  if(window.__r1285AudioGuard) return;
  window.__r1285AudioGuard = true;
  if(typeof speak !== 'function') return;
  var _prev = speak;
  speak = function(text, slow, externalBtn){
    if(text && typeof TLF_WORDS !== 'undefined' && Array.isArray(TLF_WORDS)){
      for(var i=0;i<TLF_WORDS.length;i++){
        var w = TLF_WORDS[i];
        if(text===w.ar || text===w.tr || text===w.en){
          return _prev(w.ar, slow, externalBtn);
        }
      }
    }
    return _prev(text, slow, externalBtn);
  };
  if(window.__audioFlagsKnown){ var fk=window.__audioFlagsKnown; for(var k in fk){ try{speak[k]=true;}catch(e){} } }
  speak.__r1285Audio = true;
  if(!window.__audioFlagsKnown) window.__audioFlagsKnown = {};
  window.__audioFlagsKnown['__r1285Audio'] = true;
})();

