      return `<button onclick="hflPickOpt(${i})" style="display:block;width:100%;text-align:left;padding:10px 14px;margin-bottom:8px;border-radius:8px;border:1px solid var(--border);background:${bg};color:var(--text);cursor:pointer">${o}</button>`;
