let _dwnPickedIdx = -1;
let _dwnDrillScore = {correct:0, total:0};
let _dwnTipIdx = 0;
function openDwn(){
  bumpAchievementCounter && bumpAchievementCounter('dwn_open');
  _dwnDrillIdx = 0; _dwnDrillScore = {correct:0,total:0}; _dwnDrillPicked = false; _dwnPickedIdx = -1;
  const ov = document.getElementById('dwn-overlay'); if(!ov) return;
  ov.style.display = 'block';
  setDwnTab('words');
}
function closeDwn(){ const ov=document.getElementById('dwn-overlay'); if(ov) ov.style.display='none'; }
function setDwnTab(t){
  _dwnTab = t;
  const bar = document.getElementById('dwn-tab-bar');
  if(bar){
    const tabs = [['words','📖 Words'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l])=>`<button class="cat-filter ${_dwnTab===k?'active':''}" onclick="setDwnTab('${k}')">${l}</button>`).join('');
  }
  renderDwn();
}
function renderDwn(){
  const el = document.getElementById('dwn-content');
  const stats = document.getElementById('dwn-stats');
  if(!el) return;
  const words = typeof DWN_WORDS !== 'undefined' ? DWN_WORDS : [];
  const drills = typeof DWN_DRILLS !== 'undefined' ? DWN_DRILLS : [];
  const tips = typeof DWN_TIPS !== 'undefined' ? DWN_TIPS : [];
  if(_dwnTab==='words'){
    if(_dwnWordIdx>=words.length)_dwnWordIdx=0;
    const w=words[_dwnWordIdx];
    if(stats) stats.textContent=(_dwnWordIdx+1)+'/'+words.length;
    if(!w){el.innerHTML='<p>No words loaded.</p>';return;}
    el.innerHTML=`<div style="text-align:center;padding:20px 0">
      <div style="font-size:2.4rem;font-weight:700;margin-bottom:8px">${w.ar}</div>
      <div style="font-size:1.1rem;color:var(--muted);margin-bottom:4px">${w.tr}</div>
      <div style="font-size:1rem;margin-bottom:16px">${w.en}</div>
      ${w.note?`<div style="font-size:0.85rem;color:var(--muted);background:var(--surface);padding:12px;border-radius:8px;text-align:left;line-height:1.5">${w.note}</div>`:''}
      <div style="margin-top:18px;display:flex;gap:10px;justify-content:center">
        <button class="btn btn-outline" onclick="_dwnWordIdx=Math.max(0,_dwnWordIdx-1);renderDwn()">← Prev</button>
        <button class="btn" onclick="speak&&speak(words&&words[_dwnWordIdx]&&words[_dwnWordIdx].ar)">🔊 Listen</button>
        <button class="btn" onclick="_dwnWordIdx=(_dwnWordIdx+1)%${words.length};renderDwn()">Next →</button>
      </div>
    </div>`;
  } else if(_dwnTab==='drill'){
    if(stats) stats.textContent='Score: '+_dwnDrillScore.correct+'/'+_dwnDrillScore.total;
    if(_dwnDrillIdx>=drills.length){
      el.innerHTML=`<div style="text-align:center;padding:30px"><div style="font-size:1.4rem;margin-bottom:12px">🏛️ Complete!</div><div>Score: ${_dwnDrillScore.correct}/${_dwnDrillScore.total}</div><button class="btn" style="margin-top:16px" onclick="_dwnDrillIdx=0;_dwnDrillScore={correct:0,total:0};_dwnDrillPicked=false;_dwnPickedIdx=-1;renderDwn()">Restart</button></div>`;
      return;
    }
    const q=drills[_dwnDrillIdx];
    el.innerHTML=`<div style="padding:10px 0">
      <div style="font-weight:600;margin-bottom:16px;font-size:1rem">${q.q}</div>
      ${q.opts.map((o,i)=>{
        let cls='btn btn-outline';
        if(_dwnDrillPicked){cls+=(i===q.a?' btn-correct':i===_dwnPickedIdx?' btn-wrong':'');}
        return `<button class="${cls}" style="display:block;width:100%;margin-bottom:8px;text-align:left" onclick="dwnPickOpt(${i})">${o}</button>`;
      }).join('')}
      ${_dwnDrillPicked?`<button class="btn" style="margin-top:10px" onclick="dwnNext()">Next →</button>`:''}
    </div>`;
  } else if(_dwnTab==='tips'){
    if(stats) stats.textContent=(_dwnTipIdx+1)+'/'+tips.length;
    const tip=tips[_dwnTipIdx]||{};
    el.innerHTML=`<div style="padding:10px 0">
      <div style="font-weight:700;font-size:1.1rem;margin-bottom:10px">${tip.title||''}</div>
      <div style="line-height:1.6;font-size:0.92rem">${tip.body||''}</div>
      <div style="display:flex;gap:10px;justify-content:center;margin-top:20px">
        <button class="btn btn-outline" onclick="_dwnTipIdx=Math.max(0,_dwnTipIdx-1);renderDwn()">← Prev</button>
        <button class="btn" onclick="_dwnTipIdx=(_dwnTipIdx+1)%${tips.length};renderDwn()">Next →</button>
      </div>
    </div>`;
  }
}
function dwnPickOpt(i){
  if(_dwnDrillPicked) return;
  const drills = typeof DWN_DRILLS !== 'undefined' ? DWN_DRILLS : [];
  const q=drills[_dwnDrillIdx];
  if(!q) return;
  _dwnDrillPicked=true; _dwnPickedIdx=i;
  const correct=(i===q.a);
  _dwnDrillScore.total++;
  if(correct) _dwnDrillScore.correct++;
  playSfx && playSfx(correct);
  recordActivity && recordActivity('dwn');
  incDailyCount && incDailyCount();
  addXp && addXp(correct?10:2);
  renderDwn();
}
function dwnNext(){
  _dwnDrillIdx++;
  _dwnDrillPicked=false; _dwnPickedIdx=-1;
  renderDwn();
}

