// R1505 — BUG FIX: Extend R1499 openX patcher for 18 coaches added after patcher ran.
// R1499 hardcoded a _pairs dict ending at openFll; coaches added in runs ~1230-1428
// (dwn/hly/ayn/hms/blkn/fls/hwk/blc/wlf/brd/kbs/zyr/grf/qyl/trl/mwd/hrt/mhj) were
// never patched — opening these coaches left _r1499ActiveWords null, causing browse-tab
// clicks to play audio from the previously-open coach instead of the current one.
(function(){
  if(window.__r1505BugFix) return;
  window.__r1505BugFix = true;
  var _pairs = {
    'openDwn':'DWN_WORDS','openHly':'HLY_WORDS','openAyn':'AYN_WORDS',
    'openHms':'HMS_WORDS','openBlkn':'BLKN_WORDS','openFls':'FLS_WORDS',
    'openHwk':'HWK_WORDS','openBlc':'BLC_WORDS','openWlf':'WLF_WORDS',
    'openBrd':'BRD_WORDS','openKbs':'KBS_WORDS','openZyr':'ZYR_WORDS',
    'openGrf':'GRF_WORDS','openQyl':'QYL_WORDS','openTrl':'TRL_WORDS',
    'openMwd':'MWD_WORDS','openHrt':'HRT_WORDS','openMhj':'MHJ_WORDS'
  };
  Object.keys(_pairs).forEach(function(fn){
    if(typeof window[fn]!=='function' || window[fn].__r1499Patched) return;
    var _o = window[fn], wn = _pairs[fn];
    window[fn] = function(){
      window._r1499ActiveWords = typeof window[wn]!=='undefined' ? window[wn] : null;
      return _o.apply(this,arguments);
    };
    window[fn].__r1499Patched = true;
  });
})();
// ── end R1505 ─────────────────────────────────────────────────────────────────

// ── R1506 — NEW FEATURE: Lebanese Hospitality & Diyafa (dfy) ─────────────────
let _dfyTab = 'browse';
let _dfyDrillIdx = 0;
let _dfyDrillPicked = false;
let _dfyScore = 0;
let _dfyTotal = 0;
let _dfyTipIdx = 0;
let _dfyCat = 'all';

function openDfy(){
  bumpAchievementCounter && bumpAchievementCounter('dfy_open');
  const ov = document.getElementById('dfy-overlay'); if(!ov) return;
  window._r1499ActiveWords = typeof DFY_WORDS !== 'undefined' ? DFY_WORDS : null;
  ov.style.display = 'block';
  _dfyScore = 0; _dfyTotal = 0; _dfyDrillIdx = 0; _dfyDrillPicked = false; _dfyTipIdx = 0; _dfyCat = 'all';
  setDfyTab('browse');
}
function closeDfy(){
  const ov = document.getElementById('dfy-overlay'); if(ov) ov.style.display='none';
  window._r1499ActiveWords = null;
}
function setDfyTab(t){
  _dfyTab = t;
  const bar = document.getElementById('dfy-tab-bar');
  if(bar){
    const tabs = [['browse','📖 Browse'],['drill','🎯 Drill'],['tips','💡 Tips']];
    bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter ${_dfyTab===k?'active':''}" onclick="setDfyTab('${k}')">${l}</button>`).join('');
  }
  renderDfy();
}
function renderDfy(){
  const el = document.getElementById('dfy-content'); if(!el) return;
  const words = typeof DFY_WORDS !== 'undefined' ? DFY_WORDS : [];
  const drills = typeof DFY_DRILLS !== 'undefined' ? DFY_DRILLS : [];
  const tips = typeof DFY_TIPS !== 'undefined' ? DFY_TIPS : [];
  const st = document.getElementById('dfy-stats');
  if(_dfyTab === 'browse'){
    const cats = ['all','welcome','comfort','hosting','gratitude','leaving'];
    const catBar = cats.map(c => `<button class="cat-filter ${_dfyCat===c?'active':''}" onclick="_dfyCat='${c}';renderDfy()">${c==='all'?'🌟 All':c.charAt(0).toUpperCase()+c.slice(1)}</button>`).join('');
    const filtered = _dfyCat==='all' ? words : words.filter(w=>w.cat===_dfyCat);
    if(st) st.textContent = filtered.length + ' phrases';
    el.innerHTML = `<div style="display:flex;gap:4px;flex-wrap:wrap;justify-content:center;margin-bottom:14px">${catBar}</div>`
      + filtered.map(w => `<div class="word-card" onclick="speak('${w.w.replace(/'/g,"\\'")}')">
        <div style="font-size:1.4rem;font-weight:700">${w.w}</div>
        <div style="font-size:1.5rem;color:var(--accent);margin:4px 0">${w.t}</div>
        <div style="font-size:0.85rem;color:var(--muted)">${w.tr}</div>
        <div style="font-size:0.7rem;color:var(--muted);margin-top:3px;text-transform:uppercase">${w.cat}</div>
      </div>`).join('');
  } else if(_dfyTab === 'drill'){
    if(!drills.length){ el.innerHTML='<p style="color:var(--muted)">No drills.</p>'; return; }
    if(st) st.textContent = `${_dfyScore}/${_dfyTotal} correct`;
    if(_dfyDrillIdx >= drills.length){
      el.innerHTML = `<div style="text-align:center;padding:40px">
        <div style="font-size:2rem;margin-bottom:12px">🎉</div>
        <div style="font-size:1.2rem;font-weight:700;margin-bottom:8px">Done! ${_dfyScore}/${drills.length} correct</div>
        <button class="btn btn-primary" onclick="_dfyDrillIdx=0;_dfyScore=0;_dfyTotal=0;_dfyDrillPicked=false;renderDfy()">🔄 Restart</button>
      </div>`; return;
    }
    const d = drills[_dfyDrillIdx];
    el.innerHTML = `<div style="max-width:600px;margin:0 auto">
      <div style="text-align:center;color:var(--muted);font-size:0.85rem;margin-bottom:16px">Question ${_dfyDrillIdx+1} of ${drills.length}</div>
      <div style="background:var(--card);border-radius:12px;padding:20px;margin-bottom:16px;text-align:center;font-size:1.05rem">${d.q}</div>
      <div id="dfy-drill-ans" style="text-align:center"></div>
    </div>`;
    if(!_dfyDrillPicked){
      const choices = [d.a, ...drills.filter((_,i)=>i!==_dfyDrillIdx).map(x=>x.a).sort(()=>Math.random()-0.5).slice(0,3)].sort(()=>Math.random()-0.5);
      const ansEl = document.getElementById('dfy-drill-ans');
      if(ansEl) ansEl.innerHTML = choices.map(c=>`<button class="btn btn-outline" style="margin:6px;min-width:180px" onclick="dfyPickOpt('${c.replace(/'/g,"\\'")}')">${c}</button>`).join('');
    }
  } else {
    if(!tips.length){ el.innerHTML='<p style="color:var(--muted)">No tips.</p>'; return; }
    if(st) st.textContent = `Tip ${_dfyTipIdx+1}/${tips.length}`;
    const tip = tips[_dfyTipIdx];
    el.innerHTML = `<div style="max-width:600px;margin:0 auto">
      <div style="background:var(--card);border-radius:12px;padding:24px;margin-bottom:16px">
        <div style="font-weight:700;font-size:1.1rem;margin-bottom:10px">💡 ${tip.title}</div>
        <div style="color:var(--muted);line-height:1.6">${tip.body}</div>
      </div>
      <div style="display:flex;justify-content:center;gap:10px">
        <button class="btn btn-outline" onclick="if(_dfyTipIdx>0){_dfyTipIdx--;renderDfy()}" ${_dfyTipIdx===0?'disabled':''}>← Prev</button>
        <button class="btn btn-outline" onclick="if(_dfyTipIdx<${tips.length-1}){_dfyTipIdx++;renderDfy()}" ${_dfyTipIdx===tips.length-1?'disabled':''}>Next →</button>
      </div>
    </div>`;
  }
}
function dfyPickOpt(ans){
  if(_dfyDrillPicked) return;
  _dfyDrillPicked = true;
  const drills = typeof DFY_DRILLS !== 'undefined' ? DFY_DRILLS : [];
  const d = drills[_dfyDrillIdx];
  const correct = ans === d.a;
  _dfyTotal++;
  if(correct){ _dfyScore++; addXp && addXp(2); incDailyCount && incDailyCount(); recordActivity && recordActivity(); }
  else { addXp && addXp(1); }
  const sfx = correct ? 'correct' : 'wrong';
  if(window.playSfx) playSfx(sfx); else if(window.sfx) sfx && sfx[correct?'correct':'wrong'] && sfx[correct?'correct':'wrong'].play();
  const ansEl = document.getElementById('dfy-drill-ans');
  if(ansEl) ansEl.innerHTML = `<div style="font-size:1.4rem;margin-bottom:12px">${correct?'✅':'❌'}</div>
    <div style="margin-bottom:8px"><strong>${d.a}</strong></div>
    <div style="color:var(--muted);font-size:0.9rem;margin-bottom:16px">${d.hint}</div>
    <button class="btn btn-primary" onclick="dfyNext()">Next →</button>`;
}
function dfyNext(){
  _dfyDrillIdx++;
  _dfyDrillPicked = false;
  renderDfy();
}
// ── end R1506 ─────────────────────────────────────────────────────────────────

