// R1550 — BUG FIX: playMinPairListen fires word B prematurely
// Root cause: R1046 registers audio 'error' listener BEFORE calling speak().
// speak() calls stopAllAudio() which sets audio.src='' — that fires 'error'
// immediately, triggering playB() after only 200ms before word A finishes.
// Fix: drop 'error' listener (only keep 'ended'), reduce fallback 5000→2500ms.
(function(){
  if(window.__r1550Guard) return; window.__r1550Guard = true;

  window.playMinPairListen = function(aAr, bAr){
    var audio = document.getElementById('tts-audio');
    var done = false;
    function playB(){
      if(done) return;
      done = true;
      speak(bAr, true);
    }
    if(audio && typeof audio.addEventListener === 'function'){
      var onEnd = function(){
        audio.removeEventListener('ended', onEnd);
        setTimeout(playB, 250);
      };
      audio.addEventListener('ended', onEnd);
      // No 'error' listener — stopAllAudio sets src='' which fires error prematurely
      setTimeout(playB, 2500); // fallback for browser TTS path (no audio.ended)
    } else {
      setTimeout(playB, 1400);
    }
    speak(aAr, true);
  };

  window.__r1550Done = true;
})();

