      if(typeof _audioKeyVariants !== 'function') return _origYt(text);
      var variants = _audioKeyVariants(text);
      for(var i = 0; i < variants.length; i++){
        var v = variants[i];
        if(_isStripCollision(text, v)) continue;
        if(YOUTUBE_AUDIO[v]) return { key: v, url: YOUTUBE_AUDIO[v] };
      }
