// R1573 — AUDIO: Romanized example-sentence → Arabic token mapping
// Bug per bugs.rtf: "sentence audio is often not Lebanese arabic"
// When speak() receives a multi-word romanized Lebanese sentence (no Arabic chars),
// scan global *_WORDS arrays + VOCAB, build romanized→Arabic token map, replace tokens
// (with prefix-stripping for Lebanese clitics bi-/el-/la-/w-/3a-/min-), and if ≥40% of
// tokens map, speak the Arabic version instead. TTS pronouncing Arabic > TTS pronouncing
// romanized chars as English. Per-coach single-word audio IIFEs unaffected (sentence-only).
(function(){
  if(window.__r1573AudioGuard) return; window.__r1573AudioGuard = true;
  if(typeof speak !== 'function') return;

  var _r1573Map = {};
  function _addPair(romanized, arabic){
    if(!romanized || !arabic) return;
    var k = String(romanized).toLowerCase().trim();
    if(!k || _r1573Map[k]) return;
    _r1573Map[k] = arabic;
  }
  function _idxArr(arr){
    if(!arr || !Array.isArray(arr)) return;
    arr.forEach(function(w){
      if(!w || typeof w !== 'object') return;
      if(w.w && w.t)  _addPair(w.w,  w.t);
      if(w.tr && w.t) _addPair(w.tr, w.t);
      if(w.lat && w.ar) _addPair(w.lat, w.ar);
      if(w.tr && w.ar)  _addPair(w.tr,  w.ar);
    });
  }
  try {
    if(typeof window !== 'undefined'){
      Object.keys(window).forEach(function(k){
        if(/_WORDS$/.test(k)){
          try{ _idxArr(window[k]); }catch(e){}
        }
      });
    }
  } catch(e){}
  if(typeof VOCAB !== 'undefined' && Array.isArray(VOCAB)){
    VOCAB.forEach(function(v){
      if(!v || typeof v !== 'object') return;
      if(v.lat && v.ar) _addPair(v.lat, v.ar);
      if(v.tr && v.ar)  _addPair(v.tr,  v.ar);
    });
  }
  window.__r1573Map = _r1573Map;

  var _hasArabic = function(s){ return /[\u0600-\u06FF]/.test(s); };
  var _isRomanizedSentence = function(s){
    if(!s || typeof s !== 'string') return false;
    if(_hasArabic(s)) return false;
    if(s.indexOf(' ') < 0) return false;
    return /[a-zA-Z]/.test(s);
  };

  var _prev = speak;
  speak = function(text, slow, externalBtn){
    try {
      if(_isRomanizedSentence(text)){
        var tokens = String(text).split(/\s+/);
        var mapped = [];
        var hits = 0;
        tokens.forEach(function(tok){
          var clean = tok.replace(/[.,!?;:"'()]/g,'').toLowerCase();
          var hit = _r1573Map[clean];
          if(!hit){
            var noPrefix = clean.replace(/^(bi|el|la|w|wa|3a|3al|3ala|fi|min|mn|mish|ma)-/,'');
            if(noPrefix !== clean) hit = _r1573Map[noPrefix];
          }
          if(!hit && clean.indexOf('-') > -1){
            var parts = clean.split('-');
            hit = _r1573Map[parts[parts.length-1]];
          }
          if(hit){ mapped.push(hit); hits++; }
          else { mapped.push(tok); }
        });
        if(tokens.length > 0 && (hits / tokens.length) >= 0.4){
          var arSentence = mapped.join(' ');
          return _prev(arSentence, slow, externalBtn);
        }
      }
    } catch(e){}
    return _prev(text, slow, externalBtn);
  };
  if(window.__audioFlagsKnown){ var fk=window.__audioFlagsKnown; for(var k in fk){ try{speak[k]=true;}catch(e){} } }
  speak.__r1573Audio = true;
  if(!window.__audioFlagsKnown) window.__audioFlagsKnown = {};
  window.__audioFlagsKnown.__r1573Audio = true;
  window.__r1573AudioDone = true;
})();

// R1574 — BUG FIX: Arabic-voice TTS mangles romanized example sentences
// Bug per bugs.rtf: "sentence audio is often not Lebanese arabic"
// Root cause: many coach example sentences are romanized Lebanese ("Saboun Trables a3la wa7ad bi-Lebnen").
// _speakViaBrowser unconditionally picks Arabic voice → tries to read English chars → garbled Arabic phonemes.
// R1573 maps romanized tokens → Arabic when ≥40% of tokens are in *_WORDS index. For sentences below
// that threshold (proper nouns, function words, dense romanization), R1573 falls through and the
// downstream Arabic-voice TTS produces the garbled output users complained about.
// R1574 wraps _speakViaBrowser: if text is pure-romanized (no Arabic chars + ASCII letters) AND multi-word,
// route to English-voice utterance (lang='en-US') so phonemes approximate the transliteration scheme
// instead of garbling. Single-word romanized passes through (per-coach IIFEs already swap to Arabic).
(function(){
  if(window.__r1574Guard) return; window.__r1574Guard = true;
  if(typeof _speakViaBrowser !== 'function') return;
  var _origSVB = _speakViaBrowser;
  _speakViaBrowser = function(text, slow, clearAnim){
    try {
      if(text && typeof text === 'string'){
        var hasArabic = /[\u0600-\u06FF]/.test(text);
        var hasRomanized = /[a-zA-Z]/.test(text);
        if(!hasArabic && hasRomanized && text.indexOf(' ') > -1){
          if(typeof speechSynthesis !== 'undefined' && speechSynthesis){
            try {
              speechSynthesis.cancel();
              var u = new SpeechSynthesisUtterance(text);
              u.lang = 'en-US';
              u.rate = (slow ? 0.7 : 1.0) * (typeof getPreferredPlaybackRate === 'function' ? getPreferredPlaybackRate() : 1.0);
              u.onend = clearAnim;
              u.onerror = clearAnim;
              var badge = document.getElementById('audio-source');
              if(badge) badge.textContent = '🔤 Romanized sentence — English-voice approximation';
              speechSynthesis.speak(u);
              return true;
            } catch(e){
              clearAnim && clearAnim();
              return false;
            }
          }
          clearAnim && clearAnim();
          return false;
        }
      }
    } catch(e){}
    return _origSVB(text, slow, clearAnim);
  };
  try {
    for(var _k in _origSVB){
      try { if(Object.prototype.hasOwnProperty.call(_origSVB, _k) && _k !== '__r1574Wrapped') _speakViaBrowser[_k] = _origSVB[_k]; } catch(e){}
    }
  } catch(e){}
  _speakViaBrowser.__r1574Wrapped = true;
  if(typeof window !== 'undefined') window._speakViaBrowser = _speakViaBrowser;
  window.__r1574Done = true;
})();

