// R1579 — AUDIO: Whole-string romanized → Arabic for multi-word *_WORDS entries
// Bug: R1573 sentence-swap tokenizes by space, so multi-word entries like "wadi qadisha",
// "hajar el-7ubla", "balad el-shams", "arz el-rabb" never hit because individual tokens
// "wadi"/"hajar"/"balad"/"arz" aren't in map. Pre-check whole-text key before tokenizing.
(function(){
  if(window.__r1579AudioGuard) return; window.__r1579AudioGuard = true;
  if(typeof speak !== 'function') return;
  if(!window.__r1573Map) return;
  var _hasArabic = function(s){ return /[\u0600-\u06FF]/.test(s); };
  var _prev = speak;
  speak = function(text, slow, externalBtn){
    try {
      if(text && typeof text === 'string' && !_hasArabic(text)){
        var clean = text.replace(/[.,!?;:"'()]/g,'').toLowerCase().trim();
        if(clean.indexOf(' ') > -1 && clean.length >= 4 && clean.length <= 80){
          var hit = window.__r1573Map[clean];
          if(hit){
            return _prev(hit, slow, externalBtn);
          }
        }
      }
    } catch(e){}
    return _prev(text, slow, externalBtn);
  };
  if(window.__audioFlagsKnown){ var fk=window.__audioFlagsKnown; for(var k in fk){ try{speak[k]=true;}catch(e){} } }
  speak.__r1579Audio = true;
  if(!window.__audioFlagsKnown) window.__audioFlagsKnown = {};
  window.__audioFlagsKnown.__r1579Audio = true;
  window.__r1579AudioDone = true;
})();

// R1580 — BUG FIX: Minimal pairs listening drill — robust A-finished detection
// per bugs.rtf "Minimal pairs listening drill sound not working properly".
// R1550 listens for audio.ended, but 'ended' can fire spuriously when speak()
// internally calls stopAllAudio()→audio.src='' (the previous audio's playback
// state can transition through events). Also: speechSynthesis path never fires
// audio.ended → 2500ms fallback often interrupts mid-word.
// Fix: poll audio.paused/currentTime + speechSynthesis.speaking; require
// SEEN-activity then 350ms idle before firing word B. Catches both audio path
// and TTS path. 8s safety fallback.
(function(){
  if(window.__r1580Guard) return; window.__r1580Guard = true;
  if(typeof window.playMinPairListen !== 'function') return;
  window.playMinPairListen = function(aAr, bAr){
    var done = false;
    var startedAt = Date.now();
    function playB(){
      if(done) return; done = true;
      try { speak(bAr, true); } catch(e){}
    }
    try { speak(aAr, true); } catch(e){}
    var audio = (typeof document !== 'undefined' && document.getElementById) ? document.getElementById('tts-audio') : null;
    var seenActive = false;
    var lastActiveAt = 0;
    var idleNeeded = 350;
    var maxWait = 8000;
    var poll = setInterval(function(){
      try {
        if(done){ clearInterval(poll); return; }
        var now = Date.now();
        var audioActive = !!(audio && !audio.paused && audio.currentTime > 0 && !audio.ended);
        var ss = (typeof speechSynthesis !== 'undefined') ? speechSynthesis : null;
        var ttsActive = !!(ss && (ss.speaking || ss.pending));
        if(audioActive || ttsActive){
          seenActive = true;
          lastActiveAt = now;
        } else if(seenActive && (now - lastActiveAt) >= idleNeeded){
          clearInterval(poll);
          playB();
          return;
        }
        if((now - startedAt) >= maxWait){
          clearInterval(poll);
          playB();
        }
      } catch(e){
        clearInterval(poll);
        playB();
      }
    }, 100);
  };
  window.__r1580Done = true;
})();
// ── end R1580 ────────────────────────────────────────────────────────────────

// ── R1581 NEW FEATURE: Jeita Grotto & Lebanese Cave Heritage (jta) ──────────
(function(){
  if(window.__r1581Guard) return; window.__r1581Guard = true;
  let _jtaTab = 'words';
  let _jtaDrillIdx = 0;
  let _jtaDrillPicked = false;
  let _jtaLastOpts = null;
  let _jtaScore = 0;
  let _jtaTotal = 0;

  window.openJta = function(){
    try{ bumpAchievementCounter && bumpAchievementCounter('jta_open'); }catch(e){}
    const ov = document.getElementById('jta-overlay'); if(!ov) return;
    ov.style.display = 'block';
    _jtaDrillIdx = 0; _jtaScore = 0; _jtaTotal = 0; _jtaDrillPicked = false; _jtaLastOpts = null;
    setJtaTab('words');
  };
  window.closeJta = function(){ const ov=document.getElementById('jta-overlay'); if(ov) ov.style.display='none'; };
  window.setJtaTab = function(t){
    _jtaTab = t;
    _jtaDrillIdx = 0; _jtaDrillPicked = false; _jtaLastOpts = null;
    const bar = document.getElementById('jta-tab-bar');
    if(bar){
      const tabs = [['words','📖 Words'],['drill','🎯 Drill'],['tips','💡 Culture']];
      bar.innerHTML = tabs.map(([k,l]) => `<button class="cat-filter${_jtaTab===k?' active':''}" onclick="setJtaTab('${k}')">${l}</button>`).join('');
    }
    renderJta();
  };
  function _jtaBuildOpts(correctIdx){
    if(typeof JTA_WORDS === 'undefined' || !JTA_WORDS.length) return [];
    const correct = JTA_WORDS[correctIdx];
    const pool = JTA_WORDS.filter((_,i)=>i!==correctIdx);
    const distractors = [];
    while(distractors.length < 3 && pool.length){
      const idx = Math.floor(Math.random()*pool.length);
      distractors.push(pool.splice(idx,1)[0]);
    }
    const opts = [correct, ...distractors];
    for(let i=opts.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [opts[i],opts[j]]=[opts[j],opts[i]]; }
    return opts;
  }
  window.renderJta = function(){
    const el = document.getElementById('jta-content');
    const st = document.getElementById('jta-stats');
    if(!el) return;
    if(_jtaTab === 'words'){
      if(st) st.textContent = (typeof JTA_WORDS !== 'undefined' ? JTA_WORDS.length : 0) + ' words';
      const words = (typeof JTA_WORDS !== 'undefined') ? JTA_WORDS : [];
      el.innerHTML = words.map(w => `
        <div style="background:var(--card);border-radius:12px;padding:14px;margin-bottom:10px">
          <div style="display:flex;justify-content:space-between;align-items:center;gap:8px">
            <div>
              <div style="font-size:1.4rem;font-weight:700">${w.t}</div>
              <div style="color:var(--muted);font-size:0.95rem">${w.w} — ${w.en}</div>
            </div>
            <button class="btn btn-outline" onclick="speak('${w.t.replace(/'/g,"\\'")}')">🔊</button>
          </div>
          <div style="margin-top:8px;font-style:italic;color:var(--muted);font-size:0.9rem">${w.ex} — ${w.exEn}</div>
          <div style="margin-top:6px;font-size:0.85rem;color:var(--muted)">${w.notes}</div>
        </div>
      `).join('');
    } else if(_jtaTab === 'drill'){
      const drills = (typeof JTA_DRILLS !== 'undefined') ? JTA_DRILLS : [];
      if(!drills.length){ el.innerHTML = '<div>No drills yet.</div>'; return; }
      if(_jtaDrillIdx >= drills.length){
        if(st) st.textContent = `${_jtaScore}/${_jtaTotal}`;
        el.innerHTML = `<div style="text-align:center;padding:30px">
          <div style="font-size:1.4rem;font-weight:700">Done! ${_jtaScore}/${_jtaTotal}</div>
          <button class="btn btn-primary" style="margin-top:16px" onclick="setJtaTab('drill')">↻ Restart</button>
        </div>`;
        return;
      }
      const d = drills[_jtaDrillIdx];
      const correctIdx = (typeof JTA_WORDS !== 'undefined') ? JTA_WORDS.findIndex(x => x.w === d.a) : -1;
      if(!_jtaLastOpts && correctIdx >= 0){ _jtaLastOpts = _jtaBuildOpts(correctIdx); }
      const opts = _jtaLastOpts || [];
      if(st) st.textContent = `${_jtaDrillIdx+1}/${drills.length} · ${_jtaScore}/${_jtaTotal}`;
      el.innerHTML = `
        <div style="background:var(--card);border-radius:12px;padding:18px">
          <div style="font-size:1.1rem;font-weight:700;margin-bottom:14px">${d.q}</div>
          <div style="display:grid;gap:8px">
            ${opts.map((o,i) => `
              <button class="btn btn-outline" style="text-align:left" onclick="jtaPickOpt(${i})" data-w="${o.w}">
                <span style="font-size:1.1rem">${o.t}</span>
                <span style="color:var(--muted);font-size:0.85rem"> — ${o.w}</span>
              </button>
            `).join('')}
          </div>
          ${_jtaDrillPicked ? `<div style="margin-top:14px;padding:10px;background:var(--bg);border-radius:8px"><div style="font-size:0.9rem;color:var(--muted)">${d.hint}</div></div>` : ''}
          ${_jtaDrillPicked ? `<button class="btn btn-primary" style="margin-top:12px" onclick="jtaNext()">Next →</button>` : ''}
        </div>`;
    } else if(_jtaTab === 'tips'){
      const tips = (typeof JTA_TIPS !== 'undefined') ? JTA_TIPS : [];
      if(st) st.textContent = tips.length + ' tips';
      el.innerHTML = tips.map(t => `<div style="background:var(--card);border-radius:12px;padding:14px;margin-bottom:10px">${t}</div>`).join('');
    }
  };
  window.jtaPickOpt = function(i){
    if(_jtaDrillPicked) return;
    _jtaDrillPicked = true;
    const drills = (typeof JTA_DRILLS !== 'undefined') ? JTA_DRILLS : [];
    const d = drills[_jtaDrillIdx]; if(!d) return;
    const opts = _jtaLastOpts || [];
    const picked = opts[i];
    _jtaTotal++;
    const correct = picked && picked.w === d.a;
    if(correct){ _jtaScore++; try{ playSfx && playSfx('correct'); }catch(e){} try{ addXp && addXp(10); }catch(e){} }
    else { try{ playSfx && playSfx('wrong'); }catch(e){} try{ addXp && addXp(2); }catch(e){} }
    try{ recordActivity && recordActivity('jta_drill'); }catch(e){}
    try{ incDailyCount && incDailyCount(); }catch(e){}
    renderJta();
  };
  window.jtaNext = function(){ _jtaDrillIdx++; _jtaDrillPicked = false; _jtaLastOpts = null; renderJta(); };
  window.__r1581Done = true;
})();

