  if(typeof WYN_WORDS!=='undefined'&&Array.isArray(WYN_WORDS))arrs.push(WYN_WORDS);
  if(typeof XMS_WORDS!=='undefined'&&Array.isArray(XMS_WORDS))arrs.push(XMS_WORDS);
  if(typeof YNB_WORDS!=='undefined'&&Array.isArray(YNB_WORDS))arrs.push(YNB_WORDS);
  if(typeof ZFF_WORDS!=='undefined'&&Array.isArray(ZFF_WORDS))arrs.push(ZFF_WORDS);
  if(typeof ZGL_WORDS!=='undefined'&&Array.isArray(ZGL_WORDS))arrs.push(ZGL_WORDS);
  if(typeof ZHR_WORDS!=='undefined'&&Array.isArray(ZHR_WORDS))arrs.push(ZHR_WORDS);
  if(typeof ZJL_WORDS!=='undefined'&&Array.isArray(ZJL_WORDS))arrs.push(ZJL_WORDS);
