  try {
    var s = String(window._speakSmartCrowdFetch);
    window.__r1589Wik = s.indexOf('fetchWiktionaryAudio') >= 0;
    window.__r1589Com = s.indexOf('fetchCommonsAudio') >= 0;
    window.__r1589NoneMain = s.indexOf("cache[key] = '__none__'") >= 0;
    window.__r1589NoneCom = s.indexOf("cache['__commons__:' + key] = '__none__'") >= 0;
    window.__r1589SaveN = (s.match(/saveAudioCache\(cache\)/g) || []).length;
  } catch(e){}
  window.__r1589Done = true;
