// ===== R1609 — extend __r1573Map with CHF_WORDS + ex sentence synth =====
(function(){
  if(window.__r1609Guard) return; window.__r1609Guard = true;
  if(typeof CHF_WORDS === 'undefined') return;
  if(!window.__r1573Map) window.__r1573Map = {};
  var map = window.__r1573Map;
  var added = 0;
  // 1) Single-word w → t
  CHF_WORDS.forEach(function(w){
    if(!w || !w.w || !w.t) return;
    var key = String(w.w).trim();
    if(key && !map[key]){ map[key] = w.t; added++; }
  });
  // 2) Token table for ex synth
  var tokenMap = {};
  Object.keys(map).forEach(function(k){
    var v = map[k];
    if(!k || !v) return;
    var clean = k.replace(/^(el-|l-|3al-|3a-|w-|b-|la-)/i,'').replace(/[\.,!\?:;\-—]/g,'').trim();
    if(clean) tokenMap[clean.toLowerCase()] = v;
    tokenMap[k.toLowerCase()] = v;
  });
  function _r1609Synth(s){
    if(!s) return null;
    var raw = String(s).replace(/[\.,!\?:;]+/g,' ').replace(/\s+/g,' ').trim();
    if(!raw) return null;
    var toks = raw.split(/\s+/);
    var out = [];
    var hits = 0;
    var i = 0;
    while(i < toks.length){
      var matched = false;
      for(var w = Math.min(4, toks.length - i); w >= 1 && !matched; w--){
        var phrase = toks.slice(i, i+w).join(' ').toLowerCase();
        var clean = phrase.replace(/^(el-|l-|3al-|3a-|w-|b-|la-)/i,'').trim();
        var ar = tokenMap[phrase] || tokenMap[clean];
        if(ar){
          out.push(ar);
          hits++;
          i += w;
          matched = true;
        }
      }
      if(!matched){ out.push(toks[i]); i++; }
    }
    if(hits < 2) return null;
    if(hits / toks.length < 0.5) return null;
    return out.join(' ');
  }
  var exAdded = 0;
  CHF_WORDS.forEach(function(w){
    if(!w || !w.ex) return;
    var ex = String(w.ex).trim();
    if(!ex || map[ex]) return;
    var ar = _r1609Synth(ex);
    if(ar){ map[ex] = ar; exAdded++; }
  });
  window.__r1609Added = added;
  window.__r1609ExAdded = exAdded;
  window.__r1609MapSize = Object.keys(map).length;
  window.__r1609Done = true;
})();

// ===== R1610 — BUG FIX: restore speak audio flags clobbered by R1595/R1598 wraps =====
// R1595 wrapped speak() and R1598 wrapped playAudio + _speakViaBrowser. None of
// the wraps copy props from the originals → all __rNNNAudio flags set on prior
// speak instances are lost. Probe BADs grew across r1501..r1590 audio markers.
// Fix: register all expected flags into __audioFlagsKnown + stamp them on the
// current speak. Mirrors R1214 / R1208 / R1055 restoration pattern.
(function(){
  if(window.__r1610Guard) return; window.__r1610Guard = true;
  if(typeof speak !== 'function') return;
  var flags = [
    '__r1499Fix','__r1501Audio','__r1504Audio','__r1507Audio','__r1510Audio',
    '__r1513Audio','__r1516Audio','__r1519Audio','__r1522Audio','__r1525Audio',
    '__r1528Audio','__r1531Audio','__r1534Audio','__r1537Audio','__r1540Audio',
    '__r1543Audio','__r1546Audio','__r1549Audio','__r1552Audio','__r1555Audio',
    '__r1558Audio','__r1561Audio','__r1564Audio','__r1567Audio','__r1572Audio',
    '__r1573Audio','__r1575Audio','__r1576Audio','__r1578Audio','__r1579Audio',
    '__r1581Audio','__r1584Audio','__r1587Audio','__r1590Audio'
  ];
  var known = window.__audioFlagsKnown;
  if(!known){ known = window.__audioFlagsKnown = {}; }
  // Some prior runs used array shape, others used object. Normalize: register both.
  var setIn = function(f){
    if(Array.isArray(known)){ if(known.indexOf(f) === -1) known.push(f); }
    else if(known && typeof known === 'object'){ known[f] = true; }
  };
  var restored = 0;
  flags.forEach(function(f){
    setIn(f);
    if(!speak[f]){ try { speak[f] = true; restored++; } catch(e){} }
  });
  window.__r1610Restored = restored;
  window.__r1610FlagsTotal = flags.length;
  window.__r1610Done = true;
})();

