(function(){
  if (window.__r1614Guard) return;
  window.__r1614Guard = true;
  if (typeof SRF_WORDS === 'undefined' || typeof SRF_DRILLS === 'undefined' || typeof SRF_TIPS === 'undefined') return;

  let _srfTab = 'words';
  let _srfDrillIdx = 0;
  let _srfPicked = false;
  let _srfCorrect = 0;
  let _srfTotal = 0;

  window.openSrf = function(){
    if (typeof bumpAchievementCounter === 'function') {
      try { bumpAchievementCounter('srf_open'); } catch(e){}
    }
    const ov = document.getElementById('srf-overlay');
    if (!ov) return;
    ov.style.display = 'block';
    _srfTab = 'words';
    _srfDrillIdx = 0;
    _srfPicked = false;
    setSrfTab('words');
  };

  window.closeSrf = function(){
    const ov = document.getElementById('srf-overlay');
    if (ov) ov.style.display = 'none';
  };

  window.setSrfTab = function(t){
    _srfTab = t;
    const bar = document.getElementById('srf-tab-bar');
    if (bar) {
      const tabs = [['words','💱 Words'],['drill','🎯 Drill'],['tips','💡 Tips']];
      bar.innerHTML = tabs.map(function(x){
        return '<button class="cat-filter ' + (_srfTab===x[0]?'active':'') + '" onclick="setSrfTab(\'' + x[0] + '\')">' + x[1] + '</button>';
      }).join('');
    }
    renderSrf();
  };

  window.renderSrf = function(){
    const c = document.getElementById('srf-content');
    if (!c) return;
    const stats = document.getElementById('srf-stats');
    if (stats) stats.textContent = SRF_WORDS.length + ' words · ' + SRF_DRILLS.length + ' drills · ' + SRF_TIPS.length + ' tips';

    if (_srfTab === 'words') {
      c.innerHTML = SRF_WORDS.map(function(w){
        return '<div class="card" style="margin-bottom:10px;padding:14px"><div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px"><div style="flex:1"><div style="font-weight:700;font-size:1.05rem">' + w.w + ' <span style="color:var(--muted);font-weight:400">— ' + w.t + '</span></div><div style="color:var(--muted);font-size:0.92rem;margin-top:4px">' + w.e + '</div><div style="margin-top:6px;font-style:italic;font-size:0.92rem">' + w.ex + '</div></div><button class="btn btn-outline" onclick="__r1614Speak(\'' + w.w.replace(/\'/g,"\\'") + '\')" style="flex-shrink:0">🔊</button></div></div>';
      }).join('');
    } else if (_srfTab === 'drill') {
      if (_srfDrillIdx >= SRF_DRILLS.length) {
        c.innerHTML = '<div class="card" style="text-align:center;padding:24px"><div style="font-size:1.4rem;margin-bottom:8px">🎉 Drill complete!</div><div style="color:var(--muted)">Score: ' + _srfCorrect + ' / ' + SRF_DRILLS.length + '</div><button class="btn btn-primary" onclick="__r1614Reset()" style="margin-top:14px">Restart drill</button></div>';
        return;
      }
      const d = SRF_DRILLS[_srfDrillIdx];
      const opts = _srfBuildOpts(d);
      c.innerHTML = '<div class="card" style="padding:18px"><div style="color:var(--muted);font-size:0.85rem;margin-bottom:6px">Question ' + (_srfDrillIdx+1) + ' / ' + SRF_DRILLS.length + '</div><div style="font-weight:700;font-size:1.1rem;margin-bottom:14px">' + d.q + '</div>' + opts.map(function(o,i){
        return '<button class="btn btn-outline" onclick="srfPickOpt(' + i + ',\'' + o.replace(/\'/g,"\\'") + '\')" style="display:block;width:100%;text-align:left;margin-bottom:6px">' + o + '</button>';
      }).join('') + '<div id="srf-feedback" style="margin-top:10px"></div></div>';
    } else if (_srfTab === 'tips') {
      c.innerHTML = SRF_TIPS.map(function(tp){
        return '<div class="card" style="margin-bottom:10px;padding:14px"><div style="font-weight:700;margin-bottom:6px">' + tp.t + '</div><div style="font-size:0.93rem;line-height:1.5">' + tp.b + '</div></div>';
      }).join('');
    }
  };

  function _srfBuildOpts(d){
    const correct = d.a;
    const others = SRF_DRILLS.filter(function(x){ return x.a !== correct; }).map(function(x){ return x.a; });
    const distract = [];
    while (distract.length < 3 && others.length) {
      const i = Math.floor(Math.random() * others.length);
      distract.push(others.splice(i, 1)[0]);
    }
    const opts = [correct].concat(distract);
    for (let i = opts.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      const tmp = opts[i]; opts[i] = opts[j]; opts[j] = tmp;
    }
    return opts;
  }

  window.srfPickOpt = function(i, choice){
    if (_srfPicked) return;
    _srfPicked = true;
    const d = SRF_DRILLS[_srfDrillIdx];
    const fb = document.getElementById('srf-feedback');
    _srfTotal++;
    const right = choice === d.a;
    if (right) {
      _srfCorrect++;
      if (typeof recordActivity === 'function') { try { recordActivity('srf_drill', 1); } catch(e){} }
      if (typeof incDailyCount === 'function') { try { incDailyCount('srf'); } catch(e){} }
      if (typeof addXp === 'function') { try { addXp(3); } catch(e){} }
      if (typeof playSfx === 'function') { try { playSfx('correct'); } catch(e){} }
    } else {
      if (typeof addXp === 'function') { try { addXp(1); } catch(e){} }
      if (typeof playSfx === 'function') { try { playSfx('wrong'); } catch(e){} }
    }
    if (fb) {
      fb.innerHTML = '<div style="padding:10px;border-radius:8px;background:' + (right?'rgba(34,197,94,0.15)':'rgba(239,68,68,0.15)') + ';margin-bottom:8px"><div style="font-weight:700">' + (right?'✓ Correct':'✗ Not quite') + '</div><div style="margin-top:4px">Answer: <strong>' + d.a + '</strong></div><div style="margin-top:6px;font-size:0.9rem;color:var(--muted)">' + d.exp + '</div></div><button class="btn btn-primary" onclick="__r1614Next()">Next →</button>';
    }
  };

  window.__r1614Next = function(){
    _srfDrillIdx++;
    _srfPicked = false;
    renderSrf();
  };

  window.__r1614Reset = function(){
    _srfDrillIdx = 0;
    _srfPicked = false;
    _srfCorrect = 0;
    _srfTotal = 0;
    renderSrf();
  };

  window.__r1614Speak = function(w){
    if (typeof speak === 'function') {
      try { speak(w, 'ar'); } catch(e){}
    }
  };

  window.__r1614Done = true;
})();

// ===== R1615 — extend __r1573Map with SRF_WORDS + ex sentence synth =====
(function(){
  if (window.__r1615Guard) return;
  window.__r1615Guard = true;
  if (typeof SRF_WORDS === 'undefined') return;
  if (!window.__r1573Map) window.__r1573Map = {};
  var map = window.__r1573Map;
  var added = 0;
  SRF_WORDS.forEach(function(w){
    if (!w || !w.w || !w.t) return;
    var key = String(w.w).trim();
    if (key && !map[key]) { map[key] = w.t; added++; }
  });
  var tokenMap = {};
  Object.keys(map).forEach(function(k){
    var v = map[k];
    if (!k || !v) return;
    var clean = k.replace(/^(el-|l-|3al-|3a-|w-|b-|la-)/i,'').replace(/[\.,!\?:;\-—]/g,'').trim();
    if (clean) tokenMap[clean.toLowerCase()] = v;
    tokenMap[k.toLowerCase()] = v;
  });
  function _r1615Synth(s){
    if (!s) return null;
    var raw = String(s).replace(/[\.,!\?:;]+/g,' ').replace(/\s+/g,' ').trim();
    if (!raw) return null;
    var toks = raw.split(/\s+/);
    var out = [];
    var hits = 0;
    var i = 0;
    while (i < toks.length) {
      var matched = false;
      for (var w = Math.min(4, toks.length - i); w >= 1 && !matched; w--) {
        var phrase = toks.slice(i, i+w).join(' ').toLowerCase();
        var clean = phrase.replace(/^(el-|l-|3al-|3a-|w-|b-|la-)/i,'').trim();
        var ar = tokenMap[phrase] || tokenMap[clean];
        if (ar) {
          out.push(ar);
          hits++;
          i += w;
          matched = true;
        }
      }
      if (!matched) { out.push(toks[i]); i++; }
    }
    if (hits < 2) return null;
    if (hits / toks.length < 0.5) return null;
    return out.join(' ');
  }
  var exAdded = 0;
  SRF_WORDS.forEach(function(w){
    if (!w || !w.ex) return;
    var ex = String(w.ex).trim();
    if (!ex || map[ex]) return;
    var ar = _r1615Synth(ex);
    if (ar) { map[ex] = ar; exAdded++; }
  });
  window.__r1615Added = added;
  window.__r1615ExAdded = exAdded;
  window.__r1615MapSize = Object.keys(map).length;
  window.__r1615Done = true;
})();

