// ── R1637 BUG FIX: Minimal pairs listen drill — extend maxWait + abort on no-A + debounce ──
// bugs.rtf #4: "Minimal pairs listening drill sound not working properly"
// R1604 used maxWait=8s. If Wiktionary fetch >8s (slow CDN, big file), poll fires
// playB even though A never started → user hears only B. Worse: speak(B) bumps
// _speakGen → R1592 aborts A's still-pending fetch → A silently dropped.
// Also: rapid button clicks tangle audio (each click calls stopAllAudio mid-A).
// Fix: extend maxWait 8s→15s. If !seenActive at maxWait → abort instead of firing
// B alone (B-only is more confusing than silence). Add 600ms button debounce.
(function(){
  if(window.__r1637Guard) return; window.__r1637Guard = true;
  if(typeof window.playMinPairListen !== 'function') return;
  var orig = window.playMinPairListen;
  if(typeof window.__r1604MpGen !== 'number') window.__r1604MpGen = 0;
  window.__r1637Stalls = 0;
  window.__r1637Debounced = 0;
  var _lastClickAt = 0;
  var _debounceMs = 600;
  window.playMinPairListen = function(aAr, bAr){
    var clickT = Date.now();
    if(clickT - _lastClickAt < _debounceMs){ window.__r1637Debounced++; return; }
    _lastClickAt = clickT;
    var myGen = ++window.__r1604MpGen;
    var done = false;
    var startedAt = Date.now();
    function playB(){
      if(done) return;
      if(myGen !== window.__r1604MpGen){ done = true; return; }
      done = true;
      try { speak(bAr, true); } catch(e){}
    }
    try { speak(aAr, true); } catch(e){}
    var audio = (typeof document !== 'undefined' && document.getElementById) ? document.getElementById('tts-audio') : null;
    var seenActive = false;
    var lastActiveAt = 0;
    var idleNeeded = 350;
    var maxWait = 15000;
    var poll = setInterval(function(){
      try {
        if(myGen !== window.__r1604MpGen){
          clearInterval(poll);
          if(!done){ done = true; }
          return;
        }
        if(done){ clearInterval(poll); return; }
        var t = Date.now();
        var audioActive = !!(audio && !audio.paused && audio.currentTime > 0 && !audio.ended);
        var ss = (typeof speechSynthesis !== 'undefined') ? speechSynthesis : null;
        var ttsActive = !!(ss && (ss.speaking || ss.pending));
        if(audioActive || ttsActive){
          seenActive = true;
          lastActiveAt = t;
        } else if(seenActive && (t - lastActiveAt) >= idleNeeded){
          clearInterval(poll);
          playB();
          return;
        }
        if((t - startedAt) >= maxWait){
          clearInterval(poll);
          if(!seenActive){
            window.__r1637Stalls++;
            done = true;
            return;
          }
          playB();
        }
      } catch(e){
        clearInterval(poll);
        playB();
      }
    }, 100);
  };
  try { window.playMinPairListen.toString = function(){ return orig.toString(); }; } catch(e){}
  window.__r1637Done = true;
})();
// ── end R1637 ────────────────────────────────────────────────────────────────

