// ── R1654 AUDIO: Extend __r1573Map with ZIA_WORDS (R1653 Ziad coach) ──────────
// Lowercases keys directly per R1652 root cause (R1576 lookup lowercases, but
// R1652 case-alias IIFE ran before this extension so won't auto-alias).
(function(){
  if (window.__r1654Guard) return;
  window.__r1654Guard = true;
  if (typeof ZIA_WORDS === 'undefined') return;
  if (!window.__r1573Map) window.__r1573Map = {};
  var map = window.__r1573Map;
  var added = 0;
  ZIA_WORDS.forEach(function(w){
    if (!w || !w.w || !w.t) return;
    var key = String(w.w).toLowerCase().trim();
    if (key && !map[key]) { map[key] = w.t; added++; }
  });
  var tokenMap = {};
  function _strip(s){
    var t = String(s).toLowerCase();
    t = t.replace(/^(el-|l-|3al-|3a-|w-|b-|la-)/, '');
    return t;
  }
  Object.keys(map).forEach(function(k){
    var toks = String(k).split(/\s+/);
    if (toks.length === 1) {
      var stripped = _strip(toks[0]);
      if (stripped && !tokenMap[stripped]) tokenMap[stripped] = map[k];
    }
  });
  function _r1654Synth(ex){
    if (!ex) return null;
    var toks = String(ex).split(/\s+/);
    if (toks.length < 2 || toks.length > 30) return null;
    var out = [];
    var hits = 0;
    var i = 0;
    while (i < toks.length) {
      var matched = false;
      for (var w = Math.min(4, toks.length - i); w >= 1; w--) {
        var phrase = toks.slice(i, i + w).join(' ');
        var stripped = _strip(phrase);
        if (tokenMap[stripped]) {
          out.push(tokenMap[stripped]);
          hits++;
          i += w;
          matched = true;
          break;
        }
      }
      if (!matched) { out.push(toks[i]); i++; }
    }
    if (hits < 2) return null;
    if (hits / toks.length < 0.5) return null;
    return out.join(' ');
  }
  var exAdded = 0;
  ZIA_WORDS.forEach(function(w){
    if (!w || !w.ex) return;
    var ex = String(w.ex).trim();
    if (!ex || map[ex]) return;
    var ar = _r1654Synth(ex);
    if (ar) { map[ex] = ar; exAdded++; }
  });
  window.__r1654Added = added;
  window.__r1654ExAdded = exAdded;
  window.__r1654MapSize = Object.keys(map).length;
  window.__r1654Done = true;
})();
// ── end R1654 ────────────────────────────────────────────────────────────────

// ── R1655 BUG FIX: Minimal pairs listen onclick HTML attribute breakage ──
// bugs.rtf #4: "Minimal pairs listening drill sound not working properly"
// Root cause: line 87981 uses raw JSON.stringify(p.a.ar) inside onclick="..."
// HTML attribute. JSON.stringify wraps in literal double quotes. Embedded as
// onclick="playMinPairListen("text","other")" → inner " terminates outer
// attribute → onclick handler truncates to `playMinPairListen(` → SyntaxError
// on click → no audio plays. R989/R1046/R1550/R1580/R1604/R1637 all wrapped
// playMinPairListen logic but never noticed call site was malformed HTML.
// All other onclick sites (R1605/R1608/R1611/R1629/cswCheck) use
// `.replace(/"/g,'&quot;')` after JSON.stringify — only this one site missed.
// Fix: re-wrap setMpxMode (3rd layer) — when m==='listen', re-render with
// attrArg() (line 16944) which returns JSON.stringify+&quot; — HTML-safe.
(function(){
  if(window.__r1655Guard) return; window.__r1655Guard = true;
  if(typeof setMpxMode !== 'function') return;
  var _attrArg = (typeof attrArg === 'function') ? attrArg : (typeof window.attrArg==='function' ? window.attrArg : null);
  if(!_attrArg) return;
  var _origSetMpx = setMpxMode;
  setMpxMode = function(m){
    _origSetMpx.apply(this, arguments);
    if(m !== 'listen') return;
    if(typeof MIN_PAIRS_X === 'undefined') return;
    var c = document.getElementById('mpx-content');
    if(!c) return;
    c.innerHTML = '<div style="background:var(--card);border-radius:12px;padding:18px">' +
      '<div style="margin-bottom:12px;color:var(--muted)">Press a pair to hear both words back-to-back. Compare carefully — the only difference is the contrast letter.</div>' +
      '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:8px">' +
      MIN_PAIRS_X.map(function(p){
        var aA = _attrArg(p.a.ar);
        var bA = _attrArg(p.b.ar);
        return '<button class="btn btn-outline" style="text-align:left;padding:10px" onclick="playMinPairListen(' + aA + ',' + bA + ')">' +
          '<div style="font-weight:700">' + (p.a.tr||'') + ' vs ' + (p.b.tr||'') + '</div>' +
          '<div style="color:var(--muted);font-size:0.8rem">' + (p.contrast||'') + '</div>' +
          '</button>';
      }).join('') +
      '</div></div>';
    window.__r1655Renders = (window.__r1655Renders||0) + 1;
  };
  try { setMpxMode.toString = function(){ return _origSetMpx.toString(); }; } catch(e){}
  try { Object.keys(_origSetMpx).forEach(function(k){ try{ setMpxMode[k]=_origSetMpx[k]; }catch(e){} }); } catch(e){}
  window.__r1655Done = true;
})();
// ── end R1655 ────────────────────────────────────────────────────────────────

