// ===== R1684 — AUDIO: extend __r1573Map with JEZ_WORDS w→t + ex sentence synth =====
// R1683 added JEZ_WORDS (Lebanese Jezzine, south Lebanon Maronite mountain town).
// Mirrors R1591/R1597/R1606/R1609/R1612/R1618/R1621/R1627/R1648/R1678/R1681.
(function(){
  if(window.__r1684Guard) return; window.__r1684Guard = true;
  if(typeof JEZ_WORDS === 'undefined' || !Array.isArray(JEZ_WORDS)) return;
  if(!window.__r1573Map) window.__r1573Map = {};
  var map = window.__r1573Map;
  var added = 0;
  JEZ_WORDS.forEach(function(w){
    if(!w || !w.w || !w.t) return;
    var key = String(w.w).trim();
    if(key && !map[key]){ map[key] = w.t; added++; }
  });
  var tokenMap = {};
  Object.keys(map).forEach(function(k){
    var v = map[k];
    if(!k || !v) return;
    var clean = k.replace(/^(el-|l-|3al-|3a-|w-|b-|la-)/i,'').replace(/[\.,!\?:;\-—]/g,'').trim();
    if(clean) tokenMap[clean.toLowerCase()] = v;
    tokenMap[k.toLowerCase()] = v;
  });
  function _r1684Synth(s){
    if(!s) return null;
    var raw = String(s).replace(/[\.,!\?:;]+/g,' ').replace(/\s+/g,' ').trim();
    if(!raw) return null;
    var toks = raw.split(/\s+/);
    var out = [];
    var hits = 0;
    var i = 0;
    while(i < toks.length){
      var matched = false;
      for(var w = Math.min(4, toks.length - i); w >= 1 && !matched; w--){
        var phrase = toks.slice(i, i+w).join(' ').toLowerCase();
        var clean = phrase.replace(/^(el-|l-|3al-|3a-|w-|b-|la-)/i,'').trim();
        var ar = tokenMap[phrase] || tokenMap[clean];
        if(ar){
          out.push(ar);
          hits++;
          i += w;
          matched = true;
        }
      }
      if(!matched){ out.push(toks[i]); i++; }
    }
    if(hits < 2) return null;
    if(hits / toks.length < 0.5) return null;
    return out.join(' ');
  }
  var exAdded = 0;
  JEZ_WORDS.forEach(function(w){
    if(!w || !w.ex) return;
    var ex = String(w.ex).trim();
    if(!ex || map[ex]) return;
    var ar = _r1684Synth(ex);
    if(ar){ map[ex] = ar; exAdded++; }
  });
  window.__r1684Added = added;
  window.__r1684ExAdded = exAdded;
  window.__r1684MapSize = Object.keys(map).length;
  window.__r1684Done = true;
})();

// ===== R1685 — BUG FIX: drill opts predictability (all a:1 in 8 coaches) =====
(function(){
  if(window.__r1685Guard) return; window.__r1685Guard = true;
  var targets = [];
  if(typeof WSF_DRILLS !== 'undefined') targets.push({name:'WSF',arr:WSF_DRILLS});
  if(typeof RHB_DRILLS !== 'undefined') targets.push({name:'RHB',arr:RHB_DRILLS});
  if(typeof SAH_DRILLS !== 'undefined') targets.push({name:'SAH',arr:SAH_DRILLS});
  if(typeof ZIA_DRILLS !== 'undefined') targets.push({name:'ZIA',arr:ZIA_DRILLS});
  if(typeof COU_DRILLS !== 'undefined') targets.push({name:'COU',arr:COU_DRILLS});
  if(typeof MRT_DRILLS !== 'undefined') targets.push({name:'MRT',arr:MRT_DRILLS});
  if(typeof FST_DRILLS !== 'undefined') targets.push({name:'FST',arr:FST_DRILLS});
  if(typeof RWC_DRILLS !== 'undefined') targets.push({name:'RWC',arr:RWC_DRILLS});
  var drillsTouched = 0;
  var aDistribution = {};
  targets.forEach(function(t){
    if(!Array.isArray(t.arr)) return;
    t.arr.forEach(function(d){
      if(!d || !Array.isArray(d.opts) || typeof d.a !== 'number') return;
      if(d.opts.length < 2) return;
      var correctOpt = d.opts[d.a];
      if(correctOpt === undefined) return;
      // Fisher-Yates in-place
      for(var i = d.opts.length - 1; i > 0; i--){
        var j = Math.floor(Math.random() * (i + 1));
        var tmp = d.opts[i]; d.opts[i] = d.opts[j]; d.opts[j] = tmp;
      }
      d.a = d.opts.indexOf(correctOpt);
      drillsTouched++;
      var key = String(d.a);
      aDistribution[key] = (aDistribution[key] || 0) + 1;
    });
  });
  window.__r1685DrillsTouched = drillsTouched;
  window.__r1685ADist = aDistribution;
  window.__r1685TargetCount = targets.length;
  window.__r1685Done = true;
})();

