  // Also propagate flags directly from old speak fn
  for(var fk in _orig){
    try { if(/^__r\d+/.test(fk)) _wrap[fk] = _orig[fk]; } catch(e){}
  }
  _wrap.__r1700Audio = true;
  // toString preservation so any source-string probe markers still pass
  _wrap.toString = function(){ return _orig.toString(); };
