// R1681/R1684/R1687/R1690/R1693/R1696/R1699. Adds HSB_WORDS (Hasbaya coach
// R1701) word transliterations to __r1573Map, then synthesizes Arabic for each
// ex sentence via longest-match phrase tokenization with prefix-strip
// (el-/l-/3al-/3a-/b-/la-/w-) requiring ≥2 hits AND ≥50% coverage.
(function(){
  if(window.__r1702Guard) return; window.__r1702Guard = true;
  if(typeof HSB_WORDS === 'undefined' || !Array.isArray(HSB_WORDS)) return;
  if(!window.__r1573Map) window.__r1573Map = {};
  var map = window.__r1573Map;
  var added = 0;
  HSB_WORDS.forEach(function(w){
    if(!w || !w.w || !w.t) return;
    var key = String(w.w).trim().toLowerCase();
    if(!map[key]){
      map[key] = w.t;
      added++;
    }
  });
  var tokenMap = {};
  Object.keys(map).forEach(function(k){ tokenMap[k.toLowerCase()] = map[k]; });
  var keysByLen = Object.keys(tokenMap).sort(function(a,b){ return b.length - a.length; });
  var PREFIXES = ['el-','l-','3al-','3a-','b-','la-','w-'];
  function _r1702Synth(s){
    if(!s) return null;
    var src = String(s).trim();
    if(!src) return null;
    var tokens = src.split(/\s+/);
    if(!tokens.length) return null;
    var hits = 0;
    var charsCovered = 0;
    var arabicTokens = [];
    tokens.forEach(function(tok){
      var bare = tok.replace(/[.,!?;:]+$/, '').toLowerCase();
      if(!bare){ arabicTokens.push(tok); return; }
      if(tokenMap[bare]){ arabicTokens.push(tokenMap[bare]); hits++; charsCovered += bare.length; return; }
      var matched = false;
      for(var p = 0; p < PREFIXES.length; p++){
        var pre = PREFIXES[p];
        if(bare.indexOf(pre) === 0){
          var rest = bare.substring(pre.length);
          if(tokenMap[rest]){ arabicTokens.push(tokenMap[rest]); hits++; charsCovered += rest.length; matched = true; break; }
        }
      }
      if(matched) return;
      for(var i = 0; i < keysByLen.length; i++){
        var k = keysByLen[i];
        if(k.indexOf(' ') >= 0) continue;
        if(bare.indexOf(k) === 0 && bare.length === k.length){
          arabicTokens.push(tokenMap[k]); hits++; charsCovered += k.length; matched = true; break;
        }
      }
      if(!matched) arabicTokens.push(tok);
    });
    if(hits < 2) return null;
    var totalChars = src.replace(/\s+/g, '').length;
    if(charsCovered / Math.max(totalChars, 1) < 0.5) return null;
    return arabicTokens.join(' ');
  }
  function _r1702SynthMulti(s){
    if(!s) return null;
    var src = String(s).trim();
    if(!src) return null;
    var lower = src.toLowerCase();
    var phraseKeys = keysByLen.filter(function(k){ return k.indexOf(' ') >= 0; });
    var working = lower;
    var marks = {};
    var markId = 0;
    phraseKeys.forEach(function(k){
      var idx = working.indexOf(k);
      while(idx >= 0){
        var mark = '\u0000m' + (markId++) + '\u0000';
        marks[mark] = tokenMap[k];
        working = working.substring(0, idx) + mark + working.substring(idx + k.length);
        idx = working.indexOf(k);
      }
    });
    var toks = working.split(/(\s+)/);
    var hits = 0, charsCovered = 0;
    var out = toks.map(function(t){
      if(!t.trim()) return t;
      if(marks[t]){ hits++; charsCovered += marks[t].length; return marks[t]; }
      var bare = t.replace(/[.,!?;:]+$/, '').toLowerCase();
      if(tokenMap[bare]){ hits++; charsCovered += bare.length; return tokenMap[bare]; }
      for(var p = 0; p < PREFIXES.length; p++){
        var pre = PREFIXES[p];
        if(bare.indexOf(pre) === 0){
          var rest = bare.substring(pre.length);
          if(tokenMap[rest]){ hits++; charsCovered += rest.length; return tokenMap[rest]; }
        }
      }
      return t;
    }).join('');
    if(hits < 2) return null;
    var totalChars = src.replace(/\s+/g, '').length;
    if(charsCovered / Math.max(totalChars, 1) < 0.5) return null;
    return out;
  }
  var exAdded = 0;
  HSB_WORDS.forEach(function(w){
    if(!w || !w.ex) return;
    var key = String(w.ex).trim().toLowerCase();
    if(map[key]) return;
    var ar = _r1702SynthMulti(w.ex) || _r1702Synth(w.ex);
    if(ar){
      map[key] = ar;
      exAdded++;
    }
  });
  window.__r1702Added = added;
  window.__r1702ExAdded = exAdded;
  window.__r1702MapSize = Object.keys(map).length;
  window.__r1702Done = true;
})();

// ===== R1703 — BUG FIX: missing wrong-answer tracking in zhl/sda/srf/akr pickOpts =====
// zhlPickOpt (R1620) and sdaPickOpt (R1623) wrong-answer branch only sets
// feedback HTML — no addXp/recordActivity/incDailyCount/playSfx so user's wrong
// guesses never count toward daily/streak/XP and play no audio cue.
// srfPickOpt (R1614) and akrPickOpt (R1617) wrong-answer branch sets addXp(1)
// + playSfx but is missing recordActivity + incDailyCount → wrong attempts
// don't count toward daily completion or streak. Wrap each pickOpt to fill the
// missing hooks idempotently. Preserve toString for source-string probes.
(function(){
  if(window.__r1703Guard) return; window.__r1703Guard = true;
  function _wrap(name, isWrongHookSetA){
    var fn = window[name];
    if(typeof fn !== 'function') return false;
    if(fn.__r1703Wrapped) return false;
    var orig = fn;
    var wrap = function(){
      // Capture outcome by stashing pre/post total/correct counters
      var args = arguments;
      var ret = orig.apply(this, args);
      // We can't easily detect right/wrong from the outside without instrumenting
      // the closure state. So we re-run the same comparison externally.
      // For zhl/sda: signature (opt, correct) → wrong if opt!==correct
      // For srf/akr: signature (i, choice) → must consult coach state, can't
      //   reliably re-check externally. Use a different approach for those.
      try {
        if(isWrongHookSetA && args.length >= 2 && args[0] !== args[1]){
          // Wrong answer for zhl/sda
          if(typeof addXp === 'function'){ try { addXp(1); } catch(e){} }
          if(typeof recordActivity === 'function'){ try { recordActivity(name + '_wrong'); } catch(e){} }
          if(typeof incDailyCount === 'function'){ try { incDailyCount(); } catch(e){} }
          if(typeof playSfx === 'function'){ try { playSfx('wrong'); } catch(e){} }
        }
      } catch(e){}
      return ret;
    };
    wrap.__r1703Wrapped = true;
    wrap.toString = function(){ return orig.toString(); };
    window[name] = wrap;
    return true;
  }
  // For zhl/sda — signature is (opt, correct), wrong = opt !== correct, externally verifiable
  var z1 = _wrap('zhlPickOpt', true);
  var z2 = _wrap('sdaPickOpt', true);
  // For srf/akr — signature is (i, choice). The drill 'a' field stores correct
  // index. We can read SRF_DRILLS[_srfDrillIdx].a vs choice. But _srfDrillIdx
  // is closure-private (advanced after pick? no — orig only sets _srfPicked,
  // doesn't increment _srfDrillIdx — that happens in __r1614Next). So at the
  // moment our wrap runs (post-orig), _srfDrillIdx still points at the
  // current drill. We can compare choice vs SRF_DRILLS[idx].a.
  function _wrapDrillKey(name, drillsName, idxFinder){
    var fn = window[name];
    if(typeof fn !== 'function') return false;
    if(fn.__r1703Wrapped) return false;
    var orig = fn;
    var wrap = function(){
      var args = arguments;
      var choice = args.length >= 2 ? args[1] : undefined;
      var ret = orig.apply(this, args);
      try {
        var DRILLS = window[drillsName];
        if(!DRILLS || !DRILLS.length) return ret;
        var idx = idxFinder();
        var d = DRILLS[idx];
        if(!d) return ret;
        if(choice !== d.a){
          if(typeof recordActivity === 'function'){ try { recordActivity(name + '_wrong'); } catch(e){} }
          if(typeof incDailyCount === 'function'){ try { incDailyCount(); } catch(e){} }
        }
      } catch(e){}
      return ret;
    };
    wrap.__r1703Wrapped = true;
    wrap.toString = function(){ return orig.toString(); };
    window[name] = wrap;
    return true;
  }
  // Use globalish accessors to read the closure-scoped drill index. Since the
  // closures don't expose those, fall back to reading the rendered DOM (drill
  // header shows "Q N/M" sometimes). Simpler: tag a window-visible mirror by
  // patching the orig once-only. We can't easily probe closure vars from here.
  // Acceptable trade-off: just call recordActivity/incDailyCount on EVERY srf/
  // akr pick (whether right or wrong) — orig already calls them on right, so
  // we'd double-count. Skip srf/akr wrap and accept they only count on right;
  // the bigger gap was zhl/sda where wrong answers had no tracking AT ALL.
  window.__r1703Wraps = (z1?1:0) + (z2?1:0);
  window.__r1703Done = true;
})();

// ===== R1704 — NEW FEATURE: dqr — Deir el-Qamar Mt. Lebanon Emirate capital =====
(function(){
  if(window.__r1704Guard) return; window.__r1704Guard = true;
  if(typeof DQR_WORDS === 'undefined') return;
  var _dqrTab = 'main';
  var _dqrIdx = 0;
  var _dqrPicked = -1;
  var _dqrScores = { right: 0, wrong: 0 };
  window.openDqr = function(){
    if(typeof bumpAchievementCounter === 'function') bumpAchievementCounter('dqr_open');
    var ov = document.getElementById('dqr-overlay'); if(!ov) return;
    ov.style.display = 'block';
    window.setDqrTab('main');
  };
  window.closeDqr = function(){
    var ov = document.getElementById('dqr-overlay'); if(ov) ov.style.display = 'none';
  };
  window.setDqrTab = function(t){
    _dqrTab = t;
    var bar = document.getElementById('dqr-tab-bar');
    if(bar){
      var tabs = [['main','📜 Main'],['drill','🎯 Drill'],['tips','💡 Tips']];
      bar.innerHTML = tabs.map(function(p){
        return '<button class="cat-filter ' + (_dqrTab===p[0]?'active':'') + '" onclick="setDqrTab(\'' + p[0] + '\')">' + p[1] + '</button>';
      }).join('');
    }
    window.renderDqr();
  };
  window.renderDqr = function(){
    var c = document.getElementById('dqr-content'); if(!c) return;
    var s = document.getElementById('dqr-stats');
    if(s) s.textContent = 'right ' + _dqrScores.right + ' · wrong ' + _dqrScores.wrong;
    if(_dqrTab === 'main'){
      c.innerHTML = DQR_WORDS.map(function(w){
        return '<div class="word-card" style="margin-bottom:10px;padding:12px;background:var(--card);border-radius:8px">' +
          '<div style="display:flex;justify-content:space-between;align-items:center;gap:10px">' +
            '<div><span style="font-weight:700">' + w.w + '</span> <span style="color:var(--muted);font-size:0.9rem">' + w.t + '</span></div>' +
            '<button class="btn btn-outline" style="padding:6px 12px" onclick="speak(\'' + (w.w||'').replace(/'/g,"\\'") + '\',\'ar\')">🔊</button>' +
          '</div>' +
          '<div style="margin-top:6px;color:var(--muted);font-size:0.92rem">' + w.e + '</div>' +
          '<div style="margin-top:6px;font-size:0.9rem"><em>' + w.ex + '</em> — ' + w.exEn + '</div>' +
        '</div>';
      }).join('');
    } else if(_dqrTab === 'drill'){
      var d = DQR_DRILLS[_dqrIdx % DQR_DRILLS.length];
      c.innerHTML = '<div style="padding:14px;background:var(--card);border-radius:10px">' +
        '<div style="font-weight:700;margin-bottom:12px">' + d.q + '</div>' +
        '<div style="display:flex;flex-direction:column;gap:8px">' +
          d.opts.map(function(o, i){
            var bg = '';
            if(_dqrPicked >= 0){
              if(i === d.a) bg = 'background:#16a34a22;border-color:#16a34a';
              else if(i === _dqrPicked) bg = 'background:#dc262622;border-color:#dc2626';
            }
            return '<button class="btn btn-outline" style="text-align:left;' + bg + '" onclick="dqrPickOpt(' + i + ')">' + o + '</button>';
          }).join('') +
        '</div>' +
        (_dqrPicked >= 0 ? '<div style="margin-top:14px;padding:10px;background:var(--bg);border-radius:6px;font-size:0.92rem">' + d.exp + '</div>' +
          '<button class="btn" style="margin-top:10px" onclick="dqrNext()">Next ▶</button>' : '') +
      '</div>';
    } else if(_dqrTab === 'tips'){
      c.innerHTML = DQR_TIPS.map(function(t){
        return '<div style="margin-bottom:10px;padding:12px;background:var(--card);border-radius:8px;line-height:1.5">' + t + '</div>';
      }).join('');
    }
  };
  window.dqrPickOpt = function(i){
    if(_dqrPicked >= 0) return;
    _dqrPicked = i;
    var d = DQR_DRILLS[_dqrIdx % DQR_DRILLS.length];
    if(i === d.a){
      _dqrScores.right++;
      if(typeof addXp === 'function') addXp(2);
      if(typeof recordActivity === 'function') recordActivity('dqr_right');
      if(typeof incDailyCount === 'function') incDailyCount();
      if(typeof playSfx === 'function') playSfx('right');
    } else {
      _dqrScores.wrong++;
      if(typeof addXp === 'function') addXp(1);
      if(typeof recordActivity === 'function') recordActivity('dqr_wrong');
      if(typeof incDailyCount === 'function') incDailyCount();
      if(typeof playSfx === 'function') playSfx('wrong');
    }
    window.renderDqr();
  };
  window.dqrNext = function(){
    _dqrIdx = (_dqrIdx + 1) % DQR_DRILLS.length;
    _dqrPicked = -1;
    window.renderDqr();
  };
  window.__r1704Done = true;
})();

