// ===== R1706 — BUG FIX: gbrPickOpt re-entry guard (prevents double-click double-XP) =====
(function(){
  if (window.__r1706Guard) return;
  window.__r1706Guard = true;
  if (typeof window.gbrPickOpt !== 'function') return;
  if (window.__r1706GbrWrapped) return;
  var _picked = null;
  var origPick = window.gbrPickOpt;
  var origNext = window.gbrNext;
  var origPrev = window.gbrPrev;
  var origOpen = window.openGbr;
  var wrappedPick = function(picked, idx){
    if (_picked !== null) return;
    _picked = picked;
    return origPick.apply(this, arguments);
  };
  wrappedPick.toString = function(){ return origPick.toString(); };
  window.gbrPickOpt = wrappedPick;
  if (typeof origNext === 'function') {
    var wrappedNext = function(){
      _picked = null;
      return origNext.apply(this, arguments);
    };
    wrappedNext.toString = function(){ return origNext.toString(); };
    window.gbrNext = wrappedNext;
  }
  if (typeof origPrev === 'function') {
    var wrappedPrev = function(){
      _picked = null;
      return origPrev.apply(this, arguments);
    };
    wrappedPrev.toString = function(){ return origPrev.toString(); };
    window.gbrPrev = wrappedPrev;
  }
  if (typeof origOpen === 'function') {
    var wrappedOpen = function(){
      _picked = null;
      return origOpen.apply(this, arguments);
    };
    wrappedOpen.toString = function(){ return origOpen.toString(); };
    window.openGbr = wrappedOpen;
  }
  window.__r1706GbrWrapped = true;
  window.__r1706Done = true;
})();

// ===== R1707 — NEW FEATURE: nkl coach (Nahr el-Kalb / Dog River stelae) =====
