        + '</div>'
        + '</div>'
        + '<div style="display:flex;gap:8px;justify-content:center">'
        + '<button class="btn btn-outline" onclick="bhmPrev()">◀ Prev</button>'
        + '<button class="btn btn-outline" onclick="bhmNext()">Next ▶</button>'
        + '</div>';
